/* ===== SOURCE: supabase-login.js ===== */
window.addEventListener('load', async function () {
  const MAIN_MULTIROLE_EMAIL = 'malgorzata.bartkiewicz@upbonus.pl';

  const MAIN_MULTIROLE_ACCESSES = [
    'employee',
    'hr',
    'operations',
    'partner',
    'finance',
    'bok',
    'campaigns',
    'superadmin'
  ];

  const TAB_SESSION_KEY = 'upbonus_tab_session_v20';
  const LEGACY_SESSION_KEY = 'upbonus_session_v17';
  const EMPLOYEE_CONTEXT_KEY = 'upbonus_employee_portal_context';

  // =========================================================
  // HELPERY
  // =========================================================

  function safeRender() {
    try {
      if (typeof render === 'function') render();
    } catch (err) {
      console.warn('Render warning:', err);
    }
  }

  function safePersist() {
    try {
      if (typeof persist === 'function') persist();
    } catch (err) {
      console.warn('Persist warning:', err);
    }
  }

  function navigationType() {
    try {
      const nav =
        performance.getEntriesByType &&
        performance.getEntriesByType('navigation')[0];

      return nav?.type || 'navigate';
    } catch (err) {
      return 'navigate';
    }
  }

  function clearEmployeeContext() {
    try {
      Object.keys(sessionStorage).forEach(key => {
        if (
          /employee/i.test(key) ||
          /portal.*prac/i.test(key) ||
          /prac.*context/i.test(key)
        ) {
          sessionStorage.removeItem(key);
        }
      });
    } catch (err) {
      console.warn('Employee context cleanup warning:', err);
    }
  }

  function clearLegacyPersistentSession() {
    try {
      localStorage.removeItem(LEGACY_SESSION_KEY);
    } catch (err) {
      console.warn('Legacy session cleanup warning:', err);
    }
  }

  function clearAllFrontendAuthSessions() {
    try {
      localStorage.removeItem(LEGACY_SESSION_KEY);
      sessionStorage.removeItem(TAB_SESSION_KEY);
      sessionStorage.removeItem(EMPLOYEE_CONTEXT_KEY);
    } catch (err) {
      console.warn('Frontend auth cleanup warning:', err);
    }

    clearEmployeeContext();
  }

  function forceLoggedOutState(renderNow = true) {
    if (
      typeof state !== 'undefined' &&
      state
    ) {
      state.loggedIn = false;
      state.role = null;
      state.section = null;
      state.mobileMenu = false;
      state.modal = null;
      state.drawer = null;

      if (
        state.user &&
        typeof state.user === 'object'
      ) {
        state.user.role = null;
      }
    }

    clearLegacyPersistentSession();

    if (renderNow) {
      safeRender();
    }
  }

  function buildDisplayName(profile, authUser) {
    const fullName = [
      profile?.first_name,
      profile?.last_name
    ]
      .filter(Boolean)
      .join(' ')
      .trim();

    return (
      fullName ||
      authUser?.email ||
      'Użytkownik'
    );
  }

  function mapBackendRoleToFrontend(role) {
    switch (role) {
      case 'operator':
        return 'bok';

      case 'admin':
      case 'company_admin':
      case 'hr_admin':
        return 'hr';

      case 'super_admin':
        return 'superadmin';

      case 'employee':
      case 'hr':
      case 'operations':
      case 'partner':
      case 'finance':
      case 'bok':
      case 'campaigns':
      case 'superadmin':
        return role;

      default:
        return 'employee';
    }
  }

  function getSavedTabContext() {
    try {
      const saved =
        JSON.parse(
          sessionStorage.getItem(
            TAB_SESSION_KEY
          ) || 'null'
        );

      return (
        saved &&
        saved.active
          ? saved
          : null
      );
    } catch (err) {
      return null;
    }
  }

  function canRestoreSavedContext(
    saved,
    authUser
  ) {
    if (
      !saved ||
      !authUser?.email
    ) {
      return false;
    }

    const savedEmail =
      String(
        saved.user?.email || ''
      )
        .trim()
        .toLowerCase();

    const authEmail =
      String(
        authUser.email || ''
      )
        .trim()
        .toLowerCase();

    return Boolean(
      savedEmail &&
      savedEmail === authEmail
    );
  }

  // =========================================================
  // SYNCHRONIZACJA PROFILU
  // =========================================================

  async function syncProfileToState(
    authUser,
    options = {}
  ) {
    try {
      if (
        !window.sb ||
        !authUser?.id
      ) {
        return null;
      }

      const {
        forceAccountChoice = false,
        restoredRole = null,
        restoredSection = null
      } = options;

      const {
        data: profile,
        error
      } =
        await window.sb
          .from('profiles')
          .select(`
            id,
            role,
            company_id,
            first_name,
            last_name
          `)
          .eq(
            'id',
            authUser.id
          )
          .single();

      if (error) {
        console.error(
          'Supabase profile error:',
          error
        );

        return null;
      }

      if (!profile) {
        console.warn(
          'Supabase profile: brak profilu'
        );

        return null;
      }

      if (
        typeof state === 'undefined' ||
        !state
      ) {
        return profile;
      }

      const email =
        String(
          authUser.email || ''
        )
          .trim()
          .toLowerCase();

      const backendRole =
        profile.role ||
        'employee';

      const frontendRole =
        mapBackendRoleToFrontend(
          backendRole
        );

      const displayName =
        buildDisplayName(
          profile,
          authUser
        );

      state.user =
        state.user &&
        typeof state.user === 'object'
          ? state.user
          : {};

      state.user.id =
        authUser.id;

      state.user.email =
        authUser.email || '';

      state.user.name =
        displayName;

      state.user.fullName =
        displayName;

      state.user.displayName =
        displayName;

      state.user.first_name =
        profile.first_name || '';

      state.user.last_name =
        profile.last_name || '';

      state.user.firstName =
        profile.first_name || '';

      state.user.lastName =
        profile.last_name || '';

      state.user.backendRole =
        backendRole;

      state.user.company_id =
        profile.company_id || null;

      state.email =
        authUser.email || '';

      state.userId =
        authUser.id;

      state.company_id =
        profile.company_id || null;

      state.companyId =
        profile.company_id || null;

      /* V233: company -> platform -> branding.
         Role is resolved separately below and does not select the brand. */
      if(profile.company_id && typeof window.ub233LoadPlatformBrandingForCompany==='function'){
        await window.ub233LoadPlatformBrandingForCompany(profile.company_id);
      }

      // Dopiero potwierdzona sesja Supabase otwiera aplikację.
      state.loggedIn = true;

      // =====================================================
      // GŁÓWNE KONTO — MULTI ROLE
      // =====================================================

      if (
        email ===
        MAIN_MULTIROLE_EMAIL
      ) {
        state.accesses =
          [
            ...MAIN_MULTIROLE_ACCESSES
          ];

        if (forceAccountChoice) {
          clearEmployeeContext();

          state.role = null;
          state.section = null;
          state.user.role = null;
        }

        else if (
          restoredRole &&
          MAIN_MULTIROLE_ACCESSES.includes(
            restoredRole
          )
        ) {
          state.role =
            restoredRole;

          state.section =
            restoredSection ||
            null;

          state.user.role =
            restoredRole;
        }

        else {
          state.role = null;
          state.section = null;
          state.user.role = null;
        }
      }

      // =====================================================
      // OPERATOR — AUTOMATYCZNIE BOK
      // =====================================================

      else if (
        backendRole === 'operator'
      ) {
        clearEmployeeContext();

        state.accesses = [
          'bok'
        ];

        state.role =
          'bok';

        state.section =
          'Pulpit BOK';

        state.user.role =
          'bok';
      }

      // =====================================================
      // POZOSTAŁE KONTA
      // =====================================================

      else {
        clearEmployeeContext();

        state.accesses = [
          frontendRole
        ];

        state.role =
          frontendRole;

        state.user.role =
          frontendRole;

        if (
          frontendRole ===
          'employee'
        ) {
          state.section =
            'Dla Ciebie';
        }

        else {
          state.section =
            ROLE_DEFS?.[
              frontendRole
            ]?.menu?.[0]?.[0] ||
            'Start';
        }
      }

      state.mobileMenu = false;
      state.modal = null;
      state.drawer = null;

      safePersist();
      safeRender();

      return {
        profile,
        backendRole,
        frontendRole,
        accesses:
          state.accesses
      };

    } catch (err) {
      console.error(
        'Supabase profile sync exception:',
        err
      );

      return null;
    }
  }

  // =========================================================
  // MANUALNY SYNC
  // =========================================================

  window.syncSupabaseProfileToState =
    async function () {
      try {
        if (!window.sb) {
          return null;
        }

        const {
          data: {
            user
          },
          error
        } =
          await window.sb.auth
            .getUser();

        if (
          error ||
          !user
        ) {
          return null;
        }

        return await syncProfileToState(
          user,
          {
            forceAccountChoice:
              false
          }
        );

      } catch (err) {
        console.error(
          'Manual profile sync error:',
          err
        );

        return null;
      }
    };

  // =========================================================
  // LOGIN — TYLKO SUPABASE
  // =========================================================

  window.login =
    async function (e) {
      e?.preventDefault();

      try {
        const emailEl =
          document.getElementById(
            'loginEmail'
          );

        const passwordEl =
          document.querySelector(
            'input[type="password"]'
          );

        const email =
          String(
            emailEl?.value || ''
          )
            .trim()
            .toLowerCase();

        const password =
          passwordEl?.value ||
          '';

        if (
          !email ||
          !password
        ) {
          toast?.(
            'Logowanie',
            'Podaj e-mail i hasło'
          );

          return false;
        }

        if (!window.sb) {
          toast?.(
            'Logowanie',
            'Brak połączenia z Supabase'
          );

          return false;
        }

        forceLoggedOutState(
          false
        );

        const {
          data,
          error
        } =
          await window.sb.auth
            .signInWithPassword({
              email,
              password
            });

        if (
          error ||
          !data?.user
        ) {
          console.error(
            'Supabase login error:',
            error
          );

          forceLoggedOutState(
            true
          );

          toast?.(
            'Logowanie',
            'Nieprawidłowy e-mail lub hasło'
          );

          return false;
        }

        await syncProfileToState(
          data.user,
          {
            forceAccountChoice:
              email ===
              MAIN_MULTIROLE_EMAIL
          }
        );

        return false;

      } catch (err) {
        console.error(
          'Login integration error:',
          err
        );

        forceLoggedOutState(
          true
        );

        toast?.(
          'Logowanie',
          'Błąd logowania'
        );

        return false;
      }
    };

  // =========================================================
  // LOGOUT — SUPABASE + FRONTEND
  // =========================================================

  window.logout =
    async function () {
      try {
        if (window.sb) {
          await window.sb.auth
            .signOut();
        }
      } catch (err) {
        console.warn(
          'Supabase logout warning:',
          err
        );
      }

      clearAllFrontendAuthSessions();

      forceLoggedOutState(
        false
      );

      try {
        if (location.hash) {
          history.replaceState(
            null,
            '',
            location.pathname +
              location.search
          );
        }
      } catch (err) {}

      safeRender();

      return false;
    };

  // =========================================================
  // RESET HASŁA
  // =========================================================

  window.requestSupabasePasswordReset =
    async function (
      emailValue
    ) {
      try {
        if (!window.sb) {
          toast?.(
            'Reset hasła',
            'Brak połączenia z Supabase'
          );

          return false;
        }

        const email =
          String(
            emailValue ||
            document.getElementById(
              'loginEmail'
            )?.value ||
            ''
          )
            .trim()
            .toLowerCase();

        if (!email) {
          toast?.(
            'Reset hasła',
            'Wpisz adres e-mail'
          );

          return false;
        }

        const {
          error
        } =
          await window.sb.auth
            .resetPasswordForEmail(
              email,
              {
                redirectTo:
                  window.location
                    .origin +
                  window.location
                    .pathname
              }
            );

        if (error) {
          console.error(
            'Password reset error:',
            error
          );

          toast?.(
            'Reset hasła',
            'Nie udało się wysłać wiadomości'
          );

          return false;
        }

        toast?.(
          'Reset hasła',
          'Jeśli konto istnieje, wysłaliśmy wiadomość z linkiem'
        );

        return true;

      } catch (err) {
        console.error(
          'Password reset exception:',
          err
        );

        return false;
      }
    };

  // =========================================================
  // AUTH GATE
  //
  // ZASADA:
  // - świeże wejście / nowa karta = ZAWSZE ekran logowania
  // - F5 = można zachować prawdziwą sesję Supabase
  // =========================================================

  const navType =
    navigationType();

  const savedTab =
    getSavedTabContext();

  forceLoggedOutState(
    true
  );

  // ---------------------------------------------------------
  // ŚWIEŻE WEJŚCIE:
  // wylogowujemy nawet istniejącą sesję Supabase.
  // ---------------------------------------------------------

  if (
    navType !== 'reload'
  ) {
    try {
      if (window.sb) {
        await window.sb.auth
          .signOut();
      }
    } catch (err) {
      console.warn(
        'Fresh entry signOut warning:',
        err
      );
    }

    clearAllFrontendAuthSessions();

    forceLoggedOutState(
      true
    );

    console.log(
      'Supabase auth gate: świeże wejście — wymagane logowanie'
    );

    return;
  }

  // ---------------------------------------------------------
  // F5:
  // można odtworzyć tylko prawdziwą sesję Supabase.
  // ---------------------------------------------------------

  try {
    if (!window.sb) {
      console.warn(
        'Supabase auth gate: brak klienta Supabase'
      );

      return;
    }

    const {
      data: {
        session
      },
      error:
        sessionError
    } =
      await window.sb.auth
        .getSession();

    if (
      sessionError ||
      !session?.user
    ) {
      clearAllFrontendAuthSessions();

      forceLoggedOutState(
        true
      );

      console.log(
        'Supabase auth gate: brak sesji — pokazuję logowanie'
      );

      return;
    }

    const {
      data: {
        user
      },
      error:
        userError
    } =
      await window.sb.auth
        .getUser();

    if (
      userError ||
      !user
    ) {
      try {
        await window.sb.auth
          .signOut();
      } catch (err) {}

      clearAllFrontendAuthSessions();

      forceLoggedOutState(
        true
      );

      console.log(
        'Supabase auth gate: sesja nieważna — pokazuję logowanie'
      );

      return;
    }

    let restoredRole =
      null;

    let restoredSection =
      null;

    if (
      canRestoreSavedContext(
        savedTab,
        user
      )
    ) {
      restoredRole =
        savedTab.role ||
        null;

      restoredSection =
        savedTab.section ||
        null;
    }

    await syncProfileToState(
      user,
      {
        forceAccountChoice:
          false,
        restoredRole,
        restoredSection
      }
    );

    console.log(
      'Supabase auth gate: F5 — prawidłowa sesja odtworzona'
    );

  } catch (err) {
    console.warn(
      'Supabase auth gate error:',
      err
    );

    clearAllFrontendAuthSessions();

    forceLoggedOutState(
      true
    );
  }

  console.log(
    'Supabase login integration ready — fresh entry requires login'
  );
});


