(function () {
  'use strict';

  if (window.__ubFeaturePackLoader) {
    return;
  }

  window.__ubFeaturePackLoader = true;

  const script =
    document.createElement('script');

  script.src =
    '/upbonus-feature-pack.js?v=4.0.0';

  script.async = false;

  script.onload =
    function () {
      console.log(
        'Up Bonus Feature Pack loaded successfully'
      );
    };

  script.onerror =
    function (error) {
      console.error(
        'Up Bonus Feature Pack loading error:',
        error
      );
    };

  document.head.appendChild(
    script
  );
})();


// =========================================================
// SUPABASE CHECKOUT
// =========================================================

window.addEventListener('load', function () {
  'use strict';

  // =========================================================
  // UP BONUS — SUPABASE CHECKOUT FIX V5
  // =========================================================

  function safeNumber(value, fallback = 0) {
    const number = Number(value);

    return Number.isFinite(number)
      ? number
      : fallback;
  }


  function formatMoney(value) {
    return safeNumber(value).toLocaleString(
      'pl-PL',
      {
        minimumFractionDigits: 2,
        maximumFractionDigits: 2
      }
    ) + ' zł';
  }


  function getCurrentCart() {
    return Array.isArray(
      state?.v14?.cart
    )
      ? state.v14.cart
      : [];
  }


  function getItemAmount(item) {
    return safeNumber(
      item?.nominal ??
      item?.price ??
      item?.value ??
      0
    );
  }


  function getItemQuantity(item) {
    return Math.max(
      1,
      safeNumber(
        item?.quantity,
        1
      )
    );
  }


  function getCurrentCartTotal() {
    return getCurrentCart().reduce(
      function (sum, item) {
        return (
          sum +
          getItemAmount(item) *
          getItemQuantity(item)
        );
      },
      0
    );
  }


  function sumAllocations(allocations) {
    return (
      Array.isArray(allocations)
        ? allocations
        : []
    ).reduce(
      function (sum, allocation) {
        return (
          sum +
          Math.max(
            0,
            safeNumber(
              allocation?.amount
            )
          )
        );
      },
      0
    );
  }


  function buildWalletUsage(allocations) {
    const usage = {};

    (
      Array.isArray(allocations)
        ? allocations
        : []
    ).forEach(
      function (allocation) {
        const walletId =
          allocation?.walletId;

        const amount =
          Math.max(
            0,
            safeNumber(
              allocation?.amount
            )
          );

        if (
          !walletId ||
          amount <= 0
        ) {
          return;
        }

        usage[walletId] =
          safeNumber(
            usage[walletId]
          ) +
          amount;
      }
    );

    return usage;
  }


  // =========================================================
  // KOMUNIKATY SALD
  // =========================================================

  function parsePolishMoney(text) {
    if (!text) {
      return null;
    }

    const match =
      String(text).match(
        /([\d\s]+(?:[,.]\d{1,2})?)\s*zł/i
      );

    if (!match) {
      return null;
    }

    const normalized =
      match[1]
        .replace(/\s/g, '')
        .replace(',', '.');

    const value =
      Number(normalized);

    return Number.isFinite(value)
      ? value
      : null;
  }


  function patchPaymentMethodMessages() {
    try {
      const total =
        getCurrentCartTotal();

      if (
        !Number.isFinite(total) ||
        total <= 0
      ) {
        return;
      }

      const nodes =
        Array.from(
          document.querySelectorAll(
            'div, span, p, small'
          )
        ).filter(
          function (element) {
            return (
              element.children.length === 0 &&
              String(
                element.textContent || ''
              )
                .trim()
                .startsWith(
                  'Dostępne saldo:'
                )
            );
          }
        );


      nodes.forEach(
        function (element) {
          const oldText =
            String(
              element.textContent || ''
            ).trim();

          const balance =
            parsePolishMoney(
              oldText
            );

          if (
            balance === null
          ) {
            return;
          }

          const parentText =
            String(
              element.parentElement
                ?.textContent ||
              ''
            );

          const forbidden =
            /nie jest dozwolone|nie jest dostępne|niedozwolone/i
              .test(
                parentText
              );

          let newText = '';

          if (forbidden) {
            newText =
              'Dostępne saldo: ' +
              formatMoney(balance) +
              '. To źródło nie jest dostępne dla tego produktu.';

          } else if (
            balance >= total
          ) {
            newText =
              'Dostępne saldo: ' +
              formatMoney(balance) +
              '. Wystarcza na ten zakup.';

          } else {
            newText =
              'Dostępne saldo: ' +
              formatMoney(balance) +
              '. Za mało na ten zakup.';
          }

          if (
            element.textContent !==
            newText
          ) {
            element.textContent =
              newText;
          }
        }
      );

    } catch (error) {
      console.warn(
        'Checkout payment message warning:',
        error
      );
    }
  }


  let paymentMessageScheduled =
    false;


  const paymentObserver =
    new MutationObserver(
      function () {
        if (
          paymentMessageScheduled
        ) {
          return;
        }

        paymentMessageScheduled =
          true;

        requestAnimationFrame(
          function () {
            paymentMessageScheduled =
              false;

            patchPaymentMethodMessages();
          }
        );
      }
    );


  paymentObserver.observe(
    document.body,
    {
      childList: true,
      subtree: true
    }
  );


  // =========================================================
  // START CHECKOUT
  // =========================================================

  setTimeout(
    function () {

      const originalV105Confirm =
        window.v105Confirm;


      if (
        typeof originalV105Confirm !==
        'function'
      ) {
        console.error(
          'Supabase checkout V5: brak v105Confirm()'
        );

        return;
      }


      function synchronizeCheckoutPlan(
        item,
        amount
      ) {
        state.v15 =
          state.v15 || {};

        const oldPlan =
          state.v15.checkout ||
          {};

        const oldItems =
          Array.isArray(
            oldPlan.items
          )
            ? oldPlan.items
            : [];

        const oldItem =
          oldItems.length === 1
            ? oldItems[0]
            : null;


        let allocations =
          Array.isArray(
            oldItem?.allocations
          )
            ? oldItem.allocations
                .map(
                  function (allocation) {
                    return {
                      ...allocation,

                      amount:
                        Math.max(
                          0,
                          safeNumber(
                            allocation?.amount
                          )
                        )
                    };
                  }
                )
                .filter(
                  function (allocation) {
                    return (
                      allocation.amount >
                      0
                    );
                  }
                )
            : [];


        let allocationTotal =
          sumAllocations(
            allocations
          );


        let gateway =
          Math.max(
            0,
            safeNumber(
              oldItem?.gateway ??
              oldPlan.gateway ??
              0
            )
          );


        const oldPaymentTotal =
          allocationTotal +
          gateway;


        const oldPlanIsValid =
          oldItems.length === 1 &&
          Math.abs(
            oldPaymentTotal -
            amount
          ) < 0.01;


        if (
          !oldPlanIsValid
        ) {
          try {
            if (
              typeof window
                .paymentPlan103 ===
              'function'
            ) {
              const recalculated =
                window.paymentPlan103([
                  {
                    ...item,
                    quantity: 1,
                    nominal: amount
                  }
                ]);


              if (
                recalculated &&
                Array.isArray(
                  recalculated.items
                ) &&
                recalculated.items.length ===
                  1
              ) {
                state.v15.checkout =
                  {
                    ...recalculated,
                    total: amount
                  };

                return (
                  state.v15.checkout
                );
              }
            }

          } catch (error) {
            console.warn(
              'Checkout V5 paymentPlan103 warning:',
              error
            );
          }


          allocations = [];
          allocationTotal = 0;
          gateway = amount;
        }


        if (
          allocationTotal >
          amount
        ) {
          let remaining =
            amount;

          allocations =
            allocations
              .map(
                function (allocation) {
                  const use =
                    Math.min(
                      remaining,
                      Math.max(
                        0,
                        safeNumber(
                          allocation.amount
                        )
                      )
                    );

                  remaining -= use;

                  return {
                    ...allocation,
                    amount: use
                  };
                }
              )
              .filter(
                function (allocation) {
                  return (
                    allocation.amount >
                    0
                  );
                }
              );

          allocationTotal =
            sumAllocations(
              allocations
            );

          gateway =
            Math.max(
              0,
              amount -
              allocationTotal
            );
        }


        if (
          allocationTotal +
          gateway <
          amount
        ) {
          gateway =
            amount -
            allocationTotal;
        }


        if (
          allocationTotal +
          gateway >
          amount
        ) {
          gateway =
            Math.max(
              0,
              amount -
              allocationTotal
            );
        }


        const walletUsage =
          buildWalletUsage(
            allocations
          );


        state.v15.checkout =
          {
            ...oldPlan,

            items: [
              {
                ...item,
                quantity: 1,
                nominal: amount,
                allocations,
                gateway
              }
            ],

            total: amount,
            walletTotal: allocationTotal,
            gateway,
            walletUsage
          };


        return (
          state.v15.checkout
        );
      }


      function getPaymentSource(
        plan
      ) {
        const item =
          plan?.items?.[0];

        const allocations =
          Array.isArray(
            item?.allocations
          )
            ? item.allocations.filter(
                function (allocation) {
                  return (
                    safeNumber(
                      allocation?.amount
                    ) > 0
                  );
                }
              )
            : [];


        const gateway =
          safeNumber(
            item?.gateway ??
            plan?.gateway ??
            0
          );


        if (
          allocations.length === 0 &&
          gateway > 0
        ) {
          return {
            source:
              'Środki własne',
            mixed:
              false
          };
        }


        if (
          allocations.length === 1 &&
          gateway <= 0
        ) {
          return {
            source:
              String(
                allocations[0]
                  ?.name ||
                'E-konto'
              ).trim(),
            mixed:
              false
          };
        }


        if (
          allocations.length > 1 ||
          (
            allocations.length > 0 &&
            gateway > 0
          )
        ) {
          return {
            source: null,
            mixed: true
          };
        }


        return {
          source:
            'E-konto',
          mixed:
            false
        };
      }


      async function findProduct(
        item
      ) {
        const itemName =
          String(
            item?.name ||
            ''
          ).trim();


        const possibleId =
          item?.productId ||
          item?.product_id ||
          null;


        if (
          possibleId &&
          typeof possibleId ===
            'string' &&
          /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i
            .test(
              possibleId
            )
        ) {
          const {
            data,
            error
          } =
            await window.sb
              .from(
                'products'
              )
              .select(
                'id,name,price'
              )
              .eq(
                'id',
                possibleId
              )
              .limit(1);


          if (
            !error &&
            data?.[0]
          ) {
            return data[0];
          }
        }


        const amount =
          getItemAmount(
            item
          );


        let query =
          window.sb
            .from(
              'products'
            )
            .select(
              'id,name,price'
            )
            .eq(
              'name',
              itemName
            )
            .eq(
              'is_active',
              true
            );


        if (
          amount > 0
        ) {
          query =
            query.eq(
              'price',
              amount
            );
        }


        const {
          data:
            exactProducts,
          error:
            exactError
        } =
          await query.limit(1);


        if (
          !exactError &&
          exactProducts?.[0]
        ) {
          return (
            exactProducts[0]
          );
        }


        const {
          data:
            products,
          error:
            productError
        } =
          await window.sb
            .from(
              'products'
            )
            .select(
              'id,name,price'
            )
            .eq(
              'name',
              itemName
            )
            .eq(
              'is_active',
              true
            )
            .limit(1);


        if (
          productError
        ) {
          throw productError;
        }


        return (
          products?.[0] ||
          null
        );
      }


      window.v105Confirm =
        async function () {

          const checkbox =
            document.getElementById(
              'v105Confirm'
            );


          if (
            !checkbox?.checked
          ) {
            originalV105Confirm();
            return;
          }


          if (
            window
              .__supabaseCheckoutBusy
          ) {
            return;
          }


          window
            .__supabaseCheckoutBusy =
            true;


          try {

            if (
              !window.sb
            ) {
              toast?.(
                'Zakup',
                'Brak połączenia z Supabase.'
              );

              return;
            }


            const {
              data:
                {
                  user
                },
              error:
                userError
            } =
              await window.sb
                .auth
                .getUser();


            if (
              userError ||
              !user
            ) {
              toast?.(
                'Zakup',
                'Sesja wygasła. Zaloguj się ponownie.'
              );

              return;
            }


            const cart =
              getCurrentCart();


            if (
              !cart.length
            ) {
              toast?.(
                'Zakup',
                'Koszyk jest pusty.'
              );

              return;
            }


            if (
              cart.length !==
              1
            ) {
              toast?.(
                'Zakup',
                'Na tym etapie kup dokładnie jeden benefit.'
              );

              return;
            }


            const item =
              cart[0];


            const quantity =
              getItemQuantity(
                item
              );


            if (
              quantity !==
              1
            ) {
              toast?.(
                'Zakup',
                'Na tym etapie kup dokładnie 1 sztukę benefitu.'
              );

              return;
            }


            const amount =
              getItemAmount(
                item
              );


            const itemName =
              String(
                item?.name ||
                ''
              ).trim();


            if (
              !itemName ||
              amount <= 0
            ) {
              toast?.(
                'Zakup',
                'Nieprawidłowe dane benefitu.'
              );

              return;
            }


            const safePlan =
              synchronizeCheckoutPlan(
                item,
                amount
              );


            const payment =
              getPaymentSource(
                safePlan
              );


            if (
              payment.mixed
            ) {
              toast?.(
                'Płatność łączona',
                'Na tym etapie integracji Supabase wybierz jedno źródło płatności.'
              );

              return;
            }


            function normalizeSupabasePaymentSource(source) {
              const raw = String(source || '').trim();
              const key = raw
                .toLocaleLowerCase('pl-PL')
                .replace(/\s+/g, ' ');

              const aliases = {
                'kultura': 'Karta Kultura',
                'karta kultura': 'Karta Kultura',
                'culture': 'Karta Kultura',
                'karta culture': 'Karta Kultura',

                'lunch': 'Karta Lunch',
                'karta lunch': 'Karta Lunch',
                'lunchowa': 'Karta Lunch',
                'karta lunchowa': 'Karta Lunch',

                'premia': 'Karta premiowa',
                'premiowa': 'Karta premiowa',
                'karta premia': 'Karta premiowa',
                'karta premiowa': 'Karta premiowa',
                'nagrody': 'Karta premiowa'
              };

              return aliases[key] || raw;
            }


            const paymentSource =
              normalizeSupabasePaymentSource(
                payment.source ||
                'E-konto'
              );


            console.log(
              'Checkout Supabase payment source:',
              {
                raw: payment.source,
                normalized: paymentSource
              }
            );


            const product =
              await findProduct(
                item
              );


            if (
              !product?.id
            ) {
              toast?.(
                'Zakup',
                `Benefit „${itemName}” nie jest jeszcze powiązany z tabelą products.`
              );

              return;
            }


            const companyId =
              state?.company_id ||
              state?.companyId ||
              state?.user?.company_id ||
              null;


            if (!companyId) {
              toast?.(
                'Zakup',
                'Brak company_id dla zalogowanego użytkownika.'
              );

              return;
            }


            const {
              data,
              error
            } =
              await window.sb.rpc(
                'purchase_product',
                {
                  p_company_id:
                    companyId,

                  p_product_id:
                    product.id,

                  p_product_name:
                    product.name ||
                    itemName,

                  p_quantity:
                    1,

                  p_unit_price:
                    amount,

                  p_source_name:
                    paymentSource,

                  p_regular_price:
                    safeNumber(
                      item?.regularPrice ??
                      item?.regular_price ??
                      product?.price ??
                      amount,
                      amount
                    )
                }
              );


            if (
              error
            ) {
              console.error(
                'purchase_product V6 error:',
                error
              );

              toast?.(
                'Zakup',
                error.message ||
                'Nie udało się utworzyć zamówienia.'
              );

              return;
            }


            console.log(
              'Checkout V6 purchase_product Supabase OK:',
              data
            );


            originalV105Confirm();


            try {
              if (
                typeof window
                  .loadSupabaseOrderHistory ===
                'function'
              ) {
                setTimeout(
                  function () {
                    window
                      .loadSupabaseOrderHistory()
                      .catch(
                        function (error) {
                          console.warn(
                            'Checkout history refresh warning:',
                            error
                          );
                        }
                      );
                  },
                  350
                );
              }

            } catch (error) {
              console.warn(
                'Checkout refresh warning:',
                error
              );
            }


          } catch (error) {

            console.error(
              'Checkout V5 error:',
              error
            );

            toast?.(
              'Zakup',
              'Wystąpił błąd podczas zakupu.'
            );


          } finally {

            window
              .__supabaseCheckoutBusy =
              false;
          }
        };


      // Keep a stable reference to the Supabase-backed checkout handler.
      // Later UI layers must not silently replace it.
      window.__supabaseCheckoutHandler = window.v105Confirm;
      try { window.__supabaseCheckoutHandler.__supabaseBacked = true; } catch (e) {}

      console.log(
        'Supabase checkout V6 purchase_product ready'
      );


      patchPaymentMethodMessages();

    },
    1200
  );


  setTimeout(
    patchPaymentMethodMessages,
    300
  );

});


;
/* ===== SOURCE: supabase-history.js ===== */
window.addEventListener('load', function () {
  setTimeout(function () {
    'use strict';

    // =========================================================
    // UP BONUS — SUPABASE HISTORY + REFUND SYNC
    //
    // FIX FINAL:
    // - poprawny nominał produktu
    // - realne saldo z Supabase
    // - zakupy jako wartości ujemne
    // - refundy jako wartości dodatnie
    // - transaction_type zamiast type
    // - mapowanie UUID -> UB-...
    // - synchronizacja reklamacji po istniejącym refundzie
    // - NIE wykonuje nowego refundu
    // =========================================================

    if (!window.sb) {
      console.error(
        'Supabase history sync: brak klienta Supabase'
      );
      return;
    }

    // =========================================================
    // BASIC HELPERS
    // =========================================================

    function numberValue(value) {
      const n = Number(value || 0);

      return Number.isFinite(n)
        ? n
        : 0;
    }

    function formatDate(value) {
      if (!value) {
        return '—';
      }

      try {
        return new Date(value)
          .toLocaleDateString('pl-PL');
      } catch (e) {
        return String(value);
      }
    }

    function normalizeProductName(
      productName,
      actualAmount
    ) {
      let name =
        String(
          productName || ''
        ).trim();

      const amount =
        numberValue(
          actualAmount
        );

      if (!name) {
        return amount > 0
          ? `Benefit ${amount.toLocaleString('pl-PL')} zł`
          : 'Benefit';
      }

      name = name
        .replace(
          /\s*[-–—]?\s*\d+(?:[.,]\d{1,2})?\s*(?:zł|pln)\s*$/i,
          ''
        )
        .trim();

      if (amount > 0) {
        const formatted =
          amount.toLocaleString(
            'pl-PL',
            {
              minimumFractionDigits:
                Number.isInteger(amount)
                  ? 0
                  : 2,

              maximumFractionDigits:
                2
            }
          );

        return `${name} ${formatted} zł`;
      }

      return name;
    }

    // =========================================================
    // STATUSY
    // =========================================================

    function mapStatus(status) {
      const s =
        String(
          status || ''
        ).toLowerCase();

      if (
        s === 'completed' ||
        s === 'fulfilled' ||
        s === 'delivered'
      ) {
        return 'Dostarczone';
      }

      if (
        s === 'cancelled' ||
        s === 'canceled' ||
        s === 'refunded'
      ) {
        return 'cancelled';
      }

      if (
        s === 'processing' ||
        s === 'confirmed'
      ) {
        return 'W realizacji';
      }

      if (
        s === 'pending' ||
        s === 'draft'
      ) {
        return 'Przyjęte do realizacji';
      }

      return status || '—';
    }

    function voucherStatus(status) {
      const s =
        String(
          status || ''
        ).toLowerCase();

      if (
        s === 'cancelled' ||
        s === 'canceled' ||
        s === 'revoked' ||
        s === 'invalid'
      ) {
        return 'Unieważniony';
      }

      return status || 'Gotowy';
    }

    // =========================================================
    // USER
    // =========================================================

    async function getCurrentUser() {
      const {
        data: { user },
        error
      } =
        await window.sb.auth.getUser();

      if (
        error ||
        !user
      ) {
        return null;
      }

      return user;
    }

    // =========================================================
    // ORDERS
    // =========================================================

    async function loadOrders(userId) {
      const {
        data,
        error
      } =
        await window.sb
          .from('orders')
          .select(`
            id,
            order_number,
            user_id,
            status,
            total_amount,
            created_at,
            order_items (
              id,
              order_id,
              product_name,
              quantity,
              unit_price,
              total_price,
              fulfillment_status
            )
          `)
          .eq(
            'user_id',
            userId
          )
          .order(
            'created_at',
            {
              ascending: false
            }
          );

      if (error) {
        console.error(
          'Supabase history orders error:',
          error
        );

        throw error;
      }

      return data || [];
    }

    // =========================================================
    // VOUCHERS
    // =========================================================

    async function loadVouchers(userId) {
      const {
        data,
        error
      } =
        await window.sb
          .from('vouchers')
          .select(`
            id,
            order_item_id,
            provider_name,
            code_ciphertext,
            display_hint,
            status,
            issued_at,
            valid_from,
            valid_until,
            order_items (
              id,
              order_id,
              product_name
            )
          `)
          .eq(
            'user_id',
            userId
          )
          .order(
            'issued_at',
            {
              ascending: false
            }
          );

      if (error) {
        console.warn(
          'Supabase history vouchers warning:',
          error
        );

        return [];
      }

      return data || [];
    }

    // =========================================================
    // WALLET
    // =========================================================

    async function loadWallet(userId) {
      const {
        data,
        error
      } =
        await window.sb
          .from('wallets')
          .select(`
            id,
            available_amount,
            updated_at
          `)
          .eq(
            'user_id',
            userId
          )
          .limit(1);

      if (error) {
        console.warn(
          'Supabase history wallet warning:',
          error
        );

        return null;
      }

      return data?.[0] || null;
    }

    // =========================================================
    // WALLET TRANSACTIONS
    // =========================================================

    async function loadTransactions(userId) {
      const wallet =
        await loadWallet(
          userId
        );

      if (!wallet?.id) {
        return {
          wallet,
          transactions: []
        };
      }

      const {
        data,
        error
      } =
        await window.sb
          .from(
            'wallet_transactions'
          )
          .select(`
            id,
            wallet_id,
            user_id,
            order_id,
            transaction_type,
            amount,
            status,
            reference_key,
            description,
            balance_before,
            balance_after,
            created_at
          `)
          .eq(
            'wallet_id',
            wallet.id
          )
          .order(
            'created_at',
            {
              ascending: false
            }
          );

      if (error) {
        console.error(
          'Supabase history transactions error:',
          error
        );

        return {
          wallet,
          transactions: []
        };
      }

      return {
        wallet,
        transactions:
          data || []
      };
    }

    // =========================================================
    // ORDER HELPERS
    // =========================================================

    function getOrderAmount(order) {
      const total =
        numberValue(
          order?.total_amount
        );

      if (total > 0) {
        return total;
      }

      const item =
        order?.order_items?.[0];

      const itemTotal =
        numberValue(
          item?.total_price
        );

      if (itemTotal > 0) {
        return itemTotal;
      }

      const price =
        numberValue(
          item?.unit_price
        );

      const qty =
        Math.max(
          1,
          numberValue(
            item?.quantity
          )
        );

      return price * qty;
    }

    function getOrderProductName(order) {
      const item =
        order?.order_items?.[0];

      return normalizeProductName(
        item?.product_name ||
        'Benefit',

        getOrderAmount(
          order
        )
      );
    }

    function frontendOrderId(order) {
      return (
        order?.order_number ||
        order?.id ||
        ''
      );
    }

    function buildVoucherMap(vouchers) {
      const result = {};

      (vouchers || [])
        .forEach(voucher => {
          const orderId =
            voucher
              ?.order_items
              ?.order_id;

          if (
            orderId &&
            !result[orderId]
          ) {
            result[orderId] =
              voucher;
          }
        });

      return result;
    }

    // =========================================================
    // WALLET -> FRONTEND
    // =========================================================

    function syncWalletToFrontend(wallet) {
      if (!wallet) {
        return;
      }

      const amount =
        numberValue(
          wallet.available_amount
        );

      state.v14 =
        state.v14 || {};

      state.v14.ewalletBalance =
        amount;

      state.v19 =
        state.v19 || {};

      state.v19.wallets =
        Array.isArray(
          state.v19.wallets
        )
          ? state.v19.wallets
          : [];

      let base =
        state.v19.wallets.find(
          wallet =>
            wallet.id ===
            'EW-BASE'
        );

      if (!base) {
        base = {
          id:
            'EW-BASE',

          name:
            'E-konto',

          type:
            'universal',

          balance:
            amount,

          icon:
            '💼',

          active:
            true,

          cardId:
            null
        };

        state.v19.wallets
          .unshift(base);
      }

      base.balance =
        amount;

      try {
        if (
          state.v44?.eaccount
        ) {
          state.v44
            .eaccount
            .balance =
              amount;
        }
      } catch (e) {}
    }

    // =========================================================
    // HISTORY -> FRONTEND
    // =========================================================

    function syncHistoryToFrontend(
      orders,
      vouchers
    ) {
      state.v14 =
        state.v14 || {};

      state.v14.orders = [];
      state.v14.vouchers = [];

      const voucherMap =
        buildVoucherMap(
          vouchers
        );

      (vouchers || [])
        .forEach(voucher => {
          const backendOrderId =
            voucher
              ?.order_items
              ?.order_id;

          const order =
            (orders || [])
              .find(
                candidate =>
                  String(
                    candidate.id
                  ) ===
                  String(
                    backendOrderId
                  )
              );

          const amount =
            order
              ? getOrderAmount(
                  order
                )
              : 0;

          const name =
            order
              ? getOrderProductName(
                  order
                )
              : normalizeProductName(
                  voucher
                    ?.order_items
                    ?.product_name ||
                  voucher
                    ?.provider_name ||
                  'Voucher',

                  amount
                );

          const orderNumber =
            order
              ? frontendOrderId(
                  order
                )
              : backendOrderId;

          state.v14
            .vouchers
            .push({
              id:
                voucher.id,

              orderId:
                orderNumber,

              supabaseOrderId:
                backendOrderId,

              name:
                name,

              icon:
                '🎫',

              type:
                'Kod alfanumeryczny',

              code:
                voucher
                  .code_ciphertext ||
                voucher
                  .display_hint ||
                '—',

              pin:
                '',

              validTo:
                voucher.valid_until
                  ? formatDate(
                      voucher.valid_until
                    )
                  : 'Bezterminowo',

              status:
                voucherStatus(
                  voucher.status
                ),

              createdAt:
                voucher.issued_at ||
                null
            });
        });

      (orders || [])
        .forEach(order => {
          const id =
            frontendOrderId(
              order
            );

          const voucher =
            voucherMap[
              order.id
            ];

          state.v14
            .orders
            .push({
              id:
                id,

              supabaseOrderId:
                order.id,

              orderNumber:
                order.order_number ||
                id,

              date:
                formatDate(
                  order.created_at
                ),

              name:
                getOrderProductName(
                  order
                ),

              value:
                getOrderAmount(
                  order
                ),

              status:
                mapStatus(
                  order.status
                ),

              voucherId:
                voucher?.id ||
                null,

              payment:
                '—',

              backendStatus:
                order.status,

              createdAt:
                order.created_at
            });
        });

      state.v14
        .orders
        .sort(
          (a, b) =>
            String(
              b.createdAt || ''
            ).localeCompare(
              String(
                a.createdAt || ''
              )
            )
        );
    }

    // =========================================================
    // TRANSACTIONS -> FRONTEND
    // =========================================================

    function syncTransactionsToFrontend(
      transactions,
      orders
    ) {
      state.wallet_transactions =
        (transactions || [])
          .map(tx => {
            const dbOrder =
              (orders || [])
                .find(
                  order =>
                    String(
                      order.id
                    ) ===
                    String(
                      tx.order_id
                    )
                );

            let localOrderId =
              dbOrder
                ? frontendOrderId(
                    dbOrder
                  )
                : null;

            if (
              !localOrderId &&
              tx.reference_key
            ) {
              const ref =
                String(
                  tx.reference_key
                );

              const baseRef =
                ref.replace(
                  /-REFUND$/i,
                  ''
                );

              const found =
                (orders || [])
                  .find(
                    order =>
                      String(
                        order
                          .order_number ||
                        ''
                      ) ===
                      baseRef
                  );

              if (found) {
                localOrderId =
                  frontendOrderId(
                    found
                  );
              }
            }

            const transactionType =
              String(
                tx.transaction_type ||
                ''
              ).toLowerCase();

            const rawAmount =
              Math.abs(
                numberValue(
                  tx.amount
                )
              );

            let signedAmount =
              rawAmount;

            if (
              transactionType === 'purchase' ||
              transactionType === 'payment' ||
              transactionType === 'debit'
            ) {
              signedAmount =
                -rawAmount;
            }

            if (
              transactionType === 'refund' ||
              transactionType === 'credit' ||
              transactionType === 'topup' ||
              transactionType === 'funding'
            ) {
              signedAmount =
                rawAmount;
            }

            return {
              id:
                tx.id,

              order_id:
                localOrderId ||
                tx.order_id,

              supabase_order_id:
                tx.order_id,

              amount:
                signedAmount,

              type:
                tx.transaction_type,

              transaction_type:
                tx.transaction_type,

              status:
                tx.status,

              reference_key:
                tx.reference_key,

              description:
                tx.description,

              balance_before:
                numberValue(
                  tx.balance_before
                ),

              balance_after:
                numberValue(
                  tx.balance_after
                ),

              created_at:
                tx.created_at,

              payment_parts:
                []
            };
          });

      console.log(
        'Mapped wallet transactions:',
        state.wallet_transactions
      );
    }

    // =========================================================
    // REFUND LOOKUP
    // =========================================================

    function findRefundForOrder(
      localOrder
    ) {
      if (!localOrder) {
        return null;
      }

      const orderNumber =
        String(
          localOrder.id ||
          localOrder.orderNumber ||
          ''
        );

      const backendId =
        String(
          localOrder
            .supabaseOrderId ||
          ''
        );

      return (
        state.wallet_transactions ||
        []
      ).find(tx => {
        const transactionType =
          String(
            tx.transaction_type ||
            tx.type ||
            ''
          ).toLowerCase();

        if (
          transactionType !==
          'refund'
        ) {
          return false;
        }

        if (
          orderNumber &&
          String(
            tx.order_id || ''
          ) ===
          orderNumber
        ) {
          return true;
        }

        if (
          backendId &&
          String(
            tx.supabase_order_id ||
            ''
          ) ===
          backendId
        ) {
          return true;
        }

        const ref =
          String(
            tx.reference_key ||
            ''
          );

        if (
          orderNumber &&
          ref ===
            `${orderNumber}-REFUND`
        ) {
          return true;
        }

        return false;
      }) || null;
    }

    // =========================================================
    // COMPLAINT SYNC
    // =========================================================

    function syncRefundComplaints() {
      const employeeComplaints =
        state?.v103?.complaints || [];

      const opsComplaints =
        state?.v64?.complaints || [];

      let changed = false;

      employeeComplaints
        .forEach(complaint => {
          const expectationText =
            String(
              complaint?.expectation ||
              ''
            ).toLowerCase();

          const decisionText =
            String(
              complaint?.decision ||
              ''
            ).toLowerCase();

          const expectsRefund =
            expectationText
              .includes('zwrot') ||
            decisionText
              .includes('zwrot');

          if (!expectsRefund) {
            return;
          }

          const order =
            (state?.v14?.orders || [])
              .find(
                item =>
                  String(item.id) ===
                  String(
                    complaint.orderId
                  )
              );

          if (!order) {
            return;
          }

          const refund =
            findRefundForOrder(
              order
            );

          if (!refund) {
            return;
          }

          const refundAmount =
            Math.abs(
              numberValue(
                refund.amount
              )
            );

          complaint.status =
            'Zamknięta';

          complaint.owner =
            'Zamknięte';

          complaint.decision =
            'Zwrot środków';

          complaint.settlement =
            'Zwrot / korekta';

          complaint.effect =
            `Zwrot ${refundAmount.toLocaleString(
              'pl-PL',
              {
                minimumFractionDigits:
                  2,

                maximumFractionDigits:
                  2
              }
            )} zł został wykonany.`;

          complaint.refundId =
            refund.id;

          complaint.refundAt =
            refund.created_at;

          if (
            !complaint.response
          ) {
            complaint.response =
              'Zwrot środków został wykonany i zaksięgowany na portfelu pracownika.';
          }

          const ops =
            opsComplaints
              .find(
                row =>
                  String(row.id) ===
                  String(
                    complaint.id
                  )
              );

          if (ops) {
            ops.status =
              'Zamknięta';

            ops.owner =
              'Zamknięte';

            ops.decision =
              'Zwrot środków';

            ops.settlement =
              'Zwrot / korekta';

            ops.effect =
              complaint.effect;

            ops.refundId =
              refund.id;

            ops.refundAt =
              refund.created_at;

            ops.response =
              complaint.response;
          }

          changed = true;
        });

      opsComplaints
        .forEach(complaint => {
          const existsEmployee =
            employeeComplaints
              .some(
                row =>
                  String(row.id) ===
                  String(
                    complaint.id
                  )
              );

          if (existsEmployee) {
            return;
          }

          const expectationText =
            String(
              complaint?.expectation ||
              ''
            ).toLowerCase();

          const decisionText =
            String(
              complaint?.decision ||
              ''
            ).toLowerCase();

          const expectsRefund =
            expectationText
              .includes('zwrot') ||
            decisionText
              .includes('zwrot');

          if (!expectsRefund) {
            return;
          }

          const order =
            (state?.v14?.orders || [])
              .find(
                item =>
                  String(item.id) ===
                  String(
                    complaint.orderId
                  )
              );

          if (!order) {
            return;
          }

          const refund =
            findRefundForOrder(
              order
            );

          if (!refund) {
            return;
          }

          const refundAmount =
            Math.abs(
              numberValue(
                refund.amount
              )
            );

          complaint.status =
            'Zamknięta';

          complaint.owner =
            'Zamknięte';

          complaint.decision =
            'Zwrot środków';

          complaint.settlement =
            'Zwrot / korekta';

          complaint.effect =
            `Zwrot ${refundAmount.toLocaleString(
              'pl-PL',
              {
                minimumFractionDigits:
                  2,

                maximumFractionDigits:
                  2
              }
            )} zł został wykonany.`;

          complaint.refundId =
            refund.id;

          complaint.refundAt =
            refund.created_at;

          if (!complaint.response) {
            complaint.response =
              'Zwrot środków został wykonany i zaksięgowany na portfelu pracownika.';
          }

          changed = true;
        });

      return changed;
    }

    // =========================================================
    // PUBLIC REFRESH
    // =========================================================

    window.loadSupabaseOrderHistory =
      async function () {
        try {
          const user =
            await getCurrentUser();

          if (!user) {
            console.warn(
              'Supabase history sync: brak aktywnego użytkownika'
            );

            return false;
          }

          const [
            orders,
            vouchers,
            financial
          ] =
            await Promise.all([
              loadOrders(
                user.id
              ),

              loadVouchers(
                user.id
              ),

              loadTransactions(
                user.id
              )
            ]);

          syncHistoryToFrontend(
            orders,
            vouchers
          );

          syncWalletToFrontend(
            financial.wallet
          );

          syncTransactionsToFrontend(
            financial.transactions,
            orders
          );

          const complaintsUpdated =
            syncRefundComplaints();

          try {
            persist();
          } catch (e) {}

          try {
            render();
          } catch (e) {}

          console.log(
            'Supabase history + refund sync OK',
            {
              orders:
                state.v14.orders,

              transactions:
                state.wallet_transactions,

              complaintsUpdated:
                complaintsUpdated,

              balance:
                financial
                  .wallet
                  ?.available_amount
            }
          );

          return true;

        } catch (err) {
          console.error(
            'Supabase history + refund sync error:',
            err
          );

          return false;
        }
      };

    setTimeout(
      function () {
        window
          .loadSupabaseOrderHistory()
          .catch(
            function (err) {
              console.warn(
                'Initial history/refund sync warning:',
                err
              );
            }
          );
      },
      500
    );

    console.log(
      'Supabase history + refund sync ready — transaction_type FIX'
    );

  }, 1200);
});


;
/* ===== SOURCE: supabase-cancel.js ===== */
window.addEventListener('load', function () {
  setTimeout(function () {
    'use strict';

    if (!window.sb) {
      console.error('Supabase cancel/refund FIX: brak klienta Supabase');
      return;
    }

    // =========================================================
    // HELPERY
    // =========================================================

    function norm(value) {
      return String(value || '')
        .toLowerCase()
        .normalize('NFD')
        .replace(/[\u0300-\u036f]/g, '')
        .replace(/[^a-z0-9]+/g, ' ')
        .trim();
    }

    function isUuid(value) {
      return /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i
        .test(String(value || ''));
    }

    async function getUser() {
      const {
        data: { user },
        error
      } = await window.sb.auth.getUser();

      if (error || !user) {
        throw new Error('Sesja wygasła. Zaloguj się ponownie.');
      }

      return user;
    }

    function localProductName(order) {
      return String(
        order?.name ||
        order?.productName ||
        ''
      ).trim();
    }

    function localAmount(order) {
      return Number(
        order?.value ??
        order?.amount ??
        order?.total ??
        0
      );
    }

    function dbProductName(order) {
      return String(
        order?.order_items?.[0]?.product_name ||
        ''
      ).trim();
    }

    function dbAmount(order) {
      const total =
        Number(order?.total_amount);

      if (
        Number.isFinite(total) &&
        total > 0
      ) {
        return total;
      }

      return Number(
        order?.order_items?.[0]?.total_price ||
        0
      );
    }

    function finishComplaintDecision() {
      try {
        state.modal = null;
      } catch (e) {}

      try {
        if (typeof closeModal === 'function') {
          closeModal();
        }
      } catch (e) {}

      try {
        if (typeof persist === 'function') {
          persist();
        }
      } catch (e) {}

      try {
        if (typeof save === 'function') {
          save();
        }
      } catch (e) {}

      try {
        if (typeof render === 'function') {
          render();
        }
      } catch (e) {}

      try {
        if (typeof toast === 'function') {
          toast(
            'Reklamacja rozpatrzona',
            'Odpowiedź została wysłana pracownikowi.'
          );
        }
      } catch (e) {}

      console.log(
        '✅ Complaint decision finished — modal closed + success message'
      );
    }

    // =========================================================
    // POBIERANIE ZAMÓWIEŃ Z SUPABASE
    // =========================================================

    async function getOrderById(id, userId) {
      if (
        !id ||
        !isUuid(id)
      ) {
        return null;
      }

      const {
        data,
        error
      } = await window.sb
        .from('orders')
        .select(`
          id,
          order_number,
          user_id,
          company_id,
          status,
          total_amount,
          created_at,
          order_items (
            id,
            order_id,
            product_name,
            total_price,
            fulfillment_status
          )
        `)
        .eq('id', id)
        .eq('user_id', userId)
        .limit(1);

      if (error) {
        console.warn(
          'Supabase refund FIX: lookup by id error',
          error
        );

        return null;
      }

      return data?.[0] || null;
    }

    async function getOrderByNumber(orderNumber, userId) {
      if (!orderNumber) {
        return null;
      }

      const {
        data,
        error
      } = await window.sb
        .from('orders')
        .select(`
          id,
          order_number,
          user_id,
          company_id,
          status,
          total_amount,
          created_at,
          order_items (
            id,
            order_id,
            product_name,
            total_price,
            fulfillment_status
          )
        `)
        .eq(
          'order_number',
          String(orderNumber)
        )
        .eq(
          'user_id',
          userId
        )
        .order(
          'created_at',
          {
            ascending: false
          }
        )
        .limit(1);

      if (error) {
        console.warn(
          'Supabase refund FIX: lookup by order_number error',
          error
        );

        return null;
      }

      return data?.[0] || null;
    }

    async function getLatestOrders(userId) {
      const {
        data,
        error
      } = await window.sb
        .from('orders')
        .select(`
          id,
          order_number,
          user_id,
          company_id,
          status,
          total_amount,
          created_at,
          order_items (
            id,
            order_id,
            product_name,
            total_price,
            fulfillment_status
          )
        `)
        .eq(
          'user_id',
          userId
        )
        .order(
          'created_at',
          {
            ascending: false
          }
        )
        .limit(30);

      if (error) {
        throw error;
      }

      return data || [];
    }

    function scoreOrder(candidate, localOrder) {
      let score = 0;

      const localName =
        norm(
          localProductName(localOrder)
        );

      const candidateName =
        norm(
          dbProductName(candidate)
        );

      const localValue =
        localAmount(localOrder);

      const candidateValue =
        dbAmount(candidate);

      if (
        localName &&
        candidateName &&
        localName === candidateName
      ) {
        score += 100;
      } else if (
        localName &&
        candidateName &&
        (
          localName.includes(candidateName) ||
          candidateName.includes(localName)
        )
      ) {
        score += 70;
      } else if (
        localName &&
        candidateName
      ) {
        const a =
          localName
            .split(' ')
            .filter(Boolean);

        const b =
          candidateName
            .split(' ')
            .filter(Boolean);

        const common =
          a.filter(
            word =>
              b.includes(word)
          ).length;

        score += common * 15;
      }

      if (
        Number.isFinite(localValue) &&
        Number.isFinite(candidateValue) &&
        localValue > 0 &&
        candidateValue > 0 &&
        Math.abs(
          localValue -
          candidateValue
        ) < 0.01
      ) {
        score += 80;
      }

      if (
        localOrder?.id &&
        candidate?.order_number &&
        String(localOrder.id) ===
        String(candidate.order_number)
      ) {
        score += 250;
      }

      return score;
    }

    async function resolveOrder(localOrder, user) {
      if (!localOrder) {
        return null;
      }

      const backendIds = [
        localOrder.supabaseOrderId,
        localOrder.supabase_order_id,
        localOrder.backendOrderId,
        localOrder.backend_order_id,
        localOrder.orderUuid,
        localOrder.order_uuid
      ].filter(Boolean);

      for (
        const backendId
        of backendIds
      ) {
        const found =
          await getOrderById(
            backendId,
            user.id
          );

        if (found) {
          return found;
        }
      }

      if (
        isUuid(localOrder.id)
      ) {
        const found =
          await getOrderById(
            localOrder.id,
            user.id
          );

        if (found) {
          return found;
        }
      }

      if (localOrder.id) {
        const found =
          await getOrderByNumber(
            localOrder.id,
            user.id
          );

        if (found) {
          return found;
        }
      }

      const orders =
        await getLatestOrders(
          user.id
        );

      const scored =
        orders
          .map(order => ({
            order,
            score:
              scoreOrder(
                order,
                localOrder
              )
          }))
          .sort(
            (a, b) =>
              b.score -
              a.score
          );

      const best =
        scored[0];

      if (
        !best ||
        best.score < 80
      ) {
        return null;
      }

      return best.order;
    }

    // =========================================================
    // SPRAWDZENIE, CZY REFUND JUŻ ISTNIEJE
    // =========================================================

    async function refundAlreadyExists(orderId) {
      const {
        data,
        error
      } = await window.sb
        .from('wallet_transactions')
        .select(`
          id,
          order_id,
          amount,
          transaction_type,
          status,
          created_at
        `)
        .eq(
          'order_id',
          orderId
        )
        .eq(
          'transaction_type',
          'refund'
        )
        .order(
          'created_at',
          {
            ascending: false
          }
        )
        .limit(1);

      if (error) {
        console.warn(
          'Refund lookup warning:',
          error
        );

        return null;
      }

      return data?.[0] || null;
    }

    // =========================================================
    // PRAWDZIWY REFUND W SUPABASE
    // =========================================================

    async function executeRealRefund(
      localOrder,
      reason
    ) {
      const user =
        await getUser();

      const dbOrder =
        await resolveOrder(
          localOrder,
          user
        );

      if (!dbOrder?.id) {
        throw new Error(
          'Nie udało się dopasować zamówienia do rekordu w Supabase.'
        );
      }

      localOrder.supabaseOrderId =
        dbOrder.id;

      localOrder.orderNumber =
        dbOrder.order_number ||
        localOrder.id;

      try {
        persist();
      } catch (e) {}

      const existingRefund =
        await refundAlreadyExists(
          dbOrder.id
        );

      if (existingRefund) {
        console.log(
          'Refund już istnieje:',
          existingRefund
        );

        return {
          ok: true,
          alreadyRefunded: true,
          orderId: dbOrder.id,
          refund:
            existingRefund
        };
      }

      const {
        data,
        error
      } = await window.sb.rpc(
        'cancel_order_and_refund',
        {
          p_order_id:
            dbOrder.id,

          p_reason:
            String(
              reason ||
              'Zwrot środków'
            ).trim()
        }
      );

      if (error) {
        console.error(
          'cancel_order_and_refund error:',
          error
        );

        throw new Error(
          error.message ||
          'Nie udało się wykonać zwrotu.'
        );
      }

      console.log(
        'Real Supabase refund OK:',
        data
      );

      if (
        typeof window
          .loadSupabaseOrderHistory ===
        'function'
      ) {
        try {
          await window
            .loadSupabaseOrderHistory();
        } catch (e) {
          console.warn(
            'History refresh warning:',
            e
          );
        }
      }

      return {
        ok: true,
        orderId:
          dbOrder.id,
        data
      };
    }

    window.ubApplyRefund111 =
      async function (
        localOrderId,
        reason,
        complaintId,
        label
      ) {
        try {
          const localOrder =
            (state?.v14?.orders || [])
              .find(
                order =>
                  String(order?.id) ===
                  String(localOrderId)
              );

          if (!localOrder) {
            throw new Error(
              'Nie znaleziono zamówienia w historii pracownika.'
            );
          }

          const result =
            await executeRealRefund(
              localOrder,
              reason ||
              'Zwrot środków'
            );

          console.log(
            'ubApplyRefund111 OK',
            {
              complaintId,
              label,
              result
            }
          );

          return true;

        } catch (err) {
          console.error(
            'ubApplyRefund111 error:',
            err
          );

          alert(
            'Nie udało się zwrócić środków: ' +
            (
              err?.message ||
              'błąd Supabase'
            )
          );

          return false;
        }
      };

    // =========================================================
    // WNIOSEK O ANULOWANIE
    // =========================================================

    function getLocalOrderFromCancelDraft() {
      const localId =
        state?.v104
          ?.cancelDraft
          ?.orderId;

      if (!localId) {
        return null;
      }

      return (
        state?.v14?.orders || []
      ).find(
        order =>
          String(order?.id) ===
          String(localId)
      ) || null;
    }

    async function findExistingRequest(
      orderId,
      userId
    ) {
      const {
        data,
        error
      } = await window.sb
        .from(
          'order_cancellation_requests'
        )
        .select(`
          id,
          order_id,
          user_id,
          reason,
          status,
          decision_note,
          created_at
        `)
        .eq(
          'order_id',
          orderId
        )
        .eq(
          'user_id',
          userId
        )
        .order(
          'created_at',
          {
            ascending: false
          }
        )
        .limit(1);

      if (error) {
        return null;
      }

      return data?.[0] || null;
    }

    async function submitCancellation() {
      if (
        window.__supabaseCancelBusy
      ) {
        return;
      }

      window.__supabaseCancelBusy =
        true;

      try {
        const checkbox =
          document.getElementById(
            'v104CancelConfirm'
          );

        if (
          checkbox &&
          !checkbox.checked
        ) {
          const errorBox =
            document.getElementById(
              'v104CancelError'
            );

          if (errorBox) {
            errorBox.textContent =
              'Potwierdź wysłanie wniosku do BOK.';
          }

          return;
        }

        const user =
          await getUser();

        const localOrder =
          getLocalOrderFromCancelDraft();

        if (!localOrder) {
          alert(
            'Nie znaleziono zamówienia w historii.'
          );

          return;
        }

        const reason =
          String(
            state?.v104
              ?.cancelDraft
              ?.reason ||
            'Anulowanie zamówienia'
          ).trim();

        const dbOrder =
          await resolveOrder(
            localOrder,
            user
          );

        if (!dbOrder?.id) {
          alert(
            'Nie udało się dopasować zamówienia do rekordu w Supabase.'
          );

          return;
        }

        localOrder.supabaseOrderId =
          dbOrder.id;

        localOrder.orderNumber =
          dbOrder.order_number ||
          localOrder.id;

        try {
          persist();
        } catch (e) {}

        const existing =
          await findExistingRequest(
            dbOrder.id,
            user.id
          );

        if (existing) {
          alert(
            'Wniosek o anulowanie dla tego zamówienia już istnieje.'
          );

          return;
        }

        const {
          data,
          error
        } = await window.sb.rpc(
          'create_order_cancellation_request',
          {
            p_order_id:
              dbOrder.id,

            p_reason:
              reason
          }
        );

        if (error) {
          console.error(
            'Cancellation request error:',
            error
          );

          alert(
            'Nie udało się wysłać wniosku: ' +
            (
              error.message ||
              'błąd Supabase'
            )
          );

          return;
        }

        console.log(
          'Cancellation request OK:',
          data
        );

        alert(
          'Wniosek został wysłany do BOK.'
        );

        try {
          closeModal();
        } catch (e) {}

        try {
          if (
            typeof window
              .loadSupabaseOrderHistory ===
            'function'
          ) {
            await window
              .loadSupabaseOrderHistory();
          }
        } catch (e) {}

      } catch (err) {
        console.error(
          'Cancellation submit fatal error:',
          err
        );

        alert(
          err?.message ||
          'Wystąpił błąd podczas wysyłania wniosku.'
        );

      } finally {
        window.__supabaseCancelBusy =
          false;
      }
    }

    window.v104ExecuteCancel =
      submitCancellation;

    // Keep a stable reference to the Supabase-backed cancellation handler.
    // This is intentionally process-only and does not touch UI/branding.
    window.__supabaseCancelHandler = window.v104ExecuteCancel;
    try { window.__supabaseCancelHandler.__supabaseBacked = true; } catch (e) {}

    try {
      v104ExecuteCancel =
        window.v104ExecuteCancel;
    } catch (e) {}

    // =========================================================
    // BOK / REKLAMACJE
    // =========================================================

    const originalDecisionSave =
      window.v24DecisionSave;

    if (
      typeof originalDecisionSave ===
      'function'
    ) {
      window.v24DecisionSave =
        async function (id) {

          const decision =
            document
              .getElementById(
                'v24Decision'
              )
              ?.value ||
            'Odrzucona';

          const response =
            String(
              document
                .getElementById(
                  'v24Response'
                )
                ?.value ||
              ''
            ).trim();

          if (
            response.length < 8
          ) {
            const errorBox =
              document.getElementById(
                'v24DecisionError'
              );

            if (errorBox) {
              errorBox.textContent =
                'Wpisz odpowiedź dla pracownika — minimum 8 znaków.';
            }

            return;
          }

          // =====================================================
          // DECYZJE BEZ REFUNDU
          // =====================================================

          if (
            decision !==
            'Zwrot środków'
          ) {
            try {
              const result =
                await originalDecisionSave
                  .apply(
                    this,
                    arguments
                  );

              setTimeout(
                function () {
                  finishComplaintDecision();
                },
                80
              );

              return result;

            } catch (err) {
              console.error(
                'Complaint decision error:',
                err
              );

              alert(
                'Nie udało się zapisać decyzji reklamacji.'
              );

              return;
            }
          }

          // =====================================================
          // ZWROT ŚRODKÓW
          // =====================================================

          if (
            window
              .__complaintRefundBusy
          ) {
            return;
          }

          window
            .__complaintRefundBusy =
            true;

          try {
            const complaint =
              (
                state?.v64
                  ?.complaints || []
              ).find(
                c =>
                  String(c?.id) ===
                  String(id)
              ) ||
              (
                state?.v103
                  ?.complaints || []
              ).find(
                c =>
                  String(c?.id) ===
                  String(id)
              );

            if (!complaint) {
              alert(
                'Nie znaleziono reklamacji.'
              );

              return;
            }

            const localOrder =
              (
                state?.v14
                  ?.orders || []
              ).find(
                order =>
                  String(order?.id) ===
                  String(
                    complaint.orderId
                  )
              );

            if (!localOrder) {
              alert(
                'Nie znaleziono zamówienia przypisanego do reklamacji.'
              );

              return;
            }

            const refundResult =
              await executeRealRefund(
                localOrder,
                'Zwrot po uznanej reklamacji ' +
                id
              );

            if (
              !refundResult?.ok
            ) {
              alert(
                'Zwrot nie został wykonany. Reklamacja pozostaje otwarta.'
              );

              return;
            }

            localOrder.__refundApplied =
              true;

            localOrder
              .__complaintRefunded =
              true;

            await originalDecisionSave
              .apply(
                this,
                arguments
              );

            try {
              if (
                typeof window
                  .loadSupabaseOrderHistory ===
                'function'
              ) {
                await window
                  .loadSupabaseOrderHistory();
              }
            } catch (e) {}

            setTimeout(
              function () {
                finishComplaintDecision();
              },
              100
            );

          } catch (err) {
            console.error(
              'Complaint refund error:',
              err
            );

            alert(
              'Nie udało się zwrócić środków. Reklamacja NIE została zamknięta.\n\n' +
              (
                err?.message ||
                'Błąd Supabase'
              )
            );

          } finally {
            window
              .__complaintRefundBusy =
              false;
          }
        };

      try {
        v24DecisionSave =
          window.v24DecisionSave;
      } catch (e) {}
    }

    // =========================================================
    // AUTO-REPAIR WYŁĄCZONY
    // =========================================================

    console.log(
      '✅ Supabase cancellation + complaint refund integration ready — modal success FIX'
    );

  }, 1800);
});


;
/* ===== SOURCE: supabase-bok-cancellations.js ===== */
(function () {
  'use strict';

  // =========================================================
  // INIT
  // =========================================================

  function initBokCancellations() {
    if (window.__supabaseBokCancellationsFinalInitialized) {
      return;
    }

    window.__supabaseBokCancellationsFinalInitialized = true;

    console.log(
      'Supabase BOK cancellations FINAL integration starting'
    );

    // =======================================================
    // HELPERY
    // =======================================================

    function sleep(ms) {
      return new Promise(
        resolve => setTimeout(resolve, ms)
      );
    }

    function normalizeText(value) {
      return String(value || '')
        .replace(/\s+/g, ' ')
        .trim();
    }

    function formatDate(value) {
      if (!value) {
        return '—';
      }

      try {
        return new Date(value)
          .toLocaleString(
            'pl-PL',
            {
              day: '2-digit',
              month: '2-digit',
              year: 'numeric',
              hour: '2-digit',
              minute: '2-digit'
            }
          );
      } catch (e) {
        return String(value);
      }
    }

    function mapRequestStatus(status) {
      switch (status) {
        case 'pending':
          return 'Oczekuje na decyzję Operacji';

        case 'approved':
          return 'Zaakceptowany';

        case 'rejected':
          return 'Odrzucony';

        default:
          return status || '—';
      }
    }

    function getAppState() {
      try {
        if (
          typeof state !== 'undefined'
        ) {
          return state;
        }
      } catch (e) {}

      return null;
    }

    function safePersist() {
      try {
        if (
          typeof persist === 'function'
        ) {
          persist();
        }
      } catch (err) {
        console.warn(
          'BOK cancellations persist warning:',
          err
        );
      }
    }

    function safeRender() {
      try {
        if (
          typeof render === 'function'
        ) {
          render();
        }
      } catch (err) {
        console.warn(
          'BOK cancellations render warning:',
          err
        );
      }
    }

    // =======================================================
    // CZEKAJ NA AUTH
    // =======================================================

    async function waitForAuthenticatedUser() {
      if (!window.sb) {
        console.error(
          'BOK cancellations: brak klienta Supabase'
        );

        return null;
      }

      for (
        let attempt = 1;
        attempt <= 30;
        attempt++
      ) {
        try {
          const {
            data: {
              user
            },
            error
          } = await window.sb.auth.getUser();

          if (
            !error &&
            user
          ) {
            console.log(
              'BOK cancellations authenticated:',
              user.id
            );

            return user;
          }

        } catch (err) {
          console.warn(
            'BOK cancellations auth wait:',
            attempt
          );
        }

        await sleep(300);
      }

      console.error(
        'BOK cancellations: użytkownik nie został zalogowany'
      );

      return null;
    }

    // =======================================================
    // SUPABASE -> state.v111.cancelRequests
    // =======================================================

    function syncRequestsToNativeState(
      requests
    ) {
      const appState =
        getAppState();

      if (!appState) {
        console.error(
          'BOK cancellations: state nie jest dostępny'
        );

        return false;
      }

      appState.v111 =
        appState.v111 &&
        typeof appState.v111 === 'object'
          ? appState.v111
          : {};

      const nativeRows =
        requests.map(
          request => ({
            id:
              request.id,

            orderId:
              request.order_number ||
              request.order_id,

            employee:
              request.employee_name ||
              request.user_id ||
              'Pracownik',

            product:
              request.product_name ||
              'Zamówienie',

            amount:
              Number(
                request.amount || 0
              ),

            reason:
              request.reason ||
              'Brak podanego powodu',

            created:
              formatDate(
                request.created_at
              ),

            status:
              mapRequestStatus(
                request.status
              ),

            decision:
              request.decision_note ||
              (
                request.status === 'pending'
                  ? '—'
                  : ''
              ),

            resolved:
              request.decided_at
                ? formatDate(
                    request.decided_at
                  )
                : '',

            _supabase:
              true,

            _supabaseRequestId:
              request.id,

            _supabaseOrderId:
              request.order_id,

            _supabaseStatus:
              request.status
          })
        );

      appState.v111.cancelRequests =
        nativeRows;

      console.log(
        'BOK cancellations synced to state.v111:',
        nativeRows
      );

      safePersist();

      return true;
    }

    // =======================================================
    // LOAD
    // =======================================================

    window.loadBokCancellationRequests =
      async function () {
        try {
          if (!window.sb) {
            console.error(
              'BOK cancellations: brak Supabase'
            );

            return [];
          }

          const {
            data: {
              user
            },
            error: userError
          } = await window.sb.auth.getUser();

          if (
            userError ||
            !user
          ) {
            console.warn(
              'BOK cancellations: brak użytkownika przy load'
            );

            return [];
          }

          console.log(
            'BOK cancellations load start:',
            user.id
          );

          const {
            data: requests,
            error: requestsError
          } = await window.sb
            .from(
              'order_cancellation_requests'
            )
            .select(`
              id,
              company_id,
              user_id,
              order_id,
              reason,
              status,
              decision_note,
              decided_by,
              decided_at,
              created_at,
              updated_at
            `)
            .order(
              'created_at',
              {
                ascending: false
              }
            );

          if (requestsError) {
            console.error(
              'BOK cancellations requests error:',
              requestsError
            );

            return [];
          }

          const rows =
            requests || [];

          const orderIds = [
            ...new Set(
              rows
                .map(
                  row =>
                    row.order_id
                )
                .filter(Boolean)
            )
          ];

          const userIds = [
            ...new Set(
              rows
                .map(
                  row =>
                    row.user_id
                )
                .filter(Boolean)
            )
          ];

          let orders = [];
          let items = [];
          let profiles = [];

          if (orderIds.length) {
            const {
              data,
              error
            } = await window.sb
              .from('orders')
              .select(`
                id,
                order_number,
                status,
                total_amount,
                user_id,
                company_id,
                created_at
              `)
              .in(
                'id',
                orderIds
              );

            if (error) {
              console.error(
                'BOK cancellation orders error:',
                error
              );
            } else {
              orders =
                data || [];
            }

            const {
              data: itemData,
              error: itemError
            } = await window.sb
              .from('order_items')
              .select(`
                id,
                order_id,
                product_id,
                product_name,
                quantity,
                unit_price,
                total_price,
                fulfillment_status
              `)
              .in(
                'order_id',
                orderIds
              );

            if (itemError) {
              console.warn(
                'BOK cancellation items warning:',
                itemError
              );
            } else {
              items =
                itemData || [];
            }
          }

          if (userIds.length) {
            const {
              data,
              error
            } = await window.sb
              .from('profiles')
              .select(`
                id,
                first_name,
                last_name
              `)
              .in(
                'id',
                userIds
              );

            if (error) {
              console.warn(
                'BOK cancellation profiles warning:',
                error
              );
            } else {
              profiles =
                data || [];
            }
          }

          const orderById = {};
          const itemByOrderId = {};
          const profileById = {};

          orders.forEach(
            order => {
              orderById[
                order.id
              ] = order;
            }
          );

          items.forEach(
            item => {
              if (
                !itemByOrderId[
                  item.order_id
                ]
              ) {
                itemByOrderId[
                  item.order_id
                ] = item;
              }
            }
          );

          profiles.forEach(
            profile => {
              profileById[
                profile.id
              ] = profile;
            }
          );

          const enriched =
            rows.map(
              request => {
                const order =
                  orderById[
                    request.order_id
                  ];

                const item =
                  itemByOrderId[
                    request.order_id
                  ];

                const profile =
                  profileById[
                    request.user_id
                  ];

                const employeeName =
                  profile
                    ? [
                        profile.first_name,
                        profile.last_name
                      ]
                        .filter(Boolean)
                        .join(' ')
                    : request.user_id;

                return {
                  ...request,

                  order_number:
                    order?.order_number ||
                    request.order_id,

                  order_status:
                    order?.status ||
                    '—',

                  amount:
                    Number(
                      order?.total_amount ??
                      item?.total_price ??
                      0
                    ),

                  product_name:
                    item?.product_name ||
                    'Zamówienie',

                  fulfillment_status:
                    item?.fulfillment_status ||
                    null,

                  employee_name:
                    employeeName
                };
              }
            );

          window.bokCancellationRequests =
            enriched;

          console.log(
            'BOK cancellations load OK:',
            enriched
          );

          const synced =
            syncRequestsToNativeState(
              enriched
            );

          if (synced) {
            safeRender();
          }

          return enriched;

        } catch (err) {
          console.error(
            'BOK cancellations integration error:',
            err
          );

          return [];
        }
      };
        // =======================================================
    // RESOLVE POWIADOMIENIA
    // =======================================================

    async function resolveCancellationNotification(
      requestId
    ) {
      try {
        const now =
          new Date()
            .toISOString();

        const {
          error
        } = await window.sb
          .from(
            'operational_notifications'
          )
          .update({
            read_at: now,
            resolved_at: now
          })
          .eq(
            'reference_id',
            requestId
          );

        if (error) {
          console.warn(
            'BOK cancellation notification resolve warning:',
            error
          );

          return false;
        }

        console.log(
          'BOK cancellation notification resolved:',
          requestId
        );

        if (
          typeof window
            .refreshBokNotifications ===
          'function'
        ) {
          try {
            await window
              .refreshBokNotifications();
          } catch (e) {}
        }

        return true;

      } catch (err) {
        console.warn(
          'BOK cancellation notification resolve exception:',
          err
        );

        return false;
      }
    }

    // =======================================================
    // POWIADOMIENIE O WYKONANYM ZWROCIE
    // =======================================================

    async function createRefundCompletedNotification(
      request
    ) {
      try {
        if (
          !request ||
          !window.sb
        ) {
          return false;
        }

        const amount =
          Number(
            request.amount ||
            0
          );

        const amountText =
          amount.toLocaleString(
            'pl-PL',
            {
              minimumFractionDigits: 2,
              maximumFractionDigits: 2
            }
          ) + ' zł';

        const orderNumber =
          request.order_number ||
          request.order_id ||
          'zamówienie';

        const employeeName =
          request.employee_name ||
          'pracownik';

        const productName =
          request.product_name ||
          'Zamówienie';

        const {
          error
        } = await window.sb
          .from(
            'operational_notifications'
          )
          .insert({
            company_id:
              request.company_id ||
              null,

            user_id:
              request.user_id ||
              null,

            audience:
              'bok',

            notification_type:
              'order_refund_completed',

            title:
              'Zwrot środków wykonany',

            message:
              'Zwrot ' +
              amountText +
              ' dla ' +
              employeeName +
              ' • ' +
              productName +
              ' • ' +
              orderNumber,

            reference_id:
              request.id,

            read_at:
              null,

            resolved_at:
              null
          });

        if (error) {
          console.warn(
            'BOK refund notification insert warning:',
            error
          );

          return false;
        }

        console.log(
          'BOK refund notification created:',
          request.id
        );

        if (
          typeof window
            .refreshBokNotifications ===
          'function'
        ) {
          try {
            await window
              .refreshBokNotifications();
          } catch (e) {}
        }

        return true;

      } catch (err) {
        console.warn(
          'BOK refund notification exception:',
          err
        );

        return false;
      }
    }

    // =======================================================
    // POWIADOMIENIE DLA PRACOWNIKA PO DECYZJI BOK
    // =======================================================

    function pushEmployeeDecisionNotification(
      request,
      decision,
      decisionNote
    ) {
      try {
        if (
          typeof state === 'undefined' ||
          !request
        ) {
          return false;
        }

        state.v27 =
          state.v27 &&
          typeof state.v27 === 'object'
            ? state.v27
            : {};

        state.v27.notifications =
          Array.isArray(
            state.v27.notifications
          )
            ? state.v27.notifications
            : [];

        const approved =
          decision === 'approved';

        const orderNumber =
          request.order_number ||
          request.order_id ||
          'zamówienie';

        const amount =
          Number(
            request.amount ||
            0
          );

        const amountText =
          amount.toLocaleString(
            'pl-PL',
            {
              minimumFractionDigits: 2,
              maximumFractionDigits: 2
            }
          ) + ' zł';

        const id =
          'EMP-CANCEL-' +
          String(
            request.id ||
            ''
          ) +
          '-' +
          decision;

        const alreadyExists =
          state.v27.notifications.some(
            notification =>
              String(
                notification?.id ||
                ''
              ) === id
          );

        if (alreadyExists) {
          return true;
        }

        state.v27.notifications.unshift({
          id:
            id,

          role:
            'employee',

          user_id:
            request.user_id ||
            null,

          title:
            approved
              ? 'Wniosek o anulowanie zaakceptowany'
              : 'Wniosek o anulowanie odrzucony',

          text:
            approved
              ? (
                  'Zamówienie ' +
                  orderNumber +
                  ' zostało anulowane. Voucher został unieważniony, a ' +
                  amountText +
                  ' wróciło do Twojego portfela.'
                )
              : (
                  'Wniosek dotyczący zamówienia ' +
                  orderNumber +
                  ' został odrzucony.' +
                  (
                    decisionNote
                      ? ' Powód: ' +
                        decisionNote
                      : ''
                  )
                ),

          section:
            'Zakupy i historia',

          unread:
            true,

          icon:
            approved
              ? '✓'
              : '×',

          created_at:
            new Date()
              .toISOString()
        });

        safePersist();

        console.log(
          'Employee native decision notification created:',
          id
        );

        return true;

      } catch (err) {
        console.warn(
          'Employee native notification warning:',
          err
        );

        return false;
      }
    }

    async function createEmployeeDecisionNotification(
      request,
      decision,
      decisionNote
    ) {
      if (!request) {
        return false;
      }

      pushEmployeeDecisionNotification(
        request,
        decision,
        decisionNote
      );

      try {
        if (!window.sb) {
          return false;
        }

        const approved =
          decision ===
          'approved';

        const orderNumber =
          request.order_number ||
          request.order_id ||
          'zamówienie';

        const amount =
          Number(
            request.amount ||
            0
          );

        const amountText =
          amount.toLocaleString(
            'pl-PL',
            {
              minimumFractionDigits: 2,
              maximumFractionDigits: 2
            }
          ) + ' zł';

        const title =
          approved
            ? 'Wniosek o anulowanie zaakceptowany'
            : 'Wniosek o anulowanie odrzucony';

        const message =
          approved
            ? (
                'Zamówienie ' +
                orderNumber +
                ' zostało anulowane. Voucher został unieważniony, a ' +
                amountText +
                ' wróciło do Twojego portfela.'
              )
            : (
                'Wniosek dotyczący zamówienia ' +
                orderNumber +
                ' został odrzucony.' +
                (
                  decisionNote
                    ? ' Powód: ' +
                      decisionNote
                    : ''
                )
              );

        const {
          error
        } = await window.sb
          .from(
            'operational_notifications'
          )
          .insert({
            company_id:
              request.company_id ||
              null,

            user_id:
              request.user_id ||
              null,

            audience:
              'employee',

            notification_type:
              approved
                ? 'order_cancellation_approved'
                : 'order_cancellation_rejected',

            title:
              title,

            message:
              message,

            reference_id:
              request.id,

            read_at:
              null,

            resolved_at:
              null
          });

        if (error) {
          console.warn(
            'Employee decision notification DB insert warning:',
            error
          );

          return false;
        }

        console.log(
          'Employee decision notification saved in Supabase:',
          request.id,
          decision
        );

        return true;

      } catch (err) {
        console.warn(
          'Employee decision notification exception:',
          err
        );

        return false;
      }
    }
        // =======================================================
    // FIND REQUEST
    // =======================================================

    function findRequestForNativeRow(
      row
    ) {
      if (!row) {
        return null;
      }

      const rowText =
        normalizeText(
          row.textContent
        );

      const pending =
        (
          window
            .bokCancellationRequests ||
          []
        ).filter(
          request =>
            request.status ===
            'pending'
        );

      let found =
        pending.find(
          request =>
            request.id &&
            rowText.includes(
              request.id
            )
        );

      if (found) {
        return found;
      }

      found =
        pending.find(
          request =>
            request.order_number &&
            rowText.includes(
              request.order_number
            )
        );

      if (found) {
        return found;
      }

      if (
        pending.length === 1
      ) {
        return pending[0];
      }

      return null;
    }

    // =======================================================
    // APPROVE
    // =======================================================

    window.approveBokCancellation =
      async function (
        requestId
      ) {
        try {
          const request =
            (
              window
                .bokCancellationRequests ||
              []
            ).find(
              item =>
                item.id ===
                requestId
            );

          if (!request) {
            alert(
              'Nie znaleziono wniosku.'
            );

            return false;
          }

          if (
            request.status !==
            'pending'
          ) {
            alert(
              'Ten wniosek został już rozpatrzony.'
            );

            return false;
          }

          const confirmed =
            window.confirm(
              'Czy zaakceptować wniosek?\n\n' +
              'Zamówienie zostanie anulowane, voucher unieważniony, a środki wrócą do portfela pracownika.'
            );

          if (!confirmed) {
            return false;
          }

          const note =
            window.prompt(
              'Notatka BOK:',
              'Wniosek zaakceptowany przez BOK'
            );

          if (
            note === null
          ) {
            return false;
          }

          const {
            data,
            error
          } = await window.sb.rpc(
            'approve_order_cancellation',
            {
              p_request_id:
                requestId,

              p_decision_note:
                note.trim() ||
                'Wniosek zaakceptowany przez BOK'
            }
          );

          if (error) {
            console.error(
              'BOK approve error:',
              error
            );

            alert(
              error.message ||
              'Nie udało się zaakceptować wniosku.'
            );

            return false;
          }

          console.log(
            'BOK approve OK:',
            data
          );

          await resolveCancellationNotification(
            requestId
          );

          await createRefundCompletedNotification(
            request
          );

      await createEmployeeDecisionNotification(
  request,
  'approved',
  note.trim() ||
    'Wniosek zaakceptowany przez BOK'
);

if (
  typeof window.loadSupabaseOrderHistory ===
  'function'
) {
  try {
    await window.loadSupabaseOrderHistory();
  } catch (e) {
    console.warn(
      'Employee wallet/history refresh warning:',
      e
    );
  }
}

await window
  .loadBokCancellationRequests();

          if (
            typeof window
              .syncSupabaseEmployeeData ===
            'function'
          ) {
            try {
              await window
                .syncSupabaseEmployeeData();
            } catch (e) {}
          }

          alert(
            'Wniosek zaakceptowany.\nRefund został wykonany.'
          );

          return true;

        } catch (err) {
          console.error(
            'BOK approve exception:',
            err
          );

          alert(
            'Wystąpił błąd podczas akceptacji.'
          );

          return false;
        }
      };

    // =======================================================
    // REJECT
    // =======================================================

    window.rejectBokCancellation =
      async function (
        requestId
      ) {
        try {
          const request =
            (
              window
                .bokCancellationRequests ||
              []
            ).find(
              item =>
                item.id ===
                requestId
            );

          if (!request) {
            alert(
              'Nie znaleziono wniosku.'
            );

            return false;
          }

          if (
            request.status !==
            'pending'
          ) {
            alert(
              'Ten wniosek został już rozpatrzony.'
            );

            return false;
          }

          const note =
            window.prompt(
              'Podaj powód odrzucenia:',
              'Brak podstaw do anulowania'
            );

          if (
            note === null
          ) {
            return false;
          }

          if (
            !note.trim()
          ) {
            alert(
              'Przy odrzuceniu podaj powód decyzji.'
            );

            return false;
          }

          const confirmed =
            window.confirm(
              'Czy na pewno odrzucić ten wniosek?\n\n' +
              'Zamówienie i voucher pozostaną aktywne. Refund nie zostanie wykonany.'
            );

          if (!confirmed) {
            return false;
          }

          const {
            data,
            error
          } = await window.sb.rpc(
            'reject_order_cancellation_request',
            {
              p_request_id:
                requestId,

              p_decision_note:
                note.trim()
            }
          );

          if (error) {
            console.error(
              'BOK reject error:',
              error
            );

            alert(
              error.message ||
              'Nie udało się odrzucić wniosku.'
            );

            return false;
          }

          console.log(
            'BOK reject OK:',
            data
          );

          await resolveCancellationNotification(
            requestId
          );

          await createEmployeeDecisionNotification(
            request,
            'rejected',
            note.trim()
          );

          await window
            .loadBokCancellationRequests();

          alert(
            'Wniosek został odrzucony.\nZakup i voucher pozostają aktywne.'
          );

          return true;

        } catch (err) {
          console.error(
            'BOK reject exception:',
            err
          );

          alert(
            'Wystąpił błąd podczas odrzucenia.'
          );

          return false;
        }
      };
        // =======================================================
    // NATYWNE PRZYCISKI
    // =======================================================

    if (
      !window
        .__bokCancellationFinalButtonsAttached
    ) {
      window
        .__bokCancellationFinalButtonsAttached =
        true;

      document.addEventListener(
        'click',
        async function (
          event
        ) {
          const button =
            event.target.closest(
              'button'
            );

          if (!button) {
            return;
          }

          const label =
            normalizeText(
              button.textContent
            );

          if (
            label !==
              'Akceptuj anulowanie' &&
            label !==
              'Odrzuć'
          ) {
            return;
          }

          event.preventDefault();
          event.stopPropagation();
          event.stopImmediatePropagation();

          await window
            .loadBokCancellationRequests();

          const row =
            button.closest(
              'tr'
            );

          const request =
            findRequestForNativeRow(
              row
            );

          if (!request) {
            alert(
              'Nie znaleziono odpowiadającego wniosku w Supabase.'
            );

            return;
          }

          console.log(
            'BOK native cancellation matched:',
            request
          );

          if (
            label ===
            'Akceptuj anulowanie'
          ) {
            await window
              .approveBokCancellation(
                request.id
              );

            return;
          }

          if (
            label ===
            'Odrzuć'
          ) {
            await window
              .rejectBokCancellation(
                request.id
              );
          }
        },
        true
      );

      console.log(
        'BOK FINAL native cancellation buttons ready'
      );
    }

    // =======================================================
    // DOŁADOWANIE POWIADOMIEŃ
    // =======================================================

    function loadNotificationsScript() {
      if (
        document.querySelector(
          'script[data-supabase-bok-notifications="true"]'
        )
      ) {
        return;
      }

      const script =
        document.createElement(
          'script'
        );

      script.src =
        '/supabase-bok-notifications.js';

      script.async =
        true;

      script.setAttribute(
        'data-supabase-bok-notifications',
        'true'
      );

      script.onload =
        function () {
          console.log(
            'Supabase BOK notifications script loaded'
          );
        };

      script.onerror =
        function (err) {
          console.warn(
            'Supabase BOK notifications load warning:',
            err
          );
        };

      document.head.appendChild(
        script
      );
    }

    // =======================================================
    // START PO LOGINIE
    // =======================================================

    (async function startAfterLogin() {
      const user =
        await waitForAuthenticatedUser();

      if (!user) {
        return;
      }

      await window
        .loadBokCancellationRequests();

      loadNotificationsScript();

      console.log(
        'Supabase BOK cancellations FINAL integration ready'
      );
    })();
  }

  // =========================================================
  // URUCHOMIENIE
  // =========================================================

  if (
    document.readyState ===
    'loading'
  ) {
    window.addEventListener(
      'DOMContentLoaded',
      initBokCancellations,
      {
        once: true
      }
    );
  } else {
    initBokCancellations();
  }

})();


