/* 001 — ub-safe-boot-handler */
(function(){
  function showBootError(message){
    var app=document.getElementById('app');
    if(!app) return;
    app.innerHTML=
      '<div style="min-height:100vh;display:grid;place-items:center;background:#f6f4f8;font-family:Arial,sans-serif;padding:24px">'+
      '<div style="max-width:780px;width:100%;background:#fff;border:1px solid #e4dbe8;border-radius:18px;padding:26px;box-shadow:0 12px 34px rgba(56,26,53,.10)">'+
      '<div style="font-size:22px;font-weight:800;color:#6b174e">Up Bonus — błąd uruchomienia</div>'+
      '<div style="margin-top:10px;font-size:13px;color:#766b77">Plik został poprawnie dostarczony przez serwer, ale JavaScript zatrzymał uruchamianie aplikacji.</div>'+
      '<pre style="margin-top:16px;white-space:pre-wrap;overflow-wrap:anywhere;background:#f8f5f8;border:1px solid #e4dbe8;border-radius:12px;padding:14px;font:12px/1.45 Consolas,monospace;color:#7a1857">'+
      String(message||'Nieznany błąd').replace(/[&<>]/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;'}[c]})+
      '</pre><div style="margin-top:12px;font-size:10px;color:#9b919c">build v59.4 SAFE BOOT</div></div></div>';
  }
  window.addEventListener('error',function(e){
    showBootError((e.message||'JavaScript error')+(e.filename?'\n'+e.filename+':'+e.lineno+':'+e.colno:''));
  });
  window.addEventListener('unhandledrejection',function(e){
    var r=e.reason;
    showBootError('Promise rejection: '+(r && (r.stack||r.message) ? (r.stack||r.message) : String(r)));
  });
  window.__UB_SAFE_BOOT_BUILD__='v59.4';
})();
;


