const ACCESS_PROFILES={
 'malgorzata.bartkiewicz@upbonus.pl':{name:'Małgorzata Bartkiewicz',accesses:['employee','hr','partner','finance','bok','campaigns','superadmin','giftstore']},
 'pracownik@upbonus.pl':{name:'Małgorzata',accesses:['employee']},
 'anna.kowalska@erste.pl':{name:'Anna Kowalska',accesses:['employee','hr','bok','campaigns']},
 'hr@upbonus.pl':{name:'Anna Nowak',accesses:['employee','hr']},
 'bok@upbonus.pl':{name:'Katarzyna Drzewiecka',accesses:['employee','bok']}
};
function accessProfile(email){const key=String(email||'').trim().toLowerCase();return ACCESS_PROFILES[key]||{name:key.split('@')[0].split(/[._-]/).filter(Boolean).map(x=>x.charAt(0).toUpperCase()+x.slice(1)).join(' ')||'Użytkownik',accesses:['employee']}}
function availableAccesses(){return (state.accesses||['employee']).filter(id=>tenant().modules.includes(id))}
function hasMultipleAccesses(){return availableAccesses().length>1}

let state={
 loggedIn:false,tenant:'upbonus',role:null,section:null,user:{name:'Małgorzata Bartkiewicz',email:'malgorzata.bartkiewicz@upbonus.pl'},accesses:['employee','hr','partner','finance','bok','campaigns','superadmin','giftstore'],mobileMenu:false,modal:null,drawer:null,
 filters:{client:'',order:''},customTenants:{},notifications:4,demoMode:false,demoStartedAt:null
};
try{const saved=JSON.parse(localStorage.getItem('upbonus_integrated_v2')||'{}');state={...state,...saved,loggedIn:false,modal:null,drawer:null,mobileMenu:false};}catch(e){}

function persist(){const safe={...state,modal:null,drawer:null,mobileMenu:false,loggedIn:false};localStorage.setItem('upbonus_integrated_v2',JSON.stringify(safe));}
function el(id){return document.getElementById(id)}
function icon(name){return `<span class="icon" aria-hidden="true">${ICONS[name]||'•'}</span>`}
function esc(v){return String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
function tenant(){return {...DEFAULT_TENANTS[state.tenant],...(state.customTenants[state.tenant]||{})}}
function applyTheme(){const t=tenant();document.documentElement.style.setProperty('--brand-primary',t.primary);document.documentElement.style.setProperty('--brand-accent',t.accent);document.documentElement.style.setProperty('--brand-soft',t.soft||'#f5eef8');document.title=`${t.name} — Up Bonus Ecosystem`;}
function decodeB64(v){const bin=atob(v),bytes=new Uint8Array(bin.length);for(let i=0;i<bin.length;i++)bytes[i]=bin.charCodeAt(i);return new TextDecoder('utf-8').decode(bytes)}
function toast(title,msg=''){const w=el('toastWrap');const d=document.createElement('div');d.className='toast';d.innerHTML=`<div class="status green">${ICONS.check}</div><div><strong>${esc(title)}</strong>${msg?`<small>${esc(msg)}</small>`:''}</div>`;w.appendChild(d);setTimeout(()=>d.remove(),3400)}
function setTenant(id){state.tenant=id;applyTheme();persist();render()}
function login(e){e?.preventDefault();const email=(el('loginEmail')?.value||state.user.email).trim().toLowerCase();const profile=accessProfile(email);state.user={name:profile.name,email};state.accesses=profile.accesses;state.loggedIn=true;state.role=null;state.section=null;const accesses=availableAccesses();if(accesses.length===1){openRole(accesses[0]);persist();toast('Witaj, '+profile.name.split(' ')[0],'Załadowano Twój portal i przyznane benefity.');return}persist();render();toast('Zalogowano','Wybierz jeden z przypisanych dostępów.')}
function logout(){state.loggedIn=false;state.role=null;state.section=null;render()}
function openAccounts(){const accesses=availableAccesses();if(accesses.length===1){openRole(accesses[0]);return}state.role=null;state.section=null;state.mobileMenu=false;render()}
function openRole(role){if(!availableAccesses().includes(role)){toast('Moduł wyłączony','Ten dostęp nie jest aktywny dla wybranej platformy.');return}if(role==='giftstore'){openModule('gift');return}state.role=role;state.section=ROLE_DEFS[role].menu[0]?.[0]||'Start';state.mobileMenu=false;render()}
function selectSection(label){state.section=label;state.mobileMenu=false;if(label==='Magazyn kart i kodów'){openModule('inventory');return}render()}
function toggleMobile(){state.mobileMenu=!state.mobileMenu;render()}
function closeMobile(){state.mobileMenu=false;render()}
function showModal(type,data={}){state.modal={type,data};renderOverlay()}
function closeModal(){state.modal=null;renderOverlay()}
function showDrawer(type,data={}){state.drawer={type,data};renderOverlay()}
function closeDrawer(){state.drawer=null;renderOverlay()}
function toggleButton(btn){btn.classList.toggle('on')}
function saveDemo(message='Zmiany zapisane'){persist();closeModal();closeDrawer();render();toast(message)}

function topbar({roleMode=false}={}){const t=tenant();return `<header class="topbar">
 ${roleMode?`<button class="icon-btn mobile-menu-btn" onclick="toggleMobile()" aria-label="Menu">${icon('menu')}</button>`:''}
 <button class="topbar-brand" style="border:0;background:transparent;text-align:left;padding:0;cursor:pointer" onclick="${roleMode?'openAccounts()':'render()'}">
  <span class="brand-symbol">${esc(t.logo)}</span><span><b>${esc(t.short)}</b><small>${roleMode?esc(ROLE_DEFS[state.role]?.name||'Centrum Kont'):'Centrum Kont'}</small></span>
 </button>
 <div class="top-search"><span>${ICONS.search}</span><input placeholder="Szukaj użytkownika, klienta, zamówienia, kodu lub programu…" onkeydown="if(event.key==='Enter')globalSearch(this.value)" /></div>
 <div class="top-actions">
  <button class="icon-btn" onclick="showModal('tenantSwitch')" title="Przełącz platformę">${icon('globe')}</button>
  ${state.role==='hr'?'':`<button class="icon-btn" onclick="showModal('notifications')" title="Powiadomienia">${icon('bell')}<span class="badge-dot">${state.notifications}</span></button>`}
  <button class="profile-btn" onclick="showModal('profile')"><span class="avatar">MB</span><span><b>${esc(state.user.name)}</b><span>${esc(t.name)}</span></span></button>
 </div>
 </header>`}
function globalSearch(q){if(!q.trim())return;toast('Wyszukiwanie globalne',`Szukam: ${q}`);if(state.role!=='bok'){state.role='bok';state.section='Wyszukiwarka globalna';render()}}

function renderLogin(){const t=tenant();return `<main class="login-page">
 <section class="login-brand">
  <div class="brand-mark"><span class="brand-symbol">${esc(t.logo)}</span><span>${esc(t.name)}</span></div>
  <div class="login-copy"><div class="eyebrow">TWOJA PLATFORMA BENEFITOWA</div><h1>${esc(t.hero)}</h1><p>Zaloguj się, aby sprawdzić przyznane środki, wybrać benefity, odebrać upominek oraz zarządzać swoimi kartami i voucherami.</p>
   <div class="login-points"><div class="login-point"><b>Środki i programy</b><span>Aktualne salda, terminy ważności i historia wykorzystania.</span></div><div class="login-point"><b>Benefity i zakupy</b><span>Karty, vouchery, rabaty, wellbeing i oferty dla rodziny.</span></div><div class="login-point"><b>Wnioski online</b><span>ZFŚS, dofinansowania i statusy bez papierowych formularzy.</span></div></div>
  </div><div class="login-foot">${esc(t.domain)} • Bezpieczne logowanie do platformy</div>
 </section>
 <section class="login-panel"><div class="login-box"><div class="eyebrow">LOGOWANIE</div><h2>Witaj 👋</h2><p>Platforma została rozpoznana automatycznie. Po zalogowaniu przejdziesz bezpośrednio do swoich benefitów albo — gdy masz kilka ról — wybierzesz właściwy dostęp.</p>
  <form class="form-grid" onsubmit="login(event)"><div class="field"><label>Adres e-mail</label><input id="loginEmail" type="email" value="${esc(state.user.email)}" required autocomplete="username" /></div><div class="field"><label>Hasło</label><input type="password" value="UpBonus2026!" required autocomplete="current-password" /></div>
   <div class="row-between"><label class="check"><input type="checkbox" checked /> Zapamiętaj mnie</label><button type="button" class="link-btn" onclick="toast('Reset hasła','Wysłano link demonstracyjny.')">Nie pamiętam hasła</button></div>
   <div class="login-actions"><button class="primary-btn full" type="submit">Zaloguj się ${ICONS.chevron}</button></div>
  </form>
 </div></section>
 </main>`}
function renderAccounts(){const t=tenant();const roles=Object.entries(ROLE_DEFS).filter(([id])=>availableAccesses().includes(id));const demo=state.demoMode?`<div class="ub43-demo-ribbon ub43-demo-ribbon-accounts"><div><span>DEMO SPRZEDAŻOWE</span><b>NovaTech · dane przykładowe</b><small>Możesz swobodnie przełączać perspektywy. Zmiany nie dotyczą żadnego klienta produkcyjnego.</small></div><div><button onclick="ub43ResetDemo()">↻ Resetuj demo</button><button onclick="ub43ExitDemo()">Wyjdź z demo</button></div></div>`:'';return `${topbar()}<main class="account-page"><div class="container">${demo}
 <section class="account-hero"><div class="hero-main"><div class="eyebrow" style="color:#e8c8df">${esc(t.mode.replace('_',' '))} • ${esc(t.domain)}</div><h1>Witaj, ${esc(state.user.name.split(' ')[0])} 👋</h1><p>Po zalogowaniu wybierz obszar pracy. Każdy panel ma własny zakres funkcji i uprawnień.</p><div class="hero-actions"><button class="primary-btn" onclick="openRole('employee')">Przejdź do swoich benefitów</button><button class="secondary-btn" onclick="showModal('tenantSwitch')">Przełącz platformę</button></div></div>
 <aside class="hero-side"><div><h3>Twoje dostępy</h3><p>Centrum Kont pojawia się wyłącznie wtedy, gdy konto ma więcej niż jedną rolę lub platformę.</p></div><div><div class="context-line"><span class="context-icon">${ICONS.building}</span><span><b>${esc(t.name)}</b><span>Aktualna platforma</span></span></div><div class="context-line"><span class="context-icon">${ICONS.shield}</span><span><b>${roles.length} dostępów</b><span>Przypisanych do e-maila</span></span></div><div class="context-line"><span class="context-icon">${ICONS.user}</span><span><b>${esc(state.user.email)}</b><span>Konto użytkownika</span></span></div></div></aside></section>
 <div class="section-head"><div><h2>Wybierz obszar pracy</h2><p>Wybierz obszar, w którym chcesz teraz pracować. Zawsze możesz wrócić tutaj z poziomu panelu.</p></div></div>
 <section class="role-grid">${roles.map(([id,r])=>`<button class="role-card" onclick="openRole('${id}')"><span class="role-icon">${ICONS[r.icon]}</span><span class="role-badge">Aktywne</span><h3>${esc(r.name)}</h3><p>${esc(r.desc)}</p><div class="role-card-footer"><span class="role-meta">${esc(r.group)}</span><span class="arrow-circle">${ICONS.chevron}</span></div></button>`).join('')}</section>
 </div></main>`}
function employeeTopbar(){const t=tenant();return `<header class="topbar employee-topbar">
 <button class="icon-btn mobile-menu-btn" onclick="toggleMobile()" aria-label="Menu">${icon('menu')}</button>
 <button class="topbar-brand" style="border:0;background:transparent;text-align:left;padding:0;cursor:pointer" onclick="state.section='Dla Ciebie';render()"><span class="brand-symbol">${esc(t.logo)}</span><span><b>${esc(t.short)}</b><small>Portal pracownika</small></span></button>
 <div class="top-search"><span>${ICONS.search}</span><input placeholder="Szukaj benefitów, marek, kategorii i ofert…" onkeydown="if(event.key==='Enter'){state.section='Sklep i benefity';render()}" /></div>
 <div class="top-actions"><button class="employee-balance-pill" onclick="selectSection('Portfel i budżety')"><span class="wallet-dot">${ICONS.wallet}</span><span><span>Dostępne środki</span><b>570,00 zł</b></span></button><button class="icon-btn" onclick="selectSection('Zamówienia i vouchery')" title="Koszyk i zamówienia">${icon('order')}<span class="badge-dot">2</span></button><button class="icon-btn" onclick="showModal('notifications')" title="Powiadomienia">${icon('bell')}<span class="badge-dot">${state.notifications}</span></button><button class="profile-btn" onclick="showModal('profile')"><span class="avatar">${esc(state.user.name.split(' ').map(x=>x[0]).join('').slice(0,2).toUpperCase())}</span><span><b>${esc(state.user.name)}</b><span>${esc(t.name)}</span></span></button></div>
 </header>`}
function sidebar(){const r=ROLE_DEFS[state.role];const employeeMenu=[['Dla Ciebie','Start','home'],['Portfel i budżety','Moje środki','wallet'],['Sklep i benefity','Benefity','shop'],['Zamówienia i vouchery','Moje zakupy','order'],['Wnioski i ZFŚS','Wnioski','request'],['Wellbeing','Wellbeing','spark'],['Odbierz upominek','Upominki','gift'],['Pomoc','Pomoc','support']];const menuHtml=state.role==='employee'?employeeMenu.map(([route,label,ic])=>`<button class="menu-btn ${state.section===route?'active':''}" onclick="selectSection('${route.replace(/'/g,"\\'")}')">${icon(ic)}<span>${esc(label)}</span>${route==='Zamówienia i vouchery'?'<span class="count">2</span>':''}</button>`).join(''):r.menu.map(([label,ic])=>`<button class="menu-btn ${state.section===label?'active':''}" onclick="selectSection('${label.replace(/'/g,"\\'")}')">${icon(ic)}<span>${esc(label)}</span>${['Reklamacje','Błędy integracji'].includes(label)?'<span class="count">4</span>':''}</button>`).join('');return `<aside class="sidebar ${state.mobileMenu?'open':''}"><div class="sidebar-head ub209-logo-head"><img class="ub209-sidebar-logo" src="assets/branding/upbonus-logo-orange.png" alt="Up Bonus"></div><nav class="sidebar-menu ub209-menu-up">${menuHtml}</nav><div class="sidebar-foot ub209-logout-foot"><button class="menu-btn ub209-logout" onclick="logout()">${icon('logout')}<span>Wyloguj</span></button></div></aside><div class="sidebar-overlay ${state.mobileMenu?'open':''}" onclick="closeMobile()"></div>`}
function renderRole(){const employee=state.role==='employee';return `<div class="role-app">${employee?employeeTopbar():topbar({roleMode:true})}${sidebar()}<main class="main-content ${employee?'employee-main':''}"><div class="view-container">${renderSection()}</div></main></div>`}
function pageHead(title,desc,actions=''){return `<div class="page-head"><div><h1>${esc(title)}</h1><p>${esc(desc)}</p></div><div class="page-actions">${actions}</div></div>`}
function stat(label,value,iconName='chart',trend=''){return `<div class="stat"><div class="stat-top"><span class="stat-icon">${ICONS[iconName]}</span>${trend?`<span class="trend">${esc(trend)}</span>`:''}</div><b>${esc(value)}</b><span>${esc(label)}</span></div>`}
function genericDashboard(role){if(role==='employee')return employeeDashboard();const title={employee:'Twój pulpit',hr:'Pulpit HR',operations:'Pulpit operacyjny',partner:'Pulpit partnera',finance:'Pulpit finansowy',bok:'Pulpit BOK',campaigns:'Pulpit kampanii',superadmin:'Pulpit systemu'}[role];const metrics={employee:[['Dostępne saldo','570,00 zł','wallet',''],['Aktywne programy','4','layers',''],['Nowe vouchery','2','gift',''],['Oszczędności','1 240 zł','chart','+18%']],hr:[['Pracownicy','12 450','people','+124'],['Aktywne programy','7','layers',''],['Budżet dostępny','2,8 mln zł','wallet',''],['Wnioski do decyzji','18','request','']],operations:[['Zamówienia dziś','1 284','order','+8%'],['Kody dostępne','182 401','database',''],['Błędy','3','alert',''],['Paczki do akceptacji','7','upload','']],partner:[['Aktywne produkty','48','shop',''],['Kody dostępne','42 100','database',''],['Sprzedaż MTD','284 tys. zł','chart','+12%'],['Reklamacje','6','support','']],finance:[['Obrót MTD','4,82 mln zł','finance','+9%'],['Marża','3,61%','chart','+0,2 pp'],['Do rozliczenia','18','partner',''],['Rozbieżności','2','alert','']],bok:[['Otwarte zgłoszenia','42','support',''],['W SLA','91%','chart','+4 pp'],['Reklamacje','12','alert',''],['Wymiany dziś','6','refresh','']],campaigns:[['Aktywne kampanie','9','campaign',''],['Zasięg','884 tys.','people',''],['CTR','6,4%','chart','+0,8 pp'],['Do publikacji','14','calendar','']],superadmin:[['Klienci','1284','building',''],['Platformy','1763','globe',''],['Użytkownicy','5,68 mln','people',''],['Integracje online','99,8%','api','']]}[role];
 return `${pageHead(title,'',`<button class="secondary-btn" onclick="toast('Odświeżono dane')">${icon('refresh')} Odśwież</button>`)}<section class="stat-grid">${metrics.map(x=>stat(x[0],x[1],x[2],x[3])).join('')}</section><section class="dashboard-grid"><div class="panel"><div class="panel-head"><h2>Najczęściej używane</h2><button class="link-btn" onclick="toast('Skróty','Układ skrótów można personalizować.')">Edytuj</button></div><div class="panel-body"><div class="quick-grid">${ROLE_DEFS[role].menu.slice(1,7).map(([l,i])=>`<button class="quick" onclick="selectSection('${l.replace(/'/g,"\\'")}')"><span class="role-icon" style="width:56px;height:56px;margin:0 0 10px;font-size:26px;border-radius:16px">${ICONS[i]}</span><b>${esc(l)}</b><span>Otwórz moduł i przejdź do bieżących działań.</span></button>`).join('')}</div></div></div><aside class="panel"><div class="panel-head"><h3>Do zrobienia</h3><span class="status amber">6 zadań</span></div><div class="panel-body"><ul class="list-clean"><li class="list-item"><span class="status red">Pilne</span><span class="list-item-main"><b>Zweryfikuj błędne mapowania</b><span>Migracja OB 2.0</span></span></li><li class="list-item"><span class="status amber">Dzisiaj</span><span class="list-item-main"><b>Zatwierdź paczki kodów</b><span>7 paczek oczekuje</span></span></li><li class="list-item"><span class="status purple">Nowe</span><span class="list-item-main"><b>Sprawdź kampanię BTS</b><span>Publikacja za 2 dni</span></span></li></ul></div></aside></section>`}

function employeeDashboard(){const first=esc(state.user.name.split(' ')[0]);return `<div class="employee-dashboard v61-home">
 <section class="v61-hero-grid">
  <div class="v61-hero-main">
   <div class="v61-hero-copy"><div class="v61-kicker">TWÓJ DZIEŃ W UP BONUS</div><h1>Cześć, ${first} 👋</h1><p>Masz <b>570 zł</b> do wykorzystania. Zobacz, co opłaca się zrobić dzisiaj.</p><div class="v61-hero-actions"><button class="v61-btn-light" onclick="selectSection('Sklep i benefity')">Odkrywaj benefity</button><button class="v61-btn-ghost" onclick="selectSection('Portfel i budżety')">Zobacz środki</button></div></div>
   <div class="v61-wallet-strip"><div class="v61-wallet-total"><span>ŁĄCZNIE</span><b>570,00 zł</b></div><div><span>Lunch</span><b>220 zł</b><small>do 31.08</small></div><div><span>Prezent</span><b>300 zł</b><small>do 31.12</small></div><div><span>Wellbeing</span><b>50 zł</b><small>do 30.09</small></div></div>
   <div class="v61-expiry"><span>⏳</span><b>120 zł wygasa w tym miesiącu</b><button onclick="selectSection('Portfel i budżety')">Sprawdź gdzie wykorzystać →</button></div>
  </div>
  <aside class="v61-featured" onclick="selectSection('Sklep i benefity')"><div class="v61-featured-top"><span>DZIŚ DLA CIEBIE</span><button aria-label="Dodaj do ulubionych" onclick="event.stopPropagation();this.classList.toggle('on')">♡</button></div><div class="v61-featured-art">🛍️</div><div class="v61-featured-copy"><small>OFERTA DNIA</small><h2>Allegro</h2><p>Karta podarunkowa z dodatkową korzyścią dla użytkowników platformy.</p><div><b>-5%</b><span>od 50 zł</span><strong>Sprawdź →</strong></div></div></aside>
 </section>

 <section class="v61-now"><div class="v61-section-head"><div><span>DZIŚ DLA CIEBIE</span><h2>Co warto zrobić teraz</h2></div><button onclick="selectSection('Sklep i benefity')">Zobacz wszystko</button></div><div class="v61-now-grid"><button class="urgent" onclick="selectSection('Portfel i budżety')"><span class="v61-now-icon">⏳</span><span><small>ŚRODKI</small><b>120 zł wygasa</b><em>Wykorzystaj je przed końcem miesiąca</em></span><strong>→</strong></button><button onclick="selectSection('Wellbeing')"><span class="v61-now-icon">🌿</span><span><small>WELLBEING</small><b>50 zł czeka na Ciebie</b><em>Sport, zdrowie i odpoczynek</em></span><strong>→</strong></button><button onclick="selectSection('Wnioski i ZFŚS')"><span class="v61-now-icon">📝</span><span><small>DO ZROBIENIA</small><b>Uzupełnij wniosek</b><em>Brakuje jednego załącznika</em></span><strong>→</strong></button></div></section>

 <section class="v61-market"><div class="v61-section-head"><div><span>POLECANE</span><h2>Najczęściej wybierane</h2></div><button onclick="selectSection('Sklep i benefity')">Pełny katalog →</button></div>${employeeProductGrid(4)}</section>

 <section class="v61-quick"><button onclick="selectSection('Zamówienia i vouchery')"><span>🎟️</span><b>Moje kody</b><small>2 aktywne</small></button><button onclick="selectSection('Wnioski i ZFŚS')"><span>📝</span><b>Wnioski</b><small>1 do uzupełnienia</small></button><button onclick="selectSection('Odbierz upominek')"><span>🎁</span><b>Upominek</b><small>300 zł dostępne</small></button><button onclick="selectSection('Wellbeing')"><span>🌿</span><b>Wellbeing</b><small>50 zł dostępne</small></button></section>

 <section class="v61-brand-block"><div class="v61-section-head"><div><span>MARKI</span><h2>Popularne w Twojej firmie</h2></div></div><div class="v61-brand-row"><button>Allegro</button><button>Empik</button><button>Decathlon</button><button>Zalando</button><button>Multikino</button><button>IKEA</button></div></section>

 <section class="v61-premium-banner"><div><span>WIĘCEJ NIŻ KAFETERIA</span><h2>Usługi premium i wellbeing w jednym miejscu</h2><p>Prezenty, personalizacja, kody specjalne oraz wsparcie zdrowia i aktywności.</p></div><div class="v61-premium-actions"><button onclick="selectSection('Odbierz upominek')">🎁 Odbierz upominek</button><button onclick="selectSection('Wellbeing')">🌿 Wellbeing</button><button onclick="selectSection('Sklep i benefity')">🏷️ Kody i promocje</button></div></section>
 </div>`}
function employeeProductGrid(limit=8){const products=[['Allegro','Karta podarunkowa','od 50 zł','🛒','-5%'],['Empik','Kultura i zakupy','od 50 zł','📚','Popularne'],['Decathlon','Sport i aktywność','od 50 zł','🚴','Top'],['Wakacje.pl','Podróże i wypoczynek','od 100 zł','✈️','Podróże'],['Zalando','Moda i dodatki','od 50 zł','👗','-3%'],['Multikino','Kino i rozrywka','od 35 zł','🎬','Kultura'],['IKEA','Dom i wyposażenie','od 50 zł','🏠','Dom'],['Super Prezenty','Przeżycia i SPA','od 100 zł','🎀','Prezent']].slice(0,limit);return `<div class="benefit-grid v61-benefit-grid">${products.map(p=>`<article class="benefit-card v61-benefit-card"><div class="v61-cover"><button class="v61-heart" aria-label="Dodaj do ulubionych" onclick="event.stopPropagation();this.classList.toggle('on')">♡</button><span class="v61-tag">${p[4]}</span><span class="v61-art">${p[3]}</span></div><div class="v61-card-body"><small>${p[1]}</small><h3>${p[0]}</h3><div class="v61-card-bottom"><b>${p[2]}</b><button onclick="toast('Wybierz wariant','Otwieram ofertę ${p[0]}.')">Sprawdź</button></div></div></article>`).join('')}</div>`}

function employeeBenefitsView(){return `<div class="employee-dashboard"><div class="page-head"><div><div class="eyebrow">SKLEP I BENEFITY</div><h1>Wybierz coś dla siebie</h1><p>Płać środkami z programów, łącz kilka e-kont lub dopłać prywatnie, jeśli program na to pozwala.</p></div><div class="page-actions"><button class="secondary-btn" onclick="openModule('gift')">Sklep personalizowanych prezentów</button></div></div><section class="employee-section"><div class="employee-catalog-head"><div class="search"><span>${ICONS.search}</span><input placeholder="Szukaj marki, produktu lub kategorii…" /></div><button class="secondary-btn">Filtry</button></div><div class="category-scroll"><button class="category-chip active">Wszystkie</button><button class="category-chip">Karty podarunkowe</button><button class="category-chip">Sport</button><button class="category-chip">Kultura</button><button class="category-chip">Podróże</button><button class="category-chip">Zdrowie</button><button class="category-chip">Edukacja</button><button class="category-chip">Dla rodziny</button><button class="category-chip">Rabaty</button></div>${employeeProductGrid(8)}</section></div>`}
function employeeWalletView(){return `<div class="employee-dashboard">${pageHead('Portfel i budżety','Wszystkie przyznane środki, programy, terminy ważności i historia operacji.')}<section class="wallet-summary"><div class="wallet-total"><span>Łącznie dostępne</span><b>570,00 zł</b><p>Środki firmowe możesz łączyć zgodnie z zasadami programów.</p></div><div class="wallet-mini"><span>Program Lunch</span><b>220 zł</b><div class="progress" style="margin-top:11px"><span style="width:44%"></span></div></div><div class="wallet-mini"><span>Prezent od firmy</span><b>300 zł</b><div class="progress" style="margin-top:11px"><span style="width:100%"></span></div></div><div class="wallet-mini"><span>Wellbeing</span><b>50 zł</b><div class="progress" style="margin-top:11px"><span style="width:25%"></span></div></div></section><section class="employee-two-col"><div class="employee-section"><div class="employee-section-head"><div><h2>Programy finansowania</h2><p>Źródło środków określa dostępne produkty i zasady dopłaty.</p></div></div><div class="employee-program-grid" style="grid-template-columns:1fr 1fr"><article class="employee-program"><div class="employee-program-top"><div><h3>Program Lunch</h3><p>Środki obrotowe • karta 4831</p></div><span class="status green">Aktywny</span></div><div class="amount">220,00 zł</div><div class="expiry">Ważne do 31.08.2026 • dopłata dozwolona</div></article><article class="employee-program"><div class="employee-program-top"><div><h3>Prezent od firmy</h3><p>Program jednorazowy</p></div><span class="status purple">Nowy</span></div><div class="amount">300,00 zł</div><div class="expiry">Ważne do 31.12.2026 • wybrane kategorie</div></article><article class="employee-program"><div class="employee-program-top"><div><h3>Wellbeing</h3><p>Budżet miesięczny</p></div><span class="status green">Aktywny</span></div><div class="amount">50,00 zł</div><div class="expiry">Odnowienie 01.09.2026</div></article><article class="employee-program"><div class="employee-program-top"><div><h3>ZFŚS — Wypoczynek</h3><p>Świadczenie wnioskowe</p></div><span class="status amber">Wymaga wniosku</span></div><div class="amount">do 1 800 zł</div><div class="expiry">Kwota zależna od progu socjalnego</div></article></div></div><aside class="employee-section"><div class="employee-section-head"><div><h2>Ostatnie operacje</h2><p>Historia wszystkich e-kont.</p></div></div><div class="transaction-list"><div class="transaction"><span class="transaction-icon">🛍️</span><div><b>Empik Gift Card</b><span>Dzisiaj, 18:42 • Program Lunch</span></div><strong class="minus">−100 zł</strong></div><div class="transaction"><span class="transaction-icon">＋</span><div><b>Zasilenie miesięczne</b><span>01.08.2026 • Wellbeing</span></div><strong class="plus">+100 zł</strong></div><div class="transaction"><span class="transaction-icon">🎁</span><div><b>Prezent od pracodawcy</b><span>29.07.2026</span></div><strong class="plus">+300 zł</strong></div></div></aside></section></div>`}
function employeeCardView(){return `<div class="employee-dashboard">${pageHead('E-konto i karta','Saldo programu, karta, transakcje, limity i portfel mobilny.')}<section class="employee-two-col"><div class="employee-card-box" style="min-height:260px"><div class="card-brand">UP BONUS</div><div class="card-program">Program Lunch • karta wirtualna</div><div class="card-number">•••• •••• •••• 4831</div><div class="card-meta"><span>POSIADACZ<b>${esc(state.user.name)}</b></span><span>WAŻNA DO<b>08/29</b></span></div></div><aside class="employee-section"><div class="funds-card-head"><div><span>SALDO E-KONTA</span><b>220,00 zł</b></div><span class="status green">Aktywna</span></div><div class="switch-row"><span><b>Limit dzienny</b><span>500,00 zł</span></span><button class="compact-btn">Zmień</button></div><div class="switch-row"><span><b>PIN</b><span>Ukryty ze względów bezpieczeństwa</span></span><button class="compact-btn" onclick="toast('PIN','Wymagane dodatkowe potwierdzenie.')">Pokaż</button></div><div class="form-grid" style="margin-top:12px"><button class="primary-btn full" onclick="toast('Google Wallet','Karta gotowa do dodania.')">Dodaj do Google Wallet</button><button class="secondary-btn full" onclick="toast('Karta zablokowana tymczasowo')">Zablokuj kartę</button></div></aside></section><section class="employee-section"><div class="employee-section-head"><div><h2>Historia transakcji</h2><p>Operacje kartą i e-kontem w jednym miejscu.</p></div><button class="secondary-btn">Pobierz historię</button></div><div class="transaction-list"><div class="transaction"><span class="transaction-icon">☕</span><div><b>Green Caffè Nero</b><span>04.08.2026, 08:17 • Warszawa</span></div><strong class="minus">−28,50 zł</strong></div><div class="transaction"><span class="transaction-icon">🥗</span><div><b>Lunchroom</b><span>03.08.2026, 13:02 • Warszawa</span></div><strong class="minus">−42,00 zł</strong></div><div class="transaction"><span class="transaction-icon">＋</span><div><b>Zasilenie pracodawcy</b><span>01.08.2026</span></div><strong class="plus">+500,00 zł</strong></div></div></section></div>`}
