function employeeRequestsView(){return `<div class="employee-dashboard">${pageHead('Wnioski i ZFŚS','Złóż wniosek, dołącz dokumenty i śledź decyzję HR.')}<section class="request-grid"><article class="request-card"><span class="request-icon">🏖️</span><h3>Dofinansowanie wypoczynku</h3><p>Świadczenie z ZFŚS zależne od sytuacji socjalnej gospodarstwa domowego.</p><button class="primary-btn" onclick="toast('Nowy wniosek','Otwieram formularz dofinansowania.')">Złóż wniosek</button></article><article class="request-card"><span class="request-icon">🎄</span><h3>Świadczenie świąteczne</h3><p>Wniosek o świadczenie pieniężne lub prezent w ramach programu firmowego.</p><button class="secondary-btn" onclick="toast('Nowy wniosek','Otwieram formularz świadczenia.')">Złóż wniosek</button></article><article class="request-card"><span class="request-icon">🤝</span><h3>Zapomoga</h3><p>Wsparcie w szczególnych sytuacjach życiowych wraz z bezpiecznym załącznikiem.</p><button class="secondary-btn" onclick="toast('Nowy wniosek','Otwieram formularz zapomogi.')">Złóż wniosek</button></article></section><section class="employee-section"><div class="employee-section-head"><div><h2>Twoje wnioski</h2><p>Statusy i wymagane działania.</p></div></div><div class="employee-order-grid"><article class="employee-order"><span class="voucher-logo">🏖️</span><div><h3>Dofinansowanie wypoczynku 2026</h3><p>Wniosek WN-2026-00418 • złożony 01.08.2026</p></div><div class="order-status"><span class="status amber">Uzupełnij załącznik</span><span>Termin: 12.08.2026</span></div></article><article class="employee-order"><span class="voucher-logo">🎒</span><div><h3>Wyprawka szkolna</h3><p>Wniosek WN-2026-00291 • 18.07.2026</p></div><div class="order-status"><span class="status green">Zaakceptowany</span><span>Wypłata 08.08.2026</span></div></article></div></section></div>`}
function employeeWellbeingView(){return `<div class="employee-dashboard">${pageHead('Wellbeing','Wsparcie zdrowia, aktywności, odpoczynku i rozwoju.')}<section class="employee-banner"><div><div class="eyebrow">TWÓJ BUDŻET</div><h3>Masz jeszcze 50 zł do wykorzystania</h3><p>Budżet wellbeing odnowi się 1 września. Możesz dopłacić własnymi środkami do droższej usługi.</p><button class="primary-btn" style="margin-top:13px">Zobacz zasady</button></div><div class="banner-emoji">🌿</div></section><section class="wellbeing-grid"><article class="wellbeing-card"><div class="wellbeing-img">🧘</div><div><h3>Joga i pilates online</h3><p>Miesięczny dostęp do zajęć na żywo i biblioteki nagrań.</p><button class="primary-btn full">Wybierz za 49 zł</button></div></article><article class="wellbeing-card"><div class="wellbeing-img">🧠</div><div><h3>Konsultacja psychologiczna</h3><p>Poufna rozmowa online z wybranym specjalistą.</p><button class="primary-btn full">Wybierz od 50 zł</button></div></article><article class="wellbeing-card"><div class="wellbeing-img">🏃</div><div><h3>Pakiet aktywności</h3><p>Treningi, bieganie i programy wspierające zdrowe nawyki.</p><button class="primary-btn full">Zobacz warianty</button></div></article></section></div>`}
function employeeHelpView(){return `<div class="employee-dashboard">${pageHead('Pomoc','Najczęstsze pytania i bezpieczny kontakt z obsługą.')}<section class="employee-two-col"><div class="employee-section"><div class="employee-section-head"><div><h2>Najczęstsze pytania</h2></div></div><div class="switch-row"><span><b>Jak wykorzystać środki z kilku programów?</b><span>System pokaże dostępne źródła płatności w koszyku.</span></span><button class="compact-btn">Otwórz</button></div><div class="switch-row"><span><b>Gdzie znajdę kupiony voucher?</b><span>W sekcji Zamówienia i vouchery.</span></span><button class="compact-btn">Otwórz</button></div><div class="switch-row"><span><b>Jak złożyć wniosek ZFŚS?</b><span>Wybierz typ świadczenia i uzupełnij formularz.</span></span><button class="compact-btn">Otwórz</button></div></div><aside class="employee-section"><h2 style="font-size:18px;margin-top:0">Potrzebujesz pomocy?</h2><p style="font-size:11px;color:var(--brand-muted);line-height:1.5">Napisz do BOK. Do zgłoszenia automatycznie dołączymy bezpieczny kontekst konta, ale nigdy pełny kod vouchera.</p><button class="primary-btn full" onclick="toast('Zgłoszenie','Formularz kontaktowy został otwarty.')">Napisz do nas</button></aside></section></div>`}

function renderSection(){const role=state.role,sec=state.section;if(role==='employee'&&['Start','Pulpit','Dla Ciebie'].includes(sec)&&typeof window.ub301StartHub==='function')return window.ub301StartHub();if(role==='employee'&&['Portfel i środki','Portfel i budżety','Mój portfel'].includes(sec)&&typeof window.ub301WalletView==='function')return window.ub301WalletView();if(role==='employee'){if(sec==='Dla Ciebie')return employeeDashboard();if(sec==='Sklep i benefity')return employeeBenefitsView();if(sec==='Portfel i budżety')return employeeWalletView();if(sec==='E-konto i karta')return employeeCardView();if(sec==='Odbierz upominek')return giftProgramView();if(sec==='Zamówienia i vouchery')return employeeOrdersView();if(sec==='Wnioski i ZFŚS')return employeeRequestsView();if(sec==='Wellbeing')return employeeWellbeingView();if(sec==='Pomoc')return employeeHelpView();}
 if(sec===ROLE_DEFS[role].menu[0]?.[0])return genericDashboard(role);
 if(sec==='Odbierz upominek')return giftProgramView();
 if(sec==='Klienci i platformy')return clientsView();
 if(sec==='Programy'||sec==='Platformy i programy')return programsView();
 if(sec==='Centrum migracji')return migrationView();
 if(sec==='Branding i domeny'||sec==='Wygląd portalu')return brandingView();
 if(sec==='Moduły ON/OFF')return modulesView();
 if(sec==='Centrum zamówień'||sec==='Zamówienia'||sec==='Zamówienia i vouchery')return ordersView();
 if(sec==='Katalog i oferty'||sec==='Moje produkty'||sec==='Oferty i warianty'||sec==='Kafeteria benefitów')return catalogView();
 if(sec==='Bannery i slajdery')return contentHubView();
 if(sec==='Wyszukiwarka globalna')return globalSearchView();
 if(sec==='Pracownicy i grupy'||sec==='Użytkownicy i role'||sec==='Użytkownicy')return usersView();
 if(sec==='Raporty i audyt'||sec==='Raporty HR'||sec==='Wyniki kampanii')return reportsView();
 return placeholderView(sec);
}

function giftProgramView(){return `${pageHead('Odbierz upominek','Programy prezentowe połączone z budżetem, katalogiem, personalizacją i realizacją.',`<button class="secondary-btn" onclick="showModal('giftHistory')">Historia wyborów</button>`)}<section class="gift-hero"><div><div class="eyebrow" style="color:#e7c6df">PROGRAM PREZENTOWY</div><h2>Wybierz upominek, który naprawdę Ci odpowiada</h2><p>Masz aktywny budżet 450 PLN. Możesz wybrać jeden prezent lub kartę podarunkową i dopłacić środkami własnymi, jeśli program na to pozwala.</p><div class="hero-actions"><button class="primary-btn" onclick="document.getElementById('giftCatalog').scrollIntoView({behavior:'smooth'})">Wybierz upominek</button><button class="secondary-btn" onclick="showModal('giftRules')">Zasady programu</button></div></div><div class="gift-visual"><div class="gift-box">🎁</div></div></section>
 <div class="section-head"><div><h2>Twoje programy</h2><p>Każdy program ma własny budżet, okres wyboru i katalog.</p></div></div><section class="program-grid">${SAMPLE_PROGRAMS.filter(x=>x.type==='Program prezentowy'||x.type==='Odbierz upominek').map(p=>`<article class="program-card"><div class="program-card-head"><div><h3>${esc(p.name)}</h3><p>${esc(p.client)} • ${esc(p.type)}</p></div><span class="status green">Aktywny</span></div><div class="progress"><span style="width:${p.progress}%"></span></div><div class="program-meta"><span>Budżet: ${esc(p.budget)}</span><span>do 31.12.2026</span></div><button class="primary-btn full" onclick="toast('Program wybrany','Katalog został przefiltrowany.')">Przejdź do wyboru</button></article>`).join('')}</section>
 <div class="section-head" id="giftCatalog"><div><h2>Katalog upominków</h2><p>Produkty widoczne zgodnie z konfiguracją programu, grupy i dostępności magazynu.</p></div><div class="right"><button class="secondary-btn" onclick="openModule('gift')">Otwórz pełny sklep Gifts</button></div></div><section class="gift-catalog">${[['Karta Allegro 300 PLN','Uniwersalny prezent cyfrowy.','300 PLN','🛒'],['Weekend SPA','Voucher na pobyt dla 2 osób.','450 PLN','🏨'],['Zestaw premium','Personalizowany zestaw prezentowy.','349 PLN','🎀'],['Karta Decathlon 400 PLN','Sport i aktywny wypoczynek.','400 PLN','🚴'],['Subskrypcja kultury','Kino, audiobooki i prasa.','199 PLN','🎬'],['Karta IKEA 450 PLN','Dom i wyposażenie.','450 PLN','🏠']].map(g=>`<article class="gift-item"><div class="gift-img">${g[3]}</div><div class="gift-info"><h3>${g[0]}</h3><p>${g[1]}</p><div class="gift-price"><b>${g[2]}</b><button onclick="showModal('giftConfirm',{name:'${g[0]}',price:'${g[2]}'})">Wybieram</button></div></div></article>`).join('')}</section>`}

function clientsView(){const q=(state.filters.client||'').toLowerCase();const rows=SAMPLE_CLIENTS.filter(x=>(x.name+x.nip+x.id).toLowerCase().includes(q));return `${pageHead('Klienci i platformy','Centralny rejestr tenantów, organizacji, platform, programów i brandingu.',`<button class="secondary-btn" onclick="showModal('importClient')">${icon('upload')} Import</button><button class="primary-btn" onclick="showModal('newClient')">${icon('plus')} Nowy klient</button>`)}
 <div class="toolbar"><div class="search"><span>${ICONS.search}</span><input placeholder="Nazwa, NIP lub ID klienta…" value="${esc(state.filters.client)}" oninput="state.filters.client=this.value;render()" /></div><select><option>Wszystkie statusy</option><option>Aktywny</option><option>Migracja</option><option>Pilot</option></select><select><option>Każdy model</option><option>Up Bonus</option><option>Co-branding</option><option>White-label</option></select><span class="spacer"></span><button class="compact-btn">${icon('filter')} Kolumny</button><button class="compact-btn">${icon('download')} Eksport</button></div>
 <div class="table-wrap"><table class="data-table"><thead><tr><th><input class="checkbox" type="checkbox" /></th><th>Klient ↕</th><th>ID / NIP</th><th>Platformy</th><th>Programy</th><th>Użytkownicy</th><th>Model</th><th>Status</th><th>Opiekun</th><th style="text-align:right">Akcje</th></tr></thead><tbody>${rows.map(c=>`<tr><td><input class="checkbox" type="checkbox" /></td><td><span class="td-title">${esc(c.name)}</span><span class="td-sub">Tenant główny</span></td><td>${esc(c.id)}<span class="td-sub">${esc(c.nip)}</span></td><td>${c.platforms}</td><td>${c.programs}</td><td>${Number(c.users).toLocaleString('pl-PL')}</td><td>${esc(c.mode)}</td><td><span class="status ${c.status==='Aktywny'?'green':c.status==='Migracja'?'amber':'purple'}">${esc(c.status)}</span></td><td>${esc(c.owner)}</td><td><div class="table-actions"><button onclick="showDrawer('client',{id:'${c.id}'})">Szczegóły</button><button onclick="showModal('editClient',{id:'${c.id}'})">Edytuj</button></div></td></tr>`).join('')}</tbody></table></div><div class="pagination"><span>Wyświetlono ${rows.length} z ${SAMPLE_CLIENTS.length} klientów</span><div class="pagination-buttons"><button>‹</button><button class="active">1</button><button>2</button><button>›</button></div></div>`}

function programsView(){return `${pageHead('Platformy i programy','Program łączy platformę, grupę użytkowników, finansowanie, katalog i reguły realizacji.',`<button class="primary-btn" onclick="showModal('newProgram')">${icon('plus')} Nowy program</button>`)}<div class="toolbar"><div class="search"><span>${ICONS.search}</span><input placeholder="Szukaj programu, klienta lub ID…" /></div><select><option>Wszystkie typy</option><option>ZFŚS</option><option>Prezentowy</option><option>Rabatowy</option><option>Budżet cykliczny</option></select><select><option>Wszystkie platformy</option></select><span class="spacer"></span><button class="compact-btn">${icon('download')} Eksport</button></div><div class="table-wrap"><table class="data-table"><thead><tr><th>ID</th><th>Program ↕</th><th>Klient / platforma</th><th>Typ</th><th>Budżet</th><th>Użytkownicy</th><th>Realizacja</th><th>Status</th><th style="text-align:right">Akcje</th></tr></thead><tbody>${SAMPLE_PROGRAMS.map(p=>`<tr><td>${p.id}</td><td><span class="td-title">${esc(p.name)}</span><span class="td-sub">Okres: 01.01–31.12.2026</span></td><td>${esc(p.client)}<span class="td-sub">Portal pracownika</span></td><td>${esc(p.type)}</td><td>${esc(p.budget)}</td><td>${p.users.toLocaleString('pl-PL')}</td><td><div class="progress" style="width:100px"><span style="width:${p.progress}%"></span></div><span class="td-sub">${p.progress}%</span></td><td><span class="status ${p.active?'green':'gray'}">${p.active?'Aktywny':'Wyłączony'}</span></td><td><div class="table-actions"><button onclick="showDrawer('program',{id:'${p.id}'})">Szczegóły</button><button onclick="showModal('newProgram',{id:'${p.id}'})">Edytuj</button></div></td></tr>`).join('')}</tbody></table></div>`}

function migrationView(){return `${pageHead('Centrum migracji','Przenosimy dane i zależności, nie stare ekrany 1:1.',`<button class="secondary-btn" onclick="showModal('migrationRules')">Macierz migracyjna</button><button class="primary-btn" onclick="toast('Migracja próbna uruchomiona','Wyniki pojawią się w kolejce zadań.')">${icon('refresh')} Uruchom próbę</button>`)}<section class="stat-grid">${stat('Rekordy źródłowe','7,01 mln','database')}${stat('Zmapowane','6,98 mln','check','99,5%')}${stat('Wymaga decyzji','25 586','alert')}${stat('Ostatnia próba','Dzisiaj 20:45','calendar')}</section><div class="panel" style="margin-bottom:13px"><div class="panel-head"><h2>Przepływ migracji OB 2.0</h2><span class="status amber">Etap 2 z 6</span></div><div class="panel-body"><div class="quick-grid">${[['1. Inwentaryzacja','Gotowe','check'],['2. Mapowanie','W toku','refresh'],['3. Import próbny','Oczekuje','database'],['4. Walidacja','Oczekuje','shield'],['5. Delta i DNS','Oczekuje','globe'],['6. Odbiór','Oczekuje','check']].map(x=>`<div class="quick"><span class="role-icon" style="width:56px;height:56px;margin:0 0 10px;font-size:26px;border-radius:16px">${ICONS[x[2]]}</span><b>${x[0]}</b><span>${x[1]}</span></div>`).join('')}</div></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Źródło OB 2.0</th><th>Nowy obiekt</th><th>Rekordy</th><th>Zmapowane</th><th>Błędy / decyzje</th><th>Postęp</th><th>Status</th><th style="text-align:right">Akcje</th></tr></thead><tbody>${MIGRATION_ROWS.map(m=>{const pct=Math.round(parseInt(m.mapped.replace(/\s/g,''))/parseInt(m.records.replace(/\s/g,''))*100);return `<tr><td><span class="td-title">${m.source}</span></td><td>${m.target}</td><td>${m.records}</td><td>${m.mapped}</td><td>${m.errors}</td><td><div class="progress" style="width:110px"><span style="width:${pct}%"></span></div><span class="td-sub">${pct}%</span></td><td><span class="status ${m.status==='Gotowe'?'green':m.status==='Weryfikacja'?'amber':'purple'}">${m.status}</span></td><td><div class="table-actions"><button onclick="showDrawer('migration',{source:'${m.source}'})">Mapowanie</button><button>Raport</button></div></td></tr>`}).join('')}</tbody></table></div>`}

function brandingView(){const t=tenant();return `${pageHead('Branding i domeny','Personalizacja jest konfiguracją platformy, a nie osobnym kodem klienta.',`<button class="secondary-btn" onclick="toast('Podgląd odświeżony')">Podgląd</button><button class="primary-btn" onclick="saveBranding()">Zapisz konfigurację</button>`)}<div class="dashboard-grid"><div class="form-card"><div class="section-head" style="margin:0 0 14px"><div><h2>Identyfikacja platformy</h2><p>Zmiany zastosują się od logowania i pozostaną aktywne w Centrum Kont.</p></div></div><div class="form-columns"><div class="field"><label>Nazwa platformy</label><input id="brandName" value="${esc(t.name)}" /></div><div class="field"><label>Domena</label><input id="brandDomain" value="${esc(t.domain)}" /></div><div class="field"><label>Kolor główny</label><input id="brandPrimary" type="color" value="${esc(t.primary)}" style="padding:5px" /></div><div class="field"><label>Kolor akcentu</label><input id="brandAccent" type="color" value="${esc(t.accent)}" style="padding:5px" /></div><div class="field"><label>Tryb brandingu</label><select id="brandMode"><option>up_bonus</option><option ${t.mode==='co_branded'?'selected':''}>co_branded</option><option ${t.mode==='white_label'?'selected':''}>white_label</option></select></div><div class="field"><label>Symbol / skrót logo</label><input id="brandLogo" value="${esc(t.logo)}" maxlength="4" /></div></div><div class="field" style="margin-top:14px"><label>Tekst hero</label><textarea id="brandHero">${esc(t.hero)}</textarea></div><div class="switch-row"><span><b>Logo jasne i ciemne</b><span>Automatyczny wariant zależny od tła.</span></span><button class="toggle on" onclick="toggleButton(this)"></button></div><div class="switch-row"><span><b>Własne e-maile systemowe</b><span>Nadawca, stopka i szablony platformy.</span></span><button class="toggle on" onclick="toggleButton(this)"></button></div><div class="switch-row"><span><b>Pełny white-label</b><span>Ukryj oznaczenia Up Bonus w interfejsie klienta.</span></span><button class="toggle ${t.mode==='white_label'?'on':''}" onclick="toggleButton(this)"></button></div></div><aside class="panel"><div class="panel-head"><h3>Podgląd logowania</h3><span class="status purple">Desktop / mobile</span></div><div class="panel-body"><div style="background:linear-gradient(145deg,${t.primary},#241220);border-radius:17px;padding:22px;color:#fff;min-height:280px;display:flex;flex-direction:column;justify-content:space-between"><div class="brand-mark"><span class="brand-symbol">${esc(t.logo)}</span><span>${esc(t.name)}</span></div><div><div class="eyebrow" style="color:#ead7e7">PLATFORMA BENEFITOWA</div><h2 style="font-size:27px;margin:8px 0">${esc(t.hero)}</h2><p style="font-size:12px;color:rgba(255,255,255,.76)">${esc(t.description)}</p></div><div style="font-size:10px;color:rgba(255,255,255,.6)">${esc(t.domain)}</div></div></div></aside></div>`}
function saveBranding(){const cur=state.customTenants[state.tenant]||{};state.customTenants[state.tenant]={...cur,name:el('brandName').value,domain:el('brandDomain').value,primary:el('brandPrimary').value,accent:el('brandAccent').value,mode:el('brandMode').value,logo:el('brandLogo').value,hero:el('brandHero').value,soft:cur.soft||tenant().soft};applyTheme();persist();render();toast('Branding zapisany','Konfiguracja jest aktywna w logowaniu i Centrum Kont.')}

function modulesView(){const t=tenant();return `${pageHead('Moduły ON/OFF','Moduły są aktywowane osobno dla każdego klienta i platformy.',`<button class="primary-btn" onclick="persist();toast('Konfiguracja modułów zapisana')">Zapisz zmiany</button>`)}<div class="panel"><div class="panel-head"><h2>${esc(t.name)}</h2><span class="status green">${t.modules.length} aktywnych</span></div><div class="panel-body">${Object.entries(ROLE_DEFS).map(([id,r])=>`<div class="switch-row"><span><b>${ICONS[r.icon]} ${esc(r.name)}</b><span>${esc(r.desc)}</span></span><button class="toggle ${t.modules.includes(id)?'on':''}" onclick="toggleModule('${id}',this)"></button></div>`).join('')}</div></div>`}
function toggleModule(id,btn){const cur={...tenant()};let mods=[...cur.modules];mods=mods.includes(id)?mods.filter(x=>x!==id):[...mods,id];state.customTenants[state.tenant]={...(state.customTenants[state.tenant]||{}),modules:mods};btn.classList.toggle('on');persist()}

function ordersView(){return `${pageHead('Centrum zamówień','Jedna lista łączy klienta, płatność, rezerwację kodu, dostawę, reklamację i rozliczenie.',`<button class="secondary-btn" onclick="toast('Eksport przygotowany')">${icon('download')} Eksport</button><button class="primary-btn" onclick="showModal('newOrder')">${icon('plus')} Nowe zamówienie</button>`)}<div class="toolbar"><div class="search"><span>${ICONS.search}</span><input placeholder="ID, odbiorca, produkt, klient…" /></div><select><option>Wszystkie statusy</option><option>Błąd</option><option>Rezerwacja</option><option>Wydane</option></select><select><option>Każdy klient</option><option>Erste Bank</option><option>Open Benefit</option></select><span class="spacer"></span><button class="compact-btn">${icon('filter')} Filtry</button></div><div class="table-wrap"><table class="data-table"><thead><tr><th><input class="checkbox" type="checkbox" /></th><th>Zamówienie ↕</th><th>Klient / odbiorca</th><th>Produkt</th><th>Wartość</th><th>Finansowanie</th><th>Realizacja</th><th>Dostawa</th><th>SLA</th><th style="text-align:right">Akcje</th></tr></thead><tbody>${SAMPLE_ORDERS.map(o=>`<tr><td><input class="checkbox" type="checkbox" /></td><td><span class="td-title">${o.id}</span><span class="td-sub">04.08.2026 20:48</span></td><td>${o.client}<span class="td-sub">${o.recipient}</span></td><td>${o.product}</td><td>${o.value}</td><td>${o.payment}</td><td><span class="status ${o.status==='Błąd'?'red':o.status==='Rezerwacja'?'amber':'green'}">${o.status}</span></td><td>${o.delivery}</td><td><span class="status ${o.sla==='Przekroczone'?'red':o.sla==='OK'?'green':'amber'}">${o.sla}</span></td><td><div class="table-actions"><button onclick="showDrawer('order',{id:'${o.id}'})">Szczegóły</button><button>Akcje</button></div></td></tr>`).join('')}</tbody></table></div>`}

function catalogView(){const products=[['Allegro Gift Card','Karta podarunkowa','50–500 PLN','Amilon','Aktywny'],['Empik Gift Card','Karta podarunkowa','50–300 PLN','Empik','Aktywny'],['Frisco darmowa dostawa','Oferta z kodem','50–200 PLN','Frisco','Aktywny'],['Cocolita 20%','Rabat','Kod statyczny','Cocolita','Aktywny'],['Super Prezenty','Voucher usługowy','100–1000 PLN','Super Prezenty','Roboczy'],['Multikino VIP','Bilet / voucher','35–80 PLN','Multikino','Aktywny']];return `${pageHead('Katalog produktów i ofert','Jeden katalog dla kart, voucherów, rabatów, abonamentów i produktów fizycznych.',`<button class="primary-btn" onclick="showModal('newProduct')">${icon('plus')} Dodaj produkt</button>`)}<div class="toolbar"><div class="search"><span>${ICONS.search}</span><input placeholder="Produkt, partner, ID oferty…" /></div><select><option>Wszystkie typy</option><option>Karta podarunkowa</option><option>Rabat</option><option>Abonament</option></select><select><option>Wszystkie kanały</option><option>Sklep</option><option>Kafeteria</option><option>HR</option></select><span class="spacer"></span><button class="compact-btn">Zaznacz wszystkie</button><button class="compact-btn">Akcje grupowe</button></div><div class="table-wrap"><table class="data-table"><thead><tr><th><input class="checkbox" type="checkbox" /></th><th>Produkt ↕</th><th>Typ</th><th>Warianty</th><th>Partner</th><th>Sklep</th><th>Kafeteria</th><th>HR</th><th>Status</th><th style="text-align:right">Akcje</th></tr></thead><tbody>${products.map((p,i)=>`<tr><td><input class="checkbox" type="checkbox" /></td><td><span class="td-title">${p[0]}</span><span class="td-sub">PRD-${String(70070+i)}</span></td><td>${p[1]}</td><td>${p[2]}</td><td>${p[3]}</td><td><button class="toggle ${i!==4?'on':''}" onclick="toggleButton(this)"></button></td><td><button class="toggle on" onclick="toggleButton(this)"></button></td><td><button class="toggle ${i%2?'':'on'}" onclick="toggleButton(this)"></button></td><td><span class="status ${p[4]==='Aktywny'?'green':'gray'}">${p[4]}</span></td><td><div class="table-actions"><button onclick="showDrawer('product',{name:'${p[0]}'})">Szczegóły</button><button>Edytuj</button></div></td></tr>`).join('')}</tbody></table></div>`}

function contentHubView(){const rows=[['BTS 2026 — główny slider','Hero','Desktop + mobile','17.08–13.09.2026','Wszyscy','Aktywny'],['AscoFlex Control','Banner klienta','Desktop + mobile','01.08–31.12.2026','Erste B2C','Aktywny'],['Multikino — Katalog Marzeń','Banner kategorii','Desktop + mobile','29.05–30.06.2026','Program prezentowy','Zakończony'],['Frisco darmowa dostawa','Oferta','Desktop + mobile','26.05–30.06.2026','Up Bonus Gifts','Roboczy']];return `${pageHead('Content Hub','Slajdery, bannery, hero, komunikaty i publikacje dla wielu platform.',`<button class="primary-btn" onclick="showModal('newContent')">${icon('plus')} Nowa publikacja</button>`)}<div class="toolbar"><div class="search"><span>${ICONS.search}</span><input placeholder="Nazwa publikacji…" /></div><select><option>Wszystkie typy</option></select><select><option>Wszystkie platformy</option></select><select><option>Wszystkie statusy</option></select><span class="spacer"></span><button class="compact-btn">Kalendarz</button></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Publikacja ↕</th><th>Typ</th><th>Materiały</th><th>Okres</th><th>Segment</th><th>Priorytet</th><th>Status</th><th style="text-align:right">Akcje</th></tr></thead><tbody>${rows.map((r,i)=>`<tr><td><span class="td-title">${r[0]}</span><span class="td-sub">CNT-${394-i}</span></td><td>${r[1]}</td><td>${r[2]}</td><td>${r[3]}</td><td>${r[4]}</td><td>${7000+i*100}</td><td><span class="status ${r[5]==='Aktywny'?'green':r[5]==='Roboczy'?'purple':'gray'}">${r[5]}</span></td><td><div class="table-actions"><button onclick="showDrawer('content',{name:'${r[0]}'})">Podgląd</button><button>Edytuj</button></div></td></tr>`).join('')}</tbody></table></div>`}

function globalSearchView(){return `${pageHead('Wyszukiwarka globalna','Jedno wyszukiwanie po kliencie, użytkowniku, kodzie, zamówieniu, reklamacji i referencji.',``)}<div class="form-card"><div class="field"><label>Wpisz identyfikator lub dane</label><div style="display:flex;gap:8px"><input id="globalQ" placeholder="np. ORD-2026-08192, voucher_id, e-mail, końcówka kodu…" /><button class="primary-btn" onclick="renderSearchResults()">Szukaj</button></div><div class="help">Pełny kod i PIN pozostają zamaskowane. Ujawnienie wymaga uprawnienia, powodu i zapisu w audycie.</div></div></div><div id="searchResults" style="margin-top:13px">${searchResultsHtml()}</div>`}
function renderSearchResults(){const c=el('searchResults');if(c)c.innerHTML=searchResultsHtml(true)}
function searchResultsHtml(show=false){if(!show)return `<div class="panel"><div class="panel-body" style="text-align:center;padding:46px;color:var(--brand-muted)">${icon('search')}<h3 style="margin:10px 0 5px;color:var(--brand-text)">Wyszukaj rekord w całym ekosystemie</h3><span style="font-size:12px">Wyniki pokażą połączony kontekst zamiast osobnych ekranów.</span></div></div>`;return `<div class="dashboard-grid"><div class="panel"><div class="panel-head"><h2>Znaleziono zamówienie</h2><span class="status green">ORD-2026-08192</span></div><div class="panel-body"><ul class="list-clean"><li class="list-item"><span class="context-icon">${ICONS.order}</span><span class="list-item-main"><b>Allegro Gift Card 200 PLN</b><span>Erste Bank • Anna Kowalska</span></span><span class="status green">Dostarczone</span></li><li class="list-item"><span class="context-icon">${ICONS.code}</span><span class="list-item-main"><b>Voucher: VCH-802191</b><span>Kod: AL••••••92 • paczka AMILON-0804</span></span><button class="compact-btn" onclick="showModal('revealCode')">Ujawnij</button></li><li class="list-item"><span class="context-icon">${ICONS.mail}</span><span class="list-item-main"><b>Dostawa e-mail</b><span>Wysłano i otwarto 04.08.2026</span></span><button class="compact-btn" onclick="toast('Wysłano ponownie')">Wyślij ponownie</button></li></ul></div></div><aside class="panel"><div class="panel-head"><h3>Powiązania</h3></div><div class="panel-body"><div class="context-line"><span class="context-icon">${ICONS.building}</span><span><b>Erste Bank</b><span>Klient / platforma</span></span></div><div class="context-line"><span class="context-icon">${ICONS.database}</span><span><b>AMILON-0804</b><span>Paczka kodów</span></span></div><div class="context-line"><span class="context-icon">${ICONS.finance}</span><span><b>SET-2026-441</b><span>Rozliczenie</span></span></div></div></aside></div>`}

function usersView(){const users=[['Małgorzata','Bartkiewicz','malgorzata.bartkiewicz@upbonus.pl','Super Admin','Up Bonus','Aktywny'],['Katarzyna','Drzewiecka','katarzyna.drzewiecka@upbonus.pl','Operacje','Open Benefit','Aktywny'],['Piotr','Serafin','piotr.serafin@upbonus.pl','Finanse','Wiele platform','Aktywny'],['Anna','Kowalska','anna.kowalska@erste.pl','HR','Erste Bank','Aktywny'],['Patryk','Błoński','patryk.blonski@sharp.eu','Partner','Sharp Business Systems','Aktywny']];return `${pageHead(state.section,'Konta, członkostwa, role i dostępy do platform.',`<button class="primary-btn" onclick="showModal('newUser')">${icon('plus')} Dodaj użytkownika</button>`)}<div class="toolbar"><div class="search"><span>${ICONS.search}</span><input placeholder="Imię, nazwisko, e-mail…" /></div><select><option>Wszystkie role</option></select><select><option>Wszystkie platformy</option></select><span class="spacer"></span><button class="compact-btn">Import pracowników</button></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Użytkownik ↕</th><th>E-mail</th><th>Rola</th><th>Klient / platforma</th><th>2FA</th><th>Status</th><th>Ostatnie logowanie</th><th style="text-align:right">Akcje</th></tr></thead><tbody>${users.map(u=>`<tr><td><span class="td-title">${u[0]} ${u[1]}</span></td><td>${u[2]}</td><td>${u[3]}</td><td>${u[4]}</td><td><span class="status green">Włączone</span></td><td><span class="status green">${u[5]}</span></td><td>Dzisiaj 20:34</td><td><div class="table-actions"><button onclick="showDrawer('user',{email:'${u[2]}'})">Szczegóły</button><button>Reset hasła</button></div></td></tr>`).join('')}</tbody></table></div>`}

function reportsView(){const cards=[['Sprzedaż i zamówienia','Obrót, pozycje, statusy i kanały.','order'],['Kody i zapasy','Stany, ważność, wydania i rozbieżności.','database'],['Użytkownicy','Aktywność, logowania i wykorzystanie.','people'],['Programy i budżety','Zasilenia, wykorzystanie i salda.','wallet'],['Partnerzy','Sprzedaż, SLA, reklamacje i rozliczenia.','partner'],['Finanse','Faktury, marże, korekty i ERP.','finance'],['Reklamacje','Typy problemów, wymiany i czas obsługi.','support'],['Audyt','Ujawnienia kodów, zmiany i bezpieczeństwo.','audit']];return `${pageHead('Centrum raportów','Jeden katalog raportów z zapisanymi filtrami, historią i harmonogramami.',`<button class="secondary-btn">Historia eksportów</button><button class="primary-btn" onclick="showModal('scheduleReport')">Zaplanuj raport</button>`)}<section class="role-grid">${cards.map(c=>`<button class="role-card" onclick="showModal('reportBuilder',{name:'${c[0]}'})"><span class="role-icon">${ICONS[c[2]]}</span><h3>${c[0]}</h3><p>${c[1]}</p><div class="role-card-footer"><span class="role-meta">CSV • XLSX • PDF</span><span class="arrow-circle">${ICONS.chevron}</span></div></button>`).join('')}</section>`}

function placeholderView(sec){return `${pageHead(sec,'Moduł jest włączony w zintegrowanej nawigacji i gotowy do dalszego rozwinięcia.',`<button class="primary-btn" onclick="toast('Akcja demonstracyjna','Proces został zapisany lokalnie.')">${icon('plus')} Nowa operacja</button>`)}<div class="panel"><div class="panel-body" style="padding:36px;text-align:center"><span class="role-icon" style="margin:0 auto 12px;width:56px;height:56px;font-size:27px">${ICONS.layers}</span><h2 style="margin:0 0 8px">${esc(sec)}</h2><p style="max-width:620px;margin:0 auto;color:var(--brand-muted);line-height:1.55;font-size:13px">Ten widok korzysta już ze wspólnego kontekstu klienta, platformy, programu i roli. Następny etap to podpięcie konkretnego procesu oraz danych backendowych.</p><div class="quick-grid" style="margin-top:24px;text-align:left"><div class="quick"><b>Wspólna tabela</b><span>Filtry, sortowanie w nagłówkach, zaznaczanie masowe i zapisane widoki.</span></div><div class="quick"><b>Panel szczegółów</b><span>Zakładki, audyt i powiązane rekordy bez przechodzenia przez wiele ekranów.</span></div><div class="quick"><b>Multi-tenant</b><span>Każda operacja dziedziczy tenant_id, portal_id i uprawnienia użytkownika.</span></div></div></div></div>`}

function openModule(kind){const title=kind==='gift'?'Up Bonus Gifts — sklep personalizowany':'Magazyn kart i kodów';const data=kind==='gift'?EMBEDDED_GIFT:EMBEDDED_INVENTORY;const shell=document.createElement('div');shell.className='module-shell';shell.id='moduleShell';shell.innerHTML=`<div class="module-bar"><button class="secondary-btn" style="min-height:38px;padding:7px 12px" onclick="closeModule()">${icon('back')} Centrum Kont</button><div><b>${title}</b><span>Moduł osadzony w zintegrowanym ekosystemie v2</span></div><span class="spacer"></span><button class="compact-btn" onclick="document.getElementById('moduleFrame').contentWindow.location.reload()">${icon('refresh')} Odśwież</button><button class="compact-btn" onclick="openModuleNewTab('${kind}')">Otwórz osobno</button></div><div class="loading" id="moduleLoading"><div><div class="spinner"></div>Ładowanie modułu…</div></div><iframe id="moduleFrame" class="module-frame hidden" title="${title}"></iframe>`;document.body.appendChild(shell);setTimeout(()=>{const f=el('moduleFrame');f.srcdoc=decodeB64(data);f.onload=()=>{el('moduleLoading')?.classList.add('hidden');f.classList.remove('hidden')};},20)}
function closeModule(){el('moduleShell')?.remove()}
function openModuleNewTab(kind){const data=kind==='gift'?EMBEDDED_GIFT:EMBEDDED_INVENTORY;const blob=new Blob([decodeB64(data)],{type:'text/html;charset=utf-8'});window.open(URL.createObjectURL(blob),'_blank')}

function modalHtml(){if(!state.modal)return '';const {type,data}=state.modal;let title='';let body='';let size='';let foot=`<button class="secondary-btn" onclick="closeModal()">Anuluj</button><button class="primary-btn" onclick="saveDemo()">Zapisz</button>`;
 if(type==='tenantSwitch'){title='Przełącz platformę';size='small';body=`<div class="form-grid">${Object.values(DEFAULT_TENANTS).map(t=>`<button class="portal-option ${t.id===state.tenant?'active':''}" onclick="setTenant('${t.id}');closeModal()"><b>${esc(t.name)}</b><span>${esc(t.domain)} • ${esc(t.mode)}</span></button>`).join('')}</div>`;foot=`<button class="secondary-btn" onclick="closeModal()">Zamknij</button>`}
 else if(type==='notifications'){title='Powiadomienia';size='small';body=state.role==='employee'?`<ul class="list-clean"><li class="list-item"><span class="status purple">Nowe</span><span class="list-item-main"><b>Przyznano prezent od firmy</b><span>Masz 300 zł do wykorzystania do 31.12.2026</span></span></li><li class="list-item"><span class="status amber">Ważne</span><span class="list-item-main"><b>Uzupełnij załącznik do wniosku</b><span>Termin: 12 sierpnia</span></span></li><li class="list-item"><span class="status green">Gotowe</span><span class="list-item-main"><b>Voucher Allegro jest dostępny</b><span>Możesz go otworzyć w Zamówieniach i voucherach</span></span></li></ul>`:`<ul class="list-clean"><li class="list-item"><span class="status red">Pilne</span><span class="list-item-main"><b>3 błędy integracji</b><span>Wymagają sprawdzenia przez Operacje</span></span></li><li class="list-item"><span class="status amber">7</span><span class="list-item-main"><b>Paczki kodów do akceptacji</b><span>Zasada dwóch par oczu</span></span></li><li class="list-item"><span class="status purple">Nowe</span><span class="list-item-main"><b>Import migracyjny zakończony</b><span>Raport jest gotowy</span></span></li></ul>`;foot=`<button class="secondary-btn" onclick="state.notifications=0;closeModal();render()">Oznacz jako przeczytane</button>`}
 else if(type==='profile'){title='Profil użytkownika';size='small';body=`<div style="display:flex;gap:14px;align-items:center;margin-bottom:16px"><span class="avatar" style="width:54px;height:54px;border-radius:17px">MB</span><span><b>${esc(state.user.name)}</b><span style="display:block;color:var(--brand-muted);font-size:12px;margin-top:3px">${esc(state.user.email)}</span></span></div><div class="switch-row"><span><b>Uwierzytelnianie 2FA</b><span>Aktywne dla konta</span></span><span class="status green">Włączone</span></div><div class="switch-row"><span><b>Język</b><span>Polski</span></span><button class="compact-btn">Zmień</button></div>`;foot=`<button class="danger-btn" onclick="logout();closeModal()">Wyloguj</button><button class="secondary-btn" onclick="closeModal()">Zamknij</button>`}
 else if(type==='giftConfirm'){title='Potwierdź wybór';size='small';body=`<div style="text-align:center;padding:8px"><div class="gift-box" style="margin:0 auto 18px;transform:none;background:var(--brand-soft)">🎁</div><h2 style="font-size:20px;margin:0">${esc(data.name)}</h2><p style="color:var(--brand-muted);font-size:12px">Wartość: ${esc(data.price)}. Po potwierdzeniu wybór trafi do realizacji.</p></div>`;foot=`<button class="secondary-btn" onclick="closeModal()">Wróć</button><button class="primary-btn" onclick="saveDemo('Upominek został wybrany')">Potwierdzam wybór</button>`}
 else if(type==='revealCode'){title='Ujawnienie kodu';size='small';body=`<div class="field"><label>Powód ujawnienia</label><select><option>Obsługa reklamacji</option><option>Ponowna wysyłka</option><option>Weryfikacja techniczna</option></select></div><div class="field" style="margin-top:12px"><label>Numer zgłoszenia</label><input placeholder="np. CMP-2026-1442" /></div><div class="demo-note">Ujawnienie zostanie zapisane w audycie wraz z użytkownikiem, czasem i powodem.</div>`;foot=`<button class="secondary-btn" onclick="closeModal()">Anuluj</button><button class="danger-btn" onclick="saveDemo('Kod ujawniony i zapisany w audycie')">Ujawnij kod</button>`}
 else if(type==='newClient'||type==='editClient'){title=type==='newClient'?'Nowy klient':'Edycja klienta';body=`<div class="form-columns"><div class="field"><label>Nazwa klienta *</label><input value="${type==='editClient'?'Erste Bank':''}" /></div><div class="field"><label>NIP *</label><input /></div><div class="field"><label>Model brandingu</label><select><option>Up Bonus</option><option>Co-branding</option><option>White-label</option></select></div><div class="field"><label>Waluta</label><select><option>PLN</option><option>EUR</option></select></div><div class="field"><label>Opiekun handlowy</label><input /></div><div class="field"><label>Opiekun operacyjny</label><input /></div></div>`}
 else if(type==='newProgram'){title=data.id?'Edycja programu':'Nowy program';body=`<div class="form-columns"><div class="field"><label>Nazwa programu *</label><input /></div><div class="field"><label>Typ programu *</label><select><option>Program prezentowy</option><option>ZFŚS</option><option>Program rabatowy</option><option>Budżet cykliczny</option></select></div><div class="field"><label>Klient i platforma *</label><select><option>Up Bonus — Portal pracownika</option><option>Erste Benefits</option></select></div><div class="field"><label>Źródło finansowania</label><select><option>Środki obrotowe</option><option>ZFŚS</option><option>Budżet managera</option></select></div><div class="field"><label>Budżet na użytkownika</label><input placeholder="450,00" /></div><div class="field"><label>Dopłata własna</label><select><option>Dozwolona</option><option>Niedozwolona</option></select></div></div>`}
 else if(type==='newUser'){title='Dodaj użytkownika';body=`<div class="form-columns"><div class="field"><label>Imię</label><input /></div><div class="field"><label>Nazwisko</label><input /></div><div class="field"><label>E-mail</label><input type="email" /></div><div class="field"><label>Rola</label><select>${Object.values(ROLE_DEFS).map(r=>`<option>${r.name}</option>`).join('')}</select></div><div class="field"><label>Klient / platforma</label><select><option>Up Bonus</option><option>Erste Benefits</option><option>Open Benefit</option></select></div><div class="field"><label>Logowanie</label><select><option>Hasło + 2FA</option><option>SSO</option></select></div></div>`}
 else if(type==='newOrder'){title='Nowe zamówienie operacyjne';body=`<div class="form-columns"><div class="field"><label>Klient / platforma</label><select><option>Up Bonus</option><option>Erste Bank</option></select></div><div class="field"><label>Program</label><select><option>Prezenty świąteczne 2026</option></select></div><div class="field"><label>Produkt / wariant</label><input placeholder="Wyszukaj produkt…" /></div><div class="field"><label>Liczba</label><input type="number" value="1" /></div><div class="field"><label>Odbiorca</label><input /></div><div class="field"><label>E-mail odbiorcy</label><input type="email" /></div></div>`}
 else if(type==='newProduct'){title='Nowy produkt i oferta';size='large';body=`<div class="form-columns three"><div class="field"><label>Nazwa produktu</label><input /></div><div class="field"><label>Partner</label><select><option>Amilon</option><option>Empik</option></select></div><div class="field"><label>Typ produktu</label><select><option>Karta podarunkowa</option><option>Rabat</option><option>Voucher</option></select></div><div class="field"><label>Warianty / nominały</label><input placeholder="50, 100, 200, 500" /></div><div class="field"><label>Sposób realizacji</label><select><option>Magazyn kodów</option><option>API partnera</option><option>Kod statyczny</option></select></div><div class="field"><label>Zakres magazynu</label><select><option>shared</option><option>tenant_dedicated</option><option>platform_dedicated</option></select></div></div>`}
 else if(type==='reportBuilder'){title=`Raport: ${data.name}`;body=`<div class="form-columns"><div class="field"><label>Data od</label><input type="date" value="2026-08-01" /></div><div class="field"><label>Data do</label><input type="date" value="2026-08-04" /></div><div class="field"><label>Klient</label><select><option>Wszyscy</option><option>Erste Bank</option></select></div><div class="field"><label>Platforma / program</label><select><option>Wszystkie</option></select></div><div class="field"><label>Format</label><select><option>XLSX</option><option>CSV</option><option>PDF</option></select></div><div class="field"><label>Zapisany widok</label><select><option>Domyślny</option></select></div></div>`;foot=`<button class="secondary-btn" onclick="closeModal()">Anuluj</button><button class="primary-btn" onclick="saveDemo('Raport dodany do kolejki')">Generuj raport</button>`}
 else {title={'giftRules':'Zasady programu','giftHistory':'Historia wyborów','accessInfo':'Dostępy i członkostwa','migrationRules':'Macierz migracyjna','importClient':'Import klientów','newContent':'Nowa publikacja','scheduleReport':'Harmonogram raportu'}[type]||'Szczegóły';body=`<div class="demo-note">Ten formularz jest częścią zintegrowanego prototypu. Zachowuje wspólny kontekst klienta, platformy, programu i roli.</div><div class="form-grid" style="margin-top:14px"><div class="field"><label>Nazwa / opis</label><input /></div><div class="field"><label>Uwagi</label><textarea></textarea></div></div>`}
 return `<div class="modal-backdrop" onclick="if(event.target===this)closeModal()"><section class="modal ${size}"><div class="modal-head"><h3>${esc(title)}</h3><button class="close-btn" onclick="closeModal()">×</button></div><div class="modal-body">${body}</div><div class="modal-foot">${foot}</div></section></div>`}

function drawerHtml(){if(!state.drawer)return '';const {type,data}=state.drawer;let title='Szczegóły';if(type==='client')title='Klient i platformy';if(type==='order')title='Zamówienie '+data.id;if(type==='program')title='Program '+data.id;if(type==='migration')title='Mapowanie: '+data.source;if(type==='product')title=data.name;if(type==='user')title='Użytkownik';if(type==='content')title='Publikacja';return `<div class="drawer-backdrop" onclick="if(event.target===this)closeDrawer()"><aside class="drawer"><div class="modal-head"><div><h3>${esc(title)}</h3><span style="font-size:10px;color:var(--brand-muted)">Pełny kontekst rekordu</span></div><button class="close-btn" onclick="closeDrawer()">×</button></div><div><div class="drawer-tabs"><button class="drawer-tab active">Podsumowanie</button><button class="drawer-tab">Powiązania</button><button class="drawer-tab">Finanse</button><button class="drawer-tab">Audyt</button></div><div class="modal-body"><div class="context-line"><span class="context-icon">${ICONS.building}</span><span><b>${esc(tenant().name)}</b><span>Klient i platforma</span></span></div><div class="context-line"><span class="context-icon">${ICONS.layers}</span><span><b>Program główny 2026</b><span>Powiązany program</span></span></div><div class="context-line"><span class="context-icon">${ICONS.user}</span><span><b>${esc(state.user.name)}</b><span>Ostatnia zmiana: dzisiaj 20:41</span></span></div><div class="form-card" style="margin-top:14px"><h3 style="font-size:13px;margin-top:0">Historia</h3><div class="activity"><span class="activity-dot"></span><span><b>Rekord utworzony</b><span>Import z systemu legacy</span></span></div><div class="activity"><span class="activity-dot"></span><span><b>Zaktualizowano mapowanie</b><span>Małgorzata Bartkiewicz • 14 min temu</span></span></div></div></div></div><div class="modal-foot"><button class="secondary-btn" onclick="closeDrawer()">Zamknij</button><button class="primary-btn" onclick="saveDemo('Rekord zapisany')">Edytuj</button></div></aside></div>`}
function renderOverlay(){let root=el('overlayRoot');if(!root){root=document.createElement('div');root.id='overlayRoot';document.body.appendChild(root)}root.innerHTML=modalHtml()+drawerHtml()}

function render(){applyTheme();const app=el('app');app.innerHTML=!state.loggedIn?renderLogin():state.role?renderRole():renderAccounts();renderOverlay();}


