let FLOW_DB=FLOW_DB_DEFAULT;
try{const raw=localStorage.getItem('upbonus_flow_db_v3');if(raw)FLOW_DB={...FLOW_DB_DEFAULT,...JSON.parse(raw)}}catch(e){}
function saveFlowDb(){localStorage.setItem('upbonus_flow_db_v3',JSON.stringify(FLOW_DB))}
function money(v){return Number(v||0).toLocaleString('pl-PL',{minimumFractionDigits:2,maximumFractionDigits:2})+' zł'}
function findEmployee(id){return FLOW_DB.employees.find(x=>x.employeeId===id)}
function findFlowRecords(flowId){return {
 funding:FLOW_DB.fundingBatches.filter(x=>x.flowId===flowId),
 lines:FLOW_DB.fundingLines.filter(x=>x.flowId===flowId),
 orders:FLOW_DB.orders.filter(x=>x.flowId===flowId),
 complaints:FLOW_DB.complaints.filter(x=>x.flowId===flowId),
 settlements:FLOW_DB.settlements.filter(x=>x.flowId===flowId),
 deliveries:FLOW_DB.deliveries.filter(x=>x.flowId===flowId)
}}
function flowBadge(id,label='ID'){return id?`<button class="flow-id" onclick="showFlow('${esc(id.startsWith('FLOW-')?id:resolveFlowId(id))}')" title="Pokaż powiązania">${esc(label)}: ${esc(id)}</button>`:''}
function resolveFlowId(id){for(const group of Object.values(FLOW_DB)){if(!Array.isArray(group))continue;const r=group.find(x=>Object.values(x).includes(id));if(r?.flowId)return r.flowId}return id}
function flowStrip(ids){return `<div class="linkage-strip">${ids.filter(Boolean).map((x,i)=>`${i?'<span class="linkage-arrow">→</span>':''}<div class="linkage-node"><span>${esc(x[0])}</span><div><b>${esc(x[1])}</b><span>${esc(x[2]||'')}</span></div></div>`).join('')}</div>`}

function showFlow(flowId){state.modal={type:'flowLineage',data:{flowId}};renderOverlay()}
function flowLineageModal(flowId){const r=findFlowRecords(flowId);const funding=r.funding[0],order=r.orders[0],complaint=r.complaints[0],settlement=r.settlements[0],delivery=r.deliveries[0];const emp=findEmployee(order?.employeeId||r.lines[0]?.employeeId);return `<div class="modal-backdrop" onclick="if(event.target===this)closeModal()"><section class="modal large"><div class="modal-head"><div><h3>Pełny przepływ danych</h3><span class="flow-id">${esc(flowId)}</span></div><button class="close-btn" onclick="closeModal()">×</button></div><div class="modal-body">${flowStrip([
 ['Tenant',funding?.tenantId||order?.tenantId||'TEN-001','klient'],['Platforma',funding?.platformId||order?.platformId||'PLT-001','portal'],['Program',funding?.programId||order?.programId||'PRG-1041','reguły'],['Pracownik',emp?.employeeId||'—',emp?.name||''],['Portfel',emp?.walletId||order?.walletId||'—','saldo'],['Operacja',funding?.fundingId||order?.orderId||'—',funding?'zasilenie':'zamówienie'],['Rozliczenie',settlement?.settlementId||'—',settlement?.status||'']
 ])}<div class="flow-timeline">
 ${funding?`<div class="flow-step"><span class="flow-dot">＋</span><div><b>Zasilenie pracodawcy</b><p>${esc(funding.name)} • ${funding.recipients} odbiorców • ${money(funding.total)}</p><div class="id-stack"><span class="flow-id">${funding.fundingId}</span><span class="flow-id">${funding.programId}</span><span class="flow-id">${funding.settlementId}</span></div></div></div>`:''}
 ${r.lines.length?`<div class="flow-step"><span class="flow-dot">👥</span><div><b>Pozycje zasilenia i księga portfela</b><p>${r.lines.length} powiązanych pozycji. Każda ma employee_id, wallet_id i ledger_id.</p><div class="id-stack">${r.lines.slice(0,3).map(x=>`<span class="flow-id">${x.fundingLineId}</span><span class="flow-id">${x.ledgerId}</span>`).join('')}</div></div></div>`:''}
 ${order?`<div class="flow-step"><span class="flow-dot">🛒</span><div><b>Zamówienie pracownika</b><p>${esc(order.name)} • ${money(order.value)} • ${esc(order.status)}</p><div class="id-stack"><span class="flow-id">${order.orderId}</span><span class="flow-id">${order.orderItemId}</span><span class="flow-id">${order.offerId}</span><span class="flow-id">${order.variantId}</span></div></div></div>`:''}
 ${order?.voucherId?`<div class="flow-step"><span class="flow-dot">🎫</span><div><b>Voucher przypisany do pozycji</b><p>Kod pozostaje powiązany z zamówieniem, odbiorcą i reklamacjami.</p><div class="id-stack"><span class="flow-id">${order.voucherId}</span></div></div></div>`:''}
 ${delivery?`<div class="flow-step"><span class="flow-dot">✉</span><div><b>Dostarczenie</b><p>${esc(delivery.channel)} • ${esc(delivery.status)} • ${esc(delivery.sentAt)}</p><div class="id-stack"><span class="flow-id">${delivery.deliveryId}</span></div></div></div>`:''}
 ${complaint?`<div class="flow-step"><span class="flow-dot">!</span><div><b>Obsługa BOK / reklamacja</b><p>${esc(complaint.type)} • ${esc(complaint.status)} • SLA ${esc(complaint.sla)}</p><div class="id-stack"><span class="flow-id">${complaint.complaintId}</span></div></div></div>`:''}
 ${settlement?`<div class="flow-step"><span class="flow-dot">₿</span><div><b>Rozliczenie finansowe</b><p>${esc(settlement.type)} • ${money(settlement.gross)} • ${esc(settlement.status)}</p><div class="id-stack"><span class="flow-id">${settlement.settlementId}</span><span class="flow-id">${settlement.erpId}</span></div></div></div>`:''}
 </div><div class="demo-note">Łącznikiem nadrzędnym jest <b>flow_id</b>. Poszczególne rekordy zachowują również własne identyfikatory domenowe, dzięki czemu pracownik, HR, Operacje, BOK i Finanse widzą ten sam proces z odpowiednim zakresem uprawnień.</div></div><div class="modal-foot"><button class="secondary-btn" onclick="closeModal()">Zamknij</button><button class="primary-btn" onclick="toast('Audyt','Pełna historia przepływu została przygotowana.')">Pobierz audyt</button></div></section></div>`}

function downloadText(filename,text,type='text/csv;charset=utf-8'){const blob=new Blob(['\ufeff'+text],{type});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=filename;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function downloadTemplate(kind='employees'){
 const templates={
  employees:[['employee_id','email','imie_i_nazwisko','grupa','program_id','kwota','data_waznosci'],['EMP-0001','malgorzata.bartkiewicz@upbonus.pl','Małgorzata Bartkiewicz','Centrala','PRG-1041','300','2026-12-31']],
  funding:[['employee_id','email','wallet_id','program_id','kwota','waluta','opis'],['EMP-0001','malgorzata.bartkiewicz@upbonus.pl','WAL-0001','PRG-1041','300','PLN','Prezent świąteczny']],
  codes:[['external_id','code','pin','redemption_url','qr_payload','face_value','currency','valid_to'],['EXT-0001','ABCD-EFGH-IJKL','1234','https://partner.pl/redeem','ABCD-EFGH-IJKL','100','PLN','2027-08-04']]
 };
 const rows=templates[kind]||templates.employees;const html=`<html><head><meta charset="utf-8"></head><body><table>${rows.map(r=>`<tr>${r.map(c=>`<td>${esc(c)}</td>`).join('')}</tr>`).join('')}</table>

</body></html>`;downloadText(`upbonus-formatka-${kind}.xls`,html,'application/vnd.ms-excel')
}
let sheetState={kind:'funding',headers:['employee_id','email','wallet_id','program_id','kwota','waluta','opis'],rows:[
 ['EMP-0001','malgorzata.bartkiewicz@upbonus.pl','WAL-0001','PRG-1041','300','PLN','Prezent świąteczny'],
 ['EMP-0002','jan.nowak@firma.pl','WAL-0002','PRG-1041','300','PLN','Prezent świąteczny'],
 ['EMP-0003','anna.kowalska@firma.pl','WAL-0003','PRG-1041','450','PLN','Prezent świąteczny']
 ]};
function setSheetKind(kind){sheetState.kind=kind;if(kind==='employees'){sheetState.headers=['employee_id','email','imie_i_nazwisko','grupa','program_id','kwota','data_waznosci'];sheetState.rows=[['EMP-0001','malgorzata.bartkiewicz@upbonus.pl','Małgorzata Bartkiewicz','Centrala','PRG-1041','300','2026-12-31']]}else if(kind==='codes'){sheetState.headers=['external_id','code','pin','redemption_url','qr_payload','face_value','currency','valid_to'];sheetState.rows=[['EXT-0001','ABCD-EFGH-IJKL','1234','https://partner.pl/redeem','ABCD-EFGH-IJKL','100','PLN','2027-08-04']]}else{sheetState.headers=['employee_id','email','wallet_id','program_id','kwota','waluta','opis'];sheetState.rows=[['EMP-0001','malgorzata.bartkiewicz@upbonus.pl','WAL-0001','PRG-1041','300','PLN','Prezent świąteczny'],['EMP-0002','jan.nowak@firma.pl','WAL-0002','PRG-1041','300','PLN','Prezent świąteczny']]}render()}
function pasteSheetData(v){if(!v.trim())return;const rows=v.trim().split(/\r?\n/).map(line=>line.split(/\t|;/));if(rows[0].some(x=>sheetState.headers.includes(x.trim()))){sheetState.headers=rows.shift().map(x=>x.trim())}sheetState.rows=rows.map(r=>sheetState.headers.map((_,i)=>(r[i]||'').trim()));render()}
function updateSheetCell(r,c,v){sheetState.rows[r][c]=v}
function addSheetRow(){sheetState.rows.push(sheetState.headers.map(()=>''));render()}
function removeSheetRow(r){sheetState.rows.splice(r,1);render()}
function validateSheet(){let errors=0,warnings=0;sheetState.rows.forEach(row=>{sheetState.headers.forEach((h,i)=>{const v=(row[i]||'').trim();if(['email','employee_id','code','kwota'].includes(h)&&!v)errors++;if(h==='email'&&v&&!/^\S+@\S+\.\S+$/.test(v))errors++;if((h==='kwota'||h==='face_value')&&v&&isNaN(Number(v.replace(',','.'))))errors++;if(h==='wallet_id'&&!v)warnings++})});return{errors,warnings,ok:Math.max(0,sheetState.rows.length-errors)}}
function commitSheet(){const val=validateSheet();if(val.errors){toast('Nie można zatwierdzić',`Popraw ${val.errors} błędnych pól.`);return}if(sheetState.kind==='funding'){const suffix=String(Date.now()).slice(-5),id='FND-2026-'+suffix,flow='FLOW-2026-'+suffix,stl='STL-2026-'+suffix;const idx=Object.fromEntries(sheetState.headers.map((h,i)=>[h,i]));const total=sheetState.rows.reduce((a,r)=>a+Number((r[idx.kwota]||0).replace(',','.')),0);const programId=sheetState.rows[0]?.[idx.program_id]||'PRG-1041';FLOW_DB.fundingBatches.unshift({fundingId:id,flowId:flow,tenantId:'TEN-001',platformId:'PLT-001',programId,name:'Zasilenie z edytora danych',date:new Date().toISOString().slice(0,10),recipients:sheetState.rows.length,total,status:'Robocze',createdBy:'USR-HR-001',settlementId:stl});sheetState.rows.forEach((r,i)=>{const empId=r[idx.employee_id]||`EMP-NEW-${i+1}`,emp=FLOW_DB.employees.find(x=>x.employeeId===empId),wallet=r[idx.wallet_id]||emp?.walletId||`WAL-NEW-${i+1}`,amount=Number((r[idx.kwota]||0).replace(',','.'));FLOW_DB.fundingLines.push({fundingLineId:`FNL-${suffix}-${String(i+1).padStart(4,'0')}`,fundingId:id,flowId:flow,employeeId:empId,walletId:wallet,programId:r[idx.program_id]||programId,amount,status:'Robocze',ledgerId:`LED-${suffix}-${String(i+1).padStart(4,'0')}`})});FLOW_DB.settlements.unshift({settlementId:stl,flowId:flow,type:'Zasilenie',referenceId:id,gross:total,partnerCost:0,margin:0,status:'Robocze',erpId:'—'});saveFlowDb();toast('Zapisano wersję roboczą',`${sheetState.rows.length} pozycji • ${money(total)} • ${id}`)}else toast('Dane zapisane',`${sheetState.rows.length} poprawnych rekordów.`);render()}
function excelEditorView(){const v=validateSheet();return `${pageHead('Edytor danych Excel','Wklej dane bezpośrednio z Excela, popraw je w tabeli i zobacz wynik przed zapisaniem.',`<button class="secondary-btn" onclick="downloadTemplate('${sheetState.kind}')">${icon('download')} Pobierz formatkę Excel</button><button class="primary-btn" onclick="commitSheet()">${icon('check')} Zapisz wersję roboczą</button>`)}
 <div class="toolbar"><select onchange="setSheetKind(this.value)"><option value="funding" ${sheetState.kind==='funding'?'selected':''}>Zasilenia kont pracowników</option><option value="employees" ${sheetState.kind==='employees'?'selected':''}>Pracownicy i uprawnienia</option><option value="codes" ${sheetState.kind==='codes'?'selected':''}>Kody i vouchery</option></select><button class="compact-btn" onclick="downloadTemplate('${sheetState.kind}')">Formatka .xls</button><span class="spacer"></span><span class="flow-id">TEN-001</span><span class="flow-id">PLT-001</span></div>
 <div class="sheet-layout"><aside class="sheet-help"><h3>Wklej z Excela</h3><p>Zaznacz komórki w Excelu, skopiuj i wklej poniżej. Nie musisz najpierw zapisywać ani wgrywać pliku.</p><textarea class="sheet-paste" placeholder="Wklej tutaj dane skopiowane z Excela…" onchange="pasteSheetData(this.value)"></textarea><h3 style="margin-top:14px">Kontrola przed zapisem</h3><ul><li>sprawdzenie e-maili i wymaganych ID,</li><li>podgląd kwot i liczby rekordów,</li><li>powiązanie z tenant_id, platform_id i program_id,</li><li>zapis jako wersja robocza przed zatwierdzeniem.</li></ul><button class="secondary-btn full" onclick="addSheetRow()">＋ Dodaj pusty wiersz</button></aside>
 <section class="sheet-preview"><div class="sheet-preview-head"><h3>Podgląd danych (${sheetState.rows.length})</h3><span class="status ${v.errors?'red':'green'}">${v.errors?v.errors+' błędów':'Gotowe do zapisu'}</span></div><div class="sheet-grid-wrap"><table class="sheet-grid"><thead><tr><th>#</th>${sheetState.headers.map(h=>`<th>${esc(h)}</th>`).join('')}<th></th></tr></thead><tbody>${sheetState.rows.map((row,ri)=>`<tr><td>${ri+1}</td>${sheetState.headers.map((h,ci)=>{const value=row[ci]||'';const bad=(!value&&['email','employee_id','code','kwota'].includes(h))||(h==='email'&&value&&!/^\S+@\S+\.\S+$/.test(value));return `<td class="${bad?'cell-error':''}" contenteditable="true" onblur="updateSheetCell(${ri},${ci},this.textContent)">${esc(value)}</td>`}).join('')}<td><button class="link-btn" onclick="removeSheetRow(${ri})">Usuń</button></td></tr>`).join('')}</tbody></table></div><div class="validation-bar"><span class="validation-chip">Wiersze: ${sheetState.rows.length}</span><span class="validation-chip">Poprawne: ${v.ok}</span><span class="validation-chip">Błędy: ${v.errors}</span><span class="validation-chip">Ostrzeżenia: ${v.warnings}</span></div></section></div>`}

function repeatFunding(id){state.modal={type:'repeatFunding',data:{id}};renderOverlay()}
function confirmRepeatFunding(id){const src=FLOW_DB.fundingBatches.find(x=>x.fundingId===id);if(!src)return;const suffix=String(Date.now()).slice(-5),newId='FND-2026-'+suffix,flow='FLOW-2026-'+suffix,stl='STL-2026-'+suffix;FLOW_DB.fundingBatches.unshift({...src,fundingId:newId,flowId:flow,name:(el('repeatName')?.value||src.name+' — ponowienie'),date:el('repeatDate')?.value||new Date().toISOString().slice(0,10),status:'Zaplanowane',settlementId:stl});const sourceLines=FLOW_DB.fundingLines.filter(x=>x.fundingId===id);sourceLines.forEach((line,i)=>FLOW_DB.fundingLines.push({...line,fundingLineId:`FNL-${suffix}-${String(i+1).padStart(4,'0')}`,fundingId:newId,flowId:flow,status:'Zaplanowane',ledgerId:`LED-${suffix}-${String(i+1).padStart(4,'0')}`}));FLOW_DB.settlements.unshift({settlementId:stl,flowId:flow,type:'Zasilenie',referenceId:newId,gross:src.total,partnerCost:0,margin:0,status:'Oczekuje',erpId:'—'});saveFlowDb();closeModal();render();toast('Zasilenie zostało ponowione',`${newId} • ${src.recipients} pracowników • ${sourceLines.length} pozycji skopiowanych`)}
function repeatFundingModal(id){
  const f=FLOW_DB.fundingBatches.find(function(x){return x.fundingId===id});
  if(!f)return '';
  const today=new Date().toISOString().slice(0,10);
  const recipients=Number(f.recipients||0).toLocaleString('pl-PL');
  const fundingId=esc(String(f.fundingId||''));
  const programId=esc(String(f.programId||''));
  const safeName=esc(String(f.name||''));
  const lineage=flowStrip([
    ['Klient',f.tenantId,'tenant'],
    ['Platforma',f.platformId,'portal'],
    ['Program',f.programId,'budżet'],
    ['Zasilenie',f.fundingId,'wzorzec']
  ]);
  return ''
    + '<div class="modal-backdrop" onclick="if(event.target===this)closeModal()">'
    + '<section class="modal large">'
    + '<div class="modal-head"><div><h3>Ponów zasilenie pracowników</h3><span class="flow-id">Źródło: '+fundingId+'</span></div><button class="close-btn" onclick="closeModal()">×</button></div>'
    + '<div class="modal-body">'+lineage
    + '<div class="repeat-card"><h3>Skopiowano parametry poprzedniego zasilenia</h3><p>Lista pracowników, portfele i kwoty pozostają do podglądu. Nowa operacja otrzyma własne funding_id, flow_id i settlement_id.</p>'
    + '<div class="repeat-summary"><div><span>Odbiorcy</span><b>'+recipients+'</b></div><div><span>Łączna kwota</span><b>'+money(f.total)+'</b></div><div><span>Program</span><b style="font-size:12px">'+programId+'</b></div></div></div>'
    + '<div class="form-columns" style="margin-top:13px">'
    + '<div class="field"><label>Nazwa nowego zasilenia</label><input id="repeatName" value="'+safeName+' — ponowienie" /></div>'
    + '<div class="field"><label>Data księgowania</label><input id="repeatDate" type="date" value="'+today+'" /></div>'
    + '<div class="field"><label>Grupa pracowników</label><select><option>Ta sama lista ('+recipients+')</option><option>Tylko aktywni</option><option>Wybierz grupę</option></select></div>'
    + '<div class="field"><label>Kwoty</label><select><option>Bez zmian</option><option>Podnieś procentowo</option><option>Edytuj w tabeli</option></select></div>'
    + '</div><div class="demo-note">Przed zatwierdzeniem możesz przejść do Edytora danych Excel i zmienić pojedyncze kwoty bez przygotowywania nowego pliku.</div></div>'
    + '<div class="modal-foot"><button class="secondary-btn" onclick="closeModal()">Anuluj</button><button class="secondary-btn" onclick="closeModal();openExcelImportV6(\'funding\')">Edytuj w Excelu</button><button class="primary-btn" onclick="confirmRepeatFunding(\''+String(f.fundingId).replace(/'/g,"\\'")+'\')">Utwórz nowe zasilenie</button></div>'
    + '</section></div>';
}

function fundingView(){const rows=FLOW_DB.fundingBatches;return `${pageHead('Budżety i finansowanie','Zasilenia pracowników, portfele, źródła finansowania i rozliczenia w jednym przepływie.',`<button class="secondary-btn" onclick="downloadTemplate('funding')">${icon('download')} Formatka Excel</button><button class="secondary-btn" onclick="state.section='Edytor danych Excel';render()">${icon('upload')} Edytor danych</button><button class="primary-btn" onclick="state.section='Edytor danych Excel';render()">${icon('plus')} Nowe zasilenie</button>`)}
 <div class="compact-kpis"><div class="compact-kpi"><span>Zasilenia w miesiącu</span><b>${money(rows.reduce((a,x)=>a+x.total,0))}</b><small>${rows.length} operacje</small></div><div class="compact-kpi"><span>Pracownicy objęci</span><b>${rows.reduce((a,x)=>a+x.recipients,0).toLocaleString('pl-PL')}</b><small>unikalne portfele po walidacji</small></div><div class="compact-kpi"><span>Zaplanowane</span><b>${rows.filter(x=>x.status==='Zaplanowane').length}</b><small>oczekują na datę księgowania</small></div><div class="compact-kpi"><span>Rozbieżności</span><b>0</b><small>HR ↔ księga ↔ Finanse</small></div></div>
 ${flowStrip([['Klient','TEN-001','Up Bonus'],['Platforma','PLT-001','Portal pracownika'],['Program','PRG-1041','Prezenty 2026'],['Zasilenie','FND-*','paczka'],['Portfel','WAL-*','pracownik'],['Księga','LED-*','operacja'],['Rozliczenie','STL-*','Finanse']])}
 <div class="table-wrap"><table class="data-table"><thead><tr><th>Zasilenie</th><th>Data</th><th>Program</th><th>Odbiorcy</th><th>Kwota</th><th>Status</th><th>Rozliczenie</th><th>Akcje</th></tr></thead><tbody>${rows.map(f=>`<tr><td><span class="td-title">${esc(f.name)}</span><span class="td-sub">${esc(f.fundingId)} • ${esc(f.flowId)}</span></td><td>${esc(f.date)}</td><td>${flowBadge(f.programId,'Program')}</td><td>${f.recipients.toLocaleString('pl-PL')}</td><td>${money(f.total)}</td><td><span class="status ${f.status==='Zrealizowane'||f.status==='Rozliczone'?'green':f.status==='Zaplanowane'?'purple':'amber'}">${esc(f.status)}</span></td><td>${flowBadge(f.settlementId,'STL')}</td><td><div class="table-actions"><button onclick="showFlow('${f.flowId}')">Przepływ</button><button onclick="repeatFunding('${f.fundingId}')">Ponów</button></div></td></tr>`).join('')}</tbody></table></div>`}

function linkedEmployeesView(){return `${pageHead('Pracownicy i grupy','Jedna kartoteka łączy użytkownika, pracownika, portfele, programy, zamówienia i sprawy BOK.',`<button class="secondary-btn" onclick="downloadTemplate('employees')">${icon('download')} Formatka Excel</button><button class="primary-btn" onclick="state.section='Edytor danych Excel';setSheetKind('employees')">${icon('plus')} Dodaj zbiorczo</button>`)}<div class="table-wrap"><table class="data-table"><thead><tr><th>Pracownik</th><th>ID użytkownika</th><th>Grupa</th><th>Portfel</th><th>Saldo</th><th>Programy</th><th>Status</th><th>Akcje</th></tr></thead><tbody>${FLOW_DB.employees.map(e=>`<tr><td><span class="td-title">${esc(e.name)}</span><span class="td-sub">${esc(e.email)} • ${esc(e.employeeId)}</span></td><td>${flowBadge(e.userId,'USR')}</td><td>${esc(e.group)}</td><td>${flowBadge(e.walletId,'WAL')}</td><td>${money(e.balance)}</td><td><span class="flow-id">PRG-1041</span></td><td><span class="status ${e.status==='Aktywny'?'green':'gray'}">${esc(e.status)}</span></td><td><div class="table-actions"><button onclick="showFlow('${resolveFlowId(e.employeeId)}')">Historia</button><button onclick="toast('Profil pracownika','Otwieram pełny kontekst '+ '${esc(e.employeeId)}')">Szczegóły</button></div></td></tr>`).join('')}</tbody></table></div>`}

function employeeOrdersViewV3(){const employeeId=state.user.email==='malgorzata.bartkiewicz@upbonus.pl'||state.user.email==='pracownik@upbonus.pl'?'EMP-0001':'EMP-0001';const orders=FLOW_DB.orders.filter(x=>x.employeeId===employeeId);return `<div class="employee-dashboard">${pageHead('Zamówienia i vouchery','Zakup jest połączony z programem, portfelem, dostawą i obsługą BOK.')}<section class="employee-section"><div class="employee-section-head"><div><h2>Twoje zakupy i vouchery</h2><p>Techniczne identyfikatory są dostępne w szczegółach, aby BOK mógł szybko odnaleźć tę samą sprawę.</p></div></div><div class="employee-order-grid">${orders.map(o=>{const d=FLOW_DB.deliveries.find(x=>x.deliveryId===o.deliveryId);return `<article class="employee-order"><span class="voucher-logo">${o.voucherId?'🎫':'🎁'}</span><div><h3>${esc(o.name)}</h3><p>${esc(o.orderId)} • ${money(o.value)} • ${esc(d?.status||o.status)}</p><div class="id-stack"><span class="flow-id">${o.programId}</span><span class="flow-id">${o.orderItemId}</span>${o.voucherId?`<span class="flow-id">${o.voucherId}</span>`:''}</div></div><div class="order-status"><b>${esc(o.status)}</b><span><button class="link-btn" onclick="showFlow('${o.flowId}')">Śledź zamówienie</button></span></div></article>`}).join('')}</div></section><section class="employee-section"><div class="employee-section-head"><div><h2>Jak dane łączą się po zakupie?</h2><p>Ta sama operacja jest widoczna w HR, Operacjach, BOK i Finansach, ale każda rola widzi tylko dozwolone dane.</p></div></div>${flowStrip([['Pracownik',employeeId,'konto'],['Portfel','WAL-0001','środki'],['Zamówienie','ORD-*','zakup'],['Voucher','VCH-*','wydanie'],['Dostawa','DLV-*','e-mail/PDF'],['BOK','CMP-*','reklamacja'],['Finanse','STL-*','rozliczenie']])}</section></div>`}


function employeeWalletViewV3(){const emp=findEmployee('EMP-0001'),lines=FLOW_DB.fundingLines.filter(x=>x.employeeId===emp.employeeId),batches=lines.map(l=>FLOW_DB.fundingBatches.find(b=>b.fundingId===l.fundingId)).filter(Boolean);return `<div class="employee-dashboard">${pageHead('Portfel i budżety','Środki przyznane przez pracodawcę, terminy ważności i historia księgowa.')}<section class="wallet-summary"><div class="wallet-total"><span>Łącznie dostępne</span><b>${money(emp.balance)}</b><small>${emp.walletId} • ${emp.employeeId}</small></div><div class="wallet-mini"><span>Prezent od firmy</span><b>300,00 zł</b><small>do 31.12.2026</small></div><div class="wallet-mini"><span>Lunch</span><b>220,00 zł</b><small>odnawiany co miesiąc</small></div></section><section class="employee-section"><div class="employee-section-head"><div><h2>Historia przyznanych środków</h2><p>Każde zasilenie ma numer operacji, program i pozycję w księdze portfela.</p></div></div><div class="transaction-list">${lines.map((l,i)=>{const b=FLOW_DB.fundingBatches.find(x=>x.fundingId===l.fundingId);return `<div class="transaction"><span class="transaction-icon">＋</span><div><b>${esc(b?.name||'Zasilenie pracodawcy')}</b><span>${esc(b?.date||'')} • ${l.programId}</span><div class="id-stack"><span class="flow-id">${l.fundingId}</span><span class="flow-id">${l.fundingLineId}</span><span class="flow-id">${l.ledgerId}</span></div></div><strong class="plus">+${money(l.amount)}</strong></div>`}).join('')}</div></section><section class="employee-section"><div class="employee-section-head"><div><h2>Powiązanie z pracodawcą</h2><p>HR widzi zasilenie zbiorcze, Ty widzisz wyłącznie własną pozycję i saldo.</p></div></div>${flowStrip([['Pracodawca','TEN-001','klient'],['Program','PRG-1041','zasady'],['Zasilenie',batches[0]?.fundingId||'FND-*','HR'],['Pozycja',lines[0]?.fundingLineId||'FNL-*','Twoja'],['Portfel',emp.walletId,'saldo'],['Księga',lines[0]?.ledgerId||'LED-*','historia']])}</section></div>`}
function connectedOrdersView(){return `${pageHead('Centrum zamówień','Jedna kolejka łączy pracownika, finansowanie, produkt, kod, dostawę, BOK i rozliczenie.',`<button class="secondary-btn" onclick="exportAllVisibleTables('excel')">${icon('download')} Excel</button><button class="primary-btn" onclick="showModal('newOrder')">${icon('plus')} Nowe zamówienie</button>`)}<div class="table-wrap"><table class="data-table"><thead><tr><th>Zamówienie</th><th>Pracownik</th><th>Program / finansowanie</th><th>Produkt</th><th>Voucher</th><th>Dostawa</th><th>Rozliczenie</th><th>Status</th><th>Akcje</th></tr></thead><tbody>${FLOW_DB.orders.map(o=>{const e=findEmployee(o.employeeId),d=FLOW_DB.deliveries.find(x=>x.deliveryId===o.deliveryId),st=FLOW_DB.settlements.find(x=>x.settlementId===o.settlementId);return `<tr><td><span class="td-title">${o.orderId}</span><span class="td-sub">${o.orderItemId} • ${o.flowId}</span></td><td>${esc(e?.name||o.employeeId)}<span class="td-sub">${o.employeeId} • ${o.walletId}</span></td><td>${flowBadge(o.programId,'PRG')} ${o.fundingId?flowBadge(o.fundingId,'FND'):''}</td><td><span class="td-title">${esc(o.name)}</span><span class="td-sub">${o.offerId} • ${o.variantId}</span></td><td>${o.voucherId?flowBadge(o.voucherId,'VCH'):'—'}</td><td>${flowBadge(o.deliveryId,'DLV')}<span class="td-sub">${esc(d?.status||'—')}</span></td><td>${flowBadge(o.settlementId,'STL')}<span class="td-sub">${esc(st?.status||'—')}</span></td><td><span class="status ${o.status==='Dostarczone'?'green':'amber'}">${esc(o.status)}</span></td><td><button class="flow-link" onclick="showFlow('${o.flowId}')">Pełny przepływ</button></td></tr>`}).join('')}</tbody></table></div>`}
function supportFlowView(section='Reklamacje'){const rows=FLOW_DB.complaints;return `${pageHead(section,'BOK pracuje na tym samym flow_id co pracownik, zamówienie, voucher, dostawa i rozliczenie.',`<button class="primary-btn" onclick="toast('Nowe zgłoszenie','Zgłoszenie otrzyma własne complaint_id i flow_id.')">${icon('plus')} Nowe zgłoszenie</button>`)}<div class="toolbar"><div class="search"><span>${ICONS.search}</span><input placeholder="Szukaj: ORD-, VCH-, CMP-, e-mail, employee_id…" oninput="filterSupportRows(this.value)" /></div><select><option>Wszystkie statusy</option><option>Otwarte</option><option>Wysłano do partnera</option><option>Zamknięte</option></select><span class="spacer"></span><button class="compact-btn" onclick="exportAllVisibleTables('excel')">Excel</button><button class="compact-btn" onclick="exportAllVisibleTables('pdf')">PDF</button></div><div class="table-wrap"><table class="data-table" id="supportFlowTable"><thead><tr><th>Sprawa</th><th>Pracownik</th><th>Zamówienie</th><th>Voucher</th><th>Typ</th><th>Status</th><th>SLA</th><th>Akcje</th></tr></thead><tbody>${rows.map(c=>{const emp=findEmployee(c.employeeId);return `<tr><td><span class="td-title">${c.complaintId}</span><span class="td-sub">${c.flowId}</span></td><td>${esc(emp?.name||c.employeeId)}<span class="td-sub">${c.employeeId}</span></td><td>${flowBadge(c.orderId,'ORD')}</td><td>${flowBadge(c.voucherId,'VCH')}</td><td>${esc(c.type)}</td><td><span class="status ${c.status==='Zamknięta'?'green':'amber'}">${esc(c.status)}</span></td><td>${esc(c.sla)}</td><td><div class="table-actions"><button onclick="showFlow('${c.flowId}')">Pełny kontekst</button><button onclick="toast('Ponowna wysyłka','Utworzono nowe delivery_id dla '+ '${c.orderId}')">Wyślij ponownie</button></div></td></tr>`}).join('')}</tbody></table></div>`}
function filterSupportRows(q){q=String(q||'').toLowerCase();document.querySelectorAll('#supportFlowTable tbody tr').forEach(r=>r.style.display=r.textContent.toLowerCase().includes(q)?'':'none')}

function globalSearchViewV3(){return `${pageHead('Wyszukiwarka globalna','Jedno pole odnajduje pracownika, portfel, zasilenie, zamówienie, voucher, dostawę, reklamację i rozliczenie.')}<section class="global-search"><div class="global-search-box"><span>${ICONS.search}</span><input id="globalIdSearch" value="ORD-2026-08189" placeholder="Wpisz dowolne ID lub e-mail…" onkeydown="if(event.key==='Enter')runGlobalIdSearch()"/><button class="primary-btn" onclick="runGlobalIdSearch()">Szukaj</button></div><div id="globalIdResults">${globalIdResultsHtml('ORD-2026-08189')}</div></section>`}
function runGlobalIdSearch(){const q=el('globalIdSearch')?.value||'';const c=el('globalIdResults');if(c)c.innerHTML=globalIdResultsHtml(q);enhanceDataTables(c)}
function globalIdResultsHtml(q){q=String(q||'').trim().toLowerCase();if(!q)return '<div class="demo-note">Wpisz ID lub e-mail.</div>';let flow=null,found=[];for(const [group,rows] of Object.entries(FLOW_DB)){if(!Array.isArray(rows))continue;rows.forEach(r=>{if(Object.values(r).some(v=>String(v).toLowerCase().includes(q))){found.push({group,r});flow=flow||r.flowId||resolveFlowId(r.employeeId||r.walletId||'')}})}if(!found.length)return '<div class="empty-state"><h3>Brak wyników</h3><p>Sprawdź ID, e-mail albo końcówkę numeru.</p></div>';return `${flow?`<div style="margin:12px 0"><button class="primary-btn" onclick="showFlow('${flow}')">Pokaż wspólny przepływ ${flow}</button></div>`:''}<div class="entity-card-grid">${found.slice(0,12).map(x=>`<article class="entity-card"><h3>${esc(x.group)}</h3><p>${Object.entries(x.r).slice(0,6).map(([k,v])=>`<b>${esc(k)}:</b> ${esc(v)}`).join('<br>')}</p>${x.r.flowId?`<button class="flow-link" onclick="showFlow('${x.r.flowId}')">Pełne powiązania</button>`:''}</article>`).join('')}</div>`}

function financeFlowView(section='Uzgodnienia'){return `${pageHead(section,'Każde rozliczenie wskazuje operację źródłową i wspólny flow_id.',`<button class="secondary-btn" onclick="exportAllVisibleTables('excel')">${icon('download')} Excel</button><button class="primary-btn" onclick="toast('Uzgodnienie','Uruchomiono automatyczne porównanie HR ↔ portfele ↔ partner ↔ ERP.')">${icon('check')} Uzgodnij</button>`)}<div class="compact-kpis"><div class="compact-kpi"><span>Wartość brutto</span><b>${money(FLOW_DB.settlements.reduce((a,x)=>a+x.gross,0))}</b><small>bieżący zakres</small></div><div class="compact-kpi"><span>Koszt partnerów</span><b>${money(FLOW_DB.settlements.reduce((a,x)=>a+x.partnerCost,0))}</b><small>według ofert</small></div><div class="compact-kpi"><span>Marża</span><b>${money(FLOW_DB.settlements.reduce((a,x)=>a+x.margin,0))}</b><small>przed kosztami operacyjnymi</small></div><div class="compact-kpi"><span>Rozbieżności</span><b>0</b><small>po automatycznym matchingu ID</small></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Rozliczenie</th><th>Typ</th><th>Operacja źródłowa</th><th>Brutto</th><th>Koszt</th><th>Marża</th><th>ERP</th><th>Status</th><th>Akcje</th></tr></thead><tbody>${FLOW_DB.settlements.map(s=>`<tr><td><span class="td-title">${s.settlementId}</span><span class="td-sub">${s.flowId}</span></td><td>${esc(s.type)}</td><td>${flowBadge(s.referenceId,'REF')}</td><td>${money(s.gross)}</td><td>${money(s.partnerCost)}</td><td>${money(s.margin)}</td><td><span class="flow-id">${s.erpId}</span></td><td><span class="status ${s.status==='Rozliczone'||s.status==='Uzgodnione'?'green':'amber'}">${esc(s.status)}</span></td><td><button class="flow-link" onclick="showFlow('${s.flowId}')">Przepływ</button></td></tr>`).join('')}</tbody></table></div>`}

function deliveriesView(){return `${pageHead('Dostawy i wysyłki','Status wysyłki jest połączony z zamówieniem, voucherem, odbiorcą i ewentualnym zgłoszeniem BOK.')}<div class="table-wrap"><table class="data-table"><thead><tr><th>Dostawa</th><th>Zamówienie</th><th>Kanał</th><th>Status</th><th>Wysłano</th><th>Otwarto</th><th>Flow ID</th><th>Akcje</th></tr></thead><tbody>${FLOW_DB.deliveries.map(d=>`<tr><td>${d.deliveryId}</td><td>${flowBadge(d.orderId,'ORD')}</td><td>${esc(d.channel)}</td><td><span class="status ${d.status==='Dostarczone'||d.status==='Pobrane'?'green':'amber'}">${esc(d.status)}</span></td><td>${esc(d.sentAt)}</td><td>${esc(d.openedAt)}</td><td>${flowBadge(d.flowId,'FLOW')}</td><td><button class="flow-link" onclick="toast('Ponowna wysyłka','Utworzono kolejną próbę dostarczenia z nowym delivery_attempt_id.')">Ponów</button></td></tr>`).join('')}</tbody></table></div>`}
function collectiveGiftsView(){return `${pageHead('Prezenty zbiorcze','Zamówienie zbiorcze łączy listę odbiorców, finansowanie, personalizację, realizację i rozliczenie.',`<button class="secondary-btn" onclick="downloadTemplate('funding')">Formatka Excel</button><button class="primary-btn" onclick="state.section='Edytor danych Excel';render()">Nowe zamówienie zbiorcze</button>`)}${flowStrip([['Program','PRG-1041','Prezenty 2026'],['Lista odbiorców','EMP-*','HR'],['Finansowanie','FND-*','budżet'],['Zamówienia','ORD-*','pozycje'],['Dostawy','DLV-*','e-mail/PDF'],['Rozliczenie','STL-*','Finanse']])}<div class="entity-card-grid"><article class="entity-card"><h3>1. Odbiorcy i kwoty</h3><p>Wklej dane z Excela lub edytuj je bezpośrednio w tabeli z walidacją.</p><button class="primary-btn full" onclick="state.section='Edytor danych Excel';render()">Otwórz edytor</button></article><article class="entity-card"><h3>2. Prezent i personalizacja</h3><p>Wybierz kartę, nominał, wspólne logo, zdjęcie i życzenia.</p><button class="secondary-btn full" onclick="openModule('gift')">Otwórz Gifts</button></article><article class="entity-card"><h3>3. Kontrola i realizacja</h3><p>System pokaże zapas kodów, koszt, dopłaty, błędy oraz plan wysyłki.</p><button class="secondary-btn full" onclick="state.section='Centrum zamówień';render()">Centrum zamówień</button></article></div>`}
function connectedPlaceholder(sec){return `${pageHead(sec,'Widok korzysta ze wspólnych danych i identyfikatorów całego ekosystemu.')} ${flowStrip([['Klient','TEN-001','tenant'],['Platforma','PLT-001','portal'],['Program','PRG-*','reguły'],['Operacja','FLOW-*','łącznik'],['Audyt','AUD-*','historia']])}<div class="panel"><div class="panel-body"><div class="entity-card-grid"><article class="entity-card"><h3>Akcje operacyjne</h3><p>Tworzenie, akceptacja, cofnięcie i ponowienie operacji z pełnym audytem.</p><button class="secondary-btn full" onclick="toast('Nowa operacja','Otrzymała własny identyfikator i kontekst.')">Nowa operacja</button></article><article class="entity-card"><h3>Dane i eksport</h3><p>Każda tabela ma filtrowanie, sortowanie oraz eksport do Excel i PDF.</p><button class="secondary-btn full" onclick="exportAllVisibleTables('excel')">Pobierz dane</button></article><article class="entity-card"><h3>Powiązania</h3><p>Przejście od pracownika przez HR i BOK aż do rozliczenia po flow_id.</p><button class="primary-btn full" onclick="showFlow('FLOW-2026-08189')">Pokaż przykład</button></article></div></div></div>`}

/* uniwersalne tabele */
function enhanceDataTables(root=document){root.querySelectorAll('.data-table').forEach((table,index)=>{if(table.dataset.enhanced)return;table.dataset.enhanced='1';const wrap=table.closest('.table-wrap');if(wrap&&!wrap.previousElementSibling?.classList.contains('ub-table-tools')){const tools=document.createElement('div');tools.className='ub-table-tools';tools.innerHTML=`<input class="table-filter" placeholder="Filtruj tę tabelę…"><span class="table-count"></span><button type="button">Excel</button><button type="button">PDF</button>`;wrap.parentNode.insertBefore(tools,wrap);const inp=tools.querySelector('input'),count=tools.querySelector('.table-count');const update=()=>{const q=inp.value.toLowerCase();let visible=0;table.querySelectorAll('tbody tr').forEach(r=>{const show=r.textContent.toLowerCase().includes(q);r.style.display=show?'':'none';if(show)visible++});count.textContent=visible+' wierszy'};inp.addEventListener('input',update);tools.querySelectorAll('button')[0].onclick=()=>exportTableExcel(table);tools.querySelectorAll('button')[1].onclick=()=>printTablePdf(table);update()}
 table.querySelectorAll('thead th').forEach((th,col)=>{if(th.querySelector('input')||/akcje/i.test(th.textContent))return;th.classList.add('ub-sortable');th.insertAdjacentHTML('beforeend','<span class="sort-mark">↕</span>');th.addEventListener('click',()=>{const body=table.tBodies[0];if(!body)return;const asc=th.dataset.dir!=='asc';th.dataset.dir=asc?'asc':'desc';[...body.rows].sort((a,b)=>{let av=a.cells[col]?.innerText.trim()||'',bv=b.cells[col]?.innerText.trim()||'';const an=Number(av.replace(/[^0-9,.-]/g,'').replace(',','.')),bn=Number(bv.replace(/[^0-9,.-]/g,'').replace(',','.'));if(!isNaN(an)&&!isNaN(bn)&&av.match(/\d/)&&bv.match(/\d/))return asc?an-bn:bn-an;return asc?av.localeCompare(bv,'pl',{numeric:true}):bv.localeCompare(av,'pl',{numeric:true})}).forEach(r=>body.appendChild(r));th.querySelector('.sort-mark').textContent=asc?'↑':'↓'})})})}
function tableMatrix(table){return [...table.rows].filter(r=>r.style.display!=='none').map(r=>[...r.cells].map(c=>c.innerText.replace(/\s+/g,' ').trim()))}
function exportTableExcel(table){const rows=tableMatrix(table);const html=`<html><head><meta charset="utf-8"></head><body><table>${rows.map(r=>`<tr>${r.map(c=>`<td>${esc(c)}</td>`).join('')}</tr>`).join('')}</table></body></html>`;downloadText('upbonus-dane-'+new Date().toISOString().slice(0,10)+'.xls',html,'application/vnd.ms-excel')}
function printTablePdf(table){const rows=tableMatrix(table);const w=window.open('','_blank');w.document.write(`<html><head><title>Up Bonus — tabela</title><style>body{font:11px Arial;padding:20px}table{border-collapse:collapse;width:100%}th,td{border:1px solid #bbb;padding:6px;text-align:left}th{background:#eee}@page{size:landscape;margin:12mm}</style></head><body><h2>Up Bonus — eksport tabeli</h2><table>${rows.map((r,i)=>`<tr>${r.map(c=>`<${i?'td':'th'}>${esc(c)}</${i?'td':'th'}>`).join('')}</tr>`).join('')}</table><script>onload=()=>setTimeout(()=>print(),200)<\/script></body></html>`);w.document.close()}
function exportAllVisibleTables(kind='excel'){const table=document.querySelector('.data-table');if(!table){toast('Brak tabeli','W tym widoku nie ma danych do eksportu.');return}kind==='pdf'?printTablePdf(table):exportTableExcel(table)}

const originalModalHtmlV3=modalHtml;
modalHtml=function(){if(state.modal?.type==='flowLineage')return flowLineageModal(state.modal.data.flowId);if(state.modal?.type==='repeatFunding')return repeatFundingModal(state.modal.data.id);return originalModalHtmlV3()}
const originalRenderOverlayV3=renderOverlay;
renderOverlay=function(){originalRenderOverlayV3();setTimeout(()=>enhanceDataTables(document),0)}
const originalRenderSectionV3=renderSection;
renderSection=function(){const role=state.role,sec=state.section;
 if(role==='employee'&&sec==='Zamówienia i vouchery')return employeeOrdersViewV3();
 if(role==='employee'&&sec==='Portfel i budżety')return employeeWalletViewV3();
 if(sec==='Edytor danych Excel'||sec==='Paczki i importy')return excelEditorView();
 if((role==='operations'&&sec==='Centrum zamówień')||(role==='partner'&&sec==='Zamówienia'))return connectedOrdersView();
 if(role==='hr'&&sec==='Budżety i finansowanie')return fundingView();
 if(role==='hr'&&sec==='Pracownicy i grupy')return linkedEmployeesView();
 if(role==='hr'&&sec==='Prezenty zbiorcze')return collectiveGiftsView();
 if(role==='operations'&&sec==='Dostawy i wysyłki')return deliveriesView();
 if(role==='bok'&&sec==='Wyszukiwarka globalna')return globalSearchViewV3();
 if(role==='bok'&&['Zgłoszenia','Reklamacje','Wymiany kodów','Ponowne wysyłki','Historia klienta','SLA i eskalacje'].includes(sec))return supportFlowView(sec);
 if(role==='finance'&&['Faktury','Marże i prowizje','Rozliczenia partnerów','Zasilenia i depozyty','Korekty i zwroty','Eksport ERP','Uzgodnienia'].includes(sec))return financeFlowView(sec);
 const html=originalRenderSectionV3();return html.includes('Moduł jest włączony w zintegrowanej nawigacji')?connectedPlaceholder(sec):html
}
const originalRenderV3=render;
render=function(){originalRenderV3();setTimeout(()=>enhanceDataTables(document),0)}

document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(el('moduleShell'))closeModule();else if(state.modal)closeModal();else if(state.drawer)closeDrawer();else if(state.mobileMenu){state.mobileMenu=false;render()}}});
render();
;


