function languageControl(){return `<select class="ub-lang-select" aria-label="${ubt('language')}" onchange="setLanguage(this.value)"><option value="pl" ${state.lang==='pl'?'selected':''}>PL</option><option value="en" ${state.lang==='en'?'selected':''}>EN</option><option value="de" ${state.lang==='de'?'selected':''}>DE</option></select>`}

