function empStore(){try{return JSON.parse(localStorage.getItem('upbonus_employee_engagement')||'{}')}catch(e){return {}}}
function saveEmpStore(v){localStorage.setItem('upbonus_employee_engagement',JSON.stringify(v))}
function empData(){const d=empStore();return {favorites:d.favorites||['PRD-EMP','PRD-WAK'],recentSearches:d.recentSearches||['karta dla dziecka','sport','wakacje'],recentPurchases:d.recentPurchases||['PRD-EMP','PRD-WAK'],selectedNominal:d.selectedNominal||100}}
function updateEmpData(patch){saveEmpStore({...empData(),...patch})}
function isFavorite(id){return empData().favorites.includes(id)}
function toggleFavorite(id,event){event?.stopPropagation();const d=empData(),f=d.favorites.includes(id)?d.favorites.filter(x=>x!==id):[...d.favorites,id];updateEmpData({favorites:f});render();toast(ubt('favorites'),d.favorites.includes(id)?'Usunięto z ulubionych':'Dodano do ulubionych')}
function setEmpCategory(cat){state.empCatalog.category=cat;state.empCatalog.favoritesOnly=false;render()}
function setEmpSort(v){state.empCatalog.sort=v;render()}
function toggleEmpFavFilter(){state.empCatalog.favoritesOnly=!state.empCatalog.favoritesOnly;render()}
function searchEmpProducts(v){state.empCatalog.query=v;const q=String(v||'').trim();if(q.length>2){const d=empData();updateEmpData({recentSearches:[q,...d.recentSearches.filter(x=>x.toLowerCase()!==q.toLowerCase())].slice(0,6)})}render()}
function useRecentSearch(q){state.empCatalog.query=q;state.section='Sklep i benefity';render()}
function filteredEmpProducts(){let list=[...EMP_PRODUCTS],f=state.empCatalog||{};if(f.category&&f.category!=='Wszystkie')list=list.filter(p=>p.category===f.category);if(f.query){const q=f.query.toLowerCase();list=list.filter(p=>`${p.name} ${p.category} ${p.desc}`.toLowerCase().includes(q))}if(f.favoritesOnly)list=list.filter(p=>isFavorite(p.id));if(f.sort==='priceAsc')list.sort((a,b)=>a.price-b.price);else if(f.sort==='priceDesc')list.sort((a,b)=>b.price-a.price);else if(f.sort==='name')list.sort((a,b)=>a.name.localeCompare(b.name,'pl'));else list.sort((a,b)=>(isFavorite(b.id)?1:0)-(isFavorite(a.id)?1:0));return list}
function openEmployeeProduct(id){const p=EMP_PRODUCTS.find(x=>x.id===id);if(!p)return;state.modal={type:'employeeProduct',data:{id,nominal:p.nominals[0]}};renderOverlay()}
function setProductNominal(n){if(state.modal?.type==='employeeProduct'){state.modal.data.nominal=Number(n);renderOverlay()}}
function buyEmployeeProduct(id,nominal){const p=EMP_PRODUCTS.find(x=>x.id===id),d=empData();if(!p)return;updateEmpData({recentPurchases:[id,...d.recentPurchases.filter(x=>x!==id)].slice(0,6)});closeModal();toast('Zamówienie utworzone',`${p.name} ${nominal} zł • ORD-2026-${Math.floor(10000+Math.random()*89999)}`);state.section='Zamówienia i vouchery';render()}
function repeatEmployeeOrder(id){const p=EMP_PRODUCTS.find(x=>x.id===id)||EMP_PRODUCTS[0];openEmployeeProduct(p.id);toast(ubt('reorder'),`Skopiowano poprzedni zakup: ${p.name}`)}

function campaignData(role){const common=[
 {title:'Powrót do szkoły',text:'Karty dla dzieci, elektronika, książki i sport — wykorzystaj środki przed końcem wakacji.',emoji:'🎒',bg:'linear-gradient(135deg,#552044,#8c4b77)',cta:'Zobacz kolekcję',action:"state.empCatalog.category='Dzieci';state.section='Sklep i benefity';render()"},
 {title:'Twoje środki mają termin',text:'220 zł z Programu Lunch jest ważne do 31 sierpnia. Nie pozwól, żeby przepadły.',emoji:'⏳',bg:'linear-gradient(135deg,#845207,#d99821)',cta:'Wykorzystaj środki',action:"selectSection('Sklep i benefity')"},
 {title:'Prezenty dokładnie takie, jak chcesz',text:'Dodaj logo, zdjęcie i życzenia do jednej karty lub całego zamówienia.',emoji:'🎁',bg:'linear-gradient(135deg,#5d1746,#7c3f8f)',cta:'Personalizuj',action:"openModule('gift')"}
 ];
 const admin={hr:[{title:'Kampania świadczeń szkolnych',text:'Przygotuj grupę pracowników, budżet i komunikację w jednym procesie.',emoji:'👨‍👩‍👧‍👦',bg:'linear-gradient(135deg,#254e67,#3f91b4)',cta:'Otwórz programy',action:"selectSection('Platformy i programy')"}],operations:[{title:'7 paczek kodów do akceptacji',text:'Zasada dwóch par oczu chroni magazyn przed błędnym wydaniem kodów.',emoji:'🔐',bg:'linear-gradient(135deg,#3b2659,#7555a3)',cta:'Sprawdź magazyn',action:"selectSection('Magazyn kart i kodów')"}],partner:[{title:'Uzupełnij zapas przed kampanią',text:'Prognoza pokazuje niski stan dla trzech popularnych nominałów.',emoji:'📦',bg:'linear-gradient(135deg,#375e42,#57a368)',cta:'Paczki kodów',action:"selectSection('Paczki kodów')"}],finance:[{title:'Uzgodnienie miesiąca',text:'Połącz zasilenia, zamówienia, marże i ERP wspólnym flow_id.',emoji:'🧾',bg:'linear-gradient(135deg,#514122,#a57a29)',cta:'Otwórz uzgodnienia',action:"selectSection('Uzgodnienia')"}],bok:[{title:'BOK widzi cały kontekst sprawy',text:'Wyszukaj pracownika, zamówienie, voucher i rozliczenie po jednym ID.',emoji:'🧑‍💻',bg:'linear-gradient(135deg,#22505a,#327d8c)',cta:'Wyszukaj sprawę',action:"selectSection('Wyszukiwarka globalna')"}],campaigns:[{title:'Zaplanuj kolejną okazję',text:'Slajdery desktop/mobile, segmenty i daty emisji w jednym Content Hub.',emoji:'📣',bg:'linear-gradient(135deg,#6c214d,#a63d70)',cta:'Bannery i slajdery',action:"selectSection('Bannery i slajdery')"}],superadmin:[{title:'White-label bez edycji kodu',text:'Logo, domeny, języki i moduły są konfigurowane dla każdej platformy.',emoji:'🎨',bg:'linear-gradient(135deg,#33265f,#6755ad)',cta:'Branding i domeny',action:"selectSection('Branding i domeny')"}]};
 return role==='employee'?common:[...(admin[role]||[]),...common.slice(1)];
}
function campaignSlider(role=state.role,compact=false){const slides=campaignData(role);const idx=Math.min(state.campaignSlide||0,slides.length-1);return `<section class="campaign-slider ${compact?'compact':''}" data-slider-role="${role}"><div class="campaign-track" style="transform:translateX(-${idx*100}%)">${slides.map((s,i)=>`<article class="campaign-slide" style="background:${s.bg}"><div><div class="eyebrow" style="color:rgba(255,255,255,.75)">${role==='employee'?'POLECANE DLA CIEBIE':'KOMUNIKAT PLATFORMY'}</div><h2>${esc(s.title)}</h2><p>${esc(s.text)}</p><button class="campaign-cta" onclick="${s.action}">${esc(s.cta)}</button><div class="ub-slider-admin-note">${esc(ubt('allPanels'))}</div></div><div class="campaign-visual">${s.emoji}</div></article>`).join('')}</div><div class="campaign-dots">${slides.map((_,i)=>`<button class="${i===idx?'active':''}" onclick="setCampaignSlide(${i})" aria-label="Slajd ${i+1}"></button>`).join('')}</div><div class="campaign-arrows"><button onclick="moveCampaign(-1)">‹</button><button onclick="moveCampaign(1)">›</button></div></section>`}
function setCampaignSlide(i){const count=campaignData(state.role).length;state.campaignSlide=(i+count)%count;render()}
function moveCampaign(d){setCampaignSlide((state.campaignSlide||0)+d)}

function upcomingOccasions(){return [
 {date:'Sierpień–wrzesień',title:'Powrót do szkoły',text:'Karty do Smyka, Empiku, Decathlonu i sklepów elektronicznych.',emoji:'🎒',cat:'Dzieci'},
 {date:'Listopad–grudzień',title:'Święta i Mikołajki',text:'Prezenty personalizowane oraz karty dla bliskich i współpracowników.',emoji:'🎄',cat:'Prezenty'},
 {date:'Maj–czerwiec',title:'Dzień Dziecka',text:'Karty dla dzieci, rodzinne atrakcje, sport i edukacja.',emoji:'🧸',cat:'Dzieci'}
]}
function occasionSection(){return `<section class="employee-section"><div class="employee-section-head"><div><h2>${ubt('occasions')}</h2><p>${ubt('occasionsDesc')}</p></div>${availableAccesses().includes('campaigns')?`<button class="link-btn" onclick="openRole('campaigns');state.section='Bannery i slajdery';render()">Content Hub</button>`:`<button class="link-btn" onclick="state.section='Sklep i benefity';render()">Zobacz wszystkie →</button>`}</div><div class="occasion-grid">${upcomingOccasions().map(x=>`<article class="occasion-card"><div><span class="occasion-date">${esc(x.date)}</span><h3>${esc(x.title)}</h3><p>${esc(x.text)}</p><button onclick="setEmpCategory('${x.cat}');state.section='Sklep i benefity';render()">${ubt('seeOffers')} →</button></div><div class="occasion-emoji">${x.emoji}</div></article>`).join('')}</div></section>`}
function miniProducts(ids){return `<div class="mini-product-row">${ids.map(id=>EMP_PRODUCTS.find(p=>p.id===id)).filter(Boolean).map(p=>`<article class="mini-product"><button class="favorite-heart ${isFavorite(p.id)?'active':''}" onclick="toggleFavorite('${p.id}',event)">${isFavorite(p.id)?'♥':'♡'}</button><div class="mini-logo">${p.icon}</div><h4>${esc(p.name)}</h4><p>${esc(p.category)} • od ${p.price} zł</p><button onclick="openEmployeeProduct('${p.id}')">${ubt('choose')}</button></article>`).join('')}</div>`}
function personalizationSection(){const d=empData();return `<section class="employee-section"><div class="employee-section-head"><div><h2>Twoja aktywność</h2><p>Wróć szybko do produktów, które już znasz.</p></div></div><div class="personal-tabs"><button class="active">${ubt('favorites')} (${d.favorites.length})</button><button>${ubt('recentSearches')}</button><button>${ubt('recentPurchases')}</button></div><h3 style="font-size:13px;margin:15px 0 0">${ubt('favorites')}</h3>${miniProducts(d.favorites.slice(0,4))}<div style="display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:13px"><div class="demo-note"><b>${ubt('recentSearches')}:</b><div class="category-scroll" style="margin-top:8px">${d.recentSearches.slice(0,4).map(q=>`<button class="category-chip" onclick="useRecentSearch('${esc(q).replace(/'/g,"\\'")}')">${esc(q)}</button>`).join('')}</div></div><div class="demo-note"><b>${ubt('recentPurchases')}:</b><div style="margin-top:8px;display:flex;gap:7px;flex-wrap:wrap">${d.recentPurchases.slice(0,4).map(id=>{const p=EMP_PRODUCTS.find(x=>x.id===id);return p?`<button class="compact-btn" onclick="repeatEmployeeOrder('${p.id}')">${p.icon} ${esc(p.name)}</button>`:''}).join('')}</div></div></div></section>`}
function expiryAlerts(){return `<div class="employee-alerts"><div class="employee-alert danger"><span class="alert-icon">⏳</span><div><b>${ubt('expiring')}</b><span>${ubt('useBefore')}</span></div><button onclick="state.empCatalog.category='Wszystkie';state.section='Sklep i benefity';render()">${ubt('seeOffers')} →</button></div><div class="employee-alert"><span class="alert-icon">📎</span><div><b>Wniosek wymaga uzupełnienia</b><span>Dodaj załącznik do 12.08.2026, aby HR mógł zakończyć weryfikację.</span></div><button onclick="selectSection('Wnioski i ZFŚS')">Uzupełnij →</button></div></div>`}

function employeeDashboardV4(){const first=esc(state.user.name.split(' ')[0]);return `<div class="employee-dashboard">${expiryAlerts()}${campaignSlider('employee',false)}<section class="employee-welcome"><div class="employee-hero"><div class="eyebrow" style="color:#eed5e8">TWÓJ PORTAL BENEFITOWY</div><h1>${ubt('welcome')}, ${first} 👋</h1><p>Masz <b style="color:#fff">570,00 zł</b> dostępnych środków, 4 aktywne programy i 2 nowe vouchery.</p><div class="hero-actions"><button class="primary-btn" onclick="selectSection('Sklep i benefity')">${ubt('shop')}</button><button class="secondary-btn" onclick="selectSection('Portfel i budżety')">${ubt('checkFunds')}</button></div></div><aside class="funds-card"><div class="funds-card-head"><div><span>${ubt('availableFunds')}</span><b>570,00 zł</b></div><span class="funds-icon">💳</span></div><div class="fund-line"><i class="fund-color"></i><div><b>Program Lunch</b><span>Ważne do 31.08.2026</span></div><strong>220 zł</strong></div><div class="fund-line"><i class="fund-color"></i><div><b>Prezent od firmy</b><span>Ważne do 31.12.2026</span></div><strong>300 zł</strong></div><div class="fund-line"><i class="fund-color"></i><div><b>Wellbeing</b><span>Ważne do 30.09.2026</span></div><strong>50 zł</strong></div><button class="link-btn" onclick="selectSection('Portfel i budżety')">${ubt('viewWallet')} →</button></aside></section><section class="employee-section"><div class="employee-section-head"><div><h2>Co chcesz zrobić?</h2><p>Najważniejsze funkcje zawsze pod ręką.</p></div></div><div class="employee-quick-grid"><button class="employee-quick" onclick="selectSection('Sklep i benefity')"><span class="quick-symbol">🛍️</span><b>Kup benefit</b><span>Karty, vouchery i usługi</span></button><button class="employee-quick" onclick="selectSection('Odbierz upominek')"><span class="quick-symbol">🎁</span><b>Odbierz upominek</b><span>Wybierz prezent od firmy</span></button><button class="employee-quick" onclick="selectSection('E-konto i karta')"><span class="quick-symbol">💳</span><b>Moja karta</b><span>Saldo, PIN i transakcje</span></button><button class="employee-quick" onclick="selectSection('Wnioski i ZFŚS')"><span class="quick-symbol">📝</span><b>Złóż wniosek</b><span>ZFŚS i dofinansowania</span></button></div></section>${occasionSection()}${personalizationSection()}<section class="employee-section"><div class="employee-section-head"><div><h2>Polecane dla Ciebie</h2><p>Na podstawie programów, budżetów i ostatniej aktywności.</p></div><button class="link-btn" onclick="selectSection('Sklep i benefity')">Zobacz wszystko →</button></div>${employeeProductGridV4(8)}</section></div>`}

function employeeProductGridV4(limit=99){const products=filteredEmpProducts().slice(0,limit);return `<div class="benefit-grid">${products.length?products.map(p=>`<article class="benefit-card"><button class="favorite-heart ${isFavorite(p.id)?'active':''}" onclick="toggleFavorite('${p.id}',event)">${isFavorite(p.id)?'♥':'♡'}</button><div class="benefit-cover">${p.icon}<span class="discount">${esc(p.badge)}</span></div><div class="benefit-body"><h3>${esc(p.name)}</h3><p>${esc(p.desc)}</p><div class="benefit-bottom"><b>od ${p.price} zł</b><button onclick="openEmployeeProduct('${p.id}')">${ubt('choose')}</button></div></div></article>`).join(''):`<div class="empty-catalog">Brak produktów dla wybranych filtrów.</div>`}</div>`}
function employeeBenefitsViewV4(){const cats=['Wszystkie',...new Set(EMP_PRODUCTS.map(p=>p.category))];return `<div class="employee-dashboard">${campaignSlider('employee',true)}<div class="page-head"><div><div class="eyebrow">SKLEP I BENEFITY</div><h1>Wybierz coś dla siebie</h1><p>Płać środkami z programów, łącz e-konta lub dopłać prywatnie.</p></div><div class="page-actions"><button class="secondary-btn" onclick="openModule('gift')">Sklep personalizowanych prezentów</button></div></div><section class="employee-section"><div class="employee-catalog-controls"><div class="search"><span>${ICONS.search}</span><input value="${esc(state.empCatalog.query||'')}" placeholder="${ubt('search')}" onchange="searchEmpProducts(this.value)" onkeydown="if(event.key==='Enter')searchEmpProducts(this.value)" /></div><select onchange="setEmpSort(this.value)"><option value="popular" ${state.empCatalog.sort==='popular'?'selected':''}>${ubt('popular')}</option><option value="priceAsc" ${state.empCatalog.sort==='priceAsc'?'selected':''}>${ubt('priceAsc')}</option><option value="priceDesc" ${state.empCatalog.sort==='priceDesc'?'selected':''}>${ubt('priceDesc')}</option><option value="name" ${state.empCatalog.sort==='name'?'selected':''}>${ubt('nameAZ')}</option></select><button class="filter-favorite ${state.empCatalog.favoritesOnly?'active':''}" onclick="toggleEmpFavFilter()">♥ ${ubt('onlyFavorites')}</button><button class="secondary-btn" onclick="state.empCatalog={query:'',category:'Wszystkie',sort:'popular',favoritesOnly:false};render()">Wyczyść</button></div><div class="category-scroll">${cats.map(c=>`<button class="category-chip ${state.empCatalog.category===c?'active':''}" onclick="setEmpCategory('${c.replace(/'/g,"\\'")}')">${c==='Wszystkie'?ubt('all'):esc(c)}</button>`).join('')}</div>${employeeProductGridV4()}</section></div>`}

const EMP_ORDER_HISTORY=[
 {date:'04.08.2026',id:'ORD-2026-08189',product:'Empik Gift Card',productId:'PRD-EMP',value:100,status:'Dostarczone',funding:'e-konto 100 zł'},
 {date:'29.07.2026',id:'ORD-2026-08192',product:'Personalizowany prezent',productId:'PRD-SUP',value:200,status:'W realizacji',funding:'Prezent od firmy'},
 {date:'14.07.2026',id:'ORD-2026-07811',product:'Wakacje.pl Gift Card',productId:'PRD-WAK',value:500,status:'Dostarczone',funding:'e-konto 300 zł + karta 200 zł'},
 {date:'02.06.2026',id:'ORD-2026-06101',product:'Decathlon Gift Card',productId:'PRD-DEC',value:150,status:'Dostarczone',funding:'Wellbeing + własne'},
 {date:'28.05.2026',id:'ORD-2026-05831',product:'Smyk Gift Card',productId:'PRD-SMY',value:100,status:'Anulowane',funding:'Prezent od firmy'}
];
function filterEmployeeOrders(v){state.empOrderFilters.query=v;render()}
function setEmployeeOrderStatus(v){state.empOrderFilters.status=v;render()}
function setEmployeeOrderSort(v){state.empOrderFilters.sort=v;render()}
function filteredEmployeeOrders(){let a=[...EMP_ORDER_HISTORY],f=state.empOrderFilters;if(f.query){const q=f.query.toLowerCase();a=a.filter(x=>Object.values(x).join(' ').toLowerCase().includes(q))}if(f.status!=='Wszystkie')a=a.filter(x=>x.status===f.status);if(f.sort==='oldest')a.reverse();else if(f.sort==='valueDesc')a.sort((a,b)=>b.value-a.value);else if(f.sort==='valueAsc')a.sort((a,b)=>a.value-b.value);return a}
function employeeOrdersViewV4(){const orders=filteredEmployeeOrders();return `<div class="employee-dashboard">${campaignSlider('employee',true)}${pageHead('Zamówienia i vouchery','Aktywne vouchery, historia zakupów, dostawy i ponowienie zamówienia.')}<section class="employee-section"><div class="employee-section-head"><div><h2>Aktywne vouchery</h2><p>Kody są widoczne wyłącznie dla właściciela konta.</p></div></div><div class="employee-order-grid"><article class="employee-order"><span class="voucher-logo">A</span><div><h3>Allegro Gift Card 100 zł</h3><p>ORD-2026-08189 • ważny do 04.08.2027</p></div><div class="order-status"><b>${ubt('ready')}</b><span><button class="link-btn" onclick="toast('Voucher','Kod: AL••••••92')">Pokaż voucher</button></span></div></article><article class="employee-order"><span class="voucher-logo">🎬</span><div><h3>Multikino — 2 bilety</h3><p>ORD-2026-08071 • ważne do 31.12.2026</p></div><div class="order-status"><b>${ubt('ready')}</b><span><button class="link-btn" onclick="toast('PDF','Przygotowano bezpieczny dokument do pobrania.')">Pobierz PDF</button></span></div></article></div></section><section class="employee-section"><div class="employee-section-head"><div><h2>${ubt('history')}</h2><p>Filtruj, sortuj, pobieraj i kupuj ponownie.</p></div><button class="secondary-btn" onclick="exportAllVisibleTables('excel')">Excel</button></div><div class="order-filterbar"><input value="${esc(state.empOrderFilters.query||'')}" placeholder="${ubt('orderSearch')}" onchange="filterEmployeeOrders(this.value)" /><select onchange="setEmployeeOrderStatus(this.value)"><option>Wszystkie</option>${['Dostarczone','W realizacji','Anulowane'].map(x=>`<option ${state.empOrderFilters.status===x?'selected':''}>${x}</option>`).join('')}</select><select onchange="setEmployeeOrderSort(this.value)"><option value="newest">Najnowsze</option><option value="oldest" ${state.empOrderFilters.sort==='oldest'?'selected':''}>Najstarsze</option><option value="valueDesc" ${state.empOrderFilters.sort==='valueDesc'?'selected':''}>Wartość malejąco</option><option value="valueAsc" ${state.empOrderFilters.sort==='valueAsc'?'selected':''}>Wartość rosnąco</option></select><button class="secondary-btn" onclick="state.empOrderFilters={query:'',status:'Wszystkie',sort:'newest'};render()">Wyczyść</button></div><div class="table-wrap"><table class="data-table order-history-table"><thead><tr><th>Data</th><th>Zamówienie</th><th>Produkt</th><th>Finansowanie</th><th>Wartość</th><th>Status</th><th>Akcje</th></tr></thead><tbody>${orders.map(o=>`<tr><td>${o.date}</td><td><button class="link-btn" onclick="showFlow('FLOW-ORDER-001')">${o.id}</button></td><td>${esc(o.product)}</td><td>${esc(o.funding)}</td><td>${money(o.value)}</td><td><span class="status ${o.status==='Dostarczone'?'green':o.status==='Anulowane'?'gray':'amber'}">${o.status}</span></td><td><button class="reorder-btn" onclick="repeatEmployeeOrder('${o.productId}')">${ubt('reorder')}</button></td></tr>`).join('')}</tbody></table></div></section></div>`}

function productModalV4(data){const p=EMP_PRODUCTS.find(x=>x.id===data.id);if(!p)return '';const n=Number(data.nominal||p.nominals[0]);return `<div class="modal-backdrop" onclick="if(event.target===this)closeModal()"><section class="modal standard"><div class="modal-head"><div><span class="eyebrow">${esc(p.category)}</span><h2>${esc(p.name)}</h2></div><button class="modal-close" onclick="closeModal()">×</button></div><div class="modal-body"><div class="product-detail-grid"><div class="product-detail-visual">${p.icon}</div><div><p style="color:var(--brand-muted);line-height:1.5">${esc(p.desc)}</p><b>Wybierz nominał</b><div class="nominal-grid">${p.nominals.map(x=>`<button class="nominal-btn ${x===n?'active':''}" onclick="setProductNominal(${x})">${x} zł</button>`).join('')}</div><div class="demo-note"><b>Źródła płatności:</b> Program Lunch, Prezent od firmy, Wellbeing oraz dopłata własna — zgodnie z regułami programu.</div></div></div></div><div class="modal-foot"><button class="secondary-btn" onclick="toggleFavorite('${p.id}');closeModal()">${isFavorite(p.id)?'Usuń z ulubionych':'Dodaj do ulubionych'}</button><button class="primary-btn" onclick="buyEmployeeProduct('${p.id}',${n})">Kup za ${n} zł</button></div></section></div>`}

function aiHumanIcon(){return `<svg viewBox="0 0 64 64" fill="none" aria-hidden="true"><circle cx="32" cy="22" r="10" fill="currentColor" opacity=".95"/><path d="M14 53c1.8-12 9-18 18-18s16.2 6 18 18" stroke="currentColor" stroke-width="7" stroke-linecap="round"/><path d="M48 16l3-3m-3 15l4 2M16 16l-3-3m3 15l-4 2" stroke="currentColor" stroke-width="3" stroke-linecap="round" opacity=".75"/></svg>`}
function toggleAi(){state.aiOpen=!state.aiOpen;appendGlobalEnhancements()}
function askAi(text){const input=el('ubAiInput');const q=String(text||input?.value||'').trim();if(!q)return;state.aiMessages.push({who:'user',text:q});let reply='';const l=q.toLowerCase();if(l.includes('środk')||l.includes('saldo')||l.includes('fund'))reply='Masz 570,00 zł. Najpilniejsze jest 220 zł z Programu Lunch ważne do 31.08.2026.';else if(l.includes('dzieck')||l.includes('gift'))reply='Polecam karty Smyk, Empik i Decathlon. Mogę od razu otworzyć kategorię Dzieci.';else if(l.includes('zamów')||l.includes('order'))reply='Ostatnie zamówienie ORD-2026-08189 jest dostarczone. Pełną historię znajdziesz w Zamówieniach i voucherach.';else reply='Znalazłam kilka pasujących opcji. Użyj wyszukiwarki benefitów albo wybierz kategorię, a zawężę wyniki.';state.aiMessages.push({who:'ai',text:reply});appendGlobalEnhancements()}
function aiPanelHtml(){return `<div class="ub-ai-panel"><div class="ub-ai-head"><span class="ai-face">${aiHumanIcon()}</span><div><b>Asystent Up Bonus</b><span>Online • dane zgodne z Twoimi dostępami</span></div><button class="ub-ai-close" onclick="toggleAi()">×</button></div><div class="ub-ai-body"><div class="ub-ai-msg">${esc(ubt('aiHello'))}</div>${state.aiMessages.map(m=>`<div class="ub-ai-msg ${m.who==='user'?'user':''}">${esc(m.text)}</div>`).join('')}<div class="ub-ai-chips"><button onclick="askAi('Ile mam środków?')">Ile mam środków?</button><button onclick="askAi('Karta dla dziecka')">Prezent dla dziecka</button><button onclick="askAi('Status zamówienia')">Status zamówienia</button></div></div><div class="ub-ai-input"><input id="ubAiInput" placeholder="${ubt('aiPlaceholder')}" onkeydown="if(event.key==='Enter')askAi()"/><button onclick="askAi()">${ubt('send')}</button></div></div>`}
function appendGlobalEnhancements(){document.querySelectorAll('.ub-float-tools,.ub-ai-panel,.ub-login-lang').forEach(x=>x.remove());const tools=document.createElement('div');tools.className='ub-float-tools';tools.innerHTML=`<button class="ub-ai-human" onclick="toggleAi()" aria-label="Asystent AI">${aiHumanIcon()}<span class="ai-pulse"></span></button>`;document.body.appendChild(tools);if(state.aiOpen)document.body.insertAdjacentHTML('beforeend',aiPanelHtml());if(!state.loggedIn){const d=document.createElement('div');d.className='ub-login-lang';d.style.cssText='position:fixed;right:18px;top:18px;z-index:4000';d.innerHTML=languageControl();document.body.appendChild(d)}wireFallbackButtons();document.documentElement.lang=state.lang}
function wireFallbackButtons(){document.querySelectorAll('button').forEach(b=>{if(b.dataset.ubFallback||b.getAttribute('onclick')||b.type==='submit'||b.closest('.campaign-slider')||b.closest('.ub-ai-panel'))return;b.dataset.ubFallback='1';b.addEventListener('click',()=>{const txt=b.textContent.trim();if(/Pobierz historię/i.test(txt)){toast('Eksport','Przygotowano historię do pobrania.');return}if(/Otwórz/i.test(txt)){toast('Szczegóły','Otworzono wskazaną sekcję lub instrukcję.');return}if(/Wybierz|Zobacz warianty/i.test(txt)){openEmployeeProduct(EMP_PRODUCTS[0].id);return}if(/Edytuj/i.test(txt)){toast('Edycja','Otworzono formularz edycji z audytem zmian.');return}toast('Funkcja uruchomiona',txt||'Operacja została wykonana.')})})}
function applyCommonTranslations(){if(state.lang==='pl')return;const exact=state.lang==='en'?{'Dla Ciebie':'For you','Sklep i benefity':'Shop & benefits','Portfel i budżety':'Wallet & budgets','E-konto i karta':'E-wallet & card','Odbierz upominek':'Claim a gift','Zamówienia i vouchery':'Orders & vouchers','Wnioski i ZFŚS':'Requests & Social Fund','Wellbeing':'Wellbeing','Pomoc':'Help','Wyloguj':'Log out','Strona główna':'Home','Zmień dostęp':'Switch access','Twoje benefity':'Your benefits','Menu panelu':'Panel menu','Powiadomienia':'Notifications'}:{'Dla Ciebie':'Für dich','Sklep i benefity':'Shop & Benefits','Portfel i budżety':'Wallet & Budgets','E-konto i karta':'E-Wallet & Karte','Odbierz upominek':'Geschenk auswählen','Zamówienia i vouchery':'Bestellungen & Gutscheine','Wnioski i ZFŚS':'Anträge & Sozialfonds','Wellbeing':'Wellbeing','Pomoc':'Hilfe','Wyloguj':'Abmelden','Strona główna':'Startseite','Zmień dostęp':'Zugang wechseln','Twoje benefity':'Deine Benefits','Menu panelu':'Panelmenü','Powiadomienia':'Benachrichtigungen'};document.querySelectorAll('.menu-btn span,.menu-group-label,.back-accounts').forEach(elm=>{const txt=elm.textContent.trim();if(exact[txt])elm.textContent=exact[txt]})}

const previousEmployeeTopbarV4=employeeTopbar;
employeeTopbar=function(){const t=tenant();return `<header class="topbar employee-topbar"><button class="icon-btn mobile-menu-btn" onclick="toggleMobile()" aria-label="Menu">${icon('menu')}</button><button class="topbar-brand" style="border:0;background:transparent;text-align:left;padding:0;cursor:pointer" onclick="state.section='Dla Ciebie';render()"><span class="brand-symbol">${esc(t.logo)}</span><span><b>${esc(t.short)}</b><small>Portal pracownika</small></span></button><div class="top-search"><span>${ICONS.search}</span><input placeholder="${ubt('search')}" onkeydown="if(event.key==='Enter'){state.empCatalog.query=this.value;state.section='Sklep i benefity';render()}" /></div><div class="top-actions">${languageControl()}<button class="employee-balance-pill" onclick="selectSection('Portfel i budżety')"><span class="wallet-dot">${ICONS.wallet}</span><span><span>${ubt('availableFunds')}</span><b>570,00 zł</b></span></button><button class="icon-btn" onclick="selectSection('Zamówienia i vouchery')" title="Koszyk i zamówienia">${icon('order')}<span class="badge-dot">2</span></button><button class="icon-btn" onclick="showModal('notifications')" title="Powiadomienia">${icon('bell')}<span class="badge-dot">${state.notifications}</span></button><button class="profile-btn" onclick="showModal('profile')"><span class="avatar">${esc(state.user.name.split(' ').map(x=>x[0]).join('').slice(0,2).toUpperCase())}</span><span><b>${esc(state.user.name)}</b><span>${esc(t.name)}</span></span></button></div></header>`}
const previousTopbarV4=topbar;
topbar=function(opts={}){let h=previousTopbarV4(opts);return h.replace('<div class="top-actions">','<div class="top-actions">'+languageControl())}

const previousModalHtmlV4=modalHtml;
modalHtml=function(){if(state.modal?.type==='employeeProduct')return productModalV4(state.modal.data);return previousModalHtmlV4()}
const previousRenderSectionV4=renderSection;
renderSection=function(){const role=state.role,sec=state.section;if(role==='employee'&&sec==='Dla Ciebie')return employeeDashboardV4();if(role==='employee'&&sec==='Sklep i benefity')return employeeBenefitsViewV4();if(role==='employee'&&sec==='Zamówienia i vouchery')return employeeOrdersViewV4();const html=previousRenderSectionV4();return `${campaignSlider(role,true)}${html}`}
const previousRenderV4=render;
render=function(){previousRenderV4();setTimeout(()=>{appendGlobalEnhancements();applyCommonTranslations();enhanceDataTables(document)},0)}

let ubAutoSlider=null;
function startCampaignAutoplay(){clearInterval(ubAutoSlider);ubAutoSlider=setInterval(()=>{if(document.querySelector('.campaign-slider')&&!state.modal&&!state.drawer&&!state.aiOpen){const count=campaignData(state.role).length;state.campaignSlide=((state.campaignSlide||0)+1)%count;const track=document.querySelector('.campaign-track');if(track){track.style.transform=`translateX(-${state.campaignSlide*100}%)`;document.querySelectorAll('.campaign-dots button').forEach((b,i)=>b.classList.toggle('active',i===state.campaignSlide))}}},6000)}
startCampaignAutoplay();
render();
;

