miniProducts=function(ids){return `<div class="mini-product-row">${ids.map(id=>EMP_PRODUCTS.find(p=>p.id===id)).filter(Boolean).map(raw=>{const p=localizedProduct(raw);return `<article class="mini-product"><button class="favorite-heart ${isFavorite(p.id)?'active':''}" onclick="toggleFavorite('${p.id}',event)">${isFavorite(p.id)?'♥':'♡'}</button><div class="mini-logo">${p.icon}</div><h4>${esc(p.name)}</h4><p>${esc(p.category)} • ${state.lang==='en'?'from':state.lang==='de'?'ab':'od'} ${p.price} zł</p><button onclick="openEmployeeProduct('${p.id}')">${ubt('choose')}</button></article>`}).join('')}</div>`}
employeeProductGridV4=function(limit=99){const products=filteredEmpProducts().slice(0,limit);return `<div class="benefit-grid">${products.length?products.map(raw=>{const p=localizedProduct(raw);return `<article class="benefit-card"><button class="favorite-heart ${isFavorite(p.id)?'active':''}" onclick="toggleFavorite('${p.id}',event)">${isFavorite(p.id)?'♥':'♡'}</button><div class="benefit-cover">${p.icon}<span class="discount">${esc(p.badge)}</span></div><div class="benefit-body"><h3>${esc(p.name)}</h3><p>${esc(p.desc)}</p><div class="benefit-bottom"><b>${state.lang==='en'?'from':state.lang==='de'?'ab':'od'} ${p.price} zł</b><button onclick="openEmployeeProduct('${p.id}')">${ubt('choose')}</button></div></div></article>`}).join(''):`<div class="empty-catalog">${state.lang==='en'?'No products match the selected filters.':state.lang==='de'?'Keine Produkte entsprechen den Filtern.':'Brak produktów dla wybranych filtrów.'}</div>`}</div>`}
