employeeBenefitsViewV4=function(){const cats=['Wszystkie',...new Set(EMP_PRODUCTS.map(p=>p.category))];const title=state.lang==='en'?'Choose something for yourself':state.lang==='de'?'Wähle etwas für dich':'Wybierz coś dla siebie';const desc=state.lang==='en'?'Pay with program funds, combine e-wallets or add private funds.':state.lang==='de'?'Bezahle mit Programmguthaben, kombiniere Wallets oder zahle privat zu.':'Płać środkami z programów, łącz e-konta lub dopłać prywatnie.';return `<div class="employee-dashboard">${campaignSlider('employee',true)}<div class="page-head"><div><div class="eyebrow">SHOP & BENEFITS</div><h1>${title}</h1><p>${desc}</p></div><div class="page-actions"><button class="secondary-btn" onclick="openModule('gift')">${state.lang==='en'?'Personalized gift shop':state.lang==='de'?'Personalisierter Geschenkeshop':'Sklep personalizowanych prezentów'}</button></div></div><section class="employee-section"><div class="employee-catalog-controls"><div class="search"><span>${ICONS.search}</span><input value="${esc(state.empCatalog.query||'')}" placeholder="${ubt('search')}" onchange="searchEmpProducts(this.value)" onkeydown="if(event.key==='Enter')searchEmpProducts(this.value)" /></div><select onchange="setEmpSort(this.value)"><option value="popular" ${state.empCatalog.sort==='popular'?'selected':''}>${ubt('popular')}</option><option value="priceAsc" ${state.empCatalog.sort==='priceAsc'?'selected':''}>${ubt('priceAsc')}</option><option value="priceDesc" ${state.empCatalog.sort==='priceDesc'?'selected':''}>${ubt('priceDesc')}</option><option value="name" ${state.empCatalog.sort==='name'?'selected':''}>${ubt('nameAZ')}</option></select><button class="filter-favorite ${state.empCatalog.favoritesOnly?'active':''}" onclick="toggleEmpFavFilter()">♥ ${ubt('onlyFavorites')}</button><button class="secondary-btn" onclick="state.empCatalog={query:'',category:'Wszystkie',sort:'popular',favoritesOnly:false};render()">${state.lang==='en'?'Clear':state.lang==='de'?'Löschen':'Wyczyść'}</button></div><div class="category-scroll">${cats.map(c=>`<button class="category-chip ${state.empCatalog.category===c?'active':''}" onclick="setEmpCategory('${c.replace(/'/g,"\\'")}')">${esc(localizedCategory(c))}</button>`).join('')}</div>${employeeProductGridV4()}</section></div>`}
productModalV4=function(data){const raw=EMP_PRODUCTS.find(x=>x.id===data.id);if(!raw)return '';const p=localizedProduct(raw),n=Number(data.nominal||p.nominals[0]);const choose=state.lang==='en'?'Choose value':state.lang==='de'?'Betrag wählen':'Wybierz nominał';const sources=state.lang==='en'?'Payment sources: Lunch Program, Company Gift, Wellbeing and private top-up according to program rules.':state.lang==='de'?'Zahlungsquellen: Lunch-Programm, Firmengeschenk, Wellbeing und private Zuzahlung gemäß Programmregeln.':'Źródła płatności: Program Lunch, Prezent od firmy, Wellbeing oraz dopłata własna — zgodnie z regułami programu.';return `<div class="modal-backdrop" onclick="if(event.target===this)closeModal()"><section class="modal standard"><div class="modal-head"><div><span class="eyebrow">${esc(p.category)}</span><h2>${esc(p.name)}</h2></div><button class="modal-close" onclick="closeModal()">×</button></div><div class="modal-body"><div class="product-detail-grid"><div class="product-detail-visual">${p.icon}</div><div><p style="color:var(--brand-muted);line-height:1.5">${esc(p.desc)}</p><b>${choose}</b><div class="nominal-grid">${p.nominals.map(x=>`<button class="nominal-btn ${x===n?'active':''}" onclick="setProductNominal(${x})">${x} zł</button>`).join('')}</div><div class="demo-note"><b>${esc(sources)}</b></div></div></div></div><div class="modal-foot"><button class="secondary-btn" onclick="toggleFavorite('${p.id}');closeModal()">${isFavorite(p.id)?(state.lang==='en'?'Remove from favorites':state.lang==='de'?'Aus Favoriten entfernen':'Usuń z ulubionych'):(state.lang==='en'?'Add to favorites':state.lang==='de'?'Zu Favoriten hinzufügen':'Dodaj do ulubionych')}</button><button class="primary-btn" onclick="buyEmployeeProduct('${p.id}',${n})">${state.lang==='en'?'Buy for':state.lang==='de'?'Kaufen für':'Kup za'} ${n} zł</button></div></section></div>`}

