  DEFAULT_TENANTS.sharp=DEFAULT_TENANTS.sharp||{id:'sharp',name:'Sharp Benefits',short:'SHARP',mode:'white_label',primary:'#b4202a',accent:'#d7555d',soft:'#fff0f1',logo:'SHARP',domain:'sharp.upbonus.pl',description:'Pilotażowa platforma white-label',hero:'Oferty i świadczenia dla pracowników Sharp.',modules:['employee','hr','campaigns']};

