  const MODULE_ROLES={
    'Organizacja':['hr'],'Wnioski i ZFŚS':['hr'],'Komunikacja':['hr'],
    'Magazyn kart i kodów':['operations'],'Błędy integracji':['operations'],'Personalizacja PDF':['operations'],
    'Paczki kodów':['partner'],'Reklamacje':['partner'],'Rozliczenia':['partner'],
    'Kampanie':['campaigns'],'Segmenty':['campaigns'],'Szablony treści':['campaigns'],'Kalendarz publikacji':['campaigns'],
    'Integracje':['partner','superadmin'],'Bezpieczeństwo':['superadmin'],'Baza wiedzy':['bok']
  };
  function moduleDefinition(section){
    const roles=MODULE_ROLES[section];if(!roles||!roles.includes(state.role))return null;
    if(section==='Integracje'&&state.role==='partner')return {...MODULES.Integracje,title:'Integracje partnera',desc:'API partnera, dostawa kodów, zamówienia, statusy, reklamacje i rozliczenia w ograniczonym zakresie.'};
    return MODULES[section];
  }
  function statusClass(v){v=String(v);return /Aktyw|Zgod|Zreal|Rozlicz|Zamk|OK|Uzgod/.test(v)?'green':/Błąd|Kwar|Wstrzym|Brak|Otwarte|Różn/.test(v)?'red':/Test|Zaplan|W toku|Uwaga|akcept|Konfigur|Niski|Szkic/.test(v)?'amber':'purple'}
  function v11ModuleView(section){
    const d=moduleDefinition(section);if(!d)return '';
    const slider=typeof campaignSlider==='function'?campaignSlider(state.role,true):'';
    const actions=`<button class="secondary-btn" onclick="v11ExportCurrent()">⇩ Excel</button><button class="primary-btn" onclick="v11OpenAction('${safe(section)}')">＋ ${L('Nowa operacja','New operation','Neuer Vorgang')}</button>`;
    return `${slider}${pageHead(d.title,d.desc,actions)}<section class="v11-module-hero"><article class="v11-module-card accent"><div style="font-size:34px">${d.icon}</div><h2 style="margin-top:12px">${safe(d.title)}</h2><p>${safe(d.desc)}</p><div class="v11-tag-row"><span class="v11-tag">tenant_id</span><span class="v11-tag">platform_id</span><span class="v11-tag">role_scope</span><span class="v11-tag">audit_log</span></div></article><aside class="v11-module-card"><h3>${L('Kontrola modułu','Module controls','Modulkontrolle')}</h3><div class="v11-side-list"><div class="v11-side-item"><span>✓</span><div><b>${L('Dane odseparowane per klient i platforma','Data isolated per client and platform','Daten je Kunde und Plattform getrennt')}</b><small>${L('Widok respektuje tenant_id, platform_id i uprawnienia roli.','The view respects tenant_id, platform_id and role permissions.','Ansicht berücksichtigt tenant_id, platform_id und Rollenrechte.')}</small></div></div><div class="v11-side-item"><span>↻</span><div><b>${L('Eksport, filtry i historia operacji','Export, filters and operation history','Export, Filter und Vorgangshistorie')}</b><small>${L('Każda akcja ma identyfikator, użytkownika i czas wykonania.','Every action has an identifier, user and timestamp.','Jede Aktion hat Kennung, Nutzer und Zeitstempel.')}</small></div></div></div></aside></section><section class="v11-kpi-grid">${d.kpis.map(k=>`<article class="v11-kpi"><span>${safe(k[0])}</span><b>${safe(k[1])}</b><small>${safe(k[2])}</small></article>`).join('')}</section><section class="v11-process">${d.process.map((x,i)=>`<article><i>${i+1}</i><b>${safe(x[0])}</b><span>${safe(x[1])}</span></article>`).join('')}</section><section class="v11-grid"><div><div class="v11-actionbar"><div class="search"><span>${ICONS.search}</span><input placeholder="${L('Filtruj dane w module…','Filter module data…','Moduldaten filtern…')}" oninput="v11FilterTable(this)"></div><select onchange="v11FilterStatus(this)"><option>${L('Wszystkie statusy','All statuses','Alle Status')}</option>${[...new Set(d.rows.map(r=>r[r.length-1]))].map(x=>`<option>${safe(x)}</option>`).join('')}</select><button class="compact-btn" onclick="v11ExportCurrent()">Excel</button></div><div class="table-wrap"><table class="data-table v11-module-table"><thead><tr>${d.columns.map(x=>`<th>${safe(x)}</th>`).join('')}<th>${L('Akcje','Actions','Aktionen')}</th></tr></thead><tbody>${d.rows.map((r,ri)=>`<tr>${r.map((x,ci)=>`<td>${ci===0?`<span class="td-title">${safe(x)}</span>`:ci===r.length-1?`<span class="status ${statusClass(x)}">${safe(x)}</span>`:safe(x)}</td>`).join('')}<td><button class="link-btn" onclick="v11OpenAction('${safe(section)}','${ri}')">${L('Szczegóły','Details','Details')}</button></td></tr>`).join('')}</tbody></table></div></div><aside class="v11-module-card"><h3>${L('Gotowość do MVP','MVP readiness','MVP-Bereitschaft')}</h3><div class="v11-checklist" style="margin-top:11px"><div class="v11-check"><span>✓</span><div><b>${L('Pełny widok procesu','Complete process view','Vollständige Prozessansicht')}</b><small>${L('Ekran pokazuje dane, statusy i akcje roli.','Screen shows data, statuses and role actions.','Ansicht zeigt Daten, Status und Rollenaktionen.')}</small></div><em>DEMO</em></div><div class="v11-check"><span>✓</span><div><b>${L('Filtrowanie i eksport','Filtering and export','Filter und Export')}</b><small>${L('Przygotowane do weryfikacji z użytkownikami biznesowymi.','Ready for business-user validation.','Bereit zur Validierung mit Fachanwendern.')}</small></div><em>MVP</em></div><div class="v11-check"><span>!</span><div><b>${L('Backend i integracje produkcyjne','Production backend and integrations','Produktions-Backend und Integrationen')}</b><small>${L('W prototypie są symulowane i wymagają implementacji po zakupie.','Simulated in the prototype and require implementation after purchase.','Im Prototyp simuliert und nach Kauf zu implementieren.')}</small></div><em>BUILD</em></div></div></aside></section>`;
  }

