  function v11WellbeingEnabled(){const c=state.v7?.platforms?.[state.tenant],id=state.v7?.activeByTenant?.[state.tenant],p=c?.platforms?.find(x=>x.id===id)||c?.platforms?.[0];return !p?.features?.wellbeing||Object.values(p.features.wellbeing).some(Boolean)}
