  function groupOpen45(group){
    if(state.v45.openGroups[group.id]!==undefined)return !!state.v45.openGroups[group.id];
    return group.items.some(([route])=>route===state.section)||true;
  }
  window.v45ToggleMenuGroup=function(id){state.v45.openGroups[id]=!state.v45.openGroups[id];if(typeof persist==='function')persist();render()};

  const baseSidebar45=window.sidebar;
  window.sidebar=function(){
    const groups=MENUS45[state.role];
    if(!groups)return baseSidebar45();
    const role=ROLE_DEFS[state.role]||{name:'Panel'};
    const multi=typeof hasMultipleAccesses==='function'&&hasMultipleAccesses();
    const t=typeof tenant==='function'?tenant():{name:'Up Bonus'};
    return `<aside class="sidebar ${state.mobileMenu?'open':''}"><div class="sidebar-head">${multi?`<button class="back-accounts" onclick="openAccounts()">${icon('back')} Przełącz panel</button>`:''}<div class="sidebar-context"><b>${E45(role.name)}</b><span>${E45(t.name||'Up Bonus')}</span></div></div><nav class="sidebar-menu"><div class="menu-group-label">Menu zarządzania</div>${groups.map(group=>{const open=groupOpen45(group);return `<section class="v45-menu-group"><button class="v45-menu-parent ${open?'open':''}" onclick="v45ToggleMenuGroup('${group.id}')">${icon(group.icon)}<span>${E45(group.label)}</span><span class="v45-caret">›</span></button><div class="v45-menu-children ${open?'open':''}">${group.items.map(([route,ic])=>`<button class="menu-btn ${state.section===route?'active':''} ${/Prezenty i personalizacja|Odbierz upominek/.test(route)?'v45-ecosystem':''}" onclick="selectSection('${E45(route).replace(/'/g,"\'")}')">${icon(ic)}<span>${E45(route)}</span>${route==='Reklamacje'?'<span class="count">4</span>':''}</button>`).join('')}</div></section>`}).join('')}</nav><div class="sidebar-foot"><button class="menu-btn" onclick="logout()">${icon('logout')} <span>Wyloguj</span></button></div></aside><div class="sidebar-overlay ${state.mobileMenu?'open':''}" onclick="closeMobile()"></div>`;
  };

  function accountTabs45(){return `<div class="v45-account-tabs">${[['data','Moje dane'],['password','Zmiana hasła'],['consents','Centrum zgód'],['info','Centrum informacyjne']].map(([id,label])=>`<button class="${state.v45.accountTab===id?'active':''}" onclick="v45SetAccountTab('${id}')">${label}</button>`).join('')}</div>`}
  window.v45SetAccountTab=function(tab){state.v45.accountTab=tab;if(typeof persist==='function')persist();render()};
  window.v45OpenInformation=function(anchor){state.v45.accountTab='info';state.v45.infoAnchor=anchor||'privacy';state.section='Ustawienia';if(typeof persist==='function')persist();render()};

  function profileView45(){const p=state.v45.profile;return `<section class="v45-account-card"><h2>Moje dane</h2><p>Dane konta i dane potrzebne do obsługi e-konta oraz zamówionych kart.</p><div class="v45-profile-grid"><div class="field"><label>Imię i nazwisko</label><input id="v45Name" value="${E45(state.user?.name||'')}"></div><div class="field"><label>E-mail</label><input id="v45Email" type="email" value="${E45(state.user?.email||'')}"></div><div class="field"><label>Ulica</label><input id="v45Street" value="${E45(p.street)}"></div><div class="field"><label>Nr domu / mieszkania</label><input id="v45House" value="${E45(p.house)}"></div><div class="field"><label>Kod pocztowy</label><input id="v45Postal" value="${E45(p.postal)}"></div><div class="field"><label>Miasto</label><input id="v45City" value="${E45(p.city)}"></div><div class="field"><label>Województwo</label><input id="v45Province" value="${E45(p.province)}"></div><div class="field"><label>Data urodzenia</label><input id="v45Birth" type="date" value="${E45(p.birthDate)}"></div><div class="field"><label>Telefon</label><input id="v45Phone" value="${E45(p.phone)}"></div><div class="field"><label>Typ dokumentu tożsamości</label><select id="v45DocumentType"><option value="">Wybierz</option><option ${p.documentType==='Dowód osobisty'?'selected':''}>Dowód osobisty</option><option ${p.documentType==='Paszport'?'selected':''}>Paszport</option></select></div><div class="field"><label>Numer dokumentu tożsamości</label><input id="v45DocumentNo" value="${E45(p.documentNo)}"></div></div><button class="primary-btn" style="margin-top:15px" onclick="v45SaveProfile()">Zapisz dane</button></section>`}
  window.v45SaveProfile=function(){const p=state.v45.profile;p.street=document.getElementById('v45Street')?.value||'';p.house=document.getElementById('v45House')?.value||'';p.postal=document.getElementById('v45Postal')?.value||'';p.city=document.getElementById('v45City')?.value||'';p.province=document.getElementById('v45Province')?.value||'';p.birthDate=document.getElementById('v45Birth')?.value||'';p.phone=document.getElementById('v45Phone')?.value||'';p.documentType=document.getElementById('v45DocumentType')?.value||'';p.documentNo=document.getElementById('v45DocumentNo')?.value||'';state.user.name=document.getElementById('v45Name')?.value||state.user.name;state.user.email=document.getElementById('v45Email')?.value||state.user.email;if(typeof persist==='function')persist();render();toast('Dane zapisane','Profil użytkownika został zaktualizowany.')};

  function passwordView45(){return `<section class="v45-account-card" style="max-width:760px"><h2>Zmień hasło</h2><p>Nowe hasło powinno mieć co najmniej 10 znaków, cyfrę i znak specjalny.</p><div class="field"><label>Obecne hasło</label><input id="v45CurrentPassword" type="password" autocomplete="current-password"></div><div class="field" style="margin-top:12px"><label>Nowe hasło</label><input id="v45NewPassword" type="password" autocomplete="new-password"></div><div class="field" style="margin-top:12px"><label>Powtórz nowe hasło</label><input id="v45RepeatPassword" type="password" autocomplete="new-password"></div><button class="primary-btn" style="margin-top:15px" onclick="v45ChangePassword()">Zmień hasło</button></section>`}
  window.v45ChangePassword=function(){const cur=document.getElementById('v45CurrentPassword')?.value||'',a=document.getElementById('v45NewPassword')?.value||'',b=document.getElementById('v45RepeatPassword')?.value||'';if(!cur){toast('Podaj obecne hasło');return}if(a.length<10||!/[0-9]/.test(a)||!/[!@#$%^&*]/.test(a)){toast('Hasło jest za słabe','Użyj minimum 10 znaków, cyfry i znaku specjalnego.');return}if(a!==b){toast('Hasła nie są takie same');return}toast('Hasło zmienione','Zmiana została potwierdzona.')};

  function consentRow45(id,icon45,title,text45,required=false){const active=!!state.v45.consents[id];return `<article class="v45-consent-row"><span>${icon45}</span><div><b>${E45(title)}</b><p>${E45(text45)}</p></div>${required?'<em>Wymagana</em>':`<button class="toggle ${active?'on':''}" onclick="v45ToggleConsent('${id}')" aria-label="Zmień zgodę"></button>`}</article>`}
  function consentsView45(){return `<section class="v45-account-card"><h2>Centrum zgód</h2><p>Zgody wymagane do realizacji usługi są oddzielone od dobrowolnych zgód marketingowych.</p><div class="v45-consent-list">${consentRow45('service','✓','Regulamin i przetwarzanie danych niezbędne do świadczenia usługi','Akceptacja regulaminu oraz przetwarzanie danych potrzebnych do prowadzenia konta i realizacji zamówień.',true)}${consentRow45('aganea','💳','Przekazanie danych wydawcy karty Up Aganea','Dotyczy wyłącznie osób zamawiających lub posiadających kartę przedpłaconą.',true)}${consentRow45('partnerMarketing','🎁','Marketing produktów i usług partnerów','Dobrowolna zgoda na dopasowane informacje o ofertach partnerów w platformie.')}${consentRow45('emailMarketing','✉️','Informacje handlowe przez e-mail','Dobrowolny kontakt e-mail, np. newsletter i informacje o ofertach.')}${consentRow45('smsMarketing','💬','Informacje handlowe przez SMS / MMS','Dobrowolny kontakt marketingowy na numer telefonu.')}${consentRow45('phoneMarketing','☎️','Kontakt głosowy i automatyczne systemy wywołujące','Dobrowolny kontakt telefoniczny lub komunikaty głosowe IVR.')}</div><div class="v45-note" style="margin-top:13px"><b>Historia zgód:</b> każda zmiana powinna zapisywać wersję dokumentu, datę, kanał i identyfikator użytkownika.</div></section>`}
  window.v45ToggleConsent=function(id){state.v45.consents[id]=!state.v45.consents[id];if(typeof persist==='function')persist();render();toast('Zgoda zaktualizowana')};

  function infoView45(){return `<section class="v45-account-card"><h2>Centrum informacyjne</h2><p>Dokumenty, dane kontaktowe i informacje o zasadach korzystania z platformy.</p><div class="v45-doc-summary"><article><b>Administrator danych</b><p>Bonus Systems Polska S.A., ul. Chłodna 51, Warszawa.</p></article><article><b>Kontakt w sprawach danych</b><p>odo@upbonus.pl • +48 22 575 07 77.</p></article><article><b>Twoje prawa</b><p>Dostęp, sprostowanie, usunięcie, ograniczenie, sprzeciw i przenoszenie danych.</p></article><article><b>Pliki cookies</b><p>Konieczne, funkcjonalne i reklamowe — zgodnie z ustawieniami przeglądarki.</p></article></div><div class="v45-doc-tabs"><button onclick="document.getElementById('v45InfoDoc').scrollTo({top:0,behavior:'smooth'})">Informacja o danych</button><button onclick="v45ScrollInfo('cookies')">Polityka cookies</button><button onclick="selectSection('Pomoc')">Centrum pomocy</button></div><div class="v45-document" id="v45InfoDoc">${INFO45}</div></section>`}
  window.v45ScrollInfo=function(kind){const box=document.getElementById('v45InfoDoc');if(!box)return;const headings=[...box.querySelectorAll('h2,h3')];const target=headings.find(h=>kind==='cookies'&&/Polityka plików Cookies/i.test(h.textContent));if(target)box.scrollTo({top:target.offsetTop-10,behavior:'smooth'})};

  function employeeAccount45(){return `<div class="employee-dashboard">${pageHead('Ustawienia konta','Dane użytkownika, bezpieczeństwo, zgody oraz dokumenty informacyjne.')}${accountTabs45()}${state.v45.accountTab==='password'?passwordView45():state.v45.accountTab==='consents'?consentsView45():state.v45.accountTab==='info'?infoView45():profileView45()}</div>`}

