  const M49=v=>Number(v||0).toLocaleString('pl-PL',{minimumFractionDigits:2,maximumFractionDigits:2})+' zł';
  const R49=()=>{try{if(typeof persist==='function')persist()}catch(e){};if(typeof render==='function')render()};
