    return rows.slice().sort((a,b)=>{const av=spec.k(a),bv=spec.k(b);if(typeof av==='number'&&typeof bv==='number')return (av-bv)*spec.d;return String(av).localeCompare(String(bv),'pl',{numeric:true,sensitivity:'base'})*spec.d});
