    const multi=typeof hasMultipleAccesses==='function'&&hasMultipleAccesses();
    const route=(r,ic,label,extra='')=>`<button class="menu-btn ${state.section===r?'active':''} ${extra}" onclick="selectSection('${E49(r).replace(/'/g,"\\'")}')">${icon(ic)}<span>${E49(label)}</span>${r==='Reklamacje'?'<span class="count">4</span>':''}</button>`;
