  window.v49UserQuery=v=>{state.v49.userQuery=v;R49()};window.v49UserSort=v=>{state.v49.userSort=v;R49()};
  window.v49UserHeaderSort=function(key){const pairs={name:['nameAsc','nameDesc'],email:['emailAsc','emailDesc'],employee:['employeeAsc','employeeDesc'],accounts:['accountsAsc','accountsDesc'],card:['cardAsc','cardDesc'],access:['accessAsc','accessDesc'],status:['statusAsc','statusDesc']};const p=pairs[key]||pairs.name;state.v49.userSort=state.v49.userSort===p[0]?p[1]:p[0];R49()};
  function userSortHead49(label,key){const p={name:['nameAsc','nameDesc'],email:['emailAsc','emailDesc'],employee:['employeeAsc','employeeDesc'],accounts:['accountsAsc','accountsDesc'],card:['cardAsc','cardDesc'],access:['accessAsc','accessDesc'],status:['statusAsc','statusDesc']}[key];const active=p&&p.includes(state.v49.userSort);const arrow=active?(state.v49.userSort===p[0]?'↑':'↓'):'↕';return `<button type="button" class="v53-sort-head${active?' active':''}" onclick="v49UserHeaderSort('${key}')" title="Sortuj kolumnę ${E49(label)}"><span>${E49(label)}</span><i>${arrow}</i></button>`}
  window.v49ToggleUser=function(id){const u=(state.v47?.users||[]).find(x=>x.id===id);if(!u)return;const next=u.status==='Zablokowany'?'Aktywny':'Zablokowany';if(!confirm(`${next==='Zablokowany'?'Zablokować':'Odblokować'} użytkownika ${u.name}?`))return;if(typeof v47UserStatus==='function')v47UserStatus(id,next);else{u.status=next;u.platformAccess=next;R49()}};
  function clientUsers49(){const c=currentClient49();const q=state.v49.userQuery.toLowerCase();let rows=(state.v47?.users||[]).filter(u=>u.client===c.name&&`${u.name} ${u.email} ${u.employeeId} ${u.id}`.toLowerCase().includes(q));rows=sort49(rows,state.v49.userSort,{nameAsc:{k:x=>x.name,d:1},nameDesc:{k:x=>x.name,d:-1},emailAsc:{k:x=>x.email,d:1},emailDesc:{k:x=>x.email,d:-1},employeeAsc:{k:x=>x.employeeId,d:1},employeeDesc:{k:x=>x.employeeId,d:-1},accountsAsc:{k:x=>Number(x.eaccounts||0),d:1},accountsDesc:{k:x=>Number(x.eaccounts||0),d:-1},cardAsc:{k:x=>x.card,d:1},cardDesc:{k:x=>x.card,d:-1},accessAsc:{k:x=>x.platformAccess,d:1},accessDesc:{k:x=>x.platformAccess,d:-1},status:{k:x=>x.status,d:1},statusAsc:{k:x=>x.status,d:1},statusDesc:{k:x=>x.status,d:-1}});return `${pageHead('Dostępy i blokady','Zarządzaj użytkownikami swojej organizacji. Zawieszenie całej platformy realizuje wyłącznie Up Bonus.')}
    <div class="v49-toolbar"><div class="v49-search"><span>⌕</span><input value="${E49(state.v49.userQuery)}" placeholder="Szukaj po imieniu, e-mailu lub ID…" oninput="v49UserQuery(this.value)"></div><select onchange="v49UserSort(this.value)" aria-label="Sortowanie użytkowników"><optgroup label="Użytkownik"><option value="nameAsc" ${state.v49.userSort==='nameAsc'?'selected':''}>Imię A–Z</option><option value="nameDesc" ${state.v49.userSort==='nameDesc'?'selected':''}>Imię Z–A</option></optgroup><optgroup label="E-mail"><option value="emailAsc" ${state.v49.userSort==='emailAsc'?'selected':''}>E-mail A–Z</option><option value="emailDesc" ${state.v49.userSort==='emailDesc'?'selected':''}>E-mail Z–A</option></optgroup><optgroup label="ID pracownika"><option value="employeeAsc" ${state.v49.userSort==='employeeAsc'?'selected':''}>ID rosnąco</option><option value="employeeDesc" ${state.v49.userSort==='employeeDesc'?'selected':''}>ID malejąco</option></optgroup><optgroup label="E-konta"><option value="accountsAsc" ${state.v49.userSort==='accountsAsc'?'selected':''}>Najmniej e-kont</option><option value="accountsDesc" ${state.v49.userSort==='accountsDesc'?'selected':''}>Najwięcej e-kont</option></optgroup><optgroup label="Status"><option value="statusAsc" ${['status','statusAsc'].includes(state.v49.userSort)?'selected':''}>Status A–Z</option><option value="statusDesc" ${state.v49.userSort==='statusDesc'?'selected':''}>Status Z–A</option></optgroup></select></div>
    <div class="v49-table-wrap"><table class="v49-table v53-sortable-table"><thead><tr><th>${userSortHead49('Użytkownik','name')}</th><th>${userSortHead49('E-mail','email')}</th><th>${userSortHead49('ID pracownika','employee')}</th><th>${userSortHead49('E-konta','accounts')}</th><th>${userSortHead49('Karta','card')}</th><th>${userSortHead49('Dostęp','access')}</th><th>${userSortHead49('Status','status')}</th><th>Akcje</th></tr></thead><tbody>${rows.map(u=>`<tr><td><b>${E49(u.name)}</b><small>${E49(u.id)}</small></td><td>${E49(u.email)}</td><td>${E49(u.employeeId)}</td><td>${u.eaccounts}</td><td>${E49(u.card)}</td><td>${chip49(u.platformAccess,statusClass49(u.platformAccess))}</td><td>${chip49(u.status,statusClass49(u.status))}</td><td><div class="actions"><button class="${u.status==='Zablokowany'?'':'danger'}" onclick="v49ToggleUser('${E49(u.id)}')">${u.status==='Zablokowany'?'Odblokuj':'Zablokuj'}</button><button onclick="toast('Historia użytkownika','Logowania, zamówienia i operacje użytkownika.')">Historia</button></div></td></tr>`).join('')||'<tr><td colspan="8">Brak użytkowników.</td></tr>'}</tbody></table></div>`}

