  window.v49ToggleTerms=function(){state.v49.termsOpen=!state.v49.termsOpen;R49()};
  function clientTerms49(){const c=currentClient49();return `${pageHead('Warunki umowy','Podsumowanie aktualnych ustaleń handlowych i zasad kart.')}
    <section class="v49-card"><div class="v49-terms-row"><div><strong>${E49(c.name)}</strong><span>${E49(c.platformStatus||'Aktywna')}</span></div><div><strong>${M49(c.subscriptionNet)}</strong><span>${E49(c.frequency)}</span></div><div><strong>${E49(c.billingStatus)}</strong><span>Następna faktura: ${E49(c.nextInvoice)}</span></div><div><strong>${Number(c.cardFee||0)>0?M49(c.cardFee):E49(c.cardFeeMode)}</strong><span>model opłaty za kartę</span></div><button class="secondary-btn" onclick="v49ToggleTerms()">${state.v49.termsOpen?'Ukryj szczegóły':'Pokaż szczegóły'}</button></div>${state.v49.termsOpen?`<div class="v49-details"><div class="v49-detail-grid"><div class="v49-detail"><span>Termin płatności</span><b>${E49(c.dueDate)}</b></div><div class="v49-detail"><span>Okres karencji</span><b>${Number(c.graceDays||0)} dni</b></div><div class="v49-detail"><span>Zamówienie karty przez pracownika</span><b>${c.cardOrderAllowed?'Dozwolone':'Wyłączone'}</b></div><div class="v49-detail"><span>Przelew e-konto → karta</span><b>${c.transferAllowed?'Dozwolony':'Realizuje Up Bonus / HR'}</b></div><div class="v49-detail"><span>Handlowiec Up Bonus</span><b>${E49(c.salesperson)}</b></div><div class="v49-detail"><span>Kontakt po stronie klienta</span><b>${E49(c.hrContact)}<br>${E49(c.hrEmail)}</b></div></div></div>`:''}</section>`}

