  window.v49FundingQuery=v=>{state.v49.fundingQuery=v;R49()};window.v49FundingStatus=v=>{state.v49.fundingStatus=v;R49()};window.v49FundingSort=v=>{state.v49.fundingSort=v;R49()};
  function clientFunding49(){let rows=(typeof FLOW_DB!=='undefined'&&Array.isArray(FLOW_DB.fundingBatches)?FLOW_DB.fundingBatches:[]);const q=state.v49.fundingQuery.toLowerCase();rows=rows.filter(x=>(state.v49.fundingStatus==='all'||x.status===state.v49.fundingStatus)&&`${x.name} ${x.fundingId} ${x.programId} ${x.settlementId}`.toLowerCase().includes(q));rows=sort49(rows,state.v49.fundingSort,{dateDesc:{k:x=>x.date,d:-1},dateAsc:{k:x=>x.date,d:1},amountDesc:{k:x=>Number(x.total||0),d:-1},nameAsc:{k:x=>x.name,d:1},status:{k:x=>x.status,d:1}});const sum=rows.reduce((a,x)=>a+Number(x.total||0),0);return `${pageHead('Budżety i zasilenia','Wgrywanie, historia, kontrola statusów i ponawianie zasileń.',`<button class="secondary-btn" onclick="downloadTemplate('funding')">↓ Formatka Excel</button><button class="primary-btn" onclick="state.section='Edytor danych Excel';render()">＋ Wgraj zasilenie</button>`)}
    <div class="v49-kpis"><article class="v49-kpi"><span>Widoczna wartość</span><b>${M49(sum)}</b><small>po aktualnych filtrach</small></article><article class="v49-kpi"><span>Operacje</span><b>${rows.length}</b><small>w historii</small></article><article class="v49-kpi"><span>Odbiorcy</span><b>${rows.reduce((a,x)=>a+Number(x.recipients||0),0).toLocaleString('pl-PL')}</b><small>łącznie w operacjach</small></article><article class="v49-kpi"><span>Do rozliczenia</span><b>${rows.filter(x=>!/Rozliczone/i.test(x.status)).length}</b><small>statusy inne niż rozliczone</small></article></div>
    <div class="v49-toolbar"><div class="v49-search"><span>⌕</span><input value="${E49(state.v49.fundingQuery)}" placeholder="Szukaj zasilenia, programu lub ID…" oninput="v49FundingQuery(this.value)"></div><select onchange="v49FundingStatus(this.value)"><option value="all">Wszystkie statusy</option>${[...new Set((typeof FLOW_DB!=='undefined'?FLOW_DB.fundingBatches:[]).map(x=>x.status))].map(s=>`<option ${state.v49.fundingStatus===s?'selected':''}>${E49(s)}</option>`).join('')}</select><select onchange="v49FundingSort(this.value)"><option value="dateDesc" ${state.v49.fundingSort==='dateDesc'?'selected':''}>Najnowsze</option><option value="dateAsc" ${state.v49.fundingSort==='dateAsc'?'selected':''}>Najstarsze</option><option value="amountDesc" ${state.v49.fundingSort==='amountDesc'?'selected':''}>Kwota malejąco</option><option value="nameAsc" ${state.v49.fundingSort==='nameAsc'?'selected':''}>Nazwa A–Z</option><option value="status" ${state.v49.fundingSort==='status'?'selected':''}>Status</option></select></div>
    <div class="v49-table-wrap"><table class="v49-table"><thead><tr><th>Zasilenie</th><th>Data</th><th>Program</th><th>Odbiorcy</th><th>Kwota</th><th>Status</th><th>Rozliczenie</th><th>Akcje</th></tr></thead><tbody>${rows.map(f=>`<tr><td><b>${E49(f.name)}</b><small>${E49(f.fundingId)}</small></td><td>${E49(f.date)}</td><td>${E49(f.programId)}</td><td>${Number(f.recipients||0).toLocaleString('pl-PL')}</td><td><b>${M49(f.total)}</b></td><td>${chip49(f.status,statusClass49(f.status))}</td><td>${E49(f.settlementId)}</td><td><div class="actions"><button onclick="showFlow('${E49(f.flowId)}')">Szczegóły</button><button onclick="repeatFunding('${E49(f.fundingId)}')">Ponów</button></div></td></tr>`).join('')||'<tr><td colspan="8">Brak zasileń dla wybranych filtrów.</td></tr>'}</tbody></table></div>`}

