      {id:'RKL-2026-0041',area:'Platforma',subject:'Brak widoczności nowego programu',date:'2026-08-05',reporter:'Anna Kowalska',status:'W realizacji',sla:'4 h'},
      {id:'RKL-2026-0034',area:'Zamówienie firmowe',subject:'Zmiana terminu dostawy paczki',date:'2026-07-31',reporter:'Anna Kowalska',status:'Zrealizowana',sla:'OK'}
