    return `<aside class="sidebar v54-sidebar ${state.mobileMenu?'open':''}"><div class="sidebar-head">${hasMulti56()?`<button class="back-accounts" onclick="openAccounts()">${window.icon?icon('back'):'←'} Przełącz panel</button>`:''}<div class="sidebar-context"><b>Panel klienta</b><span>${esc56(c.name)}</span></div></div><nav class="sidebar-menu"><div class="menu-group-label">Panel klienta</div><button class="menu-btn ${state.section==='Pulpit klienta'?'active':''}" onclick="selectSection('Pulpit klienta')">${window.icon?icon('home'):'🏠'}<span>Pulpit</span></button>${menu56.map(g=>{const open=state.v54.openGroups[g.id]!==undefined?state.v54.openGroups[g.id]:g.items.some(x=>x[0]===state.section);return `<section class="v54-menu-group"><button class="v54-menu-parent v56-menu-parent ${open?'open':''}" onclick="v56ToggleGroup('${g.id}')"><span class="v56-parent-emoji">${g.emoji}</span><span>${esc56(g.label)}</span><span class="v54-caret">›</span></button><div class="v54-menu-children ${open?'open':''}">${g.items.map(x=>routeBtn(x[0],x[1],x[2])).join('')}</div></section>`}).join('')}<section class="v54-premium"><div class="v56-premium-label">Up Bonus Premium</div>${routeBtn(premium56[0],premium56[1],premium56[2])}</section></nav><div class="sidebar-foot"><button class="menu-btn" onclick="logout()">${window.icon?icon('logout'):'↩'}<span>Wyloguj</span></button></div></aside><div class="sidebar-overlay ${state.mobileMenu?'open':''}" onclick="closeMobile()"></div>`;
