  function fundingLines56(fundingId){const lines=Array.isArray(window.FLOW_DB?.fundingLines)?FLOW_DB.fundingLines.filter(x=>x.fundingId===fundingId):[];const employees=Array.isArray(window.FLOW_DB?.employees)?FLOW_DB.employees:[];return lines.map((line,i)=>{const emp=employees.find(e=>e.employeeId===line.employeeId)||{};return {...line,name:emp.name||('Pracownik '+(i+1)),email:emp.email||'—',walletId:line.walletId||emp.walletId||'—'};})}
  function fundingSummary56(){const rows=fundingBatches56();const total=rows.reduce((a,x)=>a+Number(x.total||0),0);const recipients=rows.reduce((a,x)=>a+Number(x.recipients||0),0);const utilized=Math.round(total*0.64*100)/100;const unused=Math.max(total-utilized,0);const best=(rows.slice().sort((a,b)=>Number(b.total||0)-Number(a.total||0))[0]||{}).name||'Lunch';const weak=(rows.slice().sort((a,b)=>Number(a.total||0)-Number(b.total||0))[0]||{}).name||'Wellbeing';return {total,recipients,utilized,unused,best,weak}};
  function fundingReminderMeta56(id){const r=state.v56.fundingReminders[id];return r?`<span class="v56-reminder-meta">Przypomnienia: ${r.count} • ostatnie ${esc56(r.last)}</span>`:''}
  window.v56SendFundingReminder=function(id){state.v56.fundingReminders[id]=state.v56.fundingReminders[id]||{count:0,last:''};state.v56.fundingReminders[id].count++;state.v56.fundingReminders[id].last=dateTime56();save56();render();if(state.modal?.type==='v56FundingDetail')renderOverlay();toast('Przypominajka wysłana','Zapytanie o status realizacji zostało zapisane przy zasileniu '+id)};
