  window.v56ConfirmFundingBatch=function(id){state.v56.confirmedFundingBatches[id]=true;save56();render();if(state.modal?.type==='v56FundingDetail')renderOverlay();toast('Potwierdzenie zapisane','Całe zasilenie zostało oznaczone jako potwierdzone przez odbiorców.')};
  function fundingDetailModal56(){const id=state.modal?.data?.id||'';const batch=fundingBatches56().find(x=>x.fundingId===id)||{};const lines=fundingLines56(id);const confirmed=lines.filter(x=>state.v56.confirmedFundingLines[x.fundingLineId]).length;return `<div class="modal-backdrop" onclick="if(event.target===this)closeModal()"><section class="modal" style="max-width:1080px"><div class="modal-head"><div><h3>Szczegóły zasilenia ${esc56(id)}</h3><span>${esc56(batch.name||'Zasilenie')}</span></div><button class="close-btn" onclick="closeModal()">×</button></div><div class="modal-body"><div class="v56-detail-head"><div><p>W tym widoku widać, do kogo trafiło zasilenie, w jakiej wysokości i czy zostało już potwierdzone. To miejsce do kontroli realizacji oraz szybkich przypomnień.</p></div><div class="v56-detail-actions"><button class="secondary-btn" onclick="v56SendFundingReminder('${esc56(id)}')">Wyślij przypominajkę</button><button class="primary-btn" onclick="v56ConfirmFundingBatch('${esc56(id)}')">Potwierdź otrzymanie doładowania</button></div></div><div class="v56-detail-grid"><div class="v56-detail-box"><span>Program</span><b>${esc56(batch.programId||'—')}</b></div><div class="v56-detail-box"><span>Łączna kwota</span><b>${money56(batch.total||0)}</b></div><div class="v56-detail-box"><span>Odbiorcy</span><b>${Number(batch.recipients||lines.length||0).toLocaleString('pl-PL')}</b></div><div class="v56-detail-box"><span>Potwierdzenia</span><b>${confirmed}/${lines.length||0}</b></div></div><div class="v54-table-wrap"><table class="v54-table"><thead><tr><th>Pracownik</th><th>E-mail</th><th>E-konto</th><th>Kwota</th><th>Status</th><th>Potwierdzenie</th><th>Akcje</th></tr></thead><tbody>${lines.map(line=>`<tr><td><b>${esc56(line.name)}</b><small>${esc56(line.employeeId||'')}</small></td><td>${esc56(line.email)}</td><td>${esc56(line.walletId)}</td><td><b>${money56(line.amount||0)}</b></td><td><span class="v56-pill">${/realiz|rozlicz|zaakcept/i.test(String(batch.status||''))?'Przydzielone':'W trakcie'}</span></td><td>${state.v56.confirmedFundingLines[line.fundingLineId]?'<span class="v56-pill">Potwierdzone</span>':'<span class="v56-pill">Oczekuje</span>'}</td><td><div class="v56-employee-actions"><button onclick="v56ConfirmFundingLine('${esc56(id)}','${esc56(line.fundingLineId)}')">Potwierdź</button><button onclick="toast('Szczegóły odbiorcy','${esc56(line.name).replace(/'/g,"\\'")} • ${money56(line.amount||0)}')">Podgląd</button></div></td></tr>`).join('')||'<tr><td colspan="7">Brak szczegółowych pozycji.</td></tr>'}</tbody></table></div>${fundingReminderMeta56(id)}</div><div class="modal-foot"><button class="secondary-btn" onclick="closeModal()">Zamknij</button></div></section></div>`}

  function funding56(){const q=String(state.v54?.queries?.funding||'').toLowerCase();const flt=String(state.v54?.filters?.funding||'all');let rows=fundingBatches56().filter(x=>(flt==='all'||String(x.status)===flt)&&(`${x.name} ${x.fundingId} ${x.programId} ${x.status}`).toLowerCase().includes(q));const statuses=[...new Set(fundingBatches56().map(x=>String(x.status||'')))].filter(Boolean);const s=fundingSummary56();return `${pageHead('Budżety i zasilenia','Historia zasileń, szczegóły odbiorców i szybkie przypomnienia do realizacji.',`<button class="secondary-btn" onclick="downloadTemplate&&downloadTemplate('funding')">↓ Formatka Excel</button><button class="secondary-btn" onclick="v56SendBudgetReminder()">Przypomnij o budżetach</button><button class="primary-btn" onclick="window.v54OpenFunding&&v54OpenFunding()">＋ Nowe zasilenie</button>`)}<div class="v56-kpis"><article class="v56-kpi"><span>Wszystkie zasilenia</span><b>${money56(s.total)}</b><small>łączna wartość historii zasileń</small></article><article class="v56-kpi"><span>Wykorzystano</span><b>${money56(s.utilized)}</b><small>szacunkowe użycie budżetów przez pracowników</small></article><article class="v56-kpi"><span>Niewykorzystano</span><b>${money56(s.unused)}</b><small>środki warte przypomnienia pracownikom</small></article><article class="v56-kpi"><span>Odbiorcy</span><b>${Number(s.recipients).toLocaleString('pl-PL')}</b><small>pracowników objętych zasileniami</small></article></div><div class="v56-two-col"><section class="v56-card"><h3>Podsumowanie wykorzystania środków</h3><p>HR od razu widzi, czy budżety są używane i które programy pracują najlepiej. To tylko panel operacyjny — szczegóły są dostępne po wejściu w konkretne zasilenie.</p><div class="v56-inline-grid"><div class="v56-mini"><span>Najczęściej wykorzystywany program</span><b>${esc56(s.best)}</b></div><div class="v56-mini"><span>Najmniejsza aktywność</span><b>${esc56(s.weak)}</b></div><div class="v56-mini"><span>Przypomnień do pracowników</span><b>${Number(state.v56.budgetReminderHistory.length||0)}</b></div><div class="v56-mini"><span>Akcje do monitorowania</span><b>${rows.filter(x=>/Nowe|W realizacji|Do weryfikacji/i.test(String(x.status||''))).length}</b></div></div><div class="v56-note"><b>Co się sprzedaje, a co nie?</b><br>${esc56(s.best)} ma obecnie najwyższą aktywność, a ${esc56(s.weak)} wymaga dodatkowego wsparcia komunikacyjnego lub prostszego dostępu dla pracowników.</div></section><aside class="v56-card"><h3>Szybkie akcje HR</h3><p>Wysyłaj przypominajki o budżetach lub dopytuj o status zasileń, jeśli realizacja trwa zbyt długo.</p><div class="v56-chip-row"><span class="v56-chip">⏰ wyślij przypominajkę o realizacji</span><span class="v56-chip">📩 zachęć pracowników do użycia budżetu</span><span class="v56-chip">✅ potwierdź otrzymanie doładowania</span></div><div class="v56-actions"><button class="primary-btn" onclick="v56SendBudgetReminder()">Wyślij przypomnienie pracownikom</button><button class="secondary-btn" onclick="toast('Podsumowanie sprzedaży','Najwyższy popyt: ${esc56(s.best).replace(/'/g,"\\'")}')">Co się sprzedaje?</button></div><div class="v56-note">Po wejściu w szczegóły zasilenia możesz zobaczyć listę odbiorców i kwoty oraz oznaczyć potwierdzenia otrzymania.</div></aside></div><div class="v54-toolbar"><div class="v54-search"><span>⌕</span><input value="${esc56(state.v54?.queries?.funding||'')}" placeholder="Szukaj zasilenia, programu lub ID…" oninput="state.v54=state.v54||{};state.v54.queries=state.v54.queries||{};state.v54.queries.funding=this.value;render()"></div><select onchange="state.v54=state.v54||{};state.v54.filters=state.v54.filters||{};state.v54.filters.funding=this.value;render()"><option value="all">Wszystkie statusy</option>${statuses.map(s=>`<option value="${esc56(s)}" ${flt===s?'selected':''}>${esc56(s)}</option>`).join('')}</select></div><div class="v54-table-wrap"><table class="v54-table"><thead><tr><th>Zasilenie</th><th>Data</th><th>Program</th><th>Odbiorcy</th><th>Kwota</th><th>Status</th><th>Rozliczenie</th><th>Akcje</th></tr></thead><tbody>${rows.map(f=>`<tr><td><div class="v56-row-meta"><b>${esc56(f.name)}</b><small>${esc56(f.fundingId)}</small></div>${fundingReminderMeta56(f.fundingId)}</td><td>${esc56(f.date||'')}</td><td>${esc56(f.programId||'')}</td><td>${Number(f.recipients||0).toLocaleString('pl-PL')}</td><td><b>${money56(f.total||0)}</b></td><td><span class="v56-pill">${esc56(f.status||'—')}</span></td><td>${esc56(f.settlementId||'—')}</td><td><div class="actions"><button onclick="v56OpenFundingDetail('${esc56(f.fundingId)}')">Szczegóły</button><button onclick="v56SendFundingReminder('${esc56(f.fundingId)}')">Przypomnij</button><button onclick="window.v54RepeatFunding&&v54RepeatFunding('${esc56(f.fundingId)}')">Powiel</button></div></td></tr>`).join('')||'<tr><td colspan="8">Brak zasileń.</td></tr>'}</tbody></table></div>`}

