  const M571=v=>Number(v||0).toLocaleString('pl-PL',{minimumFractionDigits:2,maximumFractionDigits:2})+' zł';
  function currentClient571(){const list=state.v47?.clients||[];return list.find(x=>x.id===state.v47?.currentClientId)||list[0]||{id:'TEN-003',name:'Open Benefit 3.0'}}
