  function groupHtml58(g,route){const open=state.v58.openGroups[g.id]!==undefined?state.v58.openGroups[g.id]:g.items.some(x=>x[0]===state.section);return `<section class="v54-menu-group"><button class="v54-menu-parent v58-menu-parent ${open?'open':''}" onclick="v58ToggleGroup('${g.id}')">${icon58(g.icon)}<span>${E58(g.label)}</span><span class="v54-caret">${open?'⌄':'›'}</span></button><div class="v54-menu-children v58-menu-children ${open?'open':''}">${g.items.map(i=>route(i[0],i[1],i[2])).join('')}</div></section>`}

