  function employeeList58(){const q=String(state.v58.queries.employees||'').toLowerCase();let rows=tenantEmployees58().filter(e=>`${e.name} ${e.email} ${e.employeeId} ${e.department||''} ${e.group||''}`.toLowerCase().includes(q));return `${pageHead('Lista pracowników','Kartoteka pracowników tej organizacji. Dział, ID i e-mail rozróżniają osoby o takich samych imionach i nazwiskach.')}${tenantScope58()}<div class="v58-toolbar"><div class="v58-search"><span>⌕</span><input value="${E58(state.v58.queries.employees||'')}" placeholder="Szukaj po nazwisku, dziale, grupie, e-mailu lub ID…" oninput="state.v58.queries.employees=this.value;render()"></div><button class="secondary-btn" onclick="selectSection('Import pracowników')">Import Excel</button></div><div class="v58-table-wrap"><table class="v58-table"><thead><tr><th>Pracownik</th><th>Dział</th><th>Grupa</th><th>E-mail</th><th>ID pracownika</th><th>E-konto</th><th>Saldo</th><th>Status</th><th>Akcje</th></tr></thead><tbody>${rows.map(e=>`<tr><td><b>${E58(e.name)}</b></td><td>${E58(e.department||'—')}</td><td>${E58(e.group||'—')}</td><td>${E58(e.email||'—')}</td><td>${E58(e.employeeId||'—')}</td><td>${E58(e.walletId||'—')}</td><td><b>${M58(e.balance||0)}</b></td><td><span class="status ${e.status==='Aktywny'?'green':'gray'}">${E58(e.status||'—')}</span></td><td><button class="link-btn" onclick="toast('Pracownik','${E58(e.name).replace(/'/g,"\\'")} • ${E58(e.department||'—').replace(/'/g,"\\'")} • ${E58(e.employeeId||'—')}')">Szczegóły</button></td></tr>`).join('')||'<tr><td colspan="9">Brak pracowników w tej organizacji.</td></tr>'}</tbody></table></div>`}
  function import58(){state.v57=state.v57||{};state.v57.importRows=state.v57.importRows||[];const rows=state.v57.importRows;return `${pageHead('Import pracowników','Wgraj lub wklej dane, sprawdź podgląd i dopiero wtedy zapisz do kartoteki.',`<button class="secondary-btn" onclick="typeof v57DownloadEmployeeTemplate==='function'&&v57DownloadEmployeeTemplate()">↓ Pobierz formatkę</button>`)}${tenantScope58()}<section class="v58-card"><h2>Import Excel</h2><p>Kolumny: employee_id, e-mail, imię i nazwisko, <b>dział</b>, grupa, program_id, kwota, ważność. Dział pomaga rozróżnić osoby o takich samych danych osobowych.</p><div class="field" style="margin-top:12px"><label>Wklej komórki bezpośrednio z Excela</label><textarea id="v57PasteEmployees" rows="5" placeholder="employee_id&#9;email&#9;imie_i_nazwisko&#9;dzial&#9;grupa&#9;program_id&#9;kwota&#9;data_waznosci"></textarea></div><div class="v58-toolbar" style="margin-top:9px"><button class="secondary-btn" onclick="typeof v57ParseEmployees==='function'&&v57ParseEmployees()">Wczytaj wklejone dane</button><button class="secondary-btn" onclick="typeof v57AddImport==='function'&&v57AddImport()">＋ Dodaj wiersz</button></div><div class="v58-table-wrap"><table class="v58-table"><thead><tr><th>#</th><th>employee_id</th><th>E-mail</th><th>Imię i nazwisko</th><th>Dział</th><th>Grupa</th><th>Program</th><th>Kwota</th><th>Ważność</th><th>Akcja</th></tr></thead><tbody>${rows.map((r,i)=>`<tr><td>${i+1}</td><td contenteditable="true" onblur="v57EditImport(${i},'employeeId',this.textContent)">${E58(r.employeeId)}</td><td contenteditable="true" onblur="v57EditImport(${i},'email',this.textContent)">${E58(r.email)}</td><td contenteditable="true" onblur="v57EditImport(${i},'name',this.textContent)">${E58(r.name)}</td><td contenteditable="true" onblur="v57EditImport(${i},'department',this.textContent)">${E58(r.department)}</td><td contenteditable="true" onblur="v57EditImport(${i},'group',this.textContent)">${E58(r.group)}</td><td contenteditable="true" onblur="v57EditImport(${i},'programId',this.textContent)">${E58(r.programId)}</td><td contenteditable="true" onblur="v57EditImport(${i},'amount',this.textContent)">${E58(r.amount)}</td><td>${E58(r.validTo)}</td><td><button class="link-btn" onclick="v57RemoveImport(${i})">Usuń</button></td></tr>`).join('')||'<tr><td colspan="10">Wklej dane lub dodaj pusty wiersz.</td></tr>'}</tbody></table></div><div style="display:flex;justify-content:flex-end;margin-top:10px"><button class="primary-btn" onclick="typeof v57SaveImport==='function'&&v57SaveImport()">Zapisz do kartoteki</button></div></section>`}
  function groups58(){const emp=tenantEmployees58(),map={};emp.forEach(e=>{const g=e.group||'Bez grupy',d=e.department||'—',k=d+'||'+g;map[k]=map[k]||{department:d,group:g,count:0,programs:new Set()};map[k].count++;if(e.programId)map[k].programs.add(e.programId)});const rows=Object.values(map);return `${pageHead('Grupy pracowników','Działy i grupy wykorzystywane do programów, komunikacji i raportowania.')}${tenantScope58()}<div class="v58-table-wrap"><table class="v58-table"><thead><tr><th>Dział</th><th>Grupa</th><th>Pracownicy</th><th>Programy</th><th>Status</th><th>Akcje</th></tr></thead><tbody>${rows.map(r=>`<tr><td><b>${E58(r.department)}</b></td><td>${E58(r.group)}</td><td>${r.count}</td><td>${[...r.programs].map(E58).join(', ')||'—'}</td><td><span class="status green">Aktywna</span></td><td><button class="link-btn" onclick="toast('Grupa','${E58(r.department+' / '+r.group).replace(/'/g,"\\'")}')">Szczegóły</button></td></tr>`).join('')||'<tr><td colspan="6">Brak grup.</td></tr>'}</tbody></table></div>`}
  function admins58(){const rows=bucket58('adminsByTenant');return `${pageHead('Administratorzy i role','Osoby administrujące platformą klienta oraz zakres ich uprawnień.',`<button class="primary-btn" onclick="toast('Nowy administrator','Otwieram nadanie dostępu do Panelu klienta.')">＋ Dodaj administratora</button>`)}${tenantScope58()}<div class="v58-table-wrap"><table class="v58-table"><thead><tr><th>Administrator</th><th>Dział</th><th>E-mail</th><th>Rola</th><th>Zakres</th><th>Status</th><th>Akcje</th></tr></thead><tbody>${rows.map(r=>`<tr><td><b>${E58(r.name)}</b><small>${E58(r.id)}</small></td><td>${E58(r.department)}</td><td>${E58(r.email)}</td><td><span class="status purple">${E58(r.role)}</span></td><td>${E58(r.scope)}</td><td><span class="status green">${E58(r.status)}</span></td><td><button class="link-btn" onclick="toast('Uprawnienia','${E58(r.name).replace(/'/g,"\\'")} • ${E58(r.scope).replace(/'/g,"\\'")}')">Edytuj</button></td></tr>`).join('')}</tbody></table></div>`}

  function requests58(){const rows=bucket58('requestsByTenant');return `${pageHead('Zgłoszenia','Pytania i dyspozycje do Up Bonus inne niż reklamacje.',`<button class="primary-btn" onclick="v58OpenRequest('Ogólne')">＋ Nowe zgłoszenie</button>`)}${tenantScope58()}<div class="v58-table-wrap"><table class="v58-table"><thead><tr><th>Zgłoszenie</th><th>Typ</th><th>Obszar</th><th>Temat</th><th>Data</th><th>Priorytet</th><th>Status</th><th>Akcje</th></tr></thead><tbody>${rows.map(r=>`<tr><td><b>${E58(r.id)}</b></td><td>${E58(r.type)}</td><td>${E58(r.area)}</td><td>${E58(r.title)}</td><td>${E58(r.created)}</td><td>${E58(r.priority)}</td><td><span class="status ${/Zrealiz/.test(r.status)?'green':'amber'}">${E58(r.status)}</span></td><td><button class="link-btn" onclick="toast('Zgłoszenie','${E58(r.title).replace(/'/g,"\\'")}')">Szczegóły</button></td></tr>`).join('')||'<tr><td colspan="8">Brak zgłoszeń.</td></tr>'}</tbody></table></div>`}
  function settlements58(){const rows=bucket58('settlementsByTenant');return `${pageHead('Rozliczenia i dokumenty','Zestawienia i dokumenty przygotowane dla klienta. Księgowanie pozostaje w systemie ERP Up Bonus.')}${tenantScope58()}<div class="v58-table-wrap"><table class="v58-table"><thead><tr><th>Dokument</th><th>Okres</th><th>Typ</th><th>Kwota</th><th>Data</th><th>Status</th><th>ERP</th><th>Akcje</th></tr></thead><tbody>${rows.map(r=>`<tr><td><b>${E58(r.id)}</b></td><td>${E58(r.period)}</td><td>${E58(r.type)}</td><td><b>${M58(r.amount)}</b></td><td>${E58(r.date)}</td><td><span class="status ${/Zrealiz|Gotowe/.test(r.status)?'green':'amber'}">${E58(r.status)}</span></td><td>${E58(r.erp)}</td><td><button class="link-btn" onclick="toast('Dokument','Podgląd ${E58(r.id)}')">Podgląd</button></td></tr>`).join('')}</tbody></table></div>`}
  function needs58(){const all=state.v49?.productRequests||[];const rows=all.filter(x=>String(x.client||'')===tenantName58()||String(x.tenantId||'')===tenantId58());return `${pageHead('Zapotrzebowania','Produkty i zmiany katalogowe zgłoszone przez Twoją organizację.',`<button class="primary-btn" onclick="typeof showModal==='function'&&showModal('v49ProductRequest')">＋ Zgłoś produkt</button>`)}${tenantScope58()}<div class="v58-table-wrap"><table class="v58-table"><thead><tr><th>ID</th><th>Produkt / marka</th><th>Kategoria</th><th>Program</th><th>Data</th><th>Status</th><th>Akcje</th></tr></thead><tbody>${rows.map(r=>`<tr><td><b>${E58(r.id)}</b></td><td>${E58(r.product)}</td><td>${E58(r.category)}</td><td>${E58(r.program)}</td><td>${E58(r.created)}</td><td><span class="status amber">${E58(r.status)}</span></td><td><button class="link-btn" onclick="toast('Zapotrzebowanie','${E58(r.product).replace(/'/g,"\\'")}')">Szczegóły</button></td></tr>`).join('')||'<tr><td colspan="7">Brak zgłoszonych zapotrzebowań.</td></tr>'}</tbody></table></div>`}
  function campaigns58(){const rows=bucket58('campaignsByTenant');return `${pageHead('Kampanie i banery','Kampanie i materiały widoczne wyłącznie na platformie tej organizacji.',`<button class="primary-btn" onclick="toast('Nowa kampania','Otwieram formularz kampanii z grafiką i podglądem.')">＋ Nowa kampania</button>`)}${tenantScope58()}<div class="v58-table-wrap"><table class="v58-table"><thead><tr><th>Kampania</th><th>Typ</th><th>Odbiorcy</th><th>Od</th><th>Do</th><th>Status</th><th>Akcje</th></tr></thead><tbody>${rows.map(r=>`<tr><td><b>${E58(r.name)}</b><small>${E58(r.id)}</small></td><td>${E58(r.type)}</td><td>${E58(r.audience)}</td><td>${E58(r.from)}</td><td>${E58(r.to)}</td><td><span class="status ${r.status==='Aktywna'?'green':'purple'}">${E58(r.status)}</span></td><td><button class="link-btn" onclick="toast('Kampania','${E58(r.name).replace(/'/g,"\\'")}')">Podgląd</button></td></tr>`).join('')}</tbody></table></div>`}
  function publication58(){const rows=bucket58('publicationByTenant');return `${pageHead('Historia publikacji','Archiwum komunikatów, bannerów i wysyłek do pracowników.')}${tenantScope58()}<div class="v58-table-wrap"><table class="v58-table"><thead><tr><th>Publikacja</th><th>Tytuł</th><th>Kanał</th><th>Odbiorcy</th><th>Data</th><th>Status</th></tr></thead><tbody>${rows.map(r=>`<tr><td><b>${E58(r.id)}</b></td><td>${E58(r.title)}</td><td>${E58(r.channel)}</td><td>${E58(r.audience)}</td><td>${E58(r.date)}</td><td><span class="status green">${E58(r.status)}</span></td></tr>`).join('')}</tbody></table></div>`}

  function prefs58(){state.v57=state.v57||{};state.v57.platformPrefsByTenant=state.v57.platformPrefsByTenant||{};const id=tenantId58();if(!state.v57.platformPrefsByTenant[id])state.v57.platformPrefsByTenant[id]={portalName:tenantName58(),welcome:'Wszystkie benefity, programy i środki w jednym miejscu.',accent:'#6b174e',logo:'',favicon:'',bannerDesktop:'',bannerMobile:'',bannerTitle:'Witaj w swojej strefie benefitów'};const p=state.v57.platformPrefsByTenant[id];p.favicon=p.favicon||'';p.bannerDesktop=p.bannerDesktop||'';p.bannerMobile=p.bannerMobile||'';return p}
  window.v58PersonalField=function(k,v){prefs58()[k]=v;save58();render()};
  window.v58SavePersonalization=function(){save58();toast('Personalizacja zapisana','Zmiany dotyczą wyłącznie '+tenantName58()+'.')};
  window.v58Asset=function(input,key,maxMb){const f=input.files?.[0];if(!f)return;if(f.size>maxMb*1024*1024){toast('Plik jest za duży','Maksymalny rozmiar: '+maxMb+' MB.');return}const rd=new FileReader();rd.onload=()=>{prefs58()[key]=String(rd.result||'');save58();render()};rd.readAsDataURL(f)};
  window.v58RemoveAsset=function(key){prefs58()[key]='';save58();render()};
  function uploadBox58(key,title,desc,accept,maxMb,square=false){const p=prefs58(),img=p[key];return `<div class="v58-upload"><div class="v58-upload-copy"><b>${E58(title)}</b><span>${E58(desc)}</span><div class="v58-upload-actions"><label class="secondary-btn" style="cursor:pointer;padding:7px 10px">${img?'Zmień':'Wgraj'}<input hidden type="file" accept="${E58(accept)}" onchange="v58Asset(this,'${key}',${maxMb})"></label>${img?`<button onclick="v58RemoveAsset('${key}')">Usuń</button>`:''}</div></div><div class="v58-upload-preview ${square?'square':''}">${img?`<img src="${img}">`:'<span style="font-size:8px;color:var(--brand-muted)">Brak pliku</span>'}</div></div>`}
  function personalization58(){const p=prefs58();return `${pageHead('Personalizacja platformy','Klient samodzielnie zmienia elementy wizualne. Zmiany techniczne są zgłaszane do Up Bonus z pełnym opisem.')}${tenantScope58()}<div class="v58-personal-grid"><section class="v58-card"><h2>Do samodzielnej edycji</h2><p>Zmiany dotyczą wyłącznie ${E58(tenantName58())} i nie wpływają na integracje ani bezpieczeństwo.</p><div class="v58-personal-fields" style="margin-top:12px"><div class="field"><label>Nazwa portalu</label><input value="${E58(p.portalName)}" onchange="v58PersonalField('portalName',this.value)"></div><div class="field"><label>Kolor akcentu</label><select onchange="v58PersonalField('accent',this.value)"><option value="#6b174e" ${p.accent==='#6b174e'?'selected':''}>Bordowy Up Bonus</option><option value="#6c5aa7" ${p.accent==='#6c5aa7'?'selected':''}>Fiolet</option><option value="#315f7d" ${p.accent==='#315f7d'?'selected':''}>Granat</option><option value="#13785a" ${p.accent==='#13785a'?'selected':''}>Zieleń</option></select></div><div class="field full"><label>Nagłówek strony startowej</label><input value="${E58(p.bannerTitle)}" onchange="v58PersonalField('bannerTitle',this.value)"></div><div class="field full"><label>Tekst powitalny</label><textarea rows="3" onchange="v58PersonalField('welcome',this.value)">${E58(p.welcome)}</textarea></div><div class="full">${uploadBox58('logo','Logo organizacji','PNG / JPG / WebP • zalecane 1200 × 400 px • proporcja 3:1 • max 2 MB','image/png,image/jpeg,image/webp',2)}</div><div>${uploadBox58('favicon','Favicon / ikona','PNG / SVG • zalecane 512 × 512 px • max 1 MB','image/png,image/svg+xml',1,true)}</div><div>${uploadBox58('bannerDesktop','Baner desktop','JPG / PNG / WebP • zalecane 1920 × 480 px • proporcja 4:1 • max 5 MB','image/png,image/jpeg,image/webp',5)}</div><div class="full">${uploadBox58('bannerMobile','Baner mobile','JPG / PNG / WebP • zalecane 1080 × 1350 px • proporcja 4:5 • max 5 MB','image/png,image/jpeg,image/webp',5)}</div></div><div style="display:flex;justify-content:flex-end;margin-top:12px"><button class="primary-btn" onclick="v58SavePersonalization()">Zapisz zmiany</button></div><div class="v58-managed"><div class="v58-managed-row"><div><b>Domena, logowanie i bezpieczeństwo</b><span>DNS, certyfikaty, metody logowania i konfiguracja bezpieczeństwa.</span></div><button class="secondary-btn" onclick="v58OpenRequest('Domena / logowanie')">Opisz zmianę</button></div><div class="v58-managed-row"><div><b>Moduły, integracje i zaawansowany white-label</b><span>Włączanie funkcji, role systemowe, integracje, nietypowe układy i konfiguracja techniczna.</span></div><button class="secondary-btn" onclick="v58OpenRequest('Moduły / integracje')">Opisz zmianę</button></div></div></section><aside class="v58-card"><h2>Podgląd platformy</h2><p>Podgląd pozwala ocenić branding przed zapisaniem i publikacją.</p><div class="v58-platform-preview" style="--v58-accent:${E58(p.accent)}"><div class="v58-preview-logo">${p.logo?`<img src="${p.logo}">`:'<b style="color:#ff7900;font-size:10px">Up Bonus</b>'}</div><h2>${E58(p.bannerTitle)}</h2><p>${E58(p.welcome)}</p><span class="v58-preview-name">${E58(p.portalName)}</span><div class="v58-preview-banner">${p.bannerDesktop?`<img src="${p.bannerDesktop}">`:'<div style="padding:14px;font-size:9px;color:rgba(255,255,255,.75)">Podgląd bannera desktop (1920 × 480 px)</div>'}</div></div></aside></div>`}
  function terms58(){const c=client58();return `${pageHead('Warunki umowy','Najważniejsze ustalenia w skrócie. Status płatności nie zajmuje miejsca w głównym podsumowaniu.')}${tenantScope58()}<section class="v58-terms"><div class="v58-term"><span>Klient</span><b>${E58(c.name)}</b></div><div class="v58-term"><span>Abonament</span><b>${M58(c.subscriptionNet||0)}</b></div><div class="v58-term"><span>Częstotliwość</span><b>${E58(c.frequency||'—')}</b></div><div class="v58-term"><span>Platforma</span><b>${E58(c.platformStatus||'Aktywna')}</b></div><div class="v58-term"><span>Opiekun</span><div class="v58-manager"><span class="v58-manager-avatar">👤</span><div><b>${E58(c.salesperson||'Opiekun Up Bonus')}</b><span>kontakt@upbonus.pl</span></div></div></div><button class="v58-term-action" onclick="state.v58.termsOpen=!state.v58.termsOpen;render()">${state.v58.termsOpen?'Ukryj':'Szczegóły'} ${state.v58.termsOpen?'↑':'↓'}</button></section>${state.v58.termsOpen?`<div class="v58-grid-2 v58-terms-detail"><section class="v58-card"><h3>Szczegóły ustaleń</h3><div class="v58-table-wrap" style="margin-top:10px"><table class="v58-table"><thead><tr><th>Obszar</th><th>Ustalenie</th></tr></thead><tbody><tr><td>Model opłaty za kartę</td><td>${Number(c.cardFee||0)>0?M58(c.cardFee):E58(c.cardFeeMode||'Bezpłatna')}</td></tr><tr><td>Zamówienie karty przez pracownika</td><td>${c.cardOrderAllowed===false?'Wyłączone':'Dozwolone'}</td></tr><tr><td>Przelew e-konto → karta</td><td>${c.transferAllowed===false?'Realizuje Up Bonus':'Dozwolony zgodnie z programem'}</td></tr><tr><td>Kontakt po stronie klienta</td><td>${E58(c.hrContact||'—')} ${c.hrEmail?'• '+E58(c.hrEmail):''}</td></tr></tbody></table></div></section><aside class="v58-card"><h3>Twój opiekun Up Bonus</h3><p>Masz pytanie do ustaleń, nowego programu lub konfiguracji? Wyślij wiadomość z kontekstem bez szukania właściwego adresata.</p><div style="margin-top:12px"><b>${E58(c.salesperson||'Opiekun Up Bonus')}</b><div style="font-size:9px;color:var(--brand-muted);margin-top:4px">kontakt@upbonus.pl</div></div><button class="primary-btn" style="margin-top:14px" onclick="v58OpenRequest('Kontakt z opiekunem')">Napisz do opiekuna</button></aside></div>`:''}`}

  window.v58OpenRequest=function(area){state.modal={type:'v58Request',data:{area:area||'Ogólne'}};renderOverlay()};
  window.v58SubmitRequest=function(){const d=state.modal?.data||{},title=(document.getElementById('v58ReqTitle')?.value||'').trim(),desc=(document.getElementById('v58ReqDesc')?.value||'').trim();if(!title||!desc){toast('Uzupełnij zgłoszenie','Podaj tytuł i opis oczekiwanej zmiany.');return}const rows=bucket58('requestsByTenant'),id='ZGL-'+new Date().getFullYear()+'-'+String(Date.now()).slice(-4);rows.unshift({id,type:d.area==='Ogólne'?'Zgłoszenie':'Zmiana / pytanie',area:d.area,title,created:today58(),priority:document.getElementById('v58ReqPriority')?.value||'Standard',status:'Nowe',description:desc,reason:(document.getElementById('v58ReqReason')?.value||'').trim(),contact:(document.getElementById('v58ReqContact')?.value||'').trim(),deadline:document.getElementById('v58ReqDeadline')?.value||'',file:document.getElementById('v58ReqFile')?.files?.[0]?.name||''});save58();state.modal=null;state.section='Zgłoszenia';render();toast('Zgłoszenie wysłane',id)};
