/* 052 — ub-v58-8-script */
(function(){
  'use strict';
  if(typeof state==='undefined')return;
  const prevSection588=window.renderSection;
  const prevModal588=window.modalHtml;
  const esc588=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const client588=()=>{const list=state.v47?.clients||[];return list.find(x=>x.id===state.v47?.currentClientId)||list[0]||{id:'TEN-003',name:'Open Benefit 3.0'}};
  const tenantId588=()=>String(client588().id||'TEN-003');
  state.v588=Object.assign({groupsByTenant:{}},state.v588||{});
  function groupsBucket588(){const id=tenantId588();state.v588.groupsByTenant[id]=Array.isArray(state.v588.groupsByTenant[id])?state.v588.groupsByTenant[id]:[];return state.v588.groupsByTenant[id]}
  function save588(){try{typeof persist==='function'&&persist()}catch(e){console.warn('V58.8 persist',e)}}
  function employees588(){return (window.FLOW_DB?.employees||[]).filter(e=>String(e.tenantId||e.clientId||'')===tenantId588())}
  function derivedGroups588(){const map=new Map();employees588().forEach(e=>{const name=String(e.group||'').trim();if(!name||/^bez grupy$/i.test(name))return;const dep=String(e.department||'').trim()||'—';const key=dep+'||'+name;if(!map.has(key))map.set(key,{id:'DER-'+key,name,department:dep,description:'Grupa wynikająca z kartoteki pracowników',count:0,programs:new Set(),status:'Aktywna',source:'Kartoteka'});const g=map.get(key);g.count++;if(e.programId)g.programs.add(e.programId)});return [...map.values()]}
  function allGroups588(){const custom=groupsBucket588().map(g=>({...g,count:employees588().filter(e=>String(e.group||'').trim()===g.name && (!g.department||g.department==='—'||String(e.department||'').trim()===g.department)).length,programs:new Set(employees588().filter(e=>String(e.group||'').trim()===g.name).map(e=>e.programId).filter(Boolean)),source:'Własna'}));const seen=new Set(custom.map(g=>(g.department||'—')+'||'+g.name));const derived=derivedGroups588().filter(g=>!seen.has((g.department||'—')+'||'+g.name));return [...custom,...derived]}
  window.v588OpenGroup=function(){state.modal={type:'v588Group'};renderOverlay()};
  window.v588SaveGroup=function(){
    const name=String(document.getElementById('v588GroupName')?.value||'').trim();
    const department=String(document.getElementById('v588GroupDepartment')?.value||'').trim()||'—';
    const description=String(document.getElementById('v588GroupDescription')?.value||'').trim();
    if(!name){toast('Podaj nazwę grupy','Nazwa grupy jest wymagana.');return}
    const duplicate=allGroups588().some(g=>String(g.name).toLowerCase()===name.toLowerCase()&&String(g.department||'—').toLowerCase()===department.toLowerCase());
    if(duplicate){toast('Taka grupa już istnieje','Zmień nazwę albo dział.');return}
    groupsBucket588().unshift({id:'GRP-'+Date.now().toString().slice(-6),tenantId:tenantId588(),name,department,description,status:'Aktywna',created:new Date().toISOString().slice(0,10)});
    save588();state.modal=null;render();toast('Grupa dodana',name)
  };
  window.v588GroupAssign=function(id){const g=allGroups588().find(x=>x.id===id);toast('Przypisywanie pracowników',g?`Grupa: ${g.name}. Następny krok to wybór pracowników z kartoteki.`:'Wybierz grupę.')};
  function groupModal588(){return `<div class="modal-backdrop" onclick="if(event.target===this)closeModal()"><section class="modal" style="max-width:760px"><div class="modal-head"><div><h3>Dodaj grupę pracowników</h3><span>Każdy klient może tworzyć własne grupy i nazywać je po swojemu.</span></div><button class="close-btn" onclick="closeModal()">×</button></div><div class="modal-body"><div class="v588-helper"><b>Przykłady:</b> Centrala, Pracownicy terenowi, Managerowie, Święta 2026, Nowi pracownicy. Nazwa nie jest narzucona przez Up Bonus.</div><div class="v588-modal-grid"><div class="field"><label>Nazwa grupy *</label><input id="v588GroupName" placeholder="np. Managerowie"></div><div class="field"><label>Dział (opcjonalnie)</label><input id="v588GroupDepartment" placeholder="np. Sprzedaż"></div><div class="field full"><label>Opis (opcjonalnie)</label><textarea id="v588GroupDescription" rows="3" placeholder="Do czego grupa będzie używana, np. komunikacja, program benefitowy, raportowanie."></textarea></div></div></div><div class="modal-foot"><button class="secondary-btn" onclick="closeModal()">Anuluj</button><button class="primary-btn" onclick="v588SaveGroup()">Dodaj grupę</button></div></section></div>`}
  function groupsView588(){const rows=allGroups588();return `${pageHead('Grupy pracowników','Twórz własne grupy do programów, komunikacji i raportowania.',`<button class="primary-btn" onclick="v588OpenGroup()">＋ Dodaj grupę</button>`)}${typeof tenantScope58==='function'?tenantScope58():''}<div class="v588-groups-toolbar"><div class="v588-groups-note"><b>Dowolne nazwy grup.</b> Klient sam ustala strukturę grup — nie narzucamy słownika. Grupa może obejmować cały dział albo dowolnie wybrane osoby.</div><button class="secondary-btn" onclick="toast('Eksport','Lista grup została przygotowana do Excela.')">↓ Excel</button></div>${rows.length?`<div class="v58-table-wrap"><table class="v58-table"><thead><tr><th>Dział</th><th>Grupa</th><th>Pracownicy</th><th>Programy</th><th>Źródło</th><th>Status</th><th>Akcje</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc588(r.department||'—')}</td><td><div class="v588-group-name"><b>${esc588(r.name)}</b><small>${esc588(r.description||'Bez dodatkowego opisu')}</small></div></td><td>${Number(r.count||0).toLocaleString('pl-PL')}</td><td>${[...(r.programs||[])].map(esc588).join(', ')||'—'}</td><td>${esc588(r.source||'Własna')}</td><td><span class="status green">${esc588(r.status||'Aktywna')}</span></td><td><div class="actions"><button onclick="v588GroupAssign('${esc588(r.id)}')">Przypisz pracowników</button><button onclick="toast('Grupa','${esc588(r.name).replace(/'/g,"\\'")}')">Szczegóły</button></div></td></tr>`).join('')}</tbody></table></div>`:`<div class="v588-empty"><b>Nie masz jeszcze własnych grup</b><p>Utwórz pierwszą grupę i nazwij ją tak, jak pasuje do organizacji. Potem możesz przypisywać do niej pracowników, programy i komunikację.</p><button class="primary-btn" onclick="v588OpenGroup()">＋ Dodaj pierwszą grupę</button></div>`}`}
  function premiumDashboardBanner588(){return `<section class="v588-dashboard-premium"><div class="v588-dashboard-copy"><div class="v588-dashboard-kicker">Up Bonus Premium • Sklep z personalizacjami</div><h2>Zrób prezent, który wygląda jak przygotowany specjalnie dla odbiorcy.</h2><p>Wybierz markę i nominał, dodaj własne logo, zdjęcie lub życzenia, a przed zamówieniem zobacz finalny projekt. Działa dla pojedynczego prezentu i większej akcji firmowej.</p><div class="v588-dashboard-benefits"><span>🎨 własne logo</span><span>📷 zdjęcie lub grafika</span><span>✍️ życzenia i dedykacja</span><span>📄 PDF / druk / e-mail</span></div><div class="v588-dashboard-actions"><button class="primary-btn" onclick="selectSection('Sklep z personalizacjami')">Otwórz sklep z personalizacjami</button><button class="secondary-btn" onclick="selectSection('Odbierz upominek')">Odbierz upominek</button></div></div><div class="v588-dashboard-visual"><div class="v588-card-stack"><div class="v588-card-mock one"><span class="v588-card-logo">∞ Up Bonus Gifts</span><b>Własne życzenia</b><small>Logo • zdjęcie • wiadomość</small></div><div class="v588-card-mock two"><span class="v588-card-logo">Twoja firma</span><b>Prezent premium</b><small>Personalizowany projekt</small></div></div></div></section>`}
  function dashboard588(){let html=prevSection588.apply(window,[]);const banner=premiumDashboardBanner588();if(/<section class="v54-premium-hero">[\s\S]*?<\/section>/.test(html))html=html.replace(/<section class="v54-premium-hero">[\s\S]*?<\/section>/,banner);else html+=banner;return html}
  window.modalHtml=function(){if(state.modal?.type==='v588Group')return groupModal588();return prevModal588.apply(this,arguments)};
  window.renderSection=function(){if(state.role==='hr'&&state.section==='Grupy pracowników')return groupsView588();if(state.role==='hr'&&state.section==='Pulpit klienta')return dashboard588();return prevSection588.apply(this,arguments)};
  try{render()}catch(e){console.warn('UP-BONUS-V58.8 render',e)}
})();
;

