  window.v59DownloadEmployeeTemplate=function(){
    const rows=[
      ['employee_id','email','imie_i_nazwisko','dzial','grupa','program_id','kwota','data_waznosci'],
      ['EMP001','anna.kowalska@firma.pl','Anna Kowalska','Marketing','Pracownicy','PROGRAM01','500','2026-12-31'],
      ['EMP002','piotr.nowak@firma.pl','Piotr Nowak','Sprzedaż','Managerowie','PROGRAM01','750','2026-12-31']
    ];
    const cells=rows.map((r,ri)=>'<tr>'+r.map(c=>`<td style="border:1px solid #cdb7c7;padding:7px;${ri===0?'background:#6b174e;color:#fff;font-weight:bold':'background:'+(ri%2?'#fbf5f9':'#fff')}">${E59(c)}</td>`).join('')+'</tr>').join('');
    const xls=`<html><head><meta charset="utf-8"></head><body><table style="border-collapse:collapse;font-family:Arial">${cells}</table></body></html>`;
    const blob=new Blob(['\ufeff'+xls],{type:'application/vnd.ms-excel'});
    const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='upbonus-formatka-pracownicy.xls';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),500);
  };
