  /* ---------- GRUPY ---------- */
  function groups59(){
    state.v588=state.v588||{groupsByTenant:{}};
    state.v588.groupsByTenant=state.v588.groupsByTenant||{};
    state.v588.groupsByTenant[tenantId59()]=state.v588.groupsByTenant[tenantId59()]||[];
    const custom=state.v588.groupsByTenant[tenantId59()];
    const map=new Map();
    tenantEmployees59().forEach(e=>{
      const name=String(e.group||'').trim(); if(!name||/^bez grupy$/i.test(name))return;
      const dep=String(e.department||'').trim()||'—',key=dep+'||'+name;
      if(!map.has(key))map.set(key,{id:'DER-'+key,name,department:dep,description:'Grupa z kartoteki pracowników',source:'Kartoteka'});
    });
    custom.forEach(g=>map.set((g.department||'—')+'||'+g.name,{...g,source:'Własna'}));
    return [...map.values()].map(g=>{
      const members=tenantEmployees59().filter(e=>String(e.group||'').trim()===g.name&&(!g.department||g.department==='—'||String(e.department||'').trim()===g.department));
      return {...g,count:members.length,programs:[...new Set(members.map(x=>x.programId).filter(Boolean))]};
    });
  }
  window.v59GroupAssign=function(id){state.modal={type:'v59GroupAssign',data:{id}};renderOverlay()};
  window.v59GroupDetails=function(id){state.modal={type:'v59GroupDetails',data:{id}};renderOverlay()};
  window.v59SaveGroupAssign=function(id){
    const g=groups59().find(x=>x.id===id);if(!g)return;
    const checked=[...document.querySelectorAll('input[name="v59GroupEmp"]:checked')].map(x=>x.value);
    tenantEmployees59().forEach(e=>{
      if(checked.includes(e.employeeId))e.group=g.name;
      else if(String(e.group||'')===g.name)e.group='';
    });
    try{typeof saveFlowDb==='function'&&saveFlowDb()}catch(e){}
    closeModal();render();toast('Przypisano pracowników',g.name+' • '+checked.length+' osób');
  };
