  window.v64ComplaintNext=function(id){const c=state.v64.complaints.find(x=>x.id===id);if(!c)return;const steps=['BOK – nowe','Afiliacje – weryfikacja','Partner – weryfikacja','Decyzja partnera'];let i=steps.indexOf(c.status);c.status=steps[Math.min(steps.length-1,Math.max(0,i+1))];P64();render();toast('Reklamacja',c.id+' → '+c.status)};
