/* 067 — ub-v70-client-gift-redeem-fix */
(function(){
  if(typeof state==='undefined' || typeof window.renderSection!=='function') return;

  /* Na potrzeby prezentacji zawsze utrzymujemy jeden aktywny upominek,
     który pozwala przejść przez pełny flow wyboru: wino / miody / kawa /
     herbata / wellbeing. Nie duplikujemy go przy kolejnych wejściach. */
  try{
    state.v15=state.v15||{};
    state.v15.receivedGifts=state.v15.receivedGifts||[];
    const demoId='GFT-DEMO-CHOICE-2026';
    const exists=state.v15.receivedGifts.some(g=>g.id===demoId);
    if(!exists){
      state.v15.receivedGifts.unshift({
        id:demoId,
        sender:'Up Bonus / HR',
        recipient:'malgorzata.bartkiewicz@upbonus.pl',
        title:'Prezent od firmy — wybierz swój upominek',
        message:'Wybierz jeden z prezentów dostępnych w Twoim programie.',
        type:'choice',
        budget:180,
        deadline:'31.12.2026',
        status:'Do odebrania',
        selected:null
      });
      try{persist()}catch(e){}
    }
  }catch(e){console.warn('v70 gift demo init',e)}

  const renderSectionBefore70=window.renderSection;

  /* Panel klienta: pozycja "Odbierz upominek" ma pokazywać dokładnie
     ten sam mechanizm realizacji prezentu co Portal pracownika.
     Nie pokazujemy tu kreatora akcji HR ani listy kampanii. */
  window.renderSection=function(){
    if(state.role==='hr' && state.section==='Odbierz upominek'){
      const roleKeep=state.role;
      const sectionKeep=state.section;
      try{
        state.role='employee';
        state.section='Odbierz upominek';
        return renderSectionBefore70.apply(this,arguments);
      }finally{
        state.role=roleKeep;
        state.section=sectionKeep;
      }
    }
    return renderSectionBefore70.apply(this,arguments);
  };

  try{render()}catch(e){console.warn('v70 initial render',e)}
})();
;

