(function(){
  if(typeof state==='undefined') return;

  /* ============================================================
     1) UPBONEK
     - panel naprawdę się zamyka,
     - po ponownym otwarciu zaczyna nową rozmowę,
     - można też wyczyścić wątek bez zamykania panelu.
     ============================================================ */
  window.v72NewAiThread=function(){
    state.aiMessages=[];
    try{persist()}catch(e){}
    if(state.aiOpen && typeof appendGlobalEnhancements==='function') appendGlobalEnhancements();
  };

  window.toggleAi=function(){
    const wasOpen=!!state.aiOpen;
    if(wasOpen){
      state.aiOpen=false;
      /* Każde kolejne otwarcie zaczyna świeży temat. */
      state.aiMessages=[];
      document.querySelectorAll('.v71-ai-panel,.ub-ai-panel').forEach(x=>x.remove());
      try{persist()}catch(e){}
      if(typeof appendGlobalEnhancements==='function') appendGlobalEnhancements();
      return;
    }
    state.aiMessages=[];
    state.aiOpen=true;
    try{persist()}catch(e){}
    if(typeof appendGlobalEnhancements==='function') appendGlobalEnhancements();
  };

  /* Poprawka cleanupu: v71 zmienił klasę panelu na .v71-ai-panel,
     a starszy cleanup usuwał wyłącznie .ub-ai-panel. */
  const appendBefore72=window.appendGlobalEnhancements;
  window.appendGlobalEnhancements=function(){
    document.querySelectorAll('.v71-ai-panel').forEach(x=>x.remove());
    const out=appendBefore72.apply(this,arguments);
    /* Gwarancja: przy zamkniętym stanie nie pozostaje żaden panel. */
    if(!state.aiOpen){
      document.querySelectorAll('.v71-ai-panel,.ub-ai-panel').forEach(x=>x.remove());
    }
    return out;
  };

  /* Dodajemy "Nowa rozmowa" do aktualnego panelu v71 bez zmiany jego logiki produktowej. */
  const aiPanelBefore72=window.aiPanelHtml;
  window.aiPanelHtml=function(){
    let out=aiPanelBefore72.apply(this,arguments);
    try{
      const holder=document.createElement('div');
      holder.innerHTML=out;
      const head=holder.querySelector('.v71-ai-head,.ub-ai-head');
      const close=head?.querySelector('.v71-ai-close,.ub-ai-close');
      if(head && !head.querySelector('.v72-ai-new')){
        const btn=document.createElement('button');
        btn.type='button';
        btn.className='v72-ai-new';
        btn.setAttribute('onclick','v72NewAiThread()');
        btn.textContent='Nowa rozmowa';
        head.insertBefore(btn,close||null);
      }
      out=holder.innerHTML;
    }catch(e){}
    return out;
  };

  /* ============================================================
     2) ZDJĘCIE PROFILOWE
     Zamiast zapisywać "src + parametry kadru", zapisujemy fizycznie
     wykadrowany kwadrat JPEG. Dzięki temu topbar pokazuje dokładnie
     ten sam kadr, który użytkownik zatwierdził w edytorze.
     ============================================================ */

  function avatarDraft72(){
    return state.v27?.avatarDraft || state.v25?.avatar || {src:'',zoom:100,x:50,y:50};
  }

  function rasterizeAvatar72(a){
    return new Promise((resolve,reject)=>{
      if(!a?.src){resolve('');return}
      const img=new Image();
      img.onload=()=>{
        try{
          const S=512;
          const canvas=document.createElement('canvas');
          canvas.width=S;canvas.height=S;
          const ctx=canvas.getContext('2d');

          const iw=img.naturalWidth||img.width;
          const ih=img.naturalHeight||img.height;
          const base=Math.max(S/iw,S/ih);
          const rw=iw*base, rh=ih*base;
          const xp=Math.max(0,Math.min(100,Number(a.x??50)))/100;
          const yp=Math.max(0,Math.min(100,Number(a.y??50)))/100;
          const left=(S-rw)*xp;
          const top=(S-rh)*yp;
          const zoom=Math.max(1,Number(a.zoom||100)/100);

          /* CSS preview skaluje cały kwadrat względem środka.
             Widoczny obszar przed transformacją ma rozmiar S/zoom. */
          const preSize=S/zoom;
          const preLeft=(S-preSize)/2;
          const preTop=(S-preSize)/2;

          let sx=(preLeft-left)/base;
          let sy=(preTop-top)/base;
          let sw=preSize/base;
          let sh=preSize/base;

          /* zabezpieczenie przed błędami numerycznymi */
          sx=Math.max(0,Math.min(iw-sw,sx));
          sy=Math.max(0,Math.min(ih-sh,sy));
          sw=Math.min(iw,sw);
          sh=Math.min(ih,sh);

          ctx.fillStyle='#ffffff';
          ctx.fillRect(0,0,S,S);
          ctx.drawImage(img,sx,sy,sw,sh,0,0,S,S);
          resolve(canvas.toDataURL('image/jpeg',0.90));
        }catch(err){reject(err)}
      };
      img.onerror=()=>reject(new Error('Nie udało się odczytać zdjęcia.'));
      img.src=String(a.src||'');
    });
  }

  window.v27SaveAvatar=async function(){
    const a=avatarDraft72();
    if(!a?.src){
      state.v25=state.v25||{};
      state.v25.avatar={src:'',zoom:100,x:50,y:50};
      try{localStorage.removeItem('upbonus_avatar_v28')}catch(e){}
      state.v27.avatarDraft=null;
      state.modal=null;
      try{persist()}catch(e){}
      render();
      toast('Zdjęcie usunięte');
      return;
    }

    const saveButton=document.querySelector('.modal-foot .primary-btn');
    if(saveButton){saveButton.disabled=true;saveButton.textContent='Zapisywanie…'}

    try{
      const cropped=await rasterizeAvatar72(a);
      state.v25=state.v25||{};
      /* Gotowy kadr jest już kwadratem — nie nakładamy drugi raz zoomu/pozycji. */
      state.v25.avatar={src:cropped,zoom:100,x:50,y:50};
      try{localStorage.setItem('upbonus_avatar_v28',JSON.stringify(state.v25.avatar))}catch(e){}
      state.v27.avatarDraft=null;
      state.modal=null;
      try{persist()}catch(e){}
      render();
      toast('Zdjęcie zapisane','Kadr został zapisany dokładnie tak, jak w podglądzie.');
    }catch(err){
      console.error('v72 avatar save',err);
      if(saveButton){saveButton.disabled=false;saveButton.textContent='Zapisz zdjęcie'}
      toast('Nie udało się zapisać zdjęcia','Spróbuj ponownie lub wybierz inne zdjęcie.');
    }
  };

  /* Dodajemy czytelną notkę do istniejącego edytora profilu. */
  const modalBefore72=window.modalHtml;
  window.modalHtml=function(){
    let out=modalBefore72.apply(this,arguments);
    if(state.modal?.type!=='profile') return out;
    try{
      const holder=document.createElement('div');
      holder.innerHTML=out;
      const actions=holder.querySelector('.v27-profile-actions');
      if(actions && !actions.querySelector('.v72-crop-note')){
        const note=document.createElement('div');
        note.className='v72-crop-note';
        note.innerHTML='<b>Finalny kadr 1:1.</b> Po kliknięciu „Zapisz zdjęcie” platforma zapisze dokładnie widoczny fragment. W topbarze nie będzie ponownie przesuwany ani powiększany.';
        actions.appendChild(note);
      }
      out=holder.innerHTML;
    }catch(e){}
    return out;
  };

  /* Jeżeli stary zapis miał dodatkowy zoom/position, po nowym zapisie będą = 100/50/50.
     Render avatara pozostawiamy bez zmian — nowy crop będzie więc 1:1. */

  try{if(state.loggedIn && typeof appendGlobalEnhancements==='function')appendGlobalEnhancements()}catch(e){}
})();
;

