/* 071 — ub-v74-premium-avatar */
(function(){
  if(typeof state==='undefined') return;

  function norm74(v){return String(v||'').trim().toLowerCase()}
  function initials74(name){
    return String(name||'U').trim().split(/\s+/).filter(Boolean).map(x=>x[0]).join('').slice(0,2).toUpperCase();
  }
  function avatarKey74(email){
    const e=norm74(email);
    return 'upbonus_avatar_v74_'+encodeURIComponent(e||'anonymous');
  }
  function emptyAvatar74(){return {src:'',zoom:100,x:50,y:50}}

  /* Jednorazowa migracja starego wspólnego zdjęcia:
     legacy avatar przypisujemy wyłącznie Małgorzacie, nigdy Annie/innemu użytkownikowi. */
  try{
    const legacy=localStorage.getItem('upbonus_avatar_v28');
    const gosiaKey=avatarKey74('malgorzata.bartkiewicz@upbonus.pl');
    if(legacy && !localStorage.getItem(gosiaKey)){
      localStorage.setItem(gosiaKey,legacy);
    }
    localStorage.removeItem('upbonus_avatar_v28');
  }catch(e){}

  function loadUserAvatar74(email){
    state.v25=state.v25||{};
    const key=avatarKey74(email);
    try{
      const raw=localStorage.getItem(key);
      state.v25.avatar=raw?JSON.parse(raw):emptyAvatar74();
    }catch(e){
      state.v25.avatar=emptyAvatar74();
    }
    state.v27=state.v27||{};
    state.v27.avatarDraft=null;
    return state.v25.avatar;
  }

  function saveUserAvatar74(avatar){
    const email=state.user?.email||'';
    try{localStorage.setItem(avatarKey74(email),JSON.stringify(avatar||emptyAvatar74()))}catch(e){}
  }

  function removeUserAvatar74(){
    try{localStorage.removeItem(avatarKey74(state.user?.email||''))}catch(e){}
  }

  /* Przed KAŻDYM logowaniem podmieniamy avatar na avatar konkretnego e-maila.
     Dzięki temu render po loginie nie może przejąć zdjęcia poprzedniej osoby. */
  const loginBefore74=window.login;
  window.login=function(e){
    const email=norm74(document.getElementById('loginEmail')?.value||state.user?.email||'');
    loadUserAvatar74(email);
    return loginBefore74.apply(this,arguments);
  };

  /* Gdy trwa już sesja, upewniamy się, że ma swój własny avatar. */
  if(state.loggedIn && state.user?.email){
    loadUserAvatar74(state.user.email);
    try{persist()}catch(e){}
  }

  /* Dokładny zapis tego, co widać w edytorze:
     1) renderujemy object-fit: cover + object-position do kwadratu,
     2) potem nakładamy zoom wokół środka dokładnie jak CSS transform:scale().
     To eliminuje efekt "po zapisie ucina głowę". */
  function bakeAvatar74(a){
    return new Promise((resolve,reject)=>{
      if(!a?.src){resolve('');return}
      const img=new Image();
      img.onload=()=>{
        try{
          const S=640;
          const iw=img.naturalWidth||img.width;
          const ih=img.naturalHeight||img.height;
          if(!iw||!ih) throw new Error('Brak wymiarów zdjęcia.');

          const temp=document.createElement('canvas');
          temp.width=S;temp.height=S;
          const t=temp.getContext('2d');
          t.fillStyle='#fff';t.fillRect(0,0,S,S);

          /* CSS object-fit: cover */
          const cover=Math.max(S/iw,S/ih);
          const dw=iw*cover, dh=ih*cover;
          const px=Math.max(0,Math.min(100,Number(a.x??50)))/100;
          const rawPy=Math.max(0,Math.min(100,Number(a.y??50)))/100;
          const py=rawPy;
          const dx=(S-dw)*px;
          const dy=(S-dh)*py;
          t.drawImage(img,dx,dy,dw,dh);

          /* CSS transform: scale(zoom) around center */
          const zoom=Math.max(1,Number(a.zoom||100)/100);
          const out=document.createElement('canvas');
          out.width=S;out.height=S;
          const c=out.getContext('2d');
          c.fillStyle='#fff';c.fillRect(0,0,S,S);
          const scaled=S*zoom;
          c.drawImage(temp,(S-scaled)/2,(S-scaled)/2,scaled,scaled);

          resolve(out.toDataURL('image/jpeg',0.91));
        }catch(err){reject(err)}
      };
      img.onerror=()=>reject(new Error('Nie udało się odczytać zdjęcia.'));
      img.src=String(a.src||'');
    });
  }

  window.v27SaveAvatar=async function(){
    state.v27=state.v27||{};
    state.v25=state.v25||{};
    const a=state.v27.avatarDraft || state.v25.avatar || emptyAvatar74();

    if(!a.src){
      const empty=emptyAvatar74();
      state.v25.avatar=empty;
      removeUserAvatar74();
      state.v27.avatarDraft=null;
      state.modal=null;
      try{persist()}catch(e){}
      render();
      toast('Zdjęcie usunięte',`Profil ${state.user?.name||''} pokazuje teraz inicjały ${initials74(state.user?.name)}.`);
      return;
    }

    const btn=[...document.querySelectorAll('.modal-foot button')].find(x=>/Zapisz zdjęcie/i.test(x.textContent||''));
    if(btn){btn.disabled=true;btn.textContent='Zapisywanie…'}

    try{
      const cropped=await bakeAvatar74(a);
      const finalAvatar={src:cropped,zoom:100,x:50,y:50};
      state.v25.avatar=finalAvatar;
      saveUserAvatar74(finalAvatar);
      state.v27.avatarDraft=null;
      state.modal=null;
      try{persist()}catch(e){}
      render();
      toast('Zdjęcie zapisane','Zapisano dokładnie kadr widoczny w edytorze.');
    }catch(err){
      console.error('v74 avatar crop',err);
      if(btn){btn.disabled=false;btn.textContent='Zapisz zdjęcie'}
      toast('Nie udało się zapisać zdjęcia','Wybierz zdjęcie ponownie i spróbuj jeszcze raz.');
    }
  };

  window.v27RemoveAvatar=function(){
    state.v27=state.v27||{};
    state.v27.avatarDraft=emptyAvatar74();
    renderOverlay();
  };

  /* Notka w edytorze + inicjały konkretnego użytkownika. */
  const modalBefore74=window.modalHtml;
  window.modalHtml=function(){
    let out=modalBefore74.apply(this,arguments);
    if(state.modal?.type!=='profile') return out;
    try{
      const holder=document.createElement('div');
      holder.innerHTML=out;
      const actions=holder.querySelector('.v27-profile-actions');
      if(actions && !actions.querySelector('.v74-avatar-note')){
        const note=document.createElement('div');
        note.className='v74-avatar-note';
        note.innerHTML='<b>Zdjęcie jest przypisane tylko do tego konta.</b> Kadr zapisze się dokładnie tak, jak widzisz go po lewej. Jeśli usuniesz zdjęcie, pojawią się bordowe inicjały użytkownika.';
        actions.appendChild(note);
      }
      out=holder.innerHTML;
    }catch(e){}
    return out;
  };

  try{render()}catch(e){}
})();
;

/* 072 — ub-v78-final-branding-polish-script */
(function(){
  document.documentElement.dataset.upbonusBuild='v78-final-branding-polish';
  const oldApply=window.applyTheme;
  if(typeof oldApply==='function'){
    window.applyTheme=function(){
      const r=oldApply.apply(this,arguments);
      try{
        const t=typeof tenant==='function'?tenant():null;
        if(t){
          const root=document.documentElement;
          root.style.setProperty('--brand-primary',t.primary||'#6b174e');
          root.style.setProperty('--brand-accent',t.accent||'#8d62c4');
          root.style.setProperty('--brand-soft',t.soft||'color-mix(in srgb,var(--brand-primary) 8%,#fff)');
        }
      }catch(e){}
      return r;
    };
  }
  function labelProfiles(){
    document.querySelectorAll('.profile-btn').forEach(btn=>{
      const name=btn.querySelector('b')?.textContent?.trim()||'Profil pracownika';
      const sub=btn.querySelector('span:last-child span')?.textContent?.trim()||'';
      btn.title=sub?`${name} — ${sub}`:name;
      btn.setAttribute('aria-label',sub?`${name}, ${sub}`:name);
    });
  }
  const mo=new MutationObserver(labelProfiles);mo.observe(document.documentElement,{subtree:true,childList:true});
  labelProfiles();
})();
;

