function groups86(){return state.tenant==='erste'?[['Pracownicy',employees86().filter(x=>x.group==='Pracownicy').length],['Managerowie',employees86().filter(x=>x.group==='Managerowie').length],['Marketing',employees86().filter(x=>x.department==='Marketing').length],['Sprzedaż',employees86().filter(x=>x.department==='Sprzedaż').length]]:[['Pracownicy',Math.max(1,employees86().length)],['Managerowie',2],['Nowi pracownicy',4],['Zarząd',2]]}
function wellData86(){return [
 {id:'move30',icon:'🚶',title:'30 dni ruchu',tag:'+80 Kudos',desc:'Wyzwanie kroków z rankingiem i nagrodą.',duration:'30 dni',how:'Połącz aplikację fitness lub wpisuj wynik ręcznie. Każdy tydzień ma własny cel.',reward:'80 Kudos po ukończeniu',steps:['Dołącz do wyzwania','Synchronizuj kroki lub wpisuj wynik','Osiągnij 20 aktywnych dni','Odbierz Kudosy']},
 {id:'sleep14',icon:'😴',title:'14 dni lepszego snu',tag:'+40 Kudos',desc:'Codzienna checklista, mikroedukacja i małe nawyki.',duration:'14 dni',how:'Każdego dnia odhaczasz 3 proste zachowania wspierające regenerację.',reward:'40 Kudos za minimum 11 dni',steps:['Ustaw cel snu','Odhaczaj wieczorną checklistę','Sprawdź raport po 7 dniach','Odbierz punkty']},
 {id:'mind',icon:'🧠',title:'Miesiąc dobrostanu',tag:'Program',desc:'Webinary, konsultacje i materiały na stres i koncentrację.',duration:'4 tygodnie',how:'Wybierz wydarzenia z kalendarza i zapisuj się bezpośrednio z platformy.',reward:'Udział + materiały po spotkaniu',steps:['Wybierz temat','Zapisz się na webinar','Dodaj konsultację opcjonalnie','Pobierz materiały']},
 {id:'bike',icon:'🚴',title:'Rowerowy wrzesień',tag:'+100 Kudos',desc:'Zbieraj kilometry do wspólnego celu firmy.',duration:'1–30 września',how:'Kilometry z aplikacji lub ręcznego wpisu zasilają wynik indywidualny i zespołowy.',reward:'100 Kudos po 120 km',steps:['Dołącz','Wybierz zespół','Dodawaj kilometry','Śledź ranking']},
 {id:'water',icon:'💧',title:'Nawodnienie 2.0',tag:'+25 Kudos',desc:'Lekki challenge z punktami za regularność.',duration:'21 dni',how:'Odhaczaj dzienny cel nawodnienia. Nie zapisujemy danych medycznych.',reward:'25 Kudos za 16 dni',steps:['Ustaw przypomnienia','Odhaczaj cel','Utrzymaj serię','Odbierz Kudosy']},
 {id:'idea',icon:'💡',title:'Zaproponuj akcję',tag:'Feedback',desc:'Pomysł pracownika trafia do HR do oceny.',duration:'2 min',how:'Opisz pomysł i potencjalną grupę odbiorców. HR zobaczy zgłoszenie w panelu.',reward:'Najlepsze pomysły mogą wejść do kalendarza',steps:['Wpisz pomysł','Dodaj krótki opis','Wyślij do HR','Śledź status']}
]}
window.v86WellDetail=id=>{state.modal={type:'v86WellDetail',data:{id}};renderOverlay()};
