window.v91SaveBranding=async function(){
  if(state.tenant==='upbonus'){
    toast('Up Bonus bez zmian','Branding bazowy Up Bonus jest zablokowany. Edytuj wybraną platformę klienta.');
    return;
  }

  const pid=typeof window.upbonusActivePlatformId==='function'
    ?window.upbonusActivePlatformId()
    :null;

  if(!pid){
    toast('Brak platformy','Najpierw wybierz platformę klienta.');
    return;
  }

  state.v7=state.v7||{};
  state.v7.brandingByPlatform=state.v7.brandingByPlatform||{};
  const old=state.v7.brandingByPlatform[pid]||{};
  const c=current91();

  const nextBrand={
    ...old,
    name:document.getElementById('brandName')?.value||tenant().name,
    domain:document.getElementById('brandDomain')?.value||tenant().domain,
    logoText:document.getElementById('brandLogo')?.value||tenant().logo,
    brandMode:document.getElementById('brandMode')?.value||tenant().mode,
    hero:document.getElementById('brandHero')?.value||tenant().hero,
    primary:getColor91('v91Primary',c.primary),
    accent:getColor91('v91Accent',c.accent),
    activeBg:getColor91('v91ActiveBg',c.activeBg),
    activeText:getColor91('v91ActiveText',c.activeText),
    bannerStart:getColor91('v91BannerStart',c.bannerStart),
    bannerEnd:getColor91('v91BannerEnd',c.bannerEnd),
    heroText:getColor91('v91HeroText',c.heroText),
    buttonBg:getColor91('v91ButtonBg',c.buttonBg),
    buttonText:getColor91('v91ButtonText',c.buttonText),
    pageBg:getColor91('v91PageBg',c.pageBg),
    cardBg:getColor91('v91CardBg',c.cardBg),
    topbarBg:getColor91('v91TopbarBg',c.topbarBg),
    sidebarBg:getColor91('v91SidebarBg',c.sidebarBg),
    borderColor:getColor91('v91Border',c.borderColor)
  };

  // Local state gives instant preview, Supabase is durable source of truth.
  state.v7.brandingByPlatform[pid]=nextBrand;
  if(typeof persist==='function')persist();
  if(typeof applyTheme==='function')applyTheme();

  try{
    if(typeof window.ub233SavePlatformBranding!=='function'){
      throw new Error('Supabase branding bridge unavailable');
    }

    await window.ub233SavePlatformBranding(pid,nextBrand);
    toast('Wygląd zapisany',tenant().name+' — branding zapisany w bazie platformy.');
  }catch(err){
    console.error('V233 branding save error',err);
    toast('Nie zapisano w bazie','Podgląd lokalny działa, ale zapis Supabase nie powiódł się.');
  }

  render();
};
window.v91ResetColors=function(){
  if(state.tenant==='upbonus'){
    toast('Up Bonus bez zmian','Bazowy branding Up Bonus pozostaje nienaruszony.');
    return;
  }
  const pid=typeof window.upbonusActivePlatformId==='function'?window.upbonusActivePlatformId():null;
  if(pid&&state.v7?.brandingByPlatform){
    delete state.v7.brandingByPlatform[pid];
  }
  if(typeof persist==='function')persist();
  if(typeof applyTheme==='function')applyTheme();
  render();
  toast('Przywrócono wygląd','Przywrócono domyślny branding tej platformy klienta.');
};

