    if(grp){const key='DER-GRP-'+dep+'-'+grp;if(!map.has(key))map.set(key,{id:key,name:grp,department:dep,description:'Grupa wynikająca z kartoteki pracowników',source:'Kartoteka',status:'Aktywna'})}
