      {ts:'2026-08-11 19:18',user:'Anna Kowalska',module:'Kampanie',action:'Utworzono',object:'CMP-ER-002',details:'Kampania „Lunch — środki wygasają”'},
      {ts:'2026-08-11 17:04',user:'System',module:'Import',action:'Zaimportowano',object:'Import pracowników',details:'24 rekordy zapisane, 2 z ostrzeżeniami'},
      {ts:'2026-08-10 15:21',user:'Jakub Nowak',module:'Programy',action:'Edytowano',object:'PRG-1041',details:'Zmieniono odbiorców programu na grupę Marketing'},
      {ts:'2026-08-10 10:06',user:'Anna Kowalska',module:'Zaproszenia',action:'Wysłano',object:'Zaproszenia do platformy',details:'186 zaproszeń • Erste Benefits'}
