  seedCampaigns94();seedAudit94();
  function audit94(module,action,object,details){
    const id=tenantId94();seedAudit94();
    state.v94.auditByTenant[id].unshift({ts:new Date().toLocaleString('pl-PL',{hour12:false}).replace(',',''),user:user94(),module,action,object,details});
    save94();
  }
  window.v94Audit=audit94;
  const campaigns94=()=>{seedCampaigns94();return state.v94.campaignsByTenant[tenantId94()]};
  const auditRows94=()=>{seedAudit94();return state.v94.auditByTenant[tenantId94()]};
  const groups94=()=>{const rows=state.v86?.employees||[];return [...new Set(rows.map(x=>x.group).filter(Boolean))]};
  const departments94=()=>{const rows=state.v86?.employees||[];return [...new Set(rows.map(x=>x.department||x.dzial).filter(Boolean))]};
  function filteredCampaigns94(){
    const q=(state.v94.campaignSearch||'').toLowerCase();
    return campaigns94().filter(c=>(state.v94.campaignStatus==='all'||c.status===state.v94.campaignStatus)&&(state.v94.campaignType==='all'||c.type===state.v94.campaignType)&&(!q||[c.name,c.type,c.placement,c.audience,c.title].join(' ').toLowerCase().includes(q)));
  }
  function statusClass94(s){return s==='Aktywna'?'live':s==='Zaplanowana'?'scheduled':s==='Archiwalna'?'archived':'draft'}
  function metrics94(){const rows=campaigns94(),active=rows.filter(x=>x.status==='Aktywna').length,scheduled=rows.filter(x=>x.status==='Zaplanowana').length,views=rows.reduce((s,x)=>s+(+x.views||0),0),clicks=rows.reduce((s,x)=>s+(+x.clicks||0),0),conv=rows.reduce((s,x)=>s+(+x.conversions||0),0);return {active,scheduled,views,ctr:views?clicks/views*100:0,conv}}
  window.v94CampaignTab=t=>{state.v94.campaignTab=t;render()};
  window.v94CampaignFilter=(k,v)=>{state.v94[k]=v;render()};
  window.v94NewCampaign=function(){state.v94.editingCampaign={id:'CMP-'+String(Date.now()).slice(-6),name:'',type:'Hero',placement:'Strona główna',audience:'Wszyscy aktywni',audienceMode:'all',from:new Date().toISOString().slice(0,10),to:'2026-12-31',status:'Szkic',title:'Nowa kampania',copy:'Wpisz komunikat kampanii.',cta:'Sprawdź',url:'#',bg1:(tenant()?.primary||'#6b174e'),bg2:(tenant()?.accent||'#8d62c4'),text:'#ffffff',art:'✨',views:0,clicks:0,conversions:0,revenue:0};state.v94.campaignTab='editor';render()};
  window.v94EditCampaign=id=>{const c=campaigns94().find(x=>x.id===id);if(!c)return;state.v94.editingCampaign=JSON.parse(JSON.stringify(c));state.v94.campaignTab='editor';render()};
