   state.v96.regQuery=state.v96.regQuery||'';state.v96.regStatus=state.v96.regStatus||'all';state.v96.regSort=state.v96.regSort||'name-asc';state.v96.regSelected=state.v96.regSelected||[];
   state.v96.registry=state.v96.registry||{accounts:{},cards:{},products:{},orders:{},transactions:{},invitations:{}};
   const R=state.v96.registry;
   R.products['PROD-GIFT-ALLEGRO']=R.products['PROD-GIFT-ALLEGRO']||{id:'PROD-GIFT-ALLEGRO',legacyId:'SKU-ALLEGRO-100',name:'Allegro 100 zł',category:'Karta podarunkowa',brand:'Allegro'};
   R.products['PROD-LUNCH']=R.products['PROD-LUNCH']||{id:'PROD-LUNCH',legacyId:'SKU-LUNCH',name:'Program Lunch',category:'Lunch',brand:'Up Bonus'};
   R.products['PROD-SPORT']=R.products['PROD-SPORT']||{id:'PROD-SPORT',legacyId:'SKU-SPORT',name:'Karta sportowa',category:'Sport',brand:'Partner sportowy'};
   R.products['PROD-WELL']=R.products['PROD-WELL']||{id:'PROD-WELL',legacyId:'SKU-WELL',name:'Budżet wellbeing',category:'Wellbeing',brand:'Up Bonus'};
