     seeds.forEach((s,i)=>{const [tid,eid,pid,unit,qty,date]=s,oid='ORD-2026-'+String(i+1).padStart(5,'0'),txid='TX-2026-'+String(i+1).padStart(6,'0');R.orders[oid]={id:oid,legacyId:'OLDORD-'+(7000+i),tenantId:tid,employeeId:eid,productId:pid,qty,unitPrice:unit,total:unit*qty,status:'completed',date};R.transactions[txid]={id:txid,legacyId:'OLDTX-'+(9900+i),tenantId:tid,employeeId:eid,orderId:oid,productId:pid,amount:unit*qty,type:'purchase',date};});
