 window.v96RemindSelected=()=>remind96(state.v96.regSelected.slice());window.v96RemindOne=id=>remind96([id]);window.v96RemindPending=()=>remind96(emp96().filter(x=>x.invite!=='registered').map(x=>x.id));
 window.v96DownloadRegistrations=function(){const rows=regRows96(),head=['employee_id','user_id','account_id','email','imie_i_nazwisko','dzial','grupa','status_konta','zaproszenie_wyslane','rejestracja','ostatnia_aktywnosc','ponowienia'];const csv='\ufeff'+[head,...rows.map(x=>[x.id,x.userId,x.accountId,x.email,x.name,x.department,x.group,statusLabel96(x.invite)[1],x.sentAt,x.registeredAt,x.last,x.reminders])].map(r=>r.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(';')).join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download='rejestracje-'+tenantId96()+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500)};
 function registrationsView96(){const rows=regRows96(),all=emp96(),counts={registered:0,invited:0,inactive:0,'not-sent':0};all.forEach(x=>counts[x.invite]=(counts[x.invite]||0)+1);return `<div class="v96-page"><div class="v96-head"><div><h1>Rejestracje i dostęp</h1><p>Excelowa kartoteka statusów kont pracowników. Pracodawca widzi, kto się zarejestrował, komu wysłano zaproszenie i komu trzeba wysłać ponaglenie.</p></div><div class="v96-actions"><button onclick="v96DownloadRegistrations()">↓ Pobierz Excel</button><button onclick="v96RemindPending()">Ponów oczekującym</button><button class="primary" onclick="v96RemindSelected()" ${state.v96.regSelected.length?'':'disabled'}>Wyślij zaznaczonym (${state.v96.regSelected.length})</button></div></div><div class="v96-kpis"><article class="v96-kpi"><span>W kartotece</span><b>${all.length}</b><small>${tenantName96()}</small></article><article class="v96-kpi"><span>Zarejestrowano</span><b>${counts.registered}</b><small>${Math.round((counts.registered/Math.max(all.length,1))*100)}% bazy</small></article><article class="v96-kpi"><span>Zaproszono</span><b>${counts.invited}</b><small>oczekuje na rejestrację</small></article><article class="v96-kpi"><span>Nieaktywni</span><b>${counts.inactive}</b><small>wymagają weryfikacji</small></article><article class="v96-kpi"><span>Nie wysłano</span><b>${counts['not-sent']}</b><small>gotowe do wysyłki</small></article></div><section class="v96-panel"><div class="v96-toolbar"><input value="${esc96(state.v96.regQuery)}" placeholder="Szukaj pracownika, ID, e-maila, działu lub grupy…" oninput="v96RegFilter(this.value)"><select onchange="v96RegStatus(this.value)"><option value="all">Wszystkie statusy</option><option value="registered" ${state.v96.regStatus==='registered'?'selected':''}>Zarejestrowano</option><option value="invited" ${state.v96.regStatus==='invited'?'selected':''}>Zaproszono</option><option value="inactive" ${state.v96.regStatus==='inactive'?'selected':''}>Nieaktywny</option><option value="not-sent" ${state.v96.regStatus==='not-sent'?'selected':''}>Nie wysłano</option></select><select onchange="v96RegSort(this.value)"><option value="name-asc" ${state.v96.regSort==='name-asc'?'selected':''}>Pracownik A–Z</option><option value="department-asc" ${state.v96.regSort==='department-asc'?'selected':''}>Dział A–Z</option><option value="status-asc" ${state.v96.regSort==='status-asc'?'selected':''}>Status</option><option value="last-desc" ${state.v96.regSort==='last-desc'?'selected':''}>Ostatnia aktywność</option></select></div><div class="v96-table-wrap"><table class="v96-table"><thead><tr><th><input class="v96-check" type="checkbox" onchange="v96RegToggleAll(this.checked)"></th><th>Employee ID</th><th>Account ID</th><th>Pracownik</th><th>E-mail</th><th>Dział</th><th>Grupa</th><th>Status konta</th><th>Zaproszenie</th><th>Rejestracja</th><th>Ostatnia aktywność</th><th>Akcja</th></tr></thead><tbody>${rows.map(x=>{const st=statusLabel96(x.invite);return `<tr><td><input class="v96-check" type="checkbox" ${state.v96.regSelected.includes(x.id)?'checked':''} onchange="v96RegToggle('${esc96(x.id)}',this.checked)"></td><td class="id">${esc96(x.id)}</td><td class="id">${esc96(x.accountId)}</td><td><b>${esc96(x.name)}</b></td><td>${esc96(x.email)||'—'}</td><td>${esc96(x.department)||'—'}</td><td>${esc96(x.group)||'—'}</td><td><span class="v96-status ${st[0]}">${st[1]}</span></td><td>${esc96(x.sentAt)}</td><td>${esc96(x.registeredAt)}</td><td>${esc96(x.last)}</td><td><div class="v96-row-actions">${x.invite==='registered'?'<button onclick="toast(\'Konto aktywne\',\'Pracownik jest już zarejestrowany.\')">Szczegóły</button>':`<button class="primary" onclick="v96RemindOne('${esc96(x.id)}')">Ponów</button>`}</div></td></tr>`}).join('')}</tbody></table></div></section></div>`}
