 function dashboardView96(){const employees=emp96(),registered=employees.filter(x=>x.invite==='registered'),transactions=tx96(),orders=orders96(),cards=cards96(),programs=(state.v86?.programs||[]).filter(x=>x.clientId===tenantId96()),campaigns=campaigns96(),sales=transactions.reduce((s,x)=>s+Number(x.amount||0),0),activeCards=cards.filter(x=>x.status==='active').length;const prodAgg={};transactions.forEach(x=>{const p=products96()[x.productId]||{name:x.productId,category:'Inne'};prodAgg[x.productId]=prodAgg[x.productId]||{name:p.name,cat:p.category,count:0,value:0};prodAgg[x.productId].count++;prodAgg[x.productId].value+=Number(x.amount||0)});const tops=Object.values(prodAgg).sort((a,b)=>b.value-a.value);const invCounts={registered:0,invited:0,inactive:0,'not-sent':0};employees.forEach(x=>invCounts[x.invite]=(invCounts[x.invite]||0)+1);const audit=audit96().slice(0,5);return `<div class="v96-page"><div class="v96-head"><div><h1>Dashboard zarządczy</h1><p>Wskaźniki liczone ze wspólnego rejestru danych: pracownicy, konta, karty, zamówienia, transakcje, programy i kampanie. Nie są wpisane ręcznie w widok.</p></div><div class="v96-actions"><button onclick="state.section='Użytkownicy i dostęp';render()">Rejestracje</button><button onclick="state.section='Mapa danych i migracja';render()">Mapa danych</button></div></div><div class="v96-kpis"><article class="v96-kpi"><span>Pracownicy</span><b>${employees.length}</b><small>${registered.length} zarejestrowanych</small></article><article class="v96-kpi"><span>Konta aktywne</span><b>${registered.length}</b><small>${Math.round(registered.length/Math.max(employees.length,1)*100)}% kartoteki</small></article><article class="v96-kpi"><span>Aktywne karty</span><b>${activeCards}</b><small>${cards.length} kart w rejestrze</small></article><article class="v96-kpi"><span>Sprzedaż / wykorzystanie</span><b>${money96(sales)}</b><small>${orders.length} zamówień</small></article><article class="v96-kpi"><span>Programy / kampanie</span><b>${programs.length} / ${campaigns.length}</b><small>dla ${tenantName96()}</small></article></div><div class="v96-grid-2"><section class="v96-panel"><div class="v96-panel-head"><div><h3>Co faktycznie dzieje się na platformie</h3><p>Sprzedaż i wybory pracowników liczone z transaction_id → order_id → product_id.</p></div></div><div class="v96-table-wrap"><table class="v96-table" style="min-width:620px"><thead><tr><th>Produkt</th><th>Kategoria</th><th>Transakcje</th><th>Wartość</th></tr></thead><tbody>${tops.length?tops.map(x=>`<tr><td><b>${esc96(x.name)}</b></td><td>${esc96(x.cat)}</td><td>${x.count}</td><td>${money96(x.value)}</td></tr>`).join(''):'<tr><td colspan="4">Brak transakcji w rejestrze.</td></tr>'}</tbody></table></div></section><aside class="v96-panel"><div class="v96-panel-head"><div><h3>Rejestracje i dostęp</h3><p>Status kont na podstawie tych samych rekordów pracowników.</p></div><button class="v96-btn" onclick="state.section='Użytkownicy i dostęp';render()">Otwórz Excel</button></div>${[['Zarejestrowano','registered'],['Zaproszono','invited'],['Nieaktywni','inactive'],['Nie wysłano','not-sent']].map(([l,k])=>`<div class="v96-progress-row"><span>${l}</span><div class="v96-progress"><i style="width:${Math.round((invCounts[k]||0)/Math.max(employees.length,1)*100)}%"></i></div><b>${invCounts[k]||0}</b></div>`).join('')}<div class="v96-actions" style="margin-top:12px"><button class="primary" onclick="v96RemindPending()">Ponów oczekującym</button></div></aside></div><div class="v96-grid-even"><section class="v96-panel"><div class="v96-panel-head"><div><h3>Karty i konta</h3><p>Powiązanie employee_id → account_id → card_id → product_id.</p></div></div><div class="v96-product-list">${cards.length?cards.slice(0,6).map(c=>{const e=employees.find(x=>x.id===c.employeeId)||{},p=products96()[c.productId]||{};return `<div class="v96-product"><div><b>${esc96(p.name||c.productId)}</b><span>${esc96(e.name||c.employeeId)} • ${esc96(c.id)} • konto ${esc96(c.accountId)}</span></div><b>${money96(c.balance)}</b></div>`}).join(''):'<div class="v96-note">Brak kart dla tej organizacji.</div>'}</div></section><section class="v96-panel"><div class="v96-panel-head"><div><h3>Ostatnie zmiany</h3><p>Wspólny audyt tenanta.</p></div><button class="v96-btn" onclick="state.section='Audyt zmian';render()">Pełny audyt</button></div><div class="v96-table-wrap"><table class="v96-table" style="min-width:600px"><thead><tr><th>Data</th><th>Użytkownik</th><th>Moduł</th><th>Akcja</th></tr></thead><tbody>${audit.length?audit.map(a=>`<tr><td>${esc96(a.ts)}</td><td>${esc96(a.user)}</td><td>${esc96(a.module)}</td><td>${esc96(a.action)}</td></tr>`).join(''):'<tr><td colspan="4">Brak zdarzeń.</td></tr>'}</tbody></table></div></section></div></div>`}
 window.v96ExportMigration=function(){const R=state.v96.registry,tid=tenantId96(),rows=[['entity','primary_id','legacy_id','tenant_id','relation'],...emp96().map(x=>['employee',x.id,x.legacyEmployeeId,tid,'user_id='+x.userId+';account_id='+x.accountId]),...Object.values(R.accounts).filter(x=>x.tenantId===tid).map(x=>['account',x.id,x.legacyId,tid,'employee_id='+x.employeeId]),...Object.values(R.cards).filter(x=>x.tenantId===tid).map(x=>['card',x.id,x.legacyId,tid,'employee_id='+x.employeeId+';account_id='+x.accountId+';product_id='+x.productId]),...Object.values(R.orders).filter(x=>x.tenantId===tid).map(x=>['order',x.id,x.legacyId,tid,'employee_id='+x.employeeId+';product_id='+x.productId])];const csv='\ufeff'+rows.map(r=>r.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(';')).join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download='mapa-migracji-'+tid+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500)};
 function migrationView96(){const R=state.v96.registry,employees=emp96(),accounts=Object.values(R.accounts).filter(x=>x.tenantId===tenantId96()),cards=cards96(),orders=orders96(),transactions=tx96(),first=employees[0],card=first?cards.find(x=>x.employeeId===first.id):null,order=first?orders.find(x=>x.employeeId===first.id):null,tx=order?transactions.find(x=>x.orderId===order.id):null;return `<div class="v96-page"><div class="v96-head"><div><h1>Mapa danych i migracja</h1><p>Warstwa przygotowująca IT do migracji AS-IS → TO-BE. Każdy obiekt ma docelowy identyfikator, identyfikator legacy i jawne relacje.</p></div><div class="v96-actions"><button onclick="v96ExportMigration()">↓ Pobierz mapę ID</button></div></div><div class="v96-note"><b>Zasada migracji:</b> nie migrujemy „650 tys. luźnych rekordów”. Migrujemy relacje i tożsamość: tenant → użytkownik/pracownik → konto → karta → produkt → zamówienie → transakcja → program. Legacy ID pozostaje w rekordzie dla audytu, reklamacji i uzgodnień po cut-over.</div><div class="v96-migration-grid" style="margin-top:14px"><article class="v96-mig"><span>Pracownicy</span><b>${employees.length}</b><code>employee_id + legacy_employee_id</code></article><article class="v96-mig"><span>Konta</span><b>${accounts.length}</b><code>account_id + legacy_account_id</code></article><article class="v96-mig"><span>Karty</span><b>${cards.length}</b><code>card_id + legacy_card_id</code></article><article class="v96-mig"><span>Zamówienia / transakcje</span><b>${orders.length} / ${transactions.length}</b><code>order_id + transaction_id</code></article></div><section class="v96-panel"><div class="v96-panel-head"><div><h3>Przykładowy łańcuch referencyjny</h3><p>Ten sam model jest wykorzystywany przez pracownika, HR, BOK, Operacje i Finanse.</p></div></div><div class="v96-chain"><div class="v96-node"><small>tenant_id</small><b>${esc96(tenantId96())}</b></div><span class="v96-arrow">→</span><div class="v96-node"><small>employee_id</small><b>${esc96(first?.id||'EMP-*')}</b></div><span class="v96-arrow">→</span><div class="v96-node"><small>account_id</small><b>${esc96(first?.accountId||'ACC-*')}</b></div><span class="v96-arrow">→</span><div class="v96-node"><small>card_id</small><b>${esc96(card?.id||'CARD-*')}</b></div><span class="v96-arrow">→</span><div class="v96-node"><small>product_id</small><b>${esc96(card?.productId||'PROD-*')}</b></div><span class="v96-arrow">→</span><div class="v96-node"><small>order_id</small><b>${esc96(order?.id||'ORD-*')}</b></div><span class="v96-arrow">→</span><div class="v96-node"><small>transaction_id</small><b>${esc96(tx?.id||'TX-*')}</b></div></div></section><section class="v96-panel" style="margin-top:14px"><div class="v96-panel-head"><div><h3>Rejestr mapowania AS-IS → TO-BE</h3><p>Minimum do przekazania wykonawcy przed estymacją migracji.</p></div></div><div class="v96-table-wrap"><table class="v96-table"><thead><tr><th>Encja</th><th>Docelowe ID</th><th>Legacy ID</th><th>Klucz relacji</th><th>Źródło</th><th>Reguła migracji</th></tr></thead><tbody><tr><td>Pracownik</td><td class="id">employee_id / user_id</td><td class="id">legacy_employee_id</td><td>tenant_id</td><td>HR / stary portal</td><td class="wrap">Upsert po legacy ID + tenant; zachowaj loginy i status konta.</td></tr><tr><td>Konto</td><td class="id">account_id</td><td class="id">legacy_account_id</td><td>employee_id</td><td>ledger / e-konto</td><td class="wrap">Saldo migrowane po uzgodnieniu; wymagany raport kontrolny przed/po.</td></tr><tr><td>Karta</td><td class="id">card_id</td><td class="id">legacy_card_id</td><td>account_id + employee_id</td><td>procesor kart</td><td class="wrap">Zachowaj status, produkt, ostatnie 4 cyfry i relację do konta.</td></tr><tr><td>Produkt</td><td class="id">product_id</td><td class="id">legacy_sku</td><td>program_id</td><td>katalog</td><td class="wrap">Mapowanie SKU 1:1 albo tabela translacji legacy → nowy produkt.</td></tr><tr><td>Zamówienie</td><td class="id">order_id</td><td class="id">legacy_order_id</td><td>employee_id + product_id</td><td>commerce</td><td class="wrap">Historia w zakresie biznesowo/prawnym; zachowaj status i kwoty.</td></tr><tr><td>Transakcja</td><td class="id">transaction_id</td><td class="id">legacy_tx_id</td><td>order_id + account_id</td><td>ledger / płatności</td><td class="wrap">Niemutowalna historia; uzgodnienie sum kontrolnych per tenant/program.</td></tr></tbody></table></div></section></div>`}
 function cardsRegistryView96(){const cards=cards96(),emps=emp96(),R=state.v96.registry;return `<div class="v96-page"><div class="v96-head"><div><h1>Rejestr kart i kont</h1><p>Wspólny widok operacyjny oparty na card_id, account_id, employee_id i product_id.</p></div></div><div class="v96-table-wrap"><table class="v96-table"><thead><tr><th>Card ID</th><th>Legacy ID</th><th>Pracownik</th><th>Account ID</th><th>Produkt</th><th>Status</th><th>Saldo</th></tr></thead><tbody>${cards.map(c=>{const e=emps.find(x=>x.id===c.employeeId)||{},p=R.products[c.productId]||{};return `<tr><td class="id">${esc96(c.id)}</td><td class="id">${esc96(c.legacyId)}</td><td>${esc96(e.name||c.employeeId)}</td><td class="id">${esc96(c.accountId)}</td><td>${esc96(p.name||c.productId)}</td><td>${esc96(c.status)}</td><td>${money96(c.balance)}</td></tr>`}).join('')}</tbody></table></div></div>`}
 const prevSection96=window.renderSection;
 window.renderSection=function(){init96();if(state.role==='hr'&&(state.section==='Użytkownicy i dostęp'||state.section==='Dostępy i blokady'||state.section==='Rejestracje i dostęp'))return registrationsView96();if(['hr','campaigns','operations','finance','superadmin'].includes(state.role)&&state.section==='Dashboard zarządczy')return dashboardView96();if(['hr','superadmin','operations','finance'].includes(state.role)&&state.section==='Mapa danych i migracja')return migrationView96();if(state.role==='operations'&&state.section==='Magazyn kart i kodów')return cardsRegistryView96();return prevSection96.apply(this,arguments)};
 const prevSidebar96=window.sidebar;
