init();
if(typeof ROLE_DEFS!=='undefined'&&ROLE_DEFS.employee&&!ROLE_DEFS.employee.menu.some(x=>x[0]==='Kudos')){const a=ROLE_DEFS.employee.menu;const i=a.findIndex(x=>x[0]==='Wellbeing');a.splice(i<0?a.length:i+1,0,['Kudos','spark']);}
function activeEP(){const emp=currentEmployee();return Object.values(state.v97.programs).find(x=>x.employeeId===emp.id&&x.status==='active')||Object.values(state.v97.programs)[0]}
function activeProgram(){const ep=activeEP();return PROGRAMS.find(x=>x.id===ep?.programId)||PROGRAMS[1]}
function setTab(t){state.v97.wellTab=t;save();render()};window.v97WellTab=setTab;
window.v97ToggleGoal=function(g){const a=state.v97.goals;state.v97.goals=a.includes(g)?a.filter(x=>x!==g):[...a,g];save();render()};
