window.v97StartProgram=function(id){const emp=currentEmployee();Object.values(state.v97.programs).filter(x=>x.employeeId===emp.id).forEach(x=>x.status='paused');const p=PROGRAMS.find(x=>x.id===id);const ep={id:uuid('EPRG'),employeeId:emp.id,tenantId:tid(),programId:id,day:1,status:'active',startedAt:today(),points:0};state.v97.programs[ep.id]=ep;save();render();toast('Program rozpoczęty',p.name+' został dodany do Twojego planu.')};
