  function purchases106(){let rows=orders106().slice();const q=String(state.v106.query||'').toLowerCase(),st=state.v106.status||'all';if(q)rows=rows.filter(o=>`${o.name} ${o.payment||''} ${o.status||''}`.toLowerCase().includes(q));if(st!=='all')rows=rows.filter(o=>o.status===st);return `<div class="v106-history-toolbar"><input value="${E106(state.v106.query||'')}" placeholder="Szukaj produktu lub płatności…" oninput="v106SetQuery(this.value)"><select class="v106-filter" onchange="v106SetStatus(this.value)"><option value="all" ${st==='all'?'selected':''}>Wszystkie statusy</option><option ${st==='Dostarczone'?'selected':''}>Dostarczone</option><option ${st==='Anulowane'?'selected':''}>Anulowane</option><option ${st==='Przyjęte do realizacji'?'selected':''}>Przyjęte do realizacji</option></select></div>${rows.length?`<div class="v107-table-wrap"><table class="v107-history-table"><thead><tr><th>Data</th><th>Produkt</th><th>Płatność</th><th>Kwota</th><th>Status</th><th>Voucher</th><th>Reklamacja</th><th>Anulowanie / zwrot</th></tr></thead><tbody>${rows.map(o=>{const v=voucherFor106(o),cancel=o.status==='Anulowane',delivered=o.status==='Dostarczone';return `<tr><td class="v107-date">${E106(o.date||'—')}</td><td class="v107-product"><span class="v107-product-icon">${E106(v?.icon||'🎁')}</span><b>${E106(o.name)}</b></td><td class="v107-payment">${E106(o.payment||'—')}</td><td class="v107-money">${M106(o.value)}</td><td><span class="status ${delivered?'green':cancel?'red':'amber'}">${E106(o.status||'—')}</span></td><td class="v107-action-cell">${v&&!cancel?`<button class="v107-action" onclick="showModal('v14Voucher',{id:'${E106(v.id)}'})">Pokaż</button>`:'<span class="v107-muted">—</span>'}</td><td class="v107-action-cell">${v&&!cancel?`<button class="v107-action" onclick="v103CreateComplaint('${E106(o.id)}')">Zgłoś</button>`:'<span class="v107-muted">—</span>'}</td><td class="v107-action-cell">${v&&!cancel?`<button class="v107-action danger" onclick="v103CancelOrder('${E106(o.id)}')">Anuluj / zwrot</button>`:cancel?'<span class="v107-muted">Zakończone</span>':'<span class="v107-muted">Niedostępne</span>'}</td></tr>`}).join('')}</tbody></table></div>`:'<div class="empty-state"><h3>Brak zakupów dla wybranych filtrów</h3></div>'}`}

