  const prev106=window.renderSection||renderSection;
  const renderUnified106=function(){if(state.role==='employee'&&['Portfel i budżety','Portfel i środki','Mój portfel'].includes(state.section))return walletUnified106();if(state.role==='employee'&&['Zamówienia i vouchery','Zakupy i historia'].includes(state.section))return historyUnified106();return prev106()};
  window.renderSection=renderUnified106;try{renderSection=renderUnified106}catch(e){}

