window.v13SendKudos=function(){
  const recipient=document.getElementById('v13KudosPerson')?.value||'',type=document.querySelector('input[name="v13KudosType"]:checked')?.value||'',msg=String(document.getElementById('v13KudosMsg')?.value||'').trim();
  const k=KUDOS13.find(x=>x.id===type);
  if(!recipient||!k){toast('Uzupełnij dane','Wybierz osobę i rodzaj podziękowania.');return}
  const self=String(state.user?.name||'').toLowerCase();if(recipient.toLowerCase()===self){toast('Wybierz inną osobę','Nie możesz wysłać kudosa samemu sobie.');return}
  const today=new Date().toISOString().slice(0,10);if((state.v13fix.kudosSent||[]).some(x=>x.recipient===recipient&&x.date===today)){toast('Kudos już wysłany','Tej samej osobie możesz wysłać tylko jeden kudos dziennie.');return}
  if(k.id==='extra'&&msg.length<20){toast('Dodaj krótkie uzasadnienie','Przy „Extra mile” opisz w kilku zdaniach, za co doceniasz tę osobę.');return}
  if(msg.length<5){toast('Dodaj wiadomość','Napisz krótkie podziękowanie dla współpracownika.');return}
  state.v13fix.kudosSent.push({recipient,type:k.id,points:k.points,message:msg,date:today});
  try{persist()}catch(e){};closeModal();render();toast('Kudos wysłany',`${k.icon} ${k.name} • ${k.points} pkt`);
};
