 defs.forEach(function(d){var c=state.v44.cards.find(function(x){return x.id===d[0]||x.name===d[1];});if(!c){state.v44.cards.push({id:d[0],name:d[1],icon:d[2],number:d[3],balance:d[4],status:'Aktywna',valid:d[5],kind:d[6],pin:d[7]});}else{c.valid=c.valid||d[5];c.kind=c.kind||d[6];c.pin=c.pin||d[7];}});
