UB17.cards=function(){
 UB17.ensureCards(); var ek=state.v44.eaccount; var cards=state.v44.cards;
 var cardsHtml=cards.map(function(c){var active=c.status==='Aktywna';return '<article class="v17-card"><div class="v17-card-top"><div class="v17-icon">'+(c.icon||'💳')+'</div><span class="status '+(active?'green':'red')+'">'+UB17.esc(c.status||'Aktywna')+'</span></div><h3>'+UB17.esc(c.name)+'</h3><div style="font:11px ui-monospace;color:var(--brand-muted)">'+UB17.esc(c.number)+' • ważna do '+UB17.esc(c.valid||'08/29')+'</div><div class="v17-balance">'+UB17.money(c.balance)+'</div><div class="v17-actions"><button class="primary-btn" '+(active?'':'disabled')+' onclick="v17StartTransfer(\''+UB17.esc(c.id)+'\')">Zasil</button><button class="secondary-btn" '+(active?'':'disabled')+' onclick="v17OpenPin(\''+UB17.esc(c.id)+'\')">PIN</button><button class="secondary-btn" onclick="v17ReplaceCard(\''+UB17.esc(c.id)+'\')">Zastrzeż / wymień</button></div></article>';}).join('');
 var hist=state.v17.cardTx.map(function(t){return '<div class="v17-history-row"><div><b>'+UB17.esc(t.title)+'</b><small style="display:block;color:var(--brand-muted)">'+UB17.esc(t.date)+'</small></div><span>'+UB17.esc(t.status)+'</span><b>'+(t.amount==null?'':UB17.money(t.amount))+'</b></div>';}).join('');
 return '<div class="employee-dashboard">'+pageHead('E-konto i moje karty','Zarządzaj środkami i kartami przypisanymi do konta.')+'<section class="v17-panel" style="background:linear-gradient(135deg,var(--brand-primary),#351329);color:#fff;margin-bottom:14px"><small style="opacity:.75;text-transform:uppercase;font-weight:900">E-konto</small><div style="font-size:38px;font-weight:900;margin-top:5px">'+UB17.money(ek.balance)+'</div><p style="font-size:11px;opacity:.82">Środki możesz wydać na platformie albo przeksięgować na kartę, jeśli pracodawca włączył tę funkcję.</p></section><div class="v17-note"><b>Samodzielne przeksięgowanie jest aktywne dla tego programu.</b>Pracodawca wcześniej dopuszcza tę funkcję. Zwykła operacja nie wymaga każdorazowej akceptacji BOK/Operacji; Karta Lunch wymaga dodatkowego oświadczenia.</div><section class="employee-section"><div class="employee-section-head"><div><h2>Twoje karty</h2><p>Każda akcja ma osobny proces i potwierdzenie.</p></div></div><div class="v17-cards">'+cardsHtml+'</div></section>'+(hist?'<section class="employee-section" style="margin-top:14px"><h2>Ostatnie operacje kartowe</h2><div class="v17-history">'+hist+'</div></section>':'')+'</div>';
};
window.v17StartTransfer=function(cardId){UB17.ensureCards();var card=state.v44.cards.find(function(c){return c.id===cardId;});if(!card||card.status!=='Aktywna'){toast('Karta niedostępna','Wybierz aktywną kartę.');return;}state.modal={type:'v17Transfer',data:{cardId:cardId}};renderOverlay();};
window.v17ReviewTransfer=function(){var cardId=document.getElementById('v17TransferCard').value,amount=Number(document.getElementById('v17TransferAmount').value||0),card=state.v44.cards.find(function(c){return c.id===cardId;}),ek=state.v44.eaccount;if(amount<=0||!card){toast('Podaj kwotę','Wpisz poprawną kwotę.');return;}if(amount>Number(ek.balance||0)){toast('Za mało środków','Kwota przekracza saldo e-konta.');return;}if(card.kind==='lunch'&&!document.getElementById('v17LunchDeclaration').checked){toast('Potwierdź oświadczenie','Karta Lunch wymaga oświadczenia o przeznaczeniu środków.');return;}state.modal={type:'v17TransferReview',data:{cardId:cardId,amount:amount}};renderOverlay();};
window.v17ExecuteTransfer=function(){var d=state.modal.data,card=state.v44.cards.find(function(c){return c.id===d.cardId;}),ek=state.v44.eaccount,amount=Number(d.amount);if(!card||amount<=0||amount>ek.balance)return;ek.balance=Number((ek.balance-amount).toFixed(2));card.balance=Number((Number(card.balance||0)+amount).toFixed(2));state.v17.cardTx.unshift({date:new Date().toLocaleString('pl-PL'),title:'Przeksięgowanie na '+card.name,status:'Zrealizowane',amount:amount});if(state.v14){state.v14.ewalletBalance=ek.balance;}persist();state.modal={type:'v17TransferSuccess',data:{cardId:card.id,amount:amount,newE:ek.balance,newCard:card.balance}};render();renderOverlay();};
window.v17OpenPin=function(cardId){state.modal={type:'v17PinAuth',data:{cardId:cardId}};renderOverlay();};
window.v17RevealPin=function(){var p=document.getElementById('v17PinPassword').value;if(p.length<3){toast('Potwierdź tożsamość','Wpisz hasło do konta.');return;}state.modal={type:'v17PinShow',data:{cardId:state.modal.data.cardId}};renderOverlay();};
window.v17ReplaceCard=function(cardId){state.modal={type:'v17ReplaceCard',data:{cardId:cardId}};renderOverlay();};
window.v17ConfirmReplace=function(){var d=state.modal.data,card=state.v44.cards.find(function(c){return c.id===d.cardId;});if(!document.getElementById('v17ReplaceConfirm').checked){toast('Potwierdź dyspozycję','Zaznacz potwierdzenie.');return;}var reason=document.getElementById('v17ReplaceReason').value,form=document.getElementById('v17ReplaceForm').value;card.status='Zastrzeżona';state.v44.cards.push({id:'CARD-'+Date.now().toString().slice(-6),name:card.name,icon:card.icon,number:'•••• '+String(Math.floor(1000+Math.random()*9000)),balance:card.balance,status:'W trakcie wydania',valid:'08/29',kind:card.kind,pin:String(Math.floor(1000+Math.random()*9000))});card.balance=0;state.v17.cardTx.unshift({date:new Date().toLocaleString('pl-PL'),title:'Zastrzeżenie i wymiana: '+card.name,status:reason+' • '+form,amount:null});persist();closeModal();render();toast('Dyspozycja przyjęta','Stara karta została zastrzeżona. Nowa karta jest w trakcie wydania.');};

/* integracje */
UB17.ints=[
 {id:'apple',icon:'🍎',name:'Apple Health',desc:'Kroki, treningi i aktywność z iPhone oraz Apple Watch.',scopes:['Aktywność i kroki','Treningi','Sen']},
 {id:'healthconnect',icon:'▶️',name:'Google Health Connect',desc:'Dane aktywności z urządzeń Android.',scopes:['Aktywność i kroki','Treningi','Sen']},
 {id:'garmin',icon:'⌚',name:'Garmin Connect',desc:'Kroki, treningi i wyzwania z zegarka Garmin.',scopes:['Aktywność i kroki','Treningi','Sen']},
 {id:'fitbit',icon:'◇',name:'Fitbit',desc:'Aktywność dzienna, sen i cele zdrowotne.',scopes:['Aktywność i kroki','Treningi','Sen']},
 {id:'teams',icon:'👥',name:'Microsoft Teams',desc:'Powiadomienia, kudosy i komunikacja organizacji.',scopes:['Powiadomienia','Kudosy','Przypomnienia']},
 {id:'calendar',icon:'🗓️',name:'Kalendarz',desc:'Rezerwacje wellbeing i terminy wyzwań.',scopes:['Terminy wellbeing','Przypomnienia','Rezerwacje']}
];
UB17.integrations=function(){var cards=UB17.ints.map(function(x){var s=state.v17.integrations[x.id]||{connected:false};return '<article class="v17-integration"><div class="v17-int-top"><div class="v17-icon">'+x.icon+'</div><div><h3>'+x.name+'</h3><p style="font-size:10px;color:var(--brand-muted)">'+x.desc+'</p></div></div><div class="v17-int-foot"><span class="status '+(s.connected?'green':'gray')+'">'+(s.connected?'Połączono':'Niepołączona')+'</span>'+(s.connected?'<button class="secondary-btn" onclick="v17DisconnectIntegration(\''+x.id+'\')">Zarządzaj</button>':'<button class="primary-btn" onclick="v17StartIntegration(\''+x.id+'\')">Połącz</button>')+'</div>'+(s.connected&&s.lastSync?'<small style="display:block;color:var(--brand-muted);margin-top:7px">Ostatnia synchronizacja: '+UB17.esc(s.lastSync)+'</small>':'')+'</article>';}).join('');return '<div class="employee-dashboard">'+pageHead('Integracje i aplikacje','Połącz usługę dopiero po zgodzie i autoryzacji.')+'<div class="v17-note"><b>Samo kliknięcie „Połącz” nie aktywuje integracji.</b>Najpierw wybierasz zakres danych, potem autoryzujesz usługę. Status „Połączono” pojawia się dopiero po zakończeniu procesu.</div><div class="v17-integrations">'+cards+'</div></div>';};
window.v17StartIntegration=function(id){state.modal={type:'v17IntConsent',data:{id:id}};renderOverlay();};
window.v17IntNext=function(){var scopes=Array.prototype.slice.call(document.querySelectorAll('input[name="v17Scope"]:checked')).map(function(i){return i.value;});if(!scopes.length){toast('Wybierz zakres','Zaznacz co najmniej jeden rodzaj danych.');return;}state.modal={type:'v17IntAuth',data:{id:state.modal.data.id,scopes:scopes}};renderOverlay();};
window.v17IntAuthorize=function(){var d=state.modal.data;state.v17.integrations[d.id]={connected:true,lastSync:new Date().toLocaleString('pl-PL'),scopes:d.scopes};persist();state.modal={type:'v17IntSuccess',data:{id:d.id}};render();renderOverlay();};
window.v17DisconnectIntegration=function(id){state.modal={type:'v17IntDisconnect',data:{id:id}};renderOverlay();};
window.v17IntDisconnect=function(){var id=state.modal.data.id;state.v17.integrations[id]={connected:false,lastSync:null,scopes:[]};persist();closeModal();render();toast('Integracja rozłączona','Dostęp do nowych danych został wyłączony.');};

/* finalne przechwycenie sekcji */
UB17.prevSection=window.renderSection;
window.renderSection=function(){
 if(state.role==='employee'&&state.section==='Wellbeing')return UB17.wellbeing();
 if(state.role==='employee'&&['E-konto i karta','E-konto i karty','Karty i e-konto'].indexOf(state.section)>=0)return UB17.cards();
 if(state.role==='employee'&&state.section==='Integracje i aplikacje')return UB17.integrations();
 return UB17.prevSection.apply(this,arguments);
};

/* modale */
UB17.prevModal=window.modalHtml;
window.modalHtml=function(){
 var type=state.modal&&state.modal.type,d=(state.modal&&state.modal.data)||{};
 if(type==='v17Activity')return '<div class="modal-backdrop"><section class="modal small"><div class="modal-head"><h3>Dodaj aktywność</h3><button class="close-btn" onclick="closeModal()">×</button></div><div class="modal-body"><div class="field"><label>Rodzaj</label><select id="v17ActType"><option>Spacer</option><option>Rower</option><option>Trening</option><option>Regeneracja</option><option>Mindfulness</option></select></div><div class="form-columns" style="margin-top:12px"><div class="field"><label>Data</label><input id="v17ActDate" type="date" value="'+UB17.today()+'"></div><div class="field"><label>Czas w minutach</label><input id="v17ActMinutes" type="number" min="1" value="30"></div></div></div><div class="modal-foot"><button class="secondary-btn" onclick="closeModal()">Anuluj</button><button class="primary-btn" onclick="v17SaveActivity()">Zapisz</button></div></section></div>';
 if(type==='v17WellSupport'){var wx=UB17.support.find(function(x){return x.id===d.id;});return '<div class="modal-backdrop"><section class="modal small"><div class="modal-head"><h3>'+UB17.esc(wx.name)+'</h3><button class="close-btn" onclick="closeModal()">×</button></div><div class="modal-body"><p>'+UB17.esc(wx.desc)+'</p><div class="v17-note">Dostępność i ewentualna odpłatność wynikają z programu pracodawcy.</div></div><div class="modal-foot"><button class="primary-btn" onclick="closeModal();toast(\'Wellbeing\',\'Pokazano dostępne warianty i terminy.\')">Zobacz opcje</button></div></section></div>';}
 if(type==='v17Transfer'){UB17.ensureCards();var card=state.v44.cards.find(function(c){return c.id===d.cardId;})||state.v44.cards[0],ek=state.v44.eaccount,opts=state.v44.cards.filter(function(c){return c.status==='Aktywna';}).map(function(c){return '<option value="'+UB17.esc(c.id)+'" '+(c.id===card.id?'selected':'')+'>'+UB17.esc(c.name)+' • '+UB17.esc(c.number)+' • '+UB17.money(c.balance)+'</option>';}).join('');return '<div class="modal-backdrop"><section class="modal small"><div class="modal-head"><div><h3>Zasil kartę z e-konta</h3><span>Samodzielna dyspozycja w ramach programu</span></div><button class="close-btn" onclick="closeModal()">×</button></div><div class="modal-body"><div class="v17-note"><b>Operacja wykona się po Twoim potwierdzeniu.</b>Pracodawca wcześniej włączył tę możliwość w programie, dlatego nie wymaga ona osobnej akceptacji BOK/Operacji.</div><div class="field"><label>Karta docelowa</label><select id="v17TransferCard" onchange="state.modal.data.cardId=this.value;renderOverlay()">'+opts+'</select></div><div class="field" style="margin-top:12px"><label>Kwota</label><input id="v17TransferAmount" type="number" min="0.01" max="'+ek.balance+'" step="0.01"><div class="help">Dostępne: '+UB17.money(ek.balance)+'</div></div>'+(card.kind==='lunch'?'<label class="v17-check"><input id="v17LunchDeclaration" type="checkbox"><span><b>Potwierdzam przeznaczenie środków na posiłki i żywność.</b></span></label>':'')+'</div><div class="modal-foot"><button class="secondary-btn" onclick="closeModal()">Anuluj</button><button class="primary-btn" onclick="v17ReviewTransfer()">Dalej</button></div></section></div>';}
 if(type==='v17TransferReview'){var cr=state.v44.cards.find(function(c){return c.id===d.cardId;}),er=state.v44.eaccount;return '<div class="modal-backdrop"><section class="modal small"><div class="modal-head"><h3>Sprawdź i potwierdź</h3><button class="close-btn" onclick="closeModal()">×</button></div><div class="modal-body"><div class="v13-confirm-summary"><div class="v13-confirm-row"><span>Kwota</span><b>'+UB17.money(d.amount)+'</b></div><div class="v13-confirm-row"><span>Karta</span><b>'+UB17.esc(cr.name)+'</b></div><div class="v13-confirm-row"><span>E-konto po operacji</span><b>'+UB17.money(er.balance-d.amount)+'</b></div><div class="v13-confirm-row"><span>Karta po operacji</span><b>'+UB17.money(cr.balance+d.amount)+'</b></div></div></div><div class="modal-foot"><button class="secondary-btn" onclick="state.modal={type:\'v17Transfer\',data:{cardId:\''+UB17.esc(d.cardId)+'\'}};renderOverlay()">Wróć</button><button class="primary-btn" onclick="v17ExecuteTransfer()">Potwierdź</button></div></section></div>';}
 if(type==='v17TransferSuccess')return '<div class="modal-backdrop"><section class="modal small"><div class="modal-body"><div class="v17-success"><div class="ok">✓</div><h3>Środki zostały przeksięgowane</h3><p>'+UB17.money(d.amount)+' trafiło na kartę.</p></div></div><div class="modal-foot"><button class="primary-btn" onclick="closeModal()">Gotowe</button></div></section></div>';
 if(type==='v17PinAuth')return '<div class="modal-backdrop"><section class="modal small"><div class="modal-head"><h3>Pokaż PIN</h3><button class="close-btn" onclick="closeModal()">×</button></div><div class="modal-body"><p>Potwierdź tożsamość hasłem do konta.</p><div class="field"><label>Hasło</label><input id="v17PinPassword" type="password"></div></div><div class="modal-foot"><button class="secondary-btn" onclick="closeModal()">Anuluj</button><button class="primary-btn" onclick="v17RevealPin()">Potwierdź</button></div></section></div>';
 if(type==='v17PinShow'){var cp=state.v44.cards.find(function(c){return c.id===d.cardId;});return '<div class="modal-backdrop"><section class="modal small"><div class="modal-head"><h3>PIN do karty</h3><button class="close-btn" onclick="closeModal()">×</button></div><div class="modal-body"><div class="v17-success"><p>'+UB17.esc(cp.name)+' • '+UB17.esc(cp.number)+'</p><div style="font:900 36px ui-monospace;letter-spacing:.2em">'+UB17.esc(cp.pin)+'</div></div></div><div class="modal-foot"><button class="primary-btn" onclick="closeModal()">Zamknij</button></div></section></div>';}
 if(type==='v17ReplaceCard'){var rr=state.v44.cards.find(function(c){return c.id===d.cardId;});return '<div class="modal-backdrop"><section class="modal small"><div class="modal-head"><div><h3>Zastrzeż / wymień kartę</h3><span>'+UB17.esc(rr.name)+' • '+UB17.esc(rr.number)+'</span></div><button class="close-btn" onclick="closeModal()">×</button></div><div class="modal-body"><div class="field"><label>Powód</label><select id="v17ReplaceReason"><option>Karta zgubiona</option><option>Karta skradziona</option><option>Karta uszkodzona</option><option>Karta nie działa</option></select></div><div class="field" style="margin-top:12px"><label>Nowa karta</label><select id="v17ReplaceForm"><option>Karta wirtualna</option><option>Karta fizyczna</option></select></div><label class="v17-check"><input id="v17ReplaceConfirm" type="checkbox"><span><b>Potwierdzam zastrzeżenie obecnej karty i wymianę.</b></span></label></div><div class="modal-foot"><button class="secondary-btn" onclick="closeModal()">Anuluj</button><button class="danger-btn" onclick="v17ConfirmReplace()">Zastrzeż i wymień</button></div></section></div>';}
 if(type==='v17IntConsent'){var ix=UB17.ints.find(function(x){return x.id===d.id;}),checks=ix.scopes.map(function(s,i){return '<label class="v17-check"><input name="v17Scope" type="checkbox" value="'+UB17.esc(s)+'" '+(i===0?'checked':'')+'><span><b>'+UB17.esc(s)+'</b></span></label>';}).join('');return '<div class="modal-backdrop"><section class="modal small"><div class="modal-head"><div><h3>Połącz '+UB17.esc(ix.name)+'</h3><span>Krok 1 z 2</span></div><button class="close-btn" onclick="closeModal()">×</button></div><div class="modal-body"><div class="v17-steps"><div class="v17-step active">1. Zakres danych</div><div class="v17-step">2. Autoryzacja</div></div><p>Wybierz dane, które chcesz udostępnić.</p>'+checks+'</div><div class="modal-foot"><button class="secondary-btn" onclick="closeModal()">Anuluj</button><button class="primary-btn" onclick="v17IntNext()">Dalej</button></div></section></div>';}
 if(type==='v17IntAuth'){var ia=UB17.ints.find(function(x){return x.id===d.id;});return '<div class="modal-backdrop"><section class="modal small"><div class="modal-head"><div><h3>Autoryzacja '+UB17.esc(ia.name)+'</h3><span>Krok 2 z 2</span></div><button class="close-btn" onclick="closeModal()">×</button></div><div class="modal-body"><div class="v17-steps"><div class="v17-step">1. Zakres danych</div><div class="v17-step active">2. Autoryzacja</div></div><div class="v17-note"><b>Teraz następuje autoryzacja po stronie dostawcy.</b>W produkcji użytkownik przejdzie do '+UB17.esc(ia.name)+' lub ustawień urządzenia i wróci po udzieleniu zgody.</div><p><b>Zakres:</b> '+d.scopes.map(UB17.esc).join(' • ')+'</p></div><div class="modal-foot"><button class="secondary-btn" onclick="state.modal={type:\'v17IntConsent\',data:{id:\''+UB17.esc(d.id)+'\'}};renderOverlay()">Wróć</button><button class="primary-btn" onclick="v17IntAuthorize()">Autoryzuj dostęp</button></div></section></div>';}
 if(type==='v17IntSuccess'){var isx=UB17.ints.find(function(x){return x.id===d.id;});return '<div class="modal-backdrop"><section class="modal small"><div class="modal-body"><div class="v17-success"><div class="ok">✓</div><h3>'+UB17.esc(isx.name)+' połączono</h3><p>Synchronizowane będą wyłącznie zaakceptowane dane.</p></div></div><div class="modal-foot"><button class="primary-btn" onclick="closeModal()">Gotowe</button></div></section></div>';}
 if(type==='v17IntDisconnect')return '<div class="modal-backdrop"><section class="modal small"><div class="modal-head"><h3>Rozłącz integrację</h3><button class="close-btn" onclick="closeModal()">×</button></div><div class="modal-body"><p>Po rozłączeniu nowe dane nie będą synchronizowane.</p></div><div class="modal-foot"><button class="secondary-btn" onclick="closeModal()">Zostaw</button><button class="danger-btn" onclick="v17IntDisconnect()">Rozłącz</button></div></section></div>';
 return UB17.prevModal.apply(this,arguments);
};
