/* 097 — v18-wellbeing-final */
(function(){
  function pad(n){return String(n).padStart(2,'0')}
  function key(d){return d.getFullYear()+'-'+pad(d.getMonth()+1)+'-'+pad(d.getDate())}
  function todayKey(){return key(new Date())}
  function ensure(){
    state.v18well=state.v18well||{days:{},timer:{running:false,left:180,lastKey:''}};
    var k=todayKey();
    state.v18well.days[k]=state.v18well.days[k]||{water:0,walk:false,breakDone:false,stretch:false,daily:false};
    return state.v18well.days[k];
  }
  function save(){try{persist()}catch(e){try{localStorage.setItem('upbonus_state',JSON.stringify(state))}catch(_){}}}
  function dayCompleted(d){return d && ((d.water||0)>=8 || d.walk || d.breakDone || d.stretch || d.daily)}
  function activeDays(){return Object.values(state.v18well?.days||{}).filter(dayCompleted).length}
  function streak(){
    var n=0,d=new Date();
    for(var i=0;i<60;i++){var x=state.v18well?.days?.[key(d)];if(dayCompleted(x)){n++;d.setDate(d.getDate()-1)}else break}
    return n;
  }
  var micro=[
    ['🌤️','10 minut na świeżym powietrzu','Wyjdź na krótki spacer albo po prostu pobądź 10 minut na zewnątrz.'],
    ['🧍','Rozruszaj plecy i barki','Poświęć 3 minuty na spokojne rozciągnięcie szyi, barków i pleców.'],
    ['🥗','Dodaj coś świeżego do posiłku','Owoc, warzywo albo prostą sałatkę — bez liczenia kalorii.'],
    ['📵','5 minut bez telefonu','Odłóż telefon i przez 5 minut nie sprawdzaj powiadomień.'],
    ['🚶','Przejdź kawałek pieszo','Wybierz schody albo przejdź jeden krótki odcinek zamiast podjeżdżać.'],
    ['🌬️','3 spokojne minuty','Usiądź wygodnie i przez 3 minuty oddychaj wolniej niż zwykle.'],
    ['💬','Zrób krótką przerwę na rozmowę','Oderwij się od ekranu i porozmawiaj chwilę z kimś obok.']
  ];
  function microForToday(){var d=new Date(),start=new Date(d.getFullYear(),0,0),idx=Math.floor((d-start)/86400000)%micro.length;return micro[idx]}
  function fmtDate(d){return d.toLocaleDateString('pl-PL',{weekday:'long',day:'numeric',month:'long'})}
  function weekDays(){
    var now=new Date(),monday=new Date(now);monday.setDate(now.getDate()-((now.getDay()+6)%7));
    var out=[];for(var i=0;i<7;i++){var d=new Date(monday);d.setDate(monday.getDate()+i);out.push(d)}return out;
  }
  function todayScore(d){var n=0;if((d.water||0)>=8)n++;if(d.walk)n++;if(d.breakDone)n++;if(d.stretch)n++;return n}
  function habitButton(done,label,fn){return done?'<button class="secondary-btn" disabled>✓ Zrobione</button>':'<button class="primary-btn" onclick="'+fn+'">'+label+'</button>'}
  function renderWell(){
    var d=ensure(),microDay=microForToday(),score=todayScore(d),wk=weekDays(),timer=state.v18well.timer||{running:false,left:180};
    var water=Math.min(8,Number(d.water||0));
    var waterDots='';for(var i=1;i<=8;i++)waterDots+=i<=water?'●':'○';
    return '<div class="employee-dashboard"><div class="v18-well">'
      +'<div class="v18-hero"><div><div class="eyebrow" style="color:#f3cfe5">WELLBEING NA DZIŚ</div><h2>Małe rzeczy. Jedna minuta, kilka kroków, jedna szklanka.</h2><p>Nie musisz prowadzić dziennika ani dołączać do wielkich wyzwań. Zaznacz tylko to, co faktycznie udało Ci się zrobić.</p></div><div class="v18-date">'+fmtDate(new Date())+'</div></div>'
      +'<div class="v18-kpis"><div class="v18-kpi"><span>Dzisiaj</span><b>'+score+' / 4</b><small>proste nawyki</small></div><div class="v18-kpi"><span>Seria</span><b>'+streak()+' dni</b><small>kolejne aktywne dni</small></div><div class="v18-kpi"><span>Aktywne dni</span><b>'+activeDays()+'</b><small>łącznie w historii</small></div></div>'
      +'<section class="employee-section"><div class="employee-section-head"><div><h2>Dzisiaj</h2><p>Wszystko masz od razu na ekranie. Bez formularza „dodaj aktywność”.</p></div></div><div class="v18-today">'
      +'<article class="v18-habit '+(water>=8?'done':'')+'"><div class="ico">💧</div><h3>Woda</h3><p>Cel dnia: 8 szklanek. Kliknij za każdym razem, gdy wypijesz kolejną.</p><div class="big">'+water+' / 8</div><div class="sub" style="letter-spacing:.12em">'+waterDots+'</div><div class="actions v18-water-controls"><button class="primary-btn" '+(water>=8?'disabled':'')+' onclick="v18Water()">+ 1 szklanka</button><button class="secondary-btn" '+(water<=0?'disabled':'')+' onclick="v18WaterUndo()">−</button></div>'+(water>=8?'<div class="v18-complete">✓ Dzisiejszy cel zrealizowany</div>':'')+'</article>'
      +'<article class="v18-habit '+(d.walk?'done':'')+'"><div class="ico">🚶</div><h3>20 minut spaceru</h3><p>Może być droga do pracy, spacer po lunchu albo wyjście z psem.</p><div class="big">20 min</div><div class="sub">bez liczenia kroków</div><div class="actions">'+habitButton(d.walk,'Oznacz jako zrobione','v18Done(\'walk\')')+'</div></article>'
      +'<article class="v18-habit '+(d.breakDone?'done':'')+'"><div class="ico">👀</div><h3>Przerwa od monitora</h3><p>Uruchom 3 minuty. Wstań, odejdź od ekranu i daj odpocząć oczom.</p><div class="big v18-timer" id="v18Timer">'+(d.breakDone?'00:00':pad(Math.floor(timer.left/60))+':'+pad(timer.left%60))+'</div><div class="sub">timer działa na tej stronie</div><div class="actions">'+(d.breakDone?'<button class="secondary-btn" disabled>✓ Zrobione</button>':timer.running?'<button class="secondary-btn" onclick="v18StopTimer()">Pauza</button>':'<button class="primary-btn" onclick="v18StartTimer()">Start 3 min</button>')+'</div></article>'
      +'<article class="v18-habit '+(d.stretch?'done':'')+'"><div class="ico">🧍</div><h3>2 minuty rozciągania</h3><p>Szyja, barki, plecy. Bez przebierania się i bez treningu.</p><div class="big">2 min</div><div class="sub">przy biurku</div><div class="actions">'+habitButton(d.stretch,'Zrobione','v18Done(\'stretch\')')+'</div></article>'
      +'</div></section>'
      +'<section class="v18-daily '+(d.daily?'done':'')+'"><div class="symbol">'+microDay[0]+'</div><div><div class="eyebrow">MIKRO-AKCJA DNIA</div><h3>'+microDay[1]+'</h3><p>'+microDay[2]+' Jutro pojawi się inna.</p></div>'+(d.daily?'<button class="secondary-btn" disabled>✓ Zrobione dzisiaj</button>':'<button class="primary-btn" onclick="v18Done(\'daily\')">Zrobione</button>')+'</section>'
      +'<section class="v18-week"><div class="v18-week-head"><div><h2>Twój tydzień</h2><p>Nie chodzi o perfekcję. Wystarczy jedna zaznaczona rzecz, żeby dzień był aktywny.</p></div></div><div class="v18-days">'+wk.map(function(x){var kd=key(x),xd=state.v18well.days[kd],done=dayCompleted(xd),today=kd===todayKey();return '<div class="v18-day '+(done?'done ':'')+(today?'today':'')+'"><b>'+x.toLocaleDateString('pl-PL',{weekday:'short'})+'</b><span>'+x.getDate()+'</span><i>'+(done?'✓':'·')+'</i></div>'}).join('')+'</div></section>'
      +'<div class="v18-simple-note"><b>Jak to działa?</b> Pracownik może codziennie zaznaczać proste nawyki. Mikro-akcja dnia jest dostępna raz dziennie i zmienia się automatycznie. Nie ma rankingu, publicznego porównywania wyników ani obowiązku podłączania zegarka.</div>'
      +'</div></div>';
  }
  window.v18Water=function(){var d=ensure();d.water=Math.min(8,Number(d.water||0)+1);save();render()};
  window.v18WaterUndo=function(){var d=ensure();d.water=Math.max(0,Number(d.water||0)-1);save();render()};
  window.v18Done=function(k){var d=ensure();d[k]=true;save();render();try{toast('Zapisane','Dobra robota — dzisiejsza aktywność jest już odhaczona.')}catch(e){}};
  var timerHandle=null;
  function timerTick(){
    var t=state.v18well.timer;if(!t||!t.running)return;
    if(t.lastKey!==todayKey()){t.running=false;t.left=180;t.lastKey=todayKey();save();return}
    t.left=Math.max(0,Number(t.left||0)-1);
    var el=document.getElementById('v18Timer');if(el)el.textContent=pad(Math.floor(t.left/60))+':'+pad(t.left%60);
    if(t.left<=0){clearInterval(timerHandle);timerHandle=null;t.running=false;ensure().breakDone=true;t.left=180;save();render();try{toast('3 minuty minęły','Przerwa od ekranu zaliczona ✓')}catch(e){}}
  }
  window.v18StartTimer=function(){ensure();var t=state.v18well.timer;t.running=true;t.lastKey=todayKey();if(!t.left||t.left>180)t.left=180;save();if(timerHandle)clearInterval(timerHandle);timerHandle=setInterval(timerTick,1000);render()};
  window.v18StopTimer=function(){var t=state.v18well.timer;t.running=false;save();if(timerHandle){clearInterval(timerHandle);timerHandle=null}render()};
  var prev=window.renderSection;
  window.renderSection=function(){if(state.role==='employee'&&state.section==='Wellbeing')return renderWell();return prev.apply(this,arguments)};
  try{ensure();save()}catch(e){}
})();
;

