  window.v19Tab=function(t){ensure().employeeTab=t;save();render()};
  function engageShell(body){var x=ensure();return '<div class="employee-dashboard">'+pageHead('Up Bonus Engage','Wyzwania, punkty, docenianie i nagrody w jednym miejscu.')+tabs(x.employeeTab)+body+'</div>'}
  function employeeDashboard(){var x=ensure();return engageShell('<section class="v19-hero"><div><div class="eyebrow" style="color:#efcfe4">TWOJE PUNKTY I AKTYWNOŚCI</div><div class="v19-points">'+money(x.points)+'</div><p>Zdobywaj punkty za aktywności dostępne w programie Twojej firmy i wykorzystuj je na nagrody.</p><div class="v19-hero-meta"><span>🔥 '+x.streak+' dni aktywności z rzędu</span><span>🎯 '+x.monthGoal+'% celu miesięcznego</span><span>Do kolejnej nagrody: '+x.nextReward+' pkt</span></div></div><div style="font-size:72px">✨</div></section><div class="v19-four"><button class="v19-nav-card" onclick="v19Tab(\'challenges\')"><i>🏆</i><b>Moje wyzwania</b><span>3 aktywne</span></button><button class="v19-nav-card" onclick="v19OpenEarn()"><i>⚡</i><b>Zdobywaj punkty</b><span>Zobacz dostępne aktywności</span></button><button class="v19-nav-card" onclick="v19Tab(\'kudos\')"><i>💜</i><b>Kudosy</b><span>Masz '+x.kudosLeft+' z 5 do rozdania</span></button><button class="v19-nav-card" onclick="v19Tab(\'rewards\')"><i>🎁</i><b>Nagrody</b><span>Wymień punkty</span></button></div><section class="v19-goal" style="margin-top:14px"><div class="v19-goal-top"><div><div class="eyebrow">TWÓJ CEL NA SIERPIEŃ</div><h3>Więcej ruchu</h3><p>Zrealizuj jeszcze <b>3 aktywności</b>. Nagroda za ukończenie: <b>+250 pkt</b></p></div><strong style="font-size:28px">76%</strong></div><div class="v19-progress"><i style="width:76%"></i></div><button class="secondary-btn" onclick="v19Tab(\'challenges\')">Zobacz plan</button></section><section class="v19-company" style="margin-top:14px"><div class="eyebrow" style="color:#d8f1e7">COMPANY CHALLENGE</div><h2>Razem dla dobra 🌱</h2><p>Cel firmy: 10 000 000 kroków</p><div style="font-size:30px;font-weight:900">7 840 210</div><div class="v19-progress"><i style="width:78%"></i></div><p><b>128 osób uczestniczy.</b> Jeżeli osiągniemy cel, firma przekazuje 10 000 zł na fundację.</p></section>')}
  function challengeCard(c){var pct=Math.min(100,Math.round(c.done/c.target*100));return '<article class="v19-card"><div class="v19-card-head"><div><h3>'+c.icon+' '+E(c.name)+'</h3><p>'+E(c.desc)+'</p></div><span class="v19-reward">+'+c.reward+' pkt</span></div><div class="v19-progress"><i style="width:'+pct+'%"></i></div><div class="v19-progress-row"><span>'+c.done+' / '+c.target+'</span><span>'+pct+'%</span></div><p>Termin: '+E(c.due)+'</p><button class="secondary-btn" onclick="v19ChallengeDetails(\''+c.id+'\')">Zobacz szczegóły</button></article>'}
  function challenges(){var x=ensure(),f=x.challengeFilter,rows=x.challenges.filter(function(c){return f==='Zakończone'?c.done>=c.target:c.status===f&&c.done<c.target});return engageShell('<div class="v19-filter">'+['Aktywne','Polecane','Zakończone'].map(function(z){return '<button class="v19-chip '+(f===z?'active':'')+'" onclick="v19ChallengeFilter(\''+z+'\')">'+z+'</button>'}).join('')+'</div><div class="v19-grid">'+(rows.length?rows.map(challengeCard).join(''):'<section class="v19-card"><h3>Brak wyzwań w tej kategorii</h3><p>Nowe wyzwania pojawią się zgodnie z programem Twojego pracodawcy.</p></section>')+'</div>')}
