  window.v19ConfirmChallenge=function(id){var x=ensure(),c=x.challenges.find(function(z){return z.id===id});if(!c||c.done>=c.target)return;c.done++;var finished=c.done>=c.target;if(finished){x.points+=c.reward;x.transactions.unshift({date:now(),user:state.user?.name||'Pracownik',source:'Challenge',label:c.name,points:c.reward,type:'earn'});x.monthGoal=Math.min(100,x.monthGoal+8);x.nextReward=Math.max(0,x.nextReward-c.reward)}save();closeModal();render();toast('Aktywność zapisana ✅',finished?'Challenge ukończony. +'+c.reward+' pkt trafiło na Twoje konto.':'Zostało jeszcze '+(c.target-c.done)+' do ukończenia wyzwania.')};
  function earnView(){var x=ensure(),f=x.earnFilter,rows=x.earn.filter(function(a){return f==='Wszystkie'||a.cat===f});return '<div class="employee-dashboard">'+pageHead('Zdobywaj punkty','Katalog możliwości dostępnych w Twoim programie.','<button class="secondary-btn" onclick="selectSection(\'Engagement & Wellbeing\')">← Wróć do Engage</button>')+'<div class="v19-filter">'+['Wszystkie','Ruch','Mental','Rozwój','Relacje','CSR'].map(function(z){return '<button class="v19-chip '+(f===z?'active':'')+'" onclick="v19EarnFilter(\''+z+'\')">'+z+'</button>'}).join('')+'</div><div class="v19-earn-grid">'+rows.map(function(a){return '<article class="v19-earn"><div class="ico">'+a.icon+'</div><h3>'+E(a.name)+'</h3><p>'+E(a.desc)+'</p><strong>+'+a.pts+' pkt</strong></article>'}).join('')+'</div><div class="v18-simple-note" style="margin-top:14px">Liczba punktów i limity są określone przez Twojego pracodawcę.</div></div>'}
