  function kudos(){var x=ensure();return engageShell('<section class="v19-hero" style="grid-template-columns:1fr auto"><div><div class="eyebrow" style="color:#efcfe4">DOCENIAJ INNYCH 💜</div><h2>Masz do rozdania: '+x.kudosLeft+' z 5 kudosów</h2><p>Punkty i liczba kudosów są ustalone przez pracodawcę. Nie wpisujesz własnej wartości.</p></div><button class="primary-btn" style="background:#fff;color:var(--brand-primary)" onclick="v19OpenKudos()">Daj kudosa</button></section><section class="employee-section" style="margin-top:14px"><div class="employee-section-head"><div><h2>Ostatnie kudosy</h2><p>Podziękowania wysłane w Twojej organizacji.</p></div></div><div class="v19-kudos-feed">'+x.kudos.map(function(k){return '<div class="v19-feed"><div class="avatar">'+E(k.from[0])+'</div><div><b>'+E(k.from)+' → '+E(k.to)+' • '+E(k.cat)+'</b><p>'+E(k.msg)+'</p></div><strong>+'+k.pts+' pkt</strong></div>'}).join('')+'</div></section>')}
  window.v19OpenKudos=function(){state.modal={type:'v19Kudos',data:{}};renderOverlay()};
  window.v19SendKudos=function(){var x=ensure();if(x.kudosLeft<=0){toast('Limit wykorzystany','W tym miesiącu nie masz już kudosów do rozdania.');return}var to=document.getElementById('v19KudosTo').value,cat=document.getElementById('v19KudosCat').value,msg=document.getElementById('v19KudosMsg').value.trim();if(!msg){toast('Dodaj wiadomość','Napisz krótkie podziękowanie.');return}x.kudosLeft--;x.kudos.unshift({from:state.user?.name?.split(' ')[0]||'Ty',to:to,cat:cat,msg:msg,pts:10,date:now()});x.points+=5;x.transactions.unshift({date:now(),user:state.user?.name||'Pracownik',source:'Kudos',label:'Wyślij kudosa',points:5,type:'earn'});save();closeModal();render();toast('Kudos wysłany 💜','Za aktywność otrzymujesz +5 pkt zgodnie z programem firmy.')};
  function rewards(){var x=ensure(),f=x.rewardFilter,rows=x.rewards.filter(function(r){return f==='Popularne'||r.cat===f||r.cat==='Popularne'});return engageShell('<section class="v19-hero" style="grid-template-columns:1fr auto"><div><div class="eyebrow" style="color:#efcfe4">NAGRODY</div><div class="v19-points">Masz '+money(x.points)+'</div><p>Wybierz nagrodę. Voucher po odbiorze trafi do istniejącej sekcji zakupów i voucherów.</p></div><div style="font-size:62px">🎁</div></section><div class="v19-filter" style="margin-top:14px">'+['Popularne','Vouchery','Rozrywka','Zakupy','Charity'].map(function(z){return '<button class="v19-chip '+(f===z?'active':'')+'" onclick="v19RewardFilter(\''+z+'\')">'+z+'</button>'}).join('')+'</div><div class="v19-rewards">'+rows.map(function(r){return '<article class="v19-reward-card"><div class="logo">'+r.icon+'</div><h3>'+E(r.name)+'</h3><div class="v19-cost">'+r.pts+' pkt</div><button class="primary-btn full" '+(x.points<r.pts?'disabled':'')+' onclick="v19Redeem(\''+r.id+'\')">Odbierz za '+r.pts+' pkt</button></article>'}).join('')+'</div>')}
  window.v19RewardFilter=function(f){ensure().rewardFilter=f;save();render()};window.v19Redeem=function(id){var x=ensure(),r=x.rewards.find(function(z){return z.id===id});if(!r||x.points<r.pts)return;state.modal={type:'v19Redeem',data:{id:id}};renderOverlay()};
  window.v19ConfirmRedeem=function(id){var x=ensure(),r=x.rewards.find(function(z){return z.id===id});if(!r||x.points<r.pts)return;x.points-=r.pts;x.transactions.unshift({date:now(),user:state.user?.name||'Pracownik',source:r.name,label:'Nagroda',points:-r.pts,type:'redeem'});state.v14=state.v14||{};state.v14.vouchers=state.v14.vouchers||[];state.v14.orders=state.v14.orders||[];var stamp=String(Date.now()).slice(-7),vid='VCH-ENG-'+stamp,oid='ORD-ENG-'+stamp,code='UPB-'+Math.random().toString(36).slice(2,7).toUpperCase()+'-'+Math.random().toString(36).slice(2,7).toUpperCase();state.v14.vouchers.unshift({id:vid,orderId:oid,name:r.name,icon:r.icon,type:'Kod alfanumeryczny',code:code,pin:'',validTo:'31.12.2027',status:'Gotowy'});state.v14.orders.unshift({id:oid,date:now(),name:r.name,value:r.value,status:'Dostarczone',voucherId:vid,payment:r.pts+' pkt Engage'});save();closeModal();render();toast('Nagroda odebrana','Nagroda została dodana do Twoich voucherów.')};
  function hrDashboard(){var x=ensure();return '<div>'+pageHead('Engagement — Dashboard','Zaangażowanie pracowników, punkty, wyzwania i budżet programu.')+'<div class="v19-kpis"><div class="v19-kpi"><span>Aktywni pracownicy</span><b>68%</b><small>ostatnie 30 dni</small></div><div class="v19-kpi"><span>Uczestnicy wyzwań</span><b>54%</b><small>aktywnych osób</small></div><div class="v19-kpi"><span>Kudosy</span><b>1 248</b><small>w tym miesiącu</small></div><div class="v19-kpi"><span>Wydane punkty</span><b>124 650</b><small>earn</small></div><div class="v19-kpi"><span>Koszt programu</span><b>12 465 zł</b><small>bieżący miesiąc</small></div></div><div class="v19-budget"><section class="v19-card"><h3>Najpopularniejsze aktywności</h3><div class="v19-history"><div class="v17-history-row"><b>1. Aktywny tydzień</b><span>71%</span></div><div class="v17-history-row"><b>2. Kudos Friday</b><span>64%</span></div><div class="v17-history-row"><b>3. Zdrowy lunch</b><span>51%</span></div></div></section><section class="v19-card"><h3>Budżet programu</h3><div style="font-size:28px;font-weight:900;margin:10px 0">50 000 zł</div><p>Wykorzystano: 31 400 zł<br>Prognoza: <b>46 200 zł</b></p><div class="v19-progress"><i style="width:92%"></i></div><div class="v19-progress-row"><span>prognozowane wykorzystanie</span><b>92%</b></div></section></div><section class="v19-company" style="margin-top:14px"><div class="eyebrow" style="color:#d8f1e7">COMPANY CHALLENGE</div><h2>Razem dla dobra 🌱</h2><p>7 840 210 / 10 000 000 kroków • 78% • 128 uczestników</p><div class="v19-progress"><i style="width:78%"></i></div><p>Po osiągnięciu celu firma przekazuje 10 000 zł na fundację.</p></section></div>'}
