/* 099 — ub-v20-auth-routing-fix */
(function(){
  'use strict';
  var KEY='upbonus_tab_session_v20';
  var OLD='upbonus_session_v17';
  var EMP='upbonus_employee_portal_context';
  function navType(){try{var n=performance.getEntriesByType&&performance.getEntriesByType('navigation')[0];return n&&n.type||'navigate';}catch(e){return 'navigate'}}
  function clearHash(){try{if(location.hash)history.replaceState(null,'',location.pathname+location.search);}catch(e){}}
  function snapshot(){return {active:true,role:state.role||null,section:state.section||null,tenant:state.tenant,user:state.user,accesses:state.accesses};}
  function saveTab(){try{if(state.loggedIn)sessionStorage.setItem(KEY,JSON.stringify(snapshot()));else sessionStorage.removeItem(KEY);}catch(e){}}
  function clearLegacy(){try{localStorage.removeItem(OLD);}catch(e){}}

  /* v17 used localStorage and therefore authenticated a freshly opened link. Disable it permanently. */
  clearLegacy();

  /* Keep normal application persistence, but never allow it to recreate the legacy auth session. */
  var prevPersist=window.persist;
  window.persist=function(){var r=prevPersist?prevPersist.apply(this,arguments):undefined;clearLegacy();saveTab();return r;};
  var prevRender20=window.render;
  window.render=function(){var r=prevRender20.apply(this,arguments);clearLegacy();saveTab();return r;};

  /* A successful login always lands on the area/workspace selector. */
  window.login=function(e){
    if(e&&e.preventDefault)e.preventDefault();
    var node=document.getElementById('loginEmail');
    var email=String((node&&node.value)||state.user?.email||'').trim().toLowerCase();
    var profile=typeof accessProfile==='function'?accessProfile(email):{name:email.split('@')[0]||'Użytkownik',accesses:['employee']};
    state.user={name:profile.name,email:email};
    state.accesses=profile.accesses||['employee'];
    state.loggedIn=true;
    state.role=null;
    state.section=null;
    state.modal=null;
    state.drawer=null;
    state.mobileMenu=false;
    try{sessionStorage.removeItem(EMP);}catch(x){}
    clearHash();
    saveTab();
    if(typeof persist==='function')persist();
    render();
    if(typeof toast==='function')toast('Zalogowano','Wybierz obszar pracy.');
    return false;
  };

  /* Logout removes the tab session as well as any old persistent session. */
  window.logout=function(){
    try{sessionStorage.removeItem(KEY);sessionStorage.removeItem(EMP);}catch(e){}
    clearLegacy();
    state.loggedIn=false;state.role=null;state.section=null;state.modal=null;state.drawer=null;state.mobileMenu=false;
    clearHash();
    render();
  };

  /* Persist workspace choice only inside this browser tab, so F5 keeps context. */
  var prevOpenRole=window.openRole;
  window.openRole=function(role){var r=prevOpenRole.apply(this,arguments);setTimeout(saveTab,0);return r;};
  var prevSelectSection=window.selectSection;
  window.selectSection=function(label){var r=prevSelectSection.apply(this,arguments);setTimeout(saveTab,0);return r;};
  var prevOpenAccounts=window.openAccounts;
  window.openAccounts=function(){
    try{sessionStorage.removeItem(EMP);}catch(e){}
    state.role=null;state.section=null;state.mobileMenu=false;
    saveTab();render();
  };

  /* Fresh navigation requires login. A true reload restores only this tab's session. */
  var type=navType();
  if(type==='reload'){
    try{
      var saved=JSON.parse(sessionStorage.getItem(KEY)||'null');
      if(saved&&saved.active){
        state.loggedIn=true;
        state.role=saved.role||null;
        state.section=saved.section||null;
        if(saved.tenant)state.tenant=saved.tenant;
        if(saved.user)state.user=saved.user;
        if(saved.accesses)state.accesses=saved.accesses;
        state.modal=null;state.drawer=null;state.mobileMenu=false;
      }else{
        state.loggedIn=false;state.role=null;state.section=null;state.modal=null;state.drawer=null;clearHash();
      }
    }catch(e){state.loggedIn=false;state.role=null;state.section=null;clearHash();}
  }else{
    try{sessionStorage.removeItem(KEY);sessionStorage.removeItem(EMP);}catch(e){}
    state.loggedIn=false;state.role=null;state.section=null;state.modal=null;state.drawer=null;state.mobileMenu=false;
    clearHash();
  }
  clearLegacy();
  setTimeout(function(){render();},0);
})();
;

/* 100 — ub-v21-codes-promos-script */
(function(){
 'use strict';
 if(typeof state==='undefined')return;
 const E21=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 function ensure21(){
   state.v21promos=state.v21promos||{
     offers:[
       {id:'PROMO-001',brand:'adidas',icon:'👟',title:'-20% na wybrane produkty',type:'Kod rabatowy',code:'UPBONUS20',desc:'Specjalny rabat dla użytkowników Up Bonus.',conditions:'Kod działa na wybrane produkty oznaczone w sklepie internetowym partnera. Nie łączy się z innymi kodami. Jednorazowe użycie na zamówienie.',url:'https://www.adidas.pl/',validTo:'31.08.2026',audience:'Wszyscy użytkownicy',status:'Aktywna'},
       {id:'PROMO-002',brand:'Bolt',icon:'🚕',title:'15% taniej na przejazd',type:'Kod rabatowy',code:'BONUS15',desc:'Rabat na przejazd dla użytkowników platformy.',conditions:'Kod obowiązuje w aplikacji partnera na kwalifikujące się przejazdy. Szczegółowe ograniczenia i miasta objęte promocją są wskazane po przejściu do oferty.',url:'https://bolt.eu/pl-pl/',validTo:'15.09.2026',audience:'Wszyscy użytkownicy',status:'Aktywna'},
       {id:'PROMO-003',brand:'Reserved',icon:'🛍️',title:'Dodatkowe -10%',type:'Promocja',code:'',desc:'Oferta partnerska dostępna dla użytkowników platformy.',conditions:'Promocja działa po przejściu z Up Bonus do strony partnera. Rabat dotyczy produktów objętych akcją i obowiązuje w okresie wskazanym w ofercie.',url:'https://www.reserved.com/pl/pl/',validTo:'30.09.2026',audience:'Wszyscy użytkownicy',status:'Aktywna'},
       {id:'PROMO-004',brand:'Cinema City',icon:'🎬',title:'Tańszy zestaw kinowy',type:'Promocja',code:'',desc:'Bonus partnerski dostępny dla użytkowników Up Bonus.',conditions:'Oferta obowiązuje w wybranych kinach i na wskazane zestawy. Szczegóły dostępności są prezentowane po przejściu do promocji.',url:'https://www.cinema-city.pl/',validTo:'31.10.2026',audience:'Wszyscy użytkownicy',status:'Aktywna'}
     ]
   };
   state.v21promos.revealed=state.v21promos.revealed||{};
   state.v21promos.offers.forEach(o=>{if(o.conditions==null)o.conditions=o.desc||'Warunki promocji są dostępne po wejściu w szczegóły oferty.';if(o.url==null)o.url='';});
   return state.v21promos;
 }
 function save21(){try{persist&&persist()}catch(e){}}
 window.v21CopyCode=function(code){try{navigator.clipboard&&navigator.clipboard.writeText(code)}catch(e){};toast('Kod skopiowany','Kod jest gotowy do użycia u partnera.');};
 window.v22OpenPromo=function(id){state.modal={type:'v21PromoDetail',data:{id:id}};renderOverlay();};
 window.v22RevealCode=function(id){const x=ensure21();x.revealed[id]=true;renderOverlay();};
 window.v21UsePromo=function(id){const o=ensure21().offers.find(x=>x.id===id);if(!o||!o.url)return;window.open(o.url,'_blank','noopener,noreferrer');};
 function employee21(){
   const rows=ensure21().offers.filter(x=>x.status==='Aktywna');
   return `<div class="employee-dashboard">${pageHead('Kody i promocje','Darmowe bonusy dostępne dla użytkowników platformy. Nie zużywają punktów ani środków z e-konta.')}
   <div class="v21-promo-hero"><section class="v21-promo-main"><div class="eyebrow" style="color:#f2d7e8">UP BONUS PREMIUM</div><h2>Więcej korzyści bez wydawania środków.</h2><p>Kody rabatowe i promocje partnerów są dostępne dodatkowo — nie pomniejszają Twojego e-konta i nie wymagają punktów.</p><div class="v21-promo-tags"><span>🏷️ kody rabatowe</span><span>🎁 darmowe bonusy</span><span>⚡ oferty czasowe</span></div></section><aside class="v21-promo-side"><h3>Jak to działa?</h3><p>Wybierz ofertę i sprawdź szczegóły. Kod, warunki i link do promocji są dostępne dopiero po wejściu w ofertę.</p><div class="v21-free">0 zł / 0 pkt</div><p>To dodatkowa korzyść dla użytkowników platformy.</p></aside></div>
   <section class="employee-section"><div class="employee-section-head"><div><h2>Dostępne teraz</h2><p>Wejdź w ofertę, aby zobaczyć warunki, link i — jeśli dotyczy — pobrać kod.</p></div></div><div class="v21-promo-grid">${rows.map(o=>`<article class="v21-promo-card"><div class="v21-promo-top"><span class="v21-promo-logo">${E21(o.icon)}</span><span class="v21-free-badge">Darmowy bonus</span></div><h3>${E21(o.brand)} · ${E21(o.title)}</h3><p>${E21(o.desc)}</p><div class="v21-promo-meta">${E21(o.type)} • ważne do ${E21(o.validTo)}</div><div class="v21-promo-actions"><button class="primary-btn" onclick="v22OpenPromo('${E21(o.id)}')">Zobacz ofertę</button></div></article>`).join('')}</div></section></div>`;
 }
 function hr21(){
   const rows=ensure21().offers;
   const tenant=(state.v47?.clients||[]).find(x=>x.id===state.v47?.currentClientId)||(state.v47?.clients||[])[0];
   return `${pageHead('Kody i promocje','Darmowe bonusy publikowane użytkownikom platformy tak samo jak pozostałe oferty.',`<button class="primary-btn" onclick="showModal('v21PromoEdit',{})">＋ Dodaj ofertę</button>`)}<div class="v57-tenant-note">🎁 <span><b>Oferta bez kosztu dla pracownika.</b> Kod lub promocja pojawia się w sekcji Premium użytkownika i nie korzysta z e-konta ani punktów.</span></div><div class="v21-promo-hero"><section class="v21-promo-main"><div class="eyebrow" style="color:#f2d7e8">UP BONUS PREMIUM • KODY I PROMOCJE</div><h2>Publikuj darmowe bonusy jak zwykłą ofertę.</h2><p>Dodajesz partnera, treść, kod lub link, datę ważności i grupę odbiorców. Po publikacji oferta jest od razu dostępna użytkownikom wybranej platformy.</p><div class="v21-promo-tags"><span>bez budżetu pracownika</span><span>segmentacja odbiorców</span><span>harmonogram publikacji</span></div></section><aside class="v21-promo-side"><h3>${E21(tenant?.name||'Wybrana firma')}</h3><p>Aktywne oferty widoczne użytkownikom tej platformy.</p><div class="v21-free">${rows.filter(x=>x.status==='Aktywna').length}</div><p>aktywnych kodów i promocji</p></aside></div><div class="v21-table-wrap"><table class="v21-table"><thead><tr><th>Partner / oferta</th><th>Typ</th><th>Kod</th><th>Odbiorcy</th><th>Ważność</th><th>Status</th><th>Akcje</th></tr></thead><tbody>${rows.map(o=>`<tr><td><b>${E21(o.brand)}</b><br><span>${E21(o.title)}</span></td><td>${E21(o.type)}</td><td>${o.code?`<code>${E21(o.code)}</code>`:'—'}</td><td>${E21(o.audience)}</td><td>${E21(o.validTo)}</td><td><span class="v21-status ${o.status==='Aktywna'?'live':'draft'}">${E21(o.status)}</span></td><td><button class="link-btn" onclick="showModal('v21PromoEdit',{id:'${E21(o.id)}'})">Edytuj</button> <button class="link-btn" onclick="v21TogglePromo('${E21(o.id)}')">${o.status==='Aktywna'?'Wyłącz':'Publikuj'}</button></td></tr>`).join('')}</tbody></table></div>`;
 }
 window.v21TogglePromo=function(id){const o=ensure21().offers.find(x=>x.id===id);if(!o)return;o.status=o.status==='Aktywna'?'Szkic':'Aktywna';save21();render();toast('Status oferty',o.status)};
 window.v21SavePromo=function(){
   const d=state.modal?.data||{}, x=ensure21(), existing=x.offers.find(o=>o.id===d.id);
   const val=id=>String(document.getElementById(id)?.value||'').trim();
   const obj=existing||{id:'PROMO-'+String(Date.now()).slice(-6),icon:'🏷️'};
   obj.brand=val('v21Brand')||'Partner';obj.title=val('v21Title')||'Nowa promocja';obj.type=val('v21Type')||'Kod rabatowy';obj.code=val('v21Code');obj.desc=val('v21Desc')||'Darmowy bonus dla użytkowników platformy.';obj.conditions=val('v22Conditions')||obj.desc;obj.url=val('v22Url');obj.validTo=val('v21Valid')||'31.12.2026';obj.audience=val('v21Audience')||'Wszyscy użytkownicy';obj.status=val('v21Status')||'Szkic';
   if(!existing)x.offers.unshift(obj);state.modal=null;save21();render();toast('Oferta zapisana',obj.status==='Aktywna'?'Promocja jest widoczna użytkownikom.':'Oferta została zapisana jako szkic.');
 };
 const prevModal21=window.modalHtml;
 window.modalHtml=function(){
   const t=state.modal?.type,d=state.modal?.data||{};
   if(t==='v21PromoDetail'){
     const x=ensure21(),o=x.offers.find(v=>v.id===d.id);if(!o)return '';
     const shown=!!x.revealed[o.id];
     return `<div class="modal-backdrop" onclick="if(event.target===this)closeModal()"><section class="modal"><div class="modal-head"><div><h3>Kody i promocje</h3><span style="font-size:10px;color:var(--brand-muted)">Szczegóły oferty</span></div><button class="close-btn" onclick="closeModal()">×</button></div><div class="modal-body"><div class="v22-promo-detail-head"><div class="v22-promo-detail-logo">${E21(o.icon)}</div><div><div class="eyebrow">${E21(o.brand)}</div><h2>${E21(o.title)}</h2><p>${E21(o.desc)}</p><div class="v21-promo-meta">${E21(o.type)} • ważne do ${E21(o.validTo)}</div></div></div><div class="v22-promo-section"><h4>Warunki korzystania z promocji</h4><p>${E21(o.conditions||'Szczegóły warunków nie zostały jeszcze uzupełnione.')}</p></div>${o.url?`<div class="v22-promo-section"><h4>Gdzie działa promocja?</h4><p>Oferta działa pod linkiem partnera wskazanym dla tej promocji.</p><div class="v22-link-note">Po kliknięciu otworzy się strona partnera w nowej karcie.</div></div>`:''}${o.code?(shown?`<div class="v22-code-revealed"><div><small>Kod promocyjny</small><code>${E21(o.code)}</code></div><button class="primary-btn" onclick="v21CopyCode('${E21(o.code)}')">Kopiuj kod</button></div>`:`<div class="v22-code-locked"><div><small>Kod promocyjny</small><div class="masked">••••••••</div></div><button class="primary-btn" onclick="v22RevealCode('${E21(o.id)}')">Pokaż kod</button></div>`):''}</div><div class="modal-foot"><button class="secondary-btn" onclick="closeModal()">Zamknij</button>${o.url?`<button class="primary-btn" onclick="v21UsePromo('${E21(o.id)}')">Przejdź do promocji</button>`:''}</div></section></div>`;
   }
   if(t==='v21PromoEdit'){
     const o=ensure21().offers.find(x=>x.id===d.id)||{};
     return `<div class="modal-backdrop" onclick="if(event.target===this)closeModal()"><section class="modal"><div class="modal-head"><div><h3>${o.id?'Edytuj':'Dodaj'} kod lub promocję</h3><span style="font-size:10px;color:var(--brand-muted)">Publikacja działa jak zwykła oferta katalogowa.</span></div><button class="close-btn" onclick="closeModal()">×</button></div><div class="modal-body"><div class="form-columns"><div class="field"><label>Partner / marka *</label><input id="v21Brand" value="${E21(o.brand||'')}" placeholder="np. adidas"></div><div class="field"><label>Nazwa oferty *</label><input id="v21Title" value="${E21(o.title||'')}" placeholder="np. -20% na zakupy"></div><div class="field"><label>Typ</label><select id="v21Type"><option ${o.type==='Kod rabatowy'?'selected':''}>Kod rabatowy</option><option ${o.type==='Promocja'?'selected':''}>Promocja</option></select></div><div class="field"><label>Kod (opcjonalnie)</label><input id="v21Code" value="${E21(o.code||'')}" placeholder="np. UPBONUS20"></div><div class="field"><label>Ważne do</label><input id="v21Valid" type="date" value="${/^\d{4}-/.test(o.validTo||'')?E21(o.validTo):''}"></div><div class="field"><label>Grupa odbiorców</label><select id="v21Audience"><option>Wszyscy użytkownicy</option><option>Wybrana grupa</option><option>Wybrana lokalizacja</option></select></div></div><div class="field" style="margin-top:12px"><label>Krótki opis</label><textarea id="v21Desc" placeholder="Krótka korzyść widoczna na kaflu oferty">${E21(o.desc||'')}</textarea></div><div class="field" style="margin-top:12px"><label>Warunki korzystania z rabatu / promocji</label><textarea id="v22Conditions" placeholder="Np. zakres produktów, wyłączenia, możliwość łączenia z innymi promocjami...">${E21(o.conditions||'')}</textarea></div><div class="field" style="margin-top:12px"><label>Link, pod którym działa promocja</label><input id="v22Url" type="url" value="${E21(o.url||'')}" placeholder="https://partner.pl/promocja"><div class="help">Użytkownik zobaczy ten link dopiero w szczegółach oferty.</div></div><div class="field" style="margin-top:12px"><label>Status</label><select id="v21Status"><option ${o.status!=='Aktywna'?'selected':''}>Szkic</option><option ${o.status==='Aktywna'?'selected':''}>Aktywna</option></select></div></div><div class="modal-foot"><button class="secondary-btn" onclick="closeModal()">Anuluj</button><button class="primary-btn" onclick="v21SavePromo()">Zapisz ofertę</button></div></section></div>`;
   }
   return prevModal21.apply(this,arguments);
 };
 /* Employee premium: add a third tile without touching older premium logic. */
 window.ub21PremiumGo=function(kind){if(kind==='promos')return selectSection('Kody i promocje');if(typeof ub98PremiumGo==='function')return ub98PremiumGo(kind);};
 function patchEmployeePremium21(){
   if(state.role!=='employee')return;
   const list=document.querySelector('.ub98-premium-list');if(!list||list.querySelector('[data-v21-promos]'))return;
   const b=document.createElement('button');b.type='button';b.className='ub98-premium-item '+(state.section==='Kody i promocje'?'active':'');b.dataset.v21Promos='1';b.setAttribute('onclick',"ub21PremiumGo('promos')");b.innerHTML='<span class="ub98-item-icon">🏷️</span><b>Kody i promocje</b><span class="ub98-new">Bonus</span>';list.appendChild(b);
 }
 /* Client premium: final sidebar version is v101, so append route there after render. */
 function patchClientPremium21(){
   if(state.role!=='hr')return;const sec=document.querySelector('.v101-premium-simple');if(!sec||sec.querySelector('[data-v21-promos]'))return;
   const b=document.createElement('button');b.type='button';b.className='v101-nav-btn '+(state.section==='Kody i promocje'?'active':'');b.dataset.v21Promos='1';b.setAttribute('onclick',"v101Go('Kody i promocje')");b.innerHTML='<span class="v101-ico">🏷️</span><span>Kody i promocje</span>';sec.appendChild(b);
 }
 const prevRender21=window.render;
 window.render=function(){const r=prevRender21.apply(this,arguments);requestAnimationFrame(()=>{patchEmployeePremium21();patchClientPremium21();});return r;};
 const prevSection21=window.renderSection;
 window.renderSection=function(){if(state.role==='employee'&&state.section==='Kody i promocje')return employee21();if(state.role==='hr'&&state.section==='Kody i promocje')return hr21();return prevSection21.apply(this,arguments);};
 ensure21();
 requestAnimationFrame(()=>{patchEmployeePremium21();patchClientPremium21();});
})();
;

/* 101 — ub-deploy-safety-v22 */
(function(){
  'use strict';
  function showSafeError(err){
    var app=document.getElementById('app');
    if(!app)return;
    var msg=String(err&&err.message?err.message:err||'Nieznany błąd uruchomienia');
    app.innerHTML='<div style="min-height:100vh;display:grid;place-items:center;background:#f6f4f8;font-family:Arial,sans-serif;padding:24px"><div style="max-width:760px;width:100%;background:#fff;border:1px solid #e4dbe8;border-radius:18px;padding:26px;box-shadow:0 12px 34px rgba(56,26,53,.10)"><div style="font-size:22px;font-weight:800;color:#6b174e">Up Bonus — błąd uruchomienia</div><div style="margin-top:10px;color:#766b77;font-size:13px">Aplikacja została załadowana, ale nie udało się wyrenderować ekranu.</div><pre style="margin-top:16px;white-space:pre-wrap;overflow-wrap:anywhere;background:#f8f5f8;border:1px solid #e4dbe8;border-radius:12px;padding:14px;font:12px/1.45 Consolas,monospace;color:#7a1857">'+msg.replace(/[&<>]/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;'}[c]})+'</pre></div></div>';
  }
  function recover(){
    var app=document.getElementById('app');
    if(!app)return;
    try{
      var empty=!String(app.innerHTML||'').trim() || app.getBoundingClientRect().height<2;
      if(empty && typeof render==='function')render();
      if(!String(app.innerHTML||'').trim())throw new Error('Render nie utworzył zawartości aplikacji.');
    }catch(e){showSafeError(e);}
  }
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',function(){setTimeout(recover,0);});
  else setTimeout(recover,0);
  setTimeout(recover,600);
})();
;

