const prevModal111=window.modalHtml||modalHtml;
window.modalHtml=function(){
  const type=state.modal?.type,d=state.modal?.data||{};
  if(type==='v104CancelForm'){
    const o=orders111().find(x=>x.id===state.v104?.cancelDraft?.orderId);
    return `<div class="modal-backdrop"><section class="modal small"><div class="modal-head"><div><h3>Wniosek o anulowanie</h3><span>${E111(o?.id||'')}</span></div><button class="close-btn" onclick="closeModal()">×</button></div><div class="modal-body"><div class="field"><label>Powód</label><select id="v104CancelReason"><option>Zakup przez pomyłkę</option><option>Zmiana decyzji</option><option>Nie otrzymałam/em vouchera</option><option>Problem z płatnością</option><option>Inny powód</option></select></div><div class="field" style="margin-top:10px"><label>Dodatkowa informacja (opcjonalnie)</label><textarea id="v104CancelNote" rows="3"></textarea></div><div class="v104-case-info">Wysłanie wniosku nie anuluje zakupu automatycznie. BOK sprawdzi możliwość anulowania i dopiero po akceptacji unieważnią voucher oraz wykonają refund.</div></div><div class="modal-foot"><button class="secondary-btn" onclick="closeModal()">Wróć</button><button class="primary-btn" onclick="v104ConfirmCancel()">Dalej</button></div></section></div>`;
  }
  if(type==='v104CancelReview'){
    const o=orders111().find(x=>x.id===state.v104?.cancelDraft?.orderId);
    return `<div class="modal-backdrop"><section class="modal small"><div class="modal-head"><h3>Wyślij wniosek do BOK</h3><button class="close-btn" onclick="closeModal()">×</button></div><div class="modal-body"><div class="v104-summary-card"><span>Zamówienie</span><b>${E111(o?.id||'')} • ${E111(o?.name||'')}</b><div class="help">Wartość: ${M111(o?.value||0)}</div></div><div class="v104-summary-card" style="margin-top:10px"><span>Powód</span><b>${E111(state.v104?.cancelDraft?.reason||'')}</b></div><label class="v104-confirm"><input id="v104CancelConfirm" type="checkbox"><span>Potwierdzam wysłanie wniosku o anulowanie do BOK. Rozumiem, że decyzja nie jest automatyczna.</span></label><div id="v104CancelError" class="v104-error"></div></div><div class="modal-foot"><button class="secondary-btn" onclick="state.modal={type:'v104CancelForm'};renderOverlay()">Wróć</button><button class="primary-btn" onclick="v104ExecuteCancel()">Wyślij wniosek</button></div></section></div>`;
  }
  if(type==='v111CancelSuccess'){
    const r=state.v111.cancelRequests.find(x=>x.id===d.id)||state.v104?.lastCancelRequest||{};
    return `<div class="modal-backdrop"><section class="modal small"><div class="modal-head"><h3>Wniosek wysłany</h3><button class="close-btn" onclick="closeModal()">×</button></div><div class="modal-body"><div class="v104-success"><div class="v104-success-icon">✓</div><h3>Operacje otrzymały wniosek</h3><p>Zakup i voucher pozostają aktywne do czasu decyzji. Status zobaczysz w historii zakupów.</p><span class="v104-ref">${E111(r.id||'')}</span></div></div><div class="modal-foot"><button class="primary-btn" onclick="closeModal()">Gotowe</button></div></section></div>`;
  }
  if(type==='v111CancelStatus'){
    const r=state.v111.cancelRequests.find(x=>x.id===d.id)||{};
    return `<div class="modal-backdrop"><section class="modal small"><div class="modal-head"><h3>Status wniosku</h3><button class="close-btn" onclick="closeModal()">×</button></div><div class="modal-body"><div class="v104-summary-card"><span>Wniosek</span><b>${E111(r.id||'—')}</b></div><div class="v104-summary-card" style="margin-top:10px"><span>Status</span><b>${E111(r.status||'—')}</b></div><div class="v104-summary-card" style="margin-top:10px"><span>Decyzja</span><b>${E111(r.decision||'Oczekuje na decyzję')}</b></div></div><div class="modal-foot"><button class="primary-btn" onclick="closeModal()">Zamknij</button></div></section></div>`;
  }
  return prevModal111.apply(this,arguments);
};
try{modalHtml=window.modalHtml}catch(e){}

