(function(){
'use strict';
const E112=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const save112=()=>{try{if(typeof persist==='function')persist()}catch(e){}};
state.ubFinalOffers=Array.isArray(state.ubFinalOffers)?state.ubFinalOffers:[];
function syncFinalOffers112(){try{if(typeof EMP_PRODUCTS==='undefined')return;state.ubFinalOffers.filter(o=>o.status==='Aktywny').forEach(o=>{if(!EMP_PRODUCTS.some(p=>p.id===o.productId))EMP_PRODUCTS.push({id:o.productId,name:o.name,category:o.category||'Zakupy',desc:o.description||'Oferta dostępna w programie benefitowym.',price:Number(o.nominal||50),icon:'🎁',badge:'Nowość',nominals:[Number(o.nominal||50)]})})}catch(e){}}
syncFinalOffers112();
window.ubOpenNewOffer112=function(){state.modal={type:'ubFinalNewOffer'};renderOverlay()};
window.ubSaveNewOffer112=function(){
 const name=document.getElementById('ub112Name')?.value.trim();if(!name){toast('Podaj nazwę oferty','Nazwa jest wymagana.');return}
 const nominal=Math.max(0,Number(document.getElementById('ub112Nominal')?.value||50)),status=document.getElementById('ub112Status')?.value||'Roboczy';
 const item={id:'OFR-'+String(Date.now()).slice(-7),productId:'PRD-U'+String(Date.now()).slice(-6),name,partner:document.getElementById('ub112Partner')?.value.trim()||'Partner',type:document.getElementById('ub112Type')?.value||'Voucher / karta podarunkowa',category:document.getElementById('ub112Category')?.value||'Zakupy',description:document.getElementById('ub112Description')?.value.trim()||'',nominal,realization:document.getElementById('ub112Realization')?.value||'Pula kodów',link:document.getElementById('ub112Link')?.value.trim()||'',status,created:new Date().toLocaleString('pl-PL')};
 state.ubFinalOffers.unshift(item);state.v30=state.v30||{};state.v30.partnerOffers=Array.isArray(state.v30.partnerOffers)?state.v30.partnerOffers:[];
 state.v30.partnerOffers.unshift({id:item.id,productId:item.productId,name:item.name,type:item.type,variants:nominal?nominal+' PLN':'—',category:item.category,shop:status==='Aktywny',zfss:false,ewallet:true,lunch:false,privatePay:true,programs:['Katalog ogólny'],status:item.status,giftCampaign:false,segment:'Wszyscy pracownicy'});
 syncFinalOffers112();state.modal=null;save112();render();toast('Oferta zapisana',status==='Aktywny'?'Oferta jest widoczna w katalogu pracownika.':'Oferta została zapisana jako '+status+'.');
};
const prevModal112=window.modalHtml||modalHtml;
window.modalHtml=function(){if(state.modal?.type==='ubFinalNewOffer')return `<div class="modal-backdrop" onclick="if(event.target===this)closeModal()"><section class="modal"><div class="modal-head"><div><h3>Dodaj nową ofertę</h3><span>Jeden rekord produktu używany dalej przez katalog i publikację.</span></div><button class="close-btn" onclick="closeModal()">×</button></div><div class="modal-body"><div class="form-columns"><div class="field"><label>Partner</label><input id="ub112Partner"></div><div class="field"><label>Nazwa oferty *</label><input id="ub112Name"></div><div class="field"><label>Typ produktu</label><select id="ub112Type"><option>Voucher / karta podarunkowa</option><option>Kod rabatowy / Bonus</option><option>Oferta / benefit</option></select></div><div class="field"><label>Kategoria</label><select id="ub112Category">${['Zakupy','Kultura i rozrywka','Sport i aktywność','Zdrowie i profilaktyka','Wellbeing','Podróże i wypoczynek','Gastronomia i żywność','Moda','Dom','Dzieci','Edukacja'].map(x=>`<option>${E112(x)}</option>`).join('')}</select></div><div class="field"><label>Nominał / wartość</label><input id="ub112Nominal" type="number" min="0" value="50"></div><div class="field"><label>Sposób realizacji</label><select id="ub112Realization"><option>Pula kodów</option><option>Kod wspólny</option><option>Link zewnętrzny</option><option>Integracja/API</option></select></div><div class="field full"><label>Opis</label><textarea id="ub112Description" rows="4"></textarea></div><div class="field full"><label>Link / regulamin</label><input id="ub112Link"></div><div class="field"><label>Status</label><select id="ub112Status"><option>Roboczy</option><option>Aktywny</option></select></div></div></div><div class="modal-foot"><button class="secondary-btn" onclick="closeModal()">Anuluj</button><button class="primary-btn" onclick="ubSaveNewOffer112()">Zapisz ofertę</button></div></section></div>`;return prevModal112.apply(this,arguments)};
try{modalHtml=window.modalHtml}catch(e){}
const prevSection112=window.renderSection||renderSection;
window.renderSection=function(){let html=prevSection112.apply(this,arguments);if(state.role==='operations'&&state.section==='Katalog i oferty'){const rows=state.ubFinalOffers||[];html=`<div class="ub-offer-cta"><button class="primary-btn" onclick="ubOpenNewOffer112()">＋ Dodaj nową ofertę</button></div>${rows.length?`<div class="v25c-table-wrap" style="margin-bottom:14px"><table class="v25c-table"><thead><tr><th>Nowa oferta</th><th>Partner</th><th>Typ</th><th>Kategoria</th><th>Wartość</th><th>Status</th></tr></thead><tbody>${rows.map(o=>`<tr><td><b>${E112(o.name)}</b></td><td>${E112(o.partner)}</td><td>${E112(o.type)}</td><td>${E112(o.category)}</td><td>${Number(o.nominal||0).toLocaleString('pl-PL')} zł</td><td><span class="status ${o.status==='Aktywny'?'green':'gray'}">${E112(o.status)}</span></td></tr>`).join('')}</tbody></table></div>`:''}`+html}return html};
try{renderSection=window.renderSection}catch(e){}
save112();
})();
