/* 111 — ub-vercel-boot-final */
(function(){
  'use strict';
  var finished=false;
  function preboot(){return document.getElementById('ubDeployPreboot');}
  function app(){return document.getElementById('app');}
  function removePreboot(){var p=preboot();if(p)p.remove();finished=true;}
  function isFallback(){
    var a=app(); if(!a) return true;
    if(a.querySelector('.role-app,.login-page,.account-page,.employee-dashboard,.main-content')) return false;
    var t=String(a.innerText||'').replace(/\s+/g,' ').trim();
    return !t || (t.indexOf('Uruchamianie platformy')>=0 && t.length<120);
  }
  function showError(err){
    var p=preboot(); if(!p){p=document.createElement('div');p.id='ubDeployPreboot';document.body.prepend(p);}
    var msg=String((err&&(err.stack||err.message))||err||'Nie udało się uruchomić aplikacji.');
    p.style.cssText='position:fixed;inset:0;z-index:2147483647;display:grid;place-items:center;background:#f6f4f8;font-family:Arial,sans-serif;color:#211722;padding:24px';
    p.innerHTML='<div style="max-width:780px;width:100%;background:#fff;border:1px solid #e4dbe8;border-radius:18px;padding:26px;box-shadow:0 12px 34px rgba(56,26,53,.10)"><div style="font-size:22px;font-weight:800;color:#6b174e">Up Bonus — błąd uruchomienia</div><div style="margin-top:10px;font-size:13px;color:#766b77">Aplikacja została dostarczona, ale zatrzymała się podczas startu.</div><pre style="margin-top:16px;white-space:pre-wrap;overflow-wrap:anywhere;background:#f8f5f8;border:1px solid #e4dbe8;border-radius:12px;padding:14px;font:12px/1.45 Consolas,monospace;color:#7a1857">'+msg.replace(/[&<>]/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;'}[c]})+'</pre><div style="margin-top:12px;font-size:10px;color:#9b919c">FINAL BOOT FIX</div></div>';
  }
  function boot(){
    if(finished)return;
    try{
      if(typeof window.render==='function') window.render();
      else if(typeof render==='function') render();
      setTimeout(function(){
        try{
          if(!isFallback()) removePreboot();
          else if(typeof window.render==='function'){window.render();setTimeout(function(){if(!isFallback())removePreboot();else showError('render() wykonał się, ale ekran aplikacji nie zastąpił widoku startowego.');},120);}
          else showError('Funkcja render() nie jest dostępna po załadowaniu strony.');
        }catch(e){showError(e);}
      },80);
    }catch(e){showError(e);}
  }
  window.addEventListener('error',function(e){if(!finished)showError((e&&e.error)||e.message||'JavaScript error');});
  window.addEventListener('unhandledrejection',function(e){if(!finished)showError(e.reason||'Promise rejection');});
  if(document.readyState==='loading') document.addEventListener('DOMContentLoaded',boot,{once:true}); else boot();
  setTimeout(boot,400);
  setTimeout(function(){if(!finished && !isFallback())removePreboot();},1000);
})();
;


