  function safeState(){return typeof state!=='undefined'?state:null}
  function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
  function slug(v){return String(v||'').toLowerCase().replace(/[^a-z0-9ąćęłńóśźż]+/gi,'-').replace(/^-+|-+$/g,'')}
  function markText(v){const txt=String(v||'').replace(/[^A-Za-z0-9]/g,'');return (txt.slice(0,2)||'UB').toUpperCase()}
  function doRender(){try{if(typeof persist==='function')persist()}catch(e){}; try{if(typeof render==='function')render()}catch(e){console.warn('v13 render',e)}}
  function toast13(title,msg){if(typeof toast==='function')toast(title,msg)}
  function loadAll(){try{return JSON.parse(localStorage.getItem(STORAGE)||'{}')||{}}catch(e){return {}}}
  function saveAll(data){try{localStorage.setItem(STORAGE,JSON.stringify(data))}catch(e){}}

  function clientList(){
    const out=[]; const seen=new Set();
    const add=c=>{if(!c)return;const id=String(c.id||c.tenantId||c.key||'').trim();if(!id||seen.has(id))return;seen.add(id);out.push({id,name:String(c.name||c.company||c.client||id),nip:String(c.nip||'')})};
    try{(safeState()?.v47?.clients||[]).forEach(add)}catch(e){}
    try{if(typeof SAMPLE_CLIENTS!=='undefined'&&Array.isArray(SAMPLE_CLIENTS))SAMPLE_CLIENTS.forEach(add)}catch(e){}
    if(!out.length){add({id:'TEN-001',name:'Erste Bank'});add({id:'TEN-002',name:'Demo Up Base'});add({id:'TEN-003',name:'Demo Up Plus'})}
    return out;
  }
  function activeClientId(){
    const s=safeState();
    return String(s?.v47?.currentClientId||s?.v62ProgramClient||sessionStorage.getItem('ub13.previewClient')||clientList()[0]?.id||'TEN-001');
  }
  function inferPackage(features){
    const ids=featureDefs.map(x=>x.id);
    const same=p=>ids.every(id=>!!features[id]===!!presets[p][id]);
    if(same('essential'))return 'essential'; if(same('flex'))return 'flex'; if(same('one'))return 'one'; return 'custom';
  }
  function packageLabel(pkg){return pkg==='essential'?'Up Base':pkg==='flex'?'Up Plus':pkg==='one'?'Up Experience':'Własny zakres'}
  function configFor(id){
    const all=loadAll();
    if(!all[id]){
      const idx=clientList().findIndex(c=>c.id===id);
      const packageName=idx===1?'essential':idx===2?'flex':'one';
      all[id]={package:packageName,features:{...presets[packageName]},blocks:{...defaultBlocks},updatedAt:new Date().toISOString()};
      saveAll(all);
    }
    const cfg=all[id];
    const migrationPreset=presets[cfg.package]||presets.essential;
    cfg.features={...migrationPreset,...(cfg.features||{})};
    cfg.blocks={...defaultBlocks,...(cfg.blocks||{})};

    /* v54: one-time migration for the new engagement ecosystem.
       Older saved configs did not know these modules and could silently keep them hidden. */
    if(Number(cfg.engagementSchema||0)<55){
      cfg.features.employerPerks=true;
      cfg.features.community=true;
      cfg.features.recognition=true;
      cfg.blocks.employerPerks=true;
      cfg.blocks.community=true;
      cfg.blocks.kudosProgress=true;
      cfg.engagementSchema=55;
      all[id]=cfg;
      saveAll(all);
    }

    CORE_PREMIUM_IDS.forEach(fid=>{cfg.features[fid]=true});
    cfg.package=cfg.package||inferPackage(cfg.features);
    return cfg;
  }
  function setConfig(id,cfg){const all=loadAll();all[id]={...cfg,updatedAt:new Date().toISOString()};saveAll(all)}
  function featureOn(id,clientId){return ub73SystemFeatureAvailable(id)&&!!configFor(clientId||activeClientId()).features[id]}
  function blockOn(id,clientId){return !!configFor(clientId||activeClientId()).blocks[id]}
  function activeFeatures(clientId){return featureDefs.filter(f=>featureOn(f.id,clientId))}
  function clientName(id){return clientList().find(c=>c.id===id)?.name||id}
  function route(route){if(typeof window.selectSection==='function')window.selectSection(route)}
  window.ub13Route=route;

  function setActiveClient(id){
    const s=safeState();
    if(s){s.v47=s.v47||{};s.v47.currentClientId=id;s.v62ProgramClient=id}
    try{sessionStorage.setItem('ub13.previewClient',id)}catch(e){}
  }


  function tile(f){return `<article class="ub13-tile" onclick="ub13Route('${esc(f.route)}')"><div class="ub13-tile-icon">${f.icon}</div><h3>${esc(f.name)}</h3><p>${esc(f.desc)}</p><small>Otwórz →</small></article>`}
  function featureGrid(list){const n=list.length;return n?`<div class="ub13-grid" data-count="${n}">${list.map(tile).join('')}</div>`:`<div class="ub13-empty-smart"><b>Twoje benefity są właśnie przygotowywane</b><p>Gdy program zostanie uruchomiony, dostępne opcje pojawią się tutaj automatycznie.</p></div>`}

  function purchaseAction(p){
    if(p.productId)return `ub42OpenProduct('${esc(p.productId)}')`;
    return `ub13Route('${esc(p.route||'Katalog benefitów')}')`;
  }
  window.ub42OpenProduct=function(productId){
    if(typeof window.openEmployeeProduct==='function'){
      window.openEmployeeProduct(productId);
      return;
    }
    if(typeof openEmployeeProduct==='function'){
      openEmployeeProduct(productId);
      return;
    }
    if(typeof toast==='function')toast('Oferta','Nie udało się otworzyć szczegółów produktu.');
  };

  function productCard(p){
    const existingBadge=p.badge?String(p.badge):'';
    const derivedBadge=benefitIsNewest(p)?'Nowość':benefitIsRecommended(p)?'Polecane':benefitPopularity(p)<=3?'Popularne':'';
    const badge=(existingBadge||derivedBadge)?`<span class="ub15-product-badge">${esc(existingBadge||derivedBadge)}</span>`:'';
    const old=p.old?`<del>${esc(p.old)}</del>`:'';
    const slug=String(p.brand||'benefit').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-+|-+$/g,'');
    const action=purchaseAction(p);
    const favId=p.productId||'';
    const favOn=favId&&typeof isFavorite==='function'&&isFavorite(favId);
    const favorite=favId?`<button type="button" class="ub48-favorite-heart ${favOn?'active':''}" aria-label="${favOn?'Usuń z ulubionych':'Dodaj do ulubionych'}" title="${favOn?'Usuń z ulubionych':'Dodaj do ulubionych'}" onclick="event.stopPropagation();if(typeof toggleFavorite==='function')toggleFavorite('${favId}',event)">${favOn?'♥':'♡'}</button>`:'';
    const visual=p.image
      ? `<div class="ub43-product-image-wrap">${badge}${favorite}<img class="ub43-product-image" src="${esc(p.image)}" alt="${esc(p.brand||p.title||'Produkt')}" loading="lazy"></div>`
      : `<div class="ub43-product-image-wrap ub43-product-fallback">${badge}${favorite}<span>${esc(markText(p.visualText||p.brand))}</span></div>`;
    const brand=String(p.brand||'Benefit').trim();
    const title=String(p.title||'').trim();
    const norm=v=>v.toLowerCase().replace(/[^a-z0-9ąćęłńóśźż]+/g,' ').trim();
    const showTitle=title&&norm(title)!==norm(brand)&&!norm(title).startsWith(norm(brand)+' ');
    const type=String(p.visualSub||p.displayCategory||p.category||'Benefit');
    const finance=p.isFree?'Finansowane przez firmę':p.productId?'Dostępne z Twoich środków':'Sprawdź warunki finansowania';
    return `<article class="ub15-product-card ub17-brand-card ub43-product-card ub302-product-card" data-brand="${slug}" onclick="${action}">
      ${visual}
      <div class="ub15-product-body ub43-product-body ub302-product-body"><b class="ub15-brand">${esc(brand)}</b>${showTitle?`<h3>${esc(title)}</h3>`:''}<div class="ub43-product-sub">${esc(type)}</div><div class="ub302-finance">${esc(finance)}</div><div class="ub15-price">${old}<strong>${esc(p.price||'Sprawdź')}</strong></div><button type="button" onclick="event.stopPropagation();${action}">Zobacz ofertę →</button></div>
    </article>`;
  }

