  function catalogProducts(clientId){
    const cfg=configFor(clientId),buyCta=cfg.features.marketplace?'Kup':'Sprawdź';
    const base=[
      {productId:'PRD-ALG',brand:'Allegro',visualText:'allegro',visualSub:'Karta podarunkowa',title:'Karta podarunkowa',price:'od 50 zł',cta:buyCta,category:'Karty podarunkowe',feature:'codes',image:'/assets/products/allegro-demo.webp'},
      {productId:'PRD-EMP',brand:'Empik',visualText:'empik',visualSub:'Karta podarunkowa',title:'Karta podarunkowa',price:'od 50 zł',cta:buyCta,category:'Karty podarunkowe',feature:'codes',image:'/assets/products/empik-demo.webp'},
      {productId:'PRD-DEC',brand:'Decathlon',visualText:'DECATHLON',visualSub:'Voucher',title:'Voucher sportowy',price:'od 50 zł',cta:buyCta,category:'Karty podarunkowe',feature:'codes',image:'/assets/products/decathlon-demo.webp'},
      {productId:'PRD-ROS',brand:'Rossmann',visualText:'Rossmann',visualSub:'Karta podarunkowa',title:'Karta podarunkowa',price:'od 50 zł',cta:buyCta,category:'Karty podarunkowe',feature:'codes',image:'/assets/products/rossmann-demo.webp'},
      {productId:'PRD-MUL',brand:'Multikino',visualText:'Multikino',visualSub:'Bilety i vouchery',title:'Voucher do kina',price:'od 35 zł',cta:buyCta,category:'Bilety',feature:'codes',image:'/assets/products/multikino-demo.png'},
      {productId:'PRD-SUP',brand:'Super Prezenty',visualText:'Super Prezenty',visualSub:'Voucher',title:'Voucher prezentowy',price:'od 100 zł',cta:buyCta,category:'Vouchery',feature:'codes',image:'/assets/products/superprezenty-demo.webp'},
      {productId:'PRD-WAK',brand:'Wakacje.pl',visualText:'Wakacje.pl',visualSub:'Voucher podróżniczy',title:'Karta na podróże',price:'od 100 zł',cta:buyCta,category:'Podróże',feature:'codes'},
      {productId:'PRD-ZAL',brand:'Zalando',visualText:'Zalando',visualSub:'Karta podarunkowa',title:'Karta podarunkowa',price:'od 50 zł',cta:buyCta,category:'Moda',feature:'codes'},
      {productId:'PRD-IKE',brand:'IKEA',visualText:'IKEA',visualSub:'Karta podarunkowa',title:'Karta podarunkowa',price:'od 50 zł',cta:buyCta,category:'Dom',feature:'codes'},
      {productId:'PRD-SMY',brand:'Smyk',visualText:'Smyk',visualSub:'Karta podarunkowa',title:'Karta podarunkowa',price:'od 50 zł',cta:buyCta,category:'Dzieci',feature:'codes'},
      {productId:'PRD-PRO',brand:'ProfiLingua',visualText:'ProfiLingua',visualSub:'Edukacja',title:'Kurs językowy',price:'od 100 zł',cta:buyCta,category:'Edukacja',feature:'codes'},
      {brand:'Twoja firma',visualText:'Od firmy',visualSub:'Bezpłatnie',title:'Masaż w biurze · 15 min',price:'0 zł',cta:'Rezerwuję',route:'Od firmy',category:'Od firmy',feature:'employerPerks'},
      {brand:'Twoja firma',visualText:'Od firmy',visualSub:'Bezpłatnie',title:'Serwis rowerowy',price:'0 zł',cta:'Zapisz się',route:'Od firmy',category:'Od firmy',feature:'employerPerks'},
      {brand:'Up Bonus',visualText:'Up Bonus',visualSub:'Personalizacja',title:'Karta z personalizacją',price:'od 50 zł',cta:'Stwórz',route:'Personalizowane karty',category:'Personalizacja',feature:'personalization'},
      {brand:'Up Bonus',visualText:'Up Bonus',visualSub:'Prezent od HR',title:'Wybierz swój upominek',price:'0 zł',cta:'Odbierz',badge:'Dla Ciebie',route:'Upominki',category:'Prezenty',feature:'gifts'}
    ].filter(p=>!p.feature||featureOn(p.feature,clientId));

    const activeOffers=Array.isArray(safeState()?.v21Offers)?safeState().v21Offers.filter(o=>o.status==='Aktywny'&&o.shop!==false):[];
    const linked=new Map(activeOffers.filter(o=>o.sourceProductId).map(o=>[o.sourceProductId,o]));
    const merged=base.map(p=>{
      const o=p.productId?linked.get(p.productId):null;
      if(!o)return p;
      const values=(o.variants||[]).filter(v=>v.active!==false).map(v=>Number(v.value)).filter(Number.isFinite);
      return {...p,brand:o.brand||p.brand,title:o.name||p.title,visualSub:o.type||p.visualSub,category:o.category||p.category,image:o.image||p.image,price:values.length?`od ${Math.min(...values)} zł`:p.price};
    });
    const extras=activeOffers.filter(o=>!o.sourceProductId||!base.some(p=>p.productId===o.sourceProductId)).map(o=>{
      const values=(o.variants||[]).filter(v=>v.active!==false).map(v=>Number(v.value)).filter(Number.isFinite);
      return {productId:o.sourceProductId||'',brand:o.brand||'Up Bonus',visualText:o.brand||'Up Bonus',visualSub:o.type||o.category,title:o.name||'Produkt',price:values.length?`od ${Math.min(...values)} zł`:'Sprawdź',cta:o.sourceProductId?buyCta:'Sprawdź',route:o.sourceProductId?'':'Katalog benefitów',category:o.category||'Inne',image:o.image||''};
    });
    const master=ub76CatalogOffersForClient(clientId);
    const effectiveBase=[...merged,...extras].filter(p=>ub74CategoryEnabled(p.category));
    const seen=new Set(effectiveBase.map(p=>p.productId));
    return [...effectiveBase,...master.filter(p=>!seen.has(p.productId)&&ub74CategoryEnabled(p.category))];
  }

