    d.surveys.unshift({id,type:'survey',icon:'💬',title:'Nowa ankieta',desc:'Uzupełnij opis ankiety.',status:'active',anonymous:true,ends:new Date(Date.now()+7*86400000).toISOString().slice(0,10),responses:0,estimated:'1 min',questions:[]});
