    const end=prompt('Data zakończenia (RRRR-MM-DD)',x.ends);if(end===null)return;
    x.title=title.trim()||x.title;x.ends=end.trim()||x.ends;
    engagementSave(d);eToast('Zapisano','Ankieta została zaktualizowana.');eRender();
