  const UB77_BLOCK_KEY='upbonus.directory.blocked.v77';
  function ub77Blocked(){
    let x={users:{},partners:{}};try{x={...x,...JSON.parse(localStorage.getItem(UB77_BLOCK_KEY)||'{}')}}catch(e){};x.users=x.users||{};x.partners=x.partners||{};return x;
  }
  function ub77SaveBlocked(x){try{localStorage.setItem(UB77_BLOCK_KEY,JSON.stringify(x))}catch(e){}}
  function ub77DirectoryUsers(){
    const base=ub69Users(),clients=ub69Clients();
    const roles=['Pracownik','HR','Manager','Admin klienta','Pracownik','Pracownik'];
    const more=[];
    clients.forEach((c,ci)=>{for(let i=0;i<5;i++)more.push({name:`Użytkownik ${ci+1}-${i+1}`,email:`user${ci+1}${i+1}@${String(c.name).toLowerCase().replace(/[^a-z0-9]/g,'')||'firma'}.pl`,client:c.name,role:roles[(ci+i)%roles.length],status:'Aktywny',last:`${23-(i%4)}.08.2026 ${8+i}:1${i}`,auth:i%2?'SSO':'MFA'})});
    const seen=new Set(),all=[...base,...more].filter(u=>{const k=u.email||u.name;if(seen.has(k))return false;seen.add(k);return true});
    const blocked=ub77Blocked().users;return all.map(u=>({...u,status:blocked[u.email]?'Zablokowany':u.status}));
  }
