    b.primary=document.getElementById('ub77Primary')?.value||b.primary;
    b.accent=document.getElementById('ub77Accent')?.value||b.accent;
    b.page=document.getElementById('ub77Page')?.value||b.page;
    b.fontName=String(document.getElementById('ub77FontName')?.value||b.fontName).trim();
