  window.ub77BrandAsset=function(input,type){
    const files=[...(input.files||[])];if(!files.length)return;
    const s=ub69SuperState(),id=s.brandingClient||activeClientId(),b=ub77Branding(id);
    const read=f=>new Promise(resolve=>{const r=new FileReader();r.onload=()=>resolve(String(r.result||''));r.readAsDataURL(f)});
    Promise.all(files.map(read)).then(data=>{
      if(type==='font')b.fontData=data[0]||'';
      if(type==='logo')b.logo=data[0]||'';
      if(type==='slides')b.slides=[...(b.slides||[]),...data].slice(0,12);
      ub77SaveBranding(id,b);doRender();
    });
  };
  window.ub77RemoveSlide=function(i){const s=ub69SuperState(),id=s.brandingClient||activeClientId(),b=ub77Branding(id);b.slides=(b.slides||[]).filter((_,n)=>n!==i);ub77SaveBranding(id,b);doRender()};

