  // ---- Platform foundation 64: CMS / Voucher Gateway / Inventory / Provider / RBAC ----
  const ub64State=()=>{const root=ub69SuperState();return root.foundation64||(root.foundation64={cms:[],inventory:[],providers:[],roles:[],loading:{},errors:{}})};
  async function ub64Token(){try{const r=await window.sb?.auth?.getSession?.();return r?.data?.session?.access_token||''}catch(_){return ''}}
  async function ub64Api(path,options={}){
    const token=await ub64Token(); if(!token)throw new Error('Brak aktywnej sesji Supabase');
    const h={'Content-Type':'application/json',Authorization:`Bearer ${token}`,...(options.headers||{})};
    let endpoint='/api/v1/'+path;
    const rawPath=String(path);
    const inventoryActions=new Set(['inventory','stock','providers','provider-products','parse-file','batches','validate-import','import','delete-batch','edit-stock-group','withdraw-stock-group','test-purchase']);
    const cleanPath=rawPath.split('?')[0];
    const parts=cleanPath.split('/').filter(Boolean);
    const inventoryAction=parts[0]==='inventory'?(parts.slice(1).join('/')||'stock'):(inventoryActions.has(parts[0])?(parts[0]==='inventory'?'stock':parts[0]):null);
    if(inventoryAction){
      const query=rawPath.includes('?')?rawPath.slice(rawPath.indexOf('?')+1):'';
      endpoint='/api/inventory?action='+encodeURIComponent(inventoryAction)+(query?'&'+query:'');
    }
    const r=await fetch(endpoint,{...options,headers:h,body:options.body&&typeof options.body!=='string'?JSON.stringify(options.body):options.body});
    const data=await r.json().catch(()=>({})); if(!r.ok){const e=new Error(data.message||data.error||`HTTP ${r.status}`);e.code=data.error;throw e}return data;
  }
  function ub64Tenant(){return String(safeState()?.tenant||'upbonus')}
  function ub64BackendNote(err){const msg=String(err?.message||err||'');return `<div class="ub64-state warn"><b>Backend wymaga konfiguracji</b><span>${esc(msg)}</span></div>`}
  async function ub64Load(kind){const st=ub64State();if(st.loading[kind])return;st.loading[kind]=true;st.errors[kind]='';try{
    if(kind==='cms'){const d=await ub64Api(`content?tenant_id=${encodeURIComponent(ub64Tenant())}`);st.cms=d.items||[]}
    if(kind==='inventory'){const d=await ub64Api(`inventory?tenant_id=${encodeURIComponent(ub64Tenant())}`);st.inventory=d.items||[]}
    if(kind==='providers'){const d=await ub64Api(`providers?tenant_id=${encodeURIComponent(ub64Tenant())}`);st.providers=d.items||[]}
    if(kind==='rbac'){const d=await ub64Api(`rbac?tenant_id=${encodeURIComponent(ub64Tenant())}`);st.roles=d.roles||[]}
  }catch(e){st.errors[kind]=e.message||String(e)}finally{st.loading[kind]=false;doRender()}}
  function ub64Ensure(kind){const st=ub64State();if(!st.loading[kind]&&!st.errors[kind]&&!st[kind]?.length)setTimeout(()=>ub64Load(kind),0)}
  function ub64Pill(v){const t=String(v||'');const cls=/PUBLISHED|AVAILABLE|ACTIVE|COMPLETED/i.test(t)?'green':/BLOCK|ERROR|EXPIRED/i.test(t)?'red':/DRAFT|NOT_CONFIGURED|RESERVED/i.test(t)?'amber':'gray';return `<span class="status ${cls}">${esc(t||'—')}</span>`}
  function ub102WorkspaceState(){
    const s=ub64State();
    s.tabs=s.tabs||{cms:'Treści',inventory:'Stock',providers:'Dostawcy',security:'Role i uprawnienia'};
    s.filters=s.filters||{};
    return s;
  }
