  function ub74ConfigModal(title,subtitle,body,onSubmit){
    const modal=document.createElement('div');
    modal.className='ub57-modal-backdrop';
    modal.innerHTML=`<div class="ub57-modal ub74-config-modal"><div class="ub57-modal-head"><div><span>KONFIGURACJA SYSTEMU</span><h2>${esc(title)}</h2><p>${esc(subtitle||'')}</p></div><button class="ub57-close" type="button">×</button></div><form class="ub74-config-form">${body}<div class="ub57-actions"><button type="button" class="secondary-btn" data-cancel>Anuluj</button><button type="submit" class="primary-btn">Zapisz zmiany</button></div></form></div>`;
    modal.querySelector('.ub57-close').onclick=()=>modal.remove();
    modal.querySelector('[data-cancel]').onclick=()=>modal.remove();
    modal.querySelector('form').onsubmit=e=>{e.preventDefault();onSubmit(new FormData(e.currentTarget));modal.remove()};
    document.body.appendChild(modal);
  }

  window.ub74OpenConfigEditor=function(type,id){
    const cfg=ub74SystemConfig();

    if(type==='package'){
      const p=cfg.packages[id];
      const modules=featureDefs.map(f=>`<label class="ub74-check"><input type="checkbox" name="module" value="${f.id}" ${(p.modules||[]).includes(f.id)?'checked':''} ${isCorePremium(f.id)?'disabled':''}><span>${f.icon} ${esc(f.name)}</span></label>`).join('');
      ub74ConfigModal('Pakiet '+p.name,'Definicja globalna pakietu. Zmiana nie modyfikuje automatycznie istniejących klientów.',`
        <div class="ub74-grid2"><label>Nazwa<input name="name" value="${esc(p.name)}" required></label><label>Cena / użytk. / mies.<input name="price" type="number" min="0" step="0.01" value="${Number(p.price)}" required></label></div>
        <div class="ub74-field"><b>Moduły domyślne</b><div class="ub74-check-grid">${modules}</div></div>`,fd=>{
          const modules=fd.getAll('module');CORE_PREMIUM_IDS.forEach(x=>{if(!modules.includes(x))modules.push(x)});
          cfg.packages[id]={...p,name:String(fd.get('name')||p.name).trim(),price:Number(fd.get('price')||0),modules};
          ub74SaveSystemConfig(cfg);ub69Audit('Edycja pakietu',cfg.packages[id].name,'SYSTEM','Konfiguracja');doRender();
        });
      return;
    }

    if(type==='flag'){
      const x=cfg.featureFlags.find(v=>v.id===id);if(!x)return;
      ub74ConfigModal(x.name,'Feature flag działa w wybranym zakresie.',`
        <label>Nazwa<input name="name" value="${esc(x.name)}" required></label>
        <label>Zakres<select name="scope"><option value="global" ${x.scope==='global'?'selected':''}>Globalny</option><option value="client" ${x.scope==='client'?'selected':''}>Klient</option><option value="group" ${x.scope==='group'?'selected':''}>Grupa</option><option value="user" ${x.scope==='user'?'selected':''}>Użytkownik testowy</option></select></label>
        <label class="ub74-check"><input type="checkbox" name="enabled" ${x.enabled?'checked':''}><span>Aktywna</span></label>`,fd=>{
          x.name=String(fd.get('name')||x.name);x.scope=String(fd.get('scope')||'global');x.enabled=fd.has('enabled');
          ub74SaveSystemConfig(cfg);ub69Audit('Edycja feature flag',`${x.id}: ${x.enabled?'ON':'OFF'} / ${x.scope}`,'SYSTEM','Konfiguracja');doRender();
        });
      return;
    }

    if(type==='category'){
      const x=cfg.categories.find(v=>v.id===id);if(!x)return;
      ub74ConfigModal('Kategoria '+x.name,'Zmiana widoczności wpływa na katalog benefitów.',`
        <div class="ub74-grid2"><label>Nazwa<input name="name" value="${esc(x.name)}" required></label><label>Kolejność<input name="order" type="number" value="${x.order}" required></label></div>
        <label class="ub74-check"><input type="checkbox" name="active" ${x.active?'checked':''}><span>Widoczna w systemie</span></label>`,fd=>{
          x.name=String(fd.get('name')||x.name);x.order=Number(fd.get('order')||0);x.active=fd.has('active');
          ub74SaveSystemConfig(cfg);ub69Audit('Edycja kategorii',`${x.name}: ${x.active?'ON':'OFF'}`,'SYSTEM','Oferta');doRender();
        });
      return;
    }

    if(type==='dictionary'){
      const x=cfg.dictionaries.find(v=>v.id===id);if(!x)return;
      ub74ConfigModal(x.name,'Wartości słownika są wykorzystywane przez formularze operacyjne.',`
        <label>Nazwa<input name="name" value="${esc(x.name)}" required></label>
        <label>Wartości — jedna w linii<textarea name="values" rows="8" required>${esc(x.values.join('\n'))}</textarea></label>`,fd=>{
          x.name=String(fd.get('name')||x.name);x.values=String(fd.get('values')||'').split(/\n+/).map(v=>v.trim()).filter(Boolean);
          ub74SaveSystemConfig(cfg);ub69Audit('Edycja słownika',`${x.name}: ${x.values.length} wartości`,'SYSTEM','Konfiguracja');doRender();
        });
      return;
    }

    if(type==='template'){
      const x=cfg.templates.find(v=>v.id===id);if(!x)return;
      ub74ConfigModal(x.name,'Szablon będzie dostępny w BOK po zapisaniu.',`
        <label>Nazwa<input name="name" value="${esc(x.name)}" required></label>
        <label>Treść<textarea name="text" rows="7" required>${esc(x.text)}</textarea></label>
        <label class="ub74-check"><input type="checkbox" name="active" ${x.active?'checked':''}><span>Aktywny</span></label>`,fd=>{
          x.name=String(fd.get('name')||x.name);x.text=String(fd.get('text')||'');x.active=fd.has('active');
          ub74SaveSystemConfig(cfg);try{safeState().ub66=null}catch(e){};ub69Audit('Edycja szablonu BOK',x.name,'SYSTEM','BOK');doRender();
        });
      return;
    }

    if(type==='status'){
      const x=cfg.statuses.find(v=>v.id===id);if(!x)return;
      ub74ConfigModal('Status '+x.name,'Centralny słownik statusów procesu.',`
        <div class="ub74-grid2"><label>Nazwa<input name="name" value="${esc(x.name)}" required></label><label>Obszar<input name="area" value="${esc(x.area)}" required></label></div>
        <label class="ub74-check"><input type="checkbox" name="active" ${x.active?'checked':''}><span>Aktywny</span></label>`,fd=>{
          x.name=String(fd.get('name')||x.name);x.area=String(fd.get('area')||x.area);x.active=fd.has('active');
          ub74SaveSystemConfig(cfg);ub69Audit('Edycja statusu',`${x.name}: ${x.active?'ON':'OFF'}`,'SYSTEM','Konfiguracja');doRender();
        });
      return;
    }

    if(type==='limit'){
      const labels={seniorRefund:'Senior BOK — maks. zwrot',managerRefund:'Manager — maks. zwrot',maxImportRows:'Maks. wierszy importu',maxGiftOrder:'Maks. wartość zamówienia Gifts'};
      ub74ConfigModal(labels[id]||id,'Limit systemowy używany przez powiązany proces.',`
        <label>Wartość<input name="value" type="number" min="0" step="1" value="${Number(cfg.limits[id]||0)}" required></label>`,fd=>{
          cfg.limits[id]=Number(fd.get('value')||0);ub74SaveSystemConfig(cfg);ub69Audit('Zmiana limitu',`${id}: ${cfg.limits[id]}`,'SYSTEM','Konfiguracja');doRender();
        });
      return;
    }

    if(type==='rule'){
      const value=cfg.rules[id];
      const labels={defaultSlaHours:'Domyślne SLA reklamacji',autoAssignSla:'Automatyczne nadanie SLA',autoEscalateAfterSla:'Automatyczna eskalacja po SLA',requireClientReasonOnReject:'Wymagane uzasadnienie odrzucenia',communityModeration:'Moderacja Społeczności'};
      const input=typeof value==='boolean'?`<label class="ub74-check"><input type="checkbox" name="value" ${value?'checked':''}><span>Reguła aktywna</span></label>`:`<label>Wartość (godziny)<input name="value" type="number" min="1" value="${Number(value)}" required></label>`;
      ub74ConfigModal(labels[id]||id,'Zmiana działa globalnie dla nowych operacji.',input,fd=>{
        cfg.rules[id]=typeof value==='boolean'?fd.has('value'):Number(fd.get('value')||value);
        ub74SaveSystemConfig(cfg);ub69Audit('Zmiana reguły',`${id}: ${cfg.rules[id]}`,'SYSTEM','Konfiguracja');doRender();
      });
    }
  };

