    let items=d.wellbeingServices.filter(x=>x.active!==false);
    if(cat!=='Wszystkie')items=items.filter(x=>x.category===cat);
    items.sort((a,b)=>(a.order||99)-(b.order||99));

    return `<div class="page-content ub60-wellbeing-page">
      <div class="page-head">
        <div><span class="eyebrow">ZDROWIE I DOBROSTAN</span><h1>🌿 Wellbeing</h1><p>Praktyczne usługi zdrowotne, psychologiczne i sportowe dostępne w Twoim programie.</p></div>
      </div>

      <section class="ub60-wellbeing-hero">
        <div><span>Twoje wsparcie</span><h2>Nie tylko „wellness”. Realna pomoc, kiedy jej potrzebujesz.</h2><p>Lekarz, psycholog, psychiatra, dentysta, fizjoterapeuta, sport i profilaktyka — w jednym miejscu.</p></div>
        <div class="ub60-wb-quick">
          <button onclick="ub60SetWellbeingCat('Medycyna')"><i>🩺</i><b>Zdrowie</b><span>lekarz i specjaliści</span></button>
          <button onclick="ub60SetWellbeingCat('Psychika')"><i>🧠</i><b>Psychika</b><span>psycholog i psychiatra</span></button>
          <button onclick="ub60SetWellbeingCat('Ruch i regeneracja')"><i>🏋️</i><b>Ruch</b><span>sport i fizjoterapia</span></button>
        </div>
      </section>

      <div class="ub60-wb-toolbar">
        <div class="ub60-wb-filters">${categories.map(c=>`<button class="${cat===c?'active':''}" onclick="ub60SetWellbeingCat('${c}')">${c}</button>`).join('')}</div>
        <span>${items.length} usług</span>
      </div>

      <section class="ub60-wb-grid">
        ${items.map(x=>`<article class="ub60-wb-card">
          <div class="ub60-wb-icon">${x.icon}</div>
          <div class="ub60-wb-copy">
            <span>${esc(x.category)}</span>
            <h3>${esc(x.title)}</h3>
            <p>${esc(x.desc)}</p>
            <div class="ub60-wb-bottom"><em>${esc(x.access)}</em><button onclick="ub60WellbeingAction('${x.id}')">${esc(x.cta)} →</button></div>
          </div>
        </article>`).join('')}
      </section>
    </div>`;
