  window.employeeTopbar=function(){
    const base=typeof ub85PreviousEmployeeTopbar==='function'
      ?ub85PreviousEmployeeTopbar.apply(this,arguments)
      :'';
    if(!base)return base;
    const holder=document.createElement('div');
    holder.innerHTML=base;
    const root=holder.firstElementChild;
    if(!root)return base;
    const oldSearch=root.querySelector('.top-search');
    if(oldSearch){
      const shell=document.createElement('div');
      shell.innerHTML=ub85EmployeeSearchHtml();
      oldSearch.replaceWith(shell.firstElementChild);
    }else{
      const actions=root.querySelector('.top-actions');
      if(actions){
        const shell=document.createElement('div');
        shell.innerHTML=ub85EmployeeSearchHtml();
        actions.before(shell.firstElementChild);
      }
    }
    return root.outerHTML;
  };

  function ub85EnsureEmployeeSearch(){
    const s=safeState();
    if(s?.role!=='employee')return;
    const topbar=document.querySelector('.employee-topbar,.topbar');
    if(!topbar||topbar.querySelector('.top-search'))return;
    const actions=topbar.querySelector('.top-actions');
    if(!actions)return;
    const shell=document.createElement('div');
    shell.innerHTML=ub85EmployeeSearchHtml();
    actions.before(shell.firstElementChild);
  }

