  function bok66Load(){
    const s=safeState();
    s.ub66=s.ub66||{};
    try{
      const saved=JSON.parse(localStorage.getItem(BOK66_STORAGE)||'{}')||{};
      s.ub66={...saved,...s.ub66};
    }catch(e){}
    s.ub66.query=String(s.ub66.query||'');
    s.ub66.savedView=String(s.ub66.savedView||'');
    s.ub66.caseId=s.ub66.caseId||null;
    s.ub66.role=s.ub66.role||'Senior BOK';
    s.ub66.localCases=Array.isArray(s.ub66.localCases)?s.ub66.localCases:[];
    s.ub66.templates=ub74SystemConfig().templates.filter(x=>x.active!==false).map(x=>({id:x.id,name:x.name,text:x.text}));
    bok66Save();
    return s.ub66;
  }
  function bok66Save(){
    try{localStorage.setItem(BOK66_STORAGE,JSON.stringify(safeState()?.ub66||{}))}catch(e){}
    try{if(typeof persist==='function')persist()}catch(e){}
  }
  function bok66Esc(v){return esc(v)}
  function bok66Money(v){return Number(v||0).toLocaleString('pl-PL',{minimumFractionDigits:2,maximumFractionDigits:2})+' zł'}
  function bok66Date(v){
    if(!v)return '—';
    try{return new Date(v).toLocaleString('pl-PL',{day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit'})}catch(e){return String(v)}
  }
  function bok66Sla(c){
    const m=Number(c.slaMinutes||0);
    if(m<0)return {label:`po SLA ${Math.abs(m)} min`,cls:'late'};
    if(m<=240)return {label:`${Math.floor(m/60)}h ${m%60}m`,cls:'urgent'};
    if(m<1440)return {label:`${Math.floor(m/60)}h ${m%60}m`,cls:'ok'};
    return {label:`${Math.floor(m/1440)}d ${Math.floor((m%1440)/60)}h`,cls:'ok'};
  }
  function bok66StatusClass(status){
    const x=String(status||'').toLowerCase();
    if(x.includes('po sla'))return 'late';
    if(x.includes('pil'))return 'urgent';
    if(x.includes('w toku'))return 'progress';
    if(x.includes('oczek'))return 'waiting';
    if(x.includes('rozwiąz')||x.includes('uznan'))return 'resolved';
    if(x.includes('zamk')||x.includes('odrzu'))return 'closed';
    if(x.includes('now'))return 'new';
    if(x.includes('decyz'))return 'decision';
    return 'neutral';
  }
  function bok66StatusLabel(c){
    const sla=bok66Sla(c);
    if(sla.cls==='late'&&!String(c.status).toLowerCase().includes('zamk'))return 'Po SLA';
    return c.status||'Nowa';
  }
  function bok66Timeline(c){
    if(Array.isArray(c.timeline)&&c.timeline.length)return c.timeline;
    const start=c.createdAt||new Date().toISOString();
    const arr=[
      {time:start,label:'Klient zgłosił sprawę',detail:c.description||c.reason||''},
      {time:new Date(new Date(start).getTime()+2*60000).toISOString(),label:'System przypisał SLA',detail:'SLA: 24h'},
      {time:new Date(new Date(start).getTime()+7*60000).toISOString(),label:'Sprawa trafiła do BOK',detail:c.owner&&c.owner!=='—'?`Opiekun: ${c.owner}`:'Oczekuje na przypisanie'}
    ];
    if(c.status==='Oczekuje na partnera')arr.push({time:new Date(new Date(start).getTime()+11*60000).toISOString(),label:'Wysłano wiadomość do partnera',detail:c.partner||'Partner'});
    if(c.decision&&c.decision!=='—')arr.push({time:c.closedAt||new Date().toISOString(),label:'Decyzja',detail:c.decision});
    return arr;
  }
  function bok66Messages(c){
    return Array.isArray(c.messages)&&c.messages.length?c.messages:[
      {from:'Klient',kind:'client',time:c.createdAt,text:c.description||c.reason||'Zgłoszenie przekazane do BOK.'},
      ...(c.status==='Oczekuje na partnera'?[{from:'BOK',kind:'bok',time:new Date(new Date(c.createdAt).getTime()+11*60000).toISOString(),text:'Dziękujemy za zgłoszenie. Weryfikujemy sprawę z partnerem.'},{from:c.partner||'Partner',kind:'partner',time:new Date(new Date(c.createdAt).getTime()+4*3600000).toISOString(),text:'Sprawa jest po naszej stronie w trakcie weryfikacji.'}]:[])
    ];
  }
  function bok66NormalizeComplaint(x,i){
    const id=String(x.id||x.complaint_number||`R-${1100+i}`);
    return {
      id:id.replace(/^CMP-2026-/,'R-'),
      sourceId:id,
      supabaseComplaintId:x.supabaseComplaintId||x.supabase_complaint_id||null,
      type:'Reklamacja',
      client:x.client||'Up Bonus Shared',
      employee:x.employee||x.employee_name||'Pracownik',
      email:x.email||x.user_email||'',
      eaccount:x.eaccount||x.employeeId||'—',
      subject:x.subject||x.reason||x.product||'Reklamacja',
      partner:x.partner||x.operator||'Do ustalenia',
      amount:Number(x.amount||x.value||String(x.product||'').match(/\d+/)?.[0]||0),
      status:x.status||'Nowa',
      priority:x.priority||'Normalny',
      slaMinutes:Number(x.slaMinutes??x.sla_minutes??(ub74SystemConfig().rules.defaultSlaHours*60)),
      owner:x.owner||'—',
      orderId:x.orderId||x.order||x.frontend_order_id||'—',
      voucherId:x.voucherId||x.voucher||'—',
      product:x.product||x.product_name||'Voucher',
      paymentSource:x.paymentSource||x.payment||'e-konto główne',
      paymentStatus:x.paymentStatus||'Opłacona',
      createdAt:x.createdAt||x.created_at||x.date||new Date().toISOString(),
      closedAt:x.closedAt||x.resolvedAt||null,
      reason:x.reason||x.type||'Reklamacja',
      description:x.description||x.response||x.reason||'',
      decision:x.decision||'—',
      settlement:x.settlement||'Do decyzji',
      timeline:Array.isArray(x.timeline)?x.timeline:null,
      messages:Array.isArray(x.messages)?x.messages:null
    };
  }
  function bok66Cases(){
    const s=bok66Load();
    const pools=[
      ...(Array.isArray(safeState()?.v103?.complaints)?safeState().v103.complaints:[]),
      ...(Array.isArray(safeState()?.v64?.complaints)?safeState().v64.complaints:[])
    ];
    const real=pools.map(bok66NormalizeComplaint);
    const all=[...s.localCases,...real,...BOK66_DEMO];
    const map=new Map();
    all.forEach(c=>{if(c&&c.id&&!map.has(String(c.id)))map.set(String(c.id),{...c,timeline:bok66Timeline(c),messages:bok66Messages(c)})});
    return [...map.values()];
  }
  function bok66Case(id){return bok66Cases().find(c=>String(c.id)===String(id))}
  function bok66Patch(id,patch,historyLabel,historyDetail){
    const s=bok66Load();
    let c=s.localCases.find(x=>String(x.id)===String(id));
    if(!c){
      const base=bok66Case(id);
      if(!base)return null;
      c=JSON.parse(JSON.stringify(base));
      s.localCases.unshift(c);
    }
    Object.assign(c,patch);
    c.timeline=Array.isArray(c.timeline)?c.timeline:bok66Timeline(c);
    if(historyLabel)c.timeline.push({time:new Date().toISOString(),label:historyLabel,detail:historyDetail||''});
    bok66Save();
    return c;
  }
  async function bok66SyncSupabase(c,patch){
    if(!c?.supabaseComplaintId||!window.sb)return;
    try{
      const dbPatch={};
      if(patch.status!==undefined)dbPatch.status=patch.status;
      if(patch.owner!==undefined)dbPatch.owner=patch.owner;
      if(patch.partner!==undefined)dbPatch.partner=patch.partner;
      if(patch.decision!==undefined)dbPatch.decision=patch.decision;
      if(patch.settlement!==undefined)dbPatch.settlement=patch.settlement;
      if(patch.response!==undefined)dbPatch.response=patch.response;
      if(Object.keys(dbPatch).length)await window.sb.from('complaints').update(dbPatch).eq('id',c.supabaseComplaintId);
    }catch(e){console.warn('v66 Supabase complaint sync',e)}
  }

