  window.ub66OpenDecision=function(id,mode){
    const c=bok66Case(id);if(!c)return;
    const role=bok66Load().role;
    const seniorLimit=Number(ub74SystemConfig().limits.seniorRefund||500);
    if(mode==='approve'&&Number(c.amount)>0&&role==='Agent BOK'){toast13('Brak uprawnienia','Agent BOK nie może samodzielnie zatwierdzać zwrotów finansowych.');return}
    if(mode==='approve'&&Number(c.amount)>seniorLimit&&role==='Senior BOK'){toast13('Wymagana eskalacja',`Senior BOK może zatwierdzać reklamacje do ${seniorLimit.toLocaleString('pl-PL')} zł.`);return}
    const modal=document.createElement('div');modal.className='ub57-modal-backdrop';
    if(mode==='approve'){
      modal.innerHTML=`<div class="ub57-modal ub66-decision-modal"><div class="ub57-modal-head"><div><span>Reklamacja #${bok66Esc(c.id)}</span><h2>Uznaj reklamację</h2><p>Jedna decyzja uruchamia wszystkie powiązane operacje.</p></div><button class="ub57-close" onclick="this.closest('.ub57-modal-backdrop').remove()">×</button></div><form class="ub66-decision-form" onsubmit="return ub66Approve(event,'${c.id}')"><div class="ub66-decision-amount"><span>Kwota reklamacji</span><b>${bok66Money(c.amount)}</b></div><label>Sposób rozwiązania<select name="solution"><option value="refund">Zwrot na e-konto</option><option value="voucher">Nowy voucher</option><option value="retry">Ponowna realizacja</option><option value="manual">Korekta ręczna</option><option value="other">Inne</option></select></label><label>Źródło zwrotu<select name="source"><option>${bok66Esc(c.paymentSource||'e-konto główne')}</option><option>ZFŚS</option><option>Premia</option><option>Lunch</option><option>e-konto główne</option></select></label><label>Wiadomość do klienta<textarea name="response" rows="4" required>Reklamacja została uznana. Wskazane rozwiązanie zostało wykonane.</textarea></label><div class="ub57-actions"><button type="button" class="secondary-btn" onclick="this.closest('.ub57-modal-backdrop').remove()">Anuluj</button><button class="primary-btn">Zatwierdź decyzję</button></div></form></div>`;
    }else{
      modal.innerHTML=`<div class="ub57-modal ub66-decision-modal"><div class="ub57-modal-head"><div><span>Reklamacja #${bok66Esc(c.id)}</span><h2>Odrzuć reklamację</h2><p>Powód i uzasadnienie są wymagane.</p></div><button class="ub57-close" onclick="this.closest('.ub57-modal-backdrop').remove()">×</button></div><form class="ub66-decision-form" onsubmit="return ub66Reject(event,'${c.id}')"><label>Powód<select name="reason" required><option>Produkt prawidłowo wydany</option><option>Voucher wykorzystany</option><option>Reklamacja po terminie</option><option>Brak podstaw</option><option>Błąd użytkownika</option><option>Inne</option></select></label><label>Uzasadnienie dla klienta<textarea name="response" rows="5" required></textarea></label><div class="ub57-actions"><button type="button" class="secondary-btn" onclick="this.closest('.ub57-modal-backdrop').remove()">Anuluj</button><button class="ub66-action-danger">Odrzuć reklamację</button></div></form></div>`;
    }
    document.body.appendChild(modal);
  };

  window.ub66Approve=function(ev,id){
    ev.preventDefault();const fd=new FormData(ev.currentTarget),solution=String(fd.get('solution')),response=String(fd.get('response')||'').trim(),c=bok66Case(id);if(!c)return false;
    let decision='Uznana',settlement='Bez korekty',effect='Reklamacja uznana.';
    if(solution==='refund'){
      decision='Uznana — zwrot';settlement='Zwrot';
      if(c.orderId&&c.orderId!=='—'&&typeof window.ubApplyRefund111==='function'){
        const ok=window.ubApplyRefund111(c.orderId,'Zwrot po uznanej reklamacji',c.sourceId||c.id,'Zwrot po reklamacji');
        effect=ok?'Środki zwrócono do zapisanych źródeł płatności, voucher unieważniono.':'Decyzja zapisana; zwrot wymaga dostępnej transakcji źródłowej.';
      }
    }else if(solution==='voucher'){decision='Uznana — nowy voucher';settlement='Wymiana vouchera';effect='Zlecono wydanie nowego vouchera.'}
    else if(solution==='retry'){decision='Uznana — ponowna realizacja';settlement='Ponowna realizacja';effect='Zlecono ponowną realizację.'}
    else if(solution==='manual'){decision='Uznana — korekta ręczna';settlement='Korekta ręczna';effect='Utworzono korektę ręczną.'}
    const patch={status:'Zamknięta',decision,settlement,response,closedAt:new Date().toISOString(),paymentStatus:solution==='refund'?'Zwrócona':c.paymentStatus};
    const x=bok66Patch(id,patch,'Reklamacja uznana',effect);
    x.messages=Array.isArray(x.messages)?x.messages:bok66Messages(x);x.messages.push({from:'BOK',kind:'bok',time:new Date().toISOString(),text:response});
    bok66Save();bok66SyncSupabase(x,patch);ev.currentTarget.closest('.ub57-modal-backdrop')?.remove();toast13('Reklamacja uznana',effect);doRender();return false;
  };
  window.ub66Reject=function(ev,id){
    ev.preventDefault();const fd=new FormData(ev.currentTarget),reason=String(fd.get('reason')),response=String(fd.get('response')||'').trim();if(!response)return false;
    const patch={status:'Zamknięta',decision:'Odrzucona — '+reason,settlement:'Bez korekty',response,closedAt:new Date().toISOString()};
    const x=bok66Patch(id,patch,'Reklamacja odrzucona',reason);x.messages=Array.isArray(x.messages)?x.messages:bok66Messages(x);x.messages.push({from:'BOK',kind:'bok',time:new Date().toISOString(),text:response});bok66Save();bok66SyncSupabase(x,patch);ev.currentTarget.closest('.ub57-modal-backdrop')?.remove();toast13('Reklamacja odrzucona',reason);doRender();return false;
  };

