  function ub67ParseTable(raw){
    const lines=String(raw||'').trim().split(/\r?\n/).filter(Boolean);
    if(!lines.length)return [];
    const sep=lines[0].includes('\t')?'\t':lines[0].includes(';')?';':',';
    const cells=lines.map(l=>l.split(sep).map(v=>String(v||'').trim()));
    const norm=v=>String(v||'').toLowerCase().replace(/\s+/g,'_').replace(/[ąćęłńóśźż]/g,ch=>({ą:'a',ć:'c',ę:'e',ł:'l',ń:'n',ó:'o',ś:'s',ź:'z',ż:'z'}[ch]));
    let headers=cells[0].map(norm);
    const known=['employee_id','email','imie_i_nazwisko','name','dzial','grupa','group','wallet_id','program_id','kwota','waluta','opis'];
    const hasHeader=headers.some(h=>known.includes(h));
    const rows=hasHeader?cells.slice(1):cells;
    if(!hasHeader)headers=['employee_id','email','imie_i_nazwisko','dzial','grupa','program_id','kwota','waluta','opis'].slice(0,Math.max(...rows.map(r=>r.length),0));
    return rows.map(r=>Object.fromEntries(headers.map((h,i)=>[h,r[i]||''])));
  }

