  function ub68PolishGiftFrame(frame){
    try{
      const doc=frame.contentDocument;
      if(!doc)return;
      let style=doc.getElementById('ub68-integrated-style');
      if(!style){
        style=doc.createElement('style');
        style.id='ub68-integrated-style';
        style.textContent=`
          :root{--plum:#490F30;--plum-dark:#35091f;--purple:#7d4264;--purple-dark:#5c2446;--lilac:#f3e8ef;--lilac-soft:#fbf7fa;--line:#e6dce2;--bg:#fff}
          html,body{background:#fff!important}
          body{overflow-x:hidden!important}
          .shell{min-height:auto!important}
          .topbar{position:sticky!important;top:0!important;grid-template-columns:minmax(260px,1fr) auto!important;gap:12px!important;padding:10px 0 12px!important;border-bottom:1px solid var(--line)!important;background:#fff!important;backdrop-filter:none!important}
          .brand{display:none!important}
          .search{justify-self:stretch!important;max-width:none!important}
          .layout{display:block!important}
          .sidebar{display:none!important}
          main{padding:18px 0 26px!important}
          .container{max-width:none!important}
          .page-head{margin-bottom:14px!important}
          .page-head h1{font-size:26px!important}
          .hero{border-radius:16px!important;box-shadow:none!important}
          .card,.panel,.product-card{box-shadow:none!important}
          @media(max-width:900px){.topbar{grid-template-columns:1fr!important}.header-actions{justify-content:flex-end!important}}
        `;
        doc.head.appendChild(style);
      }
      const title=doc.querySelector('.brand b');
      if(title)title.textContent='Prezenty i personalizacja';
      doc.querySelector('.nav-btn[data-view="bok"]')?.remove();
      try{
        const fw=frame.contentWindow;
        if(fw?.state?.view==='bok'&&typeof fw.setView==='function')fw.setView('catalog');
      }catch(e){}
      doc.documentElement.dataset.ub68Integrated='1';
    }catch(e){}
  }

  window.ub68MountGiftShop=function(){
    const host=document.getElementById('ub68GiftHost');
    if(!host||safeState()?.role!=='hr'||safeState()?.section!=='Prezenty i personalizacja')return;

    if(window.__ub68GiftFrame){
      host.appendChild(window.__ub68GiftFrame);
      window.__ub68GiftFrame.classList.remove('hidden');
      ub68PolishGiftFrame(window.__ub68GiftFrame);
      document.getElementById('ub68GiftLoading')?.remove();
      return;
    }

    if(typeof openModule!=='function'){
      host.innerHTML='<div class="ub68-gift-error">Sklep personalizowany nie jest dostępny w tej sesji.</div>';
      return;
    }

    try{
      openModule('gift');
      const shell=document.getElementById('moduleShell');
      const frame=document.getElementById('moduleFrame');
      if(!frame)throw new Error('moduleFrame missing');

      /* Najważniejsze: nie pokazujemy pełnoekranowej warstwy modułu nawet przez jedną klatkę. */
      if(shell)shell.style.setProperty('display','none','important');

      frame.classList.add('ub68-integrated-frame');
      host.appendChild(frame);
      if(shell)shell.remove();
      window.__ub68GiftFrame=frame;

      const onReady=()=>{
        frame.classList.remove('hidden');
        ub68PolishGiftFrame(frame);
        document.getElementById('ub68GiftLoading')?.remove();
        try{
          if(typeof frame.contentWindow?.setView==='function')frame.contentWindow.setView('catalog');
          else if(frame.contentWindow?.state&&typeof frame.contentWindow?.render==='function'){
            frame.contentWindow.state.view='catalog';
            frame.contentWindow.render();
          }
        }catch(e){}
      };
      frame.addEventListener('load',onReady,{once:true});
      if(frame.contentDocument?.readyState==='complete'&&frame.contentDocument?.body)onReady();
    }catch(e){
      document.getElementById('moduleShell')?.remove();
      host.innerHTML='<div class="ub68-gift-error">Nie udało się załadować sklepu. Odśwież widok i spróbuj ponownie.</div>';
    }
  };

