  const UB92_FINANCE_KEY='upbonus.finance.ledger.v92';
  function ub92FinanceSeed(){
    const clients=['Erste Bank','Open Benefit','Up Bonus','Aptitude Software Poland'];
    const partners=['Allegro','Empik','Decathlon','Amilon','Pluxee','Benefit Systems'];
    const suppliers=['Allegro sp. z o.o.','Empik S.A.','Decathlon sp. z o.o.','Amilon S.p.A.','Pluxee Polska','Benefit Systems S.A.'];
    const programs=['Budżet benefitowy','ZFŚS','Lunch','Upominek jubileuszowy','Sport','Wellbeing'];
    const products=[['Karta Allegro 100 zł','ALG-100'],['Karta Empik 100 zł','EMP-100'],['Decathlon 200 zł','DEC-200'],['Voucher 50 zł','AMI-50'],['Kod lunch','PLX-LUNCH'],['Pakiet sport','BFS-SPORT']];
    const sales=[],purchases=[],documents=[],payments=[],refunds=[];
    for(let i=0;i<36;i++){
      const day=String(1+(i%23)).padStart(2,'0'), date=`2026-08-${day}`, orderId=`ORD-2026-${8200+i}`;
      const client=clients[i%clients.length], partner=partners[i%partners.length], supplier=suppliers[i%suppliers.length], program=programs[i%programs.length], [product,sku]=products[i%products.length];
      const qty=[1,2,5,10,20,50][i%6], unit=[50,100,200,300,120,80][i%6], gross=qty*unit, vatRate=23, net=Math.round(gross/1.23*100)/100, vat=Math.round((gross-net)*100)/100;
      const buyGross=Math.round(gross*(.90+((i%4)*.01))*100)/100, buyNet=Math.round(buyGross/1.23*100)/100, buyVat=Math.round((buyGross-buyNet)*100)/100;
      const saleStatus=i%11===0?'Anulowana':i%9===0?'Zwrócona':'Zrealizowana';
      const paymentStatus=i%7===0?'Po terminie':i%5===0?'Do zapłaty':'Opłacona';
      const saleId=`SAL-${8200+i}`, purchaseId=`PUR-${5200+i}`, saleDoc=`DOC-S-${8200+i}`, buyDoc=`DOC-P-${5200+i}`;
      sales.push({id:saleId,orderId,date,client,program,partner,product,sku,qty,unitGross:unit,net,vat,gross,status:saleStatus,paymentMethod:i%3===0?'Przelew':'Saldo platformy',paymentDue:`2026-09-${String(5+i%20).padStart(2,'0')}`,paymentStatus,documentId:saleDoc,cancelReason:saleStatus==='Anulowana'?['Rezygnacja klienta','Błąd płatności','Brak dostępności'][i%3]:saleStatus==='Zwrócona'?'Zwrot po reklamacji':''});
      purchases.push({id:purchaseId,orderId,date,partner,supplier,program,product,sku,qty,net:buyNet,vat:buyVat,gross:buyGross,status:i%8===0?'Oczekuje':'Zaksięgowany',paymentMode:i%3===0?'Przedpłata':'Termin płatności',paymentDue:`2026-09-${String(8+i%18).padStart(2,'0')}`,paymentStatus:i%6===0?'Do zapłaty':'Opłacona',documentId:buyDoc});
      documents.push({id:saleDoc,number:`FV/2026/08/${String(300+i).padStart(4,'0')}`,direction:'Sprzedaż',type:i%6===0?'Nota księgowa':'FV',entity:client,orderId,date,net,vat,gross,paymentStatus,accountingStatus:'Zaksięgowany',erpStatus:i%5===0?'Do eksportu':'Wyeksportowany'});
      documents.push({id:buyDoc,number:i%5===0?`NK-P/${String(700+i)}`:`FV-K/${String(900+i)}`,direction:'Zakup',type:i%5===0?'Nota księgowa':'FV kosztowa',entity:supplier,orderId,date,net:buyNet,vat:buyVat,gross:buyGross,paymentStatus:i%6===0?'Do zapłaty':'Opłacona',accountingStatus:i%7===0?'Do weryfikacji':'Zaksięgowany',erpStatus:i%4===0?'Do eksportu':'Wyeksportowany'});
      payments.push({id:`PAY-${i+1}`,orderId,date,direction:'Wpływ',entity:client,amount:gross,status:paymentStatus});
      if(saleStatus==='Zwrócona')refunds.push({id:`REF-${i+1}`,orderId,date,client,partner,amount:gross,reason:'Reklamacja uznana',status:'Zrealizowany'});
    }
    return {sales,purchases,documents,payments,refunds};
  }
  function ub92FinanceData(){let d;try{d=JSON.parse(localStorage.getItem(UB92_FINANCE_KEY)||'null')}catch(e){}if(!d||!Array.isArray(d.sales)){d=ub92FinanceSeed();try{localStorage.setItem(UB92_FINANCE_KEY,JSON.stringify(d))}catch(e){}}return d}
  function ub92FinanceState(){const s=safeState();s.ub92Finance=s.ub92Finance||{};const f=s.ub92Finance;f.q=f.q||'';f.from=f.from||'2026-08-01';f.to=f.to||'2026-08-31';f.client=f.client||'Wszyscy';f.partner=f.partner||'Wszyscy';f.program=f.program||'Wszystkie';f.status=f.status||'Wszystkie';f.sort=f.sort||'dateDesc';f.group=f.group||'partner';f.selected=f.selected||{};return f}
  window.ub92FinanceFilter=(k,v)=>{ub92FinanceState()[k]=v;doRender()};
  function ub92Uniq(rows,key){return [...new Set(rows.map(x=>x[key]).filter(Boolean))].sort((a,b)=>String(a).localeCompare(String(b),'pl'))}
  function ub92Apply(rows){const f=ub92FinanceState(),q=String(f.q||'').toLowerCase();let r=rows.filter(x=>(!f.from||!x.date||x.date>=f.from)&&(!f.to||!x.date||x.date<=f.to));if(f.client!=='Wszyscy')r=r.filter(x=>x.client===f.client||x.entity===f.client);if(f.partner!=='Wszyscy')r=r.filter(x=>x.partner===f.partner||x.entity===f.partner);if(f.program!=='Wszystkie')r=r.filter(x=>x.program===f.program);if(f.status!=='Wszystkie')r=r.filter(x=>(x.status||x.paymentStatus||x.accountingStatus)===f.status);if(q)r=r.filter(x=>Object.values(x).join(' ').toLowerCase().includes(q));return [...r].sort((a,b)=>f.sort==='grossDesc'?Number(b.gross||b.amount||0)-Number(a.gross||a.amount||0):f.sort==='name'?String(a.client||a.partner||a.entity||'').localeCompare(String(b.client||b.partner||b.entity||''),'pl'):String(b.date||'').localeCompare(String(a.date||'')))}
  function ub92Toolbar(rows){const f=ub92FinanceState(),all=[...ub92FinanceData().sales,...ub92FinanceData().purchases],opts=(arr,val,label)=>`<option>${label}</option>${arr.map(x=>`<option ${val===x?'selected':''}>${esc(x)}</option>`).join('')}`;return `<div class="ub92-fin-toolbar"><div class="ub67-search"><span>⌕</span><input value="${esc(f.q)}" placeholder="Szukaj ID, zamówienia, dokumentu, SKU..." oninput="ub92FinanceFilter('q',this.value)"></div><label>Od<input type="date" value="${f.from}" onchange="ub92FinanceFilter('from',this.value)"></label><label>Do<input type="date" value="${f.to}" onchange="ub92FinanceFilter('to',this.value)"></label><select onchange="ub92FinanceFilter('client',this.value)">${opts(ub92Uniq(all,'client'),f.client,'Wszyscy')}</select><select onchange="ub92FinanceFilter('partner',this.value)">${opts(ub92Uniq(all,'partner'),f.partner,'Wszyscy')}</select><select onchange="ub92FinanceFilter('program',this.value)">${opts(ub92Uniq(all,'program'),f.program,'Wszystkie')}</select><select onchange="ub92FinanceFilter('sort',this.value)"><option value="dateDesc">Data ↓</option><option value="grossDesc" ${f.sort==='grossDesc'?'selected':''}>Kwota ↓</option><option value="name" ${f.sort==='name'?'selected':''}>Nazwa A–Z</option></select><button class="secondary-btn" onclick="ub92ExportCurrent()">Excel / CSV</button></div>`}
  function ub92Kpis(){const d=ub92FinanceData(),s=ub92Apply(d.sales),p=ub92Apply(d.purchases),gmv=s.reduce((a,x)=>a+x.gross,0),cost=p.reduce((a,x)=>a+x.gross,0),margin=gmv-cost,recv=s.filter(x=>x.paymentStatus!=='Opłacona').reduce((a,x)=>a+x.gross,0),pay=p.filter(x=>x.paymentStatus!=='Opłacona').reduce((a,x)=>a+x.gross,0);return `<section class="ub92-kpis"><article><span>Sprzedaż / GMV</span><b>${ub69Money(gmv)}</b></article><article><span>Zakupy / koszt</span><b>${ub69Money(cost)}</b></article><article><span>Marża</span><b>${ub69Money(margin)}</b><small>${gmv?(margin/gmv*100).toFixed(2):'0.00'}%</small></article><article><span>Należności</span><b>${ub69Money(recv)}</b></article><article><span>Zobowiązania</span><b>${ub69Money(pay)}</b></article></section>`}
  function ub92MarginRows(){const d=ub92FinanceData(),map={};ub92Apply(d.sales).forEach(s=>{const p=d.purchases.filter(x=>x.orderId===s.orderId).reduce((a,x)=>a+x.gross,0);const k=s.partner||'—';map[k]=map[k]||{sales:0,cost:0,orders:0};map[k].sales+=s.gross;map[k].cost+=p;map[k].orders++});return Object.entries(map).map(([name,v])=>({name,...v,margin:v.sales-v.cost}))}
  function ub92Pivot(){const rows=ub92MarginRows();return `<section class="ub92-sheet"><div class="ub92-sheet-head"><div><b>Zestawienie marży</b><span>Sprzedaż vs zakup według partnera</span></div></div><div class="ub92-scroll"><table><thead><tr><th>Partner</th><th>Zamówienia</th><th>Sprzedaż</th><th>Koszt</th><th>Marża</th><th>Marża %</th></tr></thead><tbody>${rows.map(x=>`<tr><td><b>${esc(x.name)}</b></td><td>${x.orders}</td><td>${ub69Money(x.sales)}</td><td>${ub69Money(x.cost)}</td><td><b>${ub69Money(x.margin)}</b></td><td>${x.sales?(x.margin/x.sales*100).toFixed(2):'0.00'}%</td></tr>`).join('')}</tbody></table></div></section>`}
  function ub92Table(kind,rows){const checkbox=`<th><input type="checkbox" onchange="ub92SelectAll('${kind}',this.checked)"></th>`;let heads='',body='';if(kind==='sales'){heads='<th>Data</th><th>Sprzedaż</th><th>Zamówienie</th><th>Klient</th><th>Program</th><th>Partner</th><th>Produkt / SKU</th><th>Ilość</th><th>Netto</th><th>VAT</th><th>Brutto</th><th>Płatność</th><th>Status</th><th>Dokument</th>';body=rows.map(x=>`<tr><td><input class="ub92-row-select" data-kind="${kind}" data-id="${x.id}" type="checkbox"></td><td>${x.date}</td><td>${x.id}</td><td>${x.orderId}</td><td>${esc(x.client)}</td><td>${esc(x.program)}</td><td>${esc(x.partner)}</td><td><b>${esc(x.product)}</b><small>${esc(x.sku)}</small></td><td>${x.qty}</td><td>${ub69Money(x.net)}</td><td>${ub69Money(x.vat)}</td><td><b>${ub69Money(x.gross)}</b></td><td>${esc(x.paymentStatus)}</td><td>${ub69Status(x.status)}</td><td><button class="ub67-table-action" onclick="ub92OpenDoc('${x.documentId}')">Podgląd</button></td></tr>`).join('')}else if(kind==='purchases'){heads='<th>Data</th><th>Zakup</th><th>Zamówienie</th><th>Partner</th><th>Dostawca</th><th>Program</th><th>Produkt / SKU</th><th>Ilość</th><th>Netto</th><th>VAT</th><th>Brutto</th><th>Forma</th><th>Termin</th><th>Status</th><th>Dokument</th>';body=rows.map(x=>`<tr><td><input class="ub92-row-select" data-kind="${kind}" data-id="${x.id}" type="checkbox"></td><td>${x.date}</td><td>${x.id}</td><td>${x.orderId}</td><td>${esc(x.partner)}</td><td>${esc(x.supplier)}</td><td>${esc(x.program)}</td><td><b>${esc(x.product)}</b><small>${esc(x.sku)}</small></td><td>${x.qty}</td><td>${ub69Money(x.net)}</td><td>${ub69Money(x.vat)}</td><td><b>${ub69Money(x.gross)}</b></td><td>${esc(x.paymentMode)}</td><td>${esc(x.paymentDue)}</td><td>${ub69Status(x.status)}</td><td><button class="ub67-table-action" onclick="ub92OpenDoc('${x.documentId}')">Podgląd</button></td></tr>`).join('')}else if(kind==='documents'){heads='<th>Data</th><th>Numer</th><th>Kierunek</th><th>Typ</th><th>Kontrahent</th><th>Zamówienie</th><th>Netto</th><th>VAT</th><th>Brutto</th><th>Płatność</th><th>Księgowanie</th><th>ERP</th><th></th>';body=rows.map(x=>`<tr><td><input class="ub92-row-select" data-kind="${kind}" data-id="${x.id}" type="checkbox"></td><td>${x.date}</td><td><b>${esc(x.number)}</b></td><td>${x.direction}</td><td>${x.type}</td><td>${esc(x.entity)}</td><td>${x.orderId}</td><td>${ub69Money(x.net)}</td><td>${ub69Money(x.vat)}</td><td><b>${ub69Money(x.gross)}</b></td><td>${esc(x.paymentStatus)}</td><td>${esc(x.accountingStatus)}</td><td>${esc(x.erpStatus)}</td><td><button class="ub67-table-action" onclick="ub92OpenDoc('${x.id}')">PDF / drukuj</button></td></tr>`).join('')}return `<section class="ub92-sheet"><div class="ub92-scroll"><table class="ub92-wide"><thead><tr>${checkbox}${heads}</tr></thead><tbody>${body||'<tr><td colspan="20">Brak danych dla wybranych filtrów.</td></tr>'}</tbody></table></div></section>`}
  window.ub92SelectAll=(kind,v)=>document.querySelectorAll(`.ub92-row-select[data-kind="${kind}"]`).forEach(x=>x.checked=v);
  function ub92DocHtml(doc){return `<!doctype html><html lang="pl"><head><meta charset="utf-8"><title>${esc(doc.number)}</title><style>body{font-family:Arial;margin:40px;color:#311521}.head{display:flex;justify-content:space-between;border-bottom:3px solid #6b174e;padding-bottom:16px}.brand{font-size:28px;font-weight:800;color:#6b174e}.tag{color:#ff8500}.box{margin-top:25px;border:1px solid #eadfe5;border-radius:12px;padding:18px}table{width:100%;border-collapse:collapse;margin-top:18px}td{padding:8px;border-bottom:1px solid #eee}.sum{font-size:22px;font-weight:800;color:#6b174e}.foot{margin-top:35px;font-size:12px;color:#777}@media print{button{display:none}}</style></head><body><div class="head"><div class="brand">Up <span class="tag">Bonus</span></div><div><b>${esc(doc.type)}</b><br>${esc(doc.number)}</div></div><div class="box"><b>${doc.direction==='Sprzedaż'?'Nabywca':'Dostawca'}:</b> ${esc(doc.entity)}<br><b>Zamówienie:</b> ${doc.orderId}<br><b>Data:</b> ${doc.date}</div><table><tr><td>Wartość netto</td><td>${ub69Money(doc.net)}</td></tr><tr><td>VAT</td><td>${ub69Money(doc.vat)}</td></tr><tr><td><b>Wartość brutto</b></td><td class="sum">${ub69Money(doc.gross)}</td></tr><tr><td>Status płatności</td><td>${esc(doc.paymentStatus)}</td></tr><tr><td>Status księgowy</td><td>${esc(doc.accountingStatus)}</td></tr><tr><td>ERP</td><td>${esc(doc.erpStatus)}</td></tr></table><div class="foot">Dokument wygenerowany w systemie Up Bonus.</div><button onclick="window.print()">Drukuj / zapisz jako PDF</button></body></html>`}
  window.ub92OpenDoc=function(id){const doc=ub92FinanceData().documents.find(x=>x.id===id);if(!doc)return;const w=window.open('','_blank');if(!w)return;w.document.write(ub92DocHtml(doc));w.document.close()};
  function ub92Csv(rows){if(!rows.length)return '';const h=Object.keys(rows[0]);return [h.join(';'),...rows.map(r=>h.map(k=>`"${String(r[k]??'').replace(/"/g,'""')}"`).join(';'))].join('\n')}
  window.ub92ExportRows=function(rows,name){const blob=new Blob(['\ufeff'+ub92Csv(rows)],{type:'text/csv;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500)};
  window.ub92ExportCurrent=function(){const section=safeState()?.section||'',d=ub92FinanceData();let rows=section==='Sprzedaż'?ub92Apply(d.sales):section==='Zakupy'?ub92Apply(d.purchases):section==='Dokumenty księgowe'?ub92Apply(d.documents):section==='Należności'?ub92Apply(d.sales).filter(x=>x.paymentStatus!=='Opłacona'):section==='Zobowiązania'?ub92Apply(d.purchases).filter(x=>x.paymentStatus!=='Opłacona'):section==='Zwroty i korekty'?d.refunds:ub92Apply(d.sales);ub92ExportRows(rows,`upbonus-${section.toLowerCase().replace(/\s+/g,'-')||'finanse'}.csv`)};
