/* ===== SOURCE: upbonus-offer-studio-v21.js ===== */
(function(){
  'use strict';
  if(typeof state==='undefined') return;

  const BUILD='v43-product-studio';
  document.documentElement.dataset.upbonusOfferStudio=BUILD;

  const ESC=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const CATEGORIES=['Bilety','Doładowania','Dom','Edukacja','Karty podarunkowe','Kody rabatowe','Kultura','Moda','Personalizacja','Podróże','Prezenty','Sport','Uroda','Vouchery','Wellbeing','Żywność'];
  const TYPES=['Karta podarunkowa','Voucher','Kod rabatowy','Bilet','Usługa','Produkt cyfrowy','Benefit abonamentowy'];
  const PROGRAMS=['Prezent 2026','Premia kwartalna','ZFŚS — Kultura','ZFŚS — Sport','ZFŚS — Wypoczynek','Lunch 2026','Wellbeing'];

  function seedOffers(){
    if(Array.isArray(state.v21Offers)){const a=state.v21Offers.find(o=>o.sourceProductId==='PRD-ALG'||o.id==='OFR-ALG');if(a&&!a.image){a.image='/assets/products/allegro-demo.webp';a.imageName='allegro-demo.webp'}return;}
    const old=state.v30?.partnerOffers||[];
    state.v21Offers=old.map((o,i)=>({
      id:o.id||`OFR-${1000+i}`,
      sourceProductId:o.productId||o.sourceProductId||'',
      name:o.name||'Oferta',
      brand:o.name||'Marka',
      type:o.type||'Karta podarunkowa',
      category:o.category||'Karty podarunkowe',
      description:o.description||'Skorzystaj z benefitu w prosty sposób — wybierz wariant i przejdź do realizacji.',
      howToUse:o.howToUse||'1. Wybierz wariant.\n2. Potwierdź zakup lub odbiór.\n3. Kod znajdziesz w sekcji Moje.',
      image:o.image||'',
      imageName:o.imageName||'',
      variants:(o.variants?String(o.variants).split(/[,–;]/).map((x,idx)=>({id:`VAR-${Date.now()}-${idx}`,name:x.trim()||`Wariant ${idx+1}`,value:x.trim(),limitPerUser:1,stockLimit:0,active:true})):[]),
      limitPerUser:o.limitPerUser||1,
      segment:o.segment||'Wszyscy pracownicy',
      programs:o.programs||[],
      shop:o.shop!==false,
      giftCampaign:!!o.giftCampaign,
      ewallet:o.ewallet!==false,
      zfss:!!o.zfss,
      lunch:!!o.lunch,
      privatePay:o.privatePay!==false,
      status:o.status||'Roboczy',
      createdAt:o.createdAt||'2026-08-22',
      updatedAt:o.updatedAt||'2026-08-22'
    }));
    if(!state.v21Offers.length){
      state.v21Offers=[
        sample('OFR-ALG','Allegro','Karta podarunkowa','Karty podarunkowe','#FFE1C0'),
        sample('OFR-EMP','Empik','Karta podarunkowa','Karty podarunkowe','#F5EBDD'),
        sample('OFR-MUL','Multikino','2 bilety','Bilety','#F3E5EE')
      ];
      const allegro=state.v21Offers.find(o=>o.id==='OFR-ALG');if(allegro){allegro.image='/assets/products/allegro-demo.webp';allegro.imageName='allegro-demo.webp'}
    }
    save();
  }
  function sample(id,brand,name,cat,color){return {id,sourceProductId:id==='OFR-ALG'?'PRD-ALG':id==='OFR-EMP'?'PRD-EMP':id==='OFR-MUL'?'PRD-MUL':'',name,brand,type:name.includes('bilet')?'Bilet':'Karta podarunkowa',category:cat,description:`${brand} — benefit dostępny dla pracowników w programie Up Bonus.`,howToUse:'1. Wybierz wariant.\n2. Potwierdź zakup.\n3. Kod znajdziesz w sekcji Moje.',image:'',imageColor:color,imageName:'',variants:[{id:id+'-50',name:'50 zł',value:'50',limitPerUser:2,stockLimit:0,active:true},{id:id+'-100',name:'100 zł',value:'100',limitPerUser:2,stockLimit:0,active:true}],limitPerUser:2,segment:'Wszyscy pracownicy',programs:['Prezent 2026'],shop:true,giftCampaign:true,ewallet:true,zfss:false,lunch:false,privatePay:true,status:'Aktywny',createdAt:'2026-08-22',updatedAt:'2026-08-22'} }
  function save(){try{typeof persist==='function'&&persist()}catch(e){}}
  function nowDate(){return new Date().toISOString().slice(0,10)}
  function offer(id){seedOffers();return state.v21Offers.find(x=>x.id===id)}
  function defaultDraft(){return {id:'',sourceProductId:'',name:'',brand:'',type:'Karta podarunkowa',category:'Karty podarunkowe',description:'',howToUse:'',image:'',imageName:'',variants:[{id:'VAR-'+Date.now(),name:'50 zł',value:'50',limitPerUser:1,stockLimit:0,active:true}],limitPerUser:1,segment:'Wszyscy pracownicy',programs:[],shop:true,giftCampaign:false,ewallet:true,zfss:false,lunch:false,privatePay:true,status:'Roboczy',createdAt:nowDate(),updatedAt:nowDate()}}
  function clone(v){return JSON.parse(JSON.stringify(v))}


  function commerceProducts(){try{return typeof EMP_PRODUCTS!=='undefined'?EMP_PRODUCTS:[]}catch(e){return []}}
  function sourceProductOptions(selected){return `<option value="">Brak powiązania — produkt informacyjny</option>${commerceProducts().map(p=>`<option value="${ESC(p.id)}" ${selected===p.id?'selected':''}>${ESC(p.name)} · ${ESC(p.id)}</option>`).join('')}`}

  function cardVisual(o,compact=false){
    const bg=o.image?`background-image:url('${String(o.image).replace(/'/g,"\\'")}');`:'';
    const fallback=o.imageColor||'#F3E5EE';
    return `<div class="v21-offer-card ${compact?'is-compact':''}">
      <div class="v21-offer-image" style="background-color:${fallback};${bg}">${!o.image?`<span class="v21-image-placeholder">${ESC((o.brand||o.name||'UP').slice(0,2).toUpperCase())}</span>`:''}</div>
      <div class="v21-offer-titlebar"><span>${ESC(o.brand||'Up Bonus')}</span><strong>${ESC(o.name||'Nazwa oferty')}</strong></div>
      <div class="v21-offer-copy"><p>${ESC(o.description||'Opis produktu będzie widoczny tutaj — zawsze poza grafiką.')}</p><div class="v21-offer-meta"><span>${ESC(o.category||'Kategoria')}</span><span>${o.variants?.length||0} warianty</span></div></div>
    </div>`;
  }

  window.ub99OpenCategory=function(name){
  ub69SuperState().offerTab='Kategorie';
  ub69SuperState().focusCategory=name||'';
  render();
};
window.ub99OpenPartner=function(name){
  ub69SuperState().offerTab='Partnerzy';
  ub69SuperState().focusPartner=name||'';
  render();
};
window.ub99OpenCollections=function(){
  ub69SuperState().offerTab='Kolekcje';
  render();
};

function catalogView(){
    seedOffers();
    const q=String(state.v21OfferQuery||'').toLowerCase();
    const status=state.v21OfferStatus||'all';
    const category=state.v21OfferCategory||'all';
    const rows=state.v21Offers.filter(o=>(status==='all'||o.status===status)&&(category==='all'||o.category===category)&&`${o.brand} ${o.name} ${o.category} ${o.type}`.toLowerCase().includes(q));
    const cats=[...new Set(state.v21Offers.map(x=>x.category))].sort((a,b)=>a.localeCompare(b,'pl'));
    return `${typeof pageHead==='function'?pageHead('Produkty','Dodawaj produkty od A do Z: grafika, opis, warianty, limity, podgląd i publikacja.',`<button class="primary-btn" onclick="v21NewOffer()">＋ Dodaj produkt</button>`):'<h1>Produkty</h1>'}
      <section class="v21-toolbar-card">
        <div class="v21-search"><span>⌕</span><input value="${ESC(state.v21OfferQuery||'')}" placeholder="Szukaj po marce, nazwie lub kategorii…" oninput="v21OfferQuery(this.value)"></div>
        <select onchange="v21OfferCategory(this.value)"><option value="all">Wszystkie kategorie</option>${cats.map(c=>`<option value="${ESC(c)}" ${category===c?'selected':''}>${ESC(c)}</option>`).join('')}</select>
        <select onchange="v21OfferStatus(this.value)"><option value="all">Wszystkie statusy</option>${['Aktywny','Roboczy','Wyłączony'].map(s=>`<option ${status===s?'selected':''}>${s}</option>`).join('')}</select>
      </section>
      <section class="v21-catalog-grid">${rows.map(o=>`<article class="v21-admin-card">
        ${cardVisual(o,true)}
        <div class="v21-admin-actions"><span class="status ${o.status==='Aktywny'?'green':o.status==='Roboczy'?'purple':'gray'}">${ESC(o.status)}</span><div><button onclick="v21PreviewOffer('${ESC(o.id)}')">Podgląd</button><button onclick="v21EditOffer('${ESC(o.id)}')">Edytuj</button><button onclick="v21ToggleStatus('${ESC(o.id)}')">${o.status==='Aktywny'?'Dezaktywuj':'Aktywuj'}</button></div></div>
      </article>`).join('')||'<div class="empty-state">Brak ofert dla wybranych filtrów.</div>'}</section>`;
  }

  function wizardHeader(d){
    const steps=['Podstawy','Treść','Grafika','Warianty i limity','Dostępność','Podgląd'];
    const current=Number(state.v21WizardStep||1);
    return `<div class="v21-stepper">${steps.map((s,i)=>`<button class="${current===i+1?'active':current>i+1?'done':''}" onclick="v21GoStep(${i+1})"><span>${current>i+1?'✓':i+1}</span>${s}</button>`).join('')}</div>`;
  }

  function stepBasic(d){return `<div class="v21-form-grid"><div class="field"><label>Marka</label><input id="v21Brand" value="${ESC(d.brand)}" placeholder="np. Empik"></div><div class="field"><label>Nazwa produktu</label><input id="v21Name" value="${ESC(d.name)}" placeholder="np. Karta podarunkowa 100 zł"></div><div class="field"><label>Typ produktu</label><select id="v21Type">${TYPES.map(x=>`<option ${d.type===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Kategoria</label><select id="v21Category">${CATEGORIES.map(x=>`<option ${d.category===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field v21-full-field"><label>Powiąż z procesem zakupowym</label><select id="v21SourceProduct">${sourceProductOptions(d.sourceProductId||'')}</select><small>Jeśli produkt ma być kupowany w istniejącym checkoutcie i reklamowany po zakupie, wskaż produkt źródłowy. Grafika i opis mogą być zarządzane niezależnie.</small></div></div>`}
  function stepContent(d){return `<div class="v21-content-grid"><div class="field"><label>Opis produktu</label><textarea id="v21Description" rows="7" placeholder="Krótko i konkretnie: co użytkownik dostaje i dlaczego warto.">${ESC(d.description)}</textarea><small>Opis zawsze jest wyświetlany w osobnej części karty — nigdy na grafice.</small></div><div class="field"><label>Jak skorzystać</label><textarea id="v21HowToUse" rows="7" placeholder="1. Wybierz wariant…\n2. Potwierdź…\n3. Kod znajdziesz w Moje…">${ESC(d.howToUse)}</textarea><small>Instrukcja pojawi się na szczegółach oferty jako czytelna lista.</small></div></div>`}
  function stepImage(d){return `<div class="v21-image-editor"><div class="field"><label>Grafika <strong>(format karty bankowej 85,60 × 53,98 mm)</strong></label><div class="v21-upload-row"><label class="v21-upload-btn">${d.image?'Zmień grafikę':'Wgraj grafikę'}<input type="file" accept="image/png,image/jpeg,image/webp" onchange="v21UploadImage(this)"></label>${d.image?'<button class="secondary-btn" onclick="v21RemoveImage()">Usuń</button>':''}<span>${ESC(d.imageName||'PNG/JPG/WEBP')}</span></div><small>Grafika pozostaje bez zmian. System wyświetla ją w proporcji standardowej karty bankowej ID-1: 85,60 × 53,98 mm (ok. 1,586:1). Najlepszy efekt daje plik np. 1012 × 638 px lub większy w tej samej proporcji.</small></div><div class="v21-image-preview">${d.image?`<img src="${d.image}" alt="Podgląd grafiki">`:`<div class="v21-empty-image"><b>85,60 × 53,98 mm</b><span>Standard karty bankowej ID-1</span></div>`}</div></div>`}
  function variantRows(d){return `<div class="v21-variant-list">${d.variants.map((v,i)=>`<div class="v21-variant-row"><div class="field"><label>Wariant</label><input value="${ESC(v.name)}" onchange="v21Variant(${i},'name',this.value)"></div><div class="field"><label>Wartość / cena</label><input value="${ESC(v.value)}" onchange="v21Variant(${i},'value',this.value)"></div><div class="field"><label>Limit / użytkownik</label><input type="number" min="0" value="${Number(v.limitPerUser||0)}" onchange="v21Variant(${i},'limitPerUser',this.value)"></div><div class="field"><label>Limit puli</label><input type="number" min="0" value="${Number(v.stockLimit||0)}" onchange="v21Variant(${i},'stockLimit',this.value)"></div><label class="v21-mini-toggle"><input type="checkbox" ${v.active!==false?'checked':''} onchange="v21Variant(${i},'active',this.checked)"><span>Aktywny</span></label><button class="v21-remove-row" onclick="v21RemoveVariant(${i})">×</button></div>`).join('')}</div>`}
  function stepVariants(d){return `<div class="v21-variants-head"><div><h4>Warianty oferty</h4><p>Każdy wariant może mieć osobny limit per użytkownik i osobny limit całej puli.</p></div><button class="secondary-btn" onclick="v21AddVariant()">＋ Dodaj wariant</button></div>${variantRows(d)}<div class="v21-limit-note"><b>0 = bez limitu puli.</b> Limit per użytkownik określa, ile razy jedna osoba może wybrać dany wariant.</div>`}
  function stepAvailability(d){return `<div class="v21-form-grid"><div class="field"><label>Segment</label><select id="v21Segment">${['Wszyscy pracownicy','Wybrane grupy','Wybrane lokalizacje','Tylko administratorzy'].map(x=>`<option ${d.segment===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Status po zapisie</label><select id="v21Status">${['Roboczy','Aktywny','Wyłączony'].map(x=>`<option ${d.status===x?'selected':''}>${x}</option>`).join('')}</select></div></div><h4>Widoczność</h4><div class="v21-check-grid"><label><input id="v21Shop" type="checkbox" ${d.shop?'checked':''}><span><b>Sklep pracownika</b><small>Widoczna w katalogu benefitów.</small></span></label><label><input id="v21Gift" type="checkbox" ${d.giftCampaign?'checked':''}><span><b>Upominki / kampanie</b><small>Może być użyta w kampaniach HR.</small></span></label></div><h4>Programy</h4><div class="v21-program-grid">${PROGRAMS.map(p=>`<label><input data-v21-program type="checkbox" value="${ESC(p)}" ${d.programs.includes(p)?'checked':''}><span>${ESC(p)}</span></label>`).join('')}</div><h4>Źródła finansowania</h4><div class="v21-check-grid"><label><input id="v21Ewallet" type="checkbox" ${d.ewallet?'checked':''}><span><b>E-konto</b></span></label><label><input id="v21Zfss" type="checkbox" ${d.zfss?'checked':''}><span><b>ZFŚS</b></span></label><label><input id="v21Lunch" type="checkbox" ${d.lunch?'checked':''}><span><b>Lunch</b></span></label><label><input id="v21Private" type="checkbox" ${d.privatePay?'checked':''}><span><b>Środki własne</b></span></label></div>`}
  function detailPreview(d){return `<div class="v21-preview-layout"><div>${cardVisual(d)}</div><aside class="v21-detail-preview"><span class="status ${d.status==='Aktywny'?'green':d.status==='Roboczy'?'purple':'gray'}">${ESC(d.status)}</span><h3>${ESC(d.name||'Nazwa oferty')}</h3><p>${ESC(d.description||'Opis produktu')}</p><h4>Jak skorzystać</h4><div class="v21-howto">${ESC(d.howToUse||'Instrukcja pojawi się tutaj.').replace(/\n/g,'<br>')}</div><h4>Warianty</h4><div class="v21-preview-variants">${d.variants.filter(v=>v.active!==false).map(v=>`<span>${ESC(v.name)} · limit ${Number(v.limitPerUser||0)||'∞'}/os.</span>`).join('')}</div></aside></div>`}
  function stepPreview(d){return detailPreview(d)}

  function captureStep(){
    const d=state.v21Draft;if(!d)return;
    const val=id=>document.getElementById(id)?.value;
    const chk=id=>document.getElementById(id)?.checked;
    if(document.getElementById('v21Brand'))d.brand=val('v21Brand')||d.brand;
    if(document.getElementById('v21Name'))d.name=val('v21Name')||d.name;
    if(document.getElementById('v21Type'))d.type=val('v21Type')||d.type;
    if(document.getElementById('v21Category'))d.category=val('v21Category')||d.category;
    if(document.getElementById('v21Description'))d.description=val('v21Description')||'';
    if(document.getElementById('v21HowToUse'))d.howToUse=val('v21HowToUse')||'';
    if(document.getElementById('v21Segment'))d.segment=val('v21Segment')||d.segment;
    if(document.getElementById('v21Status'))d.status=val('v21Status')||d.status;
    if(document.getElementById('v21Shop'))d.shop=!!chk('v21Shop');
    if(document.getElementById('v21Gift'))d.giftCampaign=!!chk('v21Gift');
    if(document.getElementById('v21Ewallet'))d.ewallet=!!chk('v21Ewallet');
    if(document.getElementById('v21Zfss'))d.zfss=!!chk('v21Zfss');
    if(document.getElementById('v21Lunch'))d.lunch=!!chk('v21Lunch');
    if(document.getElementById('v21Private'))d.privatePay=!!chk('v21Private');
    const ps=[...document.querySelectorAll('[data-v21-program]:checked')].map(x=>x.value);if(document.querySelector('[data-v21-program]'))d.programs=ps;
  }

  function wizardModal(){
    const d=state.v21Draft||defaultDraft();state.v21Draft=d;
    const step=Number(state.v21WizardStep||1);
    const body=[stepBasic,stepContent,stepImage,stepVariants,stepAvailability,stepPreview][step-1](d);
    return `<div class="modal-backdrop" onclick="if(event.target===this)closeModal()"><section class="modal v21-offer-modal"><div class="modal-head"><div><h3>${d.id?'Edytuj produkt':'Nowy produkt'}</h3><span>Kompletny proces od treści i grafiki po warianty, limity i publikację.</span></div><button class="close-btn" onclick="closeModal()">×</button></div>${wizardHeader(d)}<div class="modal-body v21-wizard-body">${body}</div><div class="modal-foot"><button class="secondary-btn" onclick="v21CancelOffer()">Anuluj</button><div class="v21-foot-actions">${step>1?'<button class="secondary-btn" onclick="v21PrevStep()">← Wstecz</button>':''}${step<6?'<button class="primary-btn" onclick="v21NextStep()">Dalej →</button>':`<button class="secondary-btn" onclick="v21SaveOffer('Roboczy')">Zapisz roboczo</button><button class="primary-btn" onclick="v21SaveOffer('Aktywny')">Aktywuj produkt</button>`}</div></div></section></div>`;
  }
  function previewModal(){const d=offer(state.modal?.data?.id);if(!d)return '';return `<div class="modal-backdrop" onclick="if(event.target===this)closeModal()"><section class="modal v21-preview-modal"><div class="modal-head"><div><h3>Podgląd oferty</h3><span>Tak oferta będzie wyglądać dla pracownika.</span></div><button class="close-btn" onclick="closeModal()">×</button></div><div class="modal-body">${detailPreview(d)}</div><div class="modal-foot"><button class="secondary-btn" onclick="closeModal()">Zamknij</button><button class="secondary-btn" onclick="v21EditOffer('${ESC(d.id)}')">Edytuj</button><button class="primary-btn" onclick="v21ToggleStatus('${ESC(d.id)}')">${d.status==='Aktywny'?'Dezaktywuj':'Aktywuj'}</button></div></section></div>`}

  window.v21OfferQuery=v=>{state.v21OfferQuery=v;render()};
  window.v21OfferStatus=v=>{state.v21OfferStatus=v;render()};
  window.v21OfferCategory=v=>{state.v21OfferCategory=v;render()};
  window.v21NewOffer=()=>{state.v21Draft=defaultDraft();state.v21WizardStep=1;state.modal={type:'v21OfferWizard'};renderOverlay()};
  window.v21EditOffer=id=>{state.v21Draft=clone(offer(id)||defaultDraft());state.v21WizardStep=1;state.modal={type:'v21OfferWizard',data:{id}};renderOverlay()};
  window.v21PreviewOffer=id=>{state.modal={type:'v21OfferPreview',data:{id}};renderOverlay()};
  window.v21CancelOffer=()=>{state.v21Draft=null;state.modal=null;render()};
  window.v21GoStep=n=>{captureStep();state.v21WizardStep=Math.min(6,Math.max(1,n));renderOverlay()};
  window.v21NextStep=()=>window.v21GoStep((state.v21WizardStep||1)+1);
  window.v21PrevStep=()=>window.v21GoStep((state.v21WizardStep||1)-1);
  window.v21AddVariant=()=>{state.v21Draft.variants.push({id:'VAR-'+Date.now(),name:`Wariant ${state.v21Draft.variants.length+1}`,value:'',limitPerUser:1,stockLimit:0,active:true});renderOverlay()};
  window.v21RemoveVariant=i=>{if(state.v21Draft.variants.length<=1){toast?.('Zostaw jeden wariant','Produkt musi mieć co najmniej jeden wariant.');return}state.v21Draft.variants.splice(i,1);renderOverlay()};
  window.v21Variant=(i,key,val)=>{const v=state.v21Draft.variants[i];if(!v)return;v[key]=['limitPerUser','stockLimit'].includes(key)?Math.max(0,Number(val)||0):val};
  window.v21RemoveImage=()=>{state.v21Draft.image='';state.v21Draft.imageName='';renderOverlay()};
  window.v21UploadImage=function(input){const file=input?.files?.[0];if(!file)return;const reader=new FileReader();reader.onload=e=>{const img=new Image();img.onload=()=>{const target=85.60/53.98;const ratio=img.width/img.height;const tolerance=.006;if(Math.abs(ratio-target)>tolerance){input.value='';toast?.('Nieprawidłowy format grafiki',`Wgraj grafikę w proporcji standardowej karty bankowej 85,60:53,98, np. 1012 × 638 px. Ten plik ma ${img.width} × ${img.height} px.`);return}state.v21Draft.image=e.target.result;state.v21Draft.imageName=`${file.name} · ${img.width} × ${img.height} px`;renderOverlay()};img.src=e.target.result};reader.readAsDataURL(file)};
  window.v21SaveOffer=function(forceStatus){captureStep();const d=state.v21Draft;if(!d)return;if(!d.brand.trim()||!d.name.trim()){state.v21WizardStep=1;renderOverlay();toast?.('Uzupełnij produkt','Podaj markę i nazwę oferty.');return}if(!d.description.trim()||!d.howToUse.trim()){state.v21WizardStep=2;renderOverlay();toast?.('Uzupełnij treść','Dodaj opis oraz instrukcję „Jak skorzystać”.');return}d.status=forceStatus||d.status||'Roboczy';d.updatedAt=nowDate();if(!d.id){d.id='OFR-'+Date.now().toString().slice(-7);state.v21Offers.unshift(clone(d))}else{const idx=state.v21Offers.findIndex(x=>x.id===d.id);if(idx>=0)state.v21Offers[idx]=clone(d);else state.v21Offers.unshift(clone(d))}state.v21Draft=null;state.modal=null;save();render();toast?.(d.status==='Aktywny'?'Produkt aktywowany':'Produkt zapisany',d.name)};
  window.v21ToggleStatus=function(id){const o=offer(id);if(!o)return;o.status=o.status==='Aktywny'?'Wyłączony':'Aktywny';o.updatedAt=nowDate();save();state.modal=null;render();toast?.(o.status==='Aktywny'?'Produkt aktywowany':'Produkt dezaktywowany',o.name)};


  function ensureBokProductsMenu(){
    try{
      if(!window.ROLE_DEFS?.bok?.menu)return;
      const menu=window.ROLE_DEFS.bok.menu;
      const filtered=menu.filter(item=>!['Katalog i oferty','Katalog i oferta','Produkty'].includes(item[0]));
      const insertAt=Math.min(5,filtered.length);
      filtered.splice(insertAt,0,['Produkty','shop']);
      window.ROLE_DEFS.bok.menu=filtered;
    }catch(e){}
  }
  ensureBokProductsMenu();

  // Backward compatibility: all legacy "Dodaj/Edytuj produkt" actions open the new full flow.
  window.v30NewOffer=window.v21NewOffer;
  window.v30EditOffer=window.v21EditOffer;

  const prevRenderSection=window.renderSection;
  window.renderSection=function(){
    if(['partner','hr','operations'].includes(state.role)&&state.section==='Katalog i oferta')return catalogView();
    if(state.role==='bok'&&['Produkty','Katalog i oferta','Katalog i oferty'].includes(state.section))return catalogView();
    return prevRenderSection.apply(this,arguments);
  };
  const prevModalHtml=window.modalHtml;
  window.modalHtml=function(){
    if(state.modal?.type==='v21OfferWizard')return wizardModal();
    if(state.modal?.type==='v21OfferPreview')return previewModal();
    return prevModalHtml.apply(this,arguments);
  };

  seedOffers();
})();


