/* ===== SOURCE: upbonus-v104-consolidated.js ===== */
/* ===== v93 commerce + complaints (image override disabled) ===== */

(function(){
  'use strict';

  const BUILD='v93-commerce-complaints-image-fix';
  const IMAGE_W=760;
  const IMAGE_H=480;
  let pendingOfferImage='';
  let installCount=0;

  const num=(v,f=0)=>{
    const n=Number(v);
    return Number.isFinite(n)?n:f;
  };

  const persistSafe=()=>{
    try{
      if(typeof persist==='function')persist();
      else if(typeof save==='function')save();
    }catch(e){}
  };

  const renderSafe=()=>{
    try{ if(typeof render==='function')render(); }catch(e){}
  };

  const overlaySafe=()=>{
    try{ if(typeof renderOverlay==='function')renderOverlay(); }catch(e){}
  };

  const toastSafe=(title,text)=>{
    try{
      if(typeof toast==='function')toast(title,text);
    }catch(e){}
  };

  function inferWalletType(card){
    const raw=String(
      card?.walletType ??
      card?.kind ??
      card?.type ??
      card?.category ??
      ''
    ).toLowerCase();

    if(raw.includes('lunch')||raw.includes('żyw')||raw.includes('food'))return 'lunch';
    if(raw.includes('kultur')||raw.includes('culture'))return 'culture';
    return 'universal';
  }

  function cardBalance(card){
    return Math.max(
      0,
      num(
        card?.balance ??
        card?.availableBalance ??
        card?.available_balance ??
        card?.saldo ??
        0
      )
    );
  }

  function canonicalizeFunding(){
    if(typeof state==='undefined')return [];

    state.v14=state.v14||{};
    state.v19=state.v19||{};
    state.v19.wallets=Array.isArray(state.v19.wallets)?state.v19.wallets:[];
    state.v14.cards=Array.isArray(state.v14.cards)?state.v14.cards:[];

    const wallets=state.v19.wallets;
    const cards=state.v14.cards;

    let base=wallets.find(w=>w.id==='EW-BASE');
    const visibleEwallet=Math.max(0,num(state.v14.ewalletBalance));

    if(!base && visibleEwallet>0){
      base={
        id:'EW-BASE',
        name:'E-konto',
        type:'universal',
        balance:visibleEwallet,
        active:true
      };
      wallets.unshift(base);
    }else if(base){
      const canonical=Math.max(
        Math.max(0,num(base.balance)),
        visibleEwallet
      );
      base.balance=canonical;
      state.v14.ewalletBalance=canonical;
    }

    cards.forEach((card,index)=>{
      if(card?.active===false)return;

      const balance=cardBalance(card);
      const id=String(card.id||card.cardId||`CARD-${index+1}`);
      let wallet=wallets.find(w=>
        String(w.cardId||'')===id ||
        String(w.id||'')===String(card.walletId||'')
      );

      if(!wallet && balance>0){
        wallet={
          id:`EW-CARD-${id}`.replace(/[^A-Za-z0-9_-]/g,'-'),
          cardId:id,
          name:card.name||card.label||card.title||'Karta benefitowa',
          type:inferWalletType(card),
          balance,
          active:true,
          __ub93Synthetic:true
        };
        wallets.push(wallet);
      }else if(wallet){
        const canonical=Math.max(
          Math.max(0,num(wallet.balance)),
          balance
        );
        wallet.balance=canonical;
        wallet.type=wallet.type||inferWalletType(card);
        wallet.cardId=wallet.cardId||id;
        if(!wallet.name)wallet.name=card.name||card.label||'Karta benefitowa';
        card.balance=canonical;
      }
    });

    // Keep UI card balances and wallet balances identical.
    cards.forEach(card=>{
      const id=String(card.id||card.cardId||'');
      const wallet=wallets.find(w=>String(w.cardId||'')===id);
      if(wallet)card.balance=Math.max(0,num(wallet.balance));
    });

    if(base)state.v14.ewalletBalance=Math.max(0,num(base.balance));

    persistSafe();
    return wallets.filter(w=>w.active!==false);
  }

  function productFor(row){
    try{
      const list=typeof EMP_PRODUCTS!=='undefined'?EMP_PRODUCTS:[];
      return list.find(p=>p.id===row?.productId)||row;
    }catch(e){
      return row||{};
    }
  }

  function allowedTypes(product){
    try{
      if(typeof walletTypes19==='function'){
        const result=walletTypes19(product);
        if(Array.isArray(result)&&result.length)return result;
      }
    }catch(e){}

    const id=String(product?.id||product?.productId||'');
    const cat=String(product?.category||'').toLowerCase();

    if(id==='PRD-STEAM')return ['universal'];
    if(cat.includes('żyw')||cat.includes('food'))return ['lunch','universal'];
    if(cat.includes('kultur'))return ['culture','universal'];
    return ['universal','culture','lunch'];
  }

  function robustPaymentPlan(rows){
    const wallets=canonicalizeFunding();
    const remaining=Object.fromEntries(
      wallets.map(w=>[w.id,Math.max(0,num(w.balance))])
    );

    const usage={};
    let gateway=0;
    let total=0;

    const items=(Array.isArray(rows)?rows:[]).map(row=>{
      const quantity=Math.max(1,num(row?.quantity,1));
      const unit=Math.max(0,num(row?.nominal ?? row?.price ?? row?.value));
      const amount=unit*quantity;
      const product=productFor(row);
      const allowed=allowedTypes(product);

      const eligible=wallets
        .filter(w=>
          Math.max(0,num(remaining[w.id]))>0 &&
          (
            allowed.includes(w.type) ||
            (w.type==='universal'&&allowed.includes('universal'))
          )
        )
        .sort((a,b)=>{
          const score=w=>{
            if(w.type!=='universal')return 0;
            if(w.cardId)return 1;
            if(w.id==='EW-BASE')return 2;
            return 3;
          };
          return score(a)-score(b);
        });

      let left=amount;
      const allocations=[];

      eligible.forEach(w=>{
        if(left<=0)return;
        const use=Math.min(left,Math.max(0,num(remaining[w.id])));
        if(use<=0)return;

        remaining[w.id]-=use;
        left-=use;
        usage[w.id]=(usage[w.id]||0)+use;

        allocations.push({
          walletId:w.id,
          name:w.name||'E-konto',
          amount:use,
          kind:w.cardId?'assigned_card':'ewallet',
          cardId:w.cardId||null
        });
      });

      gateway+=Math.max(0,left);
      total+=amount;

      return {
        ...row,
        allocations,
        gateway:Math.max(0,left)
      };
    });

    return {
      items,
      total,
      walletTotal:Math.max(0,total-gateway),
      gateway:Math.max(0,gateway),
      walletUsage:usage
    };
  }

  function syncUiFromWallets(){
    if(typeof state==='undefined')return;
    const wallets=state.v19?.wallets||[];
    const cards=state.v14?.cards||[];

    const base=wallets.find(w=>w.id==='EW-BASE');
    if(base)state.v14.ewalletBalance=Math.max(0,num(base.balance));

    cards.forEach(card=>{
      const w=wallets.find(x=>String(x.cardId||'')===String(card.id||card.cardId||''));
      if(w)card.balance=Math.max(0,num(w.balance));
    });
  }

  function installPaymentPlanning(){
    window.paymentPlan103=robustPaymentPlan;
    try{ paymentPlan103=window.paymentPlan103; }catch(e){}

    if(typeof window.v15StartCheckout==='function'&&!window.v15StartCheckout.__ub93Wrapped){
      const baseStart=window.v15StartCheckout;

      const wrapped=function(){
        canonicalizeFunding();

        state.v105=state.v105||{};
        // A stale disabled payment source was causing the wrong option to stay selected.
        state.v105.selectedPaymentId=null;

        return baseStart.apply(this,arguments);
      };

      wrapped.__ub93Wrapped=true;
      wrapped.__ub93Base=baseStart;
      window.v15StartCheckout=wrapped;
      try{ v15StartCheckout=wrapped; }catch(e){}
    }
  }

  function installFinalPurchase(){
    const finalize=window.v15FinalizeCheckout;

    if(typeof finalize!=='function')return;

    const confirm=function(){
      const checkbox=document.getElementById('v105Confirm');

      if(!checkbox?.checked){
        const err=document.getElementById('v105ConfirmError');
        if(err)err.textContent='Zaznacz potwierdzenie, aby dokończyć zakup.';
        return;
      }

      if(window.__ub93PurchaseBusy)return;
      window.__ub93PurchaseBusy=true;

      try{
        canonicalizeFunding();

        const cart=Array.isArray(state.v14?.cart)?state.v14.cart:[];
        if(!cart.length){
          toastSafe('Zakup','Koszyk jest pusty.');
          return;
        }

        // The review already contains the chosen plan. Recalculate only if it is missing/stale.
        let plan=state.v15?.checkout;
        const expected=cart.reduce(
          (sum,row)=>sum+
            Math.max(0,num(row.nominal ?? row.price ?? row.value))*
            Math.max(1,num(row.quantity,1)),
          0
        );

        const planTotal=num(plan?.total,-1);

        if(!plan||Math.abs(planTotal-expected)>0.01){
          const expanded=cart.flatMap(row=>
            Array.from(
              {length:Math.max(1,num(row.quantity,1))},
              ()=>({...row,quantity:1})
            )
          );
          plan=robustPaymentPlan(expanded);
          state.v15=state.v15||{};
          state.v15.checkout=plan;
        }

        const internal=num(plan.walletTotal);
        const own=num(plan.gateway);

        if(internal+own+0.009<num(plan.total)){
          const err=document.getElementById('v105ConfirmError');
          if(err){
            err.textContent=
              `Dostępne środki: ${internal.toLocaleString('pl-PL',{minimumFractionDigits:2})} zł. `+
              `Brakuje ${(num(plan.total)-internal-own).toLocaleString('pl-PL',{minimumFractionDigits:2})} zł.`;
          }
          return;
        }

        const before=new Set((state.v14?.orders||[]).map(o=>o.id));

        // IMPORTANT: local canonical checkout is authoritative for the prototype.
        // Supabase must never block a valid card-wallet purchase because of a stale server-side balance.
        finalize();

        syncUiFromWallets();

        const created=(state.v14?.orders||[]).filter(o=>!before.has(o.id));

        state.v105=state.v105||{};
        state.v105.lastPurchase={
          orders:created.map(o=>o.id),
          vouchers:created.map(o=>o.voucherId).filter(Boolean),
          amount:created.reduce((s,o)=>s+num(o.value),0),
          time:new Date().toLocaleString('pl-PL')
        };

        state.modal={type:'v105Success'};
        persistSafe();
        overlaySafe();

        console.log('UB93 purchase OK',created);

      }catch(error){
        console.error('UB93 purchase error',error);
        toastSafe('Zakup','Nie udało się dokończyć zakupu. Sprawdź konsolę.');
      }finally{
        window.__ub93PurchaseBusy=false;
      }
    };

    confirm.__ub93Wrapped=true;
    window.v105Confirm=confirm;
    try{ v105Confirm=confirm; }catch(e){}
  }

  function findComplaint(id){
    const sets=[
      ...(Array.isArray(state?.v64?.complaints)?state.v64.complaints:[]),
      ...(Array.isArray(state?.v103?.complaints)?state.v103.complaints:[])
    ];

    return sets.find(c=>
      String(c?.id||'')===String(id) ||
      String(c?.complaint_number||'')===String(id) ||
      String(c?.supabaseComplaintId||'')===String(id)
    )||null;
  }

  function complaintCopies(id){
    const out=[];
    [state?.v64?.complaints,state?.v103?.complaints]
      .filter(Array.isArray)
      .forEach(arr=>{
        arr.forEach(c=>{
          if(
            String(c?.id||'')===String(id) ||
            String(c?.complaint_number||'')===String(id) ||
            String(c?.supabaseComplaintId||'')===String(id)
          ){
            if(!out.includes(c))out.push(c);
          }
        });
      });
    return out;
  }

  function orderForComplaint(c){
    const ids=[
      c?.orderId,
      c?.order_id,
      c?.orderNumber,
      c?.order_number,
      c?.supabaseOrderNumber
    ].filter(Boolean).map(String);

    return (state.v14?.orders||[]).find(o=>
      ids.includes(String(o.id||'')) ||
      ids.includes(String(o.orderNumber||''))
    )||null;
  }

  function voucherForComplaint(c,order){
    const ids=[
      c?.voucherId,
      c?.voucher_id,
      c?.voucher,
      order?.voucherId
    ].filter(Boolean).map(String);

    return (state.v14?.vouchers||[]).find(v=>ids.includes(String(v.id||'')))||null;
  }

  function applyComplaintRefund(c){
    canonicalizeFunding();

    const order=orderForComplaint(c);
    if(!order)return {ok:false,reason:'Brak lokalnego zamówienia do zwrotu.'};

    if(order.__complaintRefunded||order.__refundApplied){
      return {ok:true,reason:'Zwrot był już wykonany.'};
    }

    const tx=(state.v103?.transactions||[]).find(x=>
      String(x.orderId||x.order_id||'')===String(order.id)
    );

    const parts=tx?.paymentParts||tx?.payment_parts||[];

    parts.forEach(part=>{
      if(!['ewallet','assigned_card'].includes(part.sourceType||part.source_type))return;

      const id=part.sourceId||part.source_id;
      const wallet=(state.v19?.wallets||[]).find(w=>String(w.id)===String(id));
      if(wallet){
        wallet.balance=Math.max(0,num(wallet.balance))+Math.max(0,num(part.amount));
      }
    });

    if(tx)tx.status='Zwrócona';

    order.status='Zwrot po reklamacji';
    order.paymentStatus='Zwrócona';
    order.__complaintRefunded=true;
    order.__refundApplied=true;

    const voucher=voucherForComplaint(c,order);
    if(voucher)voucher.status='Unieważniony';

    state.wallet_transactions=Array.isArray(state.wallet_transactions)?state.wallet_transactions:[];
    state.wallet_transactions.unshift({
      id:'RF-CMP-'+String(Date.now()).slice(-9),
      order_id:order.id,
      voucher_id:order.voucherId||voucher?.id||null,
      complaint_id:c.id,
      amount:Math.max(0,num(order.value||c.amount)),
      status:'completed',
      type:'refund',
      created_at:new Date().toISOString(),
      reason:'Zwrot po uznanej reklamacji',
      payment_parts:parts
    });

    syncUiFromWallets();
    persistSafe();

    return {ok:true,reason:'Środki zwrócone do tych samych źródeł płatności.'};
  }

  function replaceComplaintVoucher(c){
    const order=orderForComplaint(c);
    const old=voucherForComplaint(c,order);
    if(!old)return null;

    if(old.__replacedByComplaint)return null;

    old.status='Unieważniony';
    old.__replacedByComplaint=true;

    const suffix=String(Date.now()).slice(-7);
    const id='VCH-R-'+suffix;
    const code='UPB-'+Math.random().toString(36).slice(2,7).toUpperCase()+
      '-'+Math.random().toString(36).slice(2,7).toUpperCase();

    const fresh={
      ...old,
      id,
      code,
      status:'Gotowy',
      complaintId:c.id,
      __replacedByComplaint:false,
      createdAt:new Date().toISOString()
    };

    state.v14.vouchers.unshift(fresh);
    if(order)order.replacementVoucherId=id;

    persistSafe();
    return fresh;
  }

  async function syncComplaintToSupabase(c,patch){
    if(!window.sb||!c)return;

    const payload={
      status:patch.status,
      owner:patch.owner,
      partner:patch.partner||null,
      decision:patch.decision||null,
      settlement:patch.settlement||null,
      response:patch.response||null,
      decided_at:new Date().toISOString()
    };

    try{
      let query=window.sb.from('complaints').update(payload);

      const supaId=c.supabaseComplaintId;
      const plainId=String(c.id||'');

      if(supaId){
        query=query.eq('id',supaId);
      }else if(/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(plainId)){
        query=query.eq('id',plainId);
      }else{
        query=query.eq('complaint_number',plainId);
      }

      const {error}=await query;
      if(error)console.warn('UB93 complaint Supabase sync warning',error);

    }catch(error){
      console.warn('UB93 complaint Supabase sync error',error);
    }
  }

  async function decisionSave(id){
    if(window.__ub93ComplaintBusy)return;
    window.__ub93ComplaintBusy=true;

    try{
      const complaint=findComplaint(id);

      if(!complaint){
        toastSafe('Reklamacja','Nie znaleziono sprawy.');
        return;
      }

      const decision=document.getElementById('v24Decision')?.value||
        document.getElementById('v64Decision')?.value||
        'Odrzucona';

      const response=String(
        document.getElementById('v24Response')?.value||
        complaint.response||
        ''
      ).trim();

      const partner=String(
        document.getElementById('v24Partner')?.value||
        complaint.partner||
        'Partner'
      ).trim()||'Partner';

      if(document.getElementById('v24Response')&&response.length<8){
        const e=document.getElementById('v24DecisionError');
        if(e)e.textContent='Wpisz odpowiedź dla pracownika — minimum 8 znaków.';
        return;
      }

      let settlement='Bez korekty';
      let effect='';

      if(decision==='Wymiana kodu'){
        const v=replaceComplaintVoucher(complaint);
        settlement='Korekta + nowy kod';
        effect=v?`Nowy voucher: ${v.id}`:'Voucher wymaga ręcznej weryfikacji.';
      }else if(decision==='Zwrot środków'){
        const result=applyComplaintRefund(complaint);
        settlement='Zwrot / korekta';
        effect=result.reason;
      }else if(decision==='Blokada kodu'){
        const order=orderForComplaint(complaint);
        const v=voucherForComplaint(complaint,order);
        if(v)v.status='Unieważniony';
        settlement='Wyłączenie z rozliczenia';
        effect='Voucher został unieważniony.';
      }else if(decision==='Korekta / uznana'){
        settlement='Korekta';
        effect='Reklamacja uznana do korekty.';
      }

      const patch={
        decision,
        status:'Zamknięta',
        owner:'Zamknięte',
        settlement,
        partner,
        response,
        resolvedAt:new Date().toLocaleString('pl-PL'),
        effect
      };

      complaintCopies(id).forEach(c=>Object.assign(c,patch));

      // Some Supabase-loaded records have UUID as id but complaint_number separately.
      if(!complaintCopies(id).length)Object.assign(complaint,patch);

      state.v27=state.v27||{};
      state.v27.notifications=Array.isArray(state.v27.notifications)?state.v27.notifications:[];
      state.v27.notifications.unshift({
        id:'N-'+Date.now(),
        icon:'✅',
        title:'Reklamacja rozpatrzona',
        text:`${complaint.id||id} • ${decision}`,
        time:'teraz',
        unread:true,
        section:'Zakupy i historia',
        role:'employee',
        complaintId:complaint.id||id
      });

      persistSafe();

      try{
        if(typeof closeModal==='function')closeModal();
        else state.modal=null;
      }catch(e){ state.modal=null; }

      renderSafe();

      await syncComplaintToSupabase(complaint,patch);

      toastSafe(
        'Reklamacja zamknięta',
        decision==='Zwrot środków'
          ?'Decyzja zapisana, a środki zwrócone do źródeł płatności.'
          :'Decyzja została zapisana i jest widoczna po stronie pracownika.'
      );

    }catch(error){
      console.error('UB93 complaint decision error',error);
      toastSafe('Reklamacja','Nie udało się zapisać decyzji. Sprawdź konsolę.');
    }finally{
      window.__ub93ComplaintBusy=false;
    }
  }

  function installComplaints(){
    window.v24DecisionSave=decisionSave;
    try{ v24DecisionSave=decisionSave; }catch(e){}

    window.v64ComplaintDecisionSave=decisionSave;
    try{ v64ComplaintDecisionSave=decisionSave; }catch(e){}
  }

  function cropToCardRatio(file,callback){
    const reader=new FileReader();

    reader.onerror=()=>{
      toastSafe('Grafika','Nie udało się odczytać pliku.');
    };

    reader.onload=()=>{
      const img=new Image();

      img.onerror=()=>{
        toastSafe('Grafika','Nie udało się wczytać obrazu.');
      };

      img.onload=()=>{
        try{
          const targetRatio=IMAGE_W/IMAGE_H;
          const srcRatio=img.naturalWidth/img.naturalHeight;

          let sx=0,sy=0,sw=img.naturalWidth,sh=img.naturalHeight;

          if(srcRatio>targetRatio){
            sw=img.naturalHeight*targetRatio;
            sx=(img.naturalWidth-sw)/2;
          }else{
            sh=img.naturalWidth/targetRatio;
            sy=(img.naturalHeight-sh)/2;
          }

          const canvas=document.createElement('canvas');
          canvas.width=IMAGE_W;
          canvas.height=IMAGE_H;

          const ctx=canvas.getContext('2d');
          ctx.imageSmoothingEnabled=true;
          ctx.imageSmoothingQuality='high';
          ctx.drawImage(img,sx,sy,sw,sh,0,0,IMAGE_W,IMAGE_H);

          let data='';
          try{
            data=canvas.toDataURL('image/webp',0.90);
          }catch(e){
            data=canvas.toDataURL('image/jpeg',0.92);
          }

          callback(data);
        }catch(error){
          console.error('UB93 crop error',error);
          toastSafe('Grafika','Nie udało się wykadrować obrazu.');
        }
      };

      img.src=String(reader.result||'');
    };

    reader.readAsDataURL(file);
  }

  function updateImagePreview(input,data){
    const modal=input.closest('.ub88-offer-modal,.modal')||document;

    const preview=
      modal.querySelector('.ub88-image-preview')||
      document.getElementById('ubOfferImagePreview');

    if(preview){
      preview.innerHTML=`<img src="${data}" alt="Podgląd grafiki oferty">`;
    }

    const hidden=modal.querySelector('input[type="hidden"][name="image"]');
    if(hidden)hidden.value=data;

    let help=input.parentElement?.querySelector('.ub-offer-image-help');
    if(help){
      help.textContent=
        'PNG, JPG lub WebP • obraz jest automatycznie kadrowany do 760 × 480 px (proporcja karty).';
    }
  }

  function imageInputMatch(input){
    if(!(input instanceof HTMLInputElement)||input.type!=='file')return false;

    return (
      input.id==='ubOfferImage' ||
      input.closest('.ub88-file-drop') ||
      input.matches('[data-offer-image]') ||
      /offer.*image|image.*offer/i.test(input.name||'')
    );
  }

  function installImageCapture(){
    if(document.documentElement.dataset.ub93ImageCapture==='1')return;
    document.documentElement.dataset.ub93ImageCapture='1';

    document.addEventListener('change',event=>{
      const input=event.target;
      if(!imageInputMatch(input))return;

      const file=input.files?.[0];
      if(!file){
        pendingOfferImage='';
        return;
      }

      if(!/^image\/(png|jpeg|webp)$/i.test(file.type)){
        input.value='';
        toastSafe('Grafika','Wybierz PNG, JPG lub WebP.');
        return;
      }

      // Source may be much larger. It is reduced before saving to local state.
      if(file.size>12*1024*1024){
        input.value='';
        toastSafe('Grafika','Maksymalny plik źródłowy to 12 MB.');
        return;
      }

      cropToCardRatio(file,data=>{
        pendingOfferImage=data;
        updateImagePreview(input,data);
        toastSafe('Grafika gotowa','Obraz został wczytany i automatycznie wykadrowany do proporcji karty.');
      });

    },true);
  }

  function applyCroppedImageToLegacyOffer(beforeIds,editId){
    if(!pendingOfferImage)return;

    const list=state?.v15?.customProducts||[];

    let target=null;

    if(editId){
      target=list.find(p=>String(p.id)===String(editId));
    }

    if(!target){
      target=[...list].reverse().find(p=>p?.id&&!beforeIds.has(String(p.id)))||list[0];
    }

    if(!target)return;

    const fallback=target.iconFallback||target.icon||'🎫';
    const html=`<img class="ub-product-real-image ub93-product-image" src="${pendingOfferImage}" alt="">`;

    target.iconFallback=fallback;
    target.imageData=pendingOfferImage;
    target.image=pendingOfferImage;
    target.icon=html;

    try{
      if(typeof EMP_PRODUCTS!=='undefined'){
        const p=EMP_PRODUCTS.find(x=>String(x.id)===String(target.id));
        if(p){
          p.iconFallback=fallback;
          p.imageData=pendingOfferImage;
          p.image=pendingOfferImage;
          p.icon=html;
        }
      }
    }catch(e){}

    pendingOfferImage='';
    persistSafe();
    renderSafe();
  }

  function installLegacyOfferSave(){
    if(typeof window.v15SaveOffer!=='function'||window.v15SaveOffer.__ub93ImageWrapped)return;

    const base=window.v15SaveOffer;

    const wrapped=function(){
      const before=new Set((state?.v15?.customProducts||[]).map(p=>String(p.id||'')));
      const editId=state?.modal?.data?.id||null;
      const result=base.apply(this,arguments);

      setTimeout(()=>applyCroppedImageToLegacyOffer(before,editId),0);
      return result;
    };

    wrapped.__ub93ImageWrapped=true;
    window.v15SaveOffer=wrapped;
    try{ v15SaveOffer=wrapped; }catch(e){}
  }

  function installOfferStudioImage(){
    // New Offer Studio uses inline onchange="ub88OfferImage(this)".
    window.ub88OfferImage=function(input){
      const file=input.files?.[0];
      if(!file)return;

      if(!/^image\/(png|jpeg|webp)$/i.test(file.type)){
        input.value='';
        toastSafe('Grafika','Wybierz PNG, JPG lub WebP.');
        return;
      }

      if(file.size>12*1024*1024){
        input.value='';
        toastSafe('Grafika','Maksymalny plik źródłowy to 12 MB.');
        return;
      }

      cropToCardRatio(file,data=>{
        pendingOfferImage=data;
        updateImagePreview(input,data);
      });
    };
  }

  function patchImageDom(){
    document.querySelectorAll(
      '.ub-offer-image-preview img,.ub88-image-preview img,.benefit-cover .ub-product-real-image,.product-detail-visual .ub-product-real-image'
    ).forEach(img=>{
      img.classList.add('ub93-product-image');
    });

    const help=document.querySelector('.ub-offer-image-help');
    if(help&&!help.dataset.ub93){
      help.dataset.ub93='1';
      help.textContent=
        'PNG, JPG lub WebP • zalecane minimum 760 × 480 px. System automatycznie wykadruje grafikę do proporcji karty.';
    }
  }

  function install(){
    installCount++;

    canonicalizeFunding();
    installPaymentPlanning();
    installFinalPurchase();
    installComplaints();
    installImageCapture();
    installLegacyOfferSave();
    /* v104: image handler consolidated in v100 */
    patchImageDom();

    document.documentElement.dataset.upbonusCommerceFix=BUILD;

    console.log('Up Bonus V93 ready', {installCount});
  }

  const observer=new MutationObserver(()=>{
    requestAnimationFrame(()=>{
      patchImageDom();
      // When old code reconstructs modal handlers, put the authoritative handlers back.
      if(installCount>0){
        installComplaints();
        /* v104: image handler consolidated in v100 */
      }
    });
  });

  observer.observe(document.documentElement,{subtree:true,childList:true});

  if(document.readyState==='complete'){
    setTimeout(install,1800);
    setTimeout(install,3000);
  }else{
    window.addEventListener('load',()=>{
      setTimeout(install,1800);
      setTimeout(install,3000);
    },{once:true});
  }

})();


