window.ub96SaveEmployee=function(ev,id){
  ev.preventDefault();const fd=new FormData(ev.currentTarget),rows=employees();
  const ages=String(fd.get('childAges')||'').split(/[,\s;]+/).map(Number).filter(x=>Number.isFinite(x)&&x>=0&&x<40);
  const data={
    employeeId:String(fd.get('employeeId')||id),name:String(fd.get('name')||'').trim(),email:String(fd.get('email')||'').trim(),
    phone:String(fd.get('phone')||''),gender:String(fd.get('gender')||'Nie podano'),birthDate:String(fd.get('birthDate')||''),
    children:num(fd.get('children')),childAges:ages,department:String(fd.get('department')||''),group:String(fd.get('group')||''),
    team:String(fd.get('team')||''),position:String(fd.get('position')||''),manager:String(fd.get('manager')||''),
    legalEntity:String(fd.get('legalEntity')||''),costCenter:String(fd.get('costCenter')||''),workLocation:String(fd.get('workLocation')||''),
    employmentDate:String(fd.get('employmentDate')||''),employmentType:String(fd.get('employmentType')||''),language:String(fd.get('language')||'PL'),
    status:String(fd.get('status')||'Aktywny'),programId:String(fd.get('programId')||''),walletId:String(fd.get('walletId')||''),
    balance:num(fd.get('balance')),serviceConsent:fd.has('serviceConsent'),marketingConsent:fd.has('marketingConsent'),updatedAt:new Date().toISOString()
  };
  const i=rows.findIndex(x=>x.employeeId===id);if(i>=0)rows[i]={...rows[i],...data};else rows.unshift(data);
  saveEmployees(rows);ev.currentTarget.closest('.ub57-modal-backdrop')?.remove();toastSafe('Pracownik zapisany',data.name);renderSafe();return false;
};
window.ub96ToggleEmployee=function(id){
  const rows=employees(),e=rows.find(x=>x.employeeId===id);if(!e)return;
  e.status=e.status==='Zablokowany'?'Aktywny':'Zablokowany';e.updatedAt=new Date().toISOString();saveEmployees(rows);renderSafe();
};

