window.ub96BuyCards=function(productId){
  let p=null;try{p=catalogProducts(activeClient()).find(x=>String(x.productId)===String(productId))}catch(e){}
  if(!p)return;
  const qty=Math.max(1,Number(prompt('Liczba kart / voucherów','10')||0));if(!qty)return;
  const amount=Math.max(0,Number(prompt('Nominał jednej karty','100')||0));if(!amount)return;
  const rows=cardOrders();rows.unshift({id:'HRC-'+Date.now(),productId,name:p.title||p.brand,partner:p.brand,qty,amount,total:qty*amount,date:today(),status:'Do realizacji'});saveCardOrders(rows);
  toastSafe('Zamówienie zapisane',`${qty} × ${money(amount)}`);renderSafe();
};
function benefitsView96(){
  let all=[];try{all=catalogProducts(activeClient())}catch(e){}
  const cards=all.filter(p=>/karta|voucher/i.test(`${p.offerType||''} ${p.title||''} ${p.category||''}`)).slice(0,20);
  const orders=cardOrders();
  return `<div class="page-content ub96-page"><div class="page-head"><div><h1>Benefity</h1><p>Zakup kart podarunkowych i voucherów dla organizacji.</p></div></div>
    <section class="ub96-sheet"><div class="ub96-sheet-head"><b>Karty i vouchery</b><span>${cards.length} dostępnych</span></div><div class="ub96-scroll"><table><thead><tr><th>Produkt</th><th>Partner</th><th>Kategoria</th><th>Typ</th><th></th></tr></thead><tbody>${cards.map(p=>`<tr><td><b>${esc(p.title||p.brand)}</b></td><td>${esc(p.brand||'—')}</td><td>${esc(p.category||'—')}</td><td>${esc(p.offerType||'Voucher')}</td><td><button class="ub96-primary-mini" onclick="ub96BuyCards('${esc(p.productId)}')">Kup karty</button></td></tr>`).join('')}</tbody></table></div></section>
    <section class="ub96-sheet"><div class="ub96-sheet-head"><b>Ostatnie zamówienia HR</b><span>${orders.length}</span></div><div class="ub96-scroll"><table><thead><tr><th>Data</th><th>Produkt</th><th>Ilość</th><th>Nominał</th><th>Łącznie</th><th>Status</th></tr></thead><tbody>${orders.map(x=>`<tr><td>${x.date}</td><td>${esc(x.name)}</td><td>${x.qty}</td><td>${money(x.amount)}</td><td><b>${money(x.total)}</b></td><td>${esc(x.status)}</td></tr>`).join('')||'<tr><td colspan="6">Brak zamówień.</td></tr>'}</tbody></table></div></section></div>`;
}

/* ========= FUNDING ========= */
function fundingRows(){return store(FUND_KEY,[])}
function saveFunding(x){save(FUND_KEY,x)}
function fundState(){
  const s=window.state||(window.state={});
  s.ub96Fund=s.ub96Fund||{editId:'',q:'',department:'Wszystkie',selected:[],amount:100,name:'',program:'PRG-1041',recurrence:'Jednorazowo',bookDate:today()};
  return s.ub96Fund;
}
window.ub96FundField=(k,v)=>{fundState()[k]=v;renderSafe()};
window.ub96FundToggle=function(id,on){const s=fundState(),set=new Set(s.selected||[]);on?set.add(id):set.delete(id);s.selected=[...set];renderSafe()};
window.ub96FundSelectVisible=function(on){
  const s=fundState(),all=employees().filter(e=>e.status==='Aktywny'&&(s.department==='Wszystkie'||e.department===s.department));
  const set=new Set(s.selected||[]);all.forEach(e=>on?set.add(e.employeeId):set.delete(e.employeeId));s.selected=[...set];renderSafe()
};
window.ub96FundingReset=function(){window.state.ub96Fund={editId:'',q:'',department:'Wszystkie',selected:[],amount:100,name:'',program:'PRG-1041',recurrence:'Jednorazowo',bookDate:today()};renderSafe()};
window.ub96FundingSaveDraft=function(){
  const s=fundState(),selected=employees().filter(e=>(s.selected||[]).includes(e.employeeId));
  if(!selected.length){toastSafe('Brak odbiorców','Wybierz pracowników.');return}
  const rows=fundingRows();const id=s.editId||'FND-'+String(Date.now()).slice(-9);
  const data={id,name:s.name||`Zasilenie ${today()}`,date:s.bookDate,program:s.program,recurrence:s.recurrence,amount:num(s.amount),recipients:selected.map(e=>({employeeId:e.employeeId,name:e.name,department:e.department,amount:num(s.amount)})),total:selected.length*num(s.amount),status:'Szkic',createdAt:new Date().toISOString()};
  const i=rows.findIndex(x=>x.id===id);if(i>=0)rows[i]=data;else rows.unshift(data);saveFunding(rows);toastSafe('Szkic zapisany','Zasilenie czeka na podgląd i wysłanie.');window.state.ub96Fund={...s,editId:id};renderSafe()
};
window.ub96FundingEdit=function(id){
  const x=fundingRows().find(r=>r.id===id);if(!x)return;window.state.ub96Fund={editId:id,q:'',department:'Wszystkie',selected:x.recipients.map(r=>r.employeeId),amount:x.amount,name:x.name,program:x.program,recurrence:x.recurrence,bookDate:x.date};renderSafe();setTimeout(()=>document.getElementById('ub96FundingComposer')?.scrollIntoView({behavior:'smooth'}),0)
};
window.ub96FundingRepeat=function(id){
  const x=fundingRows().find(r=>r.id===id);if(!x)return;window.state.ub96Fund={editId:'',q:'',department:'Wszystkie',selected:x.recipients.map(r=>r.employeeId),amount:x.amount,name:`${x.name} — ponowienie`,program:x.program,recurrence:x.recurrence,bookDate:today()};renderSafe();setTimeout(()=>document.getElementById('ub96FundingComposer')?.scrollIntoView({behavior:'smooth'}),0)
};
window.ub96FundingSend=function(id){
  const rows=fundingRows(),x=rows.find(r=>r.id===id);if(!x)return;
  x.status='Wysłane do BOK';x.sentAt=new Date().toISOString();saveFunding(rows);
  try{
    state.v27=state.v27||{};state.v27.notifications=Array.isArray(state.v27.notifications)?state.v27.notifications:[];
    state.v27.notifications.unshift({id:'N-'+Date.now(),icon:'💳',title:'Nowe zasilenie klienta',text:`${x.name} · ${x.recipients.length} osób · ${money(x.total)}`,time:'teraz',unread:true,section:'Zasilenia',role:'bok',fundingId:x.id});
    if(typeof persist==='function')persist();
  }catch(e){}
  toastSafe('Wysłano do BOK','Zasilenie zostało przekazane do weryfikacji.');renderSafe()
};
function fundingView(){
  const s=fundState(),allEmp=employees().filter(e=>e.status==='Aktywny'),deps=['Wszystkie',...[...new Set(allEmp.map(e=>e.department))].sort()];
  let visible=allEmp.filter(e=>(s.department==='Wszystkie'||e.department===s.department));const q=String(s.q||'').toLowerCase();if(q)visible=visible.filter(e=>`${e.name} ${e.email} ${e.department}`.toLowerCase().includes(q));
  const selectedSet=new Set(s.selected||[]);
  const drafts=fundingRows();
  return `<div class="page-content ub96-page"><div class="page-head"><div><h1>Budżety i zasilenia</h1><p>Przygotowanie, podgląd, zatwierdzenie i historia zasileń.</p></div></div>
    <section class="ub96-sheet" id="ub96FundingComposer"><div class="ub96-sheet-head"><b>${s.editId?'Edytuj zasilenie':'Nowe zasilenie'}</b><button onclick="ub96FundingReset()">Wyczyść</button></div>
      <div class="ub96-fund-form">
        <label>Nazwa operacji<input value="${esc(s.name)}" oninput="state.ub96Fund.name=this.value"></label>
        <label>Data księgowania<input type="date" value="${s.bookDate}" onchange="ub96FundField('bookDate',this.value)"></label>
        <label>Program<select onchange="ub96FundField('program',this.value)">${['PRG-1041','Budżet benefitowy','Lunch','ZFŚS','Premia'].map(x=>`<option ${s.program===x?'selected':''}>${x}</option>`).join('')}</select></label>
        <label>Kwota / pracownik<input type="number" step=".01" value="${s.amount}" onchange="ub96FundField('amount',this.value)"></label>
        <label>Cykliczność<select onchange="ub96FundField('recurrence',this.value)">${['Jednorazowo','Co miesiąc','Co kwartał','Co rok'].map(x=>`<option ${s.recurrence===x?'selected':''}>${x}</option>`).join('')}</select></label>
      </div>
      <div class="ub96-recipient-tools"><input placeholder="Szukaj pracownika..." value="${esc(s.q)}" oninput="ub96FundField('q',this.value)"><select onchange="ub96FundField('department',this.value)">${deps.map(x=>`<option ${s.department===x?'selected':''}>${x}</option>`).join('')}</select><button onclick="ub96FundSelectVisible(true)">Zaznacz widocznych</button><button onclick="ub96FundSelectVisible(false)">Odznacz widocznych</button><b>${selectedSet.size} osób · ${money(selectedSet.size*num(s.amount))}</b></div>
      <div class="ub96-scroll ub96-people-pick"><table><thead><tr><th></th><th>Pracownik</th><th>Dział</th><th>Status</th><th>Kwota</th></tr></thead><tbody>${visible.map(e=>`<tr><td><input type="checkbox" ${selectedSet.has(e.employeeId)?'checked':''} onchange="ub96FundToggle('${e.employeeId}',this.checked)"></td><td><b>${esc(e.name)}</b><small>${esc(e.email)}</small></td><td>${esc(e.department)}</td><td>${esc(e.status)}</td><td><b>${money(s.amount)}</b></td></tr>`).join('')}</tbody></table></div>
      <div class="ub96-bottom-actions"><button class="secondary-btn" onclick="ub96FundingSaveDraft()">Zapisz szkic</button>${s.editId?`<button class="primary-btn" onclick="ub96FundingSaveDraft();setTimeout(()=>ub96FundingSend('${s.editId}'),0)">Zapisz i wyślij do BOK</button>`:''}</div>
    </section>
    <section class="ub96-sheet"><div class="ub96-sheet-head"><b>Zasilenia</b><span>${drafts.length}</span></div><div class="ub96-scroll"><table><thead><tr><th>Data</th><th>Nazwa</th><th>Program</th><th>Odbiorcy</th><th>Kwota/os.</th><th>Łącznie</th><th>Cykliczność</th><th>Status</th><th>Akcje</th></tr></thead><tbody>${drafts.map(x=>`<tr><td>${x.date}</td><td><b>${esc(x.name)}</b></td><td>${esc(x.program)}</td><td>${x.recipients.length}<small>${[...new Set(x.recipients.map(r=>r.department))].join(', ')}</small></td><td>${money(x.amount)}</td><td><b>${money(x.total)}</b></td><td>${esc(x.recurrence)}</td><td>${esc(x.status)}</td><td><div class="ub96-actions"><button onclick="ub96FundingEdit('${x.id}')">Edytuj</button><button onclick="ub96FundingRepeat('${x.id}')">Ponów</button>${x.status==='Szkic'?`<button onclick="ub96FundingSend('${x.id}')">Wyślij</button>`:''}</div></td></tr>`).join('')||'<tr><td colspan="9">Brak zasileń.</td></tr>'}</tbody></table></div></section>
  </div>`;
}

/* ========= KUDOS ========= */
function kudosAwards(){return store(KUDOS_KEY,[])}
function saveKudosAwards(x){save(KUDOS_KEY,x)}
const baseKudosSubmit=window.ub64SubmitKudos;
window.ub64SubmitKudos=function(event){
  const fd=new FormData(event.currentTarget);
  let personName='',personId=String(fd.get('personId')||'');
  try{const d=engagementLoad(),p=d.orgStructure.employees.find(x=>x.id===personId);personName=p?.name||personId}catch(e){}
  const points=num(fd.get('customPoints'))||num(fd.get('points'));const reason=String(fd.get('reason')||'');
  const ok=typeof baseKudosSubmit==='function'?baseKudosSubmit(event):false;
  if(points>0&&personName){
    const rows=kudosAwards();rows.unshift({id:'KUD-'+Date.now(),recipientId:personId,recipient:personName,from:currentUser(),points,reason,message:String(fd.get('message')||''),date:today(),status:'Przyznane'});saveKudosAwards(rows)
  }
  return ok;
};
function kudosReportView(){
  let ledger=[];try{ledger=engagementLoad().kudosLedger||[]}catch(e){}
  const awards=kudosAwards();
  const rows=[...awards,...ledger.filter(x=>x.type==='sent').map(x=>({id:x.id,recipient:x.to,from:x.from,points:x.points,reason:x.reason,date:x.date,status:x.status||'Przyznane'}))];
  const total=rows.reduce((a,x)=>a+num(x.points),0),recipients=new Set(rows.map(x=>x.recipient)).size;
  return `<div class="ub96-kudos"><div class="ub96-kpis"><article><span>Przyznane Kudos</span><b>${total}</b></article><article><span>Odbiorcy</span><b>${recipients}</b></article><article><span>Osiągnięcia</span><b>${new Set(rows.map(x=>x.reason)).size}</b></article><article><span>Status programu</span><b>Aktywny</b><small>zasady wspólne dla całej organizacji</small></article></div>
    <section class="ub96-sheet"><div class="ub96-sheet-head"><b>Raport Kudos</b><span>Przyznane · komu · za co</span></div><div class="ub96-scroll"><table><thead><tr><th>Data</th><th>Komu</th><th>Od kogo</th><th>Za co</th><th>Kudos</th><th>Status</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${esc(x.date)}</td><td><b>${esc(x.recipient||x.to||'—')}</b></td><td>${esc(x.from||'—')}</td><td>${esc(x.reason||'—')}</td><td><b>${num(x.points)}</b></td><td>${esc(x.status||'Przyznane')}</td></tr>`).join('')||'<tr><td colspan="6">Brak przyznanych Kudos.</td></tr>'}</tbody></table></div></section></div>`;
}
function engagementView96(){
  return `<div class="page-content ub96-page"><div class="page-head"><div><h1>Wellbeing i Kudosy</h1><p>Raport programu doceniania i wyników zaangażowania.</p></div></div>${kudosReportView()}</div>`;
}

