window.ub96GiftCreate=function(){
  const name=prompt('Nazwa akcji / okazji','Upominek świąteczny');if(!name)return;
  const scope=prompt('Odbiorcy: Cała firma / Wybrany dział / Wybrani pracownicy','Cała firma')||'Cała firma';
  const rows=gifts();rows.unshift({id:'GFT-'+Date.now(),name,scope,recipients:scope==='Cała firma'?employees().filter(e=>e.status==='Aktywny').map(e=>e.employeeId):[],options:GIFT_OPTIONS.map(x=>x.id),status:'Wysłany',date:today()});saveGifts(rows);toastSafe('Upominek wysłany','Pracownicy zobaczą wybór bez cen.');renderSafe()
};
function giftsHrView(){
  const rows=gifts();
  return `<div class="page-content ub96-page"><div class="page-head"><div><h1>Odbierz upominek</h1><p>Wyślij upominek jednej osobie, grupie lub całej firmie.</p></div><button class="primary-btn" onclick="ub96GiftCreate()">＋ Wyślij upominek</button></div>
    <section class="ub96-sheet"><div class="ub96-sheet-head"><b>Dostępne opcje</b><span>Ceny widoczne tylko dla HR i Up Bonus Admin</span></div><div class="ub96-gift-options">${GIFT_OPTIONS.map(x=>`<article><span>🎁</span><b>${esc(x.name)}</b><small>${money(x.price)}</small></article>`).join('')}</div></section>
    <section class="ub96-sheet"><div class="ub96-scroll"><table><thead><tr><th>Data</th><th>Akcja</th><th>Odbiorcy</th><th>Liczba opcji</th><th>Status</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${x.date}</td><td><b>${esc(x.name)}</b></td><td>${esc(x.scope)}${x.recipients?.length?`<small>${x.recipients.length} osób</small>`:''}</td><td>${x.options.length}</td><td>${esc(x.status)}</td></tr>`).join('')||'<tr><td colspan="5">Brak kampanii upominkowych.</td></tr>'}</tbody></table></div></section></div>`;
}
function giftsEmployeeView(){
  const name=currentUser(),emp=employees().find(e=>e.name===name);
  const rows=gifts().filter(x=>x.status==='Wysłany'&&(x.scope==='Cała firma'||(emp&&x.recipients.includes(emp.employeeId))));
  return `<div class="employee-dashboard ub13-page"><section class="ub13-hero"><div><span class="ub13-kicker">🎁 ODBIERZ UPOMINEK</span><h1>Wybierz prezent dla siebie</h1><p>Cena nie jest wyświetlana pracownikowi.</p></div></section>${rows.map(g=>`<section class="ub13-section"><div class="ub13-section-head"><div><h2>${esc(g.name)}</h2><span>Wybierz jedną z dostępnych opcji</span></div></div><div class="ub96-employee-gifts">${GIFT_OPTIONS.filter(o=>g.options.includes(o.id)).map(o=>`<button onclick="ub96ChooseGift('${g.id}','${o.id}')"><span>🎁</span><b>${esc(o.name)}</b><em>Wybieram</em></button>`).join('')}</div></section>`).join('')||'<section class="ub13-section"><div class="ub96-empty">Nie masz obecnie upominku do odebrania.</div></section>'}</div>`;
}
window.ub96ChooseGift=function(giftId,optId){
  const rows=gifts(),g=rows.find(x=>x.id===giftId);if(!g)return;g.choices=g.choices||{};g.choices[currentUser()]=optId;saveGifts(rows);toastSafe('Wybór zapisany','HR otrzyma informację o wyborze, bez zmiany wartości prezentu.');renderSafe()
};

/* ========= EMPLOYEE KUDOS RECEIVED ========= */
function appendReceivedKudos(html){
  const name=currentUser(),rows=kudosAwards().filter(x=>x.recipient===name);
  if(!rows.length)return html;
  const extra=`<section class="ub13-section ub96-employee-kudos"><div class="ub13-section-head"><div><h2>Otrzymane Kudos</h2><span>${rows.reduce((a,x)=>a+num(x.points),0)} pkt</span></div></div><div class="ub96-scroll"><table><thead><tr><th>Data</th><th>Od</th><th>Za co</th><th>Kudos</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${x.date}</td><td>${esc(x.from)}</td><td>${esc(x.reason)}</td><td><b>+${x.points}</b></td></tr>`).join('')}</tbody></table></div></section>`;
  return html.replace(/<\/div>\s*$/,'')+extra+'</div>';
}

/* ========= ROUTE OVERRIDES ========= */
const prevRender=window.renderSection;
window.renderSection=function(){
  const s=window.state||{};
  if(s.role==='hr'){
    if(['Pracownicy i grupy','Pracownicy','Lista pracowników','Import pracowników'].includes(s.section))return employeesView();
    if(['Benefity HR','Platformy i programy'].includes(s.section))return benefitsView96();
    if(s.section==='Budżety i finansowanie')return fundingView();
    if(s.section==='Zaangażowanie')return engagementView96();
    if(s.section==='Komunikacja')return communicationView96();
    if(s.section==='Raporty HR')return reportsView96();
    if(s.section==='Ustawienia HR')return settingsView96();
    if(s.section==='Odbierz upominek')return giftsHrView();
  }
  if(s.role==='employee'){
    if(s.section==='Upominki')return giftsEmployeeView();
    if(s.section==='Punkty i nagrody'){
      const base=prevRender.apply(this,arguments);
      return appendReceivedKudos(base);
    }
  }
  return prevRender.apply(this,arguments);
};

