/* =========================
   BOK — resolved cases view
   ========================= */
function resolvedCasesView(prevRender){
  const old=state.section;
  state.section='Wszystkie zgłoszenia';
  const html=prevRender();
  state.section=old;

  const holder=document.createElement('div');
  holder.innerHTML=html;
  const h1=holder.querySelector('h1');
  const desc=holder.querySelector('.page-head p');
  if(h1)h1.textContent='Rozpatrzone';
  if(desc)desc.textContent='Zamknięte i rozpatrzone sprawy BOK.';

  const rows=[...holder.querySelectorAll('tbody tr')];
  rows.forEach(tr=>{
    const txt=tr.textContent.toLowerCase();
    if(!/(zamk|rozpatrz|uznan|odrzu|zwrócon|zrealiz)/i.test(txt))tr.remove();
  });

  const count=holder.querySelector('.ub18-section-count');
  if(count)count.textContent=`${holder.querySelectorAll('tbody tr').length} spraw`;

  return holder.innerHTML;
}

/* =========================
   BOK — clients & programs
   ========================= */
function clientProgramRows(){
  const batches=funding();
  const emps=employees();
  const clientNames=[
    'Open Benefit 3.0',
    'Erste Benefits',
    'Up Bonus Shared'
  ];
  try{
    const fromState=state?.v25?.clients||state?.clients||[];
    fromState.forEach(c=>clientNames.push(c.name||c.clientName||c.id));
  }catch(e){}
  const unique=[...new Set(clientNames.filter(Boolean))];

  return unique.map((name,i)=>{
    const clientBatches=batches.filter(x=>String(x.client||'').includes(name)||i===0);
    const programs=[...new Set(clientBatches.map(x=>x.program).filter(Boolean))];
    return {
      id:`CL-${i+1}`,
      name,
      programs:programs.length?programs:['Budżet benefitowy','ZFŚS'],
      employees:i===0?emps.length:Math.max(50,Math.floor(emps.length/2)),
      topups:clientBatches.length,
      topupTotal:clientBatches.reduce((a,x)=>a+num(x.total),0),
      status:'Aktywny'
    };
  });
}
window.ub97ClientQ=function(v){bokUi().clientQ=v;rerender()};
function bokClientsProgramsView(){
  const q=String(bokUi().clientQ||'').toLowerCase();
  let rows=clientProgramRows();
  if(q)rows=rows.filter(x=>`${x.name} ${x.programs.join(' ')}`.toLowerCase().includes(q));
  return `<div class="page-content ub97-page">
    <div class="page-head"><div><h1>Klienci i programy</h1><p>Programy klienta, użytkownicy i historia zasileń w jednym widoku.</p></div></div>
    <div class="ub97-toolbar"><input value="${esc(bokUi().clientQ||'')}" placeholder="Szukaj klienta lub programu..." oninput="ub97ClientQ(this.value)"></div>
    <section class="ub97-sheet"><div class="ub97-scroll"><table><thead><tr><th>Klient</th><th>Programy</th><th>Użytkownicy</th><th>Zasilenia</th><th>Łączna wartość</th><th>Status</th></tr></thead><tbody>
    ${rows.map(x=>`<tr><td><b>${esc(x.name)}</b><small>${x.id}</small></td><td>${x.programs.map(p=>`<span class="ub97-pill">${esc(p)}</span>`).join(' ')}</td><td>${x.employees}</td><td>${x.topups}</td><td><b>${money(x.topupTotal)}</b></td><td><span class="ub97-status ok">${x.status}</span></td></tr>`).join('')}
    </tbody></table></div></section>
  </div>`;
}

