function completion(){
  const c=cfg();
  const keys=['controllerMatrix','processorAgreements','dpiaMaster','dpiaZfss','dpiaWellbeing','limitedNetworkMemo','ksefIntegration','accessibilityAA','mfaPrivileged','immutableAudit','annualZfssReview','marketingConsentGranular'];
  const done=keys.filter(k=>c[k]).length;
  return Math.round(done/keys.length*100)
}

