    <section class="ub98-sheet"><div class="ub98-sheet-head"><b>Subprocesorzy</b><button onclick="ub98AddSub()">＋ Dodaj</button></div><div class="ub98-scroll"><table><thead><tr><th>Dostawca</th><th>Cel</th><th>Region</th><th>DPA</th><th>Status</th></tr></thead><tbody>
      ${subprocessors().map(x=>`<tr><td><b>${x.name}</b></td><td>${x.purpose}</td><td>${x.region}</td><td>${x.dpa}</td><td>${x.status}</td></tr>`).join('')}
    </tbody></table></div></section>
