/* ===== IMAGE: preserve source, adapt display with cover ===== */
window.ub88OfferImage=function(input){
  const file=input.files?.[0];
  if(!file)return;

  if(!/^image\/(png|jpeg|webp)$/i.test(file.type)){
    input.value='';
    toastSafe('Grafika','Wybierz PNG, JPG lub WebP.');
    return;
  }
  if(file.size>12*1024*1024){
    input.value='';
    toastSafe('Grafika','Maksymalny rozmiar pliku źródłowego to 12 MB.');
    return;
  }

  const reader=new FileReader();
  reader.onerror=()=>toastSafe('Grafika','Nie udało się odczytać pliku.');
  reader.onload=()=>{
    const data=String(reader.result||'');
    const modal=input.closest('.ub88-offer-modal');
    const hidden=modal?.querySelector('[name="image"]');
    const preview=modal?.querySelector('.ub88-image-preview');
    if(hidden)hidden.value=data;
    if(preview)preview.innerHTML=`<img class="ub100-cover-image" src="${data}" alt="Podgląd grafiki">`;
    toastSafe('Grafika wgrana','Oryginał został zachowany, a widok automatycznie dopasowany do proporcji karty.');
  };
  reader.readAsDataURL(file);
};

