window.ub103SaveCompanyRequest=function(){
  const f=document.getElementById('ub103CompanyForm');if(!f)return;const fd=new FormData(f),o=COMPANY_OFFERS.find(x=>x.id===fd.get('id'));if(!o)return;
  const r=companyRequests();r.unshift({id:'CP-'+Date.now(),date:today(),name:o.name,qty:String(fd.get('qty')||''),note:String(fd.get('note')||''),status:'Wysłane'});save(COMPANY_KEY,r);
  document.querySelector('.ub103-modal-backdrop')?.remove();toastSafe('Zapytanie wysłane',o.name);rerender();
};
