function importantPopup(){
  if(state?.role!=='employee')return;
  const key='christmas-gift-2026';
  const seen=store(POPUP_KEY,{});
  if(seen[key])return;
  if(document.querySelector('.ub103-important-backdrop'))return;

  const el=document.createElement('div');
  el.className='ub103-important-backdrop';
  el.innerHTML=`<div class="ub103-important-popup">
    <button class="ub103-important-close">×</button>
    <span class="ub103-important-icon">🎄</span>
    <small>WAŻNE DLA CIEBIE</small>
    <h2>Odbierz prezent z okazji Bożego Narodzenia</h2>
    <p>Twój pracodawca przygotował dla Ciebie świąteczny upominek. Wybierz prezent w platformie.</p>
    <div><button class="secondary-btn ub103-later">Później</button><button class="primary-btn ub103-open-gift">Odbierz prezent</button></div>
  </div>`;
  const close=()=>{seen[key]=true;save(POPUP_KEY,seen);el.remove()};
  el.querySelector('.ub103-important-close').onclick=close;
  el.querySelector('.ub103-later').onclick=close;
  el.querySelector('.ub103-open-gift').onclick=()=>{seen[key]=true;save(POPUP_KEY,seen);el.remove();try{selectSection('Upominki')}catch(e){}};
  document.body.appendChild(el);
}

