function walletView(){
  const ws=wallets(),rows=txRows();
  const sourceRows=[
    {name:'E-konto',balance:180,type:'Środki uniwersalne',icon:'💳',expiry:'Ważne bezterminowo',query:'',cat:'Karty podarunkowe'},
    {name:'Karta premiowa',balance:120,type:'Nagroda / premia',icon:'🎁',expiry:'Ważne bezterminowo',query:'',cat:'Karty podarunkowe'},
    {name:'Karta Lunch',balance:220,type:'Posiłki i gastronomia',icon:'🍽',expiry:'⚠ Wygasa za 12 dni',query:'jedzenie',cat:'Wszystkie'},
    {name:'Karta Kultura',balance:80,type:'Kultura i rozrywka',icon:'🎬',expiry:'Ważne do 31.12.2026',query:'kino kultura',cat:'Bilety'}
  ];
  const history=(rows||[]).map((x,i)=>({date:x.date||['04.08.2026','31.07.2026','20.07.2026','15.07.2026'][i%4],title:x.title||x.name||'Operacja',source:x.source||x.payment||(/kino|multikino|kultur/i.test(x.title||x.name||'')?'Karta Kultura':'E-konto'),status:x.status||(/refund|zwrot/i.test(x.type||'')?'Zwrot':x.amount>0?'Zasilenie':'Zrealizowano'),amount:Number(x.amount||0),type:String(x.type||'') }));
  if(!history.length)history.push({date:'04.08.2026',title:'Allegro Gift Card 100 zł',source:'E-konto',status:'Zrealizowano',amount:-100,type:'purchase'},{date:'31.07.2026',title:'Multikino – 2 bilety',source:'Karta Kultura',status:'Zrealizowano',amount:-50,type:'purchase'});
  const f=state.ub301WalletFilter||'Wszystkie',q=String(state.ub301WalletQ||'').toLowerCase();
  const filtered=history.filter(x=>{
    const matchQ=!q||`${x.title} ${x.source} ${x.status}`.toLowerCase().includes(q);
    const matchF=f==='Wszystkie'||(f==='Zakupy'&&x.amount<0&&!/zwrot|refund/i.test(x.type))||(f==='Zasilenia'&&x.amount>0&&!/zwrot|refund/i.test(x.type))||(f==='Zwroty'&&/zwrot|refund/i.test(`${x.type} ${x.status}`))||(f==='Wygasłe'&&/wygas/i.test(x.status));
    return matchQ&&matchF;
  });
  const historyExpanded=!!state.ub301WalletExpanded;
  const visibleHistory=historyExpanded?filtered:filtered.slice(0,5);
  const statusClass=v=>/zwrot/i.test(v)?'refund':/zasil/i.test(v)?'funding':/anul/i.test(v)?'cancel':/wygas/i.test(v)?'expired':'done';
  return `<div class="page-content ub301-wallet">
    <div class="ub301-wallet-head"><div><h1>Moje środki</h1><p>Sprawdź dostępne salda, terminy ważności i historię wykorzystania.</p></div><button onclick="selectSection('Katalog benefitów')">Zobacz benefity →</button></div>
    <section class="ub301-wallet-summary"><article class="main"><span>Dostępne środki</span><b>600 zł</b><small>4 aktywne źródła</small></article><article class="warning"><span>⚠ Wygasa wkrótce</span><b>150 zł</b><small>Najbliższy termin: 12 dni</small></article><article class="saving"><span>Twoje oszczędności</span><b>1 840 zł</b><small>w tym roku</small><em>+214,50 zł w ostatnich 30 dniach</em></article></section>
    <section class="ub301-wallet-section"><div class="ub301-section-head"><div><span>ŹRÓDŁA FINANSOWANIA</span><h2>Twoje salda</h2><p>Każde źródło może mieć własne zasady wykorzystania.</p></div></div><div class="ub301-balance-grid">${sourceRows.map((x,i)=>`<article><div class="ub301-balance-top"><i>${x.icon}</i><div><b>${x.name}</b><small>${x.type}</small></div></div><strong>${x.balance} zł <small>dostępne</small></strong><span class="ub301-balance-expiry ${/⚠/.test(x.expiry)?'warn':''}">${x.expiry}</span><div class="ub301-progress"><i style="width:${[65,45,72,52][i]}%"></i></div><button onclick="state.empCatalog=state.empCatalog||{};state.empCatalog.query='${x.query}';state.empCatalog.category='${x.cat}';selectSection('Katalog benefitów')">Zobacz gdzie wykorzystać →</button></article>`).join('')}</div></section>
    <section class="ub301-wallet-section"><div class="ub301-section-head"><div><span>KATEGORIE</span><h2>Na co możesz wykorzystać środki</h2></div></div><div class="ub301-use-grid"><button onclick="state.empCatalog.query='zakupy';selectSection('Katalog benefitów')">🛍 <span>Zakupy</span></button><button onclick="state.empCatalog.query='kino kultura';selectSection('Katalog benefitów')">🎬 <span>Kino i kultura</span></button><button onclick="state.empCatalog.query='jedzenie';selectSection('Katalog benefitów')">🍽 <span>Jedzenie</span></button><button onclick="selectSection('Wellbeing')">🌿 <span>Wellbeing</span></button><button onclick="state.empCatalog.query='podróże';selectSection('Katalog benefitów')">✈ <span>Podróże</span></button><button onclick="state.empCatalog.query='sport';selectSection('Katalog benefitów')">🏃 <span>Sport</span></button></div></section>
    <section class="ub301-wallet-lower"><article class="ub301-wallet-section ub301-history"><div class="ub301-history-head"><div><span>OSTATNIE OPERACJE</span><h2>Historia środków</h2><p>Zakupy, zasilenia, zwroty i wykorzystanie środków.</p></div><button>Eksportuj</button></div><div class="ub301-history-tools"><div>${['Wszystkie','Zakupy','Zasilenia','Zwroty','Wygasłe'].map(x=>`<button class="${f===x?'active':''}" onclick="state.ub301WalletFilter='${x}';render()">${x}</button>`).join('')}</div><label>⌕ <input value="${esc(state.ub301WalletQ||'')}" placeholder="Szukaj w historii…" oninput="state.ub301WalletQ=this.value;render()"></label><span><input type="date"> – <input type="date"></span></div><div class="ub301-history-table"><table><thead><tr><th>Data</th><th>Operacja</th><th>Źródło środków</th><th>Status</th><th>Kwota</th></tr></thead><tbody>${visibleHistory.map(x=>`<tr><td data-label="Data">${esc(x.date)}</td><td data-label="Operacja"><b>${esc(x.title)}</b></td><td data-label="Źródło">${esc(x.source)}</td><td data-label="Status"><span class="ub301-status ${statusClass(x.status)}">${esc(x.status)}</span></td><td data-label="Kwota" class="${x.amount>0?'plus':'minus'}">${x.amount>0?'+':''}${money(x.amount)}</td></tr>`).join('')}</tbody></table></div>${filtered.length>5?`<button class="ub302-history-more" onclick="state.ub301WalletExpanded=!state.ub301WalletExpanded;render()">${historyExpanded?'Pokaż mniej':'Pokaż całą historię ('+filtered.length+')'} →</button>`:''}</article><aside class="ub301-savings"><span>Twoje oszczędności w tym roku</span><strong>1 840 zł</strong><p>Realna wartość korzyści wykorzystanych w programie.</p><div><span>Rabaty <b>620 zł</b></span><span>Benefity finansowane przez firmę <b>870 zł</b></span><span>Promocje i kody <b>350 zł</b></span></div></aside></section>
  </div>`;
}
window.ub301WalletView=walletView;


