/* ===================== AI CONCIERGE ===================== */
window.ub105OpenAI=function(q=''){
  document.querySelector('.ub105-ai-backdrop')?.remove();
  const el=document.createElement('div');el.className='ub105-ai-backdrop';
  el.innerHTML=`<div class="ub105-ai-modal"><div class="ub105-ai-head"><div><span>✨ AI CONCIERGE</span><h2>Czego dziś potrzebujesz?</h2><p>Napisz normalnie — dopasuję benefit, usługę albo sposób wykorzystania środków.</p></div><button data-close>×</button></div>
    <div id="ub105AIConversation" class="ub105-ai-conversation">${q?`<div class="user">${esc(q)}</div>`:''}<div class="assistant">Mam dostęp do Twojego portfela i katalogu platformy. Mogę pomóc np. z prezentem, podróżą, sportem, rodziną albo wykorzystaniem środków.</div></div>
    <div class="ub105-ai-suggestions"><button onclick="ub105AskAI('Mam 300 zł. Na co najlepiej je wykorzystać?')">Mam 300 zł</button><button onclick="ub105AskAI('Znajdź prezent dla dziecka do 200 zł')">Prezent do 200 zł</button><button onclick="ub105AskAI('Chcę wyjechać z rodziną')">Wyjazd rodzinny</button></div>
    <div class="ub105-ai-compose"><input id="ub105AIInput" value="${esc(q)}" placeholder="Napisz, czego szukasz..."><button onclick="ub105AskAI()">Wyślij</button></div></div>`;
  el.querySelector('[data-close]').onclick=()=>el.remove();
  document.body.appendChild(el);
  if(q)setTimeout(()=>ub105AskAI(q),100);
};
window.ub105AIQuick=function(){
  const q=document.getElementById('ub105AIQuick')?.value?.trim()||'';ub105OpenAI(q);
};
window.ub105AskAI=function(q){
  const input=document.getElementById('ub105AIInput');
  const text=String(q||input?.value||'').trim();if(!text)return;
  if(input)input.value='';
  const c=document.getElementById('ub105AIConversation');if(!c)return;
  c.insertAdjacentHTML('beforeend',`<div class="user">${esc(text)}</div>`);
  let answer='Najlepiej zacząć od 3 dopasowanych propozycji, zamiast przeglądać cały katalog.';
  let buttons=`<button onclick="document.querySelector('.ub105-ai-backdrop')?.remove();selectSection('Marketplace usług')">Pokaż 3 propozycje</button>`;
  const low=text.toLowerCase();
  if(/300|środk|saldo|wykorzyst/.test(low)){answer=`Masz ${money(totalFunds())} dostępnych środków. Najpierw wykorzystałbym źródła, które wygasają najszybciej, a potem dobrał zakup do Twojego celu.`;buttons=`<button onclick="document.querySelector('.ub105-ai-backdrop')?.remove();selectSection('Portfel i środki')">Otwórz Benefit Wallet</button><button onclick="document.querySelector('.ub105-ai-backdrop')?.remove();selectSection('Marketplace usług')">Zobacz propozycje</button>`}
  if(/dziec|rodzin|prezent/.test(low)){answer='Wybrałem kierunek rodzinny: atrakcja, karta podarunkowa albo usługa edukacyjna. Wszystkie mieszczą się w typowym budżecie do 200 zł.';buttons=`<button onclick="document.querySelector('.ub105-ai-backdrop')?.remove();selectSection('Marketplace usług')">Rodzina — 3 propozycje</button>`}
  if(/wyjazd|podróż|hotel|wakac/.test(low)){answer='Mogę połączyć budżet, rabaty i usługi podróżne. Zacznijmy od ofert podróżnych dostępnych w marketplace.';buttons=`<button onclick="document.querySelector('.ub105-ai-backdrop')?.remove();selectSection('Marketplace usług')">Podróże — sprawdź</button>`}
  c.insertAdjacentHTML('beforeend',`<div class="assistant">${esc(answer)}<div class="actions">${buttons}</div></div>`);
  c.scrollTop=c.scrollHeight;
};

/* ===================== MICROSOFT 365 / TEAMS ===================== */
function msState(){
  const d=store(MS_KEY,null);
  if(d&&typeof d==='object')return d;
  const init={
    tenantId:'',
    connected:false,
    teams:false,
    sso:false,
    outlook:false,
    sharepoint:false,
    notifications:true,
    target:'Ogólny',
    lastSync:'',
    events:[]
  };save(MS_KEY,init);return init;
}
function saveMs(patch){
  const x={...msState(),...patch};save(MS_KEY,x);return x;
}
window.ub105MicrosoftField=function(k,v){saveMs({[k]:v});redraw()};
window.ub105MicrosoftConnect=function(){
  const x=msState();
  if(!x.tenantId){toastSafe('Microsoft 365','Wpisz Tenant ID / nazwę tenant-a do konfiguracji prototypu.');return}
  saveMs({connected:true,sso:true,lastSync:new Date().toLocaleString('pl-PL')});
  toastSafe('Microsoft 365','Konfiguracja połączenia zapisana w prototypie.');redraw();
};
window.ub105MicrosoftDisconnect=function(){saveMs({connected:false,teams:false,sso:false,outlook:false,sharepoint:false});redraw()};
window.ub105TeamsTest=function(){
  const x=msState();
  if(!x.connected||!x.teams){toastSafe('Teams','Najpierw połącz Microsoft 365 i włącz Teams.');return}
  const events=[...(x.events||[])];events.unshift({at:new Date().toLocaleString('pl-PL'),type:'Teams',text:'Test: Masz nową rzecz do sprawdzenia w Up Bonus → deep link do działania'});
  saveMs({events:events.slice(0,10),lastSync:new Date().toLocaleString('pl-PL')});
  toastSafe('Teams','Testowe powiadomienie wysłane w prototypie.');redraw();
};
function microsoftView(){
  const x=msState();
  return `<div class="page-content ub105-page">
    <div class="page-head"><div><h1>Microsoft 365 i Teams</h1><p>Up Bonus jest centrum, a Teams i Microsoft 365 są kanałami dotarcia, logowania i działania.</p></div><span class="ub105-ms-status ${x.connected?'ok':'off'}">${x.connected?'● Połączono':'○ Niepołączono'}</span></div>

    <section class="ub105-ms-setup">
      <div class="ub105-ms-brand"><span>▦</span><div><b>Microsoft 365</b><small>Entra ID · Microsoft Graph · Teams · Outlook</small></div></div>
      <div class="ub105-ms-form"><label>Tenant / Tenant ID<input value="${esc(x.tenantId)}" placeholder="contoso.onmicrosoft.com / Tenant ID" onchange="ub105MicrosoftField('tenantId',this.value)"></label><label>Kanał Teams<select onchange="ub105MicrosoftField('target',this.value)"><option ${x.target==='Ogólny'?'selected':''}>Ogólny</option><option ${x.target==='HR'?'selected':''}>HR</option><option ${x.target==='Benefity'?'selected':''}>Benefity</option></select></label></div>
      <div class="ub105-ms-actions">${x.connected?'<button class="secondary-btn" onclick="ub105MicrosoftDisconnect()">Rozłącz konfigurację</button>':'<button class="primary-btn" onclick="ub105MicrosoftConnect()">Połącz Microsoft 365</button>'}</div>
    </section>

    <section class="ub105-integration-grid">
      ${[
        ['sso','🔐','Microsoft Entra ID / SSO','Logowanie firmowym kontem Microsoft.'],
        ['teams','💬','Teams','Powiadomienia z deep-linkiem bezpośrednio do konkretnej akcji.'],
        ['outlook','📅','Outlook / Calendar','Wydarzenia HR i firmowe w kalendarzu pracownika.'],
        ['sharepoint','📁','SharePoint / OneDrive','Dokumenty i materiały firmowe bez dublowania repozytorium.']
      ].map(([k,ic,n,d])=>`<article><span>${ic}</span><div><b>${n}</b><p>${d}</p></div><label class="ub105-switch"><input type="checkbox" ${x[k]?'checked':''} ${!x.connected&&k!=='sso'?'disabled':''} onchange="ub105MicrosoftField('${k}',this.checked)"><i></i></label></article>`).join('')}
    </section>

    <section class="ub105-ms-flow">
      <div><b>Przykładowa ścieżka</b><p>HR publikuje akcję w Up Bonus → Teams pokazuje krótką informację → klik prowadzi bezpośrednio do prezentu, oferty, wydarzenia albo środków.</p></div>
      <button class="primary-btn" onclick="ub105TeamsTest()">Wyślij test do Teams</button>
    </section>

    <section class="ub105-sheet"><div class="ub105-sheet-head"><div><b>Log integracji</b><small>Ostatnia synchronizacja: ${esc(x.lastSync||'—')}</small></div></div><div class="ub105-table-scroll"><table><thead><tr><th>Czas</th><th>Kanał</th><th>Zdarzenie</th></tr></thead><tbody>${(x.events||[]).map(e=>`<tr><td>${esc(e.at)}</td><td>${esc(e.type)}</td><td>${esc(e.text)}</td></tr>`).join('')||'<tr><td colspan="3">Brak zdarzeń.</td></tr>'}</tbody></table></div></section>

    <section class="ub105-tech-note"><b>Zakres produkcyjny</b><span>Microsoft Entra ID / OIDC SSO</span><span>Microsoft Graph</span><span>Teams deep links / notification app</span><span>Outlook Calendar</span><span>SharePoint / OneDrive links</span><small>W tym prototypie konfigurujemy UX i przepływy. Produkcyjne połączenie wymaga rejestracji aplikacji w Entra ID, zgód administratora i backendu do obsługi Graph/webhooków.</small></section>
  </div>`;
}

