function ub123BenefitHubState(){
  state.ub123BenefitHub=state.ub123BenefitHub||{filter:'all'};
  return state.ub123BenefitHub;
}
window.ub123SetBenefitHubFilter=function(filter){
  ub123BenefitHubState().filter=filter||'all';
  render();
};
function ub123IconForBenefit(x,i){
  const text=`${x.name||''} ${x.category||''} ${x.type||''} ${x.partner||''}`.toLowerCase();
  if(/podró|hotel|lot|travel/.test(text)) return '✈️';
  if(/sport|siłown|fitness|decathlon/.test(text)) return '🏃';
  if(/wellbeing|well|masa|psycholog|joga/.test(text)) return '🌿';
  if(/rodzin|dziec|prezent|upomink/.test(text)) return '👨‍👩‍👧';
  if(/zdrow|uroda|rossmann|apte/.test(text)) return '🏥';
  if(/eduk|kurs|szkol/.test(text)) return '🎓';
  if(/kino|rozryw|empik|multikino/.test(text)) return '🎬';
  if(/dom|wnętrz/.test(text)) return '🏠';
  if(/moto|auta|samoch/.test(text)) return '🚗';
  if(/gastro|restaur|jedze|lunch/.test(text)) return '🍽️';
  if(/finans|bank|karta|voucher|gift/.test(text)) return '💳';
  return ['🎁','🛍️','🏃','🌿','🎬','✈️','🍽️','🎓'][i%8];
}
function ub123FilteredEmployeeBenefits(){
  const rows=ub121AllEmployeeBenefits();
  const f=ub123BenefitHubState().filter;
  if(f==='favorites') return rows.filter((_,i)=>i<4);
  if(f==='recent') return [...rows].slice(0,6);
  if(f==='popular') return [...rows].sort((a,b)=>String(a.partner||'').localeCompare(String(b.partner||''),'pl')).slice(0,8);
  return rows;
}
function ub123BenefitsGrid(rows){
  return `<div class="ub123-grid ub123-grid-direct">
      ${rows.map((x,i)=>`<article>
        <div class="ub123-top"><span class="ub123-icon">${ub123IconForBenefit(x,i)}</span><small>${esc(x.category||x.type||'Benefit')}</small></div>
        <h3>${esc(x.name||'Benefit')}</h3>
        <p>${esc(x.partner||'Up Bonus')}</p>
        <div class="ub123-meta"><span>${esc(x.type||'Oferta')}</span>${x.price?`<b>${money(x.price)}</b>`:''}</div>
        <button onclick="selectSection('Katalog benefitów')">Zobacz benefit →</button>
      </article>`).join('')||'<div class="ub123-empty">Brak benefitów do wyświetlenia.</div>'}
    </div>`;
}

