window.ub127CreateBatch=function(){
  const eligible=declarations127().filter(x=>x.status==='Zatwierdzone');
  if(!eligible.length)return;
  const byTransfer={};
  eligible.forEach(x=>{const k=`${x.provider}|${x.transfer}`;(byTransfer[k]=byTransfer[k]||[]).push(x)});
  const bs=batches127();
  Object.entries(byTransfer).forEach(([k,rows])=>{
    const [provider,transfer]=k.split('|'),id='BAT-'+Date.now()+'-'+Math.floor(Math.random()*999);
    bs.unshift({id,provider,transfer,createdAt:now127(),status:'Do przekazania',declarationIds:rows.map(x=>x.id)});
  });
  tsave127('batches',bs);addAudit127('BATCH',`BOK utworzył ${Object.keys(byTransfer).length} paczek do operatorów.`);render();
};
window.ub127MarkTransferred=function(batchId){
  const bs=batches127(),b=bs.find(x=>x.id===batchId);if(!b)return;
  b.status='Przekazano';b.transferredAt=now127();tsave127('batches',bs);
  const ds=declarations127();ds.forEach(d=>{if(b.declarationIds.includes(d.id)&&d.status==='Zatwierdzone'){d.status='Przekazane operatorowi';d.updatedAt=now127()}});
  tsave127('declarations',ds);addAudit127(batchId,`Przekazano paczkę do ${b.provider}.`);render();
};
window.ub127MarkActive=function(id){
  const ds=declarations127(),i=ds.findIndex(x=>x.id===id);if(i<0)return;
  ds[i].status='Aktywne';ds[i].activatedAt=now127();ds[i].updatedAt=now127();tsave127('declarations',ds);addAudit127(id,'BOK oznaczył abonament jako aktywny.');render();
};
window.ub127BatchCsv=function(id){
  const b=batches127().find(x=>x.id===id);if(!b)return;
  const rows=declarations127().filter(x=>b.declarationIds.includes(x.id));
  exportCsv127(rows,`${b.provider.replace(/\W+/g,'_')}_${today127()}.csv`);
};

