const t130=()=>String((typeof activeClientId==='function'&&activeClientId())||state?.v47?.currentClientId||state?.clientId||'TEN-001');
const u130=()=>({id:String(state?.user?.employeeId||state?.user?.id||state?.user?.email||'EMP-001'),name:String(state?.user?.name||'Małgorzata Bartkiewicz'),email:String(state?.user?.email||'malgorzata.bartkiewicz@upbonus.pl')});
