function reg132(){
  state.ub132Registration = state.ub132Registration || {
    step:1,firstName:'',lastName:'',email:'',email2:'',phone:'',
    account:'',nap:'',password:'',marketing:false
  };
  return state.ub132Registration;
}
window.ub132RegisterBack=function(){
  const r=reg132();
  if(r.step<=1){ state.authView='login'; render(); return; }
  r.step--; render();
};
window.ub132RegisterNext=function(){
  const r=reg132();
  if(r.step===1){
    r.firstName=(document.getElementById('ub132RegFirst')?.value||'').trim();
    r.lastName=(document.getElementById('ub132RegLast')?.value||'').trim();
    r.email=(document.getElementById('ub132RegEmail')?.value||'').trim();
    r.email2=(document.getElementById('ub132RegEmail2')?.value||'').trim();
    const terms=!!document.getElementById('ub132RegTerms')?.checked;
    const privacy=!!document.getElementById('ub132RegPrivacy')?.checked;
    r.marketing=!!document.getElementById('ub132RegMarketing')?.checked;
    if(!r.firstName||!r.lastName||!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(r.email)||r.email!==r.email2){
      toast?.('Sprawdź dane','Uzupełnij imię, nazwisko i dwa identyczne adresy e-mail.'); return;
    }
    if(!terms||!privacy){ toast?.('RODO i regulamin','Potwierdź wymagane oświadczenia.'); return; }
    r.step=2; render(); return;
  }
  if(r.step===2){
    r.account=(document.getElementById('ub132RegAccount')?.value||'').trim();
    r.nap=(document.getElementById('ub132RegNap')?.value||'').trim();
    r.phone=(document.getElementById('ub132RegPhone')?.value||'').trim();
    if(r.account.replace(/\D/g,'').length<8 || r.nap.length<3){
      toast?.('Aktywacja konta','Podaj numer e-konta i NAP.'); return;
    }
    r.step=3; render(); return;
  }
  if(r.step===3){
    const p1=document.getElementById('ub132RegPass')?.value||'';
    const p2=document.getElementById('ub132RegPass2')?.value||'';
    if(p1.length<8||p1!==p2){ toast?.('Hasło','Hasło musi mieć minimum 8 znaków i oba pola muszą być identyczne.'); return; }
    r.password=p1;
    state.user={...state.user,name:`${r.firstName} ${r.lastName}`,email:r.email,phone:r.phone||state.user?.phone||''};
    state.registration={...(state.registration||{}),contact:r.email,firstName:r.firstName,lastName:r.lastName,complete:true};
    try{ typeof persist==='function'&&persist(); }catch(e){}
    r.step=4; render();
  }
};
window.ub132RegistrationDone=function(){ state.authView='login'; state.ub132Registration=null; render(); };

