/* ==========================================================
   Calendar UX v132 — compact weekly agenda
========================================================== */
function rd132(k,d){try{return JSON.parse(localStorage.getItem(k)||'null')??d}catch(e){return d}}
function monday132(d){const x=new Date(d);const n=(x.getDay()+6)%7;x.setDate(x.getDate()-n);x.setHours(0,0,0,0);return x}
function add132(d,n){const x=new Date(d);x.setDate(x.getDate()+n);return x}
function iso132(d){return d.toISOString().slice(0,10)}
function fmt132(d,opt){return new Intl.DateTimeFormat('pl-PL',opt).format(d)}
function news132(){
  const a=rd132('upbonus.hr.news.v117',[]),b=rd132('upbonus.hr.comms.v129',[]);
  const rows=[...a.map(x=>({id:x.id,title:x.title,type:x.type||'Aktualność',body:x.body||x.description||'',date:x.dateFrom||x.date||x.publishDate||iso132(new Date())})),...b.map(x=>({id:x.id,title:x.title,type:x.type||'HR',body:x.body||'',date:x.publishDate||iso132(new Date())}))];
  const seen=new Set();return rows.filter(x=>{const k=`${x.id}|${x.title}|${x.date}`;if(seen.has(k))return false;seen.add(k);return true});
}
window.ub132CalendarMove=function(n){state.ub132CalOffset=(state.ub132CalOffset||0)+n;render()};
window.ub132CalendarToday=function(){state.ub132CalOffset=0;render()};
function calendar132(){
  const start=add132(monday132(new Date()),(state.ub132CalOffset||0)*7),days=[...Array(7)].map((_,i)=>add132(start,i)),rows=news132(),end=days[6];
  const by={};days.forEach(d=>by[iso132(d)]=[]);rows.forEach(x=>by[x.date]&&by[x.date].push(x));
  return `<div class="page-content ub132-calendar">
    <div class="page-head">
      <div><span class="ub132-kicker">KOMUNIKATY I WYDARZENIA</span><h1>Aktualności</h1><p>Najpierw tydzień i rzeczy, które faktycznie dzieją się teraz.</p></div>
      <div class="ub132-cal-controls"><button onclick="ub132CalendarMove(-1)">←</button><button class="today" onclick="ub132CalendarToday()">Dziś</button><strong>${fmt132(start,{day:'numeric',month:'long'})} – ${fmt132(end,{day:'numeric',month:'long',year:'numeric'})}</strong><button onclick="ub132CalendarMove(1)">→</button></div>
    </div>
    <section class="ub132-week-strip">
      ${days.map(d=>`<article class="${iso132(d)===iso132(new Date())?'today':''}">
        <header><span>${['Pon','Wt','Śr','Czw','Pt','Sob','Nd'][(d.getDay()+6)%7]}</span><b>${fmt132(d,{day:'2-digit',month:'2-digit'})}</b></header>
        <div>${by[iso132(d)].map(x=>`<button><small>${E132(x.type)}</small><b>${E132(x.title)}</b></button>`).join('')||'<span class="empty">—</span>'}</div>
      </article>`).join('')}
    </section>
    <section class="ub132-agenda">
      <header><div><b>Agenda tygodnia</b><small>${rows.filter(x=>x.date>=iso132(start)&&x.date<=iso132(end)).length} pozycji</small></div></header>
      ${rows.filter(x=>x.date>=iso132(start)&&x.date<=iso132(end)).sort((a,b)=>a.date.localeCompare(b.date)).map(x=>`<article>
        <div class="date"><b>${fmt132(new Date(x.date+'T12:00:00'),{day:'2-digit'})}</b><span>${fmt132(new Date(x.date+'T12:00:00'),{month:'short'})}</span></div>
        <div><small>${E132(x.type)}</small><h3>${E132(x.title)}</h3><p>${E132(x.body||'Szczegóły publikacji w platformie.')}</p></div>
        <button>Otwórz →</button>
      </article>`).join('')||'<div class="ub132-no-items">Brak publikacji w tym tygodniu.</div>'}
    </section>
  </div>`;
}
const rs132=window.renderSection;
window.renderSection=function(){
  if(state?.role==='employee'&&state.section==='Aktualności')return calendar132();
  return rs132.apply(this,arguments);
};

console.log('Up Bonus v132 auth + typography + UX ready');
