/* ===== SOURCE: upbonus-v108-docenianie-icon.js ===== */

(function(){
'use strict';

const ICON='👏';

function fixOne(btn){
  const text=(btn.textContent||'').replace(/\s+/g,' ').trim();
  if(text!=='Docenianie' && !text.endsWith(' Docenianie')) return;

  const icon =
    btn.querySelector('.ub40-nav-emoji') ||
    btn.querySelector('.nav-icon') ||
    btn.querySelector('[aria-hidden="true"]') ||
    btn.querySelector('span');

  if(icon){
    icon.textContent=ICON;
  }else{
    const span=document.createElement('span');
    span.className='ub40-nav-emoji';
    span.setAttribute('aria-hidden','true');
    span.textContent=ICON;
    btn.prepend(span);
  }
}

function apply(){
  document.querySelectorAll('button, a').forEach(fixOne);
}

let queued=false;
function schedule(){
  if(queued)return;
  queued=true;
  requestAnimationFrame(()=>{
    queued=false;
    apply();
  });
}

new MutationObserver(schedule).observe(document.documentElement,{
  subtree:true,
  childList:true,
  characterData:true
});

document.addEventListener('DOMContentLoaded',apply);
window.addEventListener('load',apply,{once:true});
setTimeout(apply,100);
setTimeout(apply,500);
setTimeout(apply,1500);

document.documentElement.dataset.upbonusV108='docenianie-hard-fix';
console.log('v108: Docenianie icon = 👏');
})();


