/* ===== SOURCE: upbonus-v153-process-core.js ===== */
/* ==========================================================
   UP BONUS V153 — PROCESS CORE / PRESENTATION SAFETY
   Stitches employee -> client/HR -> BOK -> finance notifications
   and keeps purchase/history/docs in one canonical flow.
========================================================== */
(function(){
'use strict';

const BUILD='v153-process-core';
const NOTIF_KEY='upbonus.notifications.v117';
const FIN_KEY='upbonus.finance.ledger.v92';
const FLOW_KEY='upbonus.process.audit.v153';
const esc=v=>String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
const read=(k,d)=>{try{return JSON.parse(localStorage.getItem(k)||'null')??d}catch(e){return d}};
const write=(k,v)=>{try{localStorage.setItem(k,JSON.stringify(v))}catch(e){}};
const now=()=>new Date();
const today=()=>now().toISOString().slice(0,10);
const money=n=>Number(n||0).toLocaleString('pl-PL',{minimumFractionDigits:2,maximumFractionDigits:2})+' zł';
const role=()=>String(window.state?.role||'employee');
const tenant=()=>String(window.state?.tenant||window.state?.clientId||'upbonus');
const user=()=>window.state?.user||{};
const uid=()=>String(user().employeeId||user().id||user().email||user().name||'employee-current');
const uname=()=>String(user().name||user().email||'Pracownik');
const uemail=()=>String(user().email||'pracownik@firma.pl');
const rerender=()=>{try{typeof window.render==='function'&&window.render()}catch(e){}};
const persistSafe=()=>{try{typeof window.persist==='function'&&window.persist()}catch(e){}};
const toastSafe=(a,b)=>{try{typeof window.toast==='function'&&window.toast(a,b)}catch(e){}};

function audit(type,entityId,status,meta={}){
  const rows=read(FLOW_KEY,[]);
  rows.unshift({id:'AUD-'+Date.now()+'-'+Math.random().toString(36).slice(2,6),tenant:tenant(),type,entityId,status,actor:uname(),role:role(),at:now().toISOString(),...meta});
  write(FLOW_KEY,rows.slice(0,800));
}
window.ub153AuditTrail=()=>read(FLOW_KEY,[]).filter(x=>x.tenant===tenant());

/* ---------- canonical targeted notifications ---------- */
function notifications(){const x=read(NOTIF_KEY,[]);return Array.isArray(x)?x:[]}
function saveNotifications(x){write(NOTIF_KEY,x);syncBadge()}
function currentIdentitySet(){return new Set([uid(),uemail(),uname()].filter(Boolean).map(String))}
function visibleNotification(n){
  if(!n)return false;
  if(n.targetRole && n.targetRole!==role() && role()!=='superadmin')return false;
  if(role()==='employee' && n.targetUserId){
    const ids=currentIdentitySet();
    if(!ids.has(String(n.targetUserId)) && String(n.targetUserId)!=='employee-current')return false;
  }
  return true;
}
function emit({targetRole='',targetUserId='',icon='🔔',title,text='',route='',entityId='',action=''}){
  const rows=notifications();
  const id='N153-'+Date.now()+'-'+Math.random().toString(36).slice(2,6);
  rows.unshift({id,icon,title,text,time:'teraz',unread:true,targetRole,targetUserId,route,entityId,action,tenant:tenant(),createdAt:now().toISOString()});
  saveNotifications(rows.slice(0,250));
  return id;
}
window.ub153EmitNotification=emit;
window.ub153DeleteNotification=function(id){saveNotifications(notifications().filter(x=>x.id!==id));openNotifications()};
window.ub153ClearVisibleNotifications=function(){saveNotifications(notifications().filter(x=>!visibleNotification(x)));openNotifications()};
window.ub153OpenNotification=function(id){
  const rows=notifications(),n=rows.find(x=>x.id===id);if(!n)return;
  n.unread=false;saveNotifications(rows);closeNotifications();
  if(n.route && typeof window.selectSection==='function')window.selectSection(n.route);
};
function closeNotifications(){document.querySelector('.ub153-notification-panel')?.remove()}
function openNotifications(){
  closeNotifications();
  const rows=notifications().filter(visibleNotification);
  const el=document.createElement('div');el.className='ub153-notification-panel';
  el.innerHTML=`<div class="ub153-notification-head"><div><b>Powiadomienia</b><small>${rows.filter(x=>x.unread).length} nieprzeczytane</small></div><button data-close aria-label="Zamknij">×</button></div>
    <div class="ub153-notification-list">${rows.length?rows.map(n=>`<div class="ub153-notification-row"><button class="ub153-notification-open" onclick="ub153OpenNotification('${esc(n.id)}')"><span>${esc(n.icon||'🔔')}</span><div><b>${esc(n.title)}</b><small>${esc(n.text||'')}</small></div><em>${esc(n.time||'')}</em>${n.unread?'<i></i>':''}</button><button class="ub153-notification-delete" aria-label="Usuń powiadomienie" onclick="event.stopPropagation();ub153DeleteNotification('${esc(n.id)}')">×</button></div>`).join(''):'<div class="ub153-notification-empty">Brak powiadomień.</div>'}</div>
    <div class="ub153-notification-foot"><button onclick="ub153ClearVisibleNotifications()">Wyczyść wszystkie</button></div>`;
  el.querySelector('[data-close]').onclick=closeNotifications;document.body.appendChild(el);
}
function bellButton(){return [...document.querySelectorAll('button')].find(b=>/powiad|notif|bell/i.test(`${b.title||''} ${b.getAttribute('aria-label')||''}`))}
function syncBadge(){
  const b=bellButton();if(!b)return;
  const count=notifications().filter(x=>visibleNotification(x)&&x.unread).length;
  let badge=b.querySelector('.badge-dot,.notification-badge,.badge');
  if(!badge&&count){badge=document.createElement('span');badge.className='badge-dot';b.appendChild(badge)}
  if(badge){badge.textContent=String(count);badge.style.display=count?'grid':'none'}
}
document.addEventListener('click',e=>{
  const b=e.target.closest('button');if(!b)return;
  if(/powiad|notif|bell/i.test(`${b.title||''} ${b.getAttribute('aria-label')||''}`)){e.preventDefault();e.stopPropagation();e.stopImmediatePropagation();openNotifications()}
},true);

/* ---------- remove prototype explainers without touching legal/security copy ---------- */
const explainerPatterns=[
  /^Po wysłaniu:/i,/^Odbiorca po wysłaniu:/i,/system pokaże/i,/trafi do HR/i,/trafiła do:/i,
  /model dostępu/i,/nie duplikujemy dokumentów/i,/preferowane są kontrolowane linki/i,
  /pełny proces.*architektur/i,/dane → wniosek → działanie/i
];
function scrubExplainers(){
  document.querySelectorAll('.v66-route,.ub105-tech-note,.ub106-note,.ub114-note,.ub128-ms-note,.ub130-smallnote,.v29-note,.ub13-bok-note,.ub56-policy-note').forEach(x=>x.remove());
  document.querySelectorAll('#app p,#app small,#app .help,#app .callout').forEach(el=>{
    if(el.closest('.ub98-note,.ub132-reg-note,.ub132-consents,[class*="legal"],[class*="privacy"],[class*="rodo"],[class*="security"]'))return;
    const t=(el.textContent||'').trim();if(explainerPatterns.some(r=>r.test(t)))el.remove();
  });
}

/* ---------- requests: employee -> client HR -> employee ---------- */
function ensureRequestStores(){
  state.v66=state.v66||{};state.v66.requestHistory=Array.isArray(state.v66.requestHistory)?state.v66.requestHistory:[];
  state.v29=state.v29||{};state.v29.requests=Array.isArray(state.v29.requests)?state.v29.requests:[];
}
function syncRequestStatus(id,status){
  ensureRequestStores();
  state.v66.requestHistory.filter(x=>x.id===id).forEach(x=>x.status=status);
  state.v29.requests.filter(x=>x.id===id).forEach(x=>x.status=status);
  persistSafe();
}
function submitEmployeeRequest(kind,name,owner){
  ensureRequestStores();
  const id='WN-'+now().getFullYear()+'-'+String(Date.now()).slice(-6);
  const date=now().toLocaleDateString('pl-PL');
  const emp={id,type:name,date,status:'Do akceptacji HR',owner:owner||'HR',employee:uname(),email:uemail(),employeeId:uid(),kind};
  state.v66.requestHistory.unshift({...emp});
  state.v29.requests.unshift({id,employee:uname(),email:uemail(),employeeId:uid(),type:name,date,amount:'—',status:'Do akceptacji HR',reminders:0,lastReminder:'',kind});
  persistSafe();
  try{typeof window.closeModal==='function'&&window.closeModal()}catch(e){}
  emit({targetRole:'hr',icon:'📋',title:'Nowy wniosek do akceptacji',text:`${uname()} · ${name} · ${id}`,route:'Wnioski i świadczenia',entityId:id});
  emit({targetRole:'employee',targetUserId:uid(),icon:'📋',title:'Wniosek wysłany',text:`${name} · ${id}`,route:'Wnioski i świadczenia',entityId:id});
  audit('request',id,'submitted',{kind,name});
  toastSafe('Wniosek wysłany',`Numer sprawy: ${id}`);rerender();
  return id;
}
function installRequestHooks(){
  if(window.v66SubmitRequest&&!window.v66SubmitRequest.__ub153){
    const fn=function(kind,name,owner){return submitEmployeeRequest(kind,name,owner)};fn.__ub153=true;window.v66SubmitRequest=fn;try{v66SubmitRequest=fn}catch(e){}
  }
  if(window.v29UpdateRequest&&!window.v29UpdateRequest.__ub153){
    const base=window.v29UpdateRequest;
    const wrap=function(){
      ensureRequestStores();
      const id=state.modal?.data?.id;const r=state.v29.requests.find(x=>x.id===id);const employeeId=r?.employeeId||r?.email||'employee-current';
      const next=document.getElementById('v29ReqStatus')?.value||r?.status||'';
      const out=base.apply(this,arguments);syncRequestStatus(id,next);
      if(/Zaakceptowany/i.test(next))emit({targetRole:'employee',targetUserId:employeeId,icon:'✅',title:'Wniosek zaakceptowany',text:`${r?.type||'Wniosek'} · ${id}`,route:'Wnioski i świadczenia',entityId:id});
      if(/Odrzucony/i.test(next))emit({targetRole:'employee',targetUserId:employeeId,icon:'❌',title:'Wniosek odrzucony',text:`${r?.type||'Wniosek'} · ${id}`,route:'Wnioski i świadczenia',entityId:id});
      audit('request',id,next,{employee:r?.employee||''});return out;
    };wrap.__ub153=true;window.v29UpdateRequest=wrap;try{v29UpdateRequest=wrap}catch(e){}
  }
}

/* ---------- training registration uses the same approval workflow ---------- */
const TRAINING={excel:'Excel Advanced',cyber:'Cybersecurity Basics',english:'Business English B2',mentor:'Mentoring rozwojowy'};
function installTrainingHook(){
  if(typeof window.ub144Reserve!=='function'||window.ub144Reserve.__ub153)return;
  const base=window.ub144Reserve;
  const wrap=function(id,title,route){
    if(!TRAINING[id])return base.apply(this,arguments);
    const actionKey=`upbonus.employee.actions.v144.${tenant()}`,a=read(actionKey,{});
    if(a[id]?.reserved)return;
    a[id]={...(a[id]||{}),saved:true,reserved:true,pendingApproval:true,reservedAt:now().toISOString()};write(actionKey,a);
    const reqId=submitEmployeeRequest('training',`Szkolenie: ${title||TRAINING[id]}`,'HR');
    audit('training',reqId,'pending_approval',{trainingId:id});
    toastSafe('Zapis wysłany',`${title||TRAINING[id]} · oczekuje na akceptację`);rerender();
  };wrap.__ub153=true;window.ub144Reserve=wrap;
}

/* ---------- Kudos notifications both ways ---------- */
function installKudosHook(){
  if(typeof window.ub64SubmitKudos!=='function'||window.ub64SubmitKudos.__ub153)return;
  const base=window.ub64SubmitKudos;
  const wrap=function(event){
    const form=event?.target||document.querySelector('.ub64-kudos-form');
    const fd=form?new FormData(form):null;
    const personId=String(fd?.get('personId')||'employee-current');
    const personName=form?.querySelector(`input[name="personId"][value="${CSS.escape(personId)}"]`)?.closest('label')?.querySelector('b')?.textContent||'Pracownik';
    const points=Number(fd?.get('customPoints')||fd?.get('points')||0);const reason=String(fd?.get('reason')||'Docenienie');
    const out=base.apply(this,arguments);
    emit({targetRole:'employee',targetUserId:personId,icon:'👏',title:'Otrzymujesz Kudos',text:`${points} pkt · ${reason}`,route:'Wyzwania i nagrody',entityId:personId});
    emit({targetRole:'hr',icon:'👏',title:'Przyznano Kudos',text:`${personName} · ${points} pkt · ${reason}`,route:'Wellbeing i Kudosy',entityId:personId});
    audit('kudos',personId,'awarded',{points,reason,recipient:personName});
    return out;
  };wrap.__ub153=true;window.ub64SubmitKudos=wrap;try{ub64SubmitKudos=wrap}catch(e){}
}

/* ---------- finance ledger + documents ---------- */
function financeData(){const d=read(FIN_KEY,null);return d&&Array.isArray(d.sales)?d:{sales:[],purchases:[],documents:[],payments:[],refunds:[]}}
function saveFinance(d){write(FIN_KEY,d)}
function orderPartner(order){return String(order.partner||order.brand||String(order.name||'').split(' ')[0]||'Partner')}
function ensureInvoiceForOrder(order){
  if(!order?.id)return null;const d=financeData();let doc=d.documents.find(x=>x.orderId===order.id&&x.direction==='Sprzedaż'&&x.type==='Faktura');if(doc)return doc;
  const gross=Number(order.value||order.amount||0),net=Math.round(gross/1.23*100)/100,vat=Math.round((gross-net)*100)/100;
  const docId='DOC-S-'+String(order.id).replace(/[^A-Za-z0-9]/g,'').slice(-14);
  const saleId='SAL-'+String(order.id).replace(/[^A-Za-z0-9]/g,'').slice(-14);
  doc={id:docId,number:`FV/UB/${now().getFullYear()}/${String(now().getMonth()+1).padStart(2,'0')}/${String(Date.now()).slice(-5)}`,direction:'Sprzedaż',type:'Faktura',entity:uname(),orderId:order.id,date:order.date||today(),net,vat,gross,paymentStatus:'Opłacona',accountingStatus:'Do księgowania',erpStatus:'Do eksportu'};
  d.documents.unshift(doc);
  if(!d.sales.some(x=>x.orderId===order.id))d.sales.unshift({id:saleId,orderId:order.id,date:order.date||today(),client:tenant(),program:order.program||'Benefit',partner:orderPartner(order),product:order.name||'Benefit',sku:order.productId||'—',qty:1,unitGross:gross,net,vat,gross,status:order.status||'Zrealizowana',paymentMethod:order.payment||'E-konta',paymentDue:today(),paymentStatus:'Opłacona',documentId:docId});
  order.invoiceId=docId;order.invoiceNumber=doc.number;saveFinance(d);persistSafe();audit('finance',order.id,'invoice_created',{documentId:docId});return doc;
}
function ensureCorrection(order,reason='Anulowanie / zwrot'){
  if(!order?.id)return null;const d=financeData();let doc=d.documents.find(x=>x.orderId===order.id&&x.type==='Korekta');if(doc)return doc;
  const amount=Number(order.value||0),net=-Math.round(amount/1.23*100)/100,vat=-Math.round((amount-Math.round(amount/1.23*100)/100)*100)/100,gross=-amount;
  doc={id:'DOC-K-'+String(Date.now()).slice(-9),number:`KOR/UB/${now().getFullYear()}/${String(Date.now()).slice(-5)}`,direction:'Sprzedaż',type:'Korekta',entity:uname(),orderId:order.id,date:today(),net,vat,gross,paymentStatus:'Zwrot',accountingStatus:'Do księgowania',erpStatus:'Do eksportu'};
  d.documents.unshift(doc);d.refunds.unshift({id:'REF-'+String(Date.now()).slice(-9),orderId:order.id,date:today(),client:tenant(),partner:orderPartner(order),reason,amount,status:'Do rozliczenia'});saveFinance(d);audit('finance',order.id,'correction_created',{documentId:doc.id});return doc;
}
window.ub153OpenInvoice=function(orderId){
  const d=financeData(),doc=d.documents.find(x=>x.orderId===orderId&&['Faktura','Korekta'].includes(x.type));if(!doc)return;
  const w=window.open('','_blank');if(!w)return;w.document.write(`<!doctype html><meta charset="utf-8"><title>${esc(doc.number)}</title><style>body{font-family:Inter,Arial;margin:40px;color:#2f1a28}.head{display:flex;justify-content:space-between;border-bottom:3px solid #6b174e;padding-bottom:15px}.logo{font-size:28px;font-weight:800;color:#ff8500}.box{margin-top:24px;border:1px solid #eadfe5;padding:18px;border-radius:12px}table{width:100%;border-collapse:collapse;margin-top:20px}td{padding:9px;border-bottom:1px solid #eee}.sum{font-size:22px;font-weight:800}@media print{button{display:none}}</style><div class="head"><div class="logo">Up Bonus</div><div><b>${esc(doc.type)}</b><br>${esc(doc.number)}</div></div><div class="box"><b>Zamówienie:</b> ${esc(doc.orderId)}<br><b>Data:</b> ${esc(doc.date)}<br><b>Nabywca:</b> ${esc(doc.entity)}</div><table><tr><td>Netto</td><td>${money(doc.net)}</td></tr><tr><td>VAT</td><td>${money(doc.vat)}</td></tr><tr><td><b>Brutto</b></td><td class="sum">${money(doc.gross)}</td></tr><tr><td>Status</td><td>${esc(doc.accountingStatus)}</td></tr><tr><td>ERP</td><td>${esc(doc.erpStatus)}</td></tr></table><button onclick="print()">Drukuj / PDF</button>`);w.document.close();
};

function syncOrdersAndHistory(){
  const orders=Array.isArray(state?.v14?.orders)?state.v14.orders:[];
  orders.forEach(o=>{if(!o.date)o.date=today();if(!o.payment)o.payment='Płatność e-kontami';ensureInvoiceForOrder(o)});
  state.v19=state.v19||{};state.v19.history=Array.isArray(state.v19.history)?state.v19.history:[];
  orders.forEach(o=>{if(!state.v19.history.some(h=>String(h.orderId||h.id)===String(o.id)))state.v19.history.unshift({id:'H-'+o.id,orderId:o.id,date:o.date,name:o.name,amount:-Number(o.value||0),status:o.status,payment:o.payment,voucherId:o.voucherId})});
  persistSafe();
}

function installPurchaseHooks(){
  if(typeof window.v105Confirm==='function'&&!window.v105Confirm.__ub153){
    const base=window.v105Confirm;const wrap=function(){const before=new Set((state.v14?.orders||[]).map(x=>x.id));const out=base.apply(this,arguments);setTimeout(()=>{const created=(state.v14?.orders||[]).filter(x=>!before.has(x.id));created.forEach(o=>{o.payment='Płatność e-kontami';ensureInvoiceForOrder(o);emit({targetRole:'employee',targetUserId:uid(),icon:'🛍️',title:'Zakup zakończony',text:`${o.name} · ${money(o.value)}`,route:'Zakupy i historia',entityId:o.id});emit({targetRole:'finance',icon:'🧾',title:'Nowa sprzedaż i faktura',text:`${o.id} · ${money(o.value)}`,route:'Sprzedaż',entityId:o.id});audit('purchase',o.id,'completed',{amount:o.value})});syncOrdersAndHistory();rerender()},0);return out};wrap.__ub153=true;window.v105Confirm=wrap;try{v105Confirm=wrap}catch(e){}
  }
  if(typeof window.v103CancelOrder==='function'&&!window.v103CancelOrder.__ub153){
    const base=window.v103CancelOrder;const wrap=function(orderId){const out=base.apply(this,arguments);setTimeout(()=>{const o=(state.v14?.orders||[]).find(x=>x.id===orderId);if(o&&/Anul|Zwrot|Zwró/.test(`${o.status} ${o.paymentStatus||''}`)){ensureCorrection(o,'Anulowanie / zwrot');emit({targetRole:'finance',icon:'↩️',title:'Korekta po anulowaniu',text:`${o.id} · ${money(o.value)}`,route:'Zwroty i korekty',entityId:o.id});audit('purchase',o.id,'cancelled')}} ,20);return out};wrap.__ub153=true;window.v103CancelOrder=wrap;
  }
  if(typeof window.v104SubmitComplaint==='function'&&!window.v104SubmitComplaint.__ub153){
    const base=window.v104SubmitComplaint;const wrap=function(){const before=new Set((state.v103?.complaints||[]).map(x=>x.id));const out=base.apply(this,arguments);setTimeout(()=>{const c=(state.v103?.complaints||[]).find(x=>!before.has(x.id))||(state.v103?.complaints||[])[0];if(c){emit({targetRole:'bok',icon:'🛟',title:'Nowa reklamacja',text:`${c.product||'Benefit'} · ${c.id}`,route:'Reklamacje',entityId:c.id});emit({targetRole:'employee',targetUserId:uid(),icon:'🛟',title:'Reklamacja przyjęta',text:`${c.id} · ${c.status||'Przyjęta'}`,route:'Zakupy i historia',entityId:c.id});audit('complaint',c.id,'submitted',{orderId:c.orderId})}},0);return out};wrap.__ub153=true;window.v104SubmitComplaint=wrap;try{v104SubmitComplaint=wrap}catch(e){}
  }
  const decisionNames=['v24DecisionSave','v64ComplaintDecisionSave'];
  decisionNames.forEach(name=>{const f=window[name];if(typeof f==='function'&&!f.__ub153){const wrap=function(id){const out=f.apply(this,arguments);setTimeout(()=>{const c=[...(state.v64?.complaints||[]),...(state.v103?.complaints||[])].find(x=>String(x.id)===String(id));if(c){emit({targetRole:'employee',targetUserId:c.employeeId||c.email||'employee-current',icon:'✅',title:'Reklamacja rozpatrzona',text:`${id} · ${c.decision||c.status}`,route:'Zakupy i historia',entityId:id});const o=(state.v14?.orders||[]).find(x=>String(x.id)===String(c.orderId||c.order));if(o&&/Zwrot|Korekta|uznana|Wymiana|Blokada/i.test(`${c.decision||''} ${c.settlement||''}`)){ensureCorrection(o,'Reklamacja');emit({targetRole:'finance',icon:'🧾',title:'Korekta po reklamacji',text:`${id} · ${o.id}`,route:'Zwroty i korekty',entityId:o.id})}audit('complaint',id,'resolved',{decision:c.decision||c.status})}},30);return out};wrap.__ub153=true;window[name]=wrap;try{if(name==='v24DecisionSave')v24DecisionSave=wrap;if(name==='v64ComplaintDecisionSave')v64ComplaintDecisionSave=wrap}catch(e){}}});
}

/* Dokumenty zakupowe są prezentowane wyłącznie w kolumnie historii zakupów. */

/* ---------- product media consistency ---------- */
function normalizeProductMedia(){
  document.querySelectorAll('.ub43-product-image-wrap img,.employee-product-card img,[class*="product-card"] img').forEach(img=>{img.loading='lazy';img.style.objectFit='contain'});
  document.querySelectorAll('.v107-product-icon,.voucher-logo').forEach(x=>{if((x.textContent||'').trim().length<=3)x.setAttribute('aria-hidden','true')});
}

/* ---------- installation / reinstallation because older modules also rewrap functions ---------- */
function install(){installRequestHooks();installTrainingHook();installKudosHook();installPurchaseHooks();syncBadge();scrubExplainers();normalizeProductMedia()}
let q=false;function refresh(){if(q)return;q=true;requestAnimationFrame(()=>{q=false;install()})}
new MutationObserver(refresh).observe(document.documentElement,{subtree:true,childList:true});
window.addEventListener('load',()=>{install();syncOrdersAndHistory()},{once:true});
setTimeout(install,100);setTimeout(install,700);setTimeout(install,1600);

document.documentElement.dataset.upbonusV153=BUILD;
console.log('Up Bonus V153 process core ready');
})();


