/* ==========================================================
   UP BONUS V154 — ENTERPRISE CLIENT + PARTNER
   Tenant configuration, organisation M365 model, time tracking,
   import templates, client typography/branding and security controls.
========================================================== */
(function(){
'use strict';
const KEY='upbonus.enterprise.v154';
const E=v=>String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
const rd=(k,d)=>{try{return JSON.parse(localStorage.getItem(k)||'null')??d}catch(e){return d}};
const wr=(k,v)=>{try{localStorage.setItem(k,JSON.stringify(v))}catch(e){}};
const tenant=()=>String(state?.tenant||state?.clientId||'upbonus');
const user=()=>state?.user||{};
const empId=()=>String(user().employeeId||user().id||user().email||'EMP-001');
const empName=()=>String(user().name||user().email||'Pracownik');
const now=()=>new Date();
const today=()=>now().toISOString().slice(0,10);
const money=n=>Number(n||0).toLocaleString('pl-PL',{minimumFractionDigits:2,maximumFractionDigits:2})+' zł';
const notify=o=>{try{window.ub153EmitNotification&&window.ub153EmitNotification(o)}catch(e){}};
const audit=(type,id,status,meta={})=>{try{const a=window.ub153AuditTrail?.()||[];void a}catch(e){}};
const persistSafe=()=>{try{persist()}catch(e){}};
const rerender=()=>{try{render()}catch(e){}};
const toastSafe=(a,b)=>{try{toast(a,b)}catch(e){}};

function defaults(){return {
  modules:{m365:true,projects:true,timeTracking:false,imports:true,security:true},
  ui:{font:'Inter',baseSize:14,navSize:13.5,tableSize:12.5,headingScale:1,primary:'#6b174e',accent:'#ff8500'},
  m365:{status:'not_configured',tenantId:'',domain:'',adminConsent:false,teams:true,outlook:true,calendar:true,sharepoint:true,onedrive:true,sso:true,lastTest:''},
  security:{sso:true,mfa:true,sessionMinutes:60,audit:true,retentionMonths:36,privacyContact:'dpo@firma.pl',employeeSelfRegistration:false},
  time:{requireApproval:true,rounding:5,allowManual:true,allowProjects:true},
  imports:{lastEmployeeImport:'',lastProductImport:''}
}}
function all(){const x=rd(KEY,{});return x&&typeof x==='object'?x:{}}
function cfg(){const a=all();return {...defaults(),...(a[tenant()]||{}),modules:{...defaults().modules,...(a[tenant()]?.modules||{})},ui:{...defaults().ui,...(a[tenant()]?.ui||{})},m365:{...defaults().m365,...(a[tenant()]?.m365||{})},security:{...defaults().security,...(a[tenant()]?.security||{})},time:{...defaults().time,...(a[tenant()]?.time||{})},imports:{...defaults().imports,...(a[tenant()]?.imports||{})}}}
function save(next){const a=all();a[tenant()]=next;wr(KEY,a);applyUi()}
window.ub154Config=cfg;

function applyUi(){const c=cfg().ui,r=document.documentElement;const stack=c.font==='Segoe UI'?'"Segoe UI",Arial,sans-serif':c.font==='Arial'?'Arial,sans-serif':'Inter,"Segoe UI",Arial,sans-serif';r.style.setProperty('--ub-font-ui',stack);r.style.setProperty('--ub-fs-14',`${Number(c.baseSize)||14}px`);r.style.setProperty('--brand-primary',c.primary);r.style.setProperty('--brand-accent',c.accent);r.style.setProperty('--ub-client-nav-size',`${Number(c.navSize)||13.5}px`);r.style.setProperty('--ub-client-table-size',`${Number(c.tableSize)||12.5}px`);r.dataset.ubTenant=tenant()}
window.ub154ApplyUi=applyUi;

/* ---------- Client UI configuration ---------- */
window.ub154SaveUi=function(){const c=cfg();c.ui={font:document.getElementById('ub154Font')?.value||'Inter',baseSize:Number(document.getElementById('ub154Base')?.value||14),navSize:Number(document.getElementById('ub154Nav')?.value||13.5),tableSize:Number(document.getElementById('ub154Table')?.value||12.5),headingScale:Number(document.getElementById('ub154Heading')?.value||1),primary:document.getElementById('ub154Primary')?.value||'#6b174e',accent:document.getElementById('ub154Accent')?.value||'#ff8500'};save(c);toastSafe('Wygląd zapisany','Ustawienia dotyczą tylko tego klienta.');rerender()};
function personalizationView(){const c=cfg().ui;return `<div class="page-content ub154-page"><div class="page-head"><div><h1>Personalizacja platformy</h1><p>Wygląd i typografia dla ${E(tenant())}.</p></div></div><section class="ub154-card"><div class="ub154-form"><label>Font<select id="ub154Font"><option ${c.font==='Inter'?'selected':''}>Inter</option><option ${c.font==='Segoe UI'?'selected':''}>Segoe UI</option><option ${c.font==='Arial'?'selected':''}>Arial</option></select></label><label>Tekst bazowy (px)<input id="ub154Base" type="number" min="13" max="17" step=".5" value="${c.baseSize}"></label><label>Menu (px)<input id="ub154Nav" type="number" min="12" max="16" step=".5" value="${c.navSize}"></label><label>Tabele (px)<input id="ub154Table" type="number" min="11" max="15" step=".5" value="${c.tableSize}"></label><label>Skala nagłówków<input id="ub154Heading" type="number" min=".9" max="1.2" step=".05" value="${c.headingScale}"></label><label>Kolor główny<input id="ub154Primary" type="color" value="${E(c.primary)}"></label><label>Akcent<input id="ub154Accent" type="color" value="${E(c.accent)}"></label></div><div class="ub154-actions"><button class="primary-btn" onclick="ub154SaveUi()">Zapisz dla klienta</button></div></section><div class="ub154-grid" style="margin-top:14px"><article class="ub154-card"><span>H1</span><b style="font-size:30px!important">Panel klienta</b><p>Przykład głównego nagłówka.</p></article><article class="ub154-card"><span>KARTA</span><b>Benefit / proces</b><p>Przykład treści karty na zoomie 100%.</p></article><article class="ub154-card"><span>TABELA</span><b>${c.tableSize}px</b><p>Rozmiar komórek tabeli.</p></article></div></div>`}

/* ---------- Microsoft 365: organisation connection, not personal user OAuth ---------- */
window.ub154SaveM365=function(){const c=cfg();c.m365.tenantId=String(document.getElementById('ub154TenantId')?.value||'').trim();c.m365.domain=String(document.getElementById('ub154Domain')?.value||'').trim();c.m365.adminConsent=!!document.getElementById('ub154Consent')?.checked;c.m365.status=c.m365.tenantId&&c.m365.domain&&c.m365.adminConsent?'configured':'not_configured';save(c);toastSafe('Microsoft 365','Konfiguracja organizacji została zapisana.');rerender()};
window.ub154TestM365=function(){const c=cfg();if(c.m365.status!=='configured'){toastSafe('Microsoft 365','Uzupełnij Tenant ID, domenę i zgodę administratora.');return}c.m365.lastTest=now().toLocaleString('pl-PL');c.m365.status='ready_for_oauth';save(c);toastSafe('Test konfiguracji','Parametry organizacji są kompletne do uruchomienia OAuth / Graph.');rerender()};
function m365View(){const m=cfg().m365;return `<div class="page-content ub154-page"><div class="page-head"><div><h1>Microsoft 365 i Teams</h1><p>Połączenie organizacji i zasady dostępu pracowników.</p></div><span class="ub154-status ${m.status==='ready_for_oauth'?'ok':m.status==='configured'?'warn':''}">${m.status==='ready_for_oauth'?'Gotowe do OAuth':m.status==='configured'?'Skonfigurowane':'Nie skonfigurowane'}</span></div><section class="ub154-card"><div class="ub154-form"><label>Microsoft Tenant ID<input id="ub154TenantId" value="${E(m.tenantId)}" placeholder="xxxxxxxx-xxxx-xxxx-xxxx-xxxxxxxxxxxx"></label><label>Domena organizacji<input id="ub154Domain" value="${E(m.domain)}" placeholder="firma.pl"></label><label class="wide"><span>Zgoda administratora Entra ID</span><span><input id="ub154Consent" type="checkbox" ${m.adminConsent?'checked':''}> Admin consent udzielony</span></label></div><div class="ub154-ms-permissions"><span>✓ Microsoft Graph / profile</span><span>✓ Teams / Activity Feed</span><span>✓ Outlook / kalendarz</span><span>✓ SharePoint / OneDrive links</span></div><div class="ub154-actions"><button class="primary-btn" onclick="ub154SaveM365()">Zapisz konfigurację organizacji</button><button class="secondary-btn" onclick="ub154TestM365()">Testuj konfigurację</button></div>${m.lastTest?`<p style="margin-top:10px">Ostatni test: ${E(m.lastTest)}</p>`:''}</section><div class="ub154-grid" style="margin-top:14px"><article class="ub154-card"><span>LOGOWANIE</span><b>SSO organizacji</b><p>Pracownik korzysta z polityki klienta, nie z prywatnego połączenia administratora.</p></article><article class="ub154-card"><span>TEAMS</span><b>Powiadomienia i deep linki</b><p>Akcje kierują do konkretnego procesu w Up Bonus.</p></article><article class="ub154-card"><span>DOKUMENTY</span><b>SharePoint / OneDrive</b><p>Uprawnienia pozostają po stronie Microsoft 365.</p></article></div></div>`}

/* ---------- Time tracking ---------- */
const TKEY=()=>`upbonus.time.v154.${tenant()}`;
function timeRows(){const x=rd(TKEY(),[]);return Array.isArray(x)?x:[]}
function saveTime(x){wr(TKEY(),x)}
window.ub154TimeStart=function(){const rows=timeRows();if(rows.some(x=>x.employeeId===empId()&&!x.end)){toastSafe('Czas pracy','Masz już uruchomioną rejestrację.');return}rows.unshift({id:'TIME-'+Date.now(),employeeId:empId(),employee:empName(),date:today(),start:now().toISOString(),end:'',minutes:0,project:'',status:'W toku'});saveTime(rows);notify({targetRole:'hr',icon:'⏱️',title:'Rozpoczęto rejestrację czasu',text:empName(),route:'Rejestracja czasu pracy'});rerender()};
window.ub154TimeStop=function(){const rows=timeRows(),r=rows.find(x=>x.employeeId===empId()&&!x.end);if(!r)return;r.end=now().toISOString();r.minutes=Math.max(1,Math.round((new Date(r.end)-new Date(r.start))/60000));r.status=cfg().time.requireApproval?'Do akceptacji':'Zatwierdzony';saveTime(rows);notify({targetRole:'hr',icon:'⏱️',title:'Czas pracy do akceptacji',text:`${empName()} · ${r.minutes} min`,route:'Rejestracja czasu pracy',entityId:r.id});rerender()};
window.ub154ApproveTime=function(id,status){const rows=timeRows(),r=rows.find(x=>x.id===id);if(!r)return;r.status=status;saveTime(rows);notify({targetRole:'employee',targetUserId:r.employeeId,icon:status==='Zatwierdzony'?'✅':'❌',title:`Czas pracy: ${status}`,text:`${r.date} · ${r.minutes} min`,route:'Rejestracja czasu pracy',entityId:id});rerender()};

const ub154FmtMin=m=>{m=Math.max(0,Math.round(Number(m||0)));const h=Math.floor(m/60),mm=m%60;return h?`${h} h ${String(mm).padStart(2,'0')} min`:`${mm} min`};
const ub154TimeStatus=r=>{const x=String(r?.status||'').toLowerCase();if(!r?.end)return 'W trakcie';if(x.includes('akcept'))return 'Do akceptacji';if(x.includes('odrz'))return 'Oczekuje na korektę';if(x.includes('nieobec'))return 'Nieobecność';if(x.includes('woln'))return 'Dzień wolny';return 'Rozliczone'};
const ub154TimeBadge=s=>{const k=s==='Rozliczone'?'ok':s==='W trakcie'?'active':(s==='Nieobecność'||s==='Dzień wolny')?'muted':'warn';return `<span class="ub154-time-badge ${k}">${E(s)}</span>`};
function ub154TimeStartOfWeek(d=new Date()){const x=new Date(d),day=(x.getDay()+6)%7;x.setHours(0,0,0,0);x.setDate(x.getDate()-day);return x}
function ub154TimeDateKey(d){return new Date(d).toISOString().slice(0,10)}
function ub154TimeMinutes(r){if(!r)return 0;if(r.end)return Number(r.minutes||Math.max(0,Math.round((new Date(r.end)-new Date(r.start))/60000)));return Math.max(0,Math.round((Date.now()-new Date(r.start).getTime())/60000))}
function ub154TimeClock(r){if(!r)return '00:00:00';const sec=Math.max(0,Math.floor((Date.now()-new Date(r.start).getTime())/1000)),h=Math.floor(sec/3600),m=Math.floor((sec%3600)/60),s=sec%60;return `${String(h).padStart(2,'0')}:${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`}
function ub154SeedTimeRows(rows){if(rows.length)return rows;const base=ub154TimeStartOfWeek(),mins=[482,478,492,480];const seeded=[];for(let i=0;i<4;i++){const d=new Date(base);d.setDate(d.getDate()+i);if(d>new Date())break;const start=new Date(d);start.setHours(8,2+i%3,0,0);const end=new Date(start);end.setMinutes(end.getMinutes()+mins[i]);seeded.push({id:'TIME-DEMO-'+i,employeeId:empId(),employee:empName(),date:ub154TimeDateKey(d),start:start.toISOString(),end:end.toISOString(),minutes:mins[i],breakMinutes:30,status:'Zatwierdzony',demo:true})}if(seeded.length){saveTime(seeded);return seeded}return rows}
window.ub154TimeTab=function(tab){state.ub154TimeTab=tab;rerender()};
window.ub154TimeDetail=function(id){state.ub154TimeDetail=id;rerender()};
window.ub154TimeCloseDetail=function(){state.ub154TimeDetail=null;rerender()};
window.ub154TimeCorrection=function(id){state.ub154TimeCorrection=id;rerender()};
window.ub154TimeCloseCorrection=function(){state.ub154TimeCorrection=null;rerender()};
window.ub154TimeAddBreak=function(){const rows=timeRows(),r=rows.find(x=>x.employeeId===empId()&&!x.end);if(!r)return toastSafe('Przerwa','Najpierw rozpocznij pracę.');r.breakMinutes=Number(r.breakMinutes||0)+15;saveTime(rows);toastSafe('Przerwa dodana','Dodano 15 min przerwy.');rerender()};
window.ub154TimeSubmitCorrection=function(id){const rows=timeRows(),r=rows.find(x=>x.id===id);if(!r)return;const reason=document.getElementById('ub154CorrReason')?.value||'Inne',startVal=document.getElementById('ub154CorrStart')?.value||'',endVal=document.getElementById('ub154CorrEnd')?.value||'',comment=document.getElementById('ub154CorrComment')?.value||'';r.correction={reason,start:startVal,end:endVal,comment,submittedAt:new Date().toISOString()};r.status='Do akceptacji';saveTime(rows);notify({targetRole:'hr',icon:'🕒',title:'Korekta czasu do akceptacji',text:`${empName()} · ${r.date} · ${reason}`,route:'Rejestracja czasu pracy',entityId:r.id});state.ub154TimeCorrection=null;toastSafe('Korekta wysłana','HR otrzymał zgłoszenie do akceptacji.');rerender()};
window.ub154TimeExport=function(){const rows=timeRows().filter(x=>x.employeeId===empId()),csv=['Data;Start;Koniec;Minuty;Status',...rows.map(r=>[r.date,r.start?new Date(r.start).toLocaleTimeString('pl-PL',{hour:'2-digit',minute:'2-digit'}):'',r.end?new Date(r.end).toLocaleTimeString('pl-PL',{hour:'2-digit',minute:'2-digit'}):'',r.minutes||'',ub154TimeStatus(r)].join(';'))].join('\n');const b=new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(b);a.download='czas-pracy.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500)};
window.ub154TimeMore=function(){state.ub154TimeMore=!state.ub154TimeMore;rerender()};
if(!window.__ub154TimeTicker){window.__ub154TimeTicker=setInterval(()=>{const el=document.getElementById('ub154LiveClock');if(!el)return;const rows=timeRows(),r=rows.find(x=>x.employeeId===empId()&&!x.end);if(r)el.textContent=ub154TimeClock(r)},1000)}
window.ub154ToggleTimeModule=function(on){const c=cfg();c.modules.timeTracking=!!on;save(c);rerender()};
function hrTimeView(){const c=cfg(),rows=timeRows(),min=rows.reduce((s,x)=>s+Number(x.minutes||0),0);return `<div class="page-content ub154-page"><div class="page-head"><div><h1>Rejestracja czasu pracy</h1><p>Opcjonalny moduł rozliczeniowy klienta.</p></div><label class="ub154-status ${c.modules.timeTracking?'ok':''}"><input type="checkbox" ${c.modules.timeTracking?'checked':''} onchange="ub154ToggleTimeModule(this.checked)"> Moduł ${c.modules.timeTracking?'aktywny':'wyłączony'}</label></div>${c.modules.timeTracking?`<div class="ub154-grid"><article class="ub154-card"><span>WPISY</span><b>${rows.length}</b><p>bieżący okres</p></article><article class="ub154-card"><span>ŁĄCZNIE</span><b>${Math.round(min/60*10)/10} h</b><p>zarejestrowanego czasu</p></article><article class="ub154-card"><span>DO AKCEPTACJI</span><b>${rows.filter(x=>x.status==='Do akceptacji').length}</b><p>wymaga działania HR</p></article></div><div class="ub154-table-wrap" style="margin-top:14px"><table class="ub154-table"><thead><tr><th>Data</th><th>Pracownik</th><th>Start</th><th>Koniec</th><th>Czas</th><th>Status</th><th>Akcje</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${E(r.date)}</td><td><b>${E(r.employee)}</b></td><td>${r.start?new Date(r.start).toLocaleTimeString('pl-PL',{hour:'2-digit',minute:'2-digit'}):'—'}</td><td>${r.end?new Date(r.end).toLocaleTimeString('pl-PL',{hour:'2-digit',minute:'2-digit'}):'—'}</td><td>${r.minutes?`${r.minutes} min`:'—'}</td><td>${E(r.status)}</td><td>${r.status==='Do akceptacji'?`<button onclick="ub154ApproveTime('${r.id}','Zatwierdzony')">Akceptuj</button> <button onclick="ub154ApproveTime('${r.id}','Odrzucony')">Odrzuć</button>`:'—'}</td></tr>`).join('')||'<tr><td colspan="7">Brak wpisów.</td></tr>'}</tbody></table></div>`:'<section class="ub154-card"><b>Moduł jest wyłączony dla tego klienta.</b><p>Włącz go przełącznikiem, jeśli firma chce prowadzić ewidencję czasu w Up Bonus.</p></section>'}</div>`}
function employeeTimeView(){
  const c=cfg();
  if(!c.modules.timeTracking)return `<div class="page-content ub154-page"><div class="page-head"><div><h1>Czas pracy</h1><p>Moduł nie jest dostępny w Twojej organizacji.</p></div></div><section class="ub154-card"><b>Rejestracja czasu pracy jest wyłączona dla tej organizacji.</b></section></div>`;
  let rows=ub154SeedTimeRows(timeRows().filter(x=>x.employeeId===empId()));
  const running=rows.find(x=>!x.end), todayRow=running||rows.find(x=>x.date===today());
  const tab=state.ub154TimeTab||'week', detail=rows.find(x=>x.id===state.ub154TimeDetail), corr=rows.find(x=>x.id===state.ub154TimeCorrection);
  const weekStart=ub154TimeStartOfWeek(), weekDays=Array.from({length:7},(_,i)=>{const d=new Date(weekStart);d.setDate(d.getDate()+i);return d});
  const weekRows=rows.filter(r=>{const d=new Date(r.date+'T12:00:00');return d>=weekStart&&d<new Date(weekStart.getTime()+7*86400000)}), weekMin=weekRows.reduce((a,r)=>a+ub154TimeMinutes(r),0), planWeek=40*60, balance=weekMin-planWeek;
  const month=now().getMonth(),year=now().getFullYear(),monthRows=rows.filter(r=>{const d=new Date(r.date+'T12:00:00');return d.getMonth()===month&&d.getFullYear()===year}),monthMin=monthRows.reduce((a,r)=>a+ub154TimeMinutes(r),0),monthPlan=Math.max(1,monthRows.length)*480,monthBalance=monthMin-monthPlan;
  const fmtClock=x=>x?new Date(x).toLocaleTimeString('pl-PL',{hour:'2-digit',minute:'2-digit'}):'—';
  const dayMain=running?`<span class="ub154-time-kicker">DZISIAJ · PRACA TRWA</span><h2>Pracujesz od ${fmtClock(running.start)}</h2><div class="ub154-live-clock" id="ub154LiveClock">${ub154TimeClock(running)}</div><p>Plan: 08:00–16:00</p><div class="ub154-time-actions"><button class="primary-btn" onclick="ub154TimeStop()">Zakończ pracę</button><button class="compact-btn" onclick="ub154TimeAddBreak()">Dodaj przerwę</button><button class="compact-btn" onclick="ub154TimeCorrection('${E(running.id)}')">Zgłoś korektę</button></div>`:todayRow&&todayRow.end?`<span class="ub154-time-kicker">DZISIAJ</span><h2>Dzień zakończony ✓</h2><div class="ub154-live-clock">${ub154FmtMin(ub154TimeMinutes(todayRow))}</div><p>Plan: 8 h · <b>${ub154TimeMinutes(todayRow)-480>=0?'+':''}${ub154TimeMinutes(todayRow)-480} min</b></p><div class="ub154-time-actions"><button class="compact-btn" onclick="ub154TimeDetail('${E(todayRow.id)}')">Szczegóły</button><button class="compact-btn" onclick="ub154TimeCorrection('${E(todayRow.id)}')">Zgłoś korektę</button></div>`:`<span class="ub154-time-kicker">DZISIAJ</span><h2>Nie rozpoczęto pracy</h2><div class="ub154-time-plan">Plan: 08:00–16:00</div><div class="ub154-time-actions"><button class="primary-btn" onclick="ub154TimeStart()">Rozpocznij pracę</button></div>`;
  const weekCards=weekDays.map(d=>{const key=ub154TimeDateKey(d),r=rows.find(x=>x.date===key),isToday=key===today(),weekend=d.getDay()===0||d.getDay()===6,label=['Nd','Pon','Wt','Śr','Czw','Pt','Sob'][d.getDay()];return `<button class="ub154-day-card ${isToday?'today':''} ${weekend?'weekend':''}" ${r?`onclick="ub154TimeDetail('${E(r.id)}')"`:''}><span>${label}</span><b>${d.getDate()}</b><small>${r?(r.end?ub154FmtMin(ub154TimeMinutes(r)):'W trakcie'):(weekend?'Wolne':'—')}</small>${r?ub154TimeBadge(ub154TimeStatus(r)):''}</button>`}).join('');
  const recent=rows.slice().sort((a,b)=>String(b.date).localeCompare(String(a.date))).slice(0,7);
  const weekView=`<section class="ub154-week-strip"><div class="ub154-section-title"><div><h2>Ten tydzień</h2><p><b>${ub154FmtMin(weekMin)}</b> / 40 h</p></div><div class="ub154-week-mini"><span>${weekRows.filter(r=>r.end).length} dni przepracowane</span><span class="${balance<0?'neg':'pos'}">${balance>=0?'+':''}${ub154FmtMin(Math.abs(balance))} bilansu</span><span>0 dni nieobecności</span></div></div><div class="ub154-progress"><i style="width:${Math.min(100,Math.round(weekMin/planWeek*100))}%"></i></div><div class="ub154-week-days">${weekCards}</div></section>`;
  const monthView=`<section class="ub154-card ub154-month-card"><div class="ub154-section-title"><div><h2>${now().toLocaleDateString('pl-PL',{month:'long',year:'numeric'})}</h2><p>Kalendarz czasu pracy</p></div><span class="ub154-time-badge ok">${monthRows.length} dni z rejestracją</span></div><div class="ub154-month-grid">${Array.from({length:new Date(year,month+1,0).getDate()},(_,i)=>{const d=new Date(year,month,i+1),key=ub154TimeDateKey(d),r=rows.find(x=>x.date===key),weekend=d.getDay()===0||d.getDay()===6;return `<button class="${key===today()?'today':''} ${weekend?'weekend':''}" ${r?`onclick="ub154TimeDetail('${E(r.id)}')"`:''}><span>${i+1}</span><small>${r?(ub154TimeStatus(r)==='Rozliczone'?'✓':ub154TimeStatus(r)==='W trakcie'?'●':'!'):(weekend?'•':'')}</small></button>`}).join('')}</div><div class="ub154-calendar-legend"><span>● dziś</span><span>✓ rozliczone</span><span>! wymaga działania</span><span>• dzień wolny</span></div></section>`;
  const historyView=`<section class="ub154-card"><div class="ub154-section-title"><div><h2>Historia</h2><p>Ostatnie rejestracje i korekty.</p></div><div class="ub154-more-wrap"><button class="compact-btn" onclick="ub154TimeMore()">⋯ Więcej</button>${state.ub154TimeMore?`<div class="ub154-more-menu"><button onclick="ub154TimeExport()">Eksportuj historię</button></div>`:''}</div></div><div class="ub154-time-list">${recent.map(r=>`<button class="ub154-time-row" onclick="ub154TimeDetail('${E(r.id)}')"><div><b>${new Date(r.date+'T12:00:00').toLocaleDateString('pl-PL',{day:'2-digit',month:'2-digit',year:'numeric'})}</b><span>${fmtClock(r.start)}–${r.end?fmtClock(r.end):'teraz'}</span></div><strong>${r.end?ub154FmtMin(ub154TimeMinutes(r)):'W trakcie'}</strong>${ub154TimeBadge(ub154TimeStatus(r))}<span class="ub154-time-chevron">Szczegóły →</span></button>`).join('')||'<div class="ub154-empty">Brak zarejestrowanych dni.</div>'}</div></section>`;
  const detailDrawer=detail?`<div class="ub154-overlay" onclick="if(event.target===this)ub154TimeCloseDetail()"><aside class="ub154-time-drawer"><div class="ub154-drawer-head"><div><span>Szczegóły dnia</span><h2>${new Date(detail.date+'T12:00:00').toLocaleDateString('pl-PL',{day:'2-digit',month:'2-digit',year:'numeric'})}</h2></div><button onclick="ub154TimeCloseDetail()">×</button></div><div class="ub154-detail-grid"><div><span>Plan</span><b>08:00–16:00</b></div><div><span>Rzeczywisty czas</span><b>${fmtClock(detail.start)}–${detail.end?fmtClock(detail.end):'teraz'}</b></div><div><span>Przerwy</span><b>${Number(detail.breakMinutes||30)} min</b></div><div><span>Łącznie</span><b>${ub154FmtMin(ub154TimeMinutes(detail))}</b></div><div><span>Bilans</span><b>${ub154TimeMinutes(detail)-480>=0?'+':''}${ub154TimeMinutes(detail)-480} min</b></div><div><span>Status</span>${ub154TimeBadge(ub154TimeStatus(detail))}</div></div>${detail.correction?`<div class="ub154-note"><b>Zgłoszona korekta</b><span>${E(detail.correction.reason||'')}</span>${detail.correction.comment?`<small>${E(detail.correction.comment)}</small>`:''}</div>`:''}<div class="ub154-drawer-actions"><button class="primary-btn" onclick="ub154TimeCorrection('${E(detail.id)}')">Zgłoś korektę</button><button class="compact-btn" onclick="toastSafe('Komentarz','Komentarz został dodany do dnia.')">Dodaj komentarz</button></div></aside></div>`:'';
  const corrModal=corr?`<div class="ub154-overlay" onclick="if(event.target===this)ub154TimeCloseCorrection()"><div class="ub154-correction-modal"><div class="ub154-drawer-head"><div><span>Korekta czasu</span><h2>${E(corr.date)}</h2></div><button onclick="ub154TimeCloseCorrection()">×</button></div><label>Powód korekty<select id="ub154CorrReason"><option>Zapomniałem rozpocząć pracę</option><option>Zapomniałem zakończyć pracę</option><option>Błędna godzina</option><option>Inne</option></select></label><div class="ub154-corr-times"><label>Poprawny start<input id="ub154CorrStart" type="time" value="${fmtClock(corr.start)}"></label><label>Poprawny koniec<input id="ub154CorrEnd" type="time" value="${corr.end?fmtClock(corr.end):''}"></label></div><label>Komentarz<textarea id="ub154CorrComment" placeholder="Opcjonalnie"></textarea></label><div class="ub154-drawer-actions"><button class="primary-btn" onclick="ub154TimeSubmitCorrection('${E(corr.id)}')">Wyślij do akceptacji</button><button class="compact-btn" onclick="ub154TimeCloseCorrection()">Anuluj</button></div></div></div>`:'';
  const attention=rows.find(r=>ub154TimeStatus(r)==='Do akceptacji')?`<div class="ub154-time-attention"><div><b>Wymaga Twojej uwagi</b><span>Masz korektę oczekującą na akceptację.</span></div><button class="compact-btn" onclick="ub154TimeTab('history')">Sprawdź →</button></div>`:'';
  return `<div class="page-content ub154-page ub154-time-page"><div class="page-head"><div><h1>Czas pracy</h1><p>Codzienna rejestracja czasu, bilans i korekty w jednym miejscu.</p></div><div class="ub154-more-wrap"><button class="compact-btn" onclick="ub154TimeMore()">⋯ Więcej</button>${state.ub154TimeMore?`<div class="ub154-more-menu"><button onclick="ub154TimeExport()">Eksportuj historię</button></div>`:''}</div></div>${attention}<section class="ub154-today-card"><div class="ub154-today-main">${dayMain}</div><aside class="ub154-month-balance"><span>Bilans miesiąca</span><b class="${monthBalance<0?'neg':'pos'}">${monthBalance>=0?'+':'−'}${ub154FmtMin(Math.abs(monthBalance))}</b><small>Nadgodziny i niedobór widoczne po rozliczeniu dni.</small></aside></section><nav class="ub154-time-tabs"><button class="${tab==='week'?'active':''}" onclick="ub154TimeTab('week')">Tydzień</button><button class="${tab==='month'?'active':''}" onclick="ub154TimeTab('month')">Miesiąc</button><button class="${tab==='history'?'active':''}" onclick="ub154TimeTab('history')">Historia</button></nav>${tab==='week'?weekView+historyView:tab==='month'?monthView+historyView:historyView}${detailDrawer}${corrModal}</div>`
}

/* ---------- Imports: copy/paste Excel compatible ---------- */
const employeeHeader=['employee_id','first_name','last_name','email','department','team','status','program'];
const productHeader=['product_id','partner','name','category','type','price','vat_rate','program','image_url','active'];
function tpl(type){const h=type==='products'?productHeader:employeeHeader;const sample=type==='products'?['PRD-001','Allegro','Karta Allegro 100 zł','Zakupy','Voucher','100','23','Budżet benefitowy','https://...','TRUE']:['EMP-001','Anna','Kowalska','anna@firma.pl','HR','People','active','Budżet benefitowy'];return h.join('\t')+'\n'+sample.join('\t')}
window.ub154ImportTab=function(t){state.ub154ImportTab=t;rerender()};
window.ub154CopyTemplate=async function(type){try{await navigator.clipboard.writeText(tpl(type));toastSafe('Formatka skopiowana','Wklej ją do Excela lub arkusza.')}catch(e){toastSafe('Formatka',tpl(type))}};
window.ub154DownloadTemplate=function(type){const blob=new Blob(['\ufeff'+tpl(type).replace(/\t/g,';')],{type:'text/csv;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=type==='products'?'upbonus_produkty.csv':'upbonus_pracownicy.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500)};
function parsePaste(text,headers){const lines=String(text||'').trim().split(/\r?\n/).filter(Boolean);if(!lines.length)return {rows:[],errors:['Brak danych']};const sep=lines[0].includes('\t')?'\t':';';const got=lines[0].split(sep).map(x=>x.trim().toLowerCase()),errors=[];headers.forEach(h=>{if(!got.includes(h))errors.push(`Brak kolumny: ${h}`)});const rows=lines.slice(1).map((l,i)=>{const vals=l.split(sep);const o={};got.forEach((h,j)=>o[h]=String(vals[j]??'').trim());o.__row=i+2;return o});return {rows,errors}}
window.ub154ValidateImport=function(type){const ta=document.getElementById('ub154ImportText'),headers=type==='products'?productHeader:employeeHeader,p=parsePaste(ta?.value,headers);state.ub154ImportPreview={type,...p};rerender()};
window.ub154CommitImport=function(type){const p=state.ub154ImportPreview;if(!p||p.type!==type||p.errors?.length){toastSafe('Import','Najpierw popraw dane i wykonaj walidację.');return}if(type==='employees'){const rows=p.rows.map(x=>({employeeId:x.employee_id,name:`${x.first_name} ${x.last_name}`.trim(),email:x.email,department:x.department,team:x.team,status:x.status||'active',program:x.program}));wr('upbonus.hr.employees.v96',rows);const c=cfg();c.imports.lastEmployeeImport=now().toISOString();save(c)}else{wr(`upbonus.products.import.v154.${tenant()}`,p.rows);const c=cfg();c.imports.lastProductImport=now().toISOString();save(c)}toastSafe('Import zakończony',`${p.rows.length} rekordów zapisano.`);notify({targetRole:type==='products'?'partner':'hr',icon:'⬆️',title:'Import zakończony',text:`${p.rows.length} rekordów`,route:'Importy danych'});state.ub154ImportPreview=null;rerender()};
function importView(partnerMode=false){const type=partnerMode?'products':(state.ub154ImportTab||'employees'),headers=type==='products'?productHeader:employeeHeader,p=state.ub154ImportPreview?.type===type?state.ub154ImportPreview:null;return `<div class="page-content ub154-page"><div class="page-head"><div><h1>${partnerMode?'Import produktów':'Importy danych'}</h1><p>Formatki zgodne z kopiowaniem z Excela / arkusza.</p></div></div>${partnerMode?'':`<div class="ub154-tabs"><button class="${type==='employees'?'active':''}" onclick="ub154ImportTab('employees')">Pracownicy</button><button class="${type==='products'?'active':''}" onclick="ub154ImportTab('products')">Produkty</button></div>`}<section class="ub154-card"><div class="ub154-toolbar"><div><b>${type==='products'?'Produkty i oferty':'Pracownicy'}</b><span class="ub154-status">${headers.length} kolumn</span></div><div><button class="secondary-btn" onclick="ub154CopyTemplate('${type}')">Kopiuj formatkę</button><button class="secondary-btn" onclick="ub154DownloadTemplate('${type}')">CSV</button></div></div><div class="ub154-code">${E(headers.join('    |    '))}</div><div class="ub154-import-preview" style="margin-top:14px"><div><label>Wklej dane z Excela<textarea id="ub154ImportText" placeholder="${E(tpl(type))}"></textarea></label><div class="ub154-actions"><button class="primary-btn" onclick="ub154ValidateImport('${type}')">Waliduj dane</button></div></div><div>${p?`<div class="ub154-card"><b>Walidacja</b>${p.errors?.length?`<p style="color:#a32525">${p.errors.map(E).join('<br>')}</p>`:`<p>${p.rows.length} rekordów gotowych do importu.</p><button class="primary-btn" onclick="ub154CommitImport('${type}')">Importuj ${p.rows.length} rekordów</button>`}</div>`:'<div class="ub154-card"><b>Podgląd importu</b><p>Po walidacji zobaczysz liczbę rekordów i błędy kolumn.</p></div>'}</div></div></section></div>`}

/* ---------- security / RODO ---------- */
window.ub154Security=function(k,v){const c=cfg();c.security[k]=v;save(c);rerender()};
function securityView(){const s=cfg().security;return `<div class="page-content ub154-page"><div class="page-head"><div><h1>Bezpieczeństwo i prywatność</h1><p>Ustawienia dla ${E(tenant())}.</p></div></div><div class="ub154-security-grid"><section class="ub154-card"><b>Dostęp</b><div class="ub154-switches" style="margin-top:10px"><label><span>SSO</span><input type="checkbox" ${s.sso?'checked':''} onchange="ub154Security('sso',this.checked)"></label><label><span>MFA wymagane</span><input type="checkbox" ${s.mfa?'checked':''} onchange="ub154Security('mfa',this.checked)"></label><label><span>Samodzielna rejestracja pracownika</span><input type="checkbox" ${s.employeeSelfRegistration?'checked':''} onchange="ub154Security('employeeSelfRegistration',this.checked)"></label></div></section><section class="ub154-card"><b>Sesja i audyt</b><div class="ub154-form" style="margin-top:10px"><label>Sesja (min)<input type="number" value="${s.sessionMinutes}" onchange="ub154Security('sessionMinutes',Number(this.value))"></label><label>Retencja (mies.)<input type="number" value="${s.retentionMonths}" onchange="ub154Security('retentionMonths',Number(this.value))"></label><label class="wide">Kontakt DPO<input value="${E(s.privacyContact)}" onchange="ub154Security('privacyContact',this.value)"></label></div></section></div><div class="ub154-grid" style="margin-top:14px"><article class="ub154-card"><span>TENANT</span><b>${E(tenant())}</b><p>Konfiguracja, dane i branding zapisywane per klient.</p></article><article class="ub154-card"><span>AUDYT</span><b>${s.audit?'Włączony':'Wyłączony'}</b><p>Zmiany procesowe mają identyfikator i czas wykonania.</p></article><article class="ub154-card"><span>RODO</span><b>${s.retentionMonths} mies.</b><p>Okres retencji ustawiony przez klienta.</p></article></div></div>`}

/* ---------- menu / routing ---------- */
function ensureMenus(){
  try{
    if(ROLE_DEFS?.hr){const m=ROLE_DEFS.hr.menu||[];const add=(route,icon)=>{if(!m.some(x=>x[0]===route))m.push([route,icon])};add('Projekty i zadania','layers');add('Microsoft 365 i Teams','api');add('Rejestracja czasu pracy','calendar');add('Importy danych','upload');add('Bezpieczeństwo i RODO','shield');add('Personalizacja platformy','settings');ROLE_DEFS.hr.menu=m}
    if(ROLE_DEFS?.partner){const m=ROLE_DEFS.partner.menu||[];if(!m.some(x=>x[0]==='Import produktów'))m.splice(Math.min(3,m.length),0,['Import produktów','upload']);ROLE_DEFS.partner.menu=m}
    if(ROLE_DEFS?.employee&&cfg().modules.timeTracking){const m=ROLE_DEFS.employee.menu||[];if(!m.some(x=>x[0]==='Rejestracja czasu pracy'))m.push(['Rejestracja czasu pracy','calendar'])}
  }catch(e){}
}
function installRender(){
  if(window.__ub154RenderInstalled)return;
  if(typeof window.renderSection!=='function')return;
  const base=window.renderSection;
  const wrap=function(){
    if(state?.role==='hr'){
      if(state.section==='Microsoft 365 i Teams')return m365View();
      if(state.section==='Rejestracja czasu pracy')return hrTimeView();
      if(state.section==='Importy danych')return importView(false);
      if(state.section==='Bezpieczeństwo i RODO')return securityView();
      if(state.section==='Personalizacja platformy')return personalizationView();
    }
    if(state?.role==='employee'&&state.section==='Rejestracja czasu pracy')return employeeTimeView();
    if(state?.role==='partner'&&state.section==='Import produktów')return importView(true);
    return base.apply(this,arguments);
  };
  wrap.__ub154=true;
  wrap.__ub154Base=base;
  window.__ub154RenderInstalled=true;
  window.renderSection=wrap;
}

function install(){applyUi();ensureMenus();installRender()}
let q=false;function refresh(){if(q)return;q=true;requestAnimationFrame(()=>{q=false;install()})}
new MutationObserver(refresh).observe(document.documentElement,{subtree:true,childList:true});
window.addEventListener('load',install,{once:true});setTimeout(install,120);setTimeout(install,900);
document.documentElement.dataset.upbonusV154='enterprise';console.log('Up Bonus V154 enterprise ready');
})();


