/* ===== SOURCE: upbonus-v160-all-modules.js ===== */
/* ==========================================================
   UP BONUS V160 — ALL MODULES ON + PERSONALISATION ROUTE FIX
   Presentation mode: enables every designed module for every
   client currently known by the prototype and fixes the
   personalised-gifts shop entry points.
========================================================== */
(function(){
  'use strict';

  const FEATURE_IDS=[
    'discounts','gifts','codes','specialOffers','personalization','service',
    'wallet','marketplace','requests','zfss','surveys','communication','community',
    'employerPerks','wellbeing','challenges','recognition','trs','integrations'
  ];
  const BLOCK_IDS=[
    'campaign','giftPool','favorites','top','brands','recommended','newest','recent',
    'employerPerks','community','kudosProgress'
  ];
  const ENTERPRISE_MODULES={m365:true,projects:true,timeTracking:true,imports:true,security:true};
  const ALL_ROLES=['employee','hr','operations','partner','finance','bok','campaigns','superadmin','giftstore'];

  const read=(k,d)=>{try{const v=JSON.parse(localStorage.getItem(k)||'null');return v??d}catch(e){return d}};
  const write=(k,v)=>{try{localStorage.setItem(k,JSON.stringify(v))}catch(e){}};
  const renderSafe=()=>{try{typeof render==='function'&&render()}catch(e){}};

  function knownClientIds(){
    const ids=new Set(['upbonus','TEN-001','TEN-002','TEN-003','TEN-004','TEN-005']);
    try{Object.keys(read('upbonus.clientFeatureConfig.v40',{})).forEach(x=>ids.add(String(x)))}catch(e){}
    try{Object.keys(read('upbonus.enterprise.v154',{})).forEach(x=>ids.add(String(x)))}catch(e){}
    try{(state?.v47?.clients||[]).forEach(c=>ids.add(String(c.id||c.tenantId||c.key||'')))}catch(e){}
    try{if(typeof SAMPLE_CLIENTS!=='undefined'&&Array.isArray(SAMPLE_CLIENTS))SAMPLE_CLIENTS.forEach(c=>ids.add(String(c.id||c.tenantId||c.key||'')))}catch(e){}
    try{ids.add(String(state?.tenant||''));ids.add(String(state?.clientId||''));ids.add(String(state?.v47?.currentClientId||''))}catch(e){}
    return [...ids].filter(Boolean);
  }

  function enableSystemModules(){
    const sys=read('upbonus.system.modules.v73',{});
    FEATURE_IDS.forEach(id=>sys[id]=true);
    write('upbonus.system.modules.v73',sys);

    const cfg=read('upbonus.system.config.v74',{});
    cfg.packages=cfg.packages||{};
    ['essential','flex','one'].forEach(pkg=>{
      cfg.packages[pkg]=cfg.packages[pkg]||{};
      cfg.packages[pkg].modules=[...FEATURE_IDS];
    });
    /* Do not switch experimental feature flags here. Modules are on,
       but unstable experiments remain governed separately. */
    if(Array.isArray(cfg.categories)) cfg.categories=cfg.categories.map(x=>({...x,active:true}));
    write('upbonus.system.config.v74',cfg);
  }

  function enableClientModules(){
    const all=read('upbonus.clientFeatureConfig.v40',{});
    knownClientIds().forEach(id=>{
      const old=all[id]||{};
      const features={...(old.features||{})};FEATURE_IDS.forEach(f=>features[f]=true);
      const blocks={...(old.blocks||{})};BLOCK_IDS.forEach(b=>blocks[b]=true);
      all[id]={...old,package:'custom',features,blocks,engagementSchema:55,updatedAt:new Date().toISOString()};
    });
    write('upbonus.clientFeatureConfig.v40',all);
  }

  function enableEnterpriseModules(){
    const all=read('upbonus.enterprise.v154',{});
    knownClientIds().forEach(id=>{
      const old=all[id]||{};
      all[id]={
        ...old,
        modules:{...(old.modules||{}),...ENTERPRISE_MODULES},
        time:{requireApproval:true,rounding:5,allowManual:true,allowProjects:true,...(old.time||{})},
        security:{sso:true,mfa:true,audit:true,employeeSelfRegistration:false,...(old.security||{})}
      };
    });
    write('upbonus.enterprise.v154',all);
  }

  function enableRoleAccess(){
    try{
      state.accesses=Array.from(new Set([...(state.accesses||[]),...ALL_ROLES]));
    }catch(e){}
    try{
      if(typeof USER_ACCESS!=='undefined'&&USER_ACCESS){
        Object.values(USER_ACCESS).forEach(u=>{if(u&&typeof u==='object')u.accesses=[...ALL_ROLES]});
      }
    }catch(e){}
  }

  function routePersonalisation(){
    try{
      if(document.getElementById('moduleShell')) return;
      if(typeof window.openModule==='function'){
        window.openModule('gift');
        return;
      }
      console.warn('V178: Up Bonus Gifts module is not available');
    }catch(e){console.warn('V178 personalisation route',e)}
  }
  window.ub160OpenPersonalisation=routePersonalisation;

  function patchSectionRouting(){
    if(window.__ub160RoutingInstalled)return;
    let installed=false;
    if(typeof window.selectSection==='function'&&!window.selectSection.__ub160){
      const base=window.selectSection;
      const wrap=function(section){
        const s=String(section||'').trim();
        if(/^(Sklep z personalizacjami|Sklep personalizowanych prezentów|Personalizacja prezentów|Personalizowane karty)$/i.test(s)){
          routePersonalisation();return;
        }
        return base.apply(this,arguments);
      };
      wrap.__ub160=true;
      window.selectSection=wrap;
      installed=true;
    }
    if(installed)window.__ub160RoutingInstalled=true;
  }

  const MENU_LINKS={
    'Twoje benefity':[
      ['Kody i promocje','🎟️','Kody i promocje'],
      ['Personalizowane karty','🎨','Sklep z personalizacjami']
    ],
    'Dla Ciebie':[
      ['Punkty i nagrody','🙌','Docenianie'],
      ['Wynagrodzenie i benefity','📊','Wynagrodzenie i benefity']
    ],
    'Firma':[
      ['Rozwój i kariera','📚','Rozwój i kariera'],
      ['Rejestracja czasu pracy','⏱️','Czas pracy'],
      ['Aplikacje i urządzenia','🔗','Aplikacje i integracje']
    ]
  };

  function makeNav(route,icon,label){
    const b=document.createElement('button');
    b.className='ub40-nav-item ub160-all-module-link';
    b.dataset.ub160Route=route;
    b.innerHTML=`<span class="ub40-nav-emoji" aria-hidden="true">${icon}</span><span>${label}</span>`;
    b.onclick=()=>route==='Personalizowane karty'?routePersonalisation():(typeof selectSection==='function'?selectSection(route):(state.section=route,renderSafe()));
    return b;
  }

  function ensureEmployeeMenu(){ /* v162 owns employee menu */ }

  function patchPersonalisationButtons(){
    document.querySelectorAll('button,a').forEach(el=>{
      const t=(el.textContent||'').replace(/\s+/g,' ').trim();
      if(/Sklep z personalizacjami|Sklep personalizowanych prezentów|Personalizuj/i.test(t)){
        if(el.dataset.ub160Personal==='1')return;
        el.dataset.ub160Personal='1';
        el.addEventListener('click',function(e){
          e.preventDefault();e.stopPropagation();e.stopImmediatePropagation();routePersonalisation();
        },true);
      }
    });
  }

  function applyAll(){
    enableSystemModules();
    enableClientModules();
    enableEnterpriseModules();
    enableRoleAccess();
    patchSectionRouting();
    ensureEmployeeMenu();
    patchPersonalisationButtons();
    document.documentElement.dataset.ubAllModules='on';
  }

  let scheduled=false;
  function schedule(){
    if(scheduled)return;scheduled=true;
    requestAnimationFrame(()=>{scheduled=false;applyAll()});
  }

  applyAll();
  window.addEventListener('load',()=>{applyAll();setTimeout(()=>{applyAll();renderSafe()},80)},{once:true});
  setTimeout(()=>{applyAll();renderSafe()},250);
  setTimeout(applyAll,1000);
  new MutationObserver(schedule).observe(document.documentElement,{subtree:true,childList:true});
  console.log('Up Bonus V160: all modules enabled; personalisation shop route fixed');
})();


