/* ===== SOURCE: upbonus-v167-menu-restore.js ===== */
/* ==========================================================
   UP BONUS V173 — employee menu, flat / always visible
   - no accordion
   - all modules visible in compact grouped navigation
   - one combined Kudos + Docenianie entry
========================================================== */
(function(){
  'use strict';

  const GROUPS=[
    {name:'Benefity',items:[
      ['Moje środki','Portfel i środki','💳'],
      ['Benefity','Katalog benefitów','🎁'],
      ['Abonamenty','Abonamenty','🔁']
    ]},
    {name:'Dla Ciebie',items:[
      ['Nie przegap','Nie przegap','🔥'],
      ['Wellbeing','Wellbeing','🌿'],
      ['Wyzwania i nagrody','Wyzwania i nagrody','🏆'],
      ['Moje sprawy','Zakupy i historia','📄'],
      ['Kudos i docenianie','Punkty i nagrody','👏'],
      ['Wynagrodzenie i benefity','Wynagrodzenie i benefity','📊']
    ]},
    {name:'Praca',items:[
      ['Projekty','Projekty','🗂️'],
      ['Rozwój i kariera','Rozwój i kariera','📚'],
      ['Czas pracy','Rejestracja czasu pracy','⏱️'],
      ['Aplikacje i integracje','Aplikacje i urządzenia','🔗']
    ]},
    {name:'Firma',items:[
      ['Wnioski','Wnioski i świadczenia','📋'],
      ['Ankiety','Ankiety','💬'],
      ['Aktualności','Aktualności','📣'],
      ['Społeczność','Społeczność','👥']
    ]}
  ];

  const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const isEmployee=()=>String(window.state?.role||'')==='employee'||/#panel\/employee\//i.test(location.hash);
  const activeRoute=()=>String(window.state?.section||'');

  function go(route,label){
    if(route==='Personalizowane karty' && typeof window.ub160OpenPersonalisation==='function') return window.ub160OpenPersonalisation();
    if(typeof window.ub35SelectNav==='function') return window.ub35SelectNav(route,label);
    if(typeof window.selectSection==='function') return window.selectSection(route);
    if(window.state){window.state.section=route;try{window.render?.()}catch(e){}}
  }

  function makeItem(label,route,icon){
    const b=document.createElement('button');
    b.type='button';
    b.className='ub40-nav-item ub173-nav-item';
    b.dataset.route=route;
    if(activeRoute()===route || activeRoute()===label) b.classList.add('is-active');
    b.innerHTML=`<span class="ub40-nav-emoji" aria-hidden="true">${icon}</span><span>${esc(label)}</span>`;
    b.onclick=()=>go(route,label);
    return b;
  }

  function build(){
    if(!isEmployee())return;
    const nav=document.querySelector('.ub40-nav,.sidebar-menu');
    if(!nav)return;

    const signature='v173-flat-'+GROUPS.flatMap(g=>g.items.map(x=>x[0])).join('|');
    if(nav.dataset.ub173Signature===signature){
      nav.querySelectorAll('.ub173-nav-item').forEach(btn=>btn.classList.toggle('is-active',btn.dataset.route===activeRoute()));
      return;
    }

    nav.innerHTML='';
    const start=makeItem('Start','Pulpit','🏠');
    start.classList.add('ub173-start');
    nav.appendChild(start);

    GROUPS.forEach(group=>{
      const sec=document.createElement('section');
      sec.className='ub173-nav-group';
      sec.innerHTML=`<div class="ub173-nav-label">${esc(group.name)}</div><div class="ub173-nav-items"></div>`;
      const body=sec.querySelector('.ub173-nav-items');
      group.items.forEach(([label,route,icon])=>body.appendChild(makeItem(label,route,icon)));
      nav.appendChild(sec);
    });

    // Make older accordion observers consider the navigation complete.
    nav.dataset.ub162Ready='1';
    nav.dataset.ub167Signature=GROUPS.flatMap(g=>g.items.map(x=>x[0])).join('|');
    nav.dataset.ub173Signature=signature;
  }

  let pending=false;
  function schedule(){if(pending)return;pending=true;requestAnimationFrame(()=>{pending=false;build()})}
  build();
  window.addEventListener('load',()=>{build();setTimeout(build,120);setTimeout(build,650)},{once:true});
  new MutationObserver(schedule).observe(document.documentElement,{subtree:true,childList:true});
})();


