/* ===== SOURCE: upbonus-v197-clean-runtime.js ===== */
/* UP BONUS V197 — minimal runtime cleanup. No DOM injectors, no layout rewrites. */
(function(){
  'use strict';
  if(window.__ub197CleanLoaded) return;
  window.__ub197CleanLoaded=true;

  function markRole(){
    const m=location.hash.match(/#panel\/([^/]+)/i);
    const role=m?.[1]||window.state?.role||'';
    if(role) document.body.dataset.role=role;
  }

  function removeDuplicateBranding(){
    const top=document.querySelector('.employee-topbar,.topbar,header');
    if(!top) return;
    const logos=[...top.querySelectorAll('img[alt*="Up Bonus" i],.topbar-brand,.ub166-approved-brand')];
    logos.slice(1).forEach(el=>{
      const holder=el.closest('.topbar-brand,.ub166-approved-brand')||el;
      if(holder!==logos[0]) holder.remove();
    });
    [...top.querySelectorAll('small,span,b')].forEach(el=>{
      if(/^Portal pracownika$/i.test((el.textContent||'').trim())) el.remove();
    });
  }

  function apply(){markRole();removeDuplicateBranding();}
  let raf=0;
  function schedule(){if(raf)return;raf=requestAnimationFrame(()=>{raf=0;apply();});}
  apply();
  addEventListener('hashchange',apply);
  addEventListener('load',()=>{apply();setTimeout(apply,250)},{once:true});
  new MutationObserver(schedule).observe(document.documentElement,{subtree:true,childList:true});
})();


