/* ==========================================================
   UP BONUS V198 — PANEL CONNECTIVITY / BOK RECOVERY
   One place owns role entry and BOK routing.
========================================================== */
(function(){
  'use strict';
  if(window.__ub198PanelsLoaded) return;
  window.__ub198PanelsLoaded = true;

  const ROLE_START = {
    employee:'Pulpit',
    hr:'Pulpit HR',
    partner:'Pulpit partnera',
    finance:'Dashboard finansowy',
    bok:'Pulpit BOK',
    campaigns:'Pulpit kampanii',
    superadmin:'Pulpit systemu'
  };

  const BOK_MENU = [
    ['Pulpit BOK','home'],
    ['Centrum zamówień','order'],
    ['Reklamacje','alert'],
    ['Zlecenia wyksięgowań','refresh'],
    ['Magazyn kart i kodów','database'],
    ['Katalog i oferty','shop'],
    ['Wyszukiwarka globalna','search'],
    ['Wymiany kodów','refresh'],
    ['Ponowne wysyłki','mail'],
    ['Historia klienta','user'],
    ['Terminy i eskalacje','chart']
  ];

  function ensureRoleDefs(){
    if(!window.ROLE_DEFS) return;
    if(window.ROLE_DEFS.bok){
      window.ROLE_DEFS.bok.name='BOK i reklamacje';
      window.ROLE_DEFS.bok.menu=BOK_MENU.map(x=>[...x]);
    }
  }

  function safeCall(name,args=[]){
    try{
      const fn=window[name];
      if(typeof fn==='function') return fn.apply(window,args);
    }catch(e){
      console.error('V198 route error',name,e);
    }
    return null;
  }

  function cleanHtml(v){
    return typeof v==='string' && v.trim() ? v : null;
  }

  function renderBokSection(section){
    const sec=String(section||'Pulpit BOK');

    if(sec==='Pulpit BOK'){
      return cleanHtml(safeCall('bok66Dashboard')) ||
             cleanHtml(safeCall('genericDashboard',['bok']));
    }
    if(sec==='Centrum zamówień'){
      return cleanHtml(safeCall('connectedOrdersView')) ||
             cleanHtml(safeCall('ordersView'));
    }
    if(sec==='Reklamacje'){
      return cleanHtml(safeCall('complaintsOps24')) ||
             cleanHtml(safeCall('bok66ListView',['Reklamacje'])) ||
             cleanHtml(safeCall('supportFlowView',['Reklamacje']));
    }
    if(sec==='Zlecenia wyksięgowań'){
      return cleanHtml(safeCall('bokWriteoffs76')) ||
             cleanHtml(safeCall('bok66ListView',['Zwroty i korekty']));
    }
    if(sec==='Katalog i oferty'){
      return cleanHtml(safeCall('catalogView'));
    }
    if(sec==='Wyszukiwarka globalna'){
      return cleanHtml(safeCall('globalSearchViewV3')) ||
             cleanHtml(safeCall('globalSearchView'));
    }
    if(sec==='Wymiany kodów'){
      return cleanHtml(safeCall('supportFlowView',['Wymiany kodów'])) ||
             cleanHtml(safeCall('bok66ListView',['Zwroty i korekty']));
    }
    if(sec==='Ponowne wysyłki'){
      return cleanHtml(safeCall('supportFlowView',['Ponowne wysyłki']));
    }
    if(sec==='Historia klienta'){
      return cleanHtml(safeCall('supportFlowView',['Historia klienta'])) ||
             cleanHtml(safeCall('bok66HistoryView'));
    }
    if(sec==='Terminy i eskalacje'){
      return cleanHtml(safeCall('supportFlowView',['SLA i eskalacje'])) ||
             cleanHtml(safeCall('bok66ReportsView'));
    }
    return null;
  }

  function installRenderGuard(){
    if(window.renderSection?.__ub198) return;
    const base=window.renderSection;
    if(typeof base!=='function') return;

    function guardedRenderSection(){
      const role=String(window.state?.role||'');
      const sec=String(window.state?.section||'');

      if(role==='bok'){
        const html=renderBokSection(sec);
        if(html) return html;
      }

      try{
        const html=base.apply(this,arguments);
        if(typeof html==='string' && html.trim()) return html;
      }catch(e){
        console.error('V198 base renderSection failed',role,sec,e);
      }

      const first=ROLE_START[role]||'Start';
      return `<div class="page-content"><div class="page-head"><div><h1>${first}</h1><p>Widok panelu jest dostępny z menu po lewej stronie.</p></div></div></div>`;
    }
    guardedRenderSection.__ub198=true;
    guardedRenderSection.__base=base;
    window.renderSection=guardedRenderSection;
  }

  function installSectionGuard(){
    if(window.selectSection?.__ub198) return;
    const base=window.selectSection;
    if(typeof base!=='function') return;

    function guardedSelectSection(label){
      const role=String(window.state?.role||'');
      let sec=String(label||'').trim();

      // V199 may visually translate menu labels. Routing must always use the
      // canonical Polish route key expected by the existing platform renderers.
      try{
        if(typeof window.ub199Canonical==='function'){
          sec=window.ub199Canonical(sec);
        }
      }catch(e){}

      if(role==='bok' && sec==='Magazyn kart i kodów'){
        try{
          if(typeof window.openModule==='function'){
            window.openModule('inventory');
            return;
          }
        }catch(e){}
      }

      // IMPORTANT: delegate to the complete pre-V198 routing chain.
      // It contains module-specific routes (gift shop, employee modules,
      // HR/client views, finance, Super Admin, etc.). V198 previously bypassed
      // that chain by writing state.section + render() directly, which broke
      // sidebar sections that require route side-effects.
      try{
        return base.call(this,sec);
      }catch(e){
        console.error('V200 selectSection base route failed',role,sec,e);

        // Last-resort safe fallback only if the legacy router itself throws.
        if(window.state){
          window.state.section=sec;
          window.state.mobileMenu=false;
        }
        try{ typeof window.persist==='function' && window.persist(); }catch(_){}
        try{ typeof window.render==='function' && window.render(); }catch(_){}
      }
    }
    guardedSelectSection.__ub198=true;
    guardedSelectSection.__base=base;
    window.selectSection=guardedSelectSection;
  }

  function installOpenRoleGuard(){
    if(window.openRole?.__ub198) return;
    const base=window.openRole;

    function guardedOpenRole(role){
      role=String(role||'');
      if(!ROLE_START[role]){
        if(typeof base==='function') return base.apply(this,arguments);
        return;
      }

      window.state=window.state||{};
      state.loggedIn=true;
      state.role=role;
      state.section=ROLE_START[role];
      state.mobileMenu=false;
      state.modal=null;
      state.drawer=null;

      try{ typeof window.persist==='function' && window.persist(); }catch(e){}
      try{
        history.pushState({role},'',`#panel/${encodeURIComponent(role)}/${encodeURIComponent(state.section)}/${encodeURIComponent(state.tenant||'upbonus')}`);
      }catch(e){}

      try{ typeof window.render==='function' && window.render(); }
      catch(e){ console.error('V198 openRole render',role,e); }
    }
    guardedOpenRole.__ub198=true;
    guardedOpenRole.__base=base;
    window.openRole=guardedOpenRole;

    // V187 dropdown calls its own function, so make it use the same role entry.
    window.ub187OpenRole=guardedOpenRole;
  }

  function fixCurrentRoleIfNeeded(){
    const role=String(window.state?.role||'');
    if(!ROLE_START[role]) return;
    const def=window.ROLE_DEFS?.[role];
    if(!window.state.section || (def?.menu?.length && !def.menu.some(x=>x?.[0]===window.state.section))){
      // Keep known extended employee/HR routes; only normalize broken panel entry routes.
      if(role==='bok' || !window.state.section) window.state.section=ROLE_START[role];
    }
  }

  function apply(){
    ensureRoleDefs();
    installRenderGuard();
    installSectionGuard();
    installOpenRoleGuard();
    fixCurrentRoleIfNeeded();
  }

  apply();
  window.addEventListener('load',()=>{apply();setTimeout(apply,100);setTimeout(apply,600)},{once:true});
})();


