/* UP BONUS V200 — SIDEBAR ROUTING RECOVERY */
(function(){
  'use strict';
  if(window.__ub200SidebarRecoveryLoaded) return;
  window.__ub200SidebarRecoveryLoaded=true;

  function check(){
    // Keep body role marker synchronized for role-specific UI.
    try{
      const role=String(window.state?.role||'');
      if(role) document.body.dataset.role=role;
    }catch(e){}

    // Mark menu buttons as native controls; translation changes display only,
    // never their route key / onclick.
    document.querySelectorAll(
      '.sidebar-menu button,.menu-btn,.ub67-client-nav-item,.ub66-bok-nav-item,.ub69-super-nav-item'
    ).forEach(btn=>{
      if(!btn.getAttribute('type')) btn.setAttribute('type','button');
    });
  }

  if(document.readyState==='loading'){
    document.addEventListener('DOMContentLoaded',check,{once:true});
  }else check();

  window.addEventListener('load',()=>{check();setTimeout(check,150);setTimeout(check,700)},{once:true});
})();


