/* ==========================================================
   UP BONUS V213 — PERSISTENT UI LANGUAGE + DEEPL
   Fixes language loss on #accounts/login and between panels.
========================================================== */
(function(){
  'use strict';
  if(window.__ub213Loaded) return;
  window.__ub213Loaded=true;

  const UI_LANG_KEY='upbonus.ui.lang.v213';
  const SUPPORTED=new Set(['pl','en','de','fr']);

  function norm(v){
    const l=String(v||'').trim().toLowerCase();
    return SUPPORTED.has(l)?l:null;
  }

  function initialLanguage(){
    const candidates=[
      localStorage.getItem(UI_LANG_KEY),
      localStorage.getItem('upbonus_lang'),
      window.state && window.state.lang,
      document.documentElement.lang
    ];
    for(const c of candidates){
      const l=norm(c);
      if(l) return l;
    }
    return 'pl';
  }

  let uiLang=initialLanguage();
  localStorage.setItem(UI_LANG_KEY,uiLang);

  function keep(){
    const current=norm(localStorage.getItem(UI_LANG_KEY))||uiLang||'pl';
    uiLang=current;
    document.documentElement.lang=current;
    return current;
  }

  // Make V212 read the persistent UI language first.
  try{
    Object.defineProperty(window,'__ub213UiLanguage',{
      configurable:true,
      get(){ return keep(); }
    });
  }catch(_){}

  // Intercept every language change and persist it independently from session/role state.
  const previousSet=window.setLanguage;
  window.setLanguage=function(value){
    const next=norm(value);
    if(!next) return;
    uiLang=next;
    localStorage.setItem(UI_LANG_KEY,next);
    localStorage.setItem('upbonus_lang',next);
    if(window.state) window.state.lang=next;
    document.documentElement.lang=next;

    let result;
    if(typeof previousSet==='function'){
      result=previousSet.call(this,next);
    }else if(typeof window.render==='function'){
      result=window.render();
    }

    setTimeout(()=>window.ub212TranslateNow?.(),0);
    setTimeout(()=>window.ub212TranslateNow?.(),80);
    setTimeout(()=>window.ub212TranslateNow?.(),250);
    return result;
  };

  // Capture select changes before legacy handlers can reset the language.
  window.addEventListener('change',function(e){
    const el=e.target;
    if(!el?.matches?.('.ub-lang-select,.v28-language-select,[data-language-select],select[name="language"]')) return;
    const next=norm(el.value);
    if(!next) return;
    uiLang=next;
    localStorage.setItem(UI_LANG_KEY,next);
    localStorage.setItem('upbonus_lang',next);
    if(window.state) window.state.lang=next;
    document.documentElement.lang=next;
  },true);

  function restore(){
    const l=keep();
    localStorage.setItem('upbonus_lang',l);
    if(window.state) window.state.lang=l;
    document.documentElement.lang=l;

    document.querySelectorAll(
      '.ub-lang-select,.v28-language-select,[data-language-select],select[name="language"]'
    ).forEach(sel=>{
      try{
        const opt=[...sel.options].find(o=>norm(o.value)===l);
        if(opt) sel.value=opt.value;
      }catch(_){}
    });

    setTimeout(()=>window.ub212TranslateNow?.(),0);
  }

  // Session/account screens can recreate state with PL; restore UI language afterwards.
  ['render','openRole','selectSection','openModule','logout','openAccounts'].forEach(name=>{
    const fn=window[name];
    if(typeof fn!=='function'||fn.__ub213Wrapped) return;
    function wrapped(){
      const wanted=keep();
      const result=fn.apply(this,arguments);
      uiLang=wanted;
      localStorage.setItem(UI_LANG_KEY,wanted);
      localStorage.setItem('upbonus_lang',wanted);
      if(window.state) window.state.lang=wanted;
      queueMicrotask(restore);
      setTimeout(restore,60);
      return result;
    }
    wrapped.__ub213Wrapped=true;
    wrapped.__base=fn;
    window[name]=wrapped;
  });

  window.addEventListener('hashchange',()=>setTimeout(restore,20));
  window.addEventListener('popstate',()=>setTimeout(restore,20));
  window.addEventListener('load',restore,{once:true});

  if(document.readyState==='loading'){
    document.addEventListener('DOMContentLoaded',restore,{once:true});
  }else restore();

  window.ub213LanguageStatus=function(){
    return {
      uiLanguage:keep(),
      stateLanguage:window.state&&window.state.lang,
      legacyStorage:localStorage.getItem('upbonus_lang'),
      route:location.hash
    };
  };
})();

