if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot,{once:true});else boot();
window.addEventListener('hashchange',burst);window.addEventListener('popstate',burst);window.addEventListener('load',burst,{once:true});
window.ub212Status=async()=>{let api;try{api=await (await fetch('/api/deepl-translate')).json()}catch(e){api={error:String(e)}}return{language:lang(),cached:Object.keys(cache).length,queued:q.size,api}};
