/* ===== SOURCE: upbonus-v219-notifications.js ===== */
/* ==========================================================
   UP BONUS V219 — CLEAN SINGLE-LAYER NOTIFICATIONS
   Old V189 layer removed from project and index.
========================================================== */
(function(){
  'use strict';
  if(window.__ub219NotificationsLoaded) return;
  window.__ub219NotificationsLoaded=true;

  const KEY='upbonus.notifications.v117';
  const DELETED_KEY='upbonus.notifications.deleted.v219';

  const esc=s=>String(s??'').replace(/[&<>"']/g,m=>({
    '&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'
  }[m]));

  function read(k,d){
    try{const v=JSON.parse(localStorage.getItem(k)||'null');return v??d}catch(_){return d}
  }
  function write(k,v){
    try{localStorage.setItem(k,JSON.stringify(v))}catch(_){}
  }
  function tombstones(){
    return new Set((read(DELETED_KEY,[])||[]).map(String));
  }
  function role(){
    return String(window.state?.role||'employee');
  }
  function userIds(){
    const u=window.state?.user||{};
    return new Set([u.employeeId,u.id,u.email,u.name,'employee-current'].filter(Boolean).map(String));
  }
  function visibleForUser(n){
    const r=role();
    if(n?.targetRole && String(n.targetRole)!==r && r!=='superadmin') return false;
    if(r==='employee' && n?.targetUserId && !userIds().has(String(n.targetUserId))) return false;
    return true;
  }

  function allRows(){
    const deleted=tombstones();
    const rows=[];
    const stored=read(KEY,[]);
    if(Array.isArray(stored)) stored.forEach(n=>rows.push({...n}));

    const legacy=window.state?.v27?.notifications;
    if(Array.isArray(legacy)){
      legacy.forEach(n=>{
        if(!n?.id) return;
        if(!rows.some(x=>String(x.id)===String(n.id))) rows.push({...n});
      });
    }

    return rows.filter(n=>n?.id && !deleted.has(String(n.id)));
  }

  function visibleRows(){
    return allRows().filter(visibleForUser);
  }

  function persistRows(rows){
    write(KEY,rows);

    if(window.state){
      state.v27=state.v27||{};
      state.v27.notifications=rows.filter(visibleForUser).map(n=>({...n}));
      state.notifications=rows.filter(visibleForUser).filter(n=>n.unread!==false).length;
    }

    try{typeof window.persist==='function'&&window.persist()}catch(_){}
    syncBadge();
  }

  function syncBadge(){
    const count=visibleRows().filter(n=>n.unread!==false).length;
    if(window.state) state.notifications=count;

    document.querySelectorAll(
      'button[title*="Powiad" i],button[aria-label*="Powiad" i],'+
      'button[title*="Notif" i],button[aria-label*="Notif" i]'
    ).forEach(btn=>{
      let badge=btn.querySelector('.badge-dot,.notification-badge,.badge');
      if(!badge && count){
        badge=document.createElement('span');
        badge.className='badge-dot';
        btn.appendChild(badge);
      }
      if(badge){
        badge.textContent=String(count);
        badge.style.display=count?'grid':'none';
      }
    });
  }

  function markRead(id){
    const rows=allRows();
    const n=rows.find(x=>String(x.id)===String(id));
    if(n) n.unread=false;
    persistRows(rows);
    return n;
  }

  function removeOne(id){
    const deleted=tombstones();
    deleted.add(String(id));
    write(DELETED_KEY,[...deleted].slice(-1500));
    persistRows(allRows().filter(n=>String(n.id)!==String(id)));
  }

  function clearAll(){
    const ids=new Set(visibleRows().map(n=>String(n.id)));
    const deleted=tombstones();
    ids.forEach(id=>deleted.add(id));
    write(DELETED_KEY,[...deleted].slice(-1500));
    persistRows(allRows().filter(n=>!ids.has(String(n.id))));
  }

  function clearNotificationDom(){
    document.querySelectorAll(
      '.ub219-notification-panel,.ub189-notification-panel,.ub185-notification-panel,'+
      '.ub153-notification-panel,.ub117-notification-panel,.notification-panel,'+
      '.notifications-panel,.notification-modal,.notifications-modal,'+
      '.notification-center,.notifications-center'
    ).forEach(el=>el.remove());
  }

  function closeActiveModal(){
    // Do not allow the cart/profile/old notifications modal to remain under the new panel.
    try{
      if(window.state?.modal){
        state.modal=null;
        if(typeof window.renderOverlay==='function') window.renderOverlay();
        else if(typeof window.closeModal==='function') window.closeModal();
      }
    }catch(_){}

    // Safety cleanup for legacy overlay HTML that can survive old state.
    document.querySelectorAll('.modal-backdrop').forEach(el=>el.remove());
  }

  function closeAll(){
    clearNotificationDom();
  }

  function destination(n){
    if(!n) return;
    closeAll();
    closeActiveModal();

    const section=String(n.route||n.section||'').trim();

    try{
      if(section && typeof window.selectSection==='function'){
        window.selectSection(section);
        return;
      }
      if(n.action==='wallet' && typeof window.selectSection==='function'){
        window.selectSection('Moje środki'); return;
      }
      if(n.action==='news' && typeof window.selectSection==='function'){
        window.selectSection('Aktualności'); return;
      }
      if(n.action==='gift'){
        if(typeof window.ub117OpenGiftFlow==='function'){
          window.ub117OpenGiftFlow(n.entityId); return;
        }
        if(typeof window.openModule==='function'){
          window.openModule('gift'); return;
        }
      }
      if(n.module && typeof window.openModule==='function'){
        window.openModule(n.module);
      }
    }catch(e){
      console.error('V219 notification navigation failed',e,n);
    }
  }

  function renderPanel(){
    closeAll();
    closeActiveModal();

    const rows=visibleRows();
    const panel=document.createElement('aside');
    panel.className='ub219-notification-panel';
    panel.setAttribute('role','dialog');
    panel.setAttribute('aria-label','Powiadomienia');

    panel.innerHTML=`
      <div class="ub219-head">
        <div>
          <b>Powiadomienia</b>
          <small>${rows.filter(n=>n.unread!==false).length} nieprzeczytane</small>
        </div>
        <button type="button" data-close aria-label="Zamknij">×</button>
      </div>

      <div class="ub219-list">
        ${rows.length ? rows.map(n=>`
          <article data-id="${esc(n.id)}" class="${n.unread===false?'is-read':'is-unread'}">
            <button type="button" class="ub219-content">
              <span class="ub219-icon">${esc(n.icon||'🔔')}</span>
              <span class="ub219-copy">
                <b>${esc(n.title||'Powiadomienie')}</b>
                <small>${esc(n.text||n.message||'')}</small>
                <em>${esc(n.time||'')}</em>
              </span>
            </button>
            <div class="ub219-actions">
              <button type="button" class="ub219-open">Otwórz</button>
              <button type="button" class="ub219-delete" title="Usuń" aria-label="Usuń">×</button>
            </div>
          </article>
        `).join('') : '<div class="ub219-empty">Brak powiadomień.</div>'}
      </div>

      <div class="ub219-foot">
        <button type="button" data-clear ${rows.length?'':'disabled'}>Wyczyść wszystkie</button>
      </div>
    `;

    document.body.appendChild(panel);

    panel.querySelector('[data-close]')?.addEventListener('click',closeAll);

    panel.querySelector('[data-clear]')?.addEventListener('click',()=>{
      clearAll();
      renderPanel();
    });

    panel.querySelectorAll('article[data-id]').forEach(article=>{
      const id=article.dataset.id;

      const open=()=>{
        const n=markRead(id);
        destination(n);
      };

      article.querySelector('.ub219-content')?.addEventListener('click',e=>{
        e.preventDefault(); e.stopPropagation(); open();
      });

      article.querySelector('.ub219-open')?.addEventListener('click',e=>{
        e.preventDefault(); e.stopPropagation(); open();
      });

      article.querySelector('.ub219-delete')?.addEventListener('click',e=>{
        e.preventDefault(); e.stopPropagation();
        removeOne(id);
        renderPanel();
      });
    });
  }

  // Single public notification API.
  window.ub219OpenNotifications=renderPanel;
  window.ub219DeleteNotification=removeOne;
  window.ub219ClearNotifications=clearAll;

  // Direct overlay renderer compatibility:
  // some older flows set state.modal manually and call renderOverlay(),
  // bypassing showModal(). Close notifications before those overlays render.
  const baseRenderOverlay=window.renderOverlay;
  if(typeof baseRenderOverlay==='function' && !baseRenderOverlay.__ub220Wrapped){
    function renderOverlay220(){
      const type=String(window.state?.modal?.type||'');
      if(type && type!=='notifications'){
        closeAll();
      }
      return baseRenderOverlay.apply(this,arguments);
    }
    renderOverlay220.__ub220Wrapped=true;
    renderOverlay220.__base=baseRenderOverlay;
    window.renderOverlay=renderOverlay220;
  }

  // Route all legacy showModal('notifications') calls here.
  const baseShowModal=window.showModal;
  if(typeof baseShowModal==='function'){
    window.showModal=function(type){
      const modalType=String(type||'');

      if(modalType==='notifications'){
        renderPanel();
        return;
      }

      /*
        V220:
        każdy zwykły modal (koszyk, profil, produkt, płatność itd.)
        zamyka panel powiadomień PRZED renderem.
        Dzięki temu dwie warstwy nie mogą się już nałożyć.
      */
      closeAll();

      return baseShowModal.apply(this,arguments);
    };
  }

  // Capture bell before document-level legacy listeners.
  // V220.1: a click anywhere outside the notification panel closes it,
  // while the clicked control keeps working normally.
  window.addEventListener('click',e=>{
    const panel=document.querySelector('.ub219-notification-panel');
    const btn=e.target.closest?.('button');
    const meta=btn ? [btn.title||'',btn.getAttribute('aria-label')||'',btn.className||''].join(' ') : '';
    const isNotificationTrigger=!!btn && /powiad|notif/i.test(meta);

    if(panel && !panel.contains(e.target) && !isNotificationTrigger){
      closeAll();
      // Do not prevent/stop this event: user clicked another field/action
      // and that interaction should continue after notifications close.
    }

    if(!isNotificationTrigger) return;

    e.preventDefault();
    e.stopPropagation();
    e.stopImmediatePropagation();
    renderPanel();
  },true);

  // Escape closes only notification panel first.
  window.addEventListener('keydown',e=>{
    if(e.key==='Escape' && document.querySelector('.ub219-notification-panel')){
      e.preventDefault();
      e.stopImmediatePropagation();
      closeAll();
    }
  },true);

  // Deleted items must not be recreated by legacy state sync.
  function reconcile(){
    const deleted=tombstones();

    const stored=read(KEY,[]);
    if(Array.isArray(stored)){
      const clean=stored.filter(n=>n?.id && !deleted.has(String(n.id)));
      if(clean.length!==stored.length) write(KEY,clean);
    }

    if(window.state?.v27?.notifications){
      state.v27.notifications=state.v27.notifications.filter(
        n=>n?.id && !deleted.has(String(n.id))
      );
    }

    syncBadge();
  }

  reconcile();
  window.addEventListener('load',()=>{
    reconcile();
    setTimeout(reconcile,150);
    setTimeout(reconcile,700);
  },{once:true});
})();

