/* ===== SOURCE: upbonus-v228-final-ux.js ===== */
/* ==========================================================
   UP BONUS V228 — FINAL UX BEHAVIOUR
========================================================== */
(function(){
  'use strict';
  if(window.__ub228FinalUxLoaded) return;
  window.__ub228FinalUxLoaded=true;

  function cleanupContrast(){
    const legacy=[
      'ub-v10-dark','ub-v10-light','ub-v10-hero','ub-v10-premium',
      'ub-v10-premium-title','ub-v10-premium-item','ub-v10-wallet',
      'ub-v10-alert','ub-v10-alert-expiry','ub-v10-alert-request','ub-v10-login-dark'
    ];
    document.querySelectorAll('.'+legacy.join(',.')).forEach(el=>{
      legacy.forEach(c=>el.classList.remove(c));
    });
  }

  function syncUi(){
    cleanupContrast();
    try{ window.upbonusSyncBrand?.(); }catch(_){}
    try{
      if(window.state?.role) document.body.dataset.role=String(state.role);
    }catch(_){}
  }

  function closeEverything(){
    let changed=false;

    document.querySelectorAll(
      '.ub187-role-menu,.ub219-notification-panel,.ub218-notification-panel,'+
      '.ub189-notification-panel,.notification-panel,.notifications-panel,'+
      '.ub117-modal-backdrop,.modal-backdrop,.drawer-backdrop,'+
      '.ub153-modal-backdrop,.ub154-modal-backdrop'
    ).forEach(el=>{ el.remove(); changed=true; });

    try{
      if(window.state?.modal){ state.modal=null; changed=true; }
      if(window.state?.drawer){ state.drawer=null; changed=true; }
      if(window.state?.mobileMenu){ state.mobileMenu=false; changed=true; }
    }catch(_){}

    try{
      if(changed && typeof window.renderOverlay==='function') window.renderOverlay();
      else if(changed && typeof window.render==='function') window.render();
    }catch(_){}

    return changed;
  }

  window.ub228CloseEverything=closeEverything;

  window.addEventListener('keydown',e=>{
    if(e.key!=='Escape') return;
    if(closeEverything()){
      e.preventDefault();
      e.stopPropagation();
      e.stopImmediatePropagation();
    }
  },true);

  ['render','selectSection','openRole','openModule'].forEach(name=>{
    const fn=window[name];
    if(typeof fn!=='function'||fn.__ub228Wrapped) return;
    function wrapped(){
      const result=fn.apply(this,arguments);
      queueMicrotask(syncUi);
      setTimeout(syncUi,20);
      setTimeout(syncUi,120);
      return result;
    }
    wrapped.__ub228Wrapped=true;
    wrapped.__base=fn;
    window[name]=wrapped;
  });

  window.addEventListener('hashchange',()=>{setTimeout(syncUi,0);setTimeout(syncUi,80)});
  window.addEventListener('load',()=>{syncUi();setTimeout(syncUi,100)},{once:true});
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',syncUi,{once:true});else syncUi();

  new MutationObserver(()=>{
    requestAnimationFrame(syncUi);
  }).observe(document.documentElement,{subtree:true,childList:true});
})();

