/* ===== SOURCE: upbonus-v229-universal-footer.js ===== */
/* ==========================================================
   UP BONUS V229 — ONE UNIVERSAL FOOTER OWNER
========================================================== */
(function(){
  'use strict';
  if(window.__ub229FooterLoaded) return;
  window.__ub229FooterLoaded=true;

  function footerHtml(){
    return `<footer class="v45-footer ub229-footer" data-ub229-footer="1">
      <div class="v45-footer-grid">
        <div>
          <div class="v45-footer-logo">Up Bonus</div>
          <p>Platforma benefitowa Bonus Systems Polska S.A.</p>
          <p>tel.: 22 575 07 77<br>fax: 22 575 07 01<br>
          <a href="mailto:kontakt@upbonus.pl">kontakt@upbonus.pl</a></p>
        </div>
        <div>
          <h3>Pomoc i informacje</h3>
          <div class="v45-footer-links">
            <a href="#" onclick="event.preventDefault();selectSection('Pomoc')">Centrum pomocy</a>
            <a href="#" onclick="event.preventDefault();v45OpenInformation?.('privacy')">Polityka prywatności</a>
            <a href="#" onclick="event.preventDefault();v45OpenInformation?.('cookies')">Polityka cookies</a>
            <a href="#" onclick="event.preventDefault();v45OpenInformation?.('regulations')">Regulamin</a>
          </div>
        </div>
        <div>
          <h3>Bonus Systems Polska Spółka Akcyjna</h3>
          <p>ul. Chłodna 51<br>00-867 Warszawa</p>
          <p>KRS 0000136922 • NIP 522-26-55-307</p>
        </div>
      </div>
      <div class="v45-footer-legal">
        Kapitał Akcyjny 23 490 380,00 PLN w pełni opłacony. Sąd Rejonowy dla m. st. Warszawy w Warszawie XIII Wydział Gospodarczy Krajowego Rejestru Sądowego.<br>
        © 2026 Bonus Systems Polska Spółka Akcyjna. Wszelkie prawa zastrzeżone.
      </div>
    </footer>`;
  }

  function targetHost(){
    // Role panels: footer belongs to the scrolling main.
    const main=document.querySelector('.role-app .main-content');
    if(main) return main;

    // Accounts / role chooser.
    const account=document.querySelector('.v34-account-page,.account-page');
    if(account) return account;

    return null;
  }

  function ensure(){
    const host=targetHost();
    if(!host) return;

    // Remove every stale/duplicate footer and historical spacer first.
    document.querySelectorAll('.v45-footer').forEach(f=>{
      if(f.parentElement!==host || !f.matches('[data-ub229-footer="1"]')) f.remove();
    });
    document.querySelectorAll('.v45-footer-spacer,.footer-spacer,[data-footer-spacer]').forEach(el=>el.remove());

    let footer=host.querySelector(':scope > .v45-footer[data-ub229-footer="1"]');
    if(!footer){
      host.insertAdjacentHTML('beforeend',footerHtml());
      footer=host.querySelector(':scope > .v45-footer[data-ub229-footer="1"]');
    }

    // Keep footer as the LAST direct child.
    if(footer && footer!==host.lastElementChild){
      host.appendChild(footer);
    }
  }

  let raf=0;
  function schedule(){
    if(raf) return;
    raf=requestAnimationFrame(()=>{
      raf=0;
      ensure();
    });
  }

  ['render','selectSection','openRole','openModule'].forEach(name=>{
    const fn=window[name];
    if(typeof fn!=='function'||fn.__ub229FooterWrapped) return;
    function wrapped(){
      const out=fn.apply(this,arguments);
      schedule();
      setTimeout(ensure,40);
      return out;
    }
    wrapped.__ub229FooterWrapped=true;
    wrapped.__base=fn;
    window[name]=wrapped;
  });

  window.addEventListener('hashchange',()=>{
    schedule();
    setTimeout(ensure,70);
  });

  window.addEventListener('pageshow',()=>{schedule();setTimeout(ensure,50)});
  window.addEventListener('upbonus:languagechange',()=>{schedule();setTimeout(ensure,30)});

  if(document.readyState==='loading'){
    document.addEventListener('DOMContentLoaded',ensure,{once:true});
  }else{
    ensure();
  }

  window.addEventListener('load',()=>{
    ensure();
    setTimeout(ensure,120);
  },{once:true});

  new MutationObserver(schedule).observe(document.documentElement,{
    subtree:true,
    childList:true
  });

  window.ub229EnsureFooter=ensure;
})();

