// =========================================================
// UP BONUS — SUPABASE PROCESS FINAL GUARD
// Scope: checkout + cancellation handlers only.
// Does NOT change CSS, branding, colors, layout or tenant config.
// =========================================================
(function () {
  'use strict';

  if (window.__ubSupabaseProcessFinalGuard) return;
  window.__ubSupabaseProcessFinalGuard = true;

  function bindStableHandlers() {
    try {
      if (typeof window.__supabaseCheckoutHandler === 'function' &&
          window.v105Confirm !== window.__supabaseCheckoutHandler) {
        window.v105Confirm = window.__supabaseCheckoutHandler;
        try { v105Confirm = window.v105Confirm; } catch (e) {}
        console.log('✅ Final guard: Supabase checkout handler restored');
      }
    } catch (e) {
      console.error('Final guard checkout error', e);
    }

    try {
      if (typeof window.__supabaseCancelHandler === 'function' &&
          window.v104ExecuteCancel !== window.__supabaseCancelHandler) {
        window.v104ExecuteCancel = window.__supabaseCancelHandler;
        try { v104ExecuteCancel = window.v104ExecuteCancel; } catch (e) {}
        console.log('✅ Final guard: Supabase cancellation handler restored');
      }
    } catch (e) {
      console.error('Final guard cancellation error', e);
    }
  }

  // Legacy Supabase handlers above use the pre-MVP RPC/table contract.
  // They must NOT replace the final canonical checkout/cancellation handlers.
  // Backend synchronization is now performed by process-engine.js via /api/v1.
  window.addEventListener('load', function () {
    console.log('✅ Final guard: canonical A→Z process handlers remain authoritative');
  });
})();

