/* ===== FINAL PROCESS BINDING: BOK cancellation actions -> Supabase ===== */
(function () {
  'use strict';

  function requestIdForNativeId(nativeId) {
    const id = String(nativeId || '');

    const requests =
      Array.isArray(window.bokCancellationRequests)
        ? window.bokCancellationRequests
        : [];

    const direct = requests.find(function (r) {
      return String(r?.id || '') === id;
    });

    if (direct?.id) {
      return direct.id;
    }

    try {
      const rows =
        Array.isArray(state?.v111?.cancelRequests)
          ? state.v111.cancelRequests
          : [];

      const nativeRow = rows.find(function (r) {
        return (
          String(r?.id || '') === id ||
          String(r?._supabaseRequestId || '') === id
        );
      });

      if (nativeRow?._supabaseRequestId) {
        return nativeRow._supabaseRequestId;
      }

      if (nativeRow?._supabase && nativeRow?.id) {
        return nativeRow.id;
      }
    } catch (e) {}

    return nativeId;
  }

  async function refreshRequests() {
    if (
      typeof window.loadBokCancellationRequests ===
      'function'
    ) {
      try {
        await window.loadBokCancellationRequests();
      } catch (err) {
        console.warn(
          'BOK final binding refresh warning:',
          err
        );
      }
    }
  }

  async function approve(nativeId) {
    if (
      typeof window.approveBokCancellation !==
      'function'
    ) {
      alert(
        'Integracja BOK z Supabase nie jest jeszcze gotowa. Odśwież stronę i spróbuj ponownie.'
      );
      return false;
    }

    await refreshRequests();

    const requestId =
      requestIdForNativeId(nativeId);

    console.log(
      'BOK FINAL approve -> Supabase:',
      {
        nativeId: nativeId,
        requestId: requestId
      }
    );

    const ok =
      await window.approveBokCancellation(
        requestId
      );

    if (ok) {
      await refreshRequests();

      try {
        if (typeof render === 'function') {
          render();
        }
      } catch (e) {}
    }

    return ok;
  }

  async function reject(nativeId) {
    if (
      typeof window.rejectBokCancellation !==
      'function'
    ) {
      alert(
        'Integracja BOK z Supabase nie jest jeszcze gotowa. Odśwież stronę i spróbuj ponownie.'
      );
      return false;
    }

    await refreshRequests();

    const requestId =
      requestIdForNativeId(nativeId);

    console.log(
      'BOK FINAL reject -> Supabase:',
      {
        nativeId: nativeId,
        requestId: requestId
      }
    );

    const ok =
      await window.rejectBokCancellation(
        requestId
      );

    if (ok) {
      await refreshRequests();

      try {
        if (typeof render === 'function') {
          render();
        }
      } catch (e) {}
    }

    return ok;
  }

  approve.__supabaseBacked = true;
  reject.__supabaseBacked = true;

  window.v111ApproveCancel = approve;
  window.v111RejectCancel = reject;

  try {
    v111ApproveCancel = approve;
    v111RejectCancel = reject;
  } catch (e) {}

  console.log(
    'BOK FINAL process binding installed'
  );
})();


