 surveys:[{id:'s1',name:'Puls organizacji – sierpień',audience:'Cała organizacja',deadline:'2026-09-05',status:'Aktywna',responses:'286 / 420'},{id:'s2',name:'Wellbeing Q3',audience:'IT + Sales',deadline:'2026-09-30',status:'Aktywna',responses:'184'},{id:'s3',name:'eNPS Q2',audience:'Cała organizacja',deadline:'2026-06-30',status:'Zakończona',responses:'opublikowane'}],
 kudos:{monthlyLimit:100,rewardHour:500,rewardVoucher:300,rewardWellbeing:200}
