function hrStore(){try{const v=JSON.parse(localStorage.getItem(HR_STORE_KEY)||'null');if(v&&v.employees)return v}catch(e){}const v=hrSeed();try{localStorage.setItem(HR_STORE_KEY,JSON.stringify(v))}catch(e){}return v}
function saveHrStore(v){try{localStorage.setItem(HR_STORE_KEY,JSON.stringify(v))}catch(e){}}
window.ub204HrTab=function(area,tab){state.ub204Tabs=state.ub204Tabs||{};state.ub204Tabs[area]=tab;rerender();return false};
function hubTabs(area,items){state.ub204Tabs=state.ub204Tabs||{};const active=state.ub204Tabs[area]||items[0][0];return `<div class="ub204-hub-tabs">${items.map(([id,label,count])=>`<button class="${active===id?'active':''}" onclick="ub204HrTab('${area}','${id}')"><b>${E(label)}</b>${count?`<span>${E(count)}</span>`:''}</button>`).join('')}</div>`}
window.ub204SaveEmployee=function(id=''){const st=hrStore(),fd=x=>document.getElementById(x)?.value?.trim()||'';let row=id?st.employees.find(x=>x.id===id):null;if(!row){row={id:'e'+Date.now()};st.employees.unshift(row)}row.name=fd('ub204EmpName');row.email=fd('ub204EmpEmail');row.department=fd('ub204EmpDept');row.group=fd('ub204EmpGroup');row.role=fd('ub204EmpRole')||'Pracownik';row.status=fd('ub204EmpStatus')||'Aktywny';row.budget=Number(document.getElementById('ub204EmpBudget')?.value||0);saveHrStore(st);document.querySelector('.ub204-modal-backdrop')?.remove();toast('Zapisano','Dane pracownika zostały zaktualizowane.');rerender()};
window.ub204EditEmployee=function(id=''){
 const st=hrStore(),x=id?st.employees.find(y=>y.id===id):{name:'',email:'',department:'',group:'',role:'Pracownik',status:'Aktywny',budget:0};
 const departments=[...new Set([...(st.departments||[]).map(d=>d.name),...(st.employees||[]).map(e=>e.department).filter(Boolean)])].filter(Boolean).sort((a,b)=>a.localeCompare(b,'pl'));
 const groups=[...new Set([...(st.employees||[]).map(e=>e.group).filter(Boolean),'Cała firma','Warszawa','Kraków','Gdańsk'])].filter(Boolean).sort((a,b)=>a.localeCompare(b,'pl'));
 simpleModal(id?'Edytuj pracownika':'Dodaj pracownika',`<div class="ub204-form ub204-form-grid">
 <label>Imię i nazwisko<input id="ub204EmpName" value="${E(x?.name||'')}"></label>
 <label>E-mail<input id="ub204EmpEmail" type="email" value="${E(x?.email||'')}"></label>
 <label>Dział<select id="ub204EmpDept"><option value="">Wybierz dział</option>${departments.map(v=>`<option ${x?.department===v?'selected':''}>${E(v)}</option>`).join('')}</select></label>
 <label>Grupa<select id="ub204EmpGroup"><option value="">Wybierz grupę</option>${groups.map(v=>`<option ${x?.group===v?'selected':''}>${E(v)}</option>`).join('')}</select></label>
 <label>Rola<select id="ub204EmpRole">${['Pracownik','HR Admin','HR Specialist','Manager','Finance','Communication'].map(v=>`<option ${x?.role===v?'selected':''}>${v}</option>`).join('')}</select></label>
 <label>Status<select id="ub204EmpStatus">${['Aktywny','Nieaktywny','Zaproszony','Archiwalny'].map(v=>`<option ${x?.status===v?'selected':''}>${v}</option>`).join('')}</select></label>
 <label>Budżet indywidualny<input id="ub204EmpBudget" type="number" min="0" step="0.01" value="${Number(x?.budget||0)}"></label>
 </div>`,'Zapisz',`ub204SaveEmployee('${id}')`)
};
window.ub204DeleteEmployee=function(id){const st=hrStore(),x=st.employees.find(y=>y.id===id);if(!x||!confirm(`Usunąć ${x.name}?`))return;st.employees=st.employees.filter(y=>y.id!==id);saveHrStore(st);rerender()};
window.ub204SaveDepartment=function(id=''){const st=hrStore(),name=document.getElementById('ub204DeptName')?.value?.trim()||'',owner=document.getElementById('ub204DeptOwner')?.value?.trim()||'';if(!name)return;let x=id?st.departments.find(y=>y.id===id):null;if(!x){x={id:'d'+Date.now()};st.departments.push(x)}x.name=name;x.owner=owner;saveHrStore(st);document.querySelector('.ub204-modal-backdrop')?.remove();rerender()};
window.ub204EditDepartment=function(id=''){const st=hrStore(),x=id?st.departments.find(y=>y.id===id):{name:'',owner:''};simpleModal(id?'Edytuj dział':'Dodaj dział',`<div class="ub204-form"><label>Nazwa działu<input id="ub204DeptName" value="${E(x?.name||'')}"></label><label>Owner / manager<input id="ub204DeptOwner" value="${E(x?.owner||'')}"></label></div>`,'Zapisz',`ub204SaveDepartment('${id}')`)};
window.ub204SaveBudget=function(id=''){const st=hrStore(),g=x=>document.getElementById(x)?.value?.trim()||'';let b=id?st.budgets.find(y=>y.id===id):null;if(!b){b={id:'b'+Date.now(),used:0};st.budgets.unshift(b)}b.name=g('ub204BudgetName');b.group=g('ub204BudgetGroup');b.amount=Number(document.getElementById('ub204BudgetAmount')?.value||0);b.from=g('ub204BudgetFrom');b.to=g('ub204BudgetTo');b.status=g('ub204BudgetStatus')||'Aktywny';saveHrStore(st);document.querySelector('.ub204-modal-backdrop')?.remove();rerender()};
window.ub204EditBudget=function(id=''){const st=hrStore(),b=id?st.budgets.find(y=>y.id===id):{name:'',group:'Cała firma',amount:0,from:'2026-01-01',to:'2026-12-31',status:'Aktywny'};simpleModal(id?'Edytuj budżet':'Nowy budżet',`<div class="ub204-form ub204-form-grid"><label>Nazwa<input id="ub204BudgetName" value="${E(b?.name||'')}"></label><label>Grupa / dział<input id="ub204BudgetGroup" value="${E(b?.group||'')}"></label><label>Kwota<input id="ub204BudgetAmount" type="number" value="${Number(b?.amount||0)}"></label><label>Od<input id="ub204BudgetFrom" type="date" value="${E(b?.from||'')}"></label><label>Do<input id="ub204BudgetTo" type="date" value="${E(b?.to||'')}"></label><label>Status<select id="ub204BudgetStatus"><option ${b?.status==='Aktywny'?'selected':''}>Aktywny</option><option ${b?.status==='Planowany'?'selected':''}>Planowany</option><option ${b?.status==='Zamknięty'?'selected':''}>Zamknięty</option></select></label></div>`,'Zapisz',`ub204SaveBudget('${id}')`)};
function ub204RecurrenceLabel(v){return ({once:'Jednorazowe',monthly:'Co miesiąc',quarterly:'Co kwartał',halfyear:'Co pół roku',yearly:'Co rok'})[v]||'Jednorazowe'}
function ub204TopupDate(t){return t?.date||(t?.month?`${t.month}-01`:'')}
function ub204AddMonths(date,months){const [y,m,d]=String(date||'').split('-').map(Number);if(!y||!m||!d)return '';const target=new Date(y,m-1+months,1);const last=new Date(target.getFullYear(),target.getMonth()+1,0).getDate();target.setDate(Math.min(d,last));return `${target.getFullYear()}-${String(target.getMonth()+1).padStart(2,'0')}-${String(target.getDate()).padStart(2,'0')}`}
function ub204TopupOccurrences(t,year=2026){const start=ub204TopupDate(t);if(!start)return [];const freq=t.recurrence||'once',step={monthly:1,quarterly:3,halfyear:6,yearly:12}[freq]||0,until=t.recurrenceUntil||`${year}-12-31`,out=[];if(!step)return start.startsWith(String(year))?[{...t,occurrenceDate:start}]:[];let cur=start,guard=0;while(cur&&cur<=until&&guard++<60){if(cur.startsWith(String(year)))out.push({...t,occurrenceDate:cur});cur=ub204AddMonths(cur,step)}return out}
window.ub204TopupFrequencyChanged=function(){const f=document.getElementById('ub204TopFrequency')?.value||'once',box=document.getElementById('ub204TopUntilWrap');if(box)box.hidden=f==='once'};
window.ub204SaveTopup=function(id=''){const st=hrStore(),g=x=>document.getElementById(x)?.value?.trim()||'';let t=id?st.topups.find(x=>x.id===id):null;if(!t){t={id:'t'+Date.now()};st.topups.push(t)}t.date=g('ub204TopDate');delete t.month;t.name=g('ub204TopName');t.group=g('ub204TopGroup');t.amount=Number(document.getElementById('ub204TopAmount')?.value||0);t.status=g('ub204TopStatus')||'Zaplanowane';t.recurrence=g('ub204TopFrequency')||'once';t.recurrenceUntil=t.recurrence==='once'?'':(g('ub204TopUntil')||`${String(t.date||'2026').slice(0,4)}-12-31`);saveHrStore(st);document.querySelector('.ub204-modal-backdrop')?.remove();rerender()};
window.ub204EditTopup=function(id='',prefillDate=''){const st=hrStore(),today=new Date().toISOString().slice(0,10),t=id?st.topups.find(x=>x.id===id):{date:prefillDate||today,name:'Zasilenie benefitowe',group:'Cała firma',amount:50000,status:'Zaplanowane',recurrence:'once'};const legacyDate=ub204TopupDate(t)||today,frequency=t?.recurrence||'once',until=t?.recurrenceUntil||`${legacyDate.slice(0,4)}-12-31`;simpleModal(id?'Edytuj plan zasilenia':'Zaplanuj zasilenie',`<div class="ub204-form ub204-form-grid"><label>Data pierwszego zasilenia<input id="ub204TopDate" type="date" value="${E(legacyDate)}"></label><label>Częstotliwość<select id="ub204TopFrequency" onchange="ub204TopupFrequencyChanged()"><option value="once" ${frequency==='once'?'selected':''}>Jednorazowe</option><option value="monthly" ${frequency==='monthly'?'selected':''}>Co miesiąc</option><option value="quarterly" ${frequency==='quarterly'?'selected':''}>Co kwartał</option><option value="halfyear" ${frequency==='halfyear'?'selected':''}>Co pół roku</option><option value="yearly" ${frequency==='yearly'?'selected':''}>Co rok</option></select></label><label id="ub204TopUntilWrap" ${frequency==='once'?'hidden':''}>Powtarzaj do<input id="ub204TopUntil" type="date" value="${E(until)}"></label><label>Nazwa<input id="ub204TopName" value="${E(t?.name||'')}"></label><label>Grupa / dział<input id="ub204TopGroup" value="${E(t?.group||'')}"></label><label>Kwota<input id="ub204TopAmount" type="number" value="${Number(t?.amount||0)}"></label><label>Status<select id="ub204TopStatus"><option ${t?.status==='Zaplanowane'?'selected':''}>Zaplanowane</option><option ${t?.status==='Wykonane'?'selected':''}>Wykonane</option><option ${t?.status==='Anulowane'?'selected':''}>Anulowane</option></select></label></div>`,'Zapisz plan',`ub204SaveTopup('${id}')`)};
window.ub204NewTopup=function(date=''){ub204EditTopup('',date)};
window.ub204SaveSurvey=function(id){const st=hrStore(),x=st.surveys.find(y=>y.id===id);if(!x)return;x.name=document.getElementById('ub204SurveyName')?.value?.trim()||x.name;x.status=document.getElementById('ub204SurveyStatus')?.value||x.status;x.deadline=document.getElementById('ub204SurveyDeadline')?.value||x.deadline;x.audience=document.getElementById('ub204SurveyAudience')?.value||x.audience;saveHrStore(st);document.querySelector('.ub204-modal-backdrop')?.remove();rerender()};
window.ub204SurveyAction=function(id){const st=hrStore(),x=st.surveys.find(y=>y.id===id);if(!x)return;simpleModal('Edytuj ankietę',`<div class="ub204-form ub204-form-grid"><label>Nazwa<input id="ub204SurveyName" value="${E(x.name)}"></label><label>Status<select id="ub204SurveyStatus">${['Aktywna','Zaplanowana','Szkic','Zakończona'].map(v=>`<option ${x.status===v?'selected':''}>${v}</option>`).join('')}</select></label><label>Termin<input id="ub204SurveyDeadline" type="date" value="${E(x.deadline)}"></label><label>Odbiorcy<select id="ub204SurveyAudience"><option ${x.audience==='Cała organizacja'?'selected':''}>Cała organizacja</option><option ${x.audience!=='Cała organizacja'?'selected':''}>Wybrana grupa</option></select></label></div>`,'Zapisz',`ub204SaveSurvey('${id}')`)};
window.ub204EditKudos=function(){const k=hrStore().kudos;simpleModal('Ustawienia Kudos',`<div class="ub204-form ub204-form-grid"><label>Limit miesięczny<input id="ub204KLimit" type="number" value="${k.monthlyLimit}"></label><label>1 godzina wolnego<input id="ub204KHour" type="number" value="${k.rewardHour}"></label><label>Voucher<input id="ub204KVoucher" type="number" value="${k.rewardVoucher}"></label><label>Wellbeing<input id="ub204KWell" type="number" value="${k.rewardWellbeing}"></label></div>`,'Zapisz',`(()=>{const s=hrStore();s.kudos={monthlyLimit:+document.getElementById('ub204KLimit').value,rewardHour:+document.getElementById('ub204KHour').value,rewardVoucher:+document.getElementById('ub204KVoucher').value,rewardWellbeing:+document.getElementById('ub204KWell').value};saveHrStore(s);document.querySelector('.ub204-modal-backdrop')?.remove();rerender()})()`)};
window.ub204Quick=function(type){
 const forms={
  employee:['Dodaj pracownika',`<label>Imię i nazwisko<input placeholder="Anna Kowalska"></label><label>E-mail<input type="email" placeholder="anna@firma.pl"></label><label>Grupa<select><option>Warszawa</option><option>IT</option><option>Managerowie</option></select></label>`],
  budget:['Nowy budżet',`<label>Nazwa<input placeholder="Budżet benefitowy 2026"></label><label>Grupa<select><option>Cała firma</option><option>Managerowie</option></select></label><label>Kwota<input type="number" value="500"></label><label>Okres<input type="month"></label>`],
  survey:['Nowa ankieta',`<div class="ub204-steps-mini"><span>1 Nazwa</span><span>2 Typ</span><span>3 Odbiorcy</span><span>4 Pytania</span><span>5 Termin</span><span>6 Powiadomienia</span><span>7 Podgląd</span></div><label>Nazwa<input placeholder="Puls organizacji – wrzesień"></label><label>Typ<select><option>Anonimowa</option><option>Imienna</option></select></label><label>Odbiorcy<select><option>Cała organizacja · 420 osób</option><option>Wybrana grupa</option></select></label>`],
  news:['Nowa publikacja',`<label>Typ<select><option>Aktualność</option><option>Wydarzenie</option><option>Komunikat HR</option><option>Akcja benefitowa</option></select></label><label>Tytuł<input placeholder="Tytuł publikacji"></label><label>Odbiorcy<select><option>Cała organizacja</option><option>Grupa</option></select></label><label>Publikacja<select><option>Teraz</option><option>Zaplanuj</option></select></label>`],
  challenge:['Nowe wyzwanie',`<label>Nazwa<input placeholder="50 000 kroków w 7 dni"></label><label>Grupa<select><option>Cała firma</option><option>Warszawa</option></select></label><label>Warunek<input placeholder="50 000 kroków"></label><label>Nagroda<input placeholder="120 Kudos"></label>`],
  training:['Nowe szkolenie',`<label>Nazwa<input placeholder="Excel Advanced"></label><label>Forma<select><option>Online</option><option>Stacjonarne</option><option>Hybrydowe</option></select></label><label>Termin<input type="date"></label><label>Limit miejsc<input type="number" value="12"></label>`],
  project:['Nowy projekt',`<label>Nazwa<input placeholder="Nowa platforma benefitowa"></label><label>Owner<input value="Małgorzata Bartkiewicz"></label><label>Deadline<input type="date"></label><label>Budżet<input type="number" placeholder="120000"></label>`]
 };
 const x=forms[type]||['Nowy element','<p>Uzupełnij podstawowe dane.</p>'];simpleModal(x[0],`<div class="ub204-form">${x[1]}</div>`,'Utwórz',`toast13?.('Zapisano','Element został utworzony w wersji demonstracyjnej.');this.closest('.ub204-modal-backdrop').remove()`)
};

function startView(){return `<div class="page-content ub204-page">${head('Start','Centrum operacyjne HR — tylko to, co dziś wymaga działania.')}
 <section class="ub204-start-grid"><div class="ub204-panel attention"><div class="ub204-section-head"><div><span>PRIORYTETY</span><h2>Wymaga uwagi</h2></div>${badge('10 spraw','red')}</div>${[
  ['4 wnioski do akceptacji','Urlopy, ZFŚS i praca zdalna','ub204Go(\'Wnioski\')'],['2 korekty czasu pracy','Czekają na decyzję','ub204Go(\'Czas pracy\')'],['Ankieta kończy się jutro','Puls organizacji · 68% odpowiedzi','ub204Go(\'Ankiety\')'],['3 zgłoszenia społeczności','Do moderacji','ub204Go(\'Społeczność\')']].map(x=>actionCard('›',x[0],x[1],x[2])).join('')}</div>
 <div class="ub204-panel"><div class="ub204-section-head"><div><span>DZIŚ</span><h2>Kalendarz operacyjny</h2></div></div>${listRow('Spotkanie rodzinne firmy','17:00 · Warszawa','Aktywne','ub204Go(\'Wydarzenia\')')}${listRow('Publikacja: Black Week','14:00 · zaplanowana','Zaplanowane','ub204Go(\'Aktualności\')')}${listRow('Excel Advanced','10:00 · start szkolenia','Dzisiaj','ub204Go(\'Rozwój i kariera\')')}</div></section>
 <section class="ub204-metrics">${stat('Aktywni pracownicy','12 450','+124 w tym miesiącu')}${stat('Budżety wykorzystane','68%','1,9 mln z 2,8 mln zł')}${stat('Aktywne benefity','27','dla co najmniej jednej grupy')}${stat('Otwarte sprawy','18','4 wymagają decyzji')}</section>
 <section class="ub204-panel"><div class="ub204-section-head"><div><span>AKTYWNOŚĆ</span><h2>Ostatnie zmiany</h2></div><button class="link-btn">Zobacz audyt →</button></div><div class="ub204-feed"><p><b>10:42</b><span>Opublikowano ankietę „Puls organizacji – sierpień”.</span></p><p><b>10:18</b><span>Anna Kowalska zaakceptowała wniosek urlopowy.</span></p><p><b>09:55</b><span>Dodano wydarzenie „Spotkanie rodzinne firmy”.</span></p><p><b>09:12</b><span>Zakończono wyzwanie „Rowerem do pracy”.</span></p></div></section></div>`}

function employeesView(){
 const st=hrStore(); state.ub204Tabs=state.ub204Tabs||{}; const tab=state.ub204Tabs.people||'import'; const pending=ubFinalEmployeePending();
 const tabs=hubTabs('people',[['import','Import i aktualizacja',''],['employees','Pracownicy',String(st.employees.length)],['departments','Działy i grupy',String(st.departments.length)],['roles','Role i uprawnienia','']]);
 if(tab==='import')return `<div class="page-content ub204-page ub204-premium-section">${head('Pracownicy','Dodaj pracowników masowo przez wklejenie z Excela albo import pliku. Pojedyncze dodawanie nadal dostępne.')}${tabs}<section class="ub204-panel ubfinal-import ubfinal-import-v2"><div class="ubfinal-import-head"><div><h2>Import i aktualizacja pracowników</h2><p>Wybierz wygodniejszą metodę. Niezależnie od sposobu dane najpierw trafiają do wspólnego podglądu — nic nie zapisuje się automatycznie.</p></div><button class="secondary-btn" onclick="downloadTemplate?.('employees')">↓ Pobierz formatkę</button></div>
<div class="ubfinal-import-methods">
  <article class="ubfinal-method-card primary"><div class="ubfinal-method-title"><span>1</span><div><b>Wklej dane z Excela</b><small>Najszybsza opcja — zaznacz komórki w Excelu, skopiuj i wklej tutaj.</small></div></div><button class="primary-btn" onclick="ubFinalFocusExcelGrid()">Otwórz arkusz do wklejenia</button></article>
  <article class="ubfinal-method-card"><div class="ubfinal-method-title"><span>2</span><div><b>Wgraj plik</b><small>Alternatywa dla gotowych eksportów CSV lub TXT.</small></div></div><label class="secondary-btn ubfinal-file">Wybierz plik<input type="file" accept=".csv,.txt" onchange="ubFinalEmployeeFile(this)"></label></article>
  <article class="ubfinal-method-card single"><div class="ubfinal-method-title"><span>＋</span><div><b>Dodaj pojedynczo</b><small>Dla jednej osoby lub szybkiej korekty.</small></div></div><button class="secondary-btn" onclick="ub204EditEmployee('')">Dodaj pracownika</button></article>
</div>
<div class="ubfinal-excel-box" id="ubfinal-excel-box"><div class="ubfinal-excel-head"><div><b>Arkusz do wklejenia</b><small>Kliknij pierwszą komórkę i wklej zakres z Excela (Ctrl+V). Komórki możesz też edytować ręcznie.</small></div><div><button class="link-btn" onclick="ubFinalExcelGridClear()">Wyczyść arkusz</button><button class="primary-btn" onclick="ubFinalExcelGridRead()">Dodaj do podglądu ↓</button></div></div><div class="ubfinal-sheet-wrap ubfinal-excel-editor-wrap"><table class="ubfinal-sheet ubfinal-excel-editor" id="ubfinal-excel-grid" onpaste="ubFinalExcelGridPaste(event)"><thead><tr><th>Imię i nazwisko *</th><th>E-mail *</th><th>Dział</th><th>Grupa</th><th>Rola</th><th>Budżet</th><th>Status</th></tr></thead><tbody>${Array.from({length:10},(_,i)=>`<tr data-row="${i}">${['name','email','department','group','role','budget','status'].map((c,j)=>`<td contenteditable="true" data-col="${c}" data-placeholder="${i===0?['Anna Kowalska','anna@firma.pl','HR','Warszawa','Pracownik','600','Aktywny'][j]:''}"></td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="ubfinal-excel-tip"><span>💡</span><p><b>Możesz wkleić nawet kilkaset wierszy.</b> System rozszerzy arkusz automatycznie i przeniesie dane do podglądu poniżej.</p></div></div>
<div class="ubfinal-review-head"><div><b>Podgląd przed zapisem</b><small>Sprawdź dane. Możesz poprawić lub usunąć pojedynczy rekord.</small></div><span>${pending.length} rekordów</span></div><div class="ubfinal-sheet-wrap"><table class="ubfinal-sheet"><thead><tr><th>Imię i nazwisko</th><th>E-mail</th><th>Dział</th><th>Grupa</th><th>Rola</th><th>Budżet</th><th>Status</th><th>Akcje</th></tr></thead><tbody>${pending.length?pending.map(x=>`<tr><td>${E(x.name)}</td><td>${E(x.email)}</td><td>${E(x.department)}</td><td>${E(x.group||'')}</td><td>${E(x.role||'Pracownik')}</td><td>${Number(x.budget||0)} zł</td><td>${badge(x.status||'Nowy','amber')}</td><td><button class="link-btn" onclick="ubFinalEditPending('${E(x.id)}')">Edytuj</button> <button class="link-btn danger" onclick="ubFinalDeletePending('${E(x.id)}')">Usuń</button></td></tr>`).join(''):'<tr><td colspan="8" class="ubfinal-empty-row">Wklej dane do arkusza albo wgraj plik — rekordy pojawią się tutaj przed zapisem.</td></tr>'}</tbody></table></div><div class="ubfinal-confirm ubfinal-confirm-v2"><span><b>${pending.length}</b> rekordów gotowych do zapisu</span><div><button class="secondary-btn" ${pending.length?'':'disabled'} onclick="ubFinalClearPending()">Wyczyść podgląd</button><button class="primary-btn" ${pending.length?'':'disabled'} onclick="ubFinalCommitEmployees()">Zapisz pracowników</button></div></div></section></div>`;
 if(tab==='departments')return `<div class="page-content ub204-page ub204-premium-section">${head('Pracownicy','Działy i grupy')}${tabs}<section class="ub204-panel">${st.departments.map(d=>listRow(d.name,`Owner: ${d.owner||'—'} · ${st.employees.filter(e=>e.department===d.name).length} osób`,'Aktywny')).join('')}</section></div>`;
 if(tab==='roles')return `<div class="page-content ub204-page ub204-premium-section">${head('Pracownicy','Role i uprawnienia')}${tabs}<section class="ub204-panel">${[['HR Admin','Pełna administracja'],['Manager','Akceptacje i raporty'],['Pracownik','Portal pracownika']].map(x=>listRow(x[0],x[1],'Aktywna')).join('')}</section></div>`;
 return `<div class="page-content ub204-page ub204-premium-section">${head('Pracownicy','Kartoteka w układzie tabelarycznym.',`<button class="primary-btn" onclick="ub204EditEmployee('')">＋ Dodaj pracownika</button>`)}${tabs}<div class="ubfinal-toolbar"><input placeholder="Szukaj…" oninput="ubFinalFilterRows(this,'ubfinal-employees')"><button class="secondary-btn" onclick="ubFinalExportEmployees()">↓ Excel / CSV</button></div><section class="ub204-panel ubfinal-sheet-panel"><div class="ubfinal-sheet-wrap"><table class="ubfinal-sheet" id="ubfinal-employees"><thead><tr><th onclick="ubFinalSortTable(this,0)">Pracownik ↕</th><th>E-mail</th><th>Dział</th><th>Grupa</th><th>Rola</th><th>Budżet</th><th>Status</th><th>Akcje</th></tr></thead><tbody>${st.employees.map(x=>`<tr><td><b>${E(x.name)}</b></td><td>${E(x.email)}</td><td>${E(x.department)}</td><td>${E(x.group)}</td><td>${E(x.role)}</td><td>${Number(x.budget||0).toLocaleString('pl-PL')} zł</td><td>${badge(x.status,x.status==='Aktywny'?'green':'neutral')}</td><td><select class="ubfinal-action-select" onchange="ubFinalEmployeeAction('${E(x.id)}',this.value);this.value=''"><option value="">Wybierz…</option><option value="edit">Edytuj</option><option value="archive">Archiwizuj</option><option value="delete">Usuń</option></select></td></tr>`).join('')}</tbody></table></div></section></div>`
}
