function budgetsView(){
 const st=hrStore();state.ub204Tabs=state.ub204Tabs||{};const tab=state.ub204Tabs.budgets||'overview';
 const tabs=hubTabs('budgets',[['overview','Budżety',''],['planner','Planner roczny',''],['topups','Zasilenia',String(st.topups.length)],['funding','Źródła finansowania',''],['limits','Limity','']]);
 const totals=st.budgets.reduce((a,b)=>{a.amount+=Number(b.amount||0);a.used+=Number(b.used||0);return a},{amount:0,used:0});
 const overview=`<section class="ub204-metrics">${stat('Przyznane',`${Math.round(totals.amount/1000).toLocaleString('pl-PL')} tys. zł`)}${stat('Wykorzystane',`${Math.round(totals.used/1000).toLocaleString('pl-PL')} tys. zł`,totals.amount?`${Math.round(totals.used/totals.amount*100)}%`:'0%')}${stat('Pozostało',`${Math.round((totals.amount-totals.used)/1000).toLocaleString('pl-PL')} tys. zł`)}${stat('Planowane zasilenia',String(st.topups.length))}</section><div class="ub204-hub-head"><div><h2>Budżety firmy</h2><p>Podgląd, edycja i kontrola okresów obowiązywania.</p></div><button class="primary-btn" onclick="ub204EditBudget('')">＋ Nowy budżet</button></div><section class="ub204-panel"><div class="ub204-table-list">${st.budgets.map(b=>`<div class="ub204-employee-row"><div><b>${E(b.name)}</b><small>${E(b.group)} · ${E(b.from)}–${E(b.to)}</small></div>${badge(b.status,b.status==='Aktywny'?'green':'neutral')}<span>${Number(b.amount).toLocaleString('pl-PL')} zł</span><span>wykorzystano ${Number(b.used||0).toLocaleString('pl-PL')} zł</span><div class="ub204-row-actions"><button class="link-btn" onclick="ub204EditBudget('${E(b.id)}')">Edytuj</button></div></div>`).join('')}</div></section>`;
 const months=['Sty','Lut','Mar','Kwi','Maj','Cze','Lip','Sie','Wrz','Paź','Lis','Gru'];
 const fmtDate=d=>{if(!d)return '—';const [y,m,day]=String(d).split('-');return day&&m&&y?`${day}.${m}.${y}`:d};
 const occurrences=st.topups.flatMap(t=>ub204TopupOccurrences(t,2026)).sort((a,b)=>a.occurrenceDate.localeCompare(b.occurrenceDate));
 const planner=`<div class="ub204-hub-head"><div><h2>Planner roczny 2026</h2><p>Ustaw jednorazowe albo cykliczne zasilenia na konkretny dzień: co miesiąc, co kwartał, co pół roku lub co rok.</p></div><button class="primary-btn" onclick="ub204NewTopup()">＋ Ustaw plan</button></div><div class="ub204-year-grid ub204-year-grid-daily">${months.map((m,i)=>{const mm=String(i+1).padStart(2,'0'),prefix=`2026-${mm}`,rows=occurrences.filter(t=>t.occurrenceDate.startsWith(prefix)),sum=rows.reduce((a,x)=>a+Number(x.amount||0),0);return `<article class="${rows.length?'has-data':''}"><div class="ub204-month-head"><span>${m}</span><button aria-label="Dodaj plan w ${m}" onclick="ub204NewTopup('${prefix}-01')">＋</button></div><b>${sum?sum.toLocaleString('pl-PL')+' zł':'—'}</b><small>${rows.length?rows.length+' termin'+(rows.length===1?'':'y'):'brak planu'}</small><div class="ub204-day-list">${rows.length?rows.slice(0,4).map(t=>`<button onclick="ub204EditTopup('${E(t.id)}')"><strong>${fmtDate(t.occurrenceDate).slice(0,5)}</strong><span>${E(t.name)}</span><em>${Number(t.amount||0).toLocaleString('pl-PL')} zł</em><i>${E(ub204RecurrenceLabel(t.recurrence||'once'))}</i></button>`).join(''):`<button class="empty" onclick="ub204NewTopup('${prefix}-01')">Ustaw termin</button>`}${rows.length>4?`<i>+ ${rows.length-4} kolejne</i>`:''}</div></article>`}).join('')}</div>`;
 const topups=`<div class="ub204-hub-head"><div><h2>Plany zasileń</h2><p>Jednorazowe i cykliczne harmonogramy z możliwością edycji całej serii.</p></div><button class="primary-btn" onclick="ub204NewTopup()">＋ Dodaj plan</button></div><section class="ub204-panel"><div class="ub204-table-list">${st.topups.slice().sort((a,b)=>ub204TopupDate(a).localeCompare(ub204TopupDate(b))).map(t=>`<div class="ub204-employee-row"><div><b>${E(t.name)}</b><small>${E(fmtDate(ub204TopupDate(t)))} · ${E(t.group)} · ${E(ub204RecurrenceLabel(t.recurrence||'once'))}${t.recurrence&&t.recurrence!=='once'&&t.recurrenceUntil?` · do ${E(fmtDate(t.recurrenceUntil))}`:''}</small></div>${badge(t.status,'amber')}<span>${Number(t.amount).toLocaleString('pl-PL')} zł</span><div class="ub204-row-actions"><button class="link-btn" onclick="ub204EditTopup('${E(t.id)}')">Edytuj plan</button></div></div>`).join('')}</div></section>`;
 const funding=`<section class="ub204-panel">${listRow('ZFŚS','Świadczenia socjalne · regulamin i grupy','Aktywna')}${listRow('Środki pracodawcy','Budżet benefitowy i premie','Aktywna')}${listRow('Dopłata pracownika','Dopłaty do benefitów i abonamentów','Aktywna')}</section>`;
 const limits=`<section class="ub204-panel">${listRow('Limit miesięczny benefitów','600 zł / pracownik','Aktywna')}${listRow('Limit Kudos','100 / miesiąc','Aktywna')}${listRow('Limit zakupów jednego produktu','1 / miesiąc','Aktywna')}</section>`;
 return `<div class="page-content ub204-page ub204-premium-section">${head('Budżety i zasilenia','Planuj, zasilaj, kontroluj i modyfikuj środki firmy.')}${tabs}${tab==='planner'?planner:tab==='topups'?topups:tab==='funding'?funding:tab==='limits'?limits:overview}</div>`
}
