function benefitsView(title){const rows=ubFinalBenefits();return `<div class="page-content ub204-page">${head(title,'Dodawanie, edycja, dostępność i status benefitów.',`<button class="primary-btn" onclick="ubFinalBenefitEdit()">＋ Dodaj benefit</button>`)}<div class="ubfinal-toolbar"><input placeholder="Szukaj…" oninput="ubFinalFilterRows(this,'ubfinal-benefits')"><button class="secondary-btn" onclick="ubFinalExportBenefits()">↓ Excel / CSV</button></div><section class="ub204-panel ubfinal-sheet-panel"><div class="ubfinal-sheet-wrap"><table class="ubfinal-sheet" id="ubfinal-benefits"><thead><tr><th>Benefit</th><th>Kategoria</th><th>Typ</th><th>Cena</th><th>Widoczność</th><th>Status</th><th>Akcje</th></tr></thead><tbody>${rows.map(x=>`<tr><td><b>${E(x.name)}</b></td><td>${E(x.category)}</td><td>${E(x.type)}</td><td>${Number(x.price||0)} zł</td><td>${E(x.visibility)}</td><td>${badge(x.status,/Aktyw/i.test(x.status)?'green':'neutral')}</td><td><button class="link-btn" onclick="ubFinalBenefitEdit('${E(x.id)}')">Edytuj</button> <button class="link-btn" onclick="ubFinalBenefitToggle('${E(x.id)}')">${/Aktyw/i.test(x.status)?'Wstrzymaj':'Aktywuj'}</button> <button class="link-btn danger" onclick="ubFinalBenefitDelete('${E(x.id)}')">Usuń</button></td></tr>`).join('')}</tbody></table></div></section></div>`}
