function cfg(id=tid()){const a=read();return {...baseTenant(id),...(a[id]||{}),branding:{...baseTenant(id).branding,...(a[id]?.branding||{})},modules:{...baseTenant(id).modules,...(a[id]?.modules||{})},sections:{...baseTenant(id).sections,...(a[id]?.sections||{})},names:{...(a[id]?.names||{})},goLive:{...baseTenant(id).goLive,...(a[id]?.goLive||{})}}}
