 return `<aside class="sidebar ub207-super-sidebar ${state.mobileMenu?'open':''}" aria-label="Super Admin"><nav class="sidebar-menu ub207-super-menu ub209-menu-up">${nav}</nav><div class="sidebar-foot ub207-client-foot ub209-logout-foot"><button type="button" class="ub207-super-nav ub207-foot-nav muted ub209-logout" onclick="logout()"><span class="ub207-nav-icon">↩</span><b>Wyloguj</b></button></div></aside><div class="sidebar-overlay ${state.mobileMenu?'open':''}" onclick="closeMobile()"></div>`;
