const prevRender207=window.renderSection;
window.renderSection=function(){
 if(state?.role==='hr'&&state.section==='Integracje')return wrapClient(hrIntegrations(),'Integracje');
 if(state?.role==='superadmin'&&state.section==='Workflow')return superWorkflow();
 if(state?.role==='superadmin'&&state.section==='Monitoring i support')return superMonitoring();
 const out=prevRender207.apply(this,arguments);
 if(state?.role==='hr')return wrapClient(out,state.section);
 return out;
};

document.documentElement.dataset.upbonusV207='admin-responsibility-split';

