/* FINAL-STABLE — employee import v2: paste-from-Excel + file */
(function(){
  'use strict';
  const KEY='upbonus.final.emp.pending';
  const get=()=>{try{return JSON.parse(localStorage.getItem(KEY)||'[]')||[]}catch(e){return []}};
  const put=v=>{try{localStorage.setItem(KEY,JSON.stringify(v))}catch(e){}};
  const rerender=()=>{try{typeof render==='function'&&render()}catch(e){}};
  const cols=['name','email','department','group','role','budget','status'];
  function grid(){return document.getElementById('ubfinal-excel-grid')}
  function addRows(count){
    const body=grid()?.tBodies?.[0]; if(!body)return;
    const start=body.rows.length;
    for(let i=0;i<count;i++){
      const tr=document.createElement('tr');tr.dataset.row=String(start+i);
      cols.forEach(c=>{const td=document.createElement('td');td.contentEditable='true';td.dataset.col=c;td.dataset.placeholder='';tr.appendChild(td)});
      body.appendChild(tr);
    }
  }
  function value(td){return String(td?.innerText||td?.textContent||'').trim()}
  window.ubFinalFocusExcelGrid=function(){
    document.getElementById('ubfinal-excel-box')?.scrollIntoView({behavior:'smooth',block:'center'});
    setTimeout(()=>grid()?.querySelector('tbody td')?.focus(),250);
  };
  window.ubFinalExcelGridClear=function(){
    grid()?.querySelectorAll('tbody td').forEach(td=>td.textContent='');
    grid()?.querySelector('tbody td')?.focus();
  };
  window.ubFinalExcelGridPaste=function(event){
    const text=event.clipboardData?.getData('text/plain'); if(!text)return;
    event.preventDefault();
    const rows=String(text).replace(/\r/g,'').split('\n').filter((x,i,a)=>x!==''||i<a.length-1).filter(x=>x.trim().length);
    if(!rows.length)return;
    const parsed=rows.map(r=>r.includes('\t')?r.split('\t'):r.includes(';')?r.split(';'):r.split(','));
    const target=event.target.closest('td');
    const body=grid()?.tBodies?.[0]; if(!target||!body)return;
    let startRow=target.parentElement.rowIndex-1;
    let startCol=target.cellIndex;
    const need=startRow+parsed.length-body.rows.length; if(need>0)addRows(need+3);
    parsed.forEach((arr,ri)=>arr.slice(0,cols.length-startCol).forEach((v,ci)=>{
      const td=body.rows[startRow+ri]?.cells[startCol+ci]; if(td)td.textContent=String(v||'').trim();
    }));
    const next=Math.min(body.rows.length-1,startRow+parsed.length);
    body.rows[next]?.cells?.[0]?.focus();
  };
  window.ubFinalExcelGridRead=function(){
    const body=grid()?.tBodies?.[0]; if(!body)return;
    const rows=[...body.rows].map((tr,i)=>{
      const c=[...tr.cells].map(value);
      return {id:'PX'+Date.now()+i,name:c[0],email:c[1],department:c[2],group:c[3],role:c[4]||'Pracownik',budget:Number(String(c[5]||0).replace(',','.'))||0,status:c[6]||'Nowy'};
    }).filter(r=>r.name||r.email||r.department||r.group);
    if(!rows.length){alert('Wklej lub wpisz dane do arkusza.');return}
    const invalid=rows.filter(r=>!r.name||!r.email);
    if(invalid.length){alert(`Uzupełnij wymagane pola: Imię i nazwisko oraz E-mail. Brakuje danych w ${invalid.length} wierszu/wierszach.`);return}
    const current=get();
    const map=new Map(current.map(r=>[String(r.email||'').toLowerCase(),r]));
    rows.forEach(r=>map.set(String(r.email).toLowerCase(),{...(map.get(String(r.email).toLowerCase())||{}),...r}));
    put([...map.values()]);
    rerender();
  };
  window.ubFinalClearPending=function(){if(confirm('Wyczyścić cały podgląd importu?')){put([]);rerender()}};
  const oldEdit=window.ubFinalEditPending;
  window.ubFinalEditPending=function(id){
    const rows=get(),x=rows.find(r=>r.id===id); if(!x)return;
    const name=prompt('Imię i nazwisko',x.name||''); if(name===null)return;
    const email=prompt('E-mail',x.email||''); if(email===null)return;
    const department=prompt('Dział',x.department||'')??x.department;
    const group=prompt('Grupa / lokalizacja',x.group||'')??x.group;
    const role=prompt('Rola',x.role||'Pracownik')??x.role;
    const budget=prompt('Budżet',String(x.budget||0)); if(budget===null)return;
    Object.assign(x,{name,email,department,group,role,budget:Number(String(budget).replace(',','.'))||0});
    put(rows);rerender();
  };
  document.documentElement.dataset.employeeImport='paste-file-v2';
})();


/* ===== FINAL SUPER ADMIN OPERATIONS — compact, stable, table-first ===== */
(()=>{
'use strict';
if(window.__ubFinalSuperOps)return;window.__ubFinalSuperOps=true;
const S=()=>window.state||state;
const E=v=>String(v??'').replace(/[&<>"']/g,s=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[s]));
const G=(k,d)=>{try{return JSON.parse(localStorage.getItem(k)||'null')??d}catch(_){return d}};
const P=(k,v)=>{try{localStorage.setItem(k,JSON.stringify(v))}catch(_){}};
const R=()=>{try{render()}catch(_){try{doRender()}catch(__){}}};
const KCLIENT='upbonus.v219.clients',KMOD='upbonus.final.module.catalog.v260',KSTOCK='upbonus.final.stock.imports';
const seedClients=[
 {id:'TEN-003',name:'Open Benefit 3.0',package:'Indywidualny',users:4820,modules:19,status:'Aktywny',statusDate:'2026-06-01',owner:'Anna'},
 {id:'TEN-002',name:'Erste Benefits',package:'Indywidualny',users:1482,modules:19,status:'Aktywny',statusDate:'2026-05-15',owner:'Michał'},
 {id:'TEN-006',name:'Mercedes Benefits',package:'Indywidualny',users:762,modules:16,status:'Onboarding',statusDate:'2026-08-01',owner:'Kasia'},
 {id:'TEN-001',name:'Up Bonus',package:'Business',users:612,modules:19,status:'Aktywny',statusDate:'2026-04-20',owner:'Ola'}
];
function clients(){let a=G(KCLIENT,[]);if(!Array.isArray(a)||!a.length){a=seedClients;P(KCLIENT,a)}return a}
function status(s){const c=/Aktyw/i.test(s)?'green':/Onboard|Wdroż/i.test(s)?'amber':'gray';return `<span class="status ${c}">${E(s)}</span>`}
function money(n){return Number(n||0).toLocaleString('pl-PL',{minimumFractionDigits:2,maximumFractionDigits:2})+' zł'}
function table(headers,rows,cls=''){return `<div class="ubfinal-op-table ${cls}"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${headers.length}" class="empty-state">Brak danych.</td></tr>`}</tbody></table></div>`}

/* CLIENTS: registry only. Configure only after opening client card. */
function clientsView(){
 const all=clients(),q=String(S().ubFinalClientQ||'').toLowerCase(),rows=all.filter(c=>!q||`${c.name} ${c.id} ${c.owner} ${c.package}`.toLowerCase().includes(q));
 return `<div class="page-content ubfinal-op-page"><div class="page-head"><div><h1>Klienci</h1><p>Rejestr tenantów. Konfiguracja jest dostępna dopiero po wejściu w kartę klienta.</p></div><button class="primary-btn" onclick="ub219ClientEdit?.()">＋ Dodaj klienta</button></div><div class="ubfinal-op-toolbar"><input placeholder="Szukaj klienta…" value="${E(S().ubFinalClientQ||'')}" oninput="state.ubFinalClientQ=this.value;render()"><span>${rows.length} klientów</span></div>${table(['Klient','ID tenant','Pakiet','Użytkownicy','Aktywne moduły','Status','Opiekun','Uruchomienie','Akcja'],rows.map(c=>[
  `<b>${E(c.name)}</b>`,E(c.id),E(c.package),Number(c.users||0).toLocaleString('pl-PL'),String(c.modules||0),status(c.status),E(c.owner||'—'),E(c.statusDate||'—'),`<button class="secondary-btn small" onclick="ubFinalOpenClient('${E(c.id)}')">Otwórz</button>`
 ]))}</div>`;
}
window.ubFinalOpenClient=id=>{S().ubFinalClientId=id;S().ubFinalClientTab='Overview';S().section='Final Klient';R()};
window.ubFinalClientTab=t=>{S().ubFinalClientTab=t;R()};
function clientCard(){
 const c=clients().find(x=>x.id===S().ubFinalClientId)||clients()[0],tab=S().ubFinalClientTab||'Overview';
 const tabs=['Overview','Konfiguracja','Użytkownicy','Finansowanie','Branding','Integracje','Raporty','Historia'];
 let body='';
 if(tab==='Overview') body=`${table(['Pole','Wartość'],[['Status',status(c.status)],['Pakiet',E(c.package)],['Użytkownicy',Number(c.users||0).toLocaleString('pl-PL')],['Aktywne moduły',String(c.modules||0)],['Opiekun',E(c.owner||'—')],['Uruchomienie',E(c.statusDate||'—')]])}`;
 else if(tab==='Konfiguracja') body=`<div class="ubfinal-actions-grid"><button onclick="state.section='Super Konfiguracja';state.ub219ConfigClient='${E(c.id)}';render()"><b>Moduły i pakiet</b><span>ON/OFF, ceny i pakiet indywidualny</span></button><button onclick="state.section='Super Branding';render()"><b>Branding</b><span>Logo, kolory i domena</span></button><button onclick="state.section='Super Integracje';render()"><b>Integracje</b><span>SSO, HRIS, ERP, API</span></button><button onclick="state.section='Super Użytkownicy';render()"><b>Role i dostęp</b><span>Administratorzy i uprawnienia</span></button></div>`;
 else if(tab==='Użytkownicy') body=table(['Użytkownik','Rola','Status','Akcja'],[['Administrator HR','HR Admin',status('Aktywny'),'<button class="secondary-btn small">Edytuj</button>'],['Finance Admin','Finance',status('Aktywny'),'<button class="secondary-btn small">Edytuj</button>']]);
 else if(tab==='Finansowanie') body=table(['Źródło','Status','Limit','Akcja'],[['Benefit Wallet',status('Aktywny'),'wg budżetu','<button class="secondary-btn small">Konfiguruj</button>'],['ZFŚS',status('Aktywny'),'wg regulaminu','<button class="secondary-btn small">Konfiguruj</button>'],['Środki własne',status('Aktywny'),'bez limitu','<button class="secondary-btn small">Konfiguruj</button>']]);
 else if(tab==='Branding') body=`<div class="ubfinal-actions-grid"><button onclick="state.section='Super Branding';render()"><b>Otwórz branding klienta</b><span>Logo, kolory, font, hero</span></button></div>`;
 else if(tab==='Integracje') body=table(['Integracja','Status','Ostatnia synchronizacja','Akcja'],[['SSO / Entra ID',status('Aktywny'),'23.08.2026 08:29','<button class="secondary-btn small">Otwórz</button>'],['HRIS',status('Aktywny'),'23.08.2026 07:56','<button class="secondary-btn small">Otwórz</button>']]);
 else if(tab==='Raporty') body=`<div class="ubfinal-actions-grid"><button onclick="state.section='Super Raporty';render()"><b>Raporty klienta</b><span>Sprzedaż, budżety, aktywność</span></button></div>`;
 else body=table(['Data','Zmiana','Użytkownik'],[['03.09.2026','Aktualizacja konfiguracji','Super Admin'],['02.09.2026','Import użytkowników','HR Admin']]);
 return `<div class="page-content ubfinal-op-page"><div class="page-head"><div><button class="link-btn" onclick="state.section='Super Klienci';render()">← Klienci</button><h1>${E(c.name)}</h1><p>${E(c.id)} · ${Number(c.users||0).toLocaleString('pl-PL')} użytkowników</p></div>${status(c.status)}</div><div class="ubfinal-op-tabs">${tabs.map(t=>`<button class="${tab===t?'active':''}" onclick="ubFinalClientTab('${t}')">${t}</button>`).join('')}</div><section class="ubfinal-op-card">${body}</section></div>`;
}

/* STOCK: commit really writes stock and immediately appears in inventory. */
window.ubFinalCommitStock=function(){
 const provider=document.getElementById('ubFinalStockProvider')?.value,stock=document.getElementById('ubFinalTargetStock')?.value,rows=window.__ubFinalStockRows||[];
 if(!provider||!stock||!rows.length){alert('Wybierz provider, docelowy stock i plik.');return}
 let arr=G(KSTOCK,[]);const refs=new Set(arr.flatMap(x=>x.references||[])),newRefs=rows.map(x=>x.code).filter(Boolean),dups=newRefs.filter(x=>refs.has(x));
 if(dups.length){alert('Import zatrzymany: znaleziono '+dups.length+' duplikatów.');return}
 const batch={id:'BAT-'+Date.now(),provider,stock,sku:stock.toUpperCase().replace(/[^A-Z0-9]+/g,'-'),file:document.getElementById('ubFinalStockFile')?.files?.[0]?.name||'manual',rows:rows.length,references:newRefs,status:'Dostępny',created:new Date().toISOString(),validTo:''};
 arr.unshift(batch);P(KSTOCK,arr);document.querySelector('.ubfinal-stock-modal')?.closest('.modal-backdrop')?.remove();R();setTimeout(()=>alert(`Zaimportowano ${rows.length} kodów do stocku: ${stock}.`),30)
};
function inventoryView(){
 const batches=G(KSTOCK,[]);const total=batches.reduce((s,x)=>s+Number(x.rows||0),0);
 return `<div class="page-content ubfinal-op-page"><div class="page-head"><div><h1>Magazyn i vouchery</h1><p>Stocki, partie i import kodów. Provider i stock zawsze wskazuje operator.</p></div><div class="actions"><button class="secondary-btn" onclick="ub64OpenOwnVoucher?.()">Wystaw voucher</button><button class="primary-btn" onclick="ub64OpenImport?.()">↑ Import stocku</button></div></div><div class="ubfinal-op-metrics"><span><b>${total}</b><small>Dostępne kody</small></span><span><b>${batches.length}</b><small>Partie importu</small></span><span><b>0</b><small>Zarezerwowane</small></span><span><b>0</b><small>Zablokowane</small></span></div>${table(['Provider','Stock','SKU','Ilość','Plik','Data importu','Status','Akcja'],batches.map(x=>[E(x.provider),E(x.stock),E(x.sku),Number(x.rows||0).toLocaleString('pl-PL'),E(x.file),new Date(x.created).toLocaleString('pl-PL'),status(x.status),`<button class="secondary-btn small" onclick="alert('Partia ${E(x.id)}')">Otwórz</button>`]))}</div>`;
}

/* GLOBAL MODULE CATALOG + CUSTOM PACKAGE BUILDER */
const moduleSeed=[
 ['catalog','Katalog benefitów','CORE',0],['wallet','Benefit Wallet','CORE',0],['vouchers','Zakupy i vouchery','CORE',0],['communication','Komunikacja podstawowa','CORE',0],['reports','Raport podstawowy','CORE',0],
 ['surveys','Ankiety','HR',1.20],['kudos','Kudos i docenianie','HR',0.90],['challenges','Wyzwania i nagrody','ENGAGEMENT',0.75],['wellbeing','Wellbeing','ENGAGEMENT',1.40],['community','Społeczność','ENGAGEMENT',0.70],['learning','Rozwój i kariera','HR',0.85],
 ['projects','Projekty','OPERATIONS',0.95],['time','Czas pracy','HR',0.80],['subscriptions','Benefity abonamentowe','BENEFITS',0.65],['gifts','Prezenty i personalizacja','BENEFITS',0.60],['m365','Microsoft 365 / Teams','INTEGRATIONS',0.55],['sso','SSO / Entra ID','INTEGRATIONS',0.80],['api','API / HRIS','INTEGRATIONS',1.10],['analytics','Advanced Analytics','REPORTING',1.35]
];
function modules(){let a=G(KMOD,[]);if(!Array.isArray(a)||!a.length){a=moduleSeed.map(x=>({id:x[0],name:x[1],group:x[2],price:x[3],available:true,custom:false}));P(KMOD,a)}return a}
function saveModules(a){P(KMOD,a)}
window.ubFinalModuleToggle=(id,on)=>{const a=modules(),x=a.find(m=>m.id===id);if(x){x.available=!!on;saveModules(a);R()}};
window.ubFinalModulePrice=(id,v)=>{const a=modules(),x=a.find(m=>m.id===id);if(x){x.price=Number(v||0);saveModules(a)}};
window.ubFinalModuleCustom=(id,on)=>{const a=modules(),x=a.find(m=>m.id===id);if(x){x.custom=!!on;saveModules(a);R()}};
window.ubFinalAddModule=()=>{const name=prompt('Nazwa nowego elementu / modułu');if(!name)return;const a=modules();a.push({id:'custom-'+Date.now(),name,group:prompt('Obszar','CUSTOM')||'CUSTOM',price:Number(prompt('Cena / użytk. / mies.','1.00')||0),available:true,custom:true});saveModules(a);R()};
function modulesView(){
 const a=modules(),sel=a.filter(x=>x.custom&&x.available),sum=sel.reduce((s,x)=>s+Number(x.price||0),0);
 return `<div class="page-content ubfinal-op-page"><div class="page-head"><div><h1>Moduły i pakiety</h1><p>Każdy element ma własną cenę i dostępność. Pakiet indywidualny składa się z zaznaczonych elementów.</p></div><button class="primary-btn" onclick="ubFinalAddModule()">＋ Dodaj element</button></div><div class="ubfinal-package-summary"><div><span>Pakiet indywidualny</span><b>${sel.length} elementów</b></div><div><span>Cena / użytk. / mies.</span><b>${money(sum)}</b></div><button class="primary-btn" onclick="alert('Pakiet zapisany: ${sel.length} elementów, ${sum.toFixed(2)} zł / użytk. / mies.')">Zapisz pakiet indywidualny</button></div>${table(['Element','Obszar','Dostępny systemowo','Cena / użytk. / mies.','W pakiecie indywidualnym'],a.map(m=>[
  `<b>${E(m.name)}</b>`,E(m.group),`<label class="ubfinal-switch"><input type="checkbox" ${m.available?'checked':''} onchange="ubFinalModuleToggle('${m.id}',this.checked)"><span></span></label>`,`<input class="ubfinal-price" type="number" step="0.05" min="0" value="${Number(m.price||0)}" onchange="ubFinalModulePrice('${m.id}',this.value)"> zł`,`<label class="ubfinal-switch"><input type="checkbox" ${m.custom?'checked':''} ${m.available?'':'disabled'} onchange="ubFinalModuleCustom('${m.id}',this.checked)"><span></span></label>`
 ]))}</div>`;
}

/* OFFER TABLE: no horizontal scrollbar */
function compactOfferPolish(){
 document.querySelectorAll('.ub99-scroll').forEach(x=>x.classList.add('ubfinal-no-hscroll'));
}
const observer=new MutationObserver(()=>{compactOfferPolish();document.querySelectorAll('.ub64-backend-note').forEach(x=>x.remove())});
try{observer.observe(document.documentElement,{childList:true,subtree:true})}catch(_){}

const base=window.renderSection||renderSection;
window.renderSection=function(){
 const s=S(),sec=String(s?.section||'');
 if(s?.role==='superadmin'){
  if(['Super Klienci','Klienci SaaS','Klienci'].includes(sec))return clientsView();
  if(sec==='Final Klient')return clientCard();
  if(['Super Inventory','Magazyn i vouchery'].includes(sec))return inventoryView();
  if(['Super Konfiguracja','Moduły i pakiety'].includes(sec))return modulesView();
 }
 return base.apply(this,arguments);
};
try{renderSection=window.renderSection}catch(_){}
document.documentElement.dataset.upbonusBuild='FINAL-SUPER-OPS-20260903';window.__UPBONUS_BUILD__='FINAL-SUPER-OPS-20260903';
})();
